SELECT row_number() OVER () AS n, movie_id FROM ins;
CREATE UNIQUE INDEX ON bulk_movies (n);

-- Every bulk screen, every day for two weeks, at 10:00, 13:30, 17:00 and 20:30, each showing a random film.
-- About one in seven is 3D, IMAX or 4D.
INSERT INTO events (movie_id, room_id, format_id, starts_at)
SELECT bm.movie_id, x.room_id, f.format_id, x.starts_at
FROM (
    SELECT r.room_id, 1 + floor(random() * 2000)::int AS mn,
        CASE WHEN random() < 0.86 THEN 'Standard' ELSE (ARRAY['3D', 'IMAX', '4D'])[1 + floor(random() * 3)::int] END AS format,
        ((now() AT TIME ZONE 'Australia/Sydney')::date + d + t) AT TIME ZONE 'Australia/Sydney' AS starts_at
    FROM rooms r
    JOIN cinemas c USING (cinema_id),
    generate_series(0, 13) AS d,
    unnest(ARRAY['10:00', '13:30', '17:00', '20:30']::time[]) AS t
    WHERE c.name NOT IN ('Melbourne Central', 'Mildura')
) AS x
JOIN bulk_movies bm ON bm.n = x.mn
JOIN event_formats f ON f.name = x.format;

-- Bookings of seat pairs (1-2, 3-4, ...) by random bulk users. Each showing gets its own fill rate, 0-40%, so some are
-- nearly empty and some busy. booking_id is made up front so the seats can find their booking.
WITH pair AS MATERIALIZED (
    SELECT uuidv7() AS booking_id, p.event_id, p.room_id, p.row_label, p.pair, bu.user_id, p.starts_at
    FROM (
        SELECT e.event_id, e.room_id, e.starts_at, rl AS row_label, pr AS pair, 1 + floor(random() * 5000)::int AS un,
            e.fill
        FROM (
            SELECT ev.*, random() * 0.4 AS fill
            FROM events ev
            JOIN rooms r USING (room_id)
            JOIN cinemas c USING (cinema_id)
            WHERE c.name NOT IN ('Melbourne Central', 'Mildura')
        ) AS e,
        unnest(string_to_array('A,B,C,D,E,F,G,H', ',')) AS rl,
        generate_series(1, 7) AS pr
    ) AS p
    JOIN bulk_users bu ON bu.n = p.un
    WHERE random() < p.fill
), b AS (
    INSERT INTO bookings (booking_id, event_id, user_id, created_at)
    SELECT booking_id, event_id, user_id, least(now(), starts_at) - make_interval(mins => floor(random() * 20160)::int)
    FROM pair
)
INSERT INTO booking_seats (booking_id, event_id, room_id, seat_id, price_cents)
SELECT pair.booking_id, pair.event_id, pair.room_id, s.seat_id, f.base_price_cents + sts.surcharge_cents + c.surcharge_cents
FROM pair
JOIN events e USING (event_id)
JOIN event_formats f USING (format_id)
JOIN rooms r ON r.room_id = pair.room_id
JOIN cinemas c ON c.cinema_id = r.cinema_id
JOIN seats s ON s.room_id = pair.room_id AND s.row_label = pair.row_label AND s.seat_number IN (pair.pair * 2 - 1, pair.pair * 2)
JOIN seat_type_surcharges sts ON sts.seat_type = s.seat_type;

-- TMDB's details for every film above (synopsis, runtime, poster, backdrop, trailer), copied from a filled database so
-- films show posters and trailers straight after seeding. The backend only fetches films that aren't in this list.
UPDATE movies m SET synopsis = COALESCE(NULLIF(t.synopsis, ''), m.synopsis), runtime_minutes = COALESCE(t.runtime, m.runtime_minutes),
    poster_path = t.poster, backdrop_path = t.backdrop, trailer_key = t.trailer
FROM (VALUES
    (5, 'It''s Ted the Bellhop''s first night on the job...and the hotel''s very unusual guests are about to place him in some outrageous predicaments. It seems that this evening''s room service is serving up one unbelievable happening after another.', 98, '/75aHn1NOYXh4M7L5shoeQ6NGykP.jpg', '/c1BaOxC8bo5ACFYkYYxL0bBWRaq.jpg', 'S_Pd2pGkq54'),
    (11, 'Princess Leia is captured and held hostage by the evil Imperial forces in their effort to take over the galactic Empire. Venturesome Luke Skywalker and dashing captain Han Solo team together with the loveable robot duo R2-D2 and C-3PO to rescue the beautiful princess and restore peace and justice in the Empire.', 121, '/fai0rspsNeJCS69wHNjOdWxcI7P.jpg', '/zqkmTXzjkAgXmEWLRsY4UpTWCeo.jpg', 'i-vsILeJ8_8'),
    (12, 'Nemo, an adventurous young clownfish, is unexpectedly taken from his Great Barrier Reef home to a dentist''s office aquarium. It''s up to his worrisome father Marlin and a friendly but forgetful fish Dory to bring Nemo home -- meeting vegetarian sharks, surfer dude turtles, hypnotic jellyfish, hungry seagulls, and more along the way.', 100, '/eHuGQ10FUzK1mdOY69wF5pGgEf5.jpg', '/eCynaAOgYYiw5yN5lBwz3IxqvaW.jpg', 'SPHfeNgogVs'),
    (13, 'A man with a low IQ has accomplished great things in his life and been present during significant historic events—in each case, far exceeding what anyone imagined he could do. But despite all he has achieved, his one true love eludes him.', 142, '/Cw4hIUIAmSYfK9QfaUW5igp9La.jpg', '/66Kn4XWhkuPkJxOJyPEx4U2CUfN.jpg', 'Mj9IA9tTfio'),
    (14, 'Lester Burnham, a depressed suburban father in a mid-life crisis, decides to turn his hectic life around after developing an infatuation with his daughter''s attractive friend.', 122, '/wby9315QzVKdW9BonAefg8jGTTb.jpg', '/kEA3iOrV1DpHQ3Z01Q28y2Qoc89.jpg', 'XCxzXblZyfQ'),
    (15, 'Newspaper magnate Charles Foster Kane is taken from his mother as a boy and made the ward of a rich industrialist. As a result, every well-meaning, tyrannical or self-destructive move he makes for the rest of his life appears in some way to be a reaction to that deeply wounding event.', 119, '/sav0jxhqiH0bPr2vZFU0Kjt2nZL.jpg', '/ruF3Lmd4A8MHbnEBE6lxPMbsHGL.jpg', 'fAcLNMkzfTE'),
    (18, 'In 2263, a taxi driver is unintentionally given the task of saving a young girl who is part of the key that will ensure the survival of humanity.', 126, '/fPtlCO1yQtnoLHOwKtWz7db6RGU.jpg', '/jW21PoKwqs79wk6bfiYezox63mK.jpg', '5Sg2RkdkSvk'),
    (19, 'In a futuristic city sharply divided between the rich and the poor, the son of the city''s mastermind meets a prophet who predicts the coming of a savior to mediate their differences.', 148, '/kr9wXRN23zLuWJIelahas1mtnYj.jpg', '/eeMoFKxjjiCi6iep2GEZtSAMYIr.jpg', 'ZAvzaOxDt2c'),
    (22, 'When wily pirate Captain Barbossa seizes Jack Sparrow’s beloved ship, the Black Pearl, and kidnaps the governor’s daughter, Elizabeth Swann, blacksmith Will Turner reluctantly teams up with the unpredictable pirate Jack to rescue her—only to uncover a terrifying curse that turns Barbossa’s crew into the undead.', 143, '/poHwCZeWzJCShH7tOjg8RIoyjcw.jpg', '/uRNgkJSkNBFbbn9fPsEjDIy8Sh3.jpg', '-9HT0l9HV4c'),
    (24, 'An assassin is shot by her ruthless employer, Bill, and other members of their assassination circle – but she lives to plot her vengeance.', 111, '/v7TaX8kXMXs5yFFGR41guUDNcnB.jpg', '/iffzIhuLAO38Po6sh1s6ZEVwlNL.jpg', 'sXwXk3jcrfU'),
    (25, 'Jarhead is a film about a US Marine Anthony Swofford’s experience in the Gulf War. After putting up with an arduous boot camp, Swofford and his unit are sent to the Persian Gulf where they are eager to fight, but are forced to stay back from the action. Swofford struggles with the possibility of his girlfriend cheating on him, and as his mental state deteriorates, his desire to kill increases.', 123, '/6vdj47RAWOUZBkeQmqToeZ7eaio.jpg', '/bQ8fRUaitJvi54O2lUT6Ta7FVHK.jpg', '-aBP-c28_1M'),
    (28, 'At the height of the Vietnam war, Captain Benjamin Willard is sent on a dangerous mission that, officially, "does not exist, nor will it ever exist." His goal is to locate - and eliminate - a mysterious Green Beret Colonel named Walter Kurtz, who has been leading his personal army on illegal guerrilla missions into enemy territory.', 147, '/gQB8Y5RCMkv2zwzFHbUJX3kAhvA.jpg', '/49fzLedFVKgGgFChLMuulDJBY1c.jpg', '9l-ViOOFH-s'),
    (33, 'William Munny is a retired, once-ruthless killer turned gentle widower and hog farmer. To help support his two motherless children, he accepts one last bounty-hunter mission to find the men who brutalized a prostitute. Joined by his former partner and a cocky greenhorn, he takes on a corrupt sheriff.', 130, '/54roTwbX9fltg85zjsmrooXAs12.jpg', '/rvRGFevvZK48onX0PYI1eQLbuJd.jpg', 'amE57OniG9Y'),
    (35, 'After Homer accidentally pollutes the town''s water supply, Springfield is encased in a gigantic dome by the EPA and the Simpsons are declared fugitives.', 87, '/s3b8TZWwmkYc2KoJ5zk77qB6PzY.jpg', '/8ln5VUVk7gnNGIb2VNgw8nICDVt.jpg', 'XPG0MqIcby8'),
    (38, 'Joel Barish, heartbroken that his girlfriend underwent a procedure to erase him from her memory, decides to do the same. However, as he watches his memories of her fade away, he realises that he still loves her, and may be too late to correct his mistake.', 108, '/5MwkWH9tYHv3mV9OdYTMR5qreIz.jpg', '/95qi5TJMIBI5VzWHia88Pbrye7Z.jpg', 'c2e-bj6qy8Y'),
    (55, 'A fatalistic car crash in Mexico city sets off a chain of events in the lives of three people: a supermodel, a young man wanting to run off with his sister-in-law, and a homeless man.', 154, '/1lX74fPZsBoOyyE5fWL5xT7k9sV.jpg', '/iTkxwBriD9YKg4Q35qWEIlLXd6e.jpg', '_P29GF_NbDc'),
    (58, 'Captain Jack Sparrow’s got a blood debt to pay: he owes his soul to the legendary Davy Jones, ghastly Ruler of the Ocean Depths. To escape eternal servitude aboard the Flying Dutchman, ever-crafty Jack must track down the still-beating heart of Jones. But he won’t do it alone: Will Turner and Elizabeth Swann are drawn back into another one of his perilous quests—assuming they can evade execution for aiding a pirate.', 151, '/uXEqmloGyP7UXAiphJUu2v2pcuE.jpg', '/vr6n6ZFUZvedvIlhfYcbCWcaKyW.jpg', 'elqO-GNfStM'),
    (59, 'An average family is thrust into the spotlight after the father commits a seemingly self-defense murder at his diner.', 96, '/ptJKY9WGDUUL064ge3jW78zBX0t.jpg', '/dwdZKVRjMqIGLDkdWAU0qs3VdU.jpg', 'jsEcDGKh56U'),
    (62, 'Humanity finds a mysterious object buried beneath the lunar surface and sets off to find its origins with the help of HAL 9000, the world''s most advanced super computer.', 149, '/ve72VxNqjGM69Uky4WTo2bK6rfq.jpg', '/w5IDXtifKntw0ajv2co7jFlTQDM.jpg', 'kR2r-A9H3Kg'),
    (63, 'In the year 2035, convict James Cole reluctantly volunteers to be sent back in time to discover the origin of a deadly virus that wiped out nearly all of the earth''s population and forced the survivors into underground communities. But when Cole is mistakenly sent to 1990 instead of 1996, he''s arrested and locked up in a mental hospital. There he meets psychiatrist Dr. Kathryn Railly and the son of a famous virus expert who may hold the key to the Army of the 12 Monkeys; thought to be responsible for unleashing the killer disease.', 129, '/gt3iyguaCIw8DpQZI1LIN5TohM2.jpg', '/mKIkGoyuR71qz6FdiEiOjxvBQcS.jpg', 'Xwh1xBzsc1Q'),
    (65, 'For Jimmy Smith, Jr., life is a daily fight just to keep hope alive. Feeding his dreams in Detroit''s vibrant music scene, Jimmy wages an extraordinary personal struggle to find his own voice - and earn a place in a world where rhymes rule, legends are born and every moment… is another chance.', 111, '/7BmQj8qE1FLuLTf7Xjf9sdIHzoa.jpg', '/jNG7pl0DkN1nzxnbZj4MCGf2VEG.jpg', 'axGVrfwm9L4'),
    (68, 'Low-level bureaucrat Sam Lowry escapes the monotony of his day-to-day life through a recurring daydream of himself as a virtuous hero saving a beautiful damsel. Investigating a case that led to the wrongful arrest and eventual death of an innocent man instead of wanted terrorist Harry Tuttle, he meets the woman from his daydream, and in trying to help her gets caught in a web of mistaken identities, mindless bureaucracy and lies.', 143, '/2w09J0KUnVtJvqPYu8N63XjAyCR.jpg', '/9IYyCLf5NNAQFK9pNtqzEU9HWzM.jpg', 'A_7ATU9dslE'),
    (70, 'Despondent over a painful estrangement from his daughter, trainer Frankie Dunn isn''t prepared for boxer Maggie Fitzgerald to enter his life. But Maggie''s determined to go pro and to convince Dunn and his cohort to help her.', 132, '/jcfEqKdWF1zeyvECPqp3mkWLct2.jpg', '/oGMomeS7bE43eN8SGJUaKvQnmud.jpg', '5_RsHRmIRBY'),
    (71, 'County Durham, England, 1984. The miners'' strike has started and the police have started coming up from Bethnal Green, starting a class war with the lower classes suffering. Caught in the middle of the conflict is 11-year old Billy Elliot, who, after leaving his boxing club for the day, stumbles upon a ballet class and finds out that he''s naturally talented. He practices with his teacher Mrs. Wilkinson for an upcoming audition in Newcastle-upon Tyne for the royal Ballet school in London.', 111, '/mYtqgWCJiXpDeZwjVcC3OQGD8IR.jpg', '/urzflyf41uySpgciGHdQzpcaMOY.jpg', 'WVUoWgyDxeo'),
    (73, 'Derek Vineyard is paroled after serving 3 years in prison for killing two African-American men. Through his brother, Danny Vineyard''s narration, we learn that before going to prison, Derek was a skinhead and the leader of a violent white supremacist gang that committed acts of racial crime throughout L.A. and his actions greatly influenced Danny. Reformed and fresh out of prison, Derek severs contact with the gang and becomes determined to keep Danny from going down the same violent path as he did.', 119, '/x2drgoXYZ8484lqyDj7L1CEVR4T.jpg', '/6qHI1IYj7QlLSCwHRzkL62X175s.jpg', 'el6JxnW2Tyg'),
    (74, 'Ray Ferrier is a divorced dockworker and less-than-perfect father. Soon after his ex-wife and her new husband drop off his teenage son and young daughter for a rare weekend visit, a strange and powerful lightning storm touches down.', 117, '/6Biy7R9LfumYshur3YKhpj56MpB.jpg', '/bInicBgSHfQiWLbnRT5jxw9Grvm.jpg', 'TLnQXsKn5-E'),
    (75, 'A fleet of Martian spacecraft surrounds the world''s major cities and all of humanity waits to see if the extraterrestrial visitors have, as they claim, "come in peace." U.S. President James Dale receives assurance from science professor Donald Kessler that the Martians'' mission is a friendly one. But when a peaceful exchange ends in the total annihilation of the U.S. Congress, military men call for a full-scale nuclear retaliation.', 106, '/m6BxrwE9RL6ly1B7841n7UTSCQE.jpg', '/ELsTifJ2lu4vsMhoHeZ5EnncHw.jpg', 'kTxmxlxg90E'),
    (76, 'An unexpected meeting on a train leads two travelers to spend an evening wandering through Vienna. As the night unfolds, they share stories and conversations about life and love, exploring new ideas while a quiet intimacy grows between them, knowing it may be their only night together.', 101, '/kf1Jb1c2JAOqjuzA3H4oDM263uB.jpg', '/qA2TyqPldTtoTVY3LKrNIG5g6bH.jpg', 'jGvcbSabADM'),
    (77, 'Leonard Shelby is tracking down the man who raped and murdered his wife. The difficulty of locating his wife''s killer, however, is compounded by the fact that he suffers from a rare, untreatable form of short-term memory loss. Although he can recall details of life before his accident, Leonard cannot remember what happened fifteen minutes ago, where he''s going, or why.', 113, '/nzlv62aC0octS5AklAiWpXLX9Z0.jpg', '/7Wev9JMo6R5XAfz2KDvXb7oPMmy.jpg', 'Wyc9TpJxf4A'),
    (78, 'In the smog-choked dystopian Los Angeles of 2019, blade runner Rick Deckard is called out of retirement to terminate a quartet of replicants who have escaped to Earth seeking their creator for a way to extend their short life spans.', 118, '/63N9uy8nd9j7Eog2axPQ8lbr3Wj.jpg', '/2spEHYDcyE9r9mS7AFEscfKVDzO.jpg', 'qoEyZoOTtss'),
    (80, 'Nine years later, Jesse travels across Europe giving readings from a book he wrote about the night he spent in Vienna with Celine. After his reading in Paris, Celine finds him, and they spend part of the day together before Jesse has to again leave for a flight. They are both in relationships now, and Jesse has a son, but as their strong feelings for each other start to return, both confess a longing for more.', 80, '/gycdE1ARByGQcK4fYR2mgpU6OO.jpg', '/tcZi0LQc5iu2u6i5aOWyj9NBBvl.jpg', 'jx0UWbMMZOQ'),
    (81, 'After a global war, the seaside kingdom known as the Valley of the Wind remains one of the last strongholds on Earth untouched by a poisonous jungle and the powerful insects that guard it. Led by the courageous Princess Nausicaä, the people of the Valley engage in an epic struggle to restore the bond between humanity and Earth.', 95, '/tcrkfB8SRPQCgwI88hQScua6nxh.jpg', '/z2jsAbXWGdJvadhovznjGg33VND.jpg', 'zaskbIZtfxQ'),
    (85, 'When Dr. Indiana Jones – the tweed-suited professor who just happens to be a celebrated archaeologist – is hired by the government to locate the legendary Ark of the Covenant, he finds himself up against the entire Nazi regime.', 115, '/ceG9VzoRAVGwivFU403Wc3AHRys.jpg', '/zPACwR32amTNvzId9qyapCWXYDJ.jpg', '0xQSIdSRlAk'),
    (87, 'After arriving in India, Indiana Jones is asked by a desperate village to find a mystical stone. He agrees – and stumbles upon a secret cult plotting a terrible plan in the catacombs of an ancient palace.', 118, '/gpdVNUaa4LhRMLfJOPj1AZdhAZ3.jpg', '/f133nWlU6yUkZqqwcCXCbTEJWHr.jpg', 'WBdyLyijZhU'),
    (88, 'Expecting the usual tedium that accompanies a summer in the Catskills with her family, 17-year-old Frances ''Baby'' Houseman is surprised to find herself stepping into the shoes of a professional hoofer—and unexpectedly falling in love.', 100, '/9Jw6jys7q9gjzVX5zm1z0gC8gY9.jpg', '/6iDQCBUSZKzY8Rnu8ECwl2gXcfG.jpg', '0rzsa_KEoKs'),
    (89, 'In 1938, an art collector appeals to eminent archaeologist Dr. Indiana Jones to embark on a search for the Holy Grail. Indy learns that a medieval historian has vanished while searching for it, and the missing man is his own father, Dr. Henry Jones Sr.. He sets out to rescue his father by following clues in the old man''s notebook, which his father had mailed to him before he went missing. Indy arrives in Venice, where he enlists the help of a beautiful academic, Dr. Elsa Schneider, along with Marcus Brody and Sallah. Together they must stop the Nazis from recovering the power of eternal life and taking over the world!', 127, '/sizg1AU8f8JDZX4QIgE4pjUMBvx.jpg', '/7KGdTzKux4fp5sW7hUM33NWqBU1.jpg', 'DKg36LBVgfg'),
    (90, 'Fast-talking, quick-thinking Detroit street cop Axel Foley has bent more than a few rules and regs in his time, but when his best friend is murdered, he heads to sunny Beverly Hills to work the case like only he can.', 105, '/eBJEvKkhQ0tUt1dBAcTEYW6kCle.jpg', '/p256RduW9wMC3uhGJTerywmGiiX.jpg', '1UV-lUZIyQk'),
    (95, 'When an asteroid threatens to collide with Earth, NASA honcho Dan Truman determines the only way to stop it is to drill into its surface and detonate a nuclear bomb. This leads him to renowned driller Harry Stamper, who agrees to helm the dangerous space mission provided he can bring along his own hotshot crew. Among them is the cocksure A.J. who Harry thinks isn''t good enough for his daughter, until the mission proves otherwise.', 151, '/eTM3qtGhDU8cvjpoa6KEt5E2auU.jpg', '/1cO6OQJxz7YhTZ4V1OlkYfebeJa.jpg', 'pCWKG2HVqRE'),
    (97, 'When brilliant video game maker Flynn hacks the mainframe of his ex-employer, he is beamed inside an astonishing digital world and becomes part of the very game he is designing. In his mission through cyberspace, Flynn matches wits with a maniacal Master Control Program and teams up with Tron, a security measure created to bring balance to the digital environment.', 96, '/jigY9B6TKz4qlfikZcd18qtzTK4.jpg', '/vUmeBHiGp5r2ydd8aEvbNLamTVD.jpg', 'INv-OQ1clmw'),
    (98, 'After the death of Emperor Marcus Aurelius, his devious son takes power and demotes Maximus, one of Rome''s most capable generals who Marcus preferred. Eventually, Maximus is forced to become a gladiator and battle to the death against other men for the amusement of paying audiences.', 155, '/aDb548BOkFfI4nFm0kx8A3Ezh7H.jpg', '/Ar7QuJ7sJEiC0oP3I8fKBKIQD9u.jpg', 'P5ieIbInFpg'),
    (100, 'A card shark and his unwillingly-enlisted friends need to make a lot of cash quick after losing a sketchy poker match. To do this they decide to pull a heist on a small-time gang who happen to be operating out of the flat next door.', 105, '/6pJB2t3MbQUy9m5pFIBHXLqnqNd.jpg', '/qQz3DeR9PxrMBtVGMnH3EqvMlVU.jpg', 'HY7mRdQuUSw'),
    (101, 'Léon, the top hit man in New York, has earned a rep as an effective "cleaner". But when his next-door neighbors are wiped out by a loose-cannon DEA agent, he becomes the unwilling custodian of 12-year-old Mathilda. Before long, Mathilda''s thoughts turn to revenge, and she considers following in Léon''s footsteps.', 111, '/bxB2q91nKYp8JNzqE7t7TWBVupB.jpg', '/fj0hwDJEOOHllRim2BMt5L7tbjf.jpg', 'DD-6bmOY__g'),
    (103, 'Suffering from insomnia, disturbed loner Travis Bickle takes a job as a New York City cabbie, haunting the streets nightly, growing increasingly detached from reality as he dreams of cleaning up the filthy city.', 114, '/ekstpH614fwDX8DUln1a2Opz0N8.jpg', '/9uddYYTNcLWpzUkl5iw1RUYhLhY.jpg', 'zdqCqDSTVNI'),
    (105, 'Eighties teenager Marty McFly is accidentally sent back in time to 1955, inadvertently disrupting his parents'' first meeting and attracting his mother''s romantic interest. Marty must repair the damage to history by rekindling his parents'' romance and - with the help of his eccentric inventor friend Doc Brown - return to 1985.', 116, '/vN5B5WgYscRGcQpVhHl6p9DDTP0.jpg', '/5bzPWQ2dFUl2aZKkp7ILJVVkRed.jpg', 'ez6WQ7IX72U'),
    (106, 'A team of elite commandos on a secret mission in a Central American jungle come to find themselves hunted by an extraterrestrial warrior.', 107, '/k3mW4qfJo6SKqe6laRyNGnbB9n5.jpg', '/YL3GPOiDcNraIJOVDCZsoOBoDy.jpg', 'SFoQL6gqhFM'),
    (107, 'Unscrupulous boxing promoters, violent bookies, a Russian gangster, incompetent amateur robbers, and supposedly Jewish jewellers fight to track down a priceless stolen diamond.', 103, '/kIBMvdZ3qLUycHLbT6IFs7UtaCq.jpg', '/32V4uHVRU2fbDsQl1dsYsZm3uba.jpg', 'ni4tEtuTccc'),
    (111, 'After getting a green card in exchange for assassinating a Cuban government official, Tony Montana stakes a claim on the drug trade in Miami. Viciously murdering anyone who stands in his way, Tony eventually becomes the biggest drug lord in the state, controlling nearly all the cocaine that comes through Miami. But increased pressure from the police, wars with Colombian drug cartels and his own drug-fueled paranoia serve to fuel the flames of his eventual downfall.', 170, '/iQ5ztdjvteGeboxtmRdXEChJOHh.jpg', '/cCvp5Sni75agCtyJkNOMapORUQV.jpg', 'lZMIrD36MG8'),
    (114, 'Vivian is a carefree, streetwise diamond in the rough when she meets sophisticated billionaire Edward in a chance encounter that turns into a week-long business arrangement. But Vivian''s energetic spirit challenges Edward''s no-nonsense approach to life, and soon they are teaching each other – and falling in love!', 120, '/oVKX1Pt1q7jXTkTk51mu2S0sAB0.jpg', '/rleTwPqymtOpeD2bR7asJGEmldV.jpg', '2EBAVoN8L_U'),
    (115, 'Jeffrey ''The Dude'' Lebowski, a Los Angeles slacker who only wants to bowl and drink White Russians, is mistaken for another Jeffrey Lebowski, a wheelchair-bound millionaire, and finds himself dragged into a strange series of events involving nihilists, adult film producers, ferrets, errant toes, and large sums of money.', 117, '/3bv6WAp6BSxxYvB5ozKFUYuRA8C.jpg', '/lpTXHNKCozJgfUQZZJ1Xn3LKpIS.jpg', 'GiwMMziJdqg'),
    (116, 'Chris, a former tennis pro, takes a job as an instructor and befriends his wealthy young student, Tom. After being introduced to his family, Chris is soon engaged to Tom''s sister, Chloe. Despite the professional and financial advantages that this relationship affords him, Chris becomes obsessed with Tom''s fiancee, American actress Nola.', 124, '/vHjEVTD8ucuwKSFOZJeyAnTZYli.jpg', '/yUJf20GQ5vifhk9QDxUGotAEaLz.jpg', 'yIC7Ygsy0Cg'),
    (117, 'Elliot Ness, an ambitious prohibition agent, is determined to take down Al Capone. In order to achieve this goal, he forms a group given the nickname “The Untouchables”.', 119, '/tPq0R4jTO4Ey8ZspFaWK9wGA4Ls.jpg', '/i1oWUGVDNBhGBykcCRBlX326udb.jpg', 'YbzkK06MJjE'),
    (118, 'A young boy wins a tour through the most magnificent chocolate factory in the world, led by the world''s most unusual candy maker.', 115, '/iKP6wg3c6COUe8gYutoGG7qcPnO.jpg', '/atoIgfAk2Ig2HFJLD0VUnjiPWEz.jpg', 'p6JAQ2aoXm0'),
    (120, 'Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.', 179, '/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', '/oiwc338EoBgS4sEI2ixAny4KQKg.jpg', '_nZdmwHrcnw'),
    (121, 'Frodo Baggins and the other members of the Fellowship continue on their sacred quest to destroy the One Ring--but on separate paths. Their destinies lie at two towers - Orthanc Tower in Isengard, where the corrupt wizard Saruman awaits, and Sauron''s fortress at Barad-dur, deep within the dark lands of Mordor.', 179, '/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg', '/6G73mNyooWAEQTpckPSnFxFoNmc.jpg', 'nuTU5XcZTLA'),
    (122, 'As armies mass for a final battle that will decide the fate of the world--and powerful, ancient forces of Light and Dark compete to determine the outcome--one member of the Fellowship of the Ring is revealed as the noble heir to the throne of the Kings of Men. Yet, the sole hope for triumph over evil lies with a brave hobbit, Frodo, who, accompanied by his loyal friend Sam and the hideous, wretched Gollum, ventures deep into the very dark heart of Mordor on his seemingly impossible quest to destroy the Ring of Power.​', 201, '/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg', '/ctiw6FZK4N36LmkjSklWEbuvlq9.jpg', 'zckJCxYxn1g'),
    (128, 'Ashitaka, a prince of the disappearing Emishi people, is cursed by a demonized boar god and must journey to the west to find a cure. Along the way, he encounters San, a young human woman fighting to protect the forest, and Lady Eboshi, who is trying to destroy it. Ashitaka must find a way to bring balance to this conflict.', 134, '/cMYCDADoLKLbB83g4WnJegaZimC.jpg', '/gl0jzn4BupSbL2qMVeqrjKkF9Js.jpg', 'I1dHzoRl0sQ'),
    (129, 'A young girl, Chihiro, becomes trapped in a strange new world of spirits. When her parents undergo a mysterious transformation, she must call upon the courage she never knew she had to free her family.', 125, '/jUo8cNmU400WtZiJss45HNXlQ2e.jpg', '/dyJvKsNs2KP8qQnAXbRwDjblViy.jpg', 'GAp2_0JJskk'),
    (134, 'In the deep south during the 1930s, three escaped convicts search for hidden treasure while a relentless lawman pursues them.', 107, '/2YztYilviFCYcEtDAnrOstUWGie.jpg', '/rbsm633lnt3hKHEpk7FOt3dy82a.jpg', 'pi-KDvtUaGQ'),
    (137, 'A cynical TV weatherman, along with his idealistic producer and his sardonic cameraman, is sent to report on Groundhog Day in the small town of Punxsutawney, where he finds himself repeating the same day over and over.', 101, '/gCgt1WARPZaXnq523ySQEUKinCs.jpg', '/4W6RYDNe4OByNryOCvJprrutm9h.jpg', '_ADlbEQG_VA'),
    (141, 'After narrowly escaping a bizarre accident, a troubled teenager is plagued by visions of a large bunny rabbit that manipulates him to commit a series of crimes.', 114, '/j2AtZFsflxiluaNtajMTI0Avm8C.jpg', '/msCHK5Kh1YbdZ0zPJ2nzPUhhSN9.jpg', 'iVdehGAy4zA'),
    (142, 'In 1960s Wyoming, two men develop a strong emotional and sexual relationship that endures as a lifelong connection complicating their lives as they get married and start families of their own.', 134, '/aByfQOQBNa4CMFwIgq3QrqY2ZHh.jpg', '/vXzqV2RtJlT9WhNEM4NYWCEC6ZI.jpg', 'xZvu-SczR1Y'),
    (145, 'In a small, conservative Scottish village, an oilman is paralyzed in an accident. His wife, who prayed for his return, feels guilty; even more, when he urges her to have sex with another.', 159, '/dQWMcdHXUOSHtr7ypOCa5T79JMS.jpg', '/nY2faCdUVHzuH6FmDI6QsAURE68.jpg', 'dPmWixRLFPQ'),
    (146, 'Two warriors in pursuit of a stolen sword and a notorious fugitive are led to an impetuous, physically-skilled, teenage nobleman''s daughter, who is at a crossroads in her life.', 120, '/iNDVBFNz4XyYzM9Lwip6atSTFqf.jpg', '/nSm9cij9VRrGDoZoS16CPnX0FqK.jpg', 'q-HrIQLdaNE'),
    (147, 'For young Parisian boy Antoine Doinel, life is one difficult situation after another. Surrounded by inconsiderate adults, including his neglectful parents, Antoine spends his days with his best friend, Rene, trying to plan for a better life. When one of their schemes goes awry, Antoine ends up in trouble with the law, leading to even more conflicts with unsympathetic authority figures.', 99, '/12PuU23kkDLvTd0nb8hMlE3oShB.jpg', '/9w0Kk8Sleb4tkCFEUcvibMzaa16.jpg', 'ICGZfU-9Yl0'),
    (150, 'A hard-nosed cop reluctantly teams up with a wise-cracking criminal temporarily paroled to him, in order to track down a killer.', 96, '/rvvjXHzEDBIvIVDBHNOwHS7hVPu.jpg', '/xQTSGz5dvIAYFssPWhD160AcR7Z.jpg', '24XiqMIC6q8'),
    (153, 'Two lost souls visiting Tokyo -- the young, neglected wife of a photographer and a washed-up movie star shooting a TV commercial -- find an odd solace and pensive freedom to be real in each other''s company, away from their lives in America.', 102, '/3jCLmYDIIiSMPujbwygNpqdpM8N.jpg', '/6ITVHoipvxAS8luzKtHTbPaHLtT.jpg', '1s4YQqnbnM8'),
    (154, 'The starship Enterprise and its crew is pulled back into action when old nemesis, Khan, steals a top secret device called Project Genesis.', 113, '/uPyLsKl8Z0LOoxeaFXsY5MxhR5s.jpg', '/meqmvZjKpQ7WRhpZvIoKIAvioSD.jpg', 'vOIYaRb6XpQ'),
    (155, 'Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.', 152, '/qJ2tW6WMUDux911r6m7haRef0WH.jpg', '/cfT29Im5VDvjE0RpyKOSdCKZal7.jpg', '_PZpmTj1Q8Q'),
    (161, 'Less than 24 hours into his parole, charismatic thief Danny Ocean is already rolling out his next plan: In one night, Danny''s hand-picked crew of specialists will attempt to steal more than $150 million from three Las Vegas casinos. But to score the cash, Danny risks his chances of reconciling with ex-wife, Tess.', 116, '/hQQCdZrsHtZyR6NbKH2YyCqd2fR.jpg', '/ncoqdHs1poUaBqyKic9YI8ai7MP.jpg', 'n3epi9hPbqQ'),
    (162, 'A small suburban town receives a visit from a castaway unfinished science experiment named Edward.', 105, '/e0FqKFvGPdQNWG8tF9cZBtev9Em.jpg', '/uNLIMPxknsV4n3IAEDpS1iqF5dm.jpg', 'S8bBjpUBbro'),
    (163, 'Despite pulling off one of the biggest heists in Las Vegas history and splitting the $160 million take, each of the infamous Ocean''s crew have tried to go straight, lay low and live a legit life... but that''s proven to be a challenge. Casino owner Terry Benedict demands that Danny Ocean return the money, plus millions more in interest. Unable to come up the cash, the crew is forced to come together to pull off another series of heists, this time in Rome, Paris, and Amsterdam – but a Europol agent is hot on their heels.', 125, '/pE5anFf7nf6ah7V3VRezQ1KSovi.jpg', '/5b5HrewiViLWEdMR4dmbd7ajQ8Q.jpg', 'ATHwwFhB-UQ'),
    (164, 'Holly Golightly is an eccentric New York City playgirl determined to marry a Brazilian millionaire. But when young writer Paul Varjak moves into her apartment building, her past threatens to get in their way.', 115, '/79xm4gXw4l7A5D0XukUOJRocFYQ.jpg', '/jXZ2tyJl44yKvh22I6ooQwU5rFM.jpg', 'KlZ4fYqjGJI'),
    (165, 'Marty and Doc are at it again as the time-traveling duo head to 2015 to nip some McFly family woes in the bud. But things go awry thanks to bully Biff Tannen and a pesky sports almanac. In a last-ditch attempt to set things straight, Marty finds himself bound for 1955 and face to face with his teenage parents -- again.', 108, '/hQq8xZe5uLjFzSBt4LanNP7SQjl.jpg', '/w6tPctxWAsHoQXeKxxNOT6lYKpx.jpg', 'MdENmefJRpw'),
    (169, 'A police chief in the war-torn streets of Los Angeles discovers that an extraterrestrial creature is hunting down residents - and that he is the next target.', 108, '/83X4VwY9sdSJykskmsplIVG0a4h.jpg', '/8GGAXEXaTPMDGa0sCPyFcitvlD9.jpg', 'po4MN1V75eU'),
    (170, 'Twenty-eight days after a killer virus was accidentally unleashed from a British research facility, a small group of London survivors are caught in a desperate struggle to protect themselves from the infected. Carried by animals and humans, the virus turns those it infects into homicidal maniacs -- and it''s absolutely impossible to contain.', 113, '/sQckQRt17VaWbo39GIu0TMOiszq.jpg', '/aJFwk1clMal1prxAvKAgHxKPAf.jpg', 'mWEhfF27O0c'),
    (176, 'Two men wake up to find themselves shackled in a grimy, abandoned bathroom. As they struggle to comprehend their predicament, they discover a disturbing tape left behind by the sadistic mastermind known as Jigsaw. With a chilling voice and cryptic instructions, Jigsaw informs them that they must partake in a gruesome game in order to secure their freedom.', 103, '/4da0TS3iQ1IzuyhDS8elgkmOfrN.jpg', '/ok4ot3YbfDYZcINXf91JUfq3maB.jpg', '0bHDblokwv0'),
    (180, 'John Anderton is a top ''Precrime'' cop in the late-21st century, when technology can predict crimes before they''re committed. But Anderton becomes the quarry when another investigator targets him for a murder charge.', 145, '/qtgFcnwh9dAFLocsDk2ySDVS8UF.jpg', '/PrMb3oeEluauy0q9ZO5xL33A6C.jpg', '3JNsNp2DVSE'),
    (184, 'Jackie Brown is a flight attendant who gets caught in the middle of smuggling cash into the country for her gunrunner boss. When the cops try to use Jackie to get to her boss, she hatches a plan — with help from a bail bondsman — to keep the money for herself.', 154, '/rOUx7qg4KmEh1juEDwqzbDSL1Nr.jpg', '/gvaeY5kz3wHrMU6xLdnybziwYXw.jpg', 'pH4HX76YHi0'),
    (185, 'In a near-future Britain, young Alexander DeLarge and his pals get their kicks beating and raping anyone they please. When not destroying the lives of others, Alex swoons to the music of Beethoven. The state, eager to crack down on juvenile crime, gives an incarcerated Alex the option to undergo an invasive procedure that''ll rob him of all personal agency. In a time when conscience is a commodity, can Alex change his tune?', 137, '/4sHeTAp65WrSSuc05nRBKddhBxO.jpg', '/3hwKS7e21hzEnXZaOs2FE6e97bc.jpg', '2meAsIclTzQ'),
    (186, 'Slevin is mistakenly put in the middle of a personal war between the city’s biggest criminal bosses. Under constant watch, Slevin must try not to get killed by an infamous assassin and come up with an idea of how to get out of his current dilemma.', 110, '/x21s3p5wPww534nYj1cWakTcqz4.jpg', '/ShDHEWiJ4NL6ldn4W2m3bEkIBr.jpg', 'oYOiObTFtNk'),
    (187, 'Welcome to Sin City. This town beckons to the tough, the corrupt, the brokenhearted. Some call it dark… Hard-boiled. Then there are those who call it home — Crooked cops, sexy dames, desperate vigilantes. Some are seeking revenge, others lust after redemption, and then there are those hoping for a little of both. A universe of unlikely and reluctant heroes still trying to do the right thing in a city that refuses to care.', 124, '/cByFo9vMktkRsZ6ji6FvOZggBWv.jpg', '/t9kQnqiaxQ8TLB25rTzDKLd0fdM.jpg', '0p0h_YCinMs'),
    (189, 'Some of Sin City''s most hard-boiled citizens cross paths with a few of its more reviled inhabitants.', 102, '/50kALxDX4mmzIRljbNbPY0u4cie.jpg', '/rxMnmklIpunsNsRkQ7hw61ZJa84.jpg', 'XVjDcUCui0w'),
    (192, '14th-century Franciscan monk William of Baskerville and his young novice arrive at a conference to find that several monks have been murdered under mysterious circumstances. To solve the crimes, William must rise up against the Church''s authority and fight the shadowy conspiracy of monastery monks using only his intelligence; which is considerable.', 130, '/fY8MAv403bTIfFPP4ePdHGHUKrp.jpg', '/v4d6PPfqHeUNSdcyBVQ2Xb8yBk0.jpg', 'BX2u0cxj-KU'),
    (194, 'At a tiny Parisian café, the adorable yet painfully shy Amélie accidentally discovers a gift for helping others. Soon Amelie is spending her days as a matchmaker, guardian angel, and all-around do-gooder. But when she bumps into a handsome stranger, will she find the courage to become the star of her very own love story?', 122, '/nSxDa3M9aMvGVLoItzWTepQ5h5d.jpg', '/6n53UI4mX9QMfe2S0Pgt8mGebY1.jpg', '555A7T_kmIc'),
    (196, 'The final installment finds Marty digging the trusty DeLorean out of a mineshaft and looking for Doc in the Wild West of 1885. But when their time machine breaks down, the travelers are stranded in a land of spurs. More problems arise when Doc falls for pretty schoolteacher Clara Clayton, and Marty tangles with Buford Tannen.', 119, '/crzoVQnMzIrRfHtQw0tLBirNfVg.jpg', '/AtF7TESJEMmImBRUj9Z7HmW2ZH0.jpg', 'DTdBq1fQOBU'),
    (197, 'Enraged at the slaughter of Murron, his new bride and childhood love, Scottish warrior William Wallace slays a platoon of the local English lord''s soldiers. This leads the village to revolt and, eventually, the entire country to rise up against English rule.', 178, '/or1gBugydmjToAEq7OZY0owwFk.jpg', '/1m1c5gIWWkb1FEC9lzsoXHhhs7b.jpg', 'nMft5QDOHek'),
    (203, 'A small-time hood must choose from among love, friendship and the chance to rise within the mob.', 112, '/9msfwOeGc9uL1iRRTBdEf15XonC.jpg', '/iezr93fyrP7ZuJKWmHDXOzyvJIe.jpg', 'g9xHpS10CZ0'),
    (207, 'At an elite, old-fashioned boarding school in New England, a passionate English teacher inspires his students to rebel against convention and seize the potential of every day, courting the disdain of the stern headmaster.', 129, '/erzbMlcNHOdx24AXOcn2ZKA7R1q.jpg', '/lFIXZpwwlF9hg8NM3RazaIJDuaj.jpg', 'l8TYfccpdEU'),
    (213, 'Advertising man Roger Thornhill is mistaken for a spy, triggering a deadly cross-country chase.', 137, '/kNOFPQrel9YFCVzI0DF8FnCEpCw.jpg', '/OR8oloCZ3klJtB7Y0i8pSqWw5a.jpg', 'cPNiwc3ogIo'),
    (214, 'Jigsaw has disappeared. Along with his new apprentice Amanda, the puppet-master behind the cruel, intricate games that have terrified a community and baffled police has once again eluded capture and vanished. While city detectives scramble to locate him, Doctor Lynn Denlon and Jeff Reinhart are unaware that they are about to become the latest pawns on his vicious chessboard.', 108, '/4iO9n24Rb10peXV0JH2EldIOrAp.jpg', '/qx8Pb3nVnHLBizI9792pbRN5nnm.jpg', 'Whxt7ewIbGo'),
    (215, 'The chilling and relentless Jigsaw killer returns to terrorize the city once again. When a gruesome murder victim emerges with unmistakable traces of Jigsaw''s sinister methods, Detective Eric Matthews is thrust into a high-stakes investigation. To his surprise, apprehending Jigsaw seems almost too easy, but what he doesn''t realize is that being caught is merely another piece of Jigsaw''s intricate puzzle.', 93, '/gTnaTysN8HsvVQqTRUh8m35mmUA.jpg', '/1lWeIA03iGXTlDv0yzsN0wUdT9T.jpg', 'y979drB7EEI'),
    (217, 'Set during the Cold War, the Soviets—led by sword-wielding Irina Spalko—are in search of a crystal skull which has supernatural powers related to a mystical Lost City of Gold. Indy is coerced to head to Peru at the behest of a young man whose friend—and Indy''s colleague—Professor Oxley has been captured for his knowledge of the skull''s whereabouts.', 122, '/56As6XEM1flWvprX4LgkPl8ii4K.jpg', '/p96949hcwUG2BwE6MgKmw0uYNCx.jpg', 'kTJy1rFBtVw'),
    (218, 'In the post-apocalyptic future, reigning tyrannical supercomputers teleport a cyborg assassin known as the "Terminator" back to 1984 to kill Sarah Connor, whose unborn son is destined to lead insurgents against 21st century mechanical hegemony. Meanwhile, the human-resistance movement dispatches a lone warrior to safeguard Sarah. Can he stop the virtually indestructible killing machine?', 108, '/qvktm0BHcnmDpul4Hz01GIazWPr.jpg', '/ffdqHMWkh1h9MABwIfbfRJhgFW6.jpg', 'nGrW-OR2uDk'),
    (226, 'A young transgender man explores his gender identity and searches for love in rural Nebraska.', 118, '/eB505ycEhFVfMwGglIzXNUyKAIs.jpg', '/yV1s91RyHJIMIJ7KeyHsWJ0ayUv.jpg', 'uxWt9rxNzjg'),
    (235, 'After learning that a boy their age has been accidentally killed near their rural homes, four boys decide to go see the body. Gordie, Vern, Chris, and Teddy encounter a mean junk man and a marsh full of leeches, but they also learn more about one another and their very different home lives. Just a lark at first, the boys'' adventure evolves into a defining event in their lives.', 89, '/vz0w9BSehcqjDcJOjRaCk7fgJe7.jpg', '/yjGllQUm28R4X9xD9T5xMszirgw.jpg', '2rBenGsz23E'),
    (238, 'Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.', 175, '/3bhkrj58Vtu7enYsRolD1fZdja1.jpg', '/ejdD20cdHNFAYAN2DlqPToXKyzx.jpg', 'Ew9ngL1GZvs'),
    (240, 'In the continuing saga of the Corleone crime family, a young Vito Corleone grows up in Sicily and in 1910s New York. In the 1950s, Michael Corleone attempts to expand the family business into Las Vegas, Hollywood and Cuba.', 202, '/8a1lJs7mFyGhGhZZDT1azJUoQiZ.jpg', '/pGzqRKrYeK4LogoysNro0vG8d8N.jpg', '9O1Iy9od7-A'),
    (241, 'Two victims of traumatized childhoods become lovers and serial murderers irresponsibly glorified by the mass media.', 119, '/fEKZwT91gxvkAoyPgpNXo8W5fu0.jpg', '/k3TOt50cHvTLXWYPnXP0szhiXB8.jpg', 'PgxH1-yeWNI'),
    (242, 'In the midst of trying to legitimize his business dealings in 1979 New York and Italy, aging mafia don, Michael Corleone seeks forgiveness for his sins while taking a young protege under his wing.', 162, '/lm3pQ2QoQ16pextRsmnUbG2onES.jpg', '/zNnjHLDtV8Ti3aworltaeaLMov4.jpg', 'qQR85-nGk2M'),
    (251, 'After a young man is murdered, his spirit stays behind to warn his lover of impending danger, with the help of a reluctant psychic.', 127, '/w9RaPHov8oM5cnzeE27isnFMsvS.jpg', '/6nLdSON3ErniBZTXWG7WRqs5jGz.jpg', 'jWvUTmvaOyU'),
    (252, 'When eccentric candy man Willy Wonka promises a lifetime supply of sweets and a tour of his chocolate factory to five lucky kids, penniless Charlie Bucket seeks the golden ticket that will make him a winner.', 100, '/vmpsZkrs4Uvkp9r1atL8B3frA63.jpg', '/ko7hMSCtXoJFfpYAIbrowwgH0eq.jpg', '2WKPKnggJqk'),
    (253, 'James Bond must investigate a mysterious murder case of a British agent in New Orleans. Soon he finds himself up against a gangster boss named Mr. Big.', 121, '/39qkrjqMZs6utwNmihVImC3ghas.jpg', '/hzmmXx6UeYQeylioNbliFKjSbV7.jpg', '6SQVTSFyf_A'),
    (254, 'In 1933 New York, an overly ambitious movie producer coerces his cast and hired ship crew to travel to mysterious Skull Island, where they encounter Kong, a giant ape who is immediately smitten with the leading lady.', 188, '/6a2HY6UmD7XiDD3NokgaBAXEsD2.jpg', '/mRM2NB0i3wv4HqxXvwIjEVi4Qqq.jpg', '9extfjDZCts'),
    (262, 'Aspiring comic Rupert Pupkin attempts to achieve success in show business by stalking his idol, a late night talk-show host who craves his own privacy.', 109, '/m24EbHxT9NGYEkOlu29YcLOgjgK.jpg', '/7Mh1DM4kCMbN93C2MlUavYbH5YM.jpg', '0wVhCCo02P4'),
    (268, 'Having witnessed his parents'' brutal murder as a child, millionaire philanthropist Bruce Wayne fights crime in Gotham City disguised as Batman, a costumed hero who strikes fear into the hearts of villains. But when a deformed madman known as ''The Joker'' seizes control of Gotham''s criminal underworld, Batman must face his most ruthless nemesis ever while protecting both his identity and his love interest, reporter Vicki Vale.', 126, '/cij4dd21v2Rk2YtUQbV5kW69WB2.jpg', '/rhc7OF7tC9HPu0X8DBKQJzaGRbu.jpg', 'ygK7sAavO0c'),
    (272, 'Driven by tragedy, billionaire Bruce Wayne dedicates his life to uncovering and defeating the corruption that plagues his home, Gotham City.  Unable to work within the system, he instead creates a new identity, a symbol of fear for the criminal underworld - The Batman.', 140, '/sPX89Td70IDDjVr85jdSBb4rWGr.jpg', '/9IIBboV7MCT0bTxzXHmWK1Hq558.jpg', 'lirBhHXvDSg'),
    (274, 'Clarice Starling is a top student at the FBI''s training academy.  Jack Crawford wants Clarice to interview Dr. Hannibal Lecter, a brilliant psychiatrist who is also a violent psychopath, serving life behind bars for various acts of murder and cannibalism.  Crawford believes that Lecter may have insight into a case and that Starling, as an attractive young woman, may be just the bait to draw him out.', 119, '/uS9m8OBk1A8eM9I042bx8XXpqAq.jpg', '/mbOx1wxMLikzwWUO9TKAcFIy6op.jpg', '6iB21hsprAQ'),
    (275, 'Jerry Lundegaard is a small-town Minnesota car salesman deeply in debt and willing to do almost anything to get out. Police chief Marge Gunderson discovers a string of violent crimes as Jerry''s schemes spiral out of control.', 98, '/rt7cpEr1uP6RTZykBFhBTcRaKvG.jpg', '/747dgDfL5d8esobk7h4odaOFhUq.jpg', 'Y4h7NITkNG0'),
    (277, 'Vampires and werewolves have waged a nocturnal war against each other for centuries. But all bets are off when a female vampire warrior named Selene, who''s famous for her strength and werewolf-hunting prowess, becomes smitten with a peace-loving male werewolf, Michael, who wants to end the war.', 122, '/zsnQ41UZ3jo1wEeemF0eA9cAIU0.jpg', '/pvVkWJZYsUoCgnvpkd62pgnet7r.jpg', 'gvzQGXGFD14'),
    (278, 'Imprisoned in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.', 142, '/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg', '/v8xVDqt8uCul3c3mgx4VpGCwxJC.jpg', 'PLl99DlL6b4'),
    (279, 'Disciplined Italian composer Antonio Salieri becomes consumed by jealousy and resentment towards the hedonistic and remarkably talented young Salzburger composer Wolfgang Amadeus Mozart.', 160, '/gQRfiyfGvr1az0quaYyMram3Aqt.jpg', '/rnQyWw68dPHPRtvSWMtLSueXf05.jpg', 'pNnugovJdzM'),
    (280, 'Ten years after the events of the original, a reprogrammed T-800 is sent back in time to protect young John Connor from the shape-shifting T-1000. Together with his mother Sarah, he fights to stop Skynet from triggering a nuclear apocalypse.', 137, '/jFTVD4XoWQTcg7wdyJKa8PEds5q.jpg', '/izkMjmhauFx9DjoBQqM5sM5WAwE.jpg', 'BuBD2s2NmEM'),
    (281, 'In the last days of 1999, ex-cop turned street hustler Lenny Nero receives a disc which contains the memories of the murder of a prostitute. With the help of bodyguard Mace, he starts to investigate and is pulled deeper and deeper in a whirl of murder, blackmail and intrigue.', 145, '/rY5BrDRcYAKE0BYmmT66YG6Uy5Q.jpg', '/zSFuvi6fIPT8CHpH1KMG25T2Iub.jpg', 't3vX5XRpV9c'),
    (284, 'Bud Baxter is a minor clerk in a huge New York insurance company, until he discovers a quick way to climb the corporate ladder. He lends out his apartment to the executives as a place to take their mistresses. Although he often has to deal with the aftermath of their visits, one night he''s left with a major problem to solve.', 126, '/hhSRt1KKfRT0yEhEtRW3qp31JFU.jpg', '/vRTKNKNWLZ22fAgPa5kY8wT2b1F.jpg', 'ekDkUUPSWuY'),
    (285, 'After losing Captain Jack Sparrow to the locker of Davy Jones, Will Turner, Elizabeth Swann, and Captain Barbossa journey to the ends of the earth to rescue him. And as the East India Trading Company tightens its grip on the seas under Lord Cutler Beckett—now in control of Davy Jones—the fate of piracy hangs by a thread. Now, they must unite the pirate lords for one final stand. But as loyalties are tested and alliances shift, each must ultimately choose where they stand in the battle for freedom on the high seas.', 169, '/jGWpG4YhpQwVmjyHEGkxEkeRf0S.jpg', '/1jHxkVXMI5s3vRiyiZooUy1shB5.jpg', 'HKSZtp_OGHY'),
    (289, 'In Casablanca, Morocco in December 1941, a cynical American expatriate meets a former lover, with unforeseen complications.', 102, '/lGCEKlJo2CnWydQj7aamY7s1S7Q.jpg', '/87wqeMeUeMRLjsE1IWNKJcPlpuC.jpg', 'MF7JH_54d8c'),
    (296, 'It''s been 10 years since John Connor saved Earth from Judgment Day, and he''s now living under the radar, steering clear of using anything Skynet can trace. That is, until he encounters T-X, a robotic assassin ordered to finish what T-1000 started. Good thing Connor''s former nemesis, the Terminator, is back to aid the now-adult Connor … just like he promised.', 109, '/vvevzdYIrk2636maNW4qeWmlPFG.jpg', '/voVkSwgFYv9GOpRNfUAwj6qYRTL.jpg', 'ysQizA7Una8'),
    (297, 'Bill Parrish has it all - success, wealth and power. Days before his 65th birthday, he receives a visit from a mysterious stranger, Joe Black, who soon reveals himself as Death. In exchange for extra time, Bill agrees to serve as Joe''s earthly guide. But will he regret his choice when Joe unexpectedly falls in love with Bill''s beautiful daughter Susan?', 178, '/fDPAjvfPMomkKF7cMRmL5Anak61.jpg', '/uMBByiSDpgFwWVegAtwwnuzvogJ.jpg', '_zIOjl93WrU'),
    (298, 'Danny Ocean''s team of criminals are back and composing a plan more personal than ever. When ruthless casino owner Willy Bank doublecrosses Reuben Tishkoff, causing a heart attack, Danny Ocean vows that he and his team will do anything to bring down Willy Bank along with everything he''s got. Even if it means asking for help from an enemy.', 122, '/pBsZs4zYUiUTemqbikTZ76iQRaU.jpg', '/uS18gs16EXfFJhjA11cXj4WWPMb.jpg', 'sbzwtsMiVQY'),
    (310, 'Bruce Nolan toils as a "human interest" television reporter in Buffalo, NY, but despite his high ratings and the love of his beautiful girlfriend, Bruce remains unfulfilled. At the end of the worst day in his life, he angrily ridicules God — and the Almighty responds, endowing Bruce with all of His divine powers.', 101, '/wqkWrOFtYnZSvIMu8Lsmz7WIvKC.jpg', '/m0eJc9CwCy5nowYQdNEaxkHHmj4.jpg', '0XBxoKumlqQ'),
    (311, 'A former Prohibition-era Jewish gangster returns to the Lower East Side of Manhattan over thirty years later, where he once again must confront the ghosts and regrets of his old life.', 139, '/i0enkzsL5dPeneWnjl1fCWm6L7k.jpg', '/xlDUjb0Q5Dv6jPQRF5VE4IMjIy.jpg', '5vrbUpDihxs'),
    (314, 'Liquidated after discovering a corporate conspiracy, mild-mannered graphic artist Patience Phillips washes up on an island, where she''s resurrected and endowed with the prowess of a cat — and she''s eager to use her new skills... as a vigilante. Before you can say "cat and mouse", handsome gumshoe Tom Lone is on her tail, fascinated by both of her personas.', 104, '/pvnPgukFyEKgCzyOxyLiwyZ8T1C.jpg', '/cxAr9Su5gYfx16vxtS2Zi6qc5DZ.jpg', 'Fp7MeqkCUfc'),
    (319, 'Clarence marries hooker Alabama, steals cocaine from her pimp, and tries to sell it in Hollywood, while the owners of the coke try to reclaim it.', 119, '/AqlPzcILRi0IW0JodKp7pMMNEFt.jpg', '/1Uh8yuXlFcMDpVHWZJidjanT06e.jpg', '6uoPeUa7Gkc'),
    (320, 'Two Los Angeles homicide detectives are dispatched to a northern town where the sun doesn''t set to investigate the methodical murder of a local teen.', 118, '/riVXh3EimGO0y5dgQxEWPRy5Itg.jpg', '/jU8MC5uSgBkZXyZYGtZgMsMsfeN.jpg', 'Eby9E9TBYOc'),
    (322, 'The lives of three men who were childhood friends are shattered when one of them suffers a family tragedy.', 138, '/hCHVDbo6XJGj3r2i4hVjKhE0GKF.jpg', '/4ycpMe25LYpzGW42U9amyW9gM53.jpg', 'W7NktJhrRYQ'),
    (329, 'A wealthy entrepreneur secretly creates a theme park featuring living dinosaurs drawn from prehistoric DNA. Before opening day, he invites a team of experts and his two eager grandchildren to experience the park and help calm anxious investors. However, the park is anything but amusing as the security systems go off-line and the dinosaurs escape.', 127, '/d9mtMGQDLANKieb9PbD3yK7xxzo.jpg', '/f082quUW2kAtZXFZVGEfhwacZoG.jpg', 'Rz_FvTXa_qY'),
    (330, 'Four years after Jurassic Park''s genetically bred dinosaurs ran amok, multimillionaire John Hammond shocks chaos theorist Ian Malcolm by revealing that he has been breeding more beasties at a secret location. Malcolm, his paleontologist ladylove and a wildlife videographer join an expedition to document the lethal lizards'' natural behavior in this action-packed thriller.', 129, '/s4RkAQWI9hgzctXgNFos8sJUnXJ.jpg', '/A4rYaPdzgocCjQ0n9LUSYUxyvpS.jpg', 'vtfwgaHD5_w'),
    (331, 'In need of funds for research, Dr. Alan Grant accepts a large sum of money to accompany Paul and Amanda Kirby on an aerial tour of the infamous Isla Sorna. It isn''t long before all hell breaks loose and the stranded wayfarers must fight for survival as a host of new -- and even more deadly -- dinosaurs try to make snacks of them.', 92, '/oQXj4NUfS3r3gHXtDOzcJgj1lLc.jpg', '/8v8x4vVbRgrsdU3M4drnD7HQbfe.jpg', 'FBRWNdXpG1g'),
    (334, 'On one random day in the San Fernando Valley, a dying father, a young wife, a male caretaker, a famous lost son, a police officer in love, a boy genius, an ex-boy genius, a game show host and an estranged daughter will each become part of a dazzling multiplicity of plots, but one story.', 189, '/tpfC325Jk6S38VTe5dDWjWtoyxr.jpg', '/mFfyE5DPFDqoes4HIcElHc2a15y.jpg', 'cxcegktcxSM'),
    (335, 'As the railroad builders advance unstoppably through the Arizona desert on their way to the sea, Jill arrives in the small town of Flagstone with the intention of starting a new life.', 166, '/qbYgqOczabWNn2XKwgMtVrntD6P.jpg', '/u5IhDThM1SClL4pkCUp8hOmsDQJ.jpg', 'Yw-Av9BpC-w'),
    (345, 'After Dr. Bill Harford''s wife, Alice, admits to having sexual fantasies about a man she met, Bill becomes obsessed with having a sexual encounter. He discovers an underground sexual group and attends one of their meetings -- and quickly discovers that he is in over his head.', 159, '/knEIz1eNGl5MQDbrEAVWA7iRqF9.jpg', '/aC6wW62V6b0csr5iUnbOjYAqfhg.jpg', 'qku0sbMkFZo'),
    (346, 'A samurai answers a village''s request for protection after he falls on hard times. The town needs protection from bandits, so the samurai gathers six others to help him teach the people how to defend themselves, and the villagers provide the soldiers with food.', 207, '/lOMGc8bnSwQhS4XyE1S99uH8NXf.jpg', '/qvZ91FwMq6O47VViAr8vZNQz3WI.jpg', 'RsRN65PlaIM'),
    (348, 'During its return to the earth, commercial spaceship Nostromo intercepts a distress signal from a distant planet. When a three-member team of the crew discovers a chamber containing thousands of eggs on the planet, a creature inside one of the eggs attacks an explorer. The entire crew is unaware of the impending nightmare set to descend upon them when the alien parasite planted inside its unfortunate host is birthed.', 117, '/vfrQk5IPloGg1v9Rzbh2Eg3VGyM.jpg', '/gZbcm1ADEXuxs1TsBVOBdk4heGI.jpg', 'sVwH0hIvV5k'),
    (350, 'A young woman from the Midwest gets more than she bargained for when she moves to New York to become a writer and ends up as the assistant to the tyrannical, larger-than-life editor-in-chief of a major fashion magazine.', 109, '/8912AsVuS7Sj915apArUFbv6F9L.jpg', '/gkh6Nt8DtY1XT4gQsyFq9XAVJlJ.jpg', 't4isatjZ0BM'),
    (364, 'The monstrous Penguin, who dwells in the sewers beneath Gotham, joins up with corrupt mayoral candidate Max Shreck to topple the Batman once and for all. But when Shreck''s timid assistant Selina Kyle finds out, and Shreck tries to kill her, she''s transformed into the sexy Catwoman. She teams up with the Penguin and Shreck to destroy Batman, but sparks fly unexpectedly when she confronts the caped crusader.', 126, '/jKBjeXM7iBBV9UkUcOXx3m7FSHY.jpg', '/9vYIWoJ3EoD8UoCiZOCTszrkRVZ.jpg', 'TlbtLfWvFbo'),
    (377, 'Teenagers in a small town are dropping like flies, apparently in the grip of mass hysteria causing their suicides. A cop''s daughter, Nancy Thompson, traces the cause to child molester Fred Krueger, who was burned alive by angry parents many years before. Krueger has now come back in the dreams of his killers'' children, claiming their lives as his revenge. Nancy and her boyfriend, Glen, must devise a plan to lure the monster out of the realm of nightmares and into the real world...', 91, '/b9rMHAAKISRmIonaQd9Cccx0S4X.jpg', '/nzSjTiecdosBfwMGAdpt9CxltCI.jpg', 'CBcVZcornjI'),
    (380, 'When car dealer Charlie Babbitt learns that his estranged father has died, he returns home to Cincinnati, where he discovers that he has a savant older brother named Raymond and that his father''s $3 million fortune is being left to the mental institution in which Raymond lives. Motivated by his father''s money, Charlie checks Raymond out of the facility in order to return with him to Los Angeles. The brothers'' cross-country trip ends up changing both their lives.', 134, '/iTNHwO896WKkaoPtpMMS74d8VNi.jpg', '/b3tos7Tsd6lsTe52Nn4TMrEQg65.jpg', 'wwmctS4nldM'),
    (388, 'When an armed, masked gang enter a Manhattan bank, lock the doors and take hostages, the detective assigned to effect their release enters negotiations preoccupied with corruption charges he is facing.', 129, '/ffMUgkDZICNiyaws1Jkv8qG8uFW.jpg', '/tOkSenL74N23O4S7wjJSUHz7Aeh.jpg', '4G7n7O5pel0'),
    (389, 'The defense and the prosecution have rested and the jury is filing into the jury room to decide if a young Spanish-American is guilty or innocent of murdering his father. What begins as an open and shut case soon becomes a mini-drama of each of the jurors'' prejudices and preconceptions about the trial, the accused, and each other.', 97, '/zhG3vKWyDRaZYoaww1UVAi29T9h.jpg', '/qqHQsStV6exghCM7zbObuYBiYxw.jpg', 'TEN-2uTi2c0'),
    (391, 'The Man With No Name enters the Mexican village of San Miguel in the midst of a power struggle among the three Rojo brothers and sheriff John Baxter. When a regiment of Mexican soldiers bearing gold intended to pay for new weapons is waylaid by the Rojo brothers, the stranger inserts himself into the middle of the long-simmering battle, selling false information to both sides for his own benefit.', 99, '/lBwOEpwVeUAmrmglcstnaGcJq3Y.jpg', '/9gMkOYzk7P9QXwndhLRAC8cMZcJ.jpg', 'f_oZUWAdEe8'),
    (393, 'The Bride unwaveringly continues on her roaring rampage of revenge against the band of assassins who had tried to kill her and her unborn child. She visits each of her former associates one-by-one, checking off the victims on her Death List Five until there''s nothing left to do … but kill Bill.', 136, '/2yhg0mZQMhDyvUQ4rG1IZ4oIA8L.jpg', '/pgG6tzJzC8mjGqhaT8IWwEk00xf.jpg', 'q2h6EFk36kI'),
    (395, 'When scientists discover something near Antarctica that appears to be a buried Pyramid, they send a research team out to investigate. Little do they know that they are about to step into a hunting ground where Aliens are grown as sport for the Predator race.', 101, '/2DKoPom57PVtJWcJlq7bS7JpahU.jpg', '/xvq1RLaiwSdHwPHe7WUhqZa1rCA.jpg', 'fQE62sQBkqA'),
    (402, 'Catherine, a novelist with an insatiable sexual appetite, becomes a prime suspect when her boyfriend is brutally murdered -- a crime she had described in her latest story.', 128, '/76Ts0yoHk8kVQj9MMnoMixhRWoh.jpg', '/7FRraud59N3s10bbf9bfYjvwx3v.jpg', 'cvktbdKzsq4'),
    (408, 'A beautiful girl, Snow White, takes refuge in the forest in the house of seven dwarfs to hide from her stepmother, the wicked Queen. The Queen is jealous because she wants to be known as "the fairest in the land," and Snow White''s beauty surpasses her own.', 83, '/3VAHfuNb6Z7UiW12iYKANSPBl8m.jpg', '/4yWayBvwl9gHXaWrDrAslxjL7mh.jpg', 'ZZ38rMz9U14'),
    (411, 'Four kids travel through a wardrobe to the land of Narnia and learn of their destiny to free it with the guidance of a mystical lion.', 143, '/iREd0rNCjYdf5Ar0vfaW32yrkm.jpg', '/tuDhEdza074bA497bO9WFEPs6O6.jpg', '3mKPrxjwF7A'),
    (414, 'Batman faces off against two foes: the schizophrenic, horribly scarred former District Attorney Harvey Dent, aka Two-Face, and the Riddler, a disgruntled ex-Wayne Enterprises inventor seeking revenge against his former employer by unleashing his brain-sucking weapon on Gotham City''s residents. As the caped crusader also copes with tortured memories of his parents'' murder, he has a new romance, with psychologist Chase Meridian.', 121, '/i0fJS8M5UKoETjjJ0zwUiKaR8tr.jpg', '/snlu32RmjldF9b068UURJg8sQtn.jpg', 'suOgRZflPtk'),
    (415, 'Batman and his sidekick Robin attempt to the foil the sinister schemes of a deranged set of new villains, most notably the melancholy Mr. Freeze, who wants to make Gotham City into an arctic region, and the sultry Poison Ivy, a botanical femme fatale. As the Dynamic Duo contend with these bad guys, a third hero, Batgirl, joins the ranks of the city''s crime-fighters.', 125, '/i7hEUpDuMN2LOrCEifFyGSHZQSY.jpg', '/kEuQWHte2erRpAICrYqkAZaZAAY.jpg', 'Zc7sjDHW2KY'),
    (423, 'The true story of pianist Władysław Szpilman''s experiences in Warsaw during the Nazi occupation. When the Jews of the city find themselves forced into a ghetto, Szpilman finds work playing in a café; and when his family is deported in 1942, he stays behind, works for a while as a laborer, and eventually goes into hiding in the ruins of the war-torn city.', 150, '/2hFvxCCWrTmCYwfy7yum0GKRi3Y.jpg', '/c0fB9xk7D1aVb3Bg2rk2SVJcGn.jpg', 'og9hFxxdSOg'),
    (424, 'The true story of how businessman Oskar Schindler saved over a thousand Jewish lives from the Nazis while they worked as slaves in his factory during World War II.', 195, '/sF1U4EUQS8YHUYjNl3pMGNIQyr0.jpg', '/zb6fM1CX41D9rF9hdgclu0peUmy.jpg', 'v0RB-3sWbBA'),
    (425, 'Manny the mammoth, Sid the loquacious sloth, and Diego the sabre-toothed tiger go on a comical quest to return a human baby back to his father, across a world on the brink of an ice age.', 81, '/gLhHHZUzeseRXShoDyC4VqLgsNv.jpg', '/tyVAGH1vw9JDgxPyTUQPn91nIYc.jpg', 'i4noiCRJRoE'),
    (426, 'A retired San Francisco detective suffering from acrophobia investigates the strange activities of an old friend''s wife, all the while becoming dangerously obsessed with her.', 128, '/15uOEfqBNTVtDUT7hGBVCka0rZz.jpg', '/rtVwkTqllcmyY4TVOycgVBHppWf.jpg', 'UHhsEYDg8GI'),
    (429, 'While the Civil War rages on between the Union and the Confederacy, three men – a quiet loner, a ruthless hitman, and a Mexican bandit – comb the American Southwest in search of a strongbox containing $200,000 in stolen gold.', 161, '/bX2xnavhMYjWDoZp1VM6VnU1xwe.jpg', '/x4biAVdPVCghBlsVIzB6NmbghIz.jpg', 'WCnRSl24FPA'),
    (431, 'A group of strangers find themselves trapped in a maze-like prison. It soon becomes clear that each of them possesses the peculiar skills necessary to escape, if they don''t wind up dead first.', 90, '/x4BTjxdrOKC27FcSkBh8KPEgnum.jpg', '/3TimUBrXMVblpnTsyg4HssGVbBv.jpg', 'nRZ1M4oMGJg'),
    (433, 'In turn of the century London, a magical nanny employs music and adventure to help two neglected children become closer to their father.', 139, '/o4Wsby4ydIXhWmtmfvb451D5Np1.jpg', '/nMXLizoHhVTeh3GjFyUOfNx3b7i.jpg', 'H54Ft85U2RA'),
    (435, 'After paleoclimatologist Jack Hall is largely ignored by UN officials when presenting his environmental concerns about the beginning of a new Ice Age, his research proves true when a superstorm develops, setting off catastrophic natural disasters throughout the world. Trying to get to his son, Sam, who is trapped in New York City with his friend Laura and others, Jack and his crew must travel to get to Sam before it''s too late.', 124, '/Wr4HeYQRvwVCxzOV5TmGE7UkXq.jpg', '/smqQ71MIn1DSdSiQzCzCOV6rgRq.jpg', 'HUBDFoMNXzA'),
    (440, 'After a horrifying PredAlien crash-lands near a small Colorado town, killing everyone it encounters and producing countless Alien offspring, a lone Predator arrives to "clean up" the infestation.', 94, '/5iTwPDNtvK6ZZF607BHBbU3HO0B.jpg', '/jXntuh47VtKLeoyBQ268rv24Igw.jpg', 'XbTWLrZLYmU'),
    (451, 'Ben Sanderson, an alcoholic Hollywood screenwriter who lost everything because of his drinking, arrives in Las Vegas to drink himself to death. There, he meets and forms an uneasy friendship and non-interference pact with prostitute Sera.', 111, '/wIfP6uLXD9Ptu68SyRx8WuSNNSK.jpg', '/ckTh7Ej33m9O4eiKDQ1u91Opd9N.jpg', 'PW_piBbb_lc'),
    (453, 'From the heights of notoriety to the depths of depravity, John Forbes Nash Jr. experiences it all. As a brilliant but socially awkward mathematician, he made a groundbreaking discovery early in his career and stands on the brink of international acclaim. But as the handsome and arrogant Nash accepts secret work in cryptography, he becomes entangled in a mysterious conspiracy. His life takes a nightmarish turn and he soon finds himself on a painful and harrowing journey of self-discovery.', 136, '/rEIg5yJdNOt9fmX4P8gU9LeNoTQ.jpg', '/hCJFWTPghXCwwSpvPpAoIB8318Q.jpg', 'WFJgUm7iOKw'),
    (454, 'In this contemporary take on William Shakespeare''s classic tragedy, the Montagues and Capulets have moved their ongoing feud to the sweltering suburb of Verona Beach, where Romeo and Juliet fall in love and secretly wed. Though the film is visually modern, the bard''s dialogue remains.', 120, '/dJCDUkXhfRdc4q8e4VCKEBbqzBT.jpg', '/hoQBa4EK6KFS31sPBND9zMjARfb.jpg', 'oO4jqwpt25k'),
    (462, 'A twice-divorced mother of three who sees an injustice, takes on the bad guy and wins -- with a little help from her push-up bra. Erin goes to work for an attorney and comes across medical records describing illnesses clustered in one nearby town. She starts investigating and soon exposes a monumental cover-up.', 131, '/eMs20iUQyZVs05Ck7Q0LNnRsstr.jpg', '/3HmLKhahTxX2ALTWlagr92pZrU7.jpg', 'jjqUUxIy_yk'),
    (483, 'Young lovers Sailor and Lula hit the road to start a new life together away from the wrath of Lula’s deranged, disapproving mother, who has hired a team of hitmen to cut the lovers’ surreal honeymoon short.', 125, '/uLUFI5sJIfWrBUWB2Y1dEuyvvVy.jpg', '/6xJ2odkMFmO2LptVUBR8t8wBldQ.jpg', 'CEm7gH0PzLU'),
    (489, 'Will Hunting is a headstrong, working-class genius who is failing the lessons of life. After one too many run-ins with the law, Will''s last chance is a psychology professor, who might be the only man who can reach him.', 127, '/z2FnLKpFi1HPO7BEJxdkv6hpJSU.jpg', '/xj1Sv1xm4Y0ydBueGuf10Y9qM0O.jpg', 'ReIJ1lbL-Q8'),
    (490, 'When disillusioned Swedish knight Antonius Block returns home from the Crusades to find his country in the grips of the Black Death, he challenges Death to a chess match for his life. Tormented by the belief that God does not exist, Block sets off on a journey, meeting up with traveling players Jof and his wife, Mia, and becoming determined to evade Death long enough to commit one redemptive act while he still lives.', 96, '/wcZ21zrOsy0b52AfAF50XpTiv75.jpg', '/6s2BqtDvp1BMiP70zCDU5OW6hMy.jpg', 'vZucwtdSvJ8'),
    (492, 'One day at work, unsuccessful puppeteer Craig finds a portal into the head of actor John Malkovich. The portal soon becomes a passion for anybody who enters its mad and controlling world of overtaking another human body.', 113, '/31FGQu3OnwdmS4COquENe0vMZc0.jpg', '/1Nyjb7aeRKynWgmOl8he5ZcvWLm.jpg', 'LEtlqumjXLw'),
    (496, 'Kazakh journalist Borat Sagdiyev travels to America to make a documentary. As he zigzags across the nation, Borat meets real people in real situations with hysterical consequences. His backwards behavior generates strong reactions around him exposing prejudices and hypocrisies in American culture.', 84, '/7g9kBHMN2KTr5KUf8aen187Mdn.jpg', '/mEagEZkyUp18shDqX05w4zxTnEM.jpg', 'vlnUa_dNsRQ'),
    (497, 'A supernatural tale set on death row in a Southern prison, where gentle giant John Coffey possesses the mysterious power to heal people''s ailments. When the cell block''s head guard, Paul Edgecomb, recognizes Coffey''s miraculous gift, he tries desperately to help stave off the condemned man''s execution.', 189, '/8VG8fDNiy50H4FedGwdSVUPoaJe.jpg', '/amZavErrjrdgDwhsIdpWxHNenIx.jpg', 'Bg7epsq0OIQ'),
    (500, 'A botched robbery indicates a police informant, and the pressure mounts in the aftermath at a warehouse. Crime begets violence as the survivors -- veteran Mr. White, newcomer Mr. Orange, psychopathic parolee Mr. Blonde, bickering weasel Mr. Pink and Nice Guy Eddie -- unravel.', 99, '/xi8Iu6qyTfyZVDVy60raIOYJJmk.jpg', '/jwt159hXWA9Q5xpBo8hWb3zwLi7.jpg', '2KLZ4fSXtgI'),
    (504, 'In 1989, prostitute Aileen Wuornos befriends and enters a relationship with a young woman named Selby. Determined to straighten out her life, Aileen''s limited education lands her back on the corner. She''s raped by a trick, who she kills. A string of murder and robbery follows that ultimately leads Aileen to becoming America''s first female serial killer.', 109, '/sWPKG1GX0woLNBuvDZkwZC8Q3Ub.jpg', '/nUJk4UjWS9YvBJUepCWziQ1QYSf.jpg', 'vq70brIQP40'),
    (508, 'Eight very different couples deal with their love lives in various loosely interrelated tales all set during a frantic month before Christmas in London.', 135, '/7QPeVsr9rcFU9Gl90yg0gTOTpVv.jpg', '/xUWf5xX0AnZgAnYXAMk03zTbsef.jpg', 'r3mJrSA1x5s'),
    (509, 'London bookstore owner William Thacker''s quiet life turns upside down when a chance encounter with famous actress Anna Scott sparks an unlikely romance challenged by their vastly different worlds.', 124, '/hHRIf2XHeQMbyRb3HUx19SF5Ujw.jpg', '/gznkDTmyJflVCImfC36dr0EDy5W.jpg', 'sn-m50RUf_Q'),
    (510, 'A petty criminal fakes insanity to serve his sentence in a mental ward rather than prison. He soon finds himself as a leader to the other patients—and an enemy to the cruel, domineering nurse who runs the ward.', 135, '/kjWsMh72V6d8KRLV4EOoSJLT1H7.jpg', '/5hll0hYssHbJiKxFcsQQLL7BhSP.jpg', 'F4da9uRIg8c'),
    (521, 'When her American lover visits London, a wealthy woman’s jealous husband hatches a plan to murder her and inherit her fortune.', 105, '/2gDCAgl2iBQNuJuk6p2xtuS1ewg.jpg', '/mD6EAjfIr7CLdFlCIJjh7CJeWX3.jpg', 'kR_NZuW28XE'),
    (524, 'In Las Vegas, two best friends-a casino executive and a Mafia enforcer--compete for a gambling empire and a fast-living, fast-loving socialite.', 179, '/gziIkUSnYuj9ChCi8qOu2ZunpSC.jpg', '/iZGiMD0p1M2AOmzKknFo5bkuz94.jpg', 'zFUKn_75m1o'),
    (525, 'Just released from prison, Jake Blues puts his old band back together with his brother Elwood to save the Catholic home where they were raised.', 133, '/b0hq1d2d7FIvRGNLewKLm79JNTK.jpg', '/bk2fTuIhQIvdAA3RbnrnvLvuaTc.jpg', 'zaCGMiFRJEA'),
    (533, 'Cheese-loving eccentric Wallace and his cunning canine pal Gromit run a business ridding the town of garden pests. Using only humane methods, which turns their home into a halfway house for evicted vermin, the pair stumble upon a mystery involving a voracious vegetarian monster that threatens to ruin the annual veggie-growing contest.', 85, '/cMQ2lNd7sBe6PCf6zF5QxrKzbRG.jpg', '/Aqvtwgu1G4eEwIf8nSIxiCN5ewC.jpg', 'BXYNHHj4KDw'),
    (534, 'All grown up in post-apocalyptic 2018, John Connor must lead the resistance of humans against the increasingly dominating militaristic robots. But when Marcus Wright appears, his existence confuses the mission as Connor tries to determine whether Wright has come from the future or the past -- and whether he''s friend or foe.', 115, '/gw6JhlekZgtKUFlDTezq3j5JEPK.jpg', '/uifaXfJxjTMeNttw5u04nHx1G5w.jpg', 'dayIedrLq_U'),
    (539, 'When larcenous real estate clerk Marion Crane goes on the lam with a wad of cash and hopes of starting a new life, she ends up at the notorious Bates Motel, where manager Norman Bates cares for his housebound mother.', 109, '/yz4QVqPx3h1hD1DfqqQkCq3rmxW.jpg', '/mufF1aYvwdpKerhq5R1YrVcbJLY.jpg', 'D90QhegiVvo'),
    (544, 'For Ted, prom night went about as bad as it’s possible for any night to go. Thirteen years later, he finally gets another chance with his old prom date, only to run up against other suitors including the sleazy detective he hired to find her.', 120, '/slJD1Dvnsf15LoeqhERsyzisAdn.jpg', '/egJQ3nIon5fT8wyXcKRHzvmtZpD.jpg', '503D8hOfE_8'),
    (550, 'A ticking-time-bomb insomniac and a slippery soap salesman channel primal male aggression into a shocking new form of therapy. Their concept catches on, with underground "fight clubs" forming in every town, until an eccentric gets in the way and ignites an out-of-control spiral toward oblivion.', 139, '/jSziioSwPVrOy9Yow3XhWIBDjq1.jpg', '/c6OLXfKAk5BKeR6broC8pYiCquX.jpg', 'dfeUzm6KF4g'),
    (557, 'After being bitten by a genetically altered spider at Oscorp, nerdy but endearing high school student Peter Parker is endowed with amazing powers to become the superhero known as Spider-Man.', 121, '/or6XJBVpcEbIkma0V9zshnbEtx4.jpg', '/jHxCeXnSchAuwHnmVatTgqMYdX8.jpg', 't06RUxPbp_c'),
    (558, 'Peter Parker is going through a major identity crisis. Burned out from being Spider-Man, he decides to shelve his superhero alter ego, which leaves the city suffering in the wake of carnage left by the evil Doc Ock. In the meantime, Parker still can''t act on his feelings for Mary Jane Watson, a girl he''s loved since childhood. A certain anger begins to brew in his best friend Harry Osborn as well...', 127, '/aGuvNAaaZuWXYQQ6N2v7DeuP6mB.jpg', '/6al048Lat3eLVQOuKtc9h6Tu94d.jpg', 'CA5vsCnLm34'),
    (559, 'Peter Parker finally has the girl of his dreams, Mary Jane Watson, and New York City is in the throes of Spider-mania! But when a strange alien symbiote turns Spider-Man''s suit black, his darkest demons come to light changing Spider-Man inside as well as out. Spider-Man is in for the fight of his life against a lethal mix of villains - the deadly Sandman, Venom, and the New Goblin - as well as the enemy within himself.', 139, '/qFmwhVUoUSXjkKRmca5yGDEXBIj.jpg', '/FfAU0PUs8AJkMU2VbkVNFtRXR4.jpg', 'e5wUilOeOmg'),
    (561, 'John Constantine has literally been to Hell and back. When he teams up with a policewoman to solve the mysterious suicide of her twin sister, their investigation takes them through the world of demons and angels that exists beneath the landscape of contemporary Los Angeles.', 121, '/vPYgvd2MwHlxTamAOjwVQp4qs1W.jpg', '/26OvB15pqk3eiKJG8LrXDVzO7Mw.jpg', '819JCbGfZpg'),
    (562, 'High above the city of L.A. a team of terrorists has seized a building, taken hostages, and declared war. One man has manages to escape... An off-duty cop hiding somewhere inside. He''s alone, tired... and the only chance anyone has got.', 132, '/7Bjd8kfmDSOzpmhySpEhkUyK2oH.jpg', '/bvk2AAH64lP2YZs02Q3jskfHT8j.jpg', '4Wi28Vsi_ZU'),
    (563, 'Set in the future, the story follows a young soldier named Johnny Rico and his exploits in the Mobile Infantry. Rico''s military career progresses from recruit to non-commissioned officer and finally to officer against the backdrop of an interstellar war between mankind and an arachnoid species known as "the Bugs."', 129, '/cxCmv23O7p3hyHwqoktHYkZcGsY.jpg', '/7iEfnj3rfyunky6BzvnlwqfoEF0.jpg', 'zPYuV_jGk7M'),
    (564, 'Dashing legionnaire Rick O''Connell stumbles upon the hidden ruins of Hamunaptra while in the midst of a battle to claim the area in 1920s Egypt. It has been over three thousand years since former High Priest Imhotep suffered a fate worse than death as a punishment for a forbidden love—along with a curse that guarantees eternal doom upon the world if he is ever awoken.', 124, '/yhIsVvcUm7QxzLfT6HW2wLf5ajY.jpg', '/8zLS8p1tRyWFLRFfmgQq0j5WE6z.jpg', 'OGOBz4t7OXs'),
    (565, 'Journalist Rachel Keller investigates a strange videotape that may be behind the untimely deaths of four teenagers. There is an urban legend about this tape: the viewer will die seven days after watching it. Rachel tracks down the video... and watches it. Now she has just seven days to unravel the mystery of the Ring in order to save herself and her son.', 115, '/AeRpUynJKDpJveklBJipOYrVxCS.jpg', '/6tuNQ16hC4Qp7wjTweKzUnnLBkI.jpg', 'CG7BAY6_hsw'),
    (567, 'A wheelchair-bound photographer spies on his neighbors from his apartment window and becomes convinced one of them has committed murder.', 113, '/ILVF0eJxHMddjxeQhswFtpMtqx.jpg', '/5bN06p5OwRUEqcfrtNs5egV16yb.jpg', 'iZOTTxwzyMU'),
    (568, 'The true story of technical troubles that scuttle the Apollo 13 lunar mission in 1970, risking the lives of astronaut Jim Lovell and his crew, with the failed journey turning into a thrilling saga of heroism. Drifting more than 200,000 miles from Earth, the astronauts work furiously with the ground crew to avert tragedy.', 140, '/tVeKscCm2fY1xDXZk8PgnZ87h9S.jpg', '/n0FDJI9c0uWiZwm8wgXVjaMBn96.jpg', 'B1KJ9XeZuxA'),
    (571, 'Thousands of birds flock into a seaside town and terrorize the residents in a series of deadly attacks.', 119, '/eClg8QPg8mwB6INIC4pyR5pAbDr.jpg', '/98qofsLB8HwPsmlq0HczQTt8BcS.jpg', 'lCxR7dlavwg'),
    (576, 'An aging group of outlaws look for one last big score as the "traditional" American West is disappearing around them.', 145, '/8j9yEC3xjy1PJDSizIbaxcHaSph.jpg', '/nkgWcfOeQnVnxak5xCKvkRDLt5H.jpg', 'kdy0t_8mQBw'),
    (578, 'When the seaside community of Amity finds itself under attack by a dangerous great white shark, the town''s chief of police, a young marine biologist, and a grizzled shark hunter embark on a desperate quest to kill the beast before it strikes again.', 124, '/lxM6kqilAdpdhqUl2biYp5frUxE.jpg', '/i1yf91svRHX45l9BXL8rVFzLoPH.jpg', 'N9hzLQUGr34'),
    (581, 'Wounded Civil War soldier John Dunbar tries to commit suicide—and becomes a hero instead. As a reward, he''s assigned to his dream post, a remote junction on the Western frontier, and soon makes unlikely friends with the local Sioux tribe.', 181, '/hw0ZEHAaTqTxSXGVwUFX7uvanSA.jpg', '/ywWva4trKw7f3wtbz81Fe3FnrtC.jpg', 'N4gr-uXUg1M'),
    (583, 'Brian Cohen is an average young Jewish man, but through a series of ridiculous events, he gains a reputation as the Messiah. When he''s not dodging his followers or being scolded by his shrill mother, the hapless Brian has to contend with the pompous Pontius Pilate and acronym-obsessed members of a separatist movement. Rife with Monty Python''s signature absurdity, the tale finds Brian''s life paralleling Biblical lore, albeit with many more laughs.', 94, '/lSSA64WF0M0BXnjwr2quMh6shCl.jpg', '/lOrM3OQhHlzEkpF7Ih3GghecrA8.jpg', 'tK4Qb51ftd4'),
    (584, 'It''s a major double-cross when former police officer Brian O''Conner teams up with his ex-con buddy Roman Pearce to transport a shipment of "dirty" money for shady Miami-based import-export dealer Carter Verone. But the guys are actually working with undercover agent Monica Fuentes to bring Verone down.', 108, '/6nDZExrDKIXvSAghsFKVFRVJuSf.jpg', '/90ooE5SbUEO0OVJHewNO7pgySb6.jpg', 'fDooSsgINLQ'),
    (585, 'Lovable Sulley and his wisecracking sidekick Mike Wazowski are the top scare team at Monsters, Inc., the scream-processing factory in Monstropolis. When a little girl named Boo wanders into their world, it''s the monsters who are scared silly, and it''s up to Sulley and Mike to keep her out of sight and get her back home.', 92, '/wFSpyMsp7H0ttERbxY7Trlv8xry.jpg', '/c7VbRPlev1bRfKvTxr98erw5T7B.jpg', '6tCxnHCqqxg'),
    (587, 'Throughout his life Edward Bloom has always been a man of big appetites, enormous passions and tall tales. In his later years, he remains a huge mystery to his son, William. Now, to get to know the real man, Will begins piecing together a true picture of his father from flashbacks of his amazing adventures.', 125, '/tjK063yCgaBAluVU72rZ6PKPH2l.jpg', '/bLqUd0tBvKezDr9MEla7k34i3rp.jpg', 'T6M-jwyz28U'),
    (588, 'Rose, a desperate mother, takes her adopted daughter, Sharon, to the town of Silent Hill in an attempt to cure her of her ailment. After a violent car crash, Sharon disappears, and Rose embarks on a horrific journey to get her back and begins to uncover the truth behind the apocalyptic disaster that burned the town 30 years earlier.', 125, '/6cZmJOZ6jpLF4jflBZqGCa2f4IP.jpg', '/xQKUQC0e32rkbeiwz4UARJMx2Di.jpg', '1mfnhu8sO5k'),
    (591, 'A murder in Paris’ Louvre Museum and cryptic clues in some of Leonardo da Vinci’s most famous paintings lead to the discovery of a religious mystery. For 2,000 years a secret society closely guards information that — should it come to light — could rock the very foundations of Christianity.', 149, '/9ejKfNk0LBhSI9AahH4f9NJNZNM.jpg', '/4NsQl44oXVMiuIM9t7ZsVgYzOkv.jpg', 'Xy6aVei3Mnk'),
    (594, 'An Eastern European tourist unexpectedly finds himself stranded in JFK airport, and must take up temporary residence there.', 128, '/cPB3ZMM4UdsSAhNdS4c7ps5nypY.jpg', '/zywtNiaZ9r7azrcNdl2j0jOgrkw.jpg', 'GZjC9dAvWuU'),
    (595, 'Scout Finch, 6, and her older brother Jem live in sleepy Maycomb, Alabama, spending much of their time with their friend Dill and spying on their reclusive and mysterious neighbor, Boo Radley. When Atticus, their widowed father and a respected lawyer, defends a black man named Tom Robinson against fabricated rape charges, the trial and tangent events expose the children to evils of racism and stereotyping.', 129, '/gZycFUMLx2110dzK3nBNai7gfpM.jpg', '/wYRpVySPCC7wA28p54yAaoMT478.jpg', '4-CrrtYjrbM'),
    (597, '101-year-old Rose DeWitt Bukater tells the story of her life aboard the Titanic, 84 years later. A young Rose boards the ship with her mother and fiancé. Meanwhile, Jack Dawson and Fabrizio De Rossi win third-class tickets aboard the ship. Rose tells the whole story from Titanic''s departure through to its death—on its first and last voyage—on April 15, 1912.', 194, '/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg', '/sCzcYW9h55WcesOqA12cgEr9Exw.jpg', 'wO44qBPBG4c'),
    (598, 'In the poverty-stricken favelas of Rio de Janeiro in the 1970s, two young men choose different paths. Rocket is a budding photographer who documents the increasing drug-related violence of his neighborhood, while José “Zé” Pequeno is an ambitious drug dealer diving into a dangerous life of crime.', 129, '/k7eYdWvhYQyRQoU2TB2A2Xu2TfD.jpg', '/uvitbjFU4JqvMwIkMWHp69bmUzG.jpg', 'dcUOO4Itgmw'),
    (600, 'A pragmatic U.S. Marine observes the dehumanizing effects the U.S.-Vietnam War has on his fellow recruits from their brutal boot camp training to the bloody street fighting in Hue.', 117, '/kMKyx1k8hWWscYFnPbnxxN4Eqo4.jpg', '/3k2TRmqMjgt7tcwkYwZQdctnty3.jpg', 'n2i917l5RFc'),
    (601, 'An alien is left behind on Earth and saved by the 10-year-old Elliott who decides to keep him hidden in his home. While a task force hunts for the extra-terrestrial, Elliott, his brother, and his little sister Gertie form an emotional bond with their new friend, and try to help him find his way home.', 115, '/an0nD6uq6byfxXCfk6lQBzdL2J1.jpg', '/mXLVA0YL6tcXi6SJSuAh9ONXFj5.jpg', 'NsvdZ_z56c0'),
    (602, 'Strange phenomena surface around the globe. The skies ignite. Terror races through the world''s major cities. As these extraordinary events unfold, it becomes increasingly clear that a force of incredible magnitude has arrived. Its mission: total annihilation over the Fourth of July weekend. The last hope to stop the destruction is an unlikely group of people united by fate and unimaginable circumstances.', 145, '/p0BPQGSPoSa8Ml0DAf2mB2kCU0R.jpg', '/kFI1oF6KVnLEbUT7yLIbKXeyvu.jpg', 'B1E7h3SeMDk'),
    (603, 'Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.', 136, '/dXNAPwY7VrqMAo51EKhhCJfaGb5.jpg', '/tlm8UkiQsitc8rSuIAscQDCnP8d.jpg', 'FVI84Dfx2-I'),
    (604, 'The Resistance builds in numbers as humans are freed from the Matrix and brought to the city of Zion. Neo discovers his superpowers, including the ability to see the code inside the Matrix. With machine sentinels digging to Zion in 72 hours, Neo, Morpheus and Trinity must find the Keymaker to ultimately reach the Source.', 138, '/8xEVAe84zlL9rkfYT6dZXero4KK.jpg', '/ihOJcrorpDQtHTzIOrobbOhpJsj.jpg', 'zmYE3tg26Qc'),
    (605, 'The human city of Zion defends itself against the massive invasion of the machines as Neo fights to end the war at another front while also opposing the rogue Agent Smith.', 129, '/qEWiBXJGXK28jGBAm8oFKKTB0WD.jpg', '/533xAMhhVyjTy8hwMUFEt5TuDfR.jpg', 'hMbexEPAOQI'),
    (607, 'After a police chase with an otherworldly being, a New York City cop is recruited as an agent in a top-secret organization established to monitor and police alien activity on Earth: the Men in Black. Agent K and new recruit Agent J find themselves in the middle of a deadly plot by an intergalactic terrorist who has arrived on Earth to assassinate two ambassadors from opposing galaxies.', 98, '/uLOmOF5IzWoyrgIF5MfUnh5pa1X.jpg', '/aJMhYOP80cVBtq5ku3uyqASF3Ol.jpg', 'HYUd7AOw_lk'),
    (608, 'Kay and Jay reunite to provide our best, last and only line of defense against a sinister seductress who levels the toughest challenge yet to the MIB''s untarnished mission statement – protecting Earth from the scum of the universe. It''s been four years since the alien-seeking agents averted an intergalactic disaster of epic proportions. Now it''s a race against the clock as Jay must convince Kay – who not only has absolutely no memory of his time spent with the MIB, but is also the only living person left with the expertise to save the galaxy – to reunite with the MIB before the earth submits to ultimate destruction.', 88, '/enA22EPyzc2WQ1VVyY7zxresQQr.jpg', '/o1l6OCqA3pYDZHIc5L1s7CEzCMv.jpg', 'DMHlNR6x2Sw'),
    (612, 'During the 1972 Olympic Games in Munich, eleven Israeli athletes are taken hostage and murdered by a Palestinian terrorist group known as Black September. In retaliation, the Israeli government recruits a group of Mossad agents to track down and execute those responsible for the attack.', 164, '/iUekaw96QLInZpsNwRTlRKrZgwm.jpg', '/titl6uMe5u974sLAA2Zy1kFi4sC.jpg', 'OuT_uh0CAf8'),
    (616, 'Nathan Algren is an American hired to instruct the Japanese army in the ways of modern warfare, which finds him learning to respect the samurai and the honorable principles that rule them. Pressed to destroy the samurai''s way of life in the name of modernization and open trade, Algren decides to become an ultimate warrior himself and to fight for their right to exist.', 154, '/a8jmJPs5eZBARmnuEEvZwbjwyz4.jpg', '/lm15lu2jt3I3Syxsb90UJzUzMRV.jpg', 'QZpQrc0R6J0'),
    (620, 'After losing their university jobs, three parapsychologists start a ghost-catching business in New York City and uncover a supernatural threat that could destroy the world.', 105, '/7E8nLijS9AwwUEPu2oFYOVKhdFA.jpg', '/c6yfABGVKuB5cjoOwdX4AJMlzUz.jpg', 'msq0hZSgZdM'),
    (621, 'Australian good girl Sandy and greaser Danny fell in love over the summer. But when they unexpectedly discover they''re now in the same high school, will they be able to rekindle their romance despite their eccentric friends?', 110, '/2rM7fQKpb7cs1Iq7IBqub9LFDzJ.jpg', '/2SRJMIoJzABzgyGw01U6VbQbvJD.jpg', 'THd96gHV7Tg'),
    (624, 'Wyatt and Billy, two Harley-riding hippies, complete a drug deal in Southern California and decide to travel cross-country in search of spiritual truth.', 96, '/3H3vwPGX6EbBRffIVHp3eHHcjka.jpg', '/qvTmYyYsv71qTq5syAq24k1kGk.jpg', 'IlfpTppsR0U'),
    (627, 'Heroin addict Mark Renton stumbles through bad ideas and sobriety attempts with his unreliable friends --Sick Boy, Begbie, Spud and Tommy. He also has an underage girlfriend, Diane, along for the ride. After cleaning up and moving from Edinburgh to London, Mark finds he can''t escape the life he left behind as Begbie and Sick Boy come knocking.', 94, '/1jUC02qsqS2NxBMFarbIhcQtazV.jpg', '/Aw0z8bUhGljT0ots6udf1MTLEMi.jpg', 'bKrbNruyFVE'),
    (628, 'A vampire relates his epic life story of love, betrayal, loneliness, and dark hunger to an over-curious reporter.', 123, '/t7NU8IcmcNBrlunCxiycX9JV7Rp.jpg', '/6cwkM6dkWU4F9YM0JCIqLDK2Aue.jpg', 'qmFYu8x46VY'),
    (629, 'The lone survivor of an explosive heist gone wrong recounts for interrogators the events that began with five disparate criminals assembled for a police lineup - with alleged criminal mastermind Keyser Soze at the center of it all.', 106, '/99X2SgyFunJFXGAYnDv3sb9pnUD.jpg', '/hy0Hx9fMPk2fmw26Li60z1S2giU.jpg', 'jM3jrHGAsIE'),
    (630, 'Young Dorothy finds herself in a magical world where she makes friends with a lion, a scarecrow and a tin man as they make their way along the yellow brick road to talk with the Wizard and ask for the things they miss most in their lives. The Wicked Witch of the West is the only thing that could stop them.', 102, '/uCC3j4pV9eOZwzDUWp2ilbcTf1f.jpg', '/g1OvTd1eF346vmx8qsJnjaiooZ6.jpg', 'b_A2twyZevo'),
    (634, 'Bridget Jones is an average woman struggling against expectations. As a New Year''s resolution, Bridget decides to take control of her life, starting by keeping a diary in which she will always tell the complete truth. Her charming boss takes an interest in her, and she cannot stop running into a rather disagreeable acquaintance whom Bridget cannot help finding quietly attractive.', 97, '/olMTi7uCaec9Yr3Ar07D2SIja1G.jpg', '/9rSpxsMhG1FnFtUDdvSAXdtLtb3.jpg', 'xjlKnDWZYzc'),
    (635, 'A down-and-out Brooklyn detective is hired to track down a singer on an odyssey that will take him through the desperate streets of Harlem, the smoke-filled jazz clubs of New Orleans, and the swamps of Louisiana and its seedy underworld of voodoo.', 113, '/h5v3wjJQNB7q2RntEnKDLhKtTFE.jpg', '/viDonz5uLmengw9RUAh3Rf65dQG.jpg', 'oLNHY7x055E'),
    (637, 'A touching story of an Italian book seller of Jewish ancestry who lives in his own little fairy tale. His creative and happy life would come to an abrupt halt when his entire family is deported to a concentration camp during World War II. While locked up he tries to convince his son that the whole thing is just a game.', 116, '/74hLDKjD5aGYOotO6esUVaeISa2.jpg', '/6aNKD81RHR1DqUUa8kOZ1TBY1Lp.jpg', 'pAYEQP8gx3w'),
    (638, 'A tormented jazz musician finds himself lost in an enigmatic story involving murder, surveillance, gangsters, doppelgängers, and an impossible transformation inside a prison cell.', 134, '/5POhfNeFPIi4VUNwCTaK85sh98r.jpg', '/hGnJhGSeyWlerHcLNnD06sbX5wU.jpg', ''),
    (639, 'Sex always gets in the way of friendships between men and women. At least, that''s what Harry Burns believes. So when Harry meets Sally Albright and a deep friendship blossoms between them, Harry''s determined not to let his attraction to Sally destroy it. But when a night of weakness ends in a morning of panic, can the pair avoid succumbing to Harry''s fears by remaining friends and admitting they just might be the perfect match for each other?', 96, '/rFOiFUhTMtDetqCGClC9PIgnC1P.jpg', '/dbdegCWeD4iK5LXxSBjGdIRsVXS.jpg', 'Lv8W7PPpkdo'),
    (640, 'A true story about Frank Abagnale Jr. who, before his 19th birthday, successfully conned millions of dollars worth of checks as a Pan Am pilot, doctor, and legal prosecutor. An FBI agent makes it his mission to put him behind bars. But Frank not only eludes capture, he revels in the pursuit.', 141, '/ctjEj2xM32OvBXCq8zAdK3ZrsAj.jpg', '/eS3xZQ1C8lt6mm4K5lTmjbYn2HE.jpg', '71rDQ7z4eFg'),
    (641, 'The drug-induced utopias of four Coney Island residents are shattered when their addictions run deep.', 102, '/9BTwsLaMVHOGFlmsSlx5QYCaXb.jpg', '/fAGYRJCujRBMw7TCuTp893eSG8e.jpg', 'NEKjZSTo0Uk'),
    (642, 'As the west rapidly becomes civilized, a pair of outlaws in 1890s Wyoming find themselves pursued by a posse and decide to flee to South America in hopes of evading the law.', 111, '/gFmmykF1Ym3OGzENo50nZQaD1dx.jpg', '/C6jcUqld8M6hZQmzBxgwHuQ4qT.jpg', 'YdJW2UxvSFQ'),
    (644, 'David, a robotic boy—the first of his kind programmed to love—is adopted as a test case by a Cybertronics employee and his wife. Though he gradually becomes their child, a series of unexpected circumstances make this life impossible for David.', 146, '/wnUAcUrMRGPPZUDroLeZhSjLkuu.jpg', '/n7p6UTAZtkeoHkwCO42BEQaMFJY.jpg', 'vzviK8IibAY'),
    (646, 'Agent 007 battles mysterious Dr. No, a scientific genius bent on destroying the U.S. space program. As the countdown to disaster begins, Bond must go to Jamaica, where he encounters beautiful Honey Ryder, to confront a megalomaniacal villain in his massive island headquarters.', 110, '/9zCOLJmLNst0sCPZlkW1IRoH65E.jpg', '/srgq7bzZsuDw7NoGXdazRXp7Hl6.jpg', 'h7FJDAH8Nn0'),
    (652, 'In year 1250 B.C. during the late Bronze age, two emerging nations begin to clash. Paris, the Trojan prince, convinces Helen, Queen of Sparta, to leave her husband Menelaus, and sail with him back to Troy. After Menelaus finds out that his wife was taken by the Trojans, he asks his brother Agamemnon to help him get her back. Agamemnon sees this as an opportunity for power. They set off with 1,000 ships holding 50,000 Greeks to Troy.', 163, '/a07wLy4ONfpsjnBqMwhlWTJTcm.jpg', '/ZPcC5hJh21QiW0jmhMQhZeSoGu.jpg', 'P8xLgg-MNKw'),
    (657, 'Agent 007 is back in the second installment of the James Bond series, this time battling a secret crime organization known as SPECTRE. Russians Rosa Klebb and Kronsteen are out to snatch a decoding device known as the Lektor, using the ravishing Tatiana to lure Bond into helping them. Bond willingly travels to meet Tatiana in Istanbul, where he must rely on his wits to escape with his life in a series of deadly encounters with the enemy.', 115, '/zx4V17FP8oclNvOpTgs2iCCtiYk.jpg', '/8JMiQa0OqsCYvbNUrQIrMzwV7g2.jpg', 't9AeIdMQqR8'),
    (658, 'Special agent 007 comes face to face with one of the most notorious villains of all time, and now he must outwit and outgun the powerful tycoon to prevent him from cashing in on a devious scheme to raid Fort Knox—and obliterate the world''s economy.', 110, '/aKNFzaqQgPzsGXnsMc4kJH5hFIV.jpg', '/mM4WeXqJd2tu1gCF5GYyAZf2Npl.jpg', 'xI4vbUvezLU'),
    (660, 'A criminal organization has obtained two nuclear bombs and are asking for a 100 million pound ransom in the form of diamonds in seven days or they will use the weapons. The secret service sends James Bond to the Bahamas to once again save the world.', 130, '/wCc4qllaTDsQN8zgGkAgQrKO6N9.jpg', '/7DLCXCQx52YLle1qTokrjROTwVV.jpg', '7JowkFmI1Fo'),
    (663, 'Despite Jigsaw''s death, and in order to save the lives of two of his colleagues, Lieutenant Rigg is forced to take part in a new game, which promises to test him to the limit.', 93, '/ku1QdCXOU4ckz3zxLLlis8MIJVm.jpg', '/3lrNJ5jNqKq9UpQrXo8FNFzyoE4.jpg', 'OxwdZMMymqY'),
    (664, 'An unprecedented series of violent tornadoes is sweeping across Oklahoma. Tornado chasers, headed by Dr. Jo Harding, attempt to release a groundbreaking device that will allow them to track them and create a more advanced warning system. They are joined by Jo''s soon to be ex-husband Bill, a former tornado chaser himself, and his girlfriend Melissa.', 113, '/d4ie3f6QTvNw40V770Uzo87SDZn.jpg', '/5oCAo7LFj2x0yByfi5JYirGnK8I.jpg', 'beHzfQPaTaw'),
    (665, 'In ancient Judea, a Jewish aristocrat opposing Roman occupation of his homeland reunites with his childhood friend, now a Roman commander — setting in motion a saga of betrayal, adventure, tragedy, revenge, and faith.', 212, '/m4WQ1dBIrEIHZNCoAjdpxwSKWyH.jpg', '/nk5gq5rNLBJiHvNGMRT6I9VRQX7.jpg', 'f2y1gDeZ230'),
    (667, 'A mysterious spacecraft captures Russian and American space capsules and brings the two superpowers to the brink of war. James Bond investigates the case in Japan and comes face to face with his archenemy Blofeld.', 117, '/fdRbvRcEXcf2rC4ghLFZzCWPSmB.jpg', '/cpZAXIYA0lkZMpAt7d1MmH8ojNV.jpg', 'gMXuLObYidM'),
    (668, 'With the help of Marc-Ange Draco, head of the Unione Corse crime syndicate, and Draco''s troubled daughter Tracy, James Bond tracks his archnemesis, Ernst Stravro Blofeld, to a mountaintop retreat in the Swiss Alps, where he is training an army of beautiful, lethal women.', 142, '/yVzJLLhBwuWJBR9BYEMurShu2WT.jpg', '/1kdyLiE2Mqt7cxnivdPX3qckvfW.jpg', 'U_-nD5r8dc0'),
    (670, 'With no clue how he came to be imprisoned, drugged and tortured for 15 years, a desperate man seeks revenge on his captors.', 120, '/pWDtjs568ZfOTMbURQBYuT4Qxka.jpg', '/rwf5SUTiEsmfkXAgy15R0UtJUtv.jpg', 'tAaBkFChaRg'),
    (671, 'Harry Potter has lived under the stairs at his aunt and uncle''s house his whole life. But on his 11th birthday, he learns he''s a powerful wizard—with a place waiting for him at the Hogwarts School of Witchcraft and Wizardry. As he learns to harness his newfound powers with the help of the school''s kindly headmaster, Harry uncovers the truth about his parents'' deaths—and about the villain who''s to blame.', 152, '/wuMc08IPKEatf9rnMNXvIDxqP4W.jpg', '/5jkE2SzR5uR2egEb1rRhF22JyWN.jpg', 'l91Km49W9qI'),
    (672, 'Cars fly, trees fight back, and a mysterious house-elf comes to warn Harry Potter at the start of his second year at Hogwarts. Adventure and danger await when bloody writing on a wall announces: The Chamber Of Secrets Has Been Opened. To save Hogwarts will require all of Harry, Ron and Hermione''s magical abilities and courage.', 161, '/sdEOH0992YZ0QSxgXNIGLq1ToUi.jpg', '/7tbeoSTWW2cWPecjQo9fcdf0Hzv.jpg', 'nE11U5iBnH0'),
    (673, 'Year three at Hogwarts means new fun and new challenges as Harry learns the delicate art of approaching a Hippogriff, transforming shape-shifting Boggarts into hilarity and even turning back time. But the term also brings danger: soul-sucking Dementors hover over the school, an ally of the accursed He-Who-Cannot-Be-Named lurks within the castle walls, and fearsome wizard Sirius Black escapes Azkaban. And Harry will confront them all.', 141, '/aWxwnYoe8p2d2fcxOqtvAtJ72Rw.jpg', '/vbk5CfaAHOjQPSAcYm6AoRRz2Af.jpg', 'VwErvYgoH70'),
    (674, 'After his name emerges from the Goblet of Fire, Harry Potter becomes a competitor in a grueling battle for glory among three wizarding schools in the Triwizard Tournament. But if Harry never submitted his name for the Tournament, then who did? Nevertheless, Harry must confront a deadly dragon, fierce water monsters, and an enchanted maze—only to find himself in the cruel grasp of He Who Must Not Be Named.', 157, '/fECBtHlr0RB3foNHDiCBXeg9Bv9.jpg', '/8f9dnOtpArDrOMEylpSN9Sc6fuz.jpg', '4xkFJgcCQRE'),
    (675, 'Returning for his fifth year at Hogwarts, Harry is stunned to find that his warnings about the return of Lord Voldemort have been ignored. Left with no choice, Harry takes matters into his own hands, training a small group of motivated students to defend themselves against the Dark Arts.', 138, '/5aOyriWkPec0zUDxmHFP9qMmBaj.jpg', '/pkxPkHOPJjOvzfQOclANEBT8OfK.jpg', '47PHbQTmw5g'),
    (676, 'The lifelong friendship between Rafe McCawley and Danny Walker is put to the ultimate test when the two ace fighter pilots become entangled in a love triangle with beautiful Naval nurse Evelyn Johnson. But the rivalry between the friends-turned-foes is immediately put on hold when they find themselves at the center of Japan''s devastating attack on Pearl Harbor on Dec. 7, 1941.', 183, '/giWL3kIA5E67VUTWY1PkfHgyZ1B.jpg', '/zv1xOEQzebKyku349qDZ085FZlO.jpg', 'zf3KAiimeUg'),
    (679, 'Ripley, the sole survivor of the Nostromo''s deadly encounter with the monstrous Alien, returns to Earth after drifting through space in hypersleep for 57 years. Although her story is initially met with skepticism, she agrees to accompany a team of Colonial Marines back to LV-426.', 137, '/r1x5JGpyqZU8PYhbs4UcrO1Xb6x.jpg', '/4kix6fAblJIH6eMs0Ku2loyZJXK.jpg', '8OxirbuHsBA'),
    (680, 'A burger-loving hit man, his philosophical partner, a drug-addled gangster''s moll and a washed-up boxer converge in this sprawling, comedic crime caper. Their adventures unfurl in three stories that ingeniously trip back and forth in time.', 154, '/vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg', '/suaEOtk1N1sgg2MTM7oZd2cfVp3.jpg', 'tGpTpVyI_OQ'),
    (682, 'Cool government operative James Bond searches for a stolen invention that can turn the sun''s heat into a destructive weapon. He soon crosses paths with the menacing Francisco Scaramanga, a hitman so skilled he has a seven-figure working fee. Bond then joins forces with the swimsuit-clad Mary Goodnight, and together they track Scaramanga to a Thai tropical isle hideout where the killer-for-hire lures the slick spy into a deadly maze for a final duel.', 125, '/xVkbKwGnBVNQ122GN5bCTMyPbWz.jpg', '/vcj47nTm1fDlkxUwDb2GgYbKDDW.jpg', 'QUvKxtSrHJs'),
    (686, 'A radio astronomer receives the first extraterrestrial radio signal ever picked up on Earth. As the world powers scramble to decipher the message and decide upon a course of action, she must make some difficult decisions between her beliefs, the truth, and reality.', 150, '/bCpMIywuNZeWt3i5UMLEIc0VSwM.jpg', '/aOzTr5FxlS06ppd5a5KaqKwOPgx.jpg', 's3hcz8OCd-Q'),
    (688, 'Photographer Robert Kincaid wanders into the life of housewife Francesca Johnson for four days in the 1960s.', 135, '/aCBrhOQjhG397GLkEZ49zReQEKX.jpg', '/70N7NT8JPiOD2gr9BzRX8uXwcng.jpg', 'ZoJJkAQV0Bg'),
    (693, 'Hard-to-crack ex-CIA man Jack Byrnes and his wife Dina head for the warmer climes of Florida to meet the parents of their son-in-law-to-be, Greg Focker. Unlike their happily matched offspring, the future in-laws find themselves in a situation of opposites that definitely do not attract.', 115, '/59fXm6N2x7QSbvt6BaBxTNBXGL8.jpg', '/porZOny3iVvs5LK0osW1b52wWik.jpg', 'iusZySaeI10'),
    (694, 'Jack Torrance accepts a caretaker job at the Overlook Hotel, where he, along with his wife Wendy and their son Danny, must live isolated from the rest of the world for the winter. But they aren''t prepared for the madness that lurks within.', 144, '/uAR0AWqhQL1hQa69UDEbb2rE5Wx.jpg', '/AdKA2F1SzYPhSZdEbjH1Zh75UVQ.jpg', 'jAE7dNurHR4'),
    (698, 'After Drax Industries'' Moonraker space shuttle is hijacked, secret agent James Bond is assigned to investigate, traveling to California to meet the company''s owner, the mysterious Hugo Drax. With the help of scientist Dr. Holly Goodhead, Bond soon uncovers Drax''s nefarious plans for humanity, all the while fending off an old nemesis, Jaws, and venturing to Venice, Rio, the Amazon...and even outer space.', 126, '/6LrJdXNmu5uHOVALZxVYd44Lva0.jpg', '/mrDC5DLx2wljt4HZGwgkmqlzfcF.jpg', 'qz7uoU7Xvjg'),
    (700, 'James Bond is sent to investigate after a fellow “00” agent is found dead with a priceless Fabergé egg. Bond follows the mystery and uncovers a smuggling scandal and a Russian General who wants to provoke a new World War.', 131, '/yoosZitM9igSk3Sd0sBXIhKlAh1.jpg', '/xTS1qCmhzH3vq7cuextO5vQA6eW.jpg', 'q1hLWZzgZvU'),
    (708, 'After a defecting Russian general reveals a plot to assassinate foreign spies, James Bond is assigned a secret mission to dispatch the new head of the KGB to prevent an escalation of tensions between the Soviet Union and the West.', 130, '/1oRlmWX9hewpn2B44wawBjHd7dx.jpg', '/ebaq0ecL1Tu39rIExfHwE4ToFl2.jpg', '2m7VT6zXCmE'),
    (710, 'When a powerful secret defense system is stolen, James Bond is assigned to stop a Russian crime syndicate from using it.', 130, '/z0ljRnNxIO7CRBhLEO0DvLgAFPR.jpg', '/fIWsCpYR9iGDMSbMTSAzy8L7Kg5.jpg', '8Zw8ylP4buA'),
    (744, 'For Lieutenant Pete ''Maverick'' Mitchell and his friend and co-pilot Nick ''Goose'' Bradshaw, being accepted into an elite training school for fighter pilots is a dream come true. But a tragedy, as well as personal demons, will threaten Pete''s dreams of becoming an ace pilot.', 110, '/xUuHj3CgmZQ9P2cMaqQs4J0d4Zc.jpg', '/dBgxEkWe17R0AJDAvAhpeVELQx2.jpg', 'Klc__shdj88'),
    (745, 'Following an unexpected tragedy, child psychologist Malcolm Crowe meets a nine year old boy named Cole Sear, who is hiding a dark secret.', 107, '/vOyfUXNFSnaTk7Vk5AjpsKTUWsu.jpg', '/6TjllWT3cGrPFyqDXurVZ3L8bBi.jpg', 'HXG4HTIlc1U'),
    (747, 'Shaun lives a supremely uneventful life, which revolves around his girlfriend, his mother, and, above all, his local pub. This gentle routine is threatened when the dead return to life and make strenuous attempts to snack on ordinary Londoners.', 99, '/dgXPhzNJH8HFTBjXPB177yNx6RI.jpg', '/wb34q3VgzHgL8frVMywrN3wXmqx.jpg', '_QuY93B2FS0'),
    (752, 'In a world in which Great Britain has become a fascist state, a masked vigilante known only as “V” conducts guerrilla warfare against the oppressive British government. When V rescues a young woman from the secret police, he finds in her an ally with whom he can continue his fight to free the people of Britain.', 132, '/1avD1JeaRiJX5M4ahPdZPypGoGN.jpg', '/sFEYsEfzTx7hhjetlNrme8B5OUo.jpg', 'krWn5ta9RG4'),
    (754, 'In order to foil a terrorist plot, an FBI agent undergoes facial transplant surgery and assumes the identity of a criminal mastermind. The plan turns sour when the criminal wakes up prematurely and seeks revenge.', 139, '/69Xzn8UdPbVnmqSChKz2RTpoNfB.jpg', '/tsSWHgaFlzzkp3o976juBZbmcs2.jpg', '3zebJ_NoduE'),
    (755, 'After kidnapping a father and his two kids, the Gecko brothers head south to a seedy Mexican bar to hide out in safety, unaware of its notorious clientele.', 108, '/sV3kIAmvJ9tPz4Lq5fuf9LLMxte.jpg', '/phiRQhfwZZeMMn3osvQUmGYmJbp.jpg', 'y-J9bBvO5dk'),
    (756, 'Walt Disney''s timeless masterpiece is an extravaganza of sight and sound! See the music come to life, hear the pictures burst into song and experience the excitement that is Fantasia over and over again.', 124, '/5m9njnidjR0syG2gpVPVgcEMB2X.jpg', '/lyzI5uFJC2E7sIYCCdaU0oZkDw2.jpg', 'eD8U083gQmY'),
    (762, 'King Arthur, accompanied by his squire, recruits his Knights of the Round Table, including Sir Bedevere the Wise, Sir Lancelot the Brave, Sir Robin the Not-Quite-So-Brave-As-Sir-Lancelot and Sir Galahad the Pure. On the way, Arthur battles the Black Knight who, despite having had all his limbs chopped off, insists he can still fight. They reach Camelot, but Arthur decides not  to enter, as "it is a silly place".', 91, '/7nTkHjETdGMYK1phHwDbPsrzbYl.jpg', '/1KgXxv6tHXOnakqYvMPvFwYKWiw.jpg', '4b52A3sKz-I'),
    (764, 'In 1979, a group of college students find a Sumerian Book of the Dead in an old wilderness cabin they''ve rented for a weekend getaway.', 85, '/54C1qdaiSijIU5NeNb4WsPJdNkG.jpg', '/onq6lsJLX8ay5iwxEbKX3qJKeO9.jpg', '0cQmKgV0cug'),
    (765, 'Ash Williams and his girlfriend Linda find a log cabin in the woods with a voice recording from an archeologist who had recorded himself reciting ancient chants from "The Book of the Dead." As they play the recording an evil power is unleashed taking over Linda''s body.', 84, '/4zqCKJVHUolGs6C5AZwAZqLWixW.jpg', '/j1CqN4ypo3lFJJA5C7mYJzBaXoL.jpg', 's7WNgzilRBw'),
    (766, 'Ash, a handsome, shotgun-toting, chainsaw-armed department store clerk, is time warped backwards into England''s Dark Ages, where he romances a beauty and faces legions of the undead.', 89, '/xsgTuAtR2zSH8Umg3jWZcZjlDpe.jpg', '/8WIufsaJgm7VWgAc5ALWdJ8v2kB.jpg', 'UHZQEtG8xYo'),
    (767, 'As Lord Voldemort tightens his grip on both the Muggle and wizarding worlds, Hogwarts is no longer a safe haven. Harry suspects perils may even lie within the castle, but Dumbledore is more intent upon preparing him for the final battle fast approaching. Even as the decisive showdown looms, romance blossoms for Harry, Ron, Hermione and their classmates. Love is in the air, but danger lies ahead and Hogwarts may never be the same again', 153, '/z7uo9zmQdQwU5ZJHFpv2Upl30i1.jpg', '/ze6Mx4QE5mQVXRYmG2flncqqle4.jpg', 'tAiy66Xrsz4'),
    (768, 'Frederick Abberline is an opium-huffing inspector from Scotland Yard who falls for one of Jack the Ripper''s prostitute targets in this Hughes brothers adaption of a graphic novel that posits the Ripper''s true identity.', 122, '/t2WpWM8nBO4sULXr2bDfNEt4qgr.jpg', '/bHKj3m3eLlU2wJQBlAs7wv6ZMBv.jpg', '7gJQRKQjvrU'),
    (769, 'The true story of Henry Hill, a half-Irish, half-Sicilian Brooklyn kid who is adopted by neighbourhood gangsters at an early age and climbs the ranks of a Mafia family under the guidance of Jimmy Conway.', 145, '/9OkCLM73MIU2CrKZbqiT8Ln1wY2.jpg', '/6qgSKYgkHLL0vAVbsqRfo8KmZgL.jpg', 'PTBRNXGQR9Q'),
    (770, 'The spoiled daughter of a Georgia plantation owner conducts a tumultuous romance with a cynical profiteer during the American Civil War and Reconstruction Era.', 238, '/lNz2Ow0wGCAvzckW7EOjE03KcYv.jpg', '/4FHcxMtVruMr7ltU2cItWssLjTP.jpg', 'h2oX0zQA67U'),
    (771, 'Eight-year-old Kevin McCallister makes the most of the situation after his family unwittingly leaves him behind when they go on Christmas vacation. When thieves try to break into his home, he puts up a fight like no other.', 103, '/onTSipZ8R3bliBdKfPtsDuHTdlL.jpg', '/ih2xVgeMS8R5WUetYE8Mr9hVTlB.jpg', 'dzdpqRGA1qc'),
    (772, 'Instead of flying to Florida with his folks, Kevin ends up alone in New York, where he gets a hotel room with his dad''s credit card—despite problems from a clerk and meddling bellboy. But when Kevin runs into his old nemeses, the Wet Bandits, he''s determined to foil their plans to rob a toy store on Christmas Eve.', 120, '/uuitWHpJwxD1wruFl2nZHIb4UGN.jpg', '/8fnYJPoXxwAN4valDLgz2whMGTH.jpg', 'k0kJieJ1k6k'),
    (773, 'A family loaded with quirky, colorful characters piles into an old van and road trips to California for little Olive to compete in a beauty pageant.', 102, '/niNdhTpPHSgw22tK0PLjQMV640v.jpg', '/twdtjJm31AExNx73DXaD4KRNU9c.jpg', 'oabGaaCLZ5g'),
    (782, 'Vincent is an all-too-human man who dares to defy a system obsessed with genetic perfection. He is an "In-Valid" who assumes the identity of a member of the genetic elite to pursue his goal of traveling into space with the Gattaca Aerospace Corporation.', 107, '/eSKr5Fl1MEC7zpAXaLWBWSBjgJq.jpg', '/hPsCR1ny6GnctJkWqeJwihTDD7T.jpg', 'NIIZ2P-fiyI'),
    (783, 'In the early years of the 20th century, Mohandas K. Gandhi, a British-trained lawyer, forsakes all worldly possessions to take up the cause of Indian independence. Faced with armed resistance from the British government, Gandhi adopts a policy of ''passive resistance'', endeavouring to win freedom for his people without resorting to bloodshed.', 192, '/rOXftt7SluxskrFrvU7qFJa5zeN.jpg', '/gum3tuO1zKHBdElSQPS08PJ1w67.jpg', 'vziq3CA_C30'),
    (786, 'In 1973, a precocious 15-year-old aspiring rock journalist lands a dream assignment from Rolling Stone to tour with a rising rock band, embarking on a coming-of-age journey as he discovers the exhilarating and heartbreaking realities behind rock stardom.', 124, '/3rrkyLYbgLj84AYvjhdcJot4JPx.jpg', '/AqLtFRKVX2G0ghMnMnQoSGan4pY.jpg', '4U07rtBNa2g'),
    (787, 'A husband and wife struggle to keep their marriage alive until they realize they are both secretly working as assassins. Now, their respective assignments require them to kill each other.', 120, '/kjD700RtyhveN3ZbOnSvUSne0Qj.jpg', '/wBPxAlZF6ITQ6T5BMmVuVjeduTe.jpg', 'TWB_icm5M38'),
    (788, 'Loving but irresponsible dad Daniel Hillard, estranged from his exasperated spouse, is crushed by a court order allowing only weekly visits with his kids. When Daniel learns his ex needs a housekeeper, he gets the job -- disguised as a British nanny. Soon he becomes not only his children''s best pal but the kind of parent he should have been from the start.', 125, '/ualFkVe5zYDphGuJv37byW2Suim.jpg', '/xAWx1UGc6LEMpao5FaNxgTNljay.jpg', 'NBZ2ioWBxD8'),
    (792, 'As a young and naive recruit in Vietnam, Chris Taylor faces a moral crisis when confronted with the horrors of war and the duality of man.', 120, '/m3mmFkPQKvPZq5exmh0bDuXlD9T.jpg', '/5hRvPi8z7XaGQJi1OZ3QKyJiAaA.jpg', 'R8weLPF4qBQ'),
    (793, 'The discovery of a severed human ear found in a field leads a young man on an investigation related to a beautiful, mysterious nightclub singer and a group of psychopathic criminals who have kidnapped her child.', 120, '/6v1zYh2FKOYVddY5pCQhd4PO9uX.jpg', '/s1CBwblInR0ZBIv59CSko2QdLD3.jpg', 'R9ZB7OldM6Y'),
    (794, 'Immediately after their miscarriage, the US diplomat Robert Thorn adopts the newborn Damien without the knowledge of his wife. Yet what he doesn’t know is that their new son is the son of the devil.', 111, '/kMBBlvqdfxnXkfEGugmMwvlBHnU.jpg', '/5sfbPsenSrbH8pzVMjEd0LUu50Y.jpg', 'mgjVPPVtnII'),
    (796, 'Slaking a thirst for dangerous games, Kathryn challenges her stepbrother, Sebastian, to deflower their headmaster''s daughter before the summer ends. If he succeeds, the prize is the chance to bed Kathryn. But if he loses, Kathryn will claim his most prized possession.', 97, '/76cCsRtQ5MJBAqoigojXsLXLJwh.jpg', '/m2QvGozzKz5ux74gKocn4kFTGz1.jpg', 'UzlKsS-IhEo'),
    (804, 'Overwhelmed by her suffocating schedule, touring European princess Ann takes off for a night while in Rome. When a sedative she took from her doctor kicks in, however, she falls asleep on a park bench and is found by an American reporter, Joe Bradley, who takes her back to his apartment for safety. At work the next morning, Joe finds out Ann''s regal identity and bets his editor he can get exclusive interview with her, but romance soon gets in the way.', 119, '/8lI9dmz1RH20FAqltkGelY1v4BE.jpg', '/gzRISGjiDMj4xqYE9ES2KNIXxpo.jpg', '2vm2FdHg7Io'),
    (807, 'Two homicide detectives are on a desperate hunt for a serial killer whose crimes are based on the "seven deadly sins" in this dark and haunting film that takes viewers from the tortured remains of one victim to the next. The seasoned Det. Somerset researches each sin in an effort to get inside the killer''s mind, while his novice partner, Mills, scoffs at his efforts to unravel the case.', 127, '/191nKfP0ehp3uIvWqgPbFmI4lv9.jpg', '/jwBs4djVIe9Kz3Vu9rsI9aEEKWU.jpg', 'KPOuJGkpblk'),
    (808, 'It ain''t easy bein'' green -- especially if you''re a likable (albeit smelly) ogre named Shrek. On a mission to retrieve a gorgeous princess from the clutches of a fire-breathing dragon, Shrek teams up with an unlikely compatriot -- a wisecracking donkey.', 90, '/zscUsmzDJFZjUY8f8BQqMSWlmNQ.jpg', '/2Biv1mSzaaxWOqvcnDZn4GcYEAb.jpg', 'ppDwfm6e498'),
    (809, 'Happily ever after never seemed so far far away when a trip to meet the in-laws turns into a hilariously twisted adventure for Shrek and Fiona. With the help of ever-faithful Donkey, Shrek takes on the potion-brewing Fairy Godmother, pompous Prince Charming, and infamous ogre-killer Puss In Boots.', 92, '/2yYP0PQjG8zVqturh1BAqu2Tixl.jpg', '/b33E34IywGC4NWYY3G1ck7uehNF.jpg', 'iuNghO1XsHI'),
    (810, 'After the King of Far Far Away dies, Shrek and Fiona are to succede. However, Shrek wants to return to his cozy swamp and live in peace and quiet, so when he finds out there is another heir to the throne, he and Donkey set off to bring him back to rule the kingdom.', 93, '/n4SexGGQzI26E269tfpa80MZaGV.jpg', '/wvXxKpFGXvQJRB0nvvfURhRD3C0.jpg', 'InR865IDDjU'),
    (812, 'In the boorish city of Agrabah, kind-hearted street urchin Aladdin and Princess Jasmine fall in love, although she can only marry a prince. He and power-hungry Grand Vizier Jafar vie for a magic lamp that can fulfill their wishes.', 91, '/eLFfl7vS8dkeG1hKp5mwbm37V83.jpg', '/nenJjvfe2Eq8uBMXFJnWj5mw4bi.jpg', 'XBrfbWtmvWs'),
    (813, 'An ex-fighter pilot is forced to take over the controls of an airliner when the flight crew succumbs to food poisoning.', 88, '/7Q3efxd3AF1vQjlSxnlerSA7RzN.jpg', '/wQyvrsNSTzFVEGgarZbFkFyIciy.jpg', 'HMnVs287AJ4'),
    (816, 'As a swinging fashion photographer by day and a groovy British superagent by night, Austin Powers is the ''60s'' most shagadelic spy. But can he stop megalomaniac Dr. Evil after the bald villain freezes himself and unthaws in the ''90s? With the help of sexy sidekick Vanessa Kensington, he just might.', 89, '/5uD4dxNX8JKFjWKYMHyOsqhi5pN.jpg', '/wSm5McaHSAyOx4gGRYdlDHzj00y.jpg', '9HGy-c4_xFg'),
    (817, 'When diabolical genius Dr. Evil travels back in time to steal superspy Austin Powers''s ‘mojo,’ Austin must return to the swingin'' ''60s himself - with the help of American agent, Felicity Shagwell - to stop the dastardly plan. Once there, Austin faces off against Dr. Evil''s army of minions to try to save the world in his own unbelievably groovy way.', 95, '/jiF7UShERJFn5RtgfBK2lIJrOTc.jpg', '/xI1tAzzUk2v9nON6DLAHzcOLK42.jpg', 'a9HSJwG4DXo'),
    (819, 'Two gangsters seek revenge on the state jail worker who during their stay at a youth prison sexually abused them. A sensational court hearing takes place to charge him for the crimes.', 147, '/yUpiEk2EojS9ZEXb3nIQonQCYYF.jpg', '/sDhABATFQX8nfTHShTfH8HeqKY1.jpg', 'rNaMAgf4ErE'),
    (824, 'A celebration of love and creative inspiration takes place in the infamous, gaudy and glamorous Parisian nightclub, at the cusp of the 20th century. A young poet, who is plunged into the heady world of Moulin Rouge, begins a passionate affair with the club''s most notorious and beautiful star.', 128, '/2kjM5CUZRIU5yOANUowrbJcRL9L.jpg', '/vvcLSgiviCIU0J0UcwLqWdU8Iup.jpg', '2PpgPxjzbkA'),
    (826, 'The classic story of English POWs in Burma forced to build a bridge to aid the war effort of their Japanese captors. British and American intelligence officers conspire to blow up the structure, but Col. Nicholson, the commander who supervised the bridge''s construction, has acquired a sense of pride in his creation and tries to foil their plans.', 162, '/7paXMt2e3Tr5dLmEZOGgFEn2Vo7.jpg', '/cGi9obHiooPoNR4JX72L9RooeOY.jpg', 'RlC7XBayj0s'),
    (829, 'Private eye Jake Gittes lives off of the murky moral climate of sunbaked, pre-World War II Southern California. Hired by a beautiful socialite to investigate her husband''s extra-marital affair, Gittes is swept into a maelstrom of double dealings and deadly deceits, uncovering a web of personal and political scandals that come crashing together.', 130, '/kZRSP3FmOcq0xnBulqpUQngJUXY.jpg', '/pyvkujOZ5qvY2NlQVC71flfgVWE.jpg', 'RKdXf-fiBcw'),
    (832, 'In this classic German thriller, Hans Beckert, a serial killer who preys on children, becomes the focus of a massive Berlin police manhunt. Beckert''s heinous crimes are so repellant and disruptive to city life that he is even targeted by others in the seedy underworld network. With both cops and criminals in pursuit, the murderer soon realizes that people are on his trail, sending him into a tense, panicked attempt to escape justice.', 110, '/bTdZk3q2DWpBRnLiaaItKFWOVhI.jpg', '/5Pk1rGAtyblh9Xaq72T7ARCQSDQ.jpg', 'nsVproWjN6c'),
    (834, 'As the war between the vampires and the Lycans rages on, Selene, a former member of the Death Dealers (an elite vampire special forces unit that hunts werewolves), and Michael, the werewolf hybrid, work together in an effort to unlock the secrets of their respective bloodlines.', 106, '/4yoynvNuQtK3g5RfCuaQMvujSoL.jpg', '/wBiSklv702D0KEnhPEZLgHxTm1w.jpg', 'W38N0LGau9A'),
    (837, 'As the president of a trashy TV channel, Max Renn is desperate for new programming to attract viewers. When he happens upon "Videodrome," a TV show dedicated to gratuitous torture and punishment, Max sees a potential hit and broadcasts the show on his channel. However, after his girlfriend auditions for the show and never returns, Max investigates the truth behind Videodrome and discovers that the graphic violence may not be as fake as he thought.', 88, '/qqqkiZSU9EBGZ1KiDmfn07S7qvv.jpg', '/eBS1nvaQ7BMdsSlkoLyKapf0FEY.jpg', 'v8BUXKcp8zE'),
    (840, 'After an encounter with UFOs, an electricity linesman feels undeniably drawn to an isolated area in the wilderness where something spectacular is about to happen.', 137, '/dTWvLWur0XM7YezSTSoZxZ7gDfM.jpg', '/yBCekmb7vK70xUhtsRQBcTu65sB.jpg', 'dSpQ3G08k48'),
    (841, 'In the year 10,191, the most precious substance in the universe is the spice Melange. The spice extends life. The spice expands consciousness. The spice is vital to space travel.  The spice exists on only one planet in the entire universe, the vast desert planet Arrakis, also known as Dune.  Its native inhabitants, the Fremen, have long held a prophecy that a man would come, a messiah who would lead them to true freedom.', 136, '/4kJmUCE7mkVJjXa7A0g2rY4IGTm.jpg', '/5wJ2tckpvwcxGCAgZiccodwEJpf.jpg', 'hjRG8kvMFw0'),
    (843, 'In 1960s Hong Kong, two neighbors form an intimate bond after making a discovery about their spouses in this visually stunning tale of unrequited love.', 99, '/8BgGbbWiLNhPtkMkN0gGTnbtvBv.jpg', '/ffQFnAUm2Uu4RU0nijpjPRf9TBT.jpg', 'rc3QleuaQMw'),
    (847, 'The evil Queen Bavmorda hunts the newborn princess Elora Danan, a child prophesied to bring about her downfall. When the royal infant is found by Willow, a timid farmer and aspiring sorcerer, he''s entrusted with delivering her from evil.', 126, '/pAIRGMIdN7ZdZhflazdV2ezuJ9f.jpg', '/3sF6AibdbTTkswfSRxXEGCt5w6s.jpg', '9KhFp9fqrHc'),
    (853, 'A Russian and a German sniper play a game of cat-and-mouse during the Battle of Stalingrad in WWII.', 131, '/cHRAbVdsCWFaQrswRsBP7Bn255W.jpg', '/wSMaPDDwqfYbwg1GX9B5MaMnmxe.jpg', 'xqwlIaOyBSA'),
    (854, 'Timid bank clerk Stanley Ipkiss discovers a magical mask infused with the spirit of the Norse god Loki. Donning it transforms him into an unrestrained, green-faced, cartoon-like wild man. While the mask grants him the confidence to woo a local singer, it also makes him the target of a ruthless mobster.', 101, '/jPC2eYub74zwf2tPGVtzSlBW6Oy.jpg', '/bQlw59HncOXX9alFlOYKHAvSnm.jpg', 'uPrUiKgQVQk'),
    (855, 'When U.S. Rangers and an elite Delta Force team attempt to kidnap two underlings of a Somali warlord, their Black Hawk helicopters are shot down, and the Americans suffer heavy casualties, facing intense fighting from the militia on the ground.', 145, '/7fU5dSqKRL4XHeEUz62rCKBfYok.jpg', '/7jaNOECZG8uS1tlq69HsY5xY8P9.jpg', 'V1UV3Vj4z0w'),
    (856, 'Toon star Roger is worried that his wife Jessica is playing pattycake with someone else, so the studio hires detective Eddie Valiant to snoop on her. But the stakes are quickly raised when Marvin Acme is found dead and Roger is the prime suspect.', 104, '/lYfRc57Kx9VgLZ48iulu0HKnM15.jpg', '/udIE8Cdon9wnYmVIOFYrBPfA2Mq.jpg', 'XEIJpS26aAw'),
    (857, 'As U.S. troops storm the beaches of Normandy, three brothers lie dead on the battlefield, with a fourth trapped behind enemy lines. Ranger captain John Miller and seven men are tasked with penetrating German-held territory and bringing the boy home.', 169, '/uqx37cS8cpHg8U35f9U5IBlrCV3.jpg', '/rW2xRFlJRbTnBJlQTSjQmjevIwb.jpg', 'RYExstiQlLc'),
    (858, 'After the death of his mother, a young boy calls a radio station in an attempt to set his father up on a date. Across the country, an engaged woman becomes convinced that they belong together, despite their never having met. Will their paths collide despite the odds?', 105, '/jAXfku1u1uaLGh4cUmK0ESf1pPu.jpg', '/k83YesKu0mSpMVu7YYf1QyeZpFn.jpg', '2bnxHgO59A4'),
    (860, 'High school student David Lightman has a talent for hacking. But while trying to hack into a computer system to play unreleased video games, he unwittingly taps into the Department of Defense''s war computer and initiates a confrontation of global proportions. Together with his friend and a wizardly computer genius, David must race against time to outwit his opponent and prevent a nuclear Armageddon.', 114, '/zZ1rN4LoPxKNfAp67Xl300WxVeD.jpg', '/qtamfYGFfDLfGRcucx1zNwohRts.jpg', '-hfz7qDg-Bg'),
    (861, 'Construction worker Douglas Quaid''s obsession with the planet Mars leads him to visit Rekall, a virtual vacation company that manufactures memories. When something goes wrong during Quaid''s memory implant procedure, his life turns upside down, leading him to question what is reality and what isn''t.', 113, '/wVbeL6fkbTKSmNfalj4VoAUUqJv.jpg', '/x2wOlXuK4NzPDQ0OBZiJjNNOp6Y.jpg', 'IRaRhZE-1b4'),
    (862, 'Led by Woody, Andy''s toys live happily in his room until Andy''s birthday brings Buzz Lightyear onto the scene. Afraid of losing his place in Andy''s heart, Woody plots against Buzz. But when circumstances separate Buzz and Woody from their owner, the duo eventually learns to put aside their differences.', 81, '/uXDfjJbdP4ijW5hWSBrPrlKpxab.jpg', '/8AqWECiUHnz1Crj69uB9vhiK9Le.jpg', 'CxwTLktovTU'),
    (863, 'Andy heads off to Cowboy Camp, leaving his toys to their own devices. Things shift into high gear when an obsessive toy collector named Al McWhiggen, owner of Al''s Toy Barn kidnaps Woody. Andy''s toys mount a daring rescue mission, Buzz Lightyear meets his match and Woody has to decide where he and his heart truly belong.', 92, '/4rbcp3ng8n1MKHjpeqW0L7Fnpzz.jpg', '/nsfVr4QbbunUrHINN9N7JdVAMTf.jpg', 'xNWSGRD5CzU'),
    (864, 'When a Jamaican sprinter is disqualified from the Olympic Games, he enlists the help of a dishonored coach to start the first Jamaican bobsled team.', 98, '/6fXuGEb7EqGmAeUodxm7l5ELPZ.jpg', '/ucFDgf7Nw6cEwPh5o4cacp3k1aW.jpg', 'wLlmymHRNZg'),
    (865, 'By 2017, the global economy has collapsed and U.S. society has become a totalitarian police state, censoring all cultural activity. The government pacifies the populace by broadcasting a number of game shows in which convicted criminals fight for their lives, including the gladiator-style The Running Man, hosted by the ruthless Damon Killian, where “runners” attempt to evade “stalkers” and certain death for a chance to be pardoned and set free.', 101, '/GTAUOhO4BN0peJVvxGEQydJvUO.jpg', '/ssQ7IcGmgUJdFLv8cHY3vC3OR4f.jpg', 'i2FMhBg0h_8'),
    (869, 'After a spectacular crash-landing on an uncharted planet, brash astronaut Leo Davidson finds himself trapped in a savage world where talking apes dominate the human race. Desperate to find a way home, Leo must evade the invincible gorilla army led by Ruthless General Thade.', 120, '/3ZWsuP5rExMSji7erxnb1P5SK6F.jpg', '/1HQoPSRZR5CdNPvuSWTvz3aSQQt.jpg', 'E-a4eIA8KWM'),
    (872, 'In 1927 Hollywood, a silent film star falls for a chorus girl just as he and his paranoid screen partner struggle to make the difficult transition to talking pictures.', 103, '/jDNkVrNtVeTdctYdUUgEHNl7VnM.jpg', '/6qOyw4yfzbzTp5YsCX26C28Do0S.jpg', 'lSE8sl2-PZg'),
    (879, 'The boy who wasn''t supposed to grow up—Peter Pan—does just that, becoming a soulless corporate lawyer whose workaholism could cost him his wife and kids. During his trip to see Granny Wendy in London, the vengeful Capt. Hook kidnaps Peter''s kids and forces Peter to return to Neverland.', 142, '/a6rB1lGXoGms7gWxRfJneQmAjNV.jpg', '/39OxcFZjX4uc6vYzexUh5qXghxE.jpg', 'c-vwgt8cwEM'),
    (881, 'When cocky military lawyer Lt. Daniel Kaffee and his co-counsel, Lt. Cmdr. JoAnne Galloway, are assigned to a murder case, they uncover a hazing ritual that could implicate high-ranking officials such as shady Col. Nathan Jessep.', 138, '/rLOk4z9zL1tTukIYV56P94aZXKk.jpg', '/8UOdqhVP28OcnzNL6DnQf0GDLvR.jpg', '2T2pyqrr8UM'),
    (884, 'A car crash victim inexplicably finds himself aroused by car accidents and becomes involved with an underground subculture of like-minded souls.', 100, '/gpai5oUFyFGLHOCsYTvVMqlbY7A.jpg', '/vQNknPEVSAui6IL6eUlDBPfUzcW.jpg', '9dIC-lDgpZU'),
    (888, 'Modern Stone Age family the Flintstones hit the big screen in this live-action version of the classic cartoon. Fred helps Barney adopt a child. Barney sees an opportunity to repay him when Slate Mining tests its employees to find a new executive. But no good deed goes unpunished.', 91, '/qbojLbbpSaNSerWa2moIrt0C8hy.jpg', '/4byUSbNrjqCSjqVYrJU6AxqyZYr.jpg', 'a-uN0rHF7Ig'),
    (901, 'A tramp falls in love with a beautiful blind flower girl. His on-and-off friendship with a wealthy man allows him to be the girl''s benefactor and suitor.', 87, '/bXNvzjULc9jrOVhGfjcc64uKZmZ.jpg', '/Ma7mQsldFCaQpsZbm8zolgLfmV.jpg', '7vl7F8S4cpQ'),
    (914, 'Dictator Adenoid Hynkel tries to expand his empire while a poor Jewish barber tries to avoid persecution from Hynkel''s regime.', 124, '/nhMXB8GTdswYMCL9nepDZymJCOr.jpg', '/c8Pi8F1FzpNebtgXcSjC9nWCdSW.jpg', 'i1C6qZVeFtA'),
    (920, 'Lightning McQueen, a hotshot rookie race car driven to succeed, discovers that life is about the journey, not the finish line, when he finds himself unexpectedly detoured in the sleepy Route 66 town of Radiator Springs. On route across the country to the big Piston Cup Championship in California to compete against two seasoned pros, McQueen gets to know the town''s offbeat characters.', 117, '/2Touk3m5gzsqr1VsvxypdyHY5ci.jpg', '/sd4xN5xi8tKRPrJOWwNiZEile7f.jpg', 'XszNWHhpaTc'),
    (922, 'On the run after committing murder, an accountant encounters a strange Native American man who prepares him for his journey into the spiritual world.', 122, '/jX3wGBVoYoAY3IixBpwYk1fjT4z.jpg', '/a7DtgKB187dUm9n81IlvNzVXsK1.jpg', 'FEHMWguT--U'),
    (923, 'During an ever-growing epidemic of zombies that have risen from the dead, two Philadelphia SWAT team members, a traffic reporter, and his television-executive girlfriend seek refuge in a secluded shopping mall.', 127, '/70MY8H0bLMvXf8ED2SgVMPhDVVM.jpg', '/9OKzKuCfcMwpHVp56pjNI7J4xXR.jpg', 'Y_EviQj5tvA'),
    (925, 'Sal is the Italian owner of a pizzeria in Brooklyn. A neighborhood local, Buggin'' Out, becomes upset when he sees that the pizzeria''s Wall of Fame exhibits only Italian actors. Buggin'' Out believes a pizzeria in a black neighborhood should showcase black actors, but Sal disagrees. The wall becomes a symbol of racism and hate to Buggin'' Out and to other people in the neighborhood, and tensions rise.', 120, '/63rmSDPahrH7C1gEFYzRuIBAN9W.jpg', '/xnLh9CNRxkpkSNikVhi5qLwcfUG.jpg', 'yVAD4fYRcvA'),
    (926, 'For four years, the courageous crew of the NSEA Protector —  Commander Peter Quincy Taggart, Lieutenant Tawny Madison, and Doctor Lazarus — set off on a thrilling and often dangerous mission in space... until their series was cancelled! Now, twenty years later, aliens under attack have mistaken the Galaxy Quest television transmissions for "historical documents" and beam up the crew of has-been actors to save the universe. With no script, no director, and no clue, the actors must turn in the performances of their lives.', 102, '/fZXSwgZknp81vmciTb86rw0MejV.jpg', '/yzQ0mkz1OUJKtUK1NWp53jiGcaJ.jpg', 'rzwJgFhMbL4'),
    (927, 'After receiving an exotic small animal as a Christmas gift, a young man inadvertently breaks three important rules concerning his new pet, which unleashes a horde of malevolently mischievous creatures on a small town.', 106, '/6m0F7fsXjQvUbCZrPWcJNrjvIui.jpg', '/5UX6M0aEphiW6Xmy5rpYX75glbo.jpg', 'PXXZx6skXrw'),
    (928, 'Young sweethearts Billy and Kate move to the Big Apple, land jobs in a high-tech office park and soon reunite with the friendly and lovable Gizmo. But a series of accidents creates a whole new generation of Gremlins. The situation worsens when the devilish green creatures invade a top-secret laboratory and develop genetically altered powers, making them even harder to destroy!', 106, '/35F5yD7MljvBE2AC0NHAVCoPGEi.jpg', '/iR3tV8NXFls4UKzPA60D4zrI7Jh.jpg', 'Aamzs_Wn91U'),
    (929, 'French nuclear tests irradiate an iguana into a giant monster that viciously attacks freighter ships in the Pacific Ocean. A team of experts, including Niko Tatopoulos, conclude that the oversized reptile is the culprit. Before long, the giant lizard is loose in Manhattan as the US military races to destroy the monster before it reproduces and it''s spawn takes over the world.', 138, '/xJVl1I95StraYAwaNbBkVoWE2qA.jpg', '/vjzhl4sQg4GUcZZrV64OQNVdmZe.jpg', '3FEDcXsL5o8'),
    (935, 'After the insane General Jack D. Ripper initiates a nuclear strike on the Soviet Union, a war room full of politicians, generals and a Russian diplomat all frantically try to stop it.', 95, '/gHm96BRW4GoI339rF1vYoYTB6Qe.jpg', '/7i0L2ee4Iy0aXV6vR5u1ZmblOrx.jpg', 'XjLsIWZdWmc'),
    (938, 'Two bounty hunters both pursue the brutal and sadistic bandit, El Indio, who has a large bounty on his head.', 132, '/ooqASvA7qxlTVKL3KwOzBwy57Dh.jpg', '/hs6OPto38fF589ScpGhl7uSU4MI.jpg', 'xZm8i5sGlWI'),
    (941, 'A veteran cop and an unstable detective become partners who must put their differences aside in order to bring down a heroin-smuggling ring run by ex-Special Forces.', 110, '/6gt44oqb4nE8vflPElffeGwsHVl.jpg', '/xinJKZQiqkdJhoYc2SXuEnhehXz.jpg', 'RLu49mRcmYs'),
    (942, 'Riggs and Murtaugh are on the trail of South African diplomats using their immunity to engage in criminal activities.', 114, '/1EEIUw0tkX7AJZ1ikZrtKZZKlC6.jpg', '/uY8i4RABFyBpH2cmFWMVLEswopD.jpg', 'xGcCI8JWCic'),
    (944, 'With personal crises and age weighing in on them, LAPD officers Riggs and Murtaugh must contend with a deadly Chinese crime lord trying to get his brother out of prison.', 127, '/pTLliHRoG0Qwp6qycmrMB4bD3mr.jpg', '/u4d4vymNPo1UuJ6ihtyy9OQgco2.jpg', 'pi2cGmz9Q2A'),
    (948, 'Fifteen years after murdering his sister on Halloween Night 1963, Michael Myers escapes from a mental hospital and returns to the small town of Haddonfield, Illinois to kill again.', 91, '/wijlZ3HaYMvlDTPqJoTCWKFkCPU.jpg', '/sHI9xlFRWCJ38AIIfOqnGjuEvXz.jpg', 'NT0loXUv-ks'),
    (949, 'Obsessive master thief Neil McCauley leads a top-notch crew on various daring heists throughout Los Angeles while determined detective Vincent Hanna pursues him without rest. Each man recognizes and respects the ability and the dedication of the other even though they are aware their cat-and-mouse game may end in violence.', 170, '/umSVjVdbVwtx5ryCA2QXL44Durm.jpg', '/uI22JkEMediWyiRqhllNqeeGtW0.jpg', '14oNcFxiVaQ'),
    (950, 'Diego, Manny and Sid return in this sequel to the hit animated movie Ice Age. This time around, the deep freeze is over, and the ice-covered earth is starting to melt, which will destroy the trio''s cherished valley. The impending disaster prompts them to reunite and warn all the other beasts about the desperate situation.', 91, '/zDduhCHasKQ9YOTvlOreHem7Wbi.jpg', '/o1jr0UqVjxIZ1JnFzuVLN4ulWey.jpg', 'SNMXO74bw9M'),
    (953, 'Four animal friends get a taste of the wild life when they break out of captivity at the Central Park Zoo and wash ashore on the island of Madagascar.', 86, '/zMpJY5CJKUufG9OTw0In4eAFqPX.jpg', '/tPaurpIUskVji5vwV0dhy9pq4Vs.jpg', 'fq5zU9T_Hl4'),
    (954, 'When Ethan Hunt, the leader of a crack espionage team whose perilous operation has gone awry with no explanation, discovers that a mole has penetrated the CIA, he''s surprised to learn that he''s the prime suspect. To clear his name, Hunt now must ferret out the real double agent and, in the process, even the score.', 111, '/l5uxY5m5OInWpcExIpKG6AR3rgL.jpg', '/sra8XnL96OyLHENcglmZJg6HA8z.jpg', 'L8Pbjh4EZRk'),
    (955, 'With computer genius Luther Stickell at his side and a beautiful thief on his mind, agent Ethan Hunt races across Australia and Spain to stop a former IMF agent from unleashing a genetically engineered biological weapon called Chimera. This mission, should Hunt choose to accept it, plunges him into the center of an international crisis of terrifying magnitude.', 123, '/hfnrual76gPeNFduhD4xzHWpfTw.jpg', '/24DZfupDlhXeTchmcOkoGRhP5Vg.jpg', 'hSPtsCQq52k'),
    (956, 'Retired from active duty, and training recruits for the Impossible Mission Force, agent Ethan Hunt faces the toughest foe of his career: Owen Davian, an international broker of arms and information, who''s as cunning as he is ruthless. Davian emerges to threaten Hunt and all that he holds dear – including the woman Hunt loves.', 126, '/vKGYCpmQyV9uHybWDzXuII8Los5.jpg', '/bYKeB9uUcPmvikjouEEQ86uvPw9.jpg', '4oVva0muTE8'),
    (957, 'When the nefarious Dark Helmet hatches a plan to snatch Princess Vespa and steal her planet''s air, space-bum-for-hire Lone Starr and his clueless sidekick fly to the rescue. Along the way, they meet Yogurt, who puts Lone Starr wise to the power of "The Schwartz." Can he master it in time to save the day?', 96, '/kNbaxEsnCyWBTfANVPHayujBsxp.jpg', '/p50q3DO1DTFhKH5CqNLRGio6zCo.jpg', 'LYqTjnSrDuQ'),
    (975, 'A commanding officer defends three scapegoats on trial for a failed offensive that occurred within the French Army in 1916.', 88, '/hGg1UCQSHlXfv2HI9bDHT2OQBam.jpg', '/nbMY2UcNnaAr3jrrowzN0NaxQyr.jpg', 'FESvZ0HG2p4'),
    (979, 'A woman’s lover and her ex-boyfriend take justice into their own hands after she becomes the victim of a rapist. Because some acts can’t be undone. Because man is an animal. Because the desire for vengeance is a natural impulse. Because most crimes remain unpunished.', 97, '/rxeDxo8FvZpLu6iplNpxdtAVnfu.jpg', '/xV1EfNSEg6id6juJPr1vM6p9x5X.jpg', 'e9D7hvIwgj4'),
    (984, 'When a madman dubbed ''Scorpio'' terrorizes San Francisco, hard-nosed cop, Harry Callahan – famous for his take-no-prisoners approach to law enforcement – is tasked with hunting down the psychopath.', 102, '/scl2JDHzYoIEs5xyYy5ITCfyY0G.jpg', '/3m9hY5uixci0XpUawRG0mGEUe4r.jpg', 'S6bnGiyBXuU'),
    (994, 'David Sumner, a mild-mannered academic from the United States, marries Amy, an Englishwoman. In order to escape a hectic stateside lifestyle, David and his wife relocate to the small town in rural Cornwall where Amy was raised. There, David is ostracized by the brutish men of the village, including Amy''s old flame, Charlie. Eventually the taunts escalate.', 116, '/yigkfHE1OhkxPPrjrV78Y9ibGEk.jpg', '/8Mngxf4aE99eyDHCvGo8sfyQd9C.jpg', '_SPJza7ZUjo'),
    (1018, 'Blonde Betty Elms has only just arrived in Hollywood to become a movie star when she meets an enigmatic brunette with amnesia. Meanwhile, as the two set off to solve the second woman''s identity, filmmaker Adam Kesher runs into ominous trouble while casting his latest project.', 147, '/x7A59t6ySylr1L7aubOQEA480vM.jpg', '/kxgrGGbifN60x5BopH4wk7T4Twe.jpg', '3oa64ktrwKY'),
    (1051, 'Tough narcotics detective ''Popeye'' Doyle is in hot pursuit of a suave French drug dealer who may be the key to a huge heroin-smuggling operation.', 104, '/pH4saPwMjhnVGwmSH6RkMaHrt3s.jpg', '/AsaW2VwcArvQmYjf2wsDjqWEn6f.jpg', 'T76K3RxJY0A'),
    (1089, 'In Los Angeles, a gang of bank robbers who call themselves The Ex-Presidents commit their crimes while wearing masks of Reagan, Carter, Nixon and Johnson. Believing that the members of the gang could be surfers, the F.B.I. sends young agent Johnny Utah to the beach undercover to mix with the surfers and gather information.', 122, '/tlbERIghrQ4oofqlbF7H0K0EYnx.jpg', '/yGOHbICOQwlJ20UjK8F2ChGJjvl.jpg', 'KywiWyPjrOg'),
    (1091, 'A research team in Antarctica is hunted by a shape-shifting alien that assumes the appearance of its victims.', 109, '/tzGY49kseSE9QAKk47uuDGwnSCu.jpg', '/r9leYNa8nTRCceZrZhP1DXkgKVb.jpg', 'ySvzHdtCiWE'),
    (1092, 'In postwar Vienna, Austria, Holly Martins, a writer of pulp Westerns, arrives penniless as a guest of his childhood chum Harry Lime, only to learn he has died. Martins develops a conspiracy theory after learning of a "third man" present at the time of Harry''s death, running into interference from British officer Major Calloway, and falling head-over-heels for Harry''s grief-stricken lover, Anna.', 105, '/vqnFHTx1phgTAsLfxZoejSbMVHA.jpg', '/rLLhOCgAjuvlKmjUqVb7P1UAbUI.jpg', 'Y7nwySBGqCo'),
    (1103, 'In a world ravaged by crime, the entire island of Manhattan has been converted into a walled prison where brutal prisoners roam free. After the US president crash-lands inside, war hero Snake Plissken has 24 hours to bring him back.', 99, '/vH9llaphjAssRGi0k7e75tD40Ce.jpg', '/vsIpYIa23bi5beLReFtgtIROS2N.jpg', 'bqT09APfNKI'),
    (1124, 'A mysterious story of two magicians whose intense rivalry leads them on a life-long battle for supremacy -- full of obsession, deceit and jealousy with dangerous and deadly consequences.', 131, '/Ag2B2KHKQPukjH7WutmgnnSNurZ.jpg', '/yaExZh6qE2cfyK3o4kAMEq0mkgy.jpg', 'ijXruSzfGEc'),
    (1213, 'Tom Ripley is a calculating young man who believes it''s better to be a fake somebody than a real nobody. Opportunity knocks in the form of a wealthy U.S. shipbuilder who hires Tom to travel to Italy to bring back his playboy son, Dickie. Ripley worms his way into the idyllic lives of Dickie and his girlfriend, plunging into a daring scheme of duplicity, lies and murder.', 140, '/6ojHgqtIR41O2qLKa7LFUVj0cZa.jpg', '/51UDa3IuGyiKGe2MgMcLGvJE2Fm.jpg', 'Ylc5ToQoLg0'),
    (1246, 'When he loses a highly publicized virtual boxing match to ex-champ Rocky Balboa, reigning heavyweight titleholder Mason Dixon retaliates by challenging the Italian Stallion to a 10-round exhibition bout. To the surprise of his son and friends, Rocky agrees to come out of retirement and face an opponent who''s faster, stronger and thirty years his junior. Rocky takes on Dixon in what will become the greatest fight in boxing history!', 102, '/byBlJvZwCqgtIwrZNv0pyE974jC.jpg', '/fsJn2mPXMhauXsEpNTtFqDdjSQt.jpg', 'K_z4bNupt1A'),
    (1248, 'The story of the early, murderous roots of the cannibalistic killer, Hannibal Lecter – from his hard-scrabble Lithuanian childhood, where he witnesses the repulsive lengths to which hungry soldiers will go to satiate themselves, through his sojourn in France, where as a medical student he hones his appetite for the kill and learnt sword skills from his Japanese girlfriend, who happened to have similar fate', 121, '/7FTDMQoac0uqJUquZk4KenDzLMZ.jpg', '/am6ZfhUTUmcjPjjA4GIkLEJ33TN.jpg', 'ECOUSPHn4Sg'),
    (1250, 'In order to save his dying father, young stunt cyclist Johnny Blaze sells his soul to Mephistopheles and sadly parts from the pure-hearted Roxanne Simpson, the love of his life. Years later, Johnny''s path crosses again with Roxanne, now a go-getting reporter, and also with Mephistopheles, who offers to release Johnny''s soul if Johnny becomes the fabled, fiery ''Ghost Rider''.', 114, '/4quwR1VwZouD0YF9AaD72kQAjxH.jpg', '/zbV32WKHFuEYLXLTpr0rmVjQn11.jpg', 'nu6R7ypaz5g'),
    (1251, 'The story of the battle of Iwo Jima between the United States and Imperial Japan during World War II, as told from the perspective of the Japanese who fought it.', 141, '/kZokxQtzMPURvijWYFuvh1fAvnv.jpg', '/69Mdg9vH6yQx08DwK02RlqO9CPp.jpg', 'g65ewJJ1USc'),
    (1265, 'Jesse Aarons trained all summer to become the fastest runner in school. So he''s very upset when newcomer Leslie Burke outruns him and everyone else. Despite this and other differences including that she''s rich, he''s poor, she''s a city girl, and he''s a country boy the two become fast friends. Together they create Terabithia, a land of monsters, trolls, ogres, and giants where they rule as king and queen.', 95, '/ieIoNyJvtwQ6joyG6npTKxnCtGH.jpg', '/o4mQHoP8LExn2Q9dn16OGqHvaiK.jpg', 'VxSs4mpFFRk'),
    (1267, 'Lewis, a brilliant young inventor, is keen on creating a time machine to find his mother, who abandoned him in an orphanage. Things take a turn when he meets Wilbur Robinson and his family.', 95, '/naya0zF4kT401Sx15AtwB9vpcJr.jpg', '/AsWuvFnzgmG6kZMIpJO7HZpvYRB.jpg', 'S396-fnLldk'),
    (1268, 'Mr. Bean wins a trip to Cannes where he unwittingly separates a young boy from his father and must help the two reunite. On the way he discovers France, bicycling and true love, among other things.', 90, '/bSSx9Sq6irWwN9NTQmoT9KE8kXn.jpg', '/yU5jOx10pP6veJW6CLblr6MduHH.jpg', 'LZfIzJ6XwPQ'),
    (1271, 'A story very loosely based the 480 B.C. Battle of Thermopylae, where the King of Sparta led his army against the advancing Persians.', 117, '/h7Lcio0c9ohxPhSZg42eTlKIVVY.jpg', '/lgBZlJ1LHQel5nneNQMoesmvc7l.jpg', 'UrIbxk7idYA'),
    (1272, 'Fifty years into the future, the sun is dying, and Earth is threatened by arctic temperatures. A team of astronauts is sent to revive the Sun — but the mission fails. Seven years later, a new team is sent to finish the mission as mankind’s last hope.', 108, '/oKGGeJ8qvm0UmClz43VJ31fzPP7.jpg', '/5AIAnucJKZ3sHpm7r1ykFVIoUHK.jpg', 'Ig1BU6PUt0A'),
    (1281, 'Childlike Englishman, Mr. Bean, is an incompetent watchman at the Royal National Gallery. After the museum''s board of directors'' attempt to have him fired is blocked by the chairman, who has taken a liking to Bean, they send him to Los Angeles to act as their ambassador for the unveiling of a historic painting to humiliate him. Fooled, Mr. Bean must now successfully unveil the painting or risk his and a hapless Los Angeles curator''s termination.', 89, '/IwrDPrB4d2DMcpnGkvan46yINL.jpg', '/xvBvwR3NWn1K8YcByJJhB7pYoKu.jpg', '-jCq13TtzRY'),
    (1359, 'A wealthy New York investment banking executive hides his alternate psychopathic ego from his co-workers and friends as he escalates deeper into his illogical, gratuitous fantasies.', 102, '/9uGHEgsiUXjCNq8wdq4r49YL8A1.jpg', '/5oaMV2q0qzxkIW2ukU3lldLu5q2.jpg', '81mibtQWWBg'),
    (1365, 'A prison guard begins a tentative romance with the unsuspecting widow of a man whose execution he presided over.', 113, '/rQeufx98gKH4CCeVw57KT1Fd0gr.jpg', '/2lZYvShWuVThLM6Oo8zfakdBMqw.jpg', 's7W-zEsFjMM'),
    (1366, 'Rocky Balboa is a Philadelphia club fighter who seems to be going nowhere. But when a stroke of fate puts him in the ring with a world heavyweight champion, Rocky knows that it''s his one shot at the big time — a once-in-a-lifetime opportunity to go the distance and come out a winner!', 119, '/1mcJmdbRLusxhoSGjFI3pbEboXt.jpg', '/bacOuUnRBoAO1NjMfsAGX2EKRrS.jpg', 'dmd9tEt9F30'),
    (1367, 'After Rocky goes the distance with champ Apollo Creed, both try to put the fight behind them and move on. Rocky settles down with Adrian but can''t put his life together outside the ring, while Creed seeks a rematch to restore his reputation. Soon enough, the "Master of Disaster" and the "Italian Stallion" are set on a collision course for a climactic battle that is brutal and unforgettable.', 119, '/nMaiiu0CzT77U4JZkUYV7KqdAjK.jpg', '/78jvhi792WFjk1zSwqpfDOudO78.jpg', 'yZrmRBj1r_E'),
    (1368, 'When former Green Beret John Rambo is harassed by local law enforcement and arrested for vagrancy, he is forced to flee into the mountains and wage an escalating one-man war against his pursuers.', 93, '/a9sa6ERZCpplbPEO7OMWE763CLD.jpg', '/hCxxOJojCUFyuahDx167glJgp7E.jpg', 'Rl_4vPKDijQ'),
    (1369, 'John Rambo is released from prison by the government for a top-secret covert mission to the last place on Earth he''d want to return - the jungles of Vietnam.', 96, '/fVwRtWqEPdsCH21BVDGqgkAQcff.jpg', '/aPlgkT2FlD7EcE6Vi10I4RTzRqb.jpg', 'TY8LVqaLHwY'),
    (1371, 'Following Rocky Balboa''s intense battle with his most powerful adversary yet – the ferocious Clubber Lang – Rocky joins forces with former rival Apollo Creed in an effort to get back his fighting spirit.', 99, '/uqw16i2kmwVqkJHzjzbDU4xZ0Pl.jpg', '/ljOHSIyTbxdkQFjcJyWKfGm2i2r.jpg', 'o7vbDPUMWDc'),
    (1372, 'An ex-mercenary turned smuggler. A Mende fisherman. Amid the explosive civil war overtaking 1999 Sierra Leone, these men join for two desperate missions: recovering a rare pink diamond of immense value and rescuing the fisherman''s son, conscripted as a child soldier into the brutal rebel forces ripping a swath of torture and bloodshed countrywide.', 143, '/tnLxPpajkbVdbQl5B9CuD7sSpz9.jpg', '/qrAwMckxNbnEdINi0aYU0608XMy.jpg', 'stEtrTrDlrw'),
    (1374, 'Rocky Balboa holds the world heavyweight championship, but a new challenger has stepped forward: Drago, a six-foot-four, 261-pound fighter who has the backing of the Soviet Union. This time, Rocky''s training regimen takes him to Siberia, where he prepares for a globally televised match in the heart of Moscow. But nothing can truly prepare him for what he''s about to face – a fight to the finish, in which he must defend not only himself, but also the honor of his country!', 91, '/2MHUit4H6OK5adcOjnCN6suCKOl.jpg', '/uiUb4KJ6tadldqlJme49TW1r3jA.jpg', '4qjV0bB2V0Q'),
    (1391, 'In Mexico, two teenage boys and an attractive older woman embark on a road trip and learn a thing or two about life, friendship, sex, and each other.', 106, '/aj3rqjab8jfc2fWmcS3H3c5qbur.jpg', '/orIxqUMEcU3DT7qCs16Si8KWjBO.jpg', 'inc0vS58ZKg'),
    (1402, 'A struggling salesman takes custody of his son as he''s poised to begin a life-changing professional career.', 117, '/lBYOKAMcxIvuk9s9hMuecB9dPBV.jpg', '/5jhG1lTgV0MS6tDkBMQSSitttTT.jpg', 'DMOBlEcRuw8'),
    (1417, 'In post–civil war Spain, 10-year-old Ofelia moves with her pregnant mother to live under the control of her cruel stepfather. Drawn into a mysterious labyrinth, she meets a faun who reveals that she may be a lost princess from an underground kingdom. To return to her true father, she must complete a series of surreal and perilous tasks that blur the line between reality and fantasy.', 118, '/khBQ6nN5FLfg9XgPXIZDkABJjqo.jpg', '/6G6nqSW9S7EHA9HrYl0Z8uo2H7f.jpg', 'OBGKGm3RYos'),
    (1422, 'To take down South Boston''s Irish Mafia, the police send in one of their own to infiltrate the underworld, not realizing the syndicate has done likewise. While an undercover cop curries favor with the mob kingpin, a career criminal rises through the police ranks. But both sides soon discover there''s a mole among them.', 151, '/nT97ifVT2J1yMQmeq20Qblg61T.jpg', '/6WRrGYalXXveItfpnipYdayFkQB.jpg', 'r-MiSNsCdQ4'),
    (1428, 'A corrupt CIA agent Sands hires hitman El Mariachi to assassinate a Mexican general hired by a drug kingpin attempting a coup d''état of the President of Mexico.', 102, '/ETUpGxmLocsfER8GT8w5sOkRG0.jpg', '/ctDqJtlMwASOKoQi7sacSVae3EI.jpg', '7JrCqCz6CBA'),
    (1443, 'A group of male friends become obsessed with five mysterious sisters who are sheltered by their strict, religious parents.', 97, '/1NCQtXPQnaHRjOZVmktA9BSM35F.jpg', '/6b6UpsOXmjO8mJKYsGTG9HW49CN.jpg', '8kDcCGlaBwY'),
    (1452, 'Superman returns to discover his 5-year absence has allowed Lex Luthor to walk free, and that those he was closest to felt abandoned and have moved on. Luthor plots his ultimate revenge that could see millions killed and change the face of the planet forever, as well as ridding himself of the Man of Steel.', 154, '/385XwTQZDpRX2d3kxtnpiLrjBXw.jpg', '/8eRscFbRYl681zDfkjv1jjW1KAA.jpg', 'zVCozSQj8TQ'),
    (1487, 'In the final days of World War II, the Nazis attempt to use black magic to aid their dying cause. The Allies raid the camp where the ceremony is taking place, but not before they summon a baby demon who is rescued by Allied forces and dubbed "Hellboy". Sixty years later, Hellboy serves the cause of good rather than evil as an agent in the Bureau of Paranormal Research & Defense, along with Abe Sapien - a merman with psychic powers, and Liz Sherman - a woman with pyrokinesis, protecting America against dark forces.', 122, '/21hS8mD8uxBVvf8xVYR30LbbmPO.jpg', '/avwEj8wiywFH6FZ6h2wzvyJpiH7.jpg', 'qc4-3QmiFak'),
    (1491, 'With his eye on a lovely aristocrat, a gifted illusionist named Eisenheim uses his powers to win her away from her betrothed, a crown prince. But Eisenheim''s scheme creates tumult within the monarchy and ignites the suspicion of a dogged inspector.', 110, '/1O9jUvqkHaGBMVRyOJz1AlkmALW.jpg', '/8ScGUtKTupr5rVLiXRmffjKMRhH.jpg', 'QngdF-55AGc'),
    (1493, 'When the local FBI office receives a letter from a terrorist known only as ''The Citizen'', it''s quickly determined that he''s planning his next act at the Miss America beauty pageant. Because tough-as-nails Gracie Hart is the only female agent at the office, she''s chosen to go undercover as the contestant from New Jersey.', 110, '/pat3vKaRlB70he4ghwTMydR4TvP.jpg', '/zcAcdUkb4u3JGYd9xcpXJfCRyV1.jpg', 'MSXZJDuNwJE'),
    (1495, 'After his wife dies, a blacksmith named Balian is thrust into royalty, political intrigue and bloody holy wars during the Crusades.', 144, '/2NaFdWy9hkM35vZB1hkqsnTcms8.jpg', '/kP8rK9dGS1pr0HrnmXfIi2heWjo.jpg', '6Z2wGCZ2fSM'),
    (1538, 'Cab driver Max picks up a man who offers him $600 to drive him around. But the promise of easy money sours when Max realizes his fare is an assassin.', 120, '/nV5316WUsVij8sVXLCF1g7TFitg.jpg', '/qVzmXKKOTtd3szkiCheCNrfa394.jpg', '-JDf2zIFgO8'),
    (1541, 'Taking a break from their dreary lives, close friends Thelma and Louise embark on a short weekend trip that ends in unforeseen incriminating circumstances. As fugitives, both women rediscover the strength of their bond and their newfound resilience.', 130, '/vbRAGLzbC75QfiKD1lKjmnQGuph.jpg', '/u49EZzHvGCNrHdQxkc3hhLmQEPP.jpg', 'g8Uti7PDLnI'),
    (1562, 'Twenty-eight weeks after the spread of a deadly rage virus, the inhabitants of the British Isles have lost their battle against the onslaught, as the virus has killed everyone there. Six months later, a group of Americans dare to set foot on the Isles, convinced the danger has passed. But it soon becomes all too clear that the scourge continues to live, waiting to pounce on its next victims.', 99, '/oix0aNv1lvW3nUGspUyvSIBlpbs.jpg', '/83ownpZPvBHJD5UVNShzQfa3LaW.jpg', 'gPOt4mAEfBE'),
    (1571, 'John McClane is back and badder than ever, and this time he calls on the services of a young hacker in his bid to stop a ring of Internet terrorists intent on taking control of America''s computer infrastructure.', 128, '/31TT47YjBl7a7uvJ3ff1nrirXhP.jpg', '/aRqTPOPt8BOHE0ngppM9jnuuaeS.jpg', 'svIjk-nlh_c'),
    (1572, 'New York detective John McClane is back and kicking bad-guy butt in the third installment of this action-packed series, which finds him teaming with civilian Zeus Carver to prevent the loss of innocent lives. McClane thought he''d seen it all, until a genius named Simon engages McClane, his new "partner" -- and his beloved city -- in a deadly game that demands their concentration.', 128, '/buqmCdFQEWwEpL3agGgg2GVjN2d.jpg', '/fBvSfLetWlAMevQVHa0nBDV1Fon.jpg', 'aRQetHOPpKA'),
    (1573, 'One year after his heroics in Los Angeles, John McClane is an off-duty cop who is the wrong guy in the wrong place at the wrong time. On a snowy Christmas Eve, as he waits for his wife''s plane to land at Washington Dulles International Airport, terrorists take over the air traffic control system in a plot to free a South American army general and drug smuggler being flown into the US to face drug charges. It''s now up to McClane to take on the terrorists, while coping with an inept airport police chief, an uncooperative anti-terrorist squad, and the life of his wife and everyone else trapped in planes circling overhead.', 124, '/ybki0UWO3OPhaM6MSniuKC7sy1R.jpg', '/cDtefl7KGnKrDziEUXetMnztvqr.jpg', 'IoZCfS5290M'),
    (1576, 'When a virus leaks from a top-secret facility, turning all resident researchers into ravenous zombies and their lab animals into mutated hounds from hell, the government sends in an elite military task force to contain the outbreak.', 100, '/1UKNef590A0ZaMnxsscIcWuK1Em.jpg', '/8J7J7CBmapmcMaxsn9KMiaHzOU2.jpg', 'HhBAIDHvRTc'),
    (1577, 'As the city is locked down under quarantine, Alice finds out that the people that died from the previous incident at the Umbrella Corporation have turned into zombies. She then joins a small band of elite soldiers, who are enlisted to rescue the missing daughter of the creator of the mutating T-virus.  Once lack of luck and resources happen, they begin to wage an exhilarating battle to survive and escape before the Umbrella Corporation erases its experiment from the face of the earth.', 94, '/r9j1FEYGGMkZAM47jFeVf4yTlVV.jpg', '/5PJP3NaiH9ZJRzrEHLeqSY5rNxb.jpg', 'PkutbYENBis'),
    (1578, 'The life of boxer Jake LaMotta, whose violence and temper that led him to the top in the ring destroyed his life outside of it.', 129, '/1WV7WlTS8LI1L5NkCgjWT9GSW3O.jpg', '/tvNuhRlpRozDgsX1zR9gQ2aHv1X.jpg', 'G5RHRg6zEhY'),
    (1579, 'Set in the Mayan civilization, when a man''s idyllic presence is brutally disrupted by a violent invading force, he is taken on a perilous journey to a world ruled by fear and oppression where a harrowing end awaits him. Through a twist of fate and spurred by the power of his love for his woman and his family he will make a desperate break to return home and to ultimately save his way of life.', 138, '/cRY25Q32kDNPFDkFkxAs6bgCq3L.jpg', '/nnmbJvYyDS1VkMOCbxSpdBi3WbJ.jpg', 'gSw5l5jMnPM'),
    (1580, 'Two young men attempt to prove they committed the perfect murder by hosting a dinner party for the family of a classmate they just strangled to death.', 81, '/9ar6rxLDB8kagAnXZKn6h9smscr.jpg', '/81LX4wktTXWEXjLNlkHTmJm7tRu.jpg', 'mTmEraaEY20'),
    (1581, 'Two women, one American and one British, swap homes at Christmastime following bad breakups. Each woman finds romance with a local man but realizes that the imminent return home may end the relationship.', 136, '/h1ITOpvJN3Tw4Sy60w2QTfYMvdd.jpg', '/9Ebn8atCcGk5OZrx4xmoTobAxoh.jpg', 'NLVLsyE4uUA'),
    (1584, 'Fired from his band and hard up for cash, guitarist and vocalist Dewey Finn finagles his way into a job as a fifth-grade substitute teacher at a private school, where he secretly begins teaching his straight-A students the finer points of rock ''n'' roll and the power of sticking it to the man. But as the school’s stern principal closes in and the Battle of the Bands looms, Dewey must risk everything to prove that rock ''n'' roll can change lives.', 110, '/zXLXaepIBvFVLU25DH3wv4IPSbe.jpg', '/k5MTAtE9CCi5TWA84qaFMYv3ajB.jpg', 'KdzWQT0wLCY'),
    (1585, 'George Bailey has spent his entire life giving to the people of Bedford Falls.  All that prevents rich skinflint Mr. Potter from taking over the entire town is George''s modest building and loan company.  But on Christmas Eve the business''s $8,000 is lost and George''s troubles begin.', 131, '/bSqt9rhDZx1Q7UZ86dBPKdNomp2.jpg', '/ch3lDc4xQ9MpsNEpnRhvR8PIxxK.jpg', 'iLR3gZrU2Xo'),
    (1586, 'Mort Rainey, a writer just emerging from a painful divorce with his ex-wife, is stalked at his remote lake house by a psychotic stranger and would-be scribe who claims Rainey swiped his best story idea. But as Rainey endeavors to prove his innocence, he begins to question his own sanity.', 96, '/hvzw4wufKZkDCTPVeG71Z7pGfZh.jpg', '/dBSYDUZpps3LWru7ofUZAYoFgUj.jpg', 'QboGT3v7c5A'),
    (1587, 'Gilbert Grape is a small-town young man with a lot of responsibility. Chief among his concerns are his mother, who is so overweight that she can''t leave the house, and his mentally impaired younger brother, Arnie, who has a knack for finding trouble. Settled into a job at a grocery store and an ongoing affair with local woman Betty Carver, Gilbert finally has his life shaken up by the free-spirited Becky.', 118, '/8FxWgsfDNosewo7H65oE4QkOb7g.jpg', '/m05zMH2I7aEOP4zc0JYOdqR4JUD.jpg', 'wpSGFets1oM'),
    (1592, 'Defense attorney Martin Vail takes on jobs for money and prestige rather than any sense of the greater good. His latest case involves an altar boy, accused of brutally murdering the archbishop of Chicago. Vail finds himself up against his ex-pupil and ex-lover, but as the case progresses and the Church''s dark secrets are revealed, Vail finds that what appeared a simple case takes on a darker, more dangerous aspect.', 130, '/qJf2TzE8nRTFbFMPJNW6c8mI0KU.jpg', '/dZM71rHXh3Oo3WZlw8YpMMsoVB5.jpg', 'PnmTi7hSjrA'),
    (1593, 'Chaos reigns at the natural history museum when night watchman Larry Daley accidentally stirs up an ancient curse, awakening Attila the Hun, an army of gladiators, a Tyrannosaurus rex and other exhibits.', 108, '/pDsAAYf6Zn0yiAGJ6lYGs6hoZ4E.jpg', '/1ZVlzOBYCggLzvVYHK7Im6LohjC.jpg', 'Ltba1_-tRT4'),
    (1597, 'Greg Focker is ready to marry his girlfriend, Pam, but before he pops the question, he must win over her formidable father, humorless former CIA agent Jack Byrnes, at the wedding of Pam''s sister. As Greg bends over backward to make a good impression, his visit to the Byrnes home turns into a hilarious series of disasters, and everything that can go wrong does, all under Jack''s critical, hawklike gaze.', 108, '/5tXJ9ctuyEOMUFLaeqRisbXowWs.jpg', '/qcVrlyPFlPgCsmzorvELvpJN9Be.jpg', 'wQJvx9yvc1U'),
    (1598, 'Sam Bowden is a small-town corporate attorney. Max Cady is a tattooed, cigar-smoking, Bible-quoting, psychotic rapist. What do they have in common? 14 years ago, Sam was a public defender assigned to Max Cady''s rape trial, and he made a serious error: he hid a document from his illiterate client that could have gotten him acquitted. Now, the cagey Cady has been released, and he intends to teach Sam Bowden and his family a thing or two about loss.', 128, '/meJZAAuVcjic2ipvbOPz5UlE4P9.jpg', '/ntgpger7OwFNlEldxuvvFHDKzjW.jpg', 'mPsOIhZJug4'),
    (1620, 'A genetically engineered assassin with deadly aim, known only as "Agent 47" eliminates strategic targets for a top-secret organization. But when he''s double-crossed, the hunter becomes the prey as 47 finds himself in a life-or-death game of international intrigue.', 89, '/h69UJOOKlrHcvhl5H2LY74N61DQ.jpg', '/sFAqIqo3ZvsXXLdwXYUEjB6owZu.jpg', '7A0DuqGfXqw'),
    (1621, 'A snobbish investor and a wily street con-artist find their positions reversed as part of a bet by two callous millionaires.', 116, '/8mBuLCOcpWnmYtZc4aqtvDXslv6.jpg', '/3FO1kbQmRlU1H6Kmn7sTfmd7mw9.jpg', 'Fupg2r1EJ9w'),
    (1624, 'Forced by his son''s birthday wish, fast-talking attorney and habitual liar Fletcher Reede must tell the truth for the next 24 hours.', 86, '/p1habYSdC7oD3WygQ5lynU5G5rV.jpg', '/nuDMG0uTaiWFVD6XfHPruum5JOL.jpg', 'odPUipiGYek'),
    (1635, 'In 2019, Lincoln Six-Echo is a resident of a seemingly "Utopian" but contained facility. Like all of the inhabitants of this carefully-controlled environment, Lincoln hopes to be chosen to go to The Island — reportedly the last uncontaminated location on the planet. But Lincoln soon discovers that everything about his existence is a lie.', 136, '/9MaZYEyFmQwNeDTxZGQEN8E0e4p.jpg', '/zZZ1FDl5FPClZ9OnMrlaPA4Iuxv.jpg', 'pZsDzeJh4nU'),
    (1636, 'Elliot Richards, a socially awkward IT worker, is given seven wishes to get the girl of his dreams when he meets a very seductive Satan. The catch: his soul. Some of his wishes include being a 7 foot basketball star, a wealthy, powerful man, and a sensitive caring guy. But, as could be expected, the Devil puts her own little twist on each of his fantasies.', 93, '/sBV28EVvWsJRosMsEFCbVmpAZEl.jpg', '/uaTVgIzIn02wd1SBTDXouGTpiIG.jpg', 'tDEfT9q07Ig'),
    (1637, 'Tensions run high when a crazed bomber rigs a Los Angeles bus with a device that will kill everyone on board if the vehicle''s speed dips below fifty miles per hour.', 116, '/82PkCE4R95KhHICUDF7G4Ly2z3l.jpg', '/lywmuPU5Hr1Mnpb9UGeDbILmkTx.jpg', '3q_4xiR3VJQ'),
    (1640, 'In post-Sept. 11 Los Angeles, tensions erupt when the lives of a Brentwood housewife, her district attorney husband, a Persian shopkeeper, two cops, a pair of carjackers and a Korean couple converge during a 36-hour period.', 112, '/86BdPC6RDX88NC880pLidKn2LCj.jpg', '/l5LNCgS4hbNMnt5acKFT9G3LcMl.jpg', 'dgepOrbliX4'),
    (1648, 'Two rock-''n-rolling teens, on the verge of failing their class, set out on a quest to make the ultimate school history report after being presented with a time machine.', 90, '/tV25lGWGWGEqUe3U0xjQTBgilSx.jpg', '/aMASmAmkn7NT0nEq8PBZEgwBfGN.jpg', 'gxFxklxvE_w'),
    (1669, 'A new technologically-superior Soviet nuclear sub, the Red October, is heading for the U.S. coast under the command of Captain Marko Ramius. The American government thinks Ramius is planning to attack. Lone CIA analyst Jack Ryan has a different idea: he thinks Ramius is planning to defect, but he has only a few hours to find him and prove it - because the entire Russian naval and air commands are trying to find Ramius, too. The hunt is on!', 135, '/yVl7zidse4KiWtGMqHFtZCx4X3N.jpg', '/5jCpCFrku6wmCZOYZWhHOC2j8IU.jpg', 'kxL8uBmdulY'),
    (1690, 'Three backpackers head to a Slovakian city that promises to meet their hedonistic expectations, with no idea of the hell that awaits them.', 94, '/dDrtuWUKhgUGp12kgUWuP0NpTdF.jpg', '/dF6GNQ0TnZkr1t4wBt36Xc0Pccd.jpg', 'R0ShE0EbcCA'),
    (1691, 'Three American college students studying abroad are lured to a Slovakian hostel, and discover the grim reality behind it.', 93, '/qB20aiY8Ah3pQikkBxm3j7jQVc8.jpg', '/7MorkyWQXVOi2XKYci6pIGbjb2x.jpg', ''),
    (1700, 'After an accident, acclaimed novelist Paul Sheldon is rescued by a nurse who claims to be his biggest fan.  Her obsession takes a dark turn when she holds him captive in her remote Colorado home and forces him to write back to life the popular literary character he killed off.', 107, '/klPO5oh1LOxiPpdDXZo1ADgpKcw.jpg', '/rUAn3Ul1tL7JXMjZ951UOI3F0UA.jpg', 'qM20YWFOGgY'),
    (1701, 'Newly-paroled former US Army ranger Cameron Poe is headed back to his wife, but must fly home aboard a prison transport flight dubbed "Jailbird" taking the “worst of the worst” prisoners, a group described as “pure predators”, to a new super-prison. Poe faces impossible odds when the transport plane is skyjacked mid-flight by the most vicious criminals in the country led by the mastermind — genius serial killer Cyrus "The Virus" Grissom, and backed by black militant Diamond Dog and psychopath Billy Bedlam.', 116, '/kOKjgrEzGOP92rVQ6srA9jtp60l.jpg', '/1pkFXLNHbP9ytuaNcLYKjaJSnxj.jpg', 'Sm3AAG6JyL4'),
    (1724, 'Scientist Bruce Banner scours the planet for an antidote to the unbridled force of rage within him: the Hulk. But when the military masterminds who dream of exploiting his powers force him back to civilization, he finds himself coming face to face with a new, deadly foe.', 114, '/gKzYx79y0AQTL4UAk1cBQJ3nvrm.jpg', '/xfBnQ4mgf1jYZsscJGJjr6ce0Ar.jpg', 'dz6eBeW19Lg'),
    (1726, 'After being held captive in an Afghan cave, billionaire engineer Tony Stark creates a unique weaponized suit of armor to fight evil.', 126, '/78lPtwv72eTNqFW9COBYI0dWDJa.jpg', '/cKvDv2LpwVEqbdXWoQl4XgGN6le.jpg', '8ugaeA-nMTc'),
    (1734, 'Rick and Evelyn O’Connell, along with their 8-year-old son Alex, discover the key to the legendary Scorpion King’s might: the fabled Bracelet of Anubis. Unfortunately, a newly resurrected Imhotep has designs on the bracelet as well, and isn’t above kidnapping its new bearer, Alex, to gain control of Anubis’s otherworldly army.', 130, '/kdJsW7hcy1lrj7tdMPycTAQPAiR.jpg', '/7s7WkAFPBsMTprYMbqbgKoppQsR.jpg', 'ptmLrNpmcBo'),
    (1735, 'Archaeologist Rick O''Connell travels to China, pitting him against an emperor from the 2,000-year-old Han dynasty who''s returned from the dead to pursue a quest for world domination. This time, O''Connell enlists the help of his wife and son to quash the so-called ''Dragon Emperor'' and his abuse of supernatural power.', 112, '/A3acM1lX5PNWQa6r5qeMAJOxbnT.jpg', '/W034dd7w2malON26KWyZm4y37W.jpg', 'ol-U0ibnVD4'),
    (1771, 'During World War II, Steve Rogers is a sickly man from Brooklyn who''s transformed into super-soldier Captain America to aid in the war effort. Rogers must stop the Red Skull – Adolf Hitler''s ruthless head of weaponry, and the leader of an organization that intends to use a mysterious device of untold powers for world domination.', 124, '/vSNxAJTlD0r02V9sPYpOjqDZXUK.jpg', '/yFuKvT4Vm3sKHdFY4eG6I4ldAnn.jpg', 'W4DlMggBPvc'),
    (1813, 'Aspiring Florida defense lawyer Kevin Lomax accepts a job at a New York law firm. With the stakes getting higher every case, Kevin quickly learns that his boss has something far more evil planned.', 144, '/5ZzBGpxy55OQzHxKVY11IpY6a0o.jpg', '/bFRyrzb16IqM8hTmxT0z1nCaqhr.jpg', 'etrZJJC4ox8'),
    (1817, 'A slick New York publicist who picks up a ringing receiver in a phone booth is told that if he hangs up, he''ll be killed... and the little red light from a laser rifle sight is proof that the caller isn''t kidding.', 81, '/5bRvXrcLmYz9ZNQsPIPqs7HVwb2.jpg', '/7JI7LrqD53rRVUBC0hoce65bDpb.jpg', 'PEDTSk69HcA'),
    (1824, 'Henry is a player skilled at seducing women. But when this veterinarian meets Lucy, a girl with a quirky problem when it comes to total recall, he realizes it''s possible to fall in love all over again…and again, and again. That''s because the delightful Lucy has no short-term memory, so Henry must woo her day after day until he finally sweeps her off her feet.', 99, '/lzUI2Cg7OMfcUNv3f7MywYNBjs6.jpg', '/v8lPo8UWKyP2tIXD8N64HfNP4Pw.jpg', '17KJk3ErIx0'),
    (1830, 'Yuri Orlov is a globetrotting arms dealer and, through some of the deadliest war zones, he struggles to stay one step ahead of a relentless Interpol agent, his business rivals and even some of his customers who include many of the world''s most notorious dictators. Finally, he must also face his own conscience.', 122, '/3MGQD4yXokufNlW1AyRXdiy7ytP.jpg', '/aDswjn9q5QCtLi7DaoJ21rq2pm8.jpg', 'AL8jpJkKUnM'),
    (1832, 'An abortion clinic worker with a special heritage is called upon to save the existence of humanity from being negated by two renegade angels trying to exploit a loophole and re-enter Heaven.', 130, '/oxhHl2YokTqcP44QK5tiTgjgLgk.jpg', '/nljRWpjfmqh5qYxcblFoazU5eYY.jpg', 'rwSRribTgdA'),
    (1844, 'Two thieves, who travel in elegant circles, try to outsmart each other and, in the process, end up falling in love.', 112, '/psrm7DToacaxQvgViBAcrYiLKzH.jpg', '/rsV4f4dzHyJIZ3WGNykh7K2WMHZ.jpg', 'LFSpRNtxd8I'),
    (1858, 'Young teenager Sam Witwicky becomes involved in the ancient struggle between two extraterrestrial factions of transforming robots – the heroic Autobots and the evil Decepticons. Sam holds the clue to unimaginable power and the Decepticons will stop at nothing to retrieve it.', 144, '/lkZ9gqCEjzX85lKR6Jjd1uGAXNp.jpg', '/iCDMBi6WLjUBnt24dNwHqqF81UL.jpg', 'ahYjx0rQvqQ'),
    (1865, 'When Jack crosses paths with a woman from his past, he''s not sure if it''s love...or if she''s a ruthless con artist using him to find the fabled Fountain of Youth.', 136, '/keGfSvCmYj7CvdRx36OdVrAEibE.jpg', '/uzIGtyS6bbnJzGsPL93WCF1FWm8.jpg', 'Ax6md6HoZ2o'),
    (1878, 'Raoul Duke and his attorney Dr. Gonzo drive a red convertible across the Mojave desert to Las Vegas with a suitcase full of drugs to cover a motorcycle race. As their consumption of drugs increases at an alarming rate, the stoned duo trash their hotel room and fear legal repercussions. Duke begins to drive back to L.A., but after an odd run-in with a cop, he returns to Sin City and continues his wild drug binge.', 118, '/tisNLcMkxryU2zxhi0PiyDFqhm0.jpg', '/hUzs26surgYxbHATjyDIyWat6ZL.jpg', 'Rx-EsbhLZLQ'),
    (1885, 'New Jersey teen Daniel LaRusso moves to Los Angeles with his mother, and soon strikes up a relationship with Ali. He quickly finds himself the target of bullying by a group of thugs, led by Ali''s ex-boyfriend Johnny, who study karate at the Cobra Kai dojo under ruthless sensei John Kreese. Fortunately, Daniel befriends Mr. Miyagi, an unassuming repairman who just happens to be a martial arts master himself. Miyagi takes Daniel under his wing, training him in a more compassionate form of karate for self-defense and, later, preparing him to compete against the brutal Cobra Kai.', 127, '/1mp4ViklKvA0WXXsNvNx0RBuiit.jpg', '/j1xaeJZOEOiVBD1rk3dg4YaAk23.jpg', 'r_8Rw16uscg'),
    (1887, 'A retelling of the story of France’s iconic but ill-fated queen, Marie Antoinette - from her betrothal and marriage to Louis XVI at fifteen to her reign as queen at nineteen and ultimately the fall of Versailles.', 123, '/cybXGmv8Rjd5Os8Xml6YxMBQ0Zt.jpg', '/9hxBNoRjEDZGjyR1JpmmtxJWmVU.jpg', 'fD7Uu2UU_nU'),
    (1891, 'The epic saga continues as Luke Skywalker, in hopes of defeating the evil Galactic Empire, learns the ways of the Jedi from aging master Yoda. But Darth Vader is more determined than ever to capture Luke. Meanwhile, rebel leader Princess Leia, cocky Han Solo, Chewbacca, and droids C-3PO and R2-D2 are thrown into various stages of capture, betrayal and despair.', 124, '/nNAeTmF4CtdSgMDplXTDPOpYzsX.jpg', '/k9pshruhCpJAdH9RaGJO6jaWQ4X.jpg', 'vU6L3jXt2r8'),
    (1892, 'Luke Skywalker leads a mission to rescue his friend Han Solo from the clutches of Jabba the Hutt, the Emperor prepares to crush the Rebellion with a more powerful Death Star, and the Rebel fleet mounts a massive attack on the space station. Luke Skywalker confronts Darth Vader in a final climactic duel before the evil Emperor.', 132, '/jQYlydvHm3kUix1f8prMucrplhm.jpg', '/ziECpBRIyclmBNaFSWlvCfsKbMD.jpg', 'MAW1E3JIQZE'),
    (1893, 'Anakin Skywalker, a young slave strong with the Force, is discovered on Tatooine. Meanwhile, the evil Sith have returned, enacting their plot for revenge against the Jedi.', 136, '/6wkfovpn7Eq8dYNKaG5PY3q2oq6.jpg', '/3TeGmKJfkik1D1rIoqGb1aR4k9c.jpg', 'J3kyYFHdRsM'),
    (1894, 'Following an assassination attempt on Senator Padmé Amidala, Jedi Knights Anakin Skywalker and Obi-Wan Kenobi investigate a mysterious plot into the heart of the Separatist movement and the beginning of the Clone Wars.', 142, '/oZNPzxqM2s5DyVWab09NTQScDQt.jpg', '/cxvr2IOTwHcQa3EqMoQ8RHCkqBG.jpg', 'gYbW1F_c9eM'),
    (1895, 'When the sinister Sith unveil a thousand-year-old plot to rule the galaxy, the Republic crumbles and from its ashes rises the evil Galactic Empire. Jedi hero Anakin Skywalker must choose a side.', 140, '/xfSAoBEm9MNBjmlNcDYLvLSMlnq.jpg', '/5vDuLrjJXFS9PTF7Q1xzobmYKR9.jpg', '5UnjrG_N8hU'),
    (1903, 'David Aames has it all: wealth, good looks and gorgeous women on his arm. But just as he begins falling for the warmhearted Sofia, his face is horribly disfigured in a car accident. That''s just the beginning of his troubles as the lines between illusion and reality, between life and death, are blurred.', 136, '/cAh2pCiNPftsY3aSqJuIOde7uWr.jpg', '/wwLufumafJojc59hgIamHyJSTO9.jpg', 'rRUnUbVB-eU'),
    (1907, 'Twenty-something Richard travels to Thailand and finds himself in possession of a strange map. Rumours state that it leads to a solitary beach paradise, a tropical bliss - excited and intrigued, he sets out to find it.', 119, '/4y7LxD8TSi6AtsM2xSYqUm1gu7u.jpg', '/gj4v8pmU6Noxrjry2upTAIQ88xF.jpg', 't99_nC_tYVM'),
    (1923, 'In the questionable town of Deer Meadow, Washington, FBI Agent Desmond inexplicably disappears while hunting for the man who murdered a teen girl. The killer is never apprehended, and, after experiencing dark visions and supernatural encounters, Agent Dale Cooper chillingly predicts that the culprit will claim another life. Meanwhile, in the more cozy town of Twin Peaks, hedonistic beauty Laura Palmer hangs with lowlifes and seems destined for a grisly fate.', 135, '/mxsGXqetGnirf99qapYd5MMY1VL.jpg', '/amGU1FpELmenVvNmPShW58Orepy.jpg', 'vCUxM9UZrd0'),
    (1924, 'Mild-mannered Clark Kent works as a reporter at the Daily Planet alongside his crush, Lois Lane. Clark must summon his superhero alter-ego when the nefarious Lex Luthor launches a plan to take over the world.', 144, '/d7px1FQxW4tngdACVRsCSaZq0Xl.jpg', '/5PfHGXosySGs0l1JfeREspy3v6G.jpg', 'xXyuUbtpmxE'),
    (1927, 'Bruce Banner, a genetics researcher with a tragic past, suffers massive radiation exposure in his laboratory that causes him to transform into a raging green monster when he gets angry.', 138, '/UllIft2jLSBaay3zQyMV4GNdfy.jpg', '/8vQBXqDbb30qNpBcNYwTesSg75.jpg', '2ErnLuJKQA4'),
    (1930, 'A teenage Peter Parker grapples with both high school and amazing super-human crises as his alter-ego Spider-Man.', 136, '/3zbb5XD0hEA8IpAcUmv1J9Rej3B.jpg', '/sxskOU71CO8LaNX2LOtjYFUtKv7.jpg', 'WLxul0Vzuhk'),
    (1933, 'Grace is a religious woman who lives in an old house kept dark because her two children, Anne and Nicholas, have a rare sensitivity to light. When the family begins to suspect the house is haunted, Grace fights to protect her children at any cost in the face of strange events and disturbing visions.', 101, '/p8g1vlTvpM6nr2hMMiZ1fUlKF0D.jpg', '/FY0NvzWMeCZeF3xdHIu0GtFHj7.jpg', '8upnnx2onik'),
    (1948, 'Chev Chelios, a hit man wanting to go straight, lets his latest target slip away. Then he awakes the next morning to a phone call that informs him he has been poisoned and has only an hour to live unless he keeps adrenaline coursing through his body while he searches for an antidote.', 88, '/rsKmhnvzJezjwC1Ud2Hh37oNpdQ.jpg', '/8JPz1636hMcaADngF4H4KOxXfp1.jpg', '218nsccFpag'),
    (1949, 'Police conduct a manhunt for the Zodiac Killer, a serial killer who terrorized the San Francisco Bay Area during the late 1960s and early 1970s, taunting police with letters, bloodstained clothing, and ciphers mailed to newspapers.', 157, '/6YmeO4pB7XTh8P8F960O1uA14JO.jpg', '/3zCPI4JFc54xvLaJ71oI2KoP3az.jpg', 'yNncHPl1UXg'),
    (1954, 'A young man struggles to access sublimated childhood memories. He finds a technique that allows him to travel back into the past, to occupy his childhood body and change history. However, he soon finds that every change he makes has unexpected consequences.', 113, '/ea5iv7TWMh18fOKoRGgmtcg85Gx.jpg', '/75UPGUm2Zm6M60szq1gQisDF4g.jpg', 'KctopagSGJE'),
    (1955, 'A Victorian surgeon rescues a heavily disfigured man being mistreated by his "owner" as a side-show freak. Behind his monstrous façade, there is revealed a person of great intelligence and sensitivity.', 124, '/u0wpPYjuSt8DIe1Y3Vapnh8jcKE.jpg', '/6huSptAsqYg3wbsi1jbMognSgmp.jpg', 'kxb_1457gGs'),
    (1966, 'Alexander, the King of Macedonia, leads his legions against the giant Persian Empire. After defeating the Persians, he leads his army across the then-known world, venturing farther than any Westerner had ever gone, all the way to India.', 176, '/jrwQu72sGwGqwE8Ijne89PSIvhp.jpg', '/h21dxRjtR7xOhyZljtSYeTETCht.jpg', 'oBn3VzXtuWc'),
    (1979, 'The Fantastic Four return to the big screen as a new and all powerful enemy threatens the Earth. The seemingly unstoppable ''Silver Surfer'', but all is not what it seems and there are old and new enemies that pose a greater threat than the intrepid superheroes realize.', 92, '/9wRfzTcMyyzkQxVDqBHv8RwuZOv.jpg', '/o2wYH40zW0JIYiYUTu6L4gsNy7E.jpg', '7whodtti908'),
    (1991, 'Austin''s hottest DJ, Jungle Julia, sets out into the night to unwind with her two friends Shanna and Arlene. Covertly tracking their moves is Stuntman Mike, a scarred rebel leering from behind the wheel of his muscle car, revving just feet away.', 113, '/vtu6H4NWnQVqEp3aanUq3hNeeot.jpg', '/qbVCChwbGWDAgsCXKZxyjBrRiWx.jpg', 'EAPy76vxF5s'),
    (1992, 'Two doctors find their graveyard shift inundated with townspeople ravaged by sores. Among the wounded is Cherry Darling, a dancer whose leg was ripped from her body. As the invalids quickly become enraged aggressors, Cherry and her ex-boyfriend El Wray lead a team of accidental warriors into the night.', 105, '/30ANoUgvqQZ9tgCnM6OyJZUveaf.jpg', '/iZBUOcku0xv9MMfiEMXiDqErPXl.jpg', 'j1cjXKdox0M'),
    (1995, 'Orphaned heiress, English aristocrat and intrepid archaeologist, Lara Croft, embarks on a dangerous quest to retrieve the two halves of an ancient artifact which controls time before it falls into the wrong hands. As an extremely rare planetary alignment is about to occur for the first time in 5,000 years, the fearless tomb raider will have to team up with rival adventurers and sworn enemies to collect the pieces, while time is running out. But, in the end, who can harness the archaic talisman''s unlimited power?', 101, '/sJpl1EfHGZhbKtZ3fWTlwrpM1tH.jpg', '/bL41GVWvp4YJDJ50PDcxaN4cds9.jpg', 'XiC4PDCGigE'),
    (1996, 'Off the coast of the volcanic island of Santorini, the intrepid archaeologist Lara Croft makes the unexpected discovery of a pulsating golden orb able to guide its holder to the mythical Pandora''s Box. As the legendary artifact contains ancient mysteries of unfathomable power - said to contain one of the deadliest plagues on Earth, Lara is tasked by MI6 to make sure it doesn''t fall into the wrong hands. With the aid of former Marine turned mercenary Terry Sheridan, she travels the world in pursuit of the precious item in a race against time; she must beat the unscrupulous Nobel Prize-winning scientist turned bioterrorist, Jonathan Reiss, to it.', 117, '/fp5qax3zSQcGtX96Vrwv428oNMq.jpg', '/lyCPWvJJSLgUo62USdnvqOVJfGi.jpg', 'q5VugO68swI'),
    (2005, 'When lively lounge singer Deloris sees her mobster beau commit murder, she is relocated for her protection. Set up in the guise of a nun in a California convent, she proceeds to upend the quiet lives of the resident sisters.', 100, '/xZvVSZ0RTxIjblLV87vs7ADM12m.jpg', '/bNiBuekwqwNKFGSqlJRDZIF4ADB.jpg', 'lCBjHkCK1Vw'),
    (2024, 'After proving himself on the field of battle in the French and Indian War, Benjamin Martin wants nothing more to do with such things, preferring the simple life of a farmer. But when his son Gabriel enlists in the army to defend their new nation, America, against the British, Benjamin reluctantly returns to his old life to protect his son.', 165, '/fWZd815QxUCUcrWQZwUkAp9ljG.jpg', '/8J10PcjUuJlk3BG3BMHlUOiIUpM.jpg', 'OpKR4qTOVgI'),
    (2034, 'On his first day on the job as a narcotics officer, a rookie cop works with a rogue detective who isn''t what he appears.', 122, '/bUeiwBQdupBLQthMCHKV7zv56uv.jpg', '/nuO8o9ltxhI7AZQxePavEZ4TyHa.jpg', 'VQ-SCoyUwfg'),
    (2048, 'In 2035, where robots are commonplace and abide by the three laws of robotics, a technophobic cop investigates an apparent suicide. Suspecting that a robot may be responsible for the death, his investigation leads him to believe that humanity may be in danger.', 115, '/efwv6F2lGaghjPpBRSINHtoEiZB.jpg', '/jpFcZH2eyh6gcoxCa637TrGe4bT.jpg', 'ry1N9lrzt7A'),
    (2059, 'Modern treasure hunters, led by archaeologist Ben Gates, search for a chest of riches rumored to have been stashed away by George Washington, Thomas Jefferson and Benjamin Franklin during the Revolutionary War. The chest''s whereabouts may lie in secret clues embedded in the Constitution and the Declaration of Independence, and Gates is in a race to find the gold before his enemies do.', 131, '/jKbZBMRFpF2EfFuvrsDZ2uQYsEQ.jpg', '/9EnZD3ZWjpJy4IPoQkqTzxvZrso.jpg', 'I0u9-5lPP4Q'),
    (2062, 'In one of Paris''s finest restaurants, Remy, a determined young rat, dreams of becoming a renowned French chef. Torn between his family''s wishes and his true calling, Remy and his pal Linguini set in motion a hilarious chain of events that turns the City of Lights upside down.', 111, '/t3vaWRPSf6WjDSamIkKDs1iQWna.jpg', '/zeoaHdXRDd5IoUiMVsNhwTZm78B.jpg', 'NgsQ8mVkN8w'),
    (2080, 'After seeking to live a normal life after 200 years, Logan sets out to avenge a death by undergoing the mutant Weapon X program and becoming Wolverine.', 107, '/yj8LbTju1p7CUJg7US2unSBk33s.jpg', '/p4GzAzjlL7lXIVGvayg7zvzGTSi.jpg', '8TQ-gD4UCmI'),
    (2082, 'The early years of young Michael Myers and the events leading up to his fateful Halloween night murder rampage in the quiet town of Haddonfield, Illinois.', 110, '/cD8JrfSEI4j7WVnKM1GdiYzMoUh.jpg', '/uEnA2AKtrpX4LCZ98hBLwVkhJEd.jpg', '4DvAAGrxT3I'),
    (2105, 'At a high-school party, four friends find that losing their collective virginity isn''t as easy as they had thought. But they still believe that they need to do so before college. To motivate themselves, they enter a pact to all "score" by their senior prom.', 95, '/5P68by2Thn8wHAziyWGEw2O7hco.jpg', '/cvH1gNIMRITdLzoWv1HNAbRyH3n.jpg', 'YXd7ruWo9Gg'),
    (2108, 'Five high school students from different walks of life endure a Saturday detention under a power-hungry principal. The disparate group includes rebel John, princess Claire, outcast Allison, brainy Brian and Andrew, the jock. Each has a chance to tell his or her story, making the others see them a little differently -- and when the day ends, they question whether school will ever be the same.', 98, '/gp4zlj7wgbiofLMNsTPndMuO3PN.jpg', '/s5HDOmFZaPVQFjk9BxxDrLu1T0g.jpg', 'c7VUZ29Ezcc'),
    (2109, 'When Hong Kong Inspector Lee is summoned to Los Angeles to investigate a kidnapping, the FBI doesn''t want any outside help and assigns cocky LAPD Detective James Carter to distract Lee from the case. Not content to watch the action from the sidelines, Lee and Carter form an unlikely partnership and investigate the case themselves.', 97, '/3WsLE6FtxEPRa6U9sbY1ckrn39s.jpg', '/9FrpAtF87VKblKkDEiIZzYgO40K.jpg', 'hgrQLDbs1qU'),
    (2118, 'Three detectives in the corrupt and brutal L.A. police force of the 1950s use differing methods to uncover a conspiracy behind the shotgun slayings of the patrons at an all-night diner.', 138, '/7jqrauDn3HabyvKfeKTBjzKNeom.jpg', '/hUn13Hom8OWMYpR1ay0diwswwdP.jpg', 'QeIoelqDzsA'),
    (2123, 'Rhode Island State Trooper Charlie Baileygates has a multiple personality disorder. One personality is crazy and aggressive, while the other is more friendly and laid back. Both of these personalities fall in love with the same woman named Irene after Charlie loses his medication.', 117, '/rvRrcbLbpn7UJGRH1JupgHOeJFq.jpg', '/8qLen3NLCVSu1I9aqGWbTUIoBLQ.jpg', 'UBPHrX4x3Ns'),
    (2164, 'An interstellar teleportation device, found in Egypt, leads to a planet with humans resembling ancient Egyptians who worship the god Ra.', 121, '/4T6Po0XnZlevmhfPh3ZfEs5butR.jpg', '/s2bqHApZlliCuwgyHod0qucrYqZ.jpg', 'c3sgzrgpn8s'),
    (2252, 'A Russian teenager living in London dies during childbirth but leaves clues in her diary that could tie her child to a rape involving a violent Russian mob family.', 100, '/nLwv1pxRCRZucQaqs6oPkq7HH3K.jpg', '/1ckHUJ6ztq5XJRKM2nIAW0UjJNH.jpg', 'ifilHp3_dWQ'),
    (2253, 'Wounded in Africa during World War II, Nazi Col. Claus von Stauffenberg returns to his native Germany and joins the Resistance in a daring plan to create a shadow government and assassinate Adolf Hitler. When events unfold so that he becomes a central player, he finds himself tasked with both leading the coup and personally killing the Führer.', 121, '/8eoRtXswC8IQDsqW7iJWO56NhAv.jpg', '/1F7cnW3Tf8IDJO64MxtuPhHDcQp.jpg', 'DlRCilnho1w'),
    (2268, 'In a parallel universe, after overhearing a shocking secret, precocious orphan Lyra Belacqua trades her carefree existence roaming the halls of Jordan College for an otherworldly adventure in the far North, unaware that it''s part of her destiny.', 113, '/6DTH9poR8RAw859L6OuokT7z993.jpg', '/qifYc5jT4CZxmLH9DfOlipioSPp.jpg', 'x7u-Ve9kBeQ'),
    (2270, 'In a countryside town bordering on a magical land, a young man makes a promise to his beloved that he''ll retrieve a fallen star by venturing into the magical realm. His journey takes him into a world beyond his wildest dreams and reveals his true identity.', 127, '/le1gPiqeWrCj5FkjBtcF9clFmdX.jpg', '/x2LTysjFSpeK0d40zHw6Lqd4oAH.jpg', 'VfYBKDyF-Dk'),
    (2277, 'Richard Martin buys a gift, a new NDR-114 robot. The product is named Andrew by the youngest of the family''s children. "Bicentennial Man" follows the life and times of Andrew, a robot purchased as a household appliance programmed to perform menial tasks. As Andrew begins to experience emotions and creative thought, the Martin family soon discovers they don''t have an ordinary robot.', 131, '/wrs23eO0VEWwOQpXoOasMnlW9Y4.jpg', '/aIVL5crQCBMPxKMoExiIsUDFPeR.jpg', 'NRFxf-2J1GM'),
    (2280, 'When a young boy makes a wish at a carnival machine to be big, he wakes up the following morning to find that it has been granted and his body has grown older overnight, but he is still the same 13-year-old boy inside. Now he must learn how to cope with the unfamiliar world of grown-ups, including getting a job and having his first romantic encounter with a woman.', 104, '/eWhCDJiwxvx3YXkAFRiHjimnF0j.jpg', '/bi9ihIMB9DoXs7odkS5oKkHoK2o.jpg', 'YM8zgY7sG_g'),
    (2288, 'The relationships of two couples become complicated and deceitful when the man from one couple meets the woman of the other.', 104, '/fGGaokx4k00S0J603VG53Qlr9jz.jpg', '/s7oDV92ltdecJ7BTfGSOgsDi900.jpg', 'bZ6nilkuYeo'),
    (2292, 'Convenience and video store clerks Dante and Randal are sharp-witted, potty-mouthed and bored out of their minds. So in between needling customers, the counter jockeys play hockey on the roof, visit a funeral home and deal with their love lives.', 92, '/9IiSgiq4h4siTIS9H3o4nZ3h5L9.jpg', '/sjfbZVKRGh84lNxhqvuhdvovh18.jpg', 'f8yqQkABBjY'),
    (2300, 'With their freedom on the line, the Looney Tunes seek the help of NBA superstar Michael Jordan to win a basketball game against a team of moronic aliens.', 87, '/4RN5El3Pj2W4gpwgiAGLVfSJv2g.jpg', '/lWybXICZZpxnSvWSOW53XxTERUg.jpg', 'v98aXG562h4'),
    (2309, 'The adventures of a father and his young daughter, in their search for a long lost book that will help reunite a missing, close relative.', 106, '/eXFK5aBDzUPSynAhSKMJy7xLxqE.jpg', '/dA1IWByfIvTktERGU4bzQqD3Xu8.jpg', '8k24gVJxnZ4'),
    (2395, 'Astérix and Obélix have to win the Olympic Games in order to help their friend Alafolix marry Princess Irina. Brutus uses every trick in the book to have his own team win the game, and get rid of his father Julius Caesar in the process.', 116, '/eNB2SrqmTJLByRDq3akDzA6Z9rC.jpg', '/2PuEmuXQF3XQZp8Ki2mGJXUGEOd.jpg', 'I4IwYe5N1o0'),
    (2454, 'One year after their incredible adventures in the Lion, the Witch and the Wardrobe, Peter, Edmund, Lucy and Susan Pevensie return to Narnia to aid a young prince whose life has been threatened by the evil King Miraz. Now, with the help of a colorful cast of new characters, including Trufflehunter the badger and Nikabrik the dwarf, the Pevensie clan embarks on an incredible quest to ensure that Narnia is returned to its rightful heir.', 150, '/qxz3WIyjZiSKUhaTIEJ3c1GcC9z.jpg', '/9pBv1BOSloAUgAkF0meJWdnbV4Q.jpg', 'icnmPD3QitY'),
    (2493, 'In this enchantingly cracked fairy tale, the beautiful Princess Buttercup and the dashing Westley must overcome staggering odds to find happiness amid six-fingered swordsmen, murderous princes, Sicilians and rodents of unusual size. But even death can''t stop these true lovebirds from triumphing.', 99, '/2FC9L9MrjBoGHYjYZjdWQdopVYb.jpg', '/onACwa3TjpeaY7EVHSZZbeNkd2q.jpg', 'KmXptjknRa8'),
    (2501, 'Wounded to the brink of death and suffering from amnesia, Jason Bourne is rescued at sea by a fisherman. With nothing to go on but a Swiss bank account number, he starts to reconstruct his life, but finds that many people he encounters want him dead. However, Bourne realizes that he has the combat and mental skills of a world-class spy—but who does he work for?', 119, '/aP8swke3gmowbkfZ6lmNidu0y9p.jpg', '/kJaRWmy1BGq3pHyE94LOTteiHer.jpg', 'PGKK5wACwrU'),
    (2502, 'A CIA operation to purchase classified Russian documents is blown by a rival agent, who then shows up in the sleepy seaside village where Bourne and Marie have been living. The pair run for their lives and Bourne, who promised retaliation should anyone from his former life attempt contact, is forced to once again take up his life as a trained assassin to survive.', 108, '/jupG9sFT64YwM8PSkwkUD2wHcYD.jpg', '/fE7RqvVHbGHjBC9NjIjlLh2t4zK.jpg', 'zsrdBGr8NIk'),
    (2503, 'Bourne is brought out of hiding once again by reporter Simon Ross who is trying to unveil Operation Blackbriar, an upgrade to Project Treadstone, in a series of newspaper columns. Information from the reporter stirs a new set of memories, and Bourne must finally uncover his dark past while dodging The Company''s best efforts to eradicate him.', 115, '/15rMz5MRXFp7CP4VxhjYw4y0FUn.jpg', '/qiBILuWhv7ipF0pxiEqIJdkQzj8.jpg', 'ohkW_xbPl9A'),
    (2567, 'A biopic depicting the life of filmmaker and aviation pioneer Howard Hughes from 1927 to 1947, during which time he became a successful film producer and an aviation magnate, while simultaneously growing more unstable due to severe obsessive-compulsive disorder.', 170, '/lx4kWcZc3o9PaNxlQpEJZM17XUI.jpg', '/2RICPuzwGAVNktqiyptouqjgeXM.jpg', 'dkwypzOQf8o'),
    (2642, 'Dedicated environmental lawyer Lucy Kelson goes to work for billionaire George Wade as part of a deal to preserve a community center. Indecisive and weak-willed George grows dependent on Lucy''s guidance on everything from legal matters to clothing. Exasperated, Lucy gives notice and picks Harvard graduate June Carter as her replacement. As Lucy''s time at the firm nears an end, she grows jealous of June and has second thoughts about leaving George.', 101, '/r18hSGAcxWiUysbX6nFShIZyjjP.jpg', '/owRq5hVmyLv8pNx3Kn1dmE6AQOm.jpg', '_guQ-_EFmHU'),
    (2649, 'In honor of his birthday, San Francisco banker Nicholas Van Orton, a financial genius and a cold-hearted loner, receives an unusual present from his younger brother, Conrad: a gift certificate to play a unique kind of game. In nary a nanosecond, Nicholas finds himself consumed by a dangerous set of ever-changing rules, unable to distinguish where the charade ends and reality begins.', 129, '/eRInC7NTiDkt6dnm7Ryzu4hQZEs.jpg', '/k7GM13qRYSour3lk90Dq1EwdpoW.jpg', 'DnhDqMJcKZ4'),
    (2652, 'Hayley’s a smart, charming teenage girl. Jeff’s a handsome, smooth fashion photographer. An Internet chat, a coffee shop meet-up, an impromptu fashion shoot back at Jeff’s place. Jeff thinks it’s his lucky night. He’s in for a surprise.', 104, '/uHTmlcivbPeclEdmtuQg3zOQWPS.jpg', '/9uYq1A9mx4wvQ8J6OF8BXUntciQ.jpg', 'hvx0m2SeOSk'),
    (2667, 'In October of 1994 three student filmmakers disappeared in the woods near Burkittsville, Maryland, while shooting a documentary. A year later their footage was found.', 81, '/9050VGrYjYrEjpOvDZVAngLbg1f.jpg', '/ghPJw3XfhELokIf6V5QL0VpsXtK.jpg', 'AcTh2YItSaM'),
    (2668, 'Skeptical young detective Ichabod Crane gets transferred to the hamlet of Sleepy Hollow, New York, where he is tasked with investigating the decapitations of three people – murders the townsfolk attribute to a legendary specter, The Headless Horseman.', 105, '/1GuK965FLJxqUw9fd1pmvjbFAlv.jpg', '/m8t7K3LcAY7bpyQ7iQ5kGsrcjnh.jpg', 'XB-y10r77V8'),
    (2675, 'A family living on a farm finds mysterious crop circles in their fields which suggests something more frightening to come.', 106, '/YtrIdrTxpRhvCnlw43dwOjfLqx.jpg', '/rsPjEr7o02mo8ex6wD2PbRwasUe.jpg', 'T-wgoJv9UAI'),
    (2698, 'God contacts Junior Congressman Evan Baxter and tells him to build an ark in preparation for a great flood.', 96, '/blI1ioXbgJWOJ3PbcBuSV65Ebwu.jpg', '/yVwCXQzSZvg9H0YBXvzPfSs6Vqx.jpg', 'R1QArbkQsVw'),
    (2757, 'Charlie Kaufman is a confused L.A. screenwriter overwhelmed by feelings of inadequacy, sexual frustration, self-loathing, and by the screenwriting ambitions of his freeloading twin brother Donald. While struggling to adapt "The Orchid Thief," by Susan Orlean, Kaufman''s life spins from pathetic to bizarre. The lives of Kaufman and Orlean''s book become strangely intertwined as each one''s search for passion collides with the other''s.', 115, '/ffEmHQAiD0m5dEQ6rlsuA9vlllW.jpg', '/mkjdussWOjts0Se6hEwfTQdwCv2.jpg', 'pK5jYt9QNIY'),
    (2758, 'Siblings Wednesday and Pugsley Addams will stop at nothing to get rid of Pubert, the new baby boy adored by parents Gomez and Morticia. Things go from bad to worse when the new "black widow" nanny, Debbie Jellinsky, launches her plan to add Fester to her collection of dead husbands.', 94, '/sdxT2VjVSx9DRicwnuECUdBHeE7.jpg', '/sZhTfYouKM1iV3rVbgIVEQFQogA.jpg', 'Bb2FTulPpOA'),
    (2770, 'After a year apart - attending different schools, meeting different people - the guys rent a beach house and vow to make this the best summer ever. As it turns out, whether that will happen or not has a lot to do with the girls. Between the wild parties, outrageous revelations and yes, a trip to band camp, they discover that times change and people change, but in the end, it''s all about sticking together.', 111, '/854ZZxXdeabAs90mrV72NqShJqR.jpg', '/as3gvp4DIXVRlXsj5x7OWPQI5lI.jpg', 'ntxIBzJ0tU8'),
    (2787, 'When their ship crash-lands on a remote planet, the marooned passengers soon learn that escaped convict Riddick isn''t the only thing they have to fear. Deadly creatures lurk in the shadows, waiting to attack in the dark, and the planet is rapidly plunging into the utter blackness of a total eclipse. With the body count rising, the doomed survivors are forced to turn to Riddick with his eerie eyes to guide them through the darkness to safety. With time running out, there''s only one rule: Stay in the light.', 108, '/3AnlxZ5CZnhKKzjgFyY6EHxmOyl.jpg', '/bMJdVmo6QqoUHpUsjWyei6MN02x.jpg', 'mEJ8e8S4hOw'),
    (2789, 'After years of outrunning ruthless bounty hunters, escaped convict Riddick suddenly finds himself caught between opposing forces in a fight for the future of the human race. Now, waging incredible battles on fantastic and deadly worlds, this lone, reluctant hero will emerge as humanity''s champion - and the last hope for a universe on the edge of annihilation.', 119, '/bVO1r90diKfFLzvZ5D3qK6Z558O.jpg', '/lt3NqorBMWn786m9bzqM0OLdMS8.jpg', '6kVvQ1Rtb9k'),
    (2832, 'Complete strangers stranded at a remote desert motel during a raging storm soon find themselves the target of a deranged murderer. As their numbers thin out, the travelers begin to turn on each other, as each tries to figure out who the killer is.', 90, '/sYgimsiBywqVwJI8H4sETke8m7v.jpg', '/5uf2KaYDecr2vTuKfArQN5EHIDx.jpg', '2ReUIVKB4to'),
    (2898, 'A misanthropic author, a single mother and waitress, and a gay artist form an unlikely friendship after the artist is assaulted in a robbery.', 139, '/xXxuJPNUDZ0vjsAXca0O5p3leVB.jpg', '/x7y8ezKtU1vRInk0dmbvDoKgJ8u.jpg', 't2d89afgtqg'),
    (2899, 'History''s favorite Gauls assist Queen Cleopatra when she wagers that the Egyptian people can build a palace for Julius Caesar in just three months.', 108, '/i4k9LPyy2j5d6m5bzDaZj0E7eR7.jpg', '/2kpPVHLvkHfsc9uurzmEB1PoC6R.jpg', '_MPJs0vD_oQ'),
    (2907, 'When a man claiming to be long-lost Uncle Fester reappears after 25 years lost, the family plans a celebration to wake the dead. But the kids barely have time to warm up the electric chair before Morticia begins to suspect Fester is fraud when he can''t recall any of the details of Fester''s life.', 100, '/qFf8anju5f2epI0my8RdwwIXFIP.jpg', '/7OxGhxUYAdtuike29VMzEFxJx7y.jpg', 'A6X4VAHdDVg'),
    (2976, 'Pleasantly plump teenager Tracy Turnblad auditions to be on Baltimore''s most popular dance show - The Corny Collins Show - and lands a prime spot. Through her newfound fame, she becomes determined to help her friends and end the racial segregation that has been a staple of the show.', 116, '/fgMka3HtFvI5OgW1eYdR9XpySxH.jpg', '/oO55Z71apssUy4Cf0obsK2kX3oK.jpg', 'hsFtWsRn99U'),
    (2978, 'The discovery of a massive river of ectoplasm and a resurgence of spectral activity allows the staff of Ghostbusters to revive the business.', 108, '/iUZPi31KDP0n5ycpycEsvl51BdV.jpg', '/tgHO1DdnaS0xHcRxBHxE4kOQeIm.jpg', 'weIqC-oUGmA'),
    (3021, 'A man specializing in debunking paranormal occurrences checks into the fabled room 1408 at the Dolphin Hotel. Soon after settling in, he confronts genuine terror.', 104, '/yE9MCW7ZNxSw5SC1TMqm51pMBIV.jpg', '/a4ZupLMg23auAw8e1j1K39PCO6z.jpg', 'lgLm4_fq6GY'),
    (3034, 'A young neurosurgeon inherits the castle of his grandfather, the famous Dr. Victor von Frankenstein. In the castle he finds a funny hunchback, a pretty lab assistant and the elderly housekeeper. Young Frankenstein believes that the work of his grandfather was delusional, but when he discovers the book where the mad doctor described his reanimation experiment, he suddenly changes his mind.', 106, '/3BvvVKPg9yucChlSvQtJxAbLmj9.jpg', '/nqwQwxnxX5UO2vxAyWF3N0usRS6.jpg', 'jAyNV6UZqOg'),
    (3049, 'He''s Ace Ventura: Pet Detective. The Ace is on the case to find the Miami Dolphins'' missing mascot and quarterback Dan Marino. He goes eyeball to eyeball with a man-eating shark, stakes out the Miami Dolphins and woos and wows the ladies. Whether he''s undercover, under fire or underwater, he always gets his man… or beast!', 86, '/pqiRuETmuSybfnVZ7qyeoXhQyN1.jpg', '/mhMnWStdREZiYrWpm1MqTS7J2V5.jpg', 'Lc0bgXhpmAE'),
    (3050, 'A successful physician and devoted family man, John Dolittle seems to have the world by the tail, until a long suppressed talent he possessed as a child, the ability to communicate with animals is suddenly reawakened with a vengeance! Now every creature within squawking distance wants the good doctor''s advice, unleashing an outrageous chain of events that turns his world upside down!', 85, '/tLrchGMIkdo1KamQJA6fwvDQEy0.jpg', '/kqUjxYB209bPN0DpfXZuR9E4ERW.jpg', 'LWbtxG-jXMY'),
    (3082, 'A bumbling tramp desires to build a home with a young woman, yet is thwarted time and time again by his lack of experience and habit of being in the wrong place at the wrong time...', 87, '/uEMekS25hwXrCJOZZ3NKMGcAFJo.jpg', '/kSlO1pHpwQfPQdgVPr7dJiJNtJ8.jpg', 'NNznUyDmSFc'),
    (3131, 'In early 1860s New York, Irish immigrant Amsterdam Vallon is released from prison and returns to the Five Points, seeking revenge against his father''s killer, William Cutting, a powerful anti-immigrant gang leader. He knows that revenge can only be attained by infiltrating Cutting''s inner circle. Vallon''s journey becomes a fight for personal survival and to find a place for the Irish people.', 168, '/lemqKtcCuAano5aqrzxYiKC8kkn.jpg', '/a2Aj5ksEo2HOUH3FbGyZCtaJM4C.jpg', '1bjh979vVG0'),
    (3175, 'An Irish rogue uses his cunning and wit to work his way up the social classes of 18th century England, transforming himself from the humble Redmond Barry into the noble Barry Lyndon.', 188, '/A0byHUHMwZ7dtBQtfZ44QIgDbjo.jpg', '/okdg55jhsr9k1F2lxsZoQncrLZL.jpg', 'JH8j_1dUlUU'),
    (3176, 'In the future, the Japanese government captures a class of ninth-grade students and forces them to kill each other under the revolutionary "Battle Royale" act.', 114, '/aLGKAQKgzWpJ6egyWzzC11jXBRJ.jpg', '/gtYmm8HeM6CneomZ98flixAGsBe.jpg', 's4AFmGjndAA'),
    (3580, 'Los Angeles, 1928. When single mother Christine Collins leaves for work, her son vanishes without a trace. Five months later, the police reunite mother and son. But when Christine suspects that the boy returned to her isn''t her child, her quest for truth exposes a world of corruption.', 142, '/y9Qi39dL3PceGCH8afyC7QrhbhI.jpg', '/yWs9QUP2kamsnfdV4cloxLM5RUw.jpg', 'IF5hwg4FNEU'),
    (3594, 'Animal control officer Walter Sparrow becomes obsessed with a novel that he believes was written about him, as more and more similarities between himself and his literary alter ego seem to arise.', 97, '/iPJwdvgX3I5dEw9QhDOG3hxUvMp.jpg', '/bjg50B6cGXaeGv8dV8v5U8bJ7jW.jpg', 'TUTlOC4mVQ8'),
    (3595, 'When a rich man''s son is kidnapped, he cooperates with the police at first but then tries a unique tactic against the criminals.', 121, '/4nmOA5ZOY2VlHzwSlKY03sF2JUz.jpg', '/vb6JwkHIcKiVvYrUFzuZbN7nUqN.jpg', 'fIo43xs25DQ'),
    (3597, 'After an accident on a winding road, four teens make the fatal mistake of dumping their victim''s body into the sea. Exactly one year later, the deadly secret resurfaces as they''re stalked by a hook-handed figure.', 102, '/dQyaJx0SptDqvQcAewAr8FAtLB2.jpg', '/q21bYziiGDyzKm4RppVbP46u70B.jpg', 'rEnCEM48QaY'),
    (3933, 'In a 19th-century European village, a young man about to be married is whisked away to the underworld and wed to a mysterious corpse bride, while his real bride waits bereft in the land of the living.', 77, '/3RAoVTxUk1OzZClscAsynuu670p.jpg', '/v23fWgJUEt8EMmvn19btIacxP8E.jpg', 'BgwJEpmPKk8'),
    (3981, 'Advertising executive Nick Marshall is as cocky as they come, but what happens to a chauvinistic guy when he can suddenly hear what women are thinking? Nick gets passed over for a promotion, but after an accident enables him to hear women''s thoughts, he puts his newfound talent to work against Darcy, his new boss, who seems to be infatuated with him.', 127, '/eqkBEMDk1316Yx5wVoabWY07JAi.jpg', '/xXHtSqFx8mLjzNGX9oCKQEx2yTa.jpg', 'VFwHs7fEUNs'),
    (4011, 'A newly dead New England couple seeks help from a deranged demon exorcist to scare an affluent New York family out of their home.', 92, '/nnl6OWkyPpuMm595hmAxNW3rZFn.jpg', '/yRKyJJYIzfeiVDHBe4LXguPQCvD.jpg', 'po1HJbmow0g'),
    (4108, 'Former Special Forces officer Frank Martin will deliver anything to anyone for the right price, and his no-questions-asked policy puts him in high demand. But when he realizes his latest cargo is alive, it sets in motion a dangerous chain of events. The bound and gagged Lai is being smuggled to France by a shady American businessman, and Frank works to save her as his own illegal activities are uncovered by a French detective.', 92, '/dncJ81z1BahrT3ogLvlxOUC5n4u.jpg', '/8dXR9R0NUo4eyS4hnYOsCywmo16.jpg', '0poXFSvX0_4'),
    (4133, 'The story of how George Jung, together with the Medellín Cartel led by Pablo Escobar, established the billion-dollar cocaine empire in the United States in the 1970s.', 124, '/yYZFVfk8aeMP4GxBSU9MTvqs9mJ.jpg', '/b5GNqEW951qS1sJKmWUQD1uI7UU.jpg', 'otckBy8LdVg'),
    (4141, 'A man named Mr. Smith delivers a woman''s baby during a shootout, and is then called upon to protect the newborn from the army of gunmen.', 86, '/hZ4p0MvSUWnCCL0IUn47UXTVPCs.jpg', '/1bYY2WUsHyCl66gQAGoF40JIryW.jpg', 'jlx4n_ibNZE'),
    (4147, 'Mike Sullivan works as a hit man for crime boss John Rooney. Sullivan views Rooney as a father figure, however after his son is witness to a killing, Mike Sullivan finds himself on the run in attempt to save the life of his son and at the same time looking for revenge on those who wronged him.', 117, '/loSpBeirRfTPJ3cMIqpQArstGhh.jpg', '/cDDyZ2qtBzNAepdTbgxKfFcxREl.jpg', 'LFe6arz3NcY'),
    (4232, 'A year after the murder of her mother, a teenage girl is terrorized by a masked killer who targets her and her friends by using scary movies as part of a deadly game.', 112, '/lr9ZIrmuwVmZhpZuTCW8D9g0ZJe.jpg', '/4w6nQYAY0eb7B0VVRDXilXcgAUV.jpg', 'U0LETmDvuXc'),
    (4233, 'Two years after the Woodsboro murders, Sidney Prescott acclimates to college life while someone donning the Ghostface costume begins a new string of killings.', 120, '/dORlVasiaDkJXTqt9bdH7nFNs6C.jpg', '/lVmcX3hlJqsUGkEOEZkRFiOQdLv.jpg', 'C-j2TLBmTBY'),
    (4234, 'As bodies begin dropping around the Hollywood set of STAB 3, the third film based on the gruesome Woodsboro killings, Sidney and other survivors are once again terrorized by another Ghostface killer.', 116, '/iFrDIex06Jpgs3dTI8vXlVB1jd.jpg', '/AbFWty0o5nKGo4iLJaGRgqFtC8W.jpg', 'Gx24Z9O0MuY'),
    (4256, 'News anchorwoman Cindy Campbell has to investigate mysterious crop circles and killing video tapes, and help the President stop an alien invasion in the process.', 84, '/8dLsax5KSwlCY5uWXETKjud5k6U.jpg', '/nF74HKjNe7X54XMcIc7ulK5InxR.jpg', 'O21wD8Tzr2k'),
    (4257, 'Cindy finds out the house she lives in is haunted by a little boy and goes on a quest to find out who killed him and why. Also, Alien "Tr-iPods" are invading the world and she has to uncover the secret in order to stop them.', 83, '/dEwlu8S0z1AibuX1weLwUyiRWFl.jpg', '/pSNwe7G9bESwlCBVurlwRs7fMZU.jpg', 'h0zAlXr1UOs'),
    (4327, 'The captivating crime-fighting trio who are masters of disguise, espionage and martial arts are back! When a devious mastermind embroils them in a plot to destroy individual privacy, the Angels, aided by their loyal sidekick Bosley, set out to bring down the bad guys. But when a terrible secret is revealed, it makes the Angels targets for assassination.', 98, '/paDTaHGLxhacythNZCT86VPanm6.jpg', '/oq3IOr7QvEmei0eXsXacqaMPqlV.jpg', 'GtB603KpU9g'),
    (4347, 'A young girl irrevocably changes the course of several lives when she accuses her older sister''s lover of a crime he did not commit.', 123, '/hMRIyBjPzxaSXWM06se3OcNjIQa.jpg', '/ffKYRCEVOzpb5y4tA7VW1DwhQw9.jpg', 'WZAttjca0b8'),
    (4348, 'A story of love and life among the landed English gentry during the Georgian era. Mr. Bennet is a gentleman living in Hertfordshire with his overbearing wife and five daughters, but if he dies their house will be inherited by a distant cousin whom they have never met, so the family''s future happiness and security is dependent on the daughters making good marriages.', 128, '/o8UhmEbWPHmTUxP0lMuCoqNkbB3.jpg', '/1Onam6oWyFAUCcoxtdWkACtEiNr.jpg', 'tbW-pmLT5UU'),
    (4488, 'Camp counselors are stalked and murdered by an unknown assailant while trying to reopen a summer camp that was the site of a child''s drowning.', 95, '/uGGpnWHOmWTARVN9wbC1nPxNgps.jpg', '/llLB2MWIRqWfBHENc5m63RcKR8G.jpg', '8nYuu5jpWVs'),
    (4512, 'Outlaw Jesse James is rumored to be the ''fastest gun in the West''. An eager recruit into James'' notorious gang, Robert Ford eventually grows jealous of the famed outlaw and, when Robert and his brother sense an opportunity to kill James, their murderous action elevates their target to near mythical status.', 160, '/xMKn6EQS7eR5ubhPJbw5pQSBZMw.jpg', '/3HvQ5PaxwQJEiRSZD5AyVuqEiNn.jpg', 'SrGmmitc62Q'),
    (4523, 'The beautiful princess Giselle is banished by an evil queen from her magical, musical animated land and finds herself in the gritty reality of the streets of modern-day Manhattan. Shocked by this strange new environment that doesn''t operate on a "happily ever after" basis, Giselle is now adrift in a chaotic world badly in need of enchantment. But when Giselle begins to fall in love with a charmingly flawed divorce lawyer who has come to her aid - even though she is already promised to a perfect fairy tale prince back home - she has to wonder: Can a storybook view of romance survive in the real world?', 107, '/8KCNzCArLlvLdQoHx6npua2VSVc.jpg', '/u4UpRDi0w84aNrigr9p049rMHiy.jpg', 'rwTNJgffMco'),
    (4538, 'Three American brothers who have not spoken to each other in a year set off on a train voyage across India with a plan to find themselves and bond with each other -- to become brothers again like they used to be. Their "spiritual quest", however, veers rapidly off-course (due to events involving over-the-counter pain killers, Indian cough syrup, and pepper spray).', 91, '/oSW5OVXTulaIXcoNwJAp5YEKpbP.jpg', '/hKJ513GbmTSmTXJU1uCXclh5Wkh.jpg', 'aO1bYukdvLI'),
    (4547, 'Trapped in their New York brownstone''s panic room, a hidden chamber built as a sanctuary in the event of break-ins, newly divorced Meg Altman and her young daughter Sarah play a deadly game of cat-and-mouse with three intruders - Burnham, Raoul and Junior - during a brutal home invasion. But the room itself is the focal point because what the intruders really want is inside it.', 111, '/hANYbvfwxmkC9E4yY6YyJxYxlSJ.jpg', '/gJfd2SzUsvY1q1iszthJ3ryuvEA.jpg', 'yCMKOqL94BQ'),
    (4553, 'Trevor, an insomniac lathe operator, experiences unusual occurrences at work and home. A strange man follows him everywhere, but no one else seems to notice him.', 102, '/diAYqR4xdF9Hnj7qun6DEQhRrT2.jpg', '/hi3lxLd93iKwCmVAfhMV9m1k2jr.jpg', '7HPT9006wT8'),
    (4588, 'During World War II, a secret agent must seduce, then assassinate an official  who works for the Japanese puppet government in Shanghai. Her mission becomes clouded when she finds herself falling in love with the man she is assigned to kill.', 158, '/6c1tqfJEBuIyhQC19SLlLQAUAvJ.jpg', '/lU1fQews2gye23PocVE48CsTmOQ.jpg', 'CizN-DvGhrc'),
    (4638, 'Former London constable Nicholas Angel finds it difficult to adapt to his new assignment in the sleepy British village of Sandford. Not only does he miss the excitement of the big city, but he also has a well-meaning oaf for a partner. However, when a series of grisly accidents rocks Sandford, Angel smells something rotten in the idyllic village.', 121, '/zPib4ukTSdXvHP9pxGkFCe34f3y.jpg', '/9rMSCFH9zhv1vILpEZQlUJs9iUm.jpg', 'L6PKkxn7pq0'),
    (4771, 'When 4 year old Amanda McCready disappears from her home and the police make little headway in solving the case, the girl''s aunt, Beatrice McCready hires two private detectives, Patrick Kenzie and Angie Gennaro. The detectives freely admit that they have little experience with this type of case, but the family wants them for two reasons—they''re not cops and they know the tough neighborhood in which they all live.', 113, '/w98tAPUjNPxGAMCipNDWDt8PJo.jpg', '/r9qIuaPPJQuuNvGQGKHjmDxntsK.jpg', 'itPTyd3DkEw'),
    (4806, 'Having already left three grooms at the altar, Maggie Carpenter is branded "the runaway bride" by jaded New York journalist Ike Graham. But, after his facts are called into question, Ike races to Maggie''s hometown to save his reputation and report on her upcoming fourth trip down the aisle – during which he''s convinced she''ll run again. Though he''s there on a muckraking mission, Ike can''t help but fall for this breathtaking heartbreaker.', 116, '/wzivR0yWJStVdhcl0A5rQvVdTQ7.jpg', '/kvZxYVwy75O35YqvkHztYijFVRE.jpg', 'nlOLJ_H0zcA'),
    (4824, 'Hired by a powerful member of the Russian mafia to avenge an FBI sting that left his brother dead, a psychopathic hitman known only as The Jackal proves an elusive target for the people charged with the task of bringing him down: a deputy FBI director, a Russian MVK Major,  and a jailed IRA terrorist who can recognize him.', 124, '/oXF26QmDEaRaH9Fbhs3NXtcnryx.jpg', '/ctu2jbJ4NpQX2SKXdIMCYfwDCsO.jpg', '_3UCCtpFET8'),
    (4836, 'When a seemingly straight-forward drug deal goes awry, XXXX has to break his die-hard rules and turn up the heat, not only to outwit the old regime and come out on top, but to save his own skin...', 105, '/rDOxXteqxALBaSa3V3zTjGJuyWB.jpg', '/fcAVJkXnvqxOrk7skr06CbWfgpQ.jpg', 'QtrbWfZtxxM'),
    (4922, 'Born under unusual circumstances, Benjamin Button springs into being as an elderly man in a New Orleans nursing home and ages in reverse. Twelve years after his birth, he meets Daisy, a child who flits in and out of his life as she grows up to be a dancer. Though he has all sorts of unusual adventures over the course of his life, it is his relationship with Daisy, and the hope that they will come together at the right time, that drives Benjamin forward.', 166, '/26wEWZYt6yJkwRVkjcbwJEFh9IS.jpg', '/2fswjyrY3GEzeoVn6mF8pNeNcgf.jpg', 'lqijVXvw7_E'),
    (4935, 'Sophie, a young milliner, is turned into an elderly woman by a witch who enters her shop and curses her. She encounters a wizard named Howl and gets caught up in his resistance to fighting for the king.', 119, '/13kOl2v0nD2OLbVSHnHk8GUFEhO.jpg', '/nv5wwZou159v5OC61i4ElR7OqyY.jpg', 'ARCQf2CEr8k'),
    (4944, 'When a disc containing memoirs of a former CIA analyst falls into the hands of gym employees, Linda and Chad, they see a chance to make enough money for Linda to have life-changing cosmetic surgery. Predictably, events whirl out of control for the duo, and those in their orbit.', 96, '/jdwSkQu3XirmX18MNj8CqFWsCk.jpg', '/dGaV9hfxztBIaCs0MsMlamRw9hC.jpg', 'jksnxStXol0'),
    (4951, 'After discovering his high school crush can''t date until her brash older sister does, a lovesick teen enlists a bad-boy classmate to woo her.', 97, '/ujERk3aKABXU3NDXOAxEQYTHe9A.jpg', '/yvPbncYhMu9FfTjDhq0N5lgnVkO.jpg', 'GbWQ_VXek6A'),
    (4964, 'A slacker and a career-driven woman accidentally conceive a child after a one-night stand. As they try to make the relationship work, they must navigate the challenges of parenthood and their differences in lifestyle and maturity.', 129, '/b4OaXw2MW97VvIiZE0Sbn1NfxSh.jpg', '/8uNx4YtClqB9duM4n6jOx8vWvvl.jpg', 'K6oqO-xMERc'),
    (4970, 'After a car crash, criminal psychologist Dr. Miranda Grey regains consciousness only to find that she''s a patient in the same mental institution that currently employs her. She''s been accused of murdering her husband Dr. Douglas Grey — but she has no memory of committing the crime. As she tries to regain her memory and convince her co-worker, Dr. Pete Graham, of her innocence, a vengeful spirit uses her as an earthly pawn, which further convinces everyone of her guilt.', 98, '/frSGNQcWx1ek8dCduFYCux1ho7n.jpg', '/eLBHPVQkJZyaSEUAGAFWNJJwmeo.jpg', 'STxbF5tl5T0'),
    (4982, 'Loosely based on the criminal career of Frank Lucas, a gangster from La Grange, North Carolina, who smuggled heroin into the United States on American service planes returning from the Vietnam War, before being detained by a task force led by Newark Detective Richie Roberts.', 157, '/sX9idXDqRUxE5ffww3n3RV5gL55.jpg', '/dLL90vskYFn1S89RZp5TUguK9wl.jpg', 'BV_nssS6Zkg'),
    (4995, 'In 1977, an idealistic porn producer and his promising protege try to catch up with the end of an era before their never-ending party collides with cold, hard reality.', 156, '/wnE24UPCPQsQnbBOu4zVE2qaDNm.jpg', '/ArpTzQZHWh4UVsgUvV6S7WjTq1n.jpg', '6__jTfyCMsc'),
    (5038, 'Two girlfriends on a summer holiday in Spain become enamored with the same painter, unaware that his ex-wife, with whom he has a tempestuous relationship, is about to re-enter the picture.', 96, '/ekAIg0GSbbHTH7y1GPgWj0brLTW.jpg', '/dIzeiSCVUGpaVGCAb7S9JPkBGqH.jpg', '4Ur7BmMYiIs'),
    (5123, 'Evan, a musically gifted orphan, runs away from his orphanage and searches New York City for his birth parents. On his journey, he''s taken under the wing of the Wizard, a homeless man who lives in an abandoned theater. After discovering his talent, the Wizard gives Evan the name "August Rush" and devises a plan to profit from his talent. Little does Evan know that his parents, Lyla and Louis, are searching for him too.', 114, '/oA6ZeICPINiS6YtD5WZeBaGVmuT.jpg', '/i3pONuqGZSR3UYOOdBeU2CiQnxj.jpg', 'wH7bq_RjJqg'),
    (5156, 'Unemployed Antonio is elated when he finally finds work hanging posters around war-torn Rome. However on his first day, his bicycle—essential to his work—gets stolen. His job is doomed unless he can find the thief. With the help of his son, Antonio combs the city, becoming desperate for justice.', 89, '/iPdVqIpmR3bRvOQJPrn4pr2KR3q.jpg', '/kTUUiKGKrdRhJsCcYT3Ivtfuuzh.jpg', 'H2P4xo9kmPM'),
    (5174, 'After a botched assassination attempt, the mismatched duo finds themselves in Paris, struggling to retrieve a precious list of names, as the murderous crime syndicate''s henchmen try their best to stop them. Once more, Lee and Carter must fight their way through dangerous gangsters; however, this time, the past has come back to haunt Lee. Will the boys get the job done once and for all?', 90, '/mp9CzKxLa2i7yblMXUrzVfGqsCo.jpg', '/ozsLB1HRCN6ZAmJN89pWtoiAwnb.jpg', 'Wwow2VOxGZQ'),
    (5175, 'It''s vacation time for Carter as he finds himself alongside Lee in Hong Kong wishing for more excitement. While Carter wants to party and meet the ladies, Lee is out to track down a Triad gang lord who may be responsible for killing two men at the American Embassy. Things get complicated as the pair stumble onto a counterfeiting plot. The boys are soon up to their necks in fist fights and life-threatening situations. A trip back to the U.S. may provide the answers about the bombing, the counterfeiting, and the true allegiance of sexy customs agent Isabella.', 90, '/aBQf2vMiCINeVC9v6BGVYKXurTh.jpg', '/vPJwn9pp5f58CqdaXU3eOSLoJkl.jpg', 'SCTzYY95Aw4'),
    (5176, 'In Arizona in the late 1800s, infamous outlaw Ben Wade and his vicious gang of thieves and murderers have plagued the Southern Railroad. When Wade is captured, Civil War veteran Dan Evans, struggling to survive on his drought-plagued ranch, volunteers to deliver him alive to the "3:10 to Yuma", a train that will take the killer to trial.', 122, '/voMB69AsLnPNmtfbrBl0lbeFKDH.jpg', '/2eznGndOi8s9CGReAvcQ8PEULwm.jpg', 'Kv6apbWxb5M'),
    (5236, 'A petty thief posing as an actor is brought to Los Angeles for an unlikely audition and finds himself in the middle of a murder investigation along with his high school dream girl and a detective who''s been training him for his upcoming role...', 103, '/aWfjIkpENFX6Uw82pET7EQ6jnrd.jpg', '/kKdBNPXfjENj3wG5qtiCrZ2wflp.jpg', 'x7L-kF5Im1Y'),
    (5255, 'When a doubting young boy takes an extraordinary train ride to the North Pole, he embarks on a journey of self-discovery that shows him that the wonder of life never fades for those who believe.', 100, '/eOoCzH0MqeGr2taUZO4SwG416PF.jpg', '/jtOvTVlkF8TlaOq94oNXRc9u2yp.jpg', 'f0oyHtZiJJs'),
    (5336, 'Four corrupted fascist libertines round up 9 teenage boys and girls and subject them to 120 days of sadistic physical, mental and sexual torture.', 117, '/xnaDdiRfZlJaTf6JRc4in40eaeI.jpg', '/agwkvkJTJrpRlheTn1Qe1qEgJh4.jpg', 'EtXnuPa1qAA'),
    (5503, 'Wrongfully convicted of murdering his wife and sentenced to death, Richard Kimble escapes from the law in an attempt to find the real killer and clear his name.', 131, '/b3rEtLKyOnF89mcK75GXDXdmOEf.jpg', '/tN7ZVNWLgh57iZzMyvuhunIuUVd.jpg', 'OlYsVq6FpuU'),
    (5548, 'In a violent, near-apocalyptic Detroit, evil corporation Omni Consumer Products wins a contract from the city government to privatize the police force. To test their crime-eradicating cyborgs, the company leads street cop Alex Murphy into an armed confrontation with crime lord Boddicker so they can use his body to support their untested RoboCop prototype. But when RoboCop learns of the company''s nefarious plans, he turns on his masters.', 102, '/hHtOgGb3NihlyRATHlKPaFApbrd.jpg', '/xcaX6BZ1JUPSVMH2gBkWIckLLaA.jpg', 'IqvRDhW-XVA'),
    (5549, 'After a successful deployment of the RoboCop Law Enforcement unit, OCP sees its goal of urban pacification come closer and closer, but as this develops, a new narcotic known as "Nuke" invades the streets led by God-delirious leader Cane. As this menace grows, it may prove to be too much for Murphy to handle. OCP tries to replicate the success of the first unit, but ends up with failed prototypes with suicidal issues... until Dr. Faxx, a scientist straying away from OCP''s path, uses Cane as the new subject for the RoboCop 2 project, a living God.', 117, '/nhqBxhOJXUJeFsyLxTFkctH9H5F.jpg', '/cT0YCYCtAQC8wi56VWK1JRGgk3a.jpg', 'HNcy89RqF5Q'),
    (5559, 'Barry B. Benson, a recent college graduate who wants more out of his life than making honey, decides to sue the human race after learning about the exploitation of bees at the hands of mankind. What will happen next?', 91, '/tX2mgKFUkzFMZingSVD4vioZNz2.jpg', '/uRZhr7zzaxeidLq2eYL59ulh4vn.jpg', 'z3PtI-ljZAU'),
    (5876, 'After a violent storm, a dense cloud of mist envelops a small Maine town, trapping David Drayton and his five-year-old son in a local grocery store with other local residents. They soon discover that the mist conceals deadly horrors that threaten their lives, and worse, their sanity.', 126, '/c4UgUKZjM0Qzy5t4hAXSOFHYsnb.jpg', '/76J14zgwVWyOciri7X7F3DGP3TA.jpg', 'E-NF55EZ5tw'),
    (5915, 'After graduating from Emory University in 1992, top student and athlete Christopher McCandless abandons his possessions, gives his entire $24,000 savings account to charity, and hitchhikes to Alaska to live in the wilderness.', 148, '/jnLnLYP5pGDfri04gxtAqAvkHMw.jpg', '/87tmTU1NSR5EUGTKsF5rhLwZtZc.jpg', 'g7ArZ7VD-QQ'),
    (5925, 'The Nazis, exasperated at the number of escapes from their prison camps by a relatively small number of Allied prisoners, relocate them to a high-security ''escape-proof'' camp to sit out the remainder of the war. Undaunted, the prisoners plan one of the most ambitious escape attempts of World War II. Based on a true story.', 173, '/gBH4H8UMFxl139HaLz6lRuvsel8.jpg', '/zlg0d4pnq1xDOU4cQxqGG8bX5l0.jpg', '8No6XGbvr0w'),
    (6075, 'Free after years in prison, Carlito Brigante intends to give up his criminal ways, but it''s not long before the ex-con is sucked back into the New York City underworld.', 144, '/g6D7mjQtndu768cusGmoEQY9fTB.jpg', '/9s4ZDw0j6qByLgwJtUsRcepBXSw.jpg', 'nYBHVf108J0'),
    (6114, 'Count Dracula, a 15th-century prince, is condemned to live off the blood of the living for eternity. Young lawyer Jonathan Harker is sent to Dracula''s castle to finalise a land deal, but when the Count sees a photo of Harker''s fiancée, Mina, the spitting image of his dead wife, he imprisons him and sets off for London to track her down.', 128, '/wpRrdm6g8zWtJnzVqME5QwSKkn7.jpg', '/fGuhbAlDpvmNuC0vkz1vsIzYwsq.jpg', 'xD6JMxOGBLQ'),
    (6145, 'A husband is on trial for the attempted murder of his wife, in what is seemingly an open/shut case for the ambitious district attorney trying to put him away. However, there are surprises for both around every corner, and, as a suspenseful game of cat-and-mouse is played out, each must manipulate and outwit the other.', 113, '/qNen8x5gaikjIg9CFihgxYcJwQe.jpg', '/mujUrk2diGe5vRCb3kdpHZeobRs.jpg', 'B9jSN5CXO-g'),
    (6282, 'Graced with a velvet voice, 21-year-old Violet Sanford heads to New York to pursue her dream of becoming a songwriter only to find her aspirations sidelined by the accolades and notoriety she receives at her "day" job as a barmaid at Coyote Ugly. The "Coyotes" as they are affectionately called tantalize customers and the media alike with their outrageous antics, making Coyote Ugly the watering hole for guys on the prowl.', 100, '/xYM0laKrEqjiRSQNvqRrXPXN3iL.jpg', '/f2MzXz3vjuNtSPn17ugFa6oTUmc.jpg', '2lqWOOHOwlE'),
    (6415, 'A group of American soldiers stationed in Iraq at the end of the Gulf War find a map they believe will take them to a huge cache of stolen Kuwaiti gold hidden near their base, and they embark on a secret mission that''s destined to change everything.', 114, '/fClJQW8xn8wHOFqoA4jUn0PZh1f.jpg', '/gysZn2XnFlDDQROXdBPiku4Aujg.jpg', 'Bdal5c1TfmE'),
    (6466, 'Freddy Krueger and Jason Voorhees return to terrorize the teenagers of Elm Street. Only this time, they''re out to get each other, too.', 97, '/ffoBCQ7y63Tvo48HsJqr1XOiqiV.jpg', '/hCAOQTMRop2fHjsl8n7yNwpkMJn.jpg', 'oCf4l6XnML8'),
    (6477, 'A struggling songwriter named Dave Seville finds success when he comes across a trio of singing chipmunks: mischievous leader Alvin, brainy Simon, and chubby, impressionable Theodore.', 92, '/3s3WvpKPXXeKAPketDDqiQTi20S.jpg', '/lKkkogTlIQT8o83GFQZZ3CA9MzB.jpg', 'sc-C8uumMkw'),
    (6479, 'Robert Neville is a scientist who was unable to stop the spread of the terrible virus that was incurable and man-made. Immune, Neville is now the last human survivor in what is left of New York City and perhaps the world. For three years, Neville has faithfully sent out daily radio messages, desperate to find any other survivors who might be out there. But he is not alone.', 101, '/fhbiz5BsGUVEZmzPP72SoPlbMz0.jpg', '/ePgD1cwmklyrFBjl6z96IuixuSY.jpg', '4uDU6SUpr8k'),
    (6557, 'Altruistic Jane finds herself facing her worst nightmare as her younger sister announces her engagement to the man Jane secretly adores.', 111, '/rEfourJfgEyKiewwH8ZkUYt9AqE.jpg', '/esArWR9sImBpEgq3sHCPyP5mcfd.jpg', 'gB2bILnrypc'),
    (6615, 'Extremely shy Lars finds it impossible to make friends or socialize. His brother and sister-in-law worry about him, so when he announces that he has a girlfriend he met on the Internet, they are overjoyed. But Lars'' new lady is a life-size plastic woman. On the advice of a doctor, his family and the rest of the community go along with his delusion.', 107, '/nkAt4a7KIPc7Fi1BhxNHhYYbe2b.jpg', '/2KeicelocjfYzViherowQn69moR.jpg', 'tVWXhZz5SAk'),
    (6637, 'Benjamin Franklin Gates and Abigail Chase re-team with Riley Poole and, now armed with a stack of long-lost pages from John Wilkes Booth''s diary, Ben must follow a clue left there to prove his ancestor''s innocence in the assassination of Abraham Lincoln.', 124, '/xxoIBbvmTj1ZttzV439jAvoovTw.jpg', '/aqGVdM065tIcVmaMIeozk80lLf6.jpg', 'MBQm-ovrPho'),
    (6795, 'After their father is called into work, two young boys, Walter and Danny, are left in the care of their teenage sister, Lisa, and told they must stay inside. Walter and Danny, who anticipate a boring day, are shocked when they begin playing Zathura, a space-themed board game, which they realize has mystical powers when their house is shot into space. With the help of an astronaut, the boys attempt to return home.', 101, '/gDb5BW2NLqZ9cvg9nyzkZVvmgze.jpg', '/s9Bn7Mx4U9cWOR1WdFZjU1DTAkh.jpg', 'hxrF-X1yn6Q'),
    (6947, 'When a willful young man tries to venture beyond his sequestered Pennsylvania hamlet, his actions set off a chain of chilling incidents that will alter the community forever.', 108, '/3EkD16fPin2wG5OWhD1DAQvJRHg.jpg', '/orwHXcN5NLqEG03oQlOigUXSZvE.jpg', 'c7TL1BZegLo'),
    (6957, 'Andy Stitzer has a pleasant life with a nice apartment and a job stamping invoices at an electronics store. But at age 40, there''s one thing Andy hasn''t done, and it''s really bothering his sex-obsessed male co-workers: Andy is still a virgin. Determined to help Andy get laid, the guys make it their mission to de-virginize him. But it all seems hopeless until Andy meets small business owner Trish, a single mom.', 116, '/mVeoqL37gzhMXQVpONi9DGOQ3tZ.jpg', '/3Wej7JW8Ikrzbm6h0lmSdeOYMmu.jpg', 'QVucTi58nA8'),
    (6977, 'Llewelyn Moss stumbles upon dead bodies, $2 million and a hoard of heroin in a Texas desert, but methodical killer Anton Chigurh comes looking for it, with local sheriff Ed Tom Bell hot on his trail. The roles of prey and predator blur as the violent pursuit of money and justice collide.', 122, '/6d5XOczc226jECq0LIX0siKtgHR.jpg', '/fCCvn3xsG29TGKJPvZgTRppsDgk.jpg', 'A0oNrgumrlE'),
    (7131, 'Famed monster slayer Gabriel Van Helsing is dispatched to Transylvania to assist the last of the Valerious bloodline in defeating Count Dracula. Anna Valerious reveals that Dracula has formed an unholy alliance with Dr. Frankenstein''s monster and is hell-bent on exacting a centuries-old curse on her family.', 132, '/gsFun8nATm52aGHeT8ueAel98nE.jpg', '/d72ROyJqXQtw2OupW0l15eicRAF.jpg', 'W6C6qcCW2JE'),
    (7191, 'Five young New Yorkers throw their friend a going-away party the night that a monster the size of a skyscraper descends upon the city. Told from the point of view of their video camera, the film is a document of their attempt to survive the most surreal, horrifying event of their lives.', 85, '/qIegUGJqyMMCRjkKV1s7A9MqdJ8.jpg', '/6ms6RdNcQUAnjBY26aM85xC2wV0.jpg', 'wxqSIsxMlYQ'),
    (7220, 'When undercover FBI agent Frank Castle''s wife and son are slaughtered, he becomes ''the Punisher'' -- a ruthless vigilante willing to go to any length to avenge his family.', 124, '/7rmA1HwYp2GKM85BL0cVwCaosGr.jpg', '/ziexSS07RmowuyqAdJMh1sGxjHg.jpg', 'TqVSFchQEyM'),
    (7299, 'In a dystopian future, a totalitarian regime maintains peace by subduing the populace with a drug, and displays of emotion are punishable by death. A man in charge of enforcing the law rises to overthrow the system.', 107, '/yQuovle5Ov6q69XSdTNdH52eANc.jpg', '/kSycj00Oteq910zUGrsvCfjR2wk.jpg', 'KTkAAC11w80'),
    (7326, 'Faced with an unplanned pregnancy, sixteen year old high-schooler, Juno MacGuff, makes an unusual decision regarding her unborn child.', 96, '/jNIn2tVhpvFD6P9IojldI3mNYcn.jpg', '/sRXMmeNHTSWRYdDz3zaHNyyPJ0u.jpg', 'miy1fE-8Z0U'),
    (7340, 'Withdrawn and sensitive teenager Carrie White faces bullying from her classmates and abuse from her fanatically pious mother. When she begins to suspect that she has supernatural powers, things take a dark and violent turn.', 98, '/8tT1rqlsTguyfUBMrbHR9cv1rxM.jpg', '/zwJFfKQdfiptK2GY6N8GkZFrAxJ.jpg', 'zbdIXI1s3aU'),
    (7345, 'Ruthless silver miner, turned oil prospector, Daniel Plainview, moves to oil-rich California. Using his son to project a trustworthy, family-man image, Plainview cons local landowners into selling him their valuable properties for a pittance. However, local preacher Eli Sunday suspects Plainview''s motives and intentions, starting a slow-burning feud that threatens both their lives.', 158, '/fa0RDkAlCec0STeMNAhPaF89q6U.jpg', '/9UAKA6ceZi6TgQwTAAMt7DWwYPI.jpg', '-bEwlq_7f4s'),
    (7347, 'In 1997, before the visit of the pope to Rio de Janeiro, Captain Nascimento from BOPE (Special Police Operations Battalion) is assigned to eliminate the risks of the drug dealers in a dangerous slum nearby where the pope intends to be lodged.', 115, '/lwIXz785N2fXi8hsBr1IXciFlkM.jpg', '/huUgrGkCetYSkDl5fMvZCXCbFKl.jpg', 'WNrC-vLpTGI'),
    (7350, 'Corporate billionaire Edward Cole and working class mechanic Carter Chambers are worlds apart. At a crossroads in their lives, they share a hospital room and discover they have two things in common: a desire to spend the time they have left doing everything they ever wanted to do and an unrealized need to come to terms with who they are. Together they embark on the road trip of a lifetime, becoming friends along the way and learning to live life to the fullest, with insight and humor.', 97, '/idbNSe8zsYKQL97dJApfOrDSdya.jpg', '/6OpluXPGIE8hfVrhpeygR7p4XwR.jpg', 'f-eyQswdc-c'),
    (7443, 'The creators of Wallace & Gromit bring you an exciting and original story about a group of chickens determined to fly the coop–even if they can’t fly! It’s hardly poultry in motion when Rocky attempts to teach Ginger and her feathered friends to fly…but, with teamwork, determination and a little bit o’ cluck, the fearless flock plots one last attempt in a spectacular bid for freedom.', 84, '/8XgmIsbpVamdhwcNVsYzohFZTtT.jpg', '/3eYkMSjWbvTaZso7ow5ub9ikNNq.jpg', 'rUSoF2nwPw8'),
    (7446, 'A group of self-absorbed actors set out to make the most expensive war film ever. When budgets skyrocket and schedules fall far behind, the director tries to save the production by leading his cast into the jungles of Southeast Asia, where they inadvertently encounter real danger.', 107, '/zAurB9mNxfYRoVrVjAJJwGV3sPg.jpg', '/4pLi4QMm0MZ9TSoF3l8qQmY9HNO.jpg', 'ASJvlHExnMA'),
    (7451, 'Xander Cage is your standard adrenaline junkie with no fear and a lousy attitude. When the US Government "recruits" him to go on a mission, he''s not exactly thrilled. His mission: to gather information on an organization that may just be planning the destruction of the world, led by the nihilistic Yorgi.', 124, '/xeEw3eLeSFmJgXZzmF2Efww0q3s.jpg', '/qwK9soQmmJ7kRdjLZVXblw3g7AQ.jpg', 'NgPdDDzVhkA'),
    (7453, 'Mere seconds before the Earth is to be demolished by an alien construction crew, Arthur Dent is swept off the planet by his friend Ford Prefect, a researcher penning a new edition of "The Hitchhiker''s Guide to the Galaxy."', 109, '/4fOFbNMjq708CQ7ou71by6rI6wZ.jpg', '/58xc04IuCymfgtWUFRuLRtcEECP.jpg', 'MbGNcoB2Y4I'),
    (7484, 'Boog, a domesticated 900lb. Grizzly bear finds himself stranded in the woods 3 days before Open Season. Forced to rely on Elliot, a fast-talking mule deer, the two form an unlikely friendship and must quickly rally other forest animals if they are to form a rag-tag army against the hunters.', 86, '/w5Lctmkc1yah215Luxmci4djaiW.jpg', '/wttDKH1WRXGpebDVzrqnVSdh15u.jpg', 'YHQAL6s3Mk8'),
    (7485, 'A top Marine sniper, Bob Lee Swagger, leaves the military after a mission goes horribly awry and disappears, living in seclusion. He is coaxed back into service after a high-profile government official convinces him to help thwart a plot to kill the President of the United States. Ultimately double-crossed and framed for the attempt, Swagger becomes the target of a nationwide manhunt. He goes on the run to track the real killer and find out who exactly set him up, and why, eventually seeking revenge against some of the most powerful and corrupt leaders in the free world.', 124, '/2aWGxo1E5polpBjPvtBRkWp7qaS.jpg', '/uy2trYgO8MOQfQXlvMaLhBnkUqg.jpg', 'A3lPVwYOdzA'),
    (7512, 'To test its top-secret Human Hibernation Project, the Pentagon picks the most average European-Americans it can find - an Army private and a prostitute - and sends them to the year 2505 after a series of freak events. But when they arrive, they find a civilization so dumbed-down that they''re the smartest people around.', 85, '/6cTHBq49ApwsJaRr3ojlY1cmiXk.jpg', '/9Z4msMhKvNp63sOB1ZvxPMPvqz3.jpg', 'clYwX8Z43zg'),
    (7516, 'When a Las Vegas performer-turned-snitch named Buddy Israel decides to turn state''s evidence and testify against the mob, it seems that a whole lot of people would like to make sure he''s no longer breathing.', 109, '/nrdnN8WqvyOt8Bnl3hgWcZD6ZyM.jpg', '/mvWYpXsgeZiJ1GKrl0Nb1pwJI7I.jpg', '202uOuNsgow'),
    (7518, 'A scheming raccoon fools a mismatched family of forest creatures into helping him repay a debt of food, by invading the new suburban sprawl that popped up while they were hibernating – and learns a lesson about family himself.', 83, '/jtZnymorbnHY7mOiBXR14ZDJseM.jpg', '/4BmZXt8Yty7F2He4KE05jqGidEz.jpg', 'ix_bxyRimos'),
    (7551, 'Called in to recover evidence in the aftermath of a horrific explosion on a New Orleans ferry, Federal agent Doug Carlin gets pulled away from the scene and taken to a top-secret government lab that uses a time-shifting surveillance device to help prevent crime.', 126, '/wJAz3m9kTbdTWfQ2ZJEFojWKeoj.jpg', '/mhi2fRCbEXtN43FNiq45WQg0DFe.jpg', 'VdCRypsfZDE'),
    (7555, 'In Thailand, ex-Green Beret John James Rambo joins a group of mercenaries to venture into war-torn neighboring Myanmar to rescue a group of Christian aid workers who have been kidnapped by a ruthless local infantry unit.', 92, '/3mInub5c8o00H7EJ1TrjAqOzIuc.jpg', '/wzfTG1obTazlGXiIcfRIviBZ1QU.jpg', '2oVMgRVk4lE'),
    (7737, 'Years after the Racoon City catastrophe, survivors travel across the Nevada desert, hoping to make it to Alaska. Alice joins the caravan and their fight against hordes of zombies and the evil Umbrella Corp.', 94, '/6yaLr7Ymg5cvbtSVi5hHwBKx35I.jpg', '/bzfUXYiwO8GcRolszsL8FG7uOhv.jpg', 'eDMjVARsCOk'),
    (7978, 'Lawrence Talbot, an American man on a visit to Victorian London to make amends with his estranged father, gets bitten by a werewolf and, after a moonlight transformation, leaves him with a savage hunger for flesh.', 103, '/fQqPoAHvHicie1ttuiV2q0yv9V7.jpg', '/kTDunJrHYsH6o1wmD6iT4wXkuHo.jpg', '3xSuR1zZCII'),
    (7980, 'After being brutally murdered, 14-year-old Susie Salmon watches from heaven over her grief-stricken family -- and her killer. As she observes their daily lives, she must balance her thirst for revenge with her desire for her family to heal.', 136, '/kIa9CyK2yiE4CAy7RJPGe7lztse.jpg', '/vmonG9lV1s3CtmOQmmWUO206Xay.jpg', 'QydPyttFzhs'),
    (8005, 'Robin Hood comes home after fighting in the Crusades to learn that the noble King Richard is in exile and that the despotic King John now rules England, with the help of the Sheriff of Rottingham. Robin Hood assembles a band of fellow patriots to do battle with King John and the Sheriff.', 104, '/b59epUgkPPBqgWcu5Q0YrYRKDx1.jpg', '/xFhpZ9UDUGXu52lCHdN39PIooRt.jpg', 'rL_aElj93ws'),
    (8054, 'After a carnival troupe saves his life, a man agrees to help its immortal leader collect five souls and win a bet with the devil.', 123, '/DtrqQHa0wT9AWrk2WA9beROJJx.jpg', '/vBw4z7l3NI32th7nR34zqRgdvXS.jpg', 'Iqe85ffv9-w'),
    (8065, 'Ben Campbell is a young, highly intelligent student at M.I.T. who strives to succeed. Wanting a scholarship to transfer to Harvard School of Medicine to become a doctor, Ben learns that he cannot afford the $300,000 tuition as he comes from a poor, working-class background. But one evening, Ben is introduced by his unorthodox math professor to a small but secretive club of five students, Jill, Choi, Kianna, and Fisher, who are being trained by Professor Rosa to count cards at blackjack.', 123, '/efG8Po57alqSlhqHU1lXJ3duG6t.jpg', '/u6OCGwhSWhfQX1LZ4NTq0bfcWxs.jpg', 'oqkdB7It5Go'),
    (8068, 'El Mariachi plunges headfirst into the dark border underworld when he follows a trail of blood to the last of the infamous Mexican drug lords, Bucho, for an action-packed, bullet-riddled showdown. With the help of his friend and a beautiful bookstore owner, El Mariachi tracks Bucho, takes on his army of desperados, and leaves his own trail of blood.', 104, '/e3gwpBeXpvGZsxUya9zNym5QXrw.jpg', '/pBje8Zw42aEy7E2IxrCIw9jM4qC.jpg', 'nJb0yXRHdi4'),
    (8077, 'After escaping with Newt and Hicks from the alien planet, Ripley crash lands on Fiorina 161, a prison planet and host to a correctional facility. Unfortunately, although Newt and Hicks do not survive the crash, a more unwelcome visitor does. The prison does not allow weapons of any kind, and with aid being a long time away, the prisoners must simply survive in any way they can.', 114, '/xh5wI0UoW7DfS1IyLy3d2CgrCEP.jpg', '/mqmQWkg8djY2G7v2xTmW9csE3K.jpg', 'e45rAwndek8'),
    (8078, 'Two hundred years after Lt. Ripley died, a group of scientists clone her, hoping to breed the ultimate weapon. But the new Ripley is full of surprises … as are the new aliens. Ripley must team with a band of smugglers to keep the creatures from reaching Earth.', 109, '/ivgE8yreRjesjApjbe1svgwpHHD.jpg', '/dNuNqjLVfapuv0bZG55R06TQD4Z.jpg', 'vu1tVYGsJ1Q'),
    (8193, 'A listless and alienated teenager decides to help his new friend win the class presidency in their small western high school, while he must deal with his bizarre family life back home.', 95, '/6Iv6Uwa2SBLN0dSGM00rdrwN4MJ.jpg', '/jrXKwUYxNLa7Dv7TPHToQ4mVmlF.jpg', 'W1IgJoRJ34Q'),
    (8204, 'Upon moving into the run-down Spiderwick Estate with their mother, twin brothers Jared and Simon Grace, along with their sister Mallory, find themselves pulled into an alternate world full of faeries and other creatures.', 95, '/uN7MUMaCXfa8DbMMp61A8iXEcEG.jpg', '/cVfaHnjOOS5qX8z10qnBsslq2Oi.jpg', '_yTZ8E3vbsE'),
    (8224, 'A small, seemingly innocuous plastic reel of film leads surveillance specialist Tom Welles down an increasingly dark and frightening path. With the help of the streetwise Max, he relentlessly follows a bizarre trail of evidence to determine the fate of a complete stranger. As his work turns into obsession, he drifts farther and farther away from his wife, family and simple life as a small-town PI.', 123, '/mhr9xRpjOBqlBjgDwtiOx6FsLvV.jpg', '/eEP8pyCmldfbnml0SFMvPK7kE4x.jpg', 'mjIGbTTw3i8'),
    (8247, 'David Rice is a man who knows no boundaries, a Jumper, born with the uncanny ability to teleport instantly to anywhere on Earth. When he discovers others like himself, David is thrust into a dangerous and bloodthirsty war while being hunted by a sinister and determined group of zealots who have sworn to destroy all Jumpers. Now, David’s extraordinary gift may be his only hope for survival!', 88, '/3pPZ9JhNz3VMmASVir5SMHvTDUU.jpg', '/1R4DZbEwWTPnRShBumJsOwsfAiB.jpg', 'hY5vDXOW4Nk'),
    (8271, 'Kale has a life most teenagers would envy. He spends his days endlessly playing video games, surfing the net, eating junk food and watching cable. He has complete free reign of the house, and a beautiful young hottie named Ashley has just moved in next door. There’s only one problem—he’s not allowed to leave the house. Kale’s under court-ordered house arrest for three months, and if he takes one step beyond a 100-foot perimeter of the house, his next confinement will be in a real prison.', 105, '/3f9KwSrieczuH9nRrwfOsoMoMNd.jpg', '/ve38VxE3qVdk5xbEluWTqFa9oGd.jpg', 'LoemUrP3EKQ'),
    (8273, 'With high school a distant memory, Jim and Michelle are getting married — and in a hurry, since Jim''s grandmother is sick and wants to see him walk down the aisle — prompting Stifler to throw the ultimate bachelor party. And Jim''s dad is reliable as ever, doling out advice no one wants to hear.', 103, '/pCO3lJv2PzPkJty29APxCVSjyoE.jpg', '/qW703anWHFXulRTKWOckAg9i70K.jpg', '4bqeLmhNbfI'),
    (8274, 'Everyone has ''moved on'', except for Sherman and Jim Levenstein''s still understanding father. Little Matt Stiffler wants to join his older brother Steve''s business and, after everything Matt has heard from Jim''s band-geek wife, he plans to go back to band camp and make a video of his own.', 94, '/6BgKeWEGROpWwEWvpw7vwfTCr9C.jpg', '/TWchvpMO36QZTIiNjFBm4MYsmQ.jpg', 'rSXb-9fkWFs'),
    (8275, 'When Erik Stifler realizes that he''s the only Stifler family member who might graduate high school a virgin, he decides to live up to his legacy. After some well-meaning advice from Jim''s dad, Erik''s ready to take his chances at the annual and infamous Naked Mile race, where his devoted friends and some uninhibited sorority girls will create the most outrageous weekend ever.', 97, '/6CPJVJrqVjibP5Uub8yCg4FKtJi.jpg', '/9IUZw1blAscYnyFi5vEFlHVXAWr.jpg', 'tkU2pjpt0Eo'),
    (8321, 'Ray and Ken, two hit men, are in Bruges, Belgium, waiting for their next mission. While they are there they have time to think and discuss their previous assignment. When the mission is revealed to Ken, it is not what he expected.', 108, '/vz3Vd6nfq9YZrVvyYx5RHFaYKV3.jpg', '/dtGxDOcFssdUUTYBr6M6INXTI1e.jpg', 'bc4lG_BbIEw'),
    (8328, 'When rebellious street dancer Andie West lands at the elite Maryland School of the Arts, she finds herself fighting to fit in while also trying to hold onto her old life. When she joins forces with the school''s hottest dancer, Chase Collins, to form a crew of fellow outcasts to compete in Baltimore''s underground dance battle The Streets.', 98, '/vYdlRTvA5fneB88NchV3sirzCE1.jpg', '/h87R0iJBcUYcIOE2GEVEcpwtBd9.jpg', 'bL2wDI-O5YQ'),
    (8329, 'A television reporter and cameraman follow emergency workers into a dark apartment building and are quickly locked inside with something terrifying.', 78, '/hgyJR4sgMsee6xMFM3xYiG6cDCh.jpg', '/xfrguTH6maYiGsC8FXiQ9N3lZXw.jpg', 'oPvHTzqY2fM'),
    (8337, 'A lone drifter stumbles upon a unique pair of sunglasses that reveal aliens are systematically gaining control of the Earth by masquerading as humans and lulling the public into submission.', 93, '/ngnybFTuopfbfmmEeX9jjBQQmF6.jpg', '/bwyLycDaQdS3rS4crpbYssYLJRy.jpg', 'vSVQ975eTBI'),
    (8346, 'A young Greek woman falls in love with a non-Greek and struggles to get her family to accept him while she comes to terms with her heritage and cultural identity.', 95, '/ztc05ym0T3stnBpRHdxEs3Zwsmp.jpg', '/3d8Y4q172YFp2obUdfMjyErB7eU.jpg', 'O2mecmDFE-Q'),
    (8355, 'Times are changing for Manny the moody mammoth, Sid the motor mouthed sloth and Diego the crafty saber-toothed tiger. Life heats up for our heroes when they meet some new and none-too-friendly neighbors – the mighty dinosaurs.', 94, '/cXOLaxcNjNAYmEx1trZxOTKhK3Q.jpg', '/6Ybbh8TrO8bkEfQXDedekLwVDfA.jpg', 'byUCa2vjDik'),
    (8358, 'Chuck Noland, a top international manager for FedEx, and Kelly, a Ph.D. student, are in love and heading towards marriage. Then Chuck''s plane to Malaysia crashes at sea during a terrible storm. He''s the only survivor, and finds himself marooned on a desolate island. With no way to escape, Chuck must find ways to survive in his new home.', 143, '/7lLJgKnAicAcR5UEuo8xhSMj18w.jpg', '/oCFVYPXI4IfhtF3GapU2jkDicDI.jpg', '4tVklCz2jcI'),
    (8363, 'Two co-dependent high school seniors are forced to deal with separation anxiety after their plan to stage a booze-soaked party goes awry.', 113, '/ek8e8txUyUwd2BNqj6lFEerJfbq.jpg', '/coru98UcFBzJIU7bxZguxaePgu0.jpg', 'LvKvus3vCEY'),
    (8367, 'Nobleman crusader Robin of Locksley breaks out of a Jerusalem prison with the help of Moorish fellow prisoner Azeem and travels back home to England. But upon arrival he discovers his dead father in the ruins of his family estate, killed by the vicious sheriff of Nottingham, Robin and Azeem join forces with outlaws Little John and Will Scarlett to save the kingdom from the sheriff''s villainy.', 143, '/hbRnWUNJkKKVN5mkcuC5ooqjE4e.jpg', '/kuLk79GQq8WQb8fZxc6MtvIhPaC.jpg', 'k8IYE8N3ink'),
    (8373, 'Sam Witwicky leaves the Autobots behind for a normal life. But when his mind is filled with cryptic symbols, the Decepticons target him and he is dragged back into the Transformers'' war.', 150, '/pLBb0whOzVDtJvyD4DPeQyQNOqp.jpg', '/bH1bhjn37uA1zOPvyHbzJSvza7v.jpg', 'fnXzKwUgDhg'),
    (8374, 'Tired of the crime overrunning the streets of Boston, Irish Catholic twin brothers Conner and Murphy are inspired by their faith to cleanse their hometown of evil with their own brand of zealous vigilante justice. As they hunt down and kill one notorious gangster after another, they become controversial folk heroes in the community. But Paul Smecker, an eccentric FBI agent, is fast closing in on their blood-soaked trail.', 108, '/wtLUmkWg41xFLpvmUWAN1mm65f6.jpg', '/9DNDELpVxuLJWMoomgULhhZFoHR.jpg', 'IMs4ESRJuCU'),
    (8392, 'Two sisters move to the country with their father in order to be closer to their hospitalized mother, and discover the surrounding trees are inhabited by Totoros, magical spirits of the forest. When the youngest runs away from home, the older sister seeks help from the spirits to find her.', 86, '/rtGDOeG9LzoerkDGZF9dnVeLppL.jpg', '/zkThiZAaAie8Lw7RAc5yPTOewBV.jpg', '_nv94fL_IA8'),
    (8413, 'In 2047, a group of astronauts are sent to investigate and salvage the starship Event Horizon which disappeared mysteriously seven years before on its maiden voyage. However, it soon becomes evident that something sinister resides in its corridors.', 96, '/qfluaDXv0cIdLwgQWzNB2piHL2q.jpg', '/nByMcYBhChTs2TF9fEFcTSsjme5.jpg', 'Ix9CHnOo94k'),
    (8456, 'Jake, full of anger after his father''s death, is just starting to find a place for himself at his new Orlando high school - until Ryan, head of an underground MMA fight club, picks Jake out as a prime opponent. After being trounced by Ryan in front of the entire school, Jake begins training under the firm, moral guidance of a MMA master, where he learns how to fight... and how to avoid a fight. But it becomes obvious that a rematch will be inevitable if Jake wants to stop Ryan and his bullying, once and for all.', 113, '/8oRUTyP1QAtGDMvRpKZyuyFPG0U.jpg', '/5XlOI0yFHIdAMKJBoN2hMHAZqay.jpg', '7X8O-OBJY4g'),
    (8467, 'Lloyd and Harry are two men whose stupidity is really indescribable. When Mary, a beautiful woman, loses an important suitcase with money before she leaves for Aspen, the two friends (who have found the suitcase) decide to return it to her. After some "adventures" they finally get to Aspen where, using the lost money they live it up and fight for Mary''s heart.', 107, '/4LdpBXiCyGKkR8FGHgjKlphrfUc.jpg', '/8uBTDGRcNHhYChcoazP5rleRME7.jpg', 'OyJhN2Es7Cw'),
    (8487, 'Legless Southern inventor Dr. Arliss Loveless plans to rekindle the Civil War by assassinating President Ulysses S. Grant. Only two men can stop him: gunfighter James West and master-of-disguise and inventor Artemus Gordon. The two must team up to thwart Loveless'' plans.', 106, '/mCdo7nykEVCa25bjnkwgyX35fjm.jpg', '/tbzWgnaqhFwN5mCIiwbgN5oiw0V.jpg', 'wSRtRrPBTT8'),
    (8488, 'Dating coach Alex ''Hitch'' Hitchens mentors a bumbling client, Albert, who hopes to win the heart of the glamorous Allegra Cole. While Albert makes progress, Hitch faces his own romantic setbacks when proven techniques fail to work on Sara Melas, a tabloid reporter digging for dirt on Allegra Cole''s love life. When Sara discovers Hitch''s connection to Albert – now Allegra''s boyfriend – it threatens to destroy both relationships.', 118, '/x3W9H3nhGQbWSlyI8Amp2F6Z6cz.jpg', '/a6tIX4fGgp60w2d9pqYRbFM91ne.jpg', 'dMaq_pfxs-0'),
    (8584, 'Chon Wang, a clumsy imperial guard, trails Princess Pei Pei when she''s kidnapped from the Forbidden City and transported to America. Wang follows her captors to Nevada, where he teams up with an unlikely partner, outcast outlaw Roy O''Bannon, and tries to spring the princess from her imprisonment.', 110, '/b0WwWRcDiDahkah5vZ0KjB4N9ZZ.jpg', '/xuwPmDMHslcx71T7zHc9YqF2Ny3.jpg', 'FqHg5fc_0_U'),
    (8587, 'Young lion prince Simba, eager to one day become king of the Pride Lands, grows up under the watchful eye of his father Mufasa; all the while his villainous uncle Scar conspires to take the throne for himself. Amid betrayal and tragedy, Simba must confront his past and find his rightful place in the Circle of Life.', 89, '/sKCr78MXSLixwmZ8DyJLrpMsd15.jpg', '/wXsQvli6tWqja51pYxXNG1LFIGV.jpg', 'lFzVJEksoDY'),
    (8619, 'After an abrupt and violent encounter with a French warship inflicts severe damage upon his ship, a captain of the British Royal Navy begins a chase over two oceans to capture or destroy the enemy, though he must weigh his commitment to duty and ferocious pursuit of glory against the safety of his devoted crew, including the ship''s thoughtful surgeon, his best friend.', 138, '/7ZUHF6P0vcA5v1Gm8NbRYyd9w4N.jpg', '/zMHyNxNt4zhL939XX8QLBW3gWfu.jpg', 'tHTHCNYiiHk'),
    (8645, 'When a deadly airborne virus threatens to wipe out the northeastern United States, teacher Elliot Moore and his wife Alma flee from contaminated cities into the countryside in a fight to discover the truth. Is it terrorism, the accidental release of some toxic military bio weapon -- or something even more sinister?', 90, '/fP4nBrtmc0teSDDHzYmDE7TLQBT.jpg', '/6moXpp6y1EZ6pfnSxnKFMrbFnWv.jpg', 'TIQ21m1Ks08'),
    (8649, 'Once called "Father Frank" for his efforts to rescue lives, Frank Pierce sees the ghosts of those he failed to save around every turn. He has tried everything he can to get fired, calling in sick, delaying taking calls where he might have to face one more victim he couldn''t help, yet cannot quit the job on his own.', 121, '/gE2Q8mL0m0EA6HakRyc92uzSPJn.jpg', '/6UgzxKBBIdfTLrDQdDdFf1gpBBa.jpg', 'sfUwvmRmMtw'),
    (8681, 'Bryan Mills, a former government operative, is trying to reconnect with his teenage daughter Kim. After reluctantly agreeing with his ex-wife to let Kim go to Paris on vacation with a friend, his worst nightmare comes true. While on the phone with his daughter shortly after she arrives in Paris, she and her friend are abducted by a gang of human traffickers. Working against the clock, Bryan relies on his extensive training and skills to track down the ruthless gang that abducted her and launch a one-man war to rescue his daughter.', 94, '/ognkaUSNgJe1a2pjB4UNdzEo5jT.jpg', '/ysCmtf9Y9fLDChZ88PXId5RbLP1.jpg', 'ZxKDnpiJaVc'),
    (8689, 'A New York University professor returns from a rescue mission to the Amazon rainforest with the footage shot by a lost team of documentarians who were making a film about the area''s local cannibal tribes.', 96, '/otxZzMh53TsN7yYFqSZ3rwH1yMd.jpg', '/fhPSg2a8tuGfTv3vohoOgRLFhQG.jpg', 'cZ-Xp6VC7RQ'),
    (8698, 'To prevent a world war from breaking out, famous characters from Victorian literature band together to do battle against a cunning villain.', 110, '/kdAuVFP63XXxnb983ry2pLCKd9S.jpg', '/n3VpgjdOB1DkHSUe1DbFzV8ncpJ.jpg', 'fndHh-SEDe0'),
    (8699, 'It''s the 1970s and San Diego anchorman Ron Burgundy is the top dog in local TV, but that''s all about to change when ambitious reporter Veronica Corningstone arrives as a new employee at his station.', 95, '/mhZIcRePT7U8viFQVjt1ZjYIsR4.jpg', '/qWSI9Lpq8K4o1n9ZD9zUVD4Gds1.jpg', '-T3wnP91OnI'),
    (8810, 'Max Rockatansky returns as the heroic loner who drives the dusty roads of a postapocalyptic Australian Outback in an unending search for gasoline. Arrayed against him and the other scraggly defendants of a fuel-depot encampment are the bizarre warriors commanded by the charismatic Lord Humungus, a violent leader whose scruples are as barren as the surrounding landscape.', 96, '/l1KVEhkGDpWRzQ0VqIhZqDDuOim.jpg', '/MMSI9WzRmOdqXarevQ3Kqnytrx.jpg', 'bwcADuJZDNA'),
    (8814, 'A team of space marines known as the Rapid Response Tactical Squad, led by Sarge, is sent to a science facility on Mars after somebody reports a security breach. There, they learn that the alert came after a test subject, a mass murderer purposefully injected with alien DNA, broke free and began killing people. Dr. Grimm, who is related to team member Reaper, informs them all that the chromosome can mutate humans into monsters -- and is highly infectious.', 105, '/nkzyhae9Eb9Eglbi6T5iEuPD6L.jpg', '/9EpgaLS44zlXoTSAOhGiJmkIA4B.jpg', 'LljkKoPs1Gg'),
    (8835, 'Fashionable sorority queen Elle Woods has it all, but, she wants nothing more than to be Mrs. Warner Huntington III. But he dumps her before heading to Harvard Law School. Elle rallies all of her resources and gets into Harvard, determined to win him back. While there, she figures out that there is more to herself than just good looks.', 96, '/9ohlMrJHQqKhfUKh7Zr3JQqHNLZ.jpg', '/viU23X3BIycUFf6TOlm9c7TxLgM.jpg', 'yBSVBk1Add0'),
    (8839, 'Casper is a kind young ghost who peacefully haunts a mansion in Maine. When specialist James Harvey arrives to communicate with Casper and his fellow spirits, he brings along his teenage daughter, Kat. Casper quickly falls in love with Kat, but their budding relationship is complicated not only by his transparent state, but also by his troublemaking apparition uncles and their mischievous antics.', 100, '/2ah8fNJFZVU3vcXhU5xfAYi2eym.jpg', '/sQPckU0TfSeYIlUneHfIXwzQC2f.jpg', 'kRX7PPqbKaQ'),
    (8843, 'A team of scientists use experimental technology to help a psychotherapist enter the mind of a comatose serial killer in the hopes of saving his latest victim.', 107, '/1LX8AOUGDSrBDzgC4KLtRvyJFgY.jpg', '/iFJ7GEIjIysbEJ36TohH28x6Nyu.jpg', 'ZhH3CHunglk'),
    (8844, 'When siblings Judy and Peter discover an enchanted board game that opens the door to a magical world, they unwittingly invite Alan -- an adult who''s been trapped inside the game for 26 years -- into their living room. Alan''s only hope for freedom is to finish the game, which proves risky as all three find themselves running from giant rhinoceroses, evil monkeys and other terrifying creatures.', 104, '/bdHG5Mo83VPobeZZdlSz0Y7HQHB.jpg', '/qSxeCfWUUyht9hZgaaYmtPtTkw2.jpg', 'veszTagaXik'),
    (8848, 'Terry is a small-time car dealer trying to leave his shady past behind and start a family. Martine is a beautiful model from Terry''s old neighbourhood who knows that Terry is no angel. When Martine proposes a foolproof plan to rob a bank, Terry recognises the danger but realises this may be the opportunity of a lifetime.', 112, '/bfXjFTytfFTdo9WeO7lYqzkHG7g.jpg', '/ynnarxTMs8jWKV9GK0SpUhGNCgH.jpg', 'tdiWAhlVOBY'),
    (8856, 'Summoned by his dying father, Miyagi returns to his homeland of Okinawa, with Daniel, after a 40-year exile. There he must confront Yukie, the love of his youth, and Sato, his former best friend turned vengeful rival. Sato is bent on a fight to the death, even if it means the destruction of their village. Daniel finds his own love in Yukia''s niece, Kumiko, and his own enemy in Sato''s nephew, the vicious Chozen. Now, far away from the tournaments, cheering crowds and safety of home, Daniel will face his greatest challenge ever when the cost of honor is life itself.', 113, '/k0OwgRR6PNu7h3SiqpCbRdZWNaG.jpg', '/7rfcRXbFD0xr8NteNq1hwXUd4Af.jpg', 'siRMz-PyjZI'),
    (8871, 'The Grinch decides to rob Whoville of Christmas - but a dash of kindness from little Cindy Lou Who and her family may be enough to melt his heart...', 105, '/1WZbbPApEivA421gCOluuzMMKCk.jpg', '/sy0vo1cmpKqwPRiMUiJ45jyLsX7.jpg', 'UnyPPS1Z-Vs'),
    (8872, 'The adventures of two amiably aimless metal-head friends, Wayne and Garth. From Wayne''s basement, the pair broadcast a talk-show called "Wayne''s World" on local public access television. The show comes to the attention of a sleazy network executive who wants to produce a big-budget version of "Wayne''s World"—and he also wants Wayne''s girlfriend, a rock singer named Cassandra. Wayne and Garth have to battle the executive not only to save their show, but also Cassandra.', 94, '/fHwZnFNWR7PaS9t5EBwTvGPeoYQ.jpg', '/lAvf5zzyOgTZmpRBRJFa7IVVqCK.jpg', 'eBzr2UDK4DM'),
    (8909, 'Doormat Wesley Gibson is an office worker whose life is going nowhere. He meets an attractive woman named Fox and discovers that his recently murdered father - whom Wesley never knew - belonged to the Fraternity, a secret society of assassins which takes its orders from Fate itself. Fox and Sloan, the Fraternity''s leader, teach Wesley, through intense training, to tap into dormant powers and hone his innate killing skills. Though he enjoys his newfound abilities, he begins to suspect that there is more to the Fraternity than meets the eye.', 110, '/njy7Pz7ZHZceO7lNfGIHKphY8Hd.jpg', '/vjwuT8EzWY96W6nrJKZNI2WJU87.jpg', 'b9YEdjEKme0'),
    (8913, 'After the Creed family''s cat is accidentally killed, a friendly neighbor advises its burial in a mysterious nearby cemetery.', 103, '/8ZtH1V4rhrtP53ezlEWrCaMALXF.jpg', '/xWq3T9P4NU2pTdZ3hXFygsNnAq4.jpg', 'jpjpUOXQZac'),
    (8916, 'A neurotic worker ant in love with a rebellious princess rises to unlikely stardom when he switches places with a soldier. Signing up to march in a parade, he ends up under the command of a bloodthirsty general. But he''s actually been enlisted to fight against a termite army.', 83, '/lWPjxbUMpAHFkJpZHHNWhQaRsax.jpg', '/i4NvcHeYeAdLEFiLxEVvUA3BT0.jpg', 'g4SiWDIoFhE'),
    (8920, 'Garfield, the fat, lazy, lasagna lover, has everything a cat could want. But when Jon, in an effort to impress the Liz - the vet and an old high-school crush - adopts a dog named Odie and brings him home, Garfield gets the one thing he doesn''t want. Competition.', 80, '/vqwTSWNLyH55g8kBT61s2DgNYEp.jpg', '/r8Vk1PJ7eDwRKDZJOS4AKC7puK3.jpg', '5g1SLGRM6qU'),
    (8922, 'On a desolate country highway, two homeward-bound teens are nearly run off the road by a maniac in a beat-up truck, and later spot him shoving what appears to be a body down a sewer pipe.', 90, '/g410Y1U1ELbmJG14Zru3UAimm1G.jpg', '/m0yTFeh8vrsMP0fQDdYGSh4xthX.jpg', 'ACMqG1WdPQk'),
    (8923, 'After being wrongfully expelled from Harvard University, American Matt Buckner flees to his sister''s home in England. Once there, he is befriended by her charming and dangerous brother-in-law, Pete Dunham, and introduced to the underworld of British football hooliganism. Matt learns to stand his ground through a friendship that develops against the backdrop of this secret and often violent world. ''Green Street Hooligans'' is a story of loyalty, trust and the sometimes brutal consequences of living close to the edge.', 109, '/oTxHFRSbFcCWdfJB4ozA41Yq57c.jpg', '/isRzCN0ATsZ4CdBf6CSGA2ruclW.jpg', 'EAe-1Lv1KYU'),
    (8960, 'Hancock is a down-and-out superhero who''s forced to employ a PR expert to help repair his image when the public grows weary of all the damage he''s inflicted during his lifesaving heroics. The agent''s idea of imprisoning the antihero to make the world miss him proves successful, but will Hancock stick to his new sense of purpose or slip back into old habits?', 92, '/7DyuV2G0hLEqHeueDfOqhZ2DVut.jpg', '/xh0ZRdnL4pSqfW73HBf97xiNEFP.jpg', 'vexi9xLS-bQ'),
    (8961, 'Detectives Marcus Burnett and Mike Lowrey of the Miami Narcotics Task Force are tasked with stopping the flow of the drug Ecstasy into Miami. They track the drugs to the whacked-out Cuban drug lord Johnny Tapia, who is also involved in a bloody war with Russian and Haitian mobsters. If that isn''t bad enough, there''s tension between the two detectives when Marcus discovers that playboy Mike is secretly romancing Marcus’ sister, Syd.', 146, '/yCvB5fG5aEPqa1St7ihY6KEAsHD.jpg', '/gxSVZCUlDd8upT1G2wdrUdz2hxG.jpg', 'MsGSpfK6H4A'),
    (8965, 'Milo and Kida reunite with their friends to investigate strange occurances around the world that seem to have links to the secrets of Atlantis.', 80, '/hyAbWGld5WLdrmUB9OHyewcJQGL.jpg', '/3raqIytmaDD9AkAWh8W0FYtx3gX.jpg', 'P4ac-I7aDTE'),
    (8966, 'When Bella Swan moves to a small town in the Pacific Northwest, she falls in love with Edward Cullen, a mysterious classmate who reveals himself to be a 108-year-old vampire. Despite Edward''s repeated cautions, Bella can''t stay away from him, a fatal move that endangers her own life.', 122, '/3Gkb6jm6962ADUPaCBqzz9CTbn9.jpg', '/weAYfu6FfrNxEDJ3xH1XpgQcqUv.jpg', 'uxjNDE2fMjI'),
    (8967, 'The impressionistic story of a Texas family in the 1950s. The film follows the life journey of the eldest son, Jack, through the innocence of childhood to his disillusioned adult years as he tries to reconcile a complicated relationship with his father. Jack finds himself a lost soul in the modern world, seeking answers to the origins and meaning of life while questioning the existence of faith.', 139, '/l8cwuB5WJSoj4uMAsnzuHBOMaSJ.jpg', '/xq1HIwZq9VbuvMQELAua1nqEkH.jpg', 'RrAz1YLh8nY'),
    (9016, 'When space galleon cabin boy Jim Hawkins discovers a map to an intergalactic "loot of a thousand worlds," a cyborg cook named John Silver teaches him to battle supernovas and space storms on their journey to find treasure.', 96, '/kNhZkR3UNbXfvESQo7mJpOi4tGd.jpg', '/f2opsSUSiMdEp6AiY2sbC8QPd8S.jpg', 'ajhZRL1j7a0'),
    (9023, 'Against impossible odds, Spirit, a young mustang, sets out across the majestic wilderness to regain his freedom and save his homeland. Along the way, he forms a friendship with a young Lakota brave, outwits a squadron of soldiers, and ultimately, finds love.', 83, '/bBEkKDQFianNYwGWR7gJfPVakmG.jpg', '/b8hPBW0NJmiIVzvQjT3CwIpAdzl.jpg', 'RPJ4EQ2Eh9I'),
    (9032, 'A lazy law school grad adopts a kid to impress his girlfriend, but everything doesn''t go as planned. Now he''s forced to grow up while navigating the challenges of fatherhood.', 93, '/lEYg1X8RjqNB5NWEtodcbK7vm1G.jpg', '/fl3no3IMXGjZAUa2iU9aBzlid5m.jpg', 'J_l5fMb1oxg'),
    (9040, 'New York cop Frank Serpico blows the whistle on the rampant corruption in the force only to have his comrades turn against him.', 129, '/pRagfd10PPWryFRSzLPIivfAXHJ.jpg', '/dXlO2Ri2RvVYWRtBsr6GsIVkleX.jpg', 'eoP6bH2ymFo'),
    (9078, 'Wart is a young boy who aspires to be a knight''s squire. On a hunting trip he falls in on Merlin, a powerful but amnesiac wizard who has plans for him beyond mere squiredom. He starts by trying to give him an education, believing that once one has an education, one can go anywhere. Needless to say, it doesn''t quite work out that way.', 79, '/7lyeeuhGAJSNXYEW34S8mJ1bwI8.jpg', '/uMe6McFXAPEhkasGVlaLTOuhfnl.jpg', 'ThOtoGV6ylU'),
    (9273, 'Summoned from an ashram in Tibet, Ace finds himself on a perilous journey into the jungles of Africa to find Shikaka, the missing sacred animal of the friendly Wachati tribe. He must accomplish this before the wedding of the Wachati''s Princess to the prince of the warrior Wachootoos. If Ace fails, the result will be a vicious tribal war.', 90, '/wcinCf1ov2D6M3P7BBZkzQFOiIb.jpg', '/h5Y9T4OoFpMrONhVBZvN2X2DfAB.jpg', 'DfqPjRMsRP0'),
    (9277, 'A novice con man teams up with an acknowledged master to avenge the murder of a mutual friend by pulling off the ultimate big con and swindling a fortune from a big-time mobster.', 129, '/ckmYng37zey8INYf6d10cVgIG93.jpg', '/1r9lH3DaSWKGyvZaoo6BF5STOk5.jpg', '_nAIb_J9T5M'),
    (9279, 'Howard Langston, a salesman for a mattress company, is constantly kept busy at his job, disappointing his son. After he misses his son''s karate exposition, Howard vows to make it up to him by buying an action figure of his son''s favorite television hero for Christmas. Unfortunately for Howard, it is Christmas Eve, and every store is sold out of Turbo Man. Now, Howard must travel all over town and compete with everybody else to find a Turbo Man action figure.', 89, '/vhdLrQ3P2JxlxsTREUsr2nbtnjS.jpg', '/rnn6sGMGPpM8VfVmCMFxsjKvz7q.jpg', '04CWFXHYMGk'),
    (9285, 'After a student at the University of Ithaca films his one-night stand with a beautiful sorority girl, he discovers one of his friends has accidentally mailed the homemade sex tape to his girlfriend in Austin. In a frenzy, he must borrow a car and hit the road in a desperate bid to intercept the tape.', 93, '/jee4eY5tZprI0V18S6PXUloBzSk.jpg', '/cV0JkbhWNSgfRmENuVMkkDvNgdG.jpg', 'NU9NYU9O0Hw'),
    (9286, 'High school senior Wendy''s premonition of a deadly rollercoaster ride saves her life and a lucky few, but not from death itself — which seeks out those who escaped their fate.', 92, '/p7ARuNKUGPGvkBiDtIDvAzYzonX.jpg', '/nSV1NIAK0Sp5dM1oiobtqbJ8Jrv.jpg', 'ttgUq963nFc'),
    (9291, 'Disgraced pro football quarterback Paul Crewe lands in a Texas federal penitentiary, where manipulative Warden Hazen recruits him to advise the institution''s football team of prison guards. Crewe suggests a tune-up game which lands him quarterbacking a crew of inmates in a game against the guards. Aided by incarcerated ex-NFL coach and player Nate Scarborough, Crewe and his team must overcome not only the bloodthirstiness of the opposition, but also the corrupt warden trying to fix the game against them.', 113, '/nbKcVBcxF96ARW2oKHqDYAcLdu.jpg', '/63V4wbVah1gnjckPJnSU0ZmOGAW.jpg', 'Cl--Ye9pmAQ'),
    (9297, 'Monsters under the bed are scary enough, but what happens when an entire house is out to get you? Three teens aim to find out when they go up against a decrepit neighboring home and unlock its frightening secrets.', 91, '/zCRPr4bkO3ae0U1134vJ39xZnAG.jpg', '/aDnCTWpWMHcQxOeGWsITmoLuEGy.jpg', 'kS8eoP8bols'),
    (9303, 'Corky, a tough female ex-convict working on an apartment renovation in a Chicago building, meets a couple living next door, Caesar, a paranoid mobster, and Violet, his seductive girlfriend, who is immediately attracted to her.', 105, '/9qAy6UWVw44dGrsyKrdEMt5qIUM.jpg', '/pMvTpyls1l3OEGKBvgRwKMT8a6O.jpg', 'WHBmxInOC4E'),
    (9313, 'Years have passed since the Three Musketeers, Aramis, Athos and Porthos, have fought together with their friend, D''Artagnan. But with the tyrannical King Louis using his power to wreak havoc in the kingdom while his twin brother, Philippe, remains imprisoned, the Musketeers reunite to abduct Louis and replace him with Philippe.', 132, '/zHE9yRURvA7DyhYtQxkGTfE1Ywi.jpg', '/uhhtglfXNaTavkKtjer38qHLfVi.jpg', 'gnNt7l2nA_o'),
    (9322, 'A beautiful felon, sentenced to life in prison for the murder of a policeman, is given a second chance – as a secret political assassin controlled by the government.', 117, '/1ulQDewUG4KKHOhpXdGKm3GdLFq.jpg', '/rk56vslwBXUCcNlQ74s6gmpJqxa.jpg', 'Gh8RoDMUUsA'),
    (9323, 'In the year 2029, the barriers of our world have been broken down by the net and by cybernetics, but this brings new vulnerability to humans in the form of brain-hacking. When a highly-wanted hacker known as ''The Puppetmaster'' begins involving them in politics, Section 9, a group of cybernetically enhanced cops, are called in to investigate and stop the Puppetmaster.', 83, '/9gC88zYUBARRSThcG93MvW14sqx.jpg', '/jIpagj2Dud9g3ZVJFvaWikEWsYz.jpg', 'R1K__7QhLaA'),
    (9325, 'The boy Mowgli makes his way to the man-village with Bagheera, the wise panther. Along the way he meets jazzy King Louie, the hypnotic snake Kaa and the lovable, happy-go-lucky bear Baloo, who teaches Mowgli "The Bare Necessities" of life and the true meaning of friendship.', 78, '/yN1kuupnPTLUprgfvC5WapgrxG4.jpg', '/3sbmRuIpYEH5dMvec4z4JxKQHoj.jpg', 'qdkU9NmI0jA'),
    (9335, 'Professional driver, and former Special Forces officer, Frank Martin is living in Miami, where he is temporarily filling in for a friend as the chauffeur for a government narcotics control policy director and his family. The young boy in the family is targeted for kidnapping, and Frank immediately becomes involved in protecting the child and exposing the kidnappers.', 88, '/cdm17vK8PxHfTi7ayZf6WKbOgUO.jpg', '/lbs1ood36hzj0O0cqW2a8MqptOh.jpg', 'rEggzzOVOyo'),
    (9339, 'A married workaholic, Michael Newman doesn''t have time for his wife and children, not if he''s to impress his ungrateful boss and earn a well-deserved promotion. So when he meets Morty, a loopy sales clerk, he gets the answer to his prayers: a magical remote that allows him to bypass life''s little distractions with increasingly hysterical results.', 107, '/oL0k5JA53PyoHSZqKb3cNkhwBCE.jpg', '/n6eIm882V7cj0In0xp8QXNItoTp.jpg', 'APUqyhgtCfk'),
    (9340, 'Young teen Mikey Walsh and his friends set off on a quest to find Pirate One-Eyed Willie''s treasure in hopes of saving their homes from demolition. However, on their quest to find the treasure, they run into a family of recently escaped criminals, determined to capture the kids and reach the treasure first.', 114, '/eBU7gCjTCj9n2LTxvCSIXXOvHkD.jpg', '/5qsyqA7FeYRymBmNbPBqBgqWPO4.jpg', 'lYLAGAwcpSQ'),
    (9342, 'It has been twenty years since Don Diego de la Vega fought Spanish oppression in Alta California as the legendary romantic hero, Zorro. Having escaped from prison he transforms troubled bandit Alejandro into his successor, in order to foil the plans of the tyrannical Don Rafael Montero who robbed him of his freedom, his wife and his precious daughter.', 138, '/y7x5tAFqE589IHwTUfamstD53RM.jpg', '/cwII5LZyvAMcjeEv1N12T5ic7cr.jpg', 'abwtRFZx8Rs'),
    (9344, 'A group of bored, disaffected New York City teenagers spend a day skating, smoking, drinking, partying, deflowering virgins, and getting into fights.', 91, '/8qV8hUVCUnFIQKewzlhaFWhdszK.jpg', '/3gmreIMvzQgd1q4hsiUN5ADV88W.jpg', 'U9a5tZSKDOU'),
    (9352, 'When Scott learns that his longtime cyber-buddy from Berlin is a gorgeous young woman, he and his friends embark on a trip across Europe.', 92, '/iLdO4PwbZCCQSa9rchZMwuJm9xe.jpg', '/kg8na5u6qdCydm7cK7p2I0zQmgr.jpg', '-_Eu0X3B6OM'),
    (9354, 'The scientist father of a teenage girl and boy accidentally shrinks his and two other neighborhood teens to the size of insects. Now the teens must fight diminutive dangers as the father searches for them.', 93, '/omQOzahi2NIeiYznNxHFDvNbvo6.jpg', '/jQuP23kN9iEBglGpw4AxRagoqBf.jpg', '_av5kqcMVm4'),
    (9358, 'When Kimberly has a violent premonition of a highway pileup she blocks the freeway, keeping a few others meant to die, safe...Or are they? The survivors mysteriously start dying and it''s up to Kimberly to stop it before she''s next.', 90, '/dg6Tf98InieJSClSKQJTQevYWmB.jpg', '/tKnmfO5lAyu8hpTZMyMaI4lhZpJ.jpg', 'MNXpuPu4URk'),
    (9362, 'Val McKee and Earl Bassett are in a fight for their lives when they discover that their desolate town has been infested with gigantic, man-eating creatures that live below the ground.', 96, '/cA4ggkZ3r1d5r9hOAUWC8x5ul2i.jpg', '/3L3DUwfRLW18OUiLSdmovfICyY3.jpg', 'msngBcC75LI'),
    (9366, 'An FBI undercover agent infiltrates the mob and identifies more with the mafia life at the expense of his regular one.', 127, '/xtKLvpOfARi1XVm8u2FTdhY5Piq.jpg', '/gXWzBnxUfLCT0w0WzAmJ5wF37hC.jpg', 'TDWkpydv51k'),
    (9373, 'After picking up a traumatized young hitchhiker, five friends find themselves stalked and hunted by a chainsaw-wielding killer and his family of equally psychopathic killers.', 98, '/781px1eOtfVt1RdIsL4Dt1s3x7R.jpg', '/xnShZK7y4lupUmXghz75HRSooW9.jpg', 'y2NDtxcE2DY'),
    (9377, 'After high school slacker Ferris Bueller successfully fakes an illness in order to skip school for the day, he goes on a series of adventures throughout Chicago with his girlfriend Sloane and best friend Cameron, all the while trying to outwit his wily school principal and fed-up sister.', 103, '/9LTQNCvoLsKXP0LtaKAaYVtRaQL.jpg', '/jehzP4JKiFzgTWIaASLFOJocJke.jpg', '0ZDbKhkLxTs'),
    (9378, 'Arthur and his two children inherit his uncle''s estate: a glass house that serves as a prison to twelve ghosts. When the family, accompanied by a nanny and an attorney, enter the house they find themselves trapped inside an evil machine ''designed by the Devil and powered by the dead'' to open the Eye of Hell. Aided by a ghost hunter and his rival, a ghost rights activist out to set the ghosts free, the group must do what they can to get out of the house alive.', 91, '/6yrrddjIjx0ElCRZp5pTZeqrj3k.jpg', '/x30bpi16AFWrfGVhYMqujbcCAWS.jpg', 'Xj1LWNgG0Ng'),
    (9390, 'Jerry Maguire used to be a typical sports agent: willing to do just about anything he could to get the biggest possible contracts for his clients, plus a nice commission for himself. Then, one day, he suddenly has second thoughts about what he''s really doing. When he voices these doubts, he ends up losing his job and all of his clients, save Rod Tidwell, an egomaniacal football player.', 139, '/lABvGN7fDk5ifnwZoxij6G96t2w.jpg', '/a66PKC32YVZISoqZtRQyz8c9Vx6.jpg', 'x1V_WduwrE8'),
    (9392, 'After a personal tragedy, Sarah joins her friends on a caving expedition in the Appalachian Mountains. But when a rockfall traps them deep underground, their adventure turns into a nightmare. As they search for a way out, the group discovers they are not alone—lurking in the darkness are savage, cave-dwelling creatures. With rising tension and dwindling trust, the women must fight to survive against both the predators and each other.', 100, '/mxFPI4KYBk5ri9cPteIS8jiDFgj.jpg', '/9T5D5RGuCsC6CeqYZJTv4rT4RPy.jpg', '_onLUDusszw'),
    (9397, 'A comedy that follows the chaos that ensues when a meteor hits the Earth carrying alien life forms that give new meaning to the term "survival of the fittest." David Duchovny, Orlando Jones, Seann William Scott, and Julianne Moore are the only people standing between the aliens and world domination... which could be bad news for the Earth.', 102, '/dwIrP544LxJtXToLpzkEa08pIMm.jpg', '/uQVXQ7VI0jbLDo5QwGGyLQUd1so.jpg', 'NCRrGp5bkjY'),
    (9398, 'Clear the runway for Derek Zoolander, VH1''s three-time male model of the year. His face falls when hippie-chic Hansel scooters in to steal this year''s award. The evil fashion guru Mugatu seizes the opportunity to turn Derek into a killing machine. It''s a well-designed conspiracy and only with the help of Hansel and a few well-chosen accessories like Matilda can Derek make the world safe for male models everywhere.', 89, '/qdrbSneHZjJG2Dj0hhBxzzAo4HB.jpg', '/lIyyiBOuyokL82rPEDcZaMKleA3.jpg', 'YtQq0T3ExLs'),
    (9399, 'Lyon Gaultier is a deserter in the Foreign Legion arriving in the USA entirely hard up. He finds his brother between life and death and his sister-in-law without the money needed to heal her husband and to maintain her child. To earn the money needed, Gaultier decides to take part in some very dangerous clandestine fights.', 105, '/kf3qx5fzsYyLv7PEAORUGxwzQEk.jpg', '/vxB5L14mQdszDWPPlvYnfM4FnXB.jpg', 'XZ4x4HqSGFk'),
    (9408, 'With a documentary crew in tow, Cody Maverick—a young surfer from Antarctica—travels to the pacific for his first professional competition. Determined to earn respect and live up to his idol, Big Z, Cody pushes himself to the limit. But all that changes when an encounter with a laid-back local forces him to rethink his values.', 85, '/tTDsCVlDA8QR4Dc6t6nERfwl5z.jpg', '/Y50RfoNVKIj9dSJavE8uBdN377.jpg', '7mPdQRXFiPA'),
    (9426, 'When brilliant, eccentric scientist Seth Brundle makes a huge technological breakthrough in teleportation, he decides to test it on himself. Unbeknownst to him, a common housefly manages to get inside the device and the two become one.', 96, '/8gZWMhJHRvaXdXsNhERtqNHYpH3.jpg', '/g1FzhbtWYKk9WMJYi1X26kf2Q4Q.jpg', 'YPhM5T1DViw'),
    (9428, 'Royal Tenenbaum and his wife Etheline had three children and then they separated. All three children are extraordinary --- all geniuses. Virtually all memory of the brilliance of the young Tenenbaums was subsequently erased by two decades of betrayal, failure, and disaster. Most of this was generally considered to be their father''s fault. "The Royal Tenenbaums" is the story of the family''s sudden, unexpected reunion one recent winter.', 110, '/nG7hZJn7wQTSDCQT39Gy3s3tbrp.jpg', '/cbuX448RKetr5Y5cZkmJEfu3xji.jpg', '-DNAI9bhBFU'),
    (9444, 'Ten years after she was separated from her family, an eighteen-year-old orphan with vague memories of the past sets out to Paris in hopes of reuniting with her grandmother. She is accompanied by two con men, who intend to pass her off as the Grand Duchess Anastasia to the Dowager Empress for a reward.', 94, '/bppGWGA8zq1sRvTdDJnUzVW9GcH.jpg', '/h6VshReCGaGQoaGZwT2wqiqrcZW.jpg', '1vC1Ju__0R8'),
    (9453, 'After the death of the paranoid emperor Tiberius, Caligula, his heir, seizes power and plunges the empire into a bloody spiral of madness and depravity.', 156, '/vNXAY6r9Pb6WkMCGmNeW2PlznLQ.jpg', '/cT6xO3YjzfZKYGhZ8S7plNlA27F.jpg', 'Nn8cKrkQ9cs'),
    (9470, 'It''s the 1940s, and the notorious Axe Gang terrorizes Shanghai. Small-time criminals Sing and Bone hope to join, but they only manage to make lots of very dangerous enemies. Fortunately for them, kung fu masters and hidden strength can be found in unlikely places. Now they just have to take on the entire Axe Gang.', 99, '/exbyTbrvRUDKN2mcNEuVor4VFQW.jpg', '/4JKluvwcYvhkTNvWP5N3kcUNsPl.jpg', '-m3IB7N_PRk'),
    (9472, 'When megalomaniacal White Goodman, the owner of a trendy, high-end fitness center, makes a move to take over the struggling local gym run by happy-go-lucky Pete La Fleur, there''s only one way for La Fleur to fight back: dodgeball. Aided by a dodgeball guru and Goodman''s attorney, La Fleur and his rag-tag team of underdogs launch a knock-down, drag-out battle in which the winner takes all.', 92, '/r8KbNHkkwFXLjV1suGwm0Qjure5.jpg', '/1nL5TJrldKI4rIj16tZTdqpdYL3.jpg', 'rZfmbdpVLAA'),
    (9473, 'The third graders of South Park sneak into an R-rated film by ultra-vulgar Canadian television personalities Terrance and Phillip, and emerge with expanded vocabularies that leave their parents and teachers scandalized. When outraged Americans try to censor the film, the controversy spirals into a call to wage war on Canada and Terrance and Phillip end up on death row, with the kids their only hope of rescue.', 81, '/tS0PedvA2mFO9VCHYwQpaU1K36U.jpg', '/2q3B90h2hZ6xJTvna9CIFDNaIr4.jpg', 'Tq-C9-QJV30'),
    (9475, 'Charlie Simms is a student at a private preparatory school who comes from a poor family. To earn the money for his flight home to Gresham, Oregon for Christmas, Charlie takes a job over Thanksgiving looking after retired U.S. Army officer Lieutenant Colonel Frank Slade, a cantankerous middle-aged man who lives with his niece and her family.', 156, '/4adI7IaveWb7EidYXfLb3MK3CgO.jpg', '/fa03pD2qYmms4ZMgAv7PMqfFiGO.jpg', '7xIYQgrd-Sg'),
    (9479, 'Tired of scaring humans every October 31 with the same old bag of tricks, Jack Skellington, the spindly Pumpkin King of Halloween Town, kidnaps Santa Claus and plans to deliver shrunken heads and other ghoulish gifts to children on Christmas morning in his place. But, as the holiday approaches, Jack''s rag-doll girlfriend Sally tries to foil his well-meaning yet misguided plans.', 76, '/oQffRNjK8e19rF7xVYEN8ew0j7b.jpg', '/dSfrsjhqC6lYe7LYDYnzWeXZmEl.jpg', 'IoYahD_xNR0'),
    (9480, 'By day, blind attorney Matt Murdock toils for justice in Hell''s Kitchen. By night, he''s Daredevil, The Man Without Fear - a powerful, masked vigilante stalking the dark streets with an uncanny "radar sense" that allows him to "see" with superhuman capabilities. But when the love of his life, fiery Elektra Natchios, is targeted by New York City''s ruthless Kingpin of crime and his deadly assassin Bullseye, Daredevil may be about to meet his match.', 103, '/oCDBwSkntYamuw8VJIxMRCtDBmi.jpg', '/e7jIX02GiSwsgkU5lMpeKjwq2Zc.jpg', 't3Xc6FjRfoA'),
    (9481, 'Lincoln Rhyme was the department''s top homicide detective and leading expert in criminal forensics until an injury left him paralyzed, depressed, and incapable of working. But when a gruesome murder in Manhattan leaves detectives baffled, they call on Rhyme to help solve the mystery. Amelia Donaghy, a rookie cop whose quick thinking preserved a gruesome murder scene, is enlisted by Rhyme to be his on-the-scene forensics expert. With Amelia reluctantly acting as Rhyme''s able-bodied go-between, the pair piece together cryptic clues the killer leaves behind at the scene of the crime, hoping to catch the grisly serial killer.', 118, '/7atMCqRaDpAOnGsteTRm17zmvN3.jpg', '/hMclNPye6G3ouN5QdusrlTK0SaE.jpg', 'krU7HZgCxsI'),
    (9486, 'A lowly pencil pusher working for MI7, Johnny English is suddenly promoted to super spy after Agent One is assassinated and every other agent is blown up at his funeral. When a billionaire entrepreneur sponsors the exhibition of the Crown Jewels—and the valuable gems disappear on the opening night and on English''s watch—the newly-designated agent must jump into action to find the thief and recover the missing gems.', 87, '/mmzW88tnkB2MnOV3Un2F9IUxSnZ.jpg', '/tGcIy7gA8jwYpi5W2UB1Rxrk2i6.jpg', '7VlpHnog6rw'),
    (9487, 'On behalf of "oppressed bugs everywhere," an inventive ant named Flik hires a troupe of warrior bugs to defend his bustling colony from a horde of freeloading grasshoppers led by the evil-minded Hopper.', 95, '/Ah3J9OJVc2CNCuH2zMydXy9fmIC.jpg', '/hwwFyowfcbLRVmRBOkvnABBNIOs.jpg', 'mE35XQFxbeo'),
    (9488, 'Exploring the further adventures of Carmen and Juni Cortez, who have now joined the family spy business as Level 2 OSS agents. Their new mission is to save the world from a mad scientist living on a volcanic island populated by an imaginative menagerie of creatures. On this bizarre island, none of the Cortez''s gadgets work and they must rely on their wits--and each other--to survive and save the day.', 100, '/z8pfWCk6SlxxDLXXQdUHdxF5dwJ.jpg', '/5rKa5UKXnTdLsgY0mJbjAEQX3gB.jpg', 'RLkRbj8sv8E'),
    (9489, 'Book superstore magnate Joe Fox and independent book shop owner Kathleen Kelly fall in love in the anonymity of the Internet—both blissfully unaware that he''s trying to put her out of business.', 119, '/rJLUSpmdxSMqqEsyzeCni3vy1ca.jpg', '/9lYpkcO7WuruOXB2mn8ppC6Ecaq.jpg', 'AKlhYZ-HqKs'),
    (9493, 'Julius and Vincent Benedict are the results of an experiment that would allow for the perfect child. Julius was planned and grows to athletic proportions. Vincent is an accident and is somewhat smaller in stature. Vincent is placed in an orphanage while Julius is taken to a south seas island and raised by philosophers. Vincent becomes the ultimate low life and is about to be killed by loan sharks.', 107, '/stJx9BQZbXrZnTGf9Erc7d2UMVc.jpg', '/sAtK99PjOX1IzDUV24N2nab803R.jpg', 'eRdcL2qKt6k'),
    (9495, 'Exactly one year after young rock guitarist Eric Draven and his fiancée are brutally killed by a ruthless gang of criminals, Draven, watched over by a hypnotic crow, returns from the grave to exact revenge.', 102, '/rMMB3v6jYHjsvXRNJYESacoTD7j.jpg', '/2VN9umruwVZsT1Pr1NMCV71HpUu.jpg', 'Ltzov6nhud0'),
    (9502, 'Chosen by prophecy but doubted by all, Po is an unlikely choice for the mystical title of the Dragon Warrior—a clumsy panda thrust into the world of kung fu as a deadly enemy threatens the Valley of Peace. Under reluctant guidance by Master Shifu and the Furious Five, Po must embrace who he is to unlock the power that no scroll can teach.', 90, '/wWt4JYXTg5Wr3xBW2phBrMKgp3x.jpg', '/qdthf9WrRDSaIkGVQGhhJ9pz1hn.jpg', 'NRc-ze7Wrxw'),
    (9509, 'Jaded ex-CIA operative John Creasy reluctantly accepts a job as the bodyguard for a 10-year-old girl in Mexico City. They clash at first, but eventually bond, and when she''s kidnapped he''s consumed by fury and will stop at nothing to save her life.', 146, '/grCGLCcTHv9TChibzOwzUpykcjB.jpg', '/6c7j7MQCczzNVvcrNEiXbs8Kt2p.jpg', 'eDDh50B6kA4'),
    (9513, 'Jon and Garfield visit the United Kingdom, where a case of mistaken cat identity finds Garfield ruling over a castle. His reign is soon jeopardized by the nefarious Lord Dargis, who has designs on the estate.', 86, '/O2j1bwErQ6bbBVZM5Vxg3Tsoir.jpg', '/lrUeu7XMNaKJn6v8ps0DHqUE11L.jpg', '1u0rQ7J3oS4'),
    (9522, 'John and his buddy Jeremy are emotional criminals who know how to use a woman''s hopes and dreams for their own carnal gain. Their modus operandi: crashing weddings. Normally, they meet guests who want to toast the romantic day with a random hook-up. But when John meets Claire, he discovers what true love – and heartache – feels like.', 119, '/lFM3lk2zVzC1YFnKm0r6LbFPyRu.jpg', '/m1WSBzJ3uZ0WmxRBt1dpGUfNq7J.jpg', 'MBTY2PJD0yY'),
    (9532, 'After a teenager has a terrifying vision of him and his friends dying in a plane crash, he prevents the accident only to have Death hunt them down, one by one.', 98, '/1mXhlQMnlfvJ2frxTjZSQNnA9Vp.jpg', '/7isarjYDEKZ5t1CgcvbuqEUby8P.jpg', '9hvUxRGeBhA'),
    (9533, 'Former FBI Agent Will Graham, who was once almost killed by the savage Hannibal ''The Cannibal'' Lecter, now has no choice but to face him again, as it seems Lecter is the only one who can help Graham track down a new serial killer.', 124, '/ou9ZKA2cms02b7CdCdVqGkKu0O0.jpg', '/7c65xpnYlea6VITznLLRS9cTuwS.jpg', 'zLcI8OFyNUo'),
    (9535, 'Countless wiseguy films are spoofed in this film that centers on the neuroses and angst of a powerful Mafia racketeer who suffers from panic attacks. When Paul Vitti needs help dealing with his role in the "family," unlucky shrink Dr. Ben Sobel is given just days to resolve Vitti''s emotional crisis and turn him into a happy, well-adjusted gangster.', 103, '/gN8o7Ke1lUF2K8tzcLRb5bfEKbD.jpg', '/oas0DvvhhaMncvn805LjepxeoZh.jpg', 'ZJyv0AYmy4c'),
    (9538, 'A scientist trains a man with an advanced telepathic ability called ''scanning'' to stop a dangerous Scanner with extraordinary psychic powers from waging war against non-Scanners.', 103, '/VTqLdveNXxGsIAZL5I4RliTTt7.jpg', '/1qxQvGJXlkFRqfGallca9DXmynS.jpg', 'UveLSA7Hoj8'),
    (9539, 'A young woman’s quest for revenge against the people who kidnapped and tortured her as a child leads her and her best friend, also a victim of child abuse, on a terrifying journey into a living hell of depravity.', 99, '/6CHGHLfhmNBdwSRHhL0vWr6yA0d.jpg', '/fO1hwjlUqDe1ixO7eMfxTby62Ut.jpg', '1a9AgSIpobc'),
    (9542, 'On a stormy night, young Jim, who transports a luxury car from Chicago to California to deliver it to its owner, feeling tired and sleepy, picks up a mysterious hitchhiker, who has appeared out of nowhere, thinking that a good conversation will help him not to fall asleep. He will have enough time to deeply regret such an unmeditated decision.', 98, '/89giuiFssSVCUxkCP386v66cry8.jpg', '/frs1y0gf2En7REwpCcOeU9WbNMK.jpg', 'dTs-9jKh5_U'),
    (9543, 'A rogue prince reluctantly joins forces with a mysterious princess and together, they race against dark forces to safeguard an ancient dagger capable of releasing the Sands of Time – gift from the gods that can reverse time and allow its possessor to rule the world.', 116, '/siNGMLdOUNYLEGtlsnmQcpO2XZX.jpg', '/iP0capCU4w5nxCDl398CH7yR1r9.jpg', 'SOlc7fV9zL0'),
    (9552, 'When a mysterious entity possesses a young girl, her mother seeks the help of two Catholic priests to save her life.', 122, '/5x0CeVHJI8tcDx8tUUwYHQSNILq.jpg', '/xcjJ5khg2yzOa282mza39Lbrm7j.jpg', 'BU2eYAO31Cc'),
    (9567, 'Navy SEAL Lieutenant A.K. Waters and his elite squadron of tactical specialists are forced to choose between their duty and their humanity, between following orders by ignoring the conflict that surrounds them, or finding the courage to follow their conscience and protect a group of innocent refugees. When the democratic government of Nigeria collapses and the country is taken over by a ruthless military dictator, Waters, a fiercely loyal and hardened veteran is dispatched on a routine mission to retrieve a Doctors Without Borders physician.', 121, '/fUnSSQukwTwBSdCbufEE36petLq.jpg', '/cMkUwVCe6dpQnDqDwn0KwyBB2iv.jpg', 'DuTlpSfptO0'),
    (9574, 'Professor Phillip Brainard, an absent minded professor, works with his assistant Weebo, trying to create a substance that''s a new source of energy and that will save Medfield College where his sweetheart Sara is the president. He has missed his wedding twice, and on the afternoon of his third wedding, Professor Brainard creates flubber, which allows objects to fly through the air.', 94, '/bnKvk04icAyCO1KjqhsaEXBO9aJ.jpg', '/iaAWeeZaWU7c1UHfxMOhqxLXAUp.jpg', 'dl4r6JK6vgY'),
    (9594, 'Jean Claude Van Damme plays a dual role as Alex and Chad, twins separated at the death of their parents. Chad is raised by a family retainer in Paris, Alex becomes a petty crook in Hong Kong. Seeing a picture of Alex, Chad rejoins him and convinces him that his rival in Hong Kong is also the man who killed their parents. Alex is suspicious of Chad, especially when it comes to his girlfriend.', 110, '/tmzwvSqoMC37Tgqwj4mA2dHNSmw.jpg', '/iI0n28l5vn3K1GdXHVoA54kRemv.jpg', 'txTgynA3iFo'),
    (9598, 'Babe is a little pig who doesn''t quite know his place in the world. With a bunch of odd friends, like Ferdinand the duck who thinks he is a rooster and Fly the dog he calls mum, Babe realises that he has the makings to become the greatest sheep pig of all time, and Farmer Hoggett knows it. With the help of the sheep dogs, Babe learns that a pig can be anything that he wants to be.', 92, '/zKuQMtnbVTz9DsOnOJmlW71v4qH.jpg', '/agkZziO4ZPAsVfKUrJD68lys08P.jpg', 'tVxeoUtVF0o'),
    (9602, 'An African prince decides it’s time for him to find a princess... and his mission leads him and his most loyal friend to Queens, New York. In disguise as an impoverished immigrant, the pampered prince quickly finds himself a new job, new friends, new digs, new enemies and lots of trouble.', 117, '/djRAvxyvvN2yqlJKDbT3uy4vOBw.jpg', '/vsCIw7ARCKQVPT2K2hkkFVl7yo5.jpg', 'ZDme5Y5E-bI'),
    (9603, 'Shallow, rich and socially successful Cher is at the top of her Beverly Hills high school''s pecking scale. Seeing herself as a matchmaker, Cher first coaxes two teachers into dating each other. Emboldened by her success, she decides to give hopelessly klutzy new student Tai a makeover. When Tai becomes more popular than she is, Cher realizes that her disapproving ex-stepbrother was right about how misguided she was -- and falls for him.', 97, '/8AwVTcgpTnmeOs4TdTWqcFDXEsA.jpg', '/65d0MccsiRSPTVicregKQL8owoo.jpg', 'KeGqX4GVBZE'),
    (9615, 'In order to avoid a jail sentence, Sean Boswell heads to Tokyo to live with his military father. In a low-rent section of the city, Sean gets caught up in the underground world of drift racing', 104, '/46xqGOwHbh2TH2avWSw3SMXph4E.jpg', '/dMARcKLrv0T7kVJ4iQR3vqTTdtT.jpg', 'K6RWbKMSDcg'),
    (9631, 'The police try to arrest expert hostage negotiator Danny Roman, who insists he''s being framed for his partner''s murder in what he believes is an elaborate conspiracy. Thinking there''s evidence in the Internal Affairs offices that might clear him, he takes everyone in the office hostage and demands that another well-known negotiator be brought in to handle the situation and secretly investigate the conspiracy.', 140, '/dUMHEymATOGbs2K3E4dmNSVBgFQ.jpg', '/y4TbQOC9DCzZop9HwKuX73rKbYO.jpg', 'LJ1pS1W0XXg'),
    (9637, 'When the Mystery Inc. gang is invited to Spooky Island, a popular amusement park, they soon discover that the attractions aren''t the only things that are spooky. Strange things are happening, and it''s up to Scooby, Shaggy, Fred, Daphne, and Velma to uncover the truth behind the mysterious happenings.', 87, '/mTAiBJGg8mqEfnYHHbi37ZoRSZm.jpg', '/1RAxtBxslR4OZCZC1vxIRUxjR7a.jpg', 'lh6v23z6iek'),
    (9645, 'After discovering a passenger ship missing since 1962 floating adrift on the Bering Sea, salvagers claim the vessel as their own. Once they begin towing the ghost ship towards harbor, a series of bizarre occurrences happen and the group becomes trapped inside the ship, which they soon learn is inhabited by a demonic creature.', 91, '/qT9jhRnf67dmMNpX2FmNPMeuW57.jpg', '/r4yVwsLF2pJr4C50pWizn9fYNbF.jpg', '_RlzNBlMQpY'),
    (9654, 'Charlie Croker pulled off the crime of a lifetime. The one thing that he didn''t plan on was being double-crossed. Along with a drop-dead gorgeous safecracker, Croker and his team take off to re-steal the loot and end up in a pulse-pounding, pedal-to-the-metal chase that careens up, down, above and below the streets of Los Angeles.', 110, '/eSkjK4kctyrWpFhxl35GPvSs6tI.jpg', '/scub2eRSY0c3feyVIZhjZFXvgeV.jpg', 'mJgGUnV9i54'),
    (9655, 'Viola Hastings is in a real jam. Complications threaten her scheme to pose as her twin brother, Sebastian, and take his place at a new boarding school. She falls in love with her handsome roommate, Duke, who loves beautiful Olivia, who has fallen for Sebastian! As if that were not enough, Viola''s twin returns from London ahead of schedule but has no idea that his sister has already replaced him on campus.', 105, '/8exPgs8jLGh26BGSrAyHa9MeFyO.jpg', '/9ys3pySjmZiONZWAy8QhOxv5SDH.jpg', 'D4OhwrMidSU'),
    (9659, 'In the ravaged near-future, a savage motorcycle gang rules the road. Terrorizing innocent civilians while tearing up the streets, the ruthless gang laughs in the face of a police force hell-bent on stopping them.', 91, '/5LrI4GiCSrChgkdskVZiwv643Kg.jpg', '/mWQg2INejtX1PCWRAN4vseadA6H.jpg', 'E3F8IegOcjA'),
    (9679, 'Ex-car thief Randall Raines is forced out of retirement to save his brother Kip after a boost gone wrong. With the help of allies old and new, they race to meet the demands of notorious crime boss Raymond Calitri as the police are in hot pursuit.', 118, '/fToQDmkBtiXYGh9xfgAh3gpo6GZ.jpg', '/4GsvnaGqBGA78ccZusXvCH7zzun.jpg', 'cxCE9gDm1vo'),
    (9693, 'In 2027, in a chaotic world in which humans can no longer procreate, a former activist agrees to help transport a miraculously pregnant woman to a sanctuary at sea, where her child''s birth may help scientists save the future of humankind.', 109, '/k9IAS4TehZFcKi4HVByxZNPfqex.jpg', '/8Y1S9BtmTOh86irwFo7CJ01YPXF.jpg', '2VT2apoX90o'),
    (9705, 'Rogue agent Gabriel Shear is determined to get his mitts on $9 billion stashed in a secret Drug Enforcement Administration account. He wants the cash to fight terrorism, but lacks the computer skills necessary to hack into the government mainframe. Enter Stanley Jobson, a n''er-do-well encryption expert who can log into anything.', 99, '/mM6h4jMqC4q5IaFgBIGKQDLnRU.jpg', '/eSxvC0Qw0A9AfI355MF9dSItrfR.jpg', 'MTWGd-63sIM'),
    (9714, '9-year-old Alex Pruitt is home alone with the chicken pox. Turns out, due to a mix-up among nefarious spies, Alex was given a toy car concealing a top-secret microchip. Now Alex must fend off the spies as they try to break into his house to get it back.', 102, '/6uOadrCfle0n2LOOxHbgWEdnrm2.jpg', '/oHsiqHajO9v8YTuonvcMCkxtpSq.jpg', 'PP--dDh4axI'),
    (9725, 'Five years after the horrible bloodbath at Camp Crystal Lake, new counselors roam the area, not sensing the ominous lurking presence that proves that the grisly legend is real.', 86, '/92rGctBMTv4uaSlIBVnhz01kRWL.jpg', '/80emEEa0svrT0YJDZLgLUu85ttp.jpg', '3mNnJuOoI80'),
    (9730, 'After his revival in a hospital morgue, Jason fixes his vengeful attention on the Jarvis family and a group of hitherto carefree teenagers.', 91, '/1J7zudfR3VLPwAf9lK5YPfSu0n6.jpg', '/2bbEE2aLu47unsPJwS57UZW0YF4.jpg', '8zcPf9fuDPg'),
    (9731, 'Homicidal maniac Jason returns from the grave to cause more bloody mayhem. Young Tommy may have escaped from Crystal Lake, but he’s still haunted by the gruesome events that happened there. When gory murders start happening at the secluded halfway house for troubled teens where he now lives, it seems like his nightmarish nemesis, Jason, is back for more sadistic slaughters.', 92, '/ewnIs4aCuWnKQ13Eaj8f3ybrQc8.jpg', '/s24BnEjgnDFZrUHaL3IYhGTcBZ0.jpg', 'cZ5cMK-3Z_I'),
    (9732, 'The circle of life continues for Simba, now fully grown and in his rightful place as the king of Pride Rock. Simba and Nala have given birth to a daughter, Kiara who''s as rebellious as her father was. But Kiara drives her parents to distraction when she catches the eye of Kovu, the son of the evil lioness, Zira. Will Kovu steal Kiara''s heart?', 81, '/sWR1x6UCMCGN9xEf8RGhPS934X0.jpg', '/vyOFlV1afDHb9MMwJVyON4qXbvC.jpg', 'gxrwh6WNMLU'),
    (9737, 'Marcus Burnett is a henpecked family man. Mike Lowrey is a footloose and fancy free ladies'' man. Both Miami policemen, they have 72 hours to reclaim a consignment of drugs stolen from under their station''s nose. To complicate matters, in order to get the assistance of the sole witness to a murder, they have to pretend to be each other.', 119, '/x1ygBecKHfXX4M2kRhmFKWfWbJc.jpg', '/wOLTJxfv98miIQcn0oNXq9fIgXM.jpg', 'OLYENHi4IIc'),
    (9738, 'During a space voyage, four scientists are altered by cosmic rays: Reed Richards gains the ability to stretch his body; Sue Storm can become invisible; Johnny Storm controls fire; and Ben Grimm is turned into a super-strong … thing. Together, these "Fantastic Four" must now thwart the evil plans of Dr. Doom and save the world from certain destruction.', 125, '/4YMcYEFS8sFuW3soP1HVmgR3cSm.jpg', '/qq9ELjoyllBUMkGisZvcj0fCd43.jpg', 'QIx2jkXYu34'),
    (9739, 'In 1996, brash L.A. detective John Spartan and maniac killer Simon Phoenix are both sentenced to decades in a cryogenic prison as punishment for a rescue mission gone wrong. When Phoenix escapes 36 years later to wreak havoc on the future, Spartan is awakened to capture his nemesis the old-fashioned way.', 115, '/dq6AmlVFo92PRuoLCcIyFdoRuxf.jpg', '/4pl165EUdvveHCr4J4YcHVA1MnD.jpg', 'JdXYTDqeXe4'),
    (9740, 'After having successfully eluded the authorities for years, Hannibal peacefully lives in Italy in disguise as an art scholar. Trouble strikes again when he''s discovered leaving a deserving few dead in the process. He returns to America to make contact with now disgraced Agent Clarice Starling, who is suffering the wrath of a malicious FBI rival as well as the media.', 131, '/v5wAZwRqpGWmyAaaJ8BBHYuNXnj.jpg', '/3Nb9AQaq3elLNCUBxG8VprmqfhZ.jpg', '20rd9VQ1Wx0'),
    (9741, 'An ordinary man makes an extraordinary discovery when a train accident leaves his fellow passengers dead — and him unscathed. The answer to this mystery could lie with the mysterious Elijah Price, a man who suffers from a disease that renders his bones as fragile as glass.', 106, '/mLuehrGLiK5zFCyRmDDOH6gbfPf.jpg', '/2Gq4teAIkVVv0kc6JsfU66C3VOJ.jpg', 'faVXsGSC1AY'),
    (9762, 'Delinquent Tyler Gage receives the opportunity of a lifetime after vandalizing a performing arts school, gaining him the chance to earn a scholarship and dance with up-and-coming dancer Nora.', 104, '/fmw52kXk2kN8AQil7tgOD41gt4Q.jpg', '/k3AGi4UD8Ql2dKosXh6FrBSKm0s.jpg', '2_g--dceQoY'),
    (9778, 'Although already in relationships, two strangers realize they have genuine chemistry after a chance encounter – but part company soon after. Years later, they each yearn to reunite, despite being destined for the altar. But to give true love a chance, they have to find one another again.', 90, '/4jS66Qmq2Ru5S2YzHVknGd4xJyT.jpg', '/sBecqcXgrLRiwufYr6apGnYA70k.jpg', 'xgwn8UqU2aY'),
    (9792, 'Based on Wes Craven''s 1977 suspenseful cult classic, The Hills Have Eyes is the story of a family road trip that goes terrifyingly awry when the travelers become stranded in a government atomic zone. Miles from nowhere, the Carter family soon realizes the seemingly uninhabited wasteland is actually the breeding ground of a blood-thirsty mutant family...and they are the prey.', 107, '/2eJL1Ccr1FN3dm9OSDwyd8uaX1b.jpg', '/vrFI0I3M8ROZduj9XbFDoQKZyao.jpg', 'weZ6GEXeYl0'),
    (9796, 'A group of young backpackers'' vacation turns sour when a bus accident leaves them marooned in a remote Brazilian rural area that holds an ominous secret.', 93, '/v3mbkqUSLJlqdqecviwIWv52BCU.jpg', '/aAhl5eoAV2At26QQxnFZeUsVuvy.jpg', 'gRu91mkfHh4'),
    (9798, 'When the videotape of the murder of a congressman unknowingly ends up in the hands of labor lawyer and dedicated family man Robert Clayton Dean, he is framed for the murder. With the help of the mysterious Brill, Dean attempts to throw the NSA off his trail and prove his innocence.', 132, '/xWGLT3AHPcqCrj1G11pwEO5nyNv.jpg', '/lPLTLCBn39Wiy1RPQLB9xOKyF2v.jpg', 'a3mrRv-1khI'),
    (9799, 'Dominic Toretto is a Los Angeles street racer suspected of masterminding a series of big-rig hijackings. When undercover cop Brian O''Conner infiltrates Toretto''s iconoclastic crew, he falls for Toretto''s sister and must choose a side: the gang or the LAPD.', 106, '/gqY0ITBgT7A82poL9jv851qdnIb.jpg', '/jY9ef5nqY4xIIMu3yzW3qamUCoi.jpg', 'iIU1xlDbbQk'),
    (9800, 'Two lawyers join forces to sue a prestigious law firm for AIDS discrimination. As their unlikely friendship develops, their courage overcomes the prejudice and corruption of their powerful adversaries.', 126, '/tFe5Yoo5zT495okA49bq1vPPkiV.jpg', '/nWO4sGqH950N2fij8X0Pwumqe9k.jpg', 'qf49UApA88s'),
    (9802, 'When vengeful General Francis X. Hummel seizes control of Alcatraz Island and threatens to launch missiles loaded with deadly chemical weapons into San Francisco, only a young FBI chemical weapons expert and notorious Federal prisoner have the skills to penetrate the impregnable island fortress and take him down.', 137, '/eBcoxveWzzXQrCrwWMGAROcqgpP.jpg', '/qDVdTL1KqGmGLGsy7UPA3vksku7.jpg', 'a3qcNyjj9ZQ'),
    (9804, 'In a futuristic world where the polar ice caps have melted and made Earth a liquid planet, a beautiful barmaid rescues a mutant seafarer from a floating island prison. They escape, along with her young charge, Enola, and sail off aboard his ship. But the trio soon becomes the target of a menacing pirate who covets the map to ''Dryland''—which is tattooed on Enola''s back.', 135, '/X4UyUO5jgzs3c5YafnmYKLKKYw.jpg', '/yaIu82UiD9QZEkKCGrAd8VAmc0V.jpg', 'r4LLyBCz9tw'),
    (9806, 'Bob Parr has given up his superhero days to log in time as an insurance adjuster and raise his three children with his formerly heroic wife in suburbia. But when he receives a mysterious assignment, it''s time to get back into costume.', 115, '/2LqaLgk4Z226KkgPJuiOQ58wvrm.jpg', '/lxwzY9vNwjDgxWKt3zZ6zcU6rEJ.jpg', 'sJCjKQQOqT0'),
    (9820, 'Hallie Parker and Annie James are identical twins who were separated at a young age due to their parents'' divorce. Unbeknownst to their parents, the girls are sent to the same summer camp, where they meet, discover the truth about their relationship, and come up with a plan to switch places in an effort to reunite their mother and father.', 128, '/p4dGmi8u9W0HHyVXcgWPoiFfKTF.jpg', '/hz6NQHZG9vAdSpwG1qeTCKHupO3.jpg', 'PMAhVpgzmRU'),
    (9836, 'Into the world of the Emperor Penguins, who find their soul mates through song, a penguin is born who cannot sing. But he can tap dance something fierce!', 108, '/zP4CK9O70P8GDilfTkPm4lrmaks.jpg', '/pxsR974ez8bQx0GDixxiKr7pk1o.jpg', 'ThMZMdH3gVA'),
    (9837, 'The strong bond between two Royal Egyptian brothers is challenged when their chosen responsibilities set them at odds, with extraordinary consequences.', 99, '/2xUjYwL6Ol7TLJPPKs7sYW5PWLX.jpg', '/565DYYXgdRYMiETLi2EDx4p7s92.jpg', 'zmBDY-fSlIs'),
    (9846, 'When his longtime partner on the force is killed, reckless U.S. Secret Service agent Richard Chance vows revenge, setting out to nab dangerous counterfeit artist Eric Masters.', 116, '/2iW3pSihBIhXjnBQmUJ0mAiZbB5.jpg', '/1asVOmgViSEn4yi0EylEdtlL5H9.jpg', 'BQGB-wufbQU'),
    (9870, 'When actress Sarah Marshall dumps aspiring musician Peter Bretter for rock star Aldous Snow, Peter''s world comes crashing down. His best friend Brian suggests that Peter should get away from everything and to fly off to Hawaii to escape all his problems. After arriving in Hawaii and meeting the beautiful receptionist Rachel Jansen, Peter is shocked to see not only Aldous in Hawaii, but also Sarah.', 111, '/d4elOzyhNWVlxpG7BwigrumkFTe.jpg', '/xe0kqei6uS5qzcSEb2bmokld0YN.jpg', 'GSwA6QQW8P4'),
    (9874, 'A tough-on-crime street cop must protect the only surviving witness to a strange murderous cult with far reaching plans.', 87, '/rCN9c1NfxjfgMkTPFATOzUkNEyg.jpg', '/zPDpHMdbbE4O0TxVkMcgD6j2ImR.jpg', 'juL0qVu8PGY'),
    (9880, 'A socially awkward but very bright 15-year-old girl being raised by a single mom discovers that she is the princess of a small European country because of the recent death of her long-absent father, who, unknown to her, was the crown prince of Genovia. She must make a choice between continuing the life of a San Francisco teen or stepping up to the throne.', 115, '/7axhsbEzFan6HQQ1aMOy7w3CFRx.jpg', '/ktPixrzD9Rbet7Co4uUWxyR9191.jpg', '2CkcwPi20ms'),
    (9885, 'Three backpackers stranded in the Australian outback are plunged inside a hellish nightmare of insufferable torture by a sadistic psychopathic local.', 99, '/545PYpfCeDwVgdgydHCQqXFr168.jpg', '/315xehapBIRk5XCHbcTxjgUmvdx.jpg', 'eMaEkGjm4dM'),
    (9902, 'Chris crashes into a carload of other young people, and the group of stranded motorists is soon lost in the woods of West Virginia, where they''re hunted by three cannibalistic mountain men who are grossly disfigured by generations of inbreeding.', 84, '/12G5V0dTmljnv7RFMT144dJ2chh.jpg', '/6FYkeJOKKEdrUVg9g5sSye802RH.jpg', '_WqHuwZcENM'),
    (9919, 'It''s the battle of wills, as Andie needs to prove she can dump a guy in 10 days, whereas Ben needs to prove he can win a girl in 10 days. Now, the clock is ticking—and the wildly entertaining comedy smash is off and running in this irresistible tale of sex, lies and outrageous romantic fireworks!', 116, '/2dlftyPz7mTYbrsPvTogyFmYd7d.jpg', '/cdYj6HFpKp5NTmLiHHbNEGSmDT4.jpg', '2ZMGk_Ml1fc'),
    (9928, 'Rodney Copperbottom is a young robot inventor who dreams of making the world a better place, until the evil Ratchet takes over Bigweld Industries. Now, Rodney''s dreams – and those of his friends – are in danger of becoming obsolete.', 90, '/fnKCh67l2DDG9NxxIlk9IpsXQ99.jpg', '/8p4gCdDT55PMY3UMDvo6ybzMrai.jpg', 'zyLI71Z0RF4'),
    (9964, 'A team from the intergalactic fast food chain Crumb''s Crunchy Delights descends on Earth, planning to make human flesh the newest taste sensation. After they wipe out the New Zealand town Kaihoro, the country’s Astro-Investigation and Defense Service (AIaDS) is called in to deal with the problem. Things are complicated due to Giles, an aid worker who comes to Kaihoro the same day to collect change from the residents. He is captured by the aliens, and AIaDS stages a rescue mission that quickly becomes an all-out assault on the aliens’ headquarters.', 91, '/msttMX3undIiaeJLZbMRq94v1bw.jpg', '/HUnVuk7xCe9bZE5YZcVwMV8xea.jpg', '7IHwKJOZZ6U'),
    (9982, 'When the sky really is falling and sanity has flown the coop, who will rise to save the day? Together with his hysterical band of misfit friends, Chicken Little must hatch a plan to save the planet from alien invasion and prove that the world''s biggest hero is a little chicken.', 81, '/87FpA4b90eTaw3U6zmCNikoPLir.jpg', '/h5Bwxe6dTVFtAFkybkd1EAB4yUW.jpg', 'PPuk2JQgMkU'),
    (9992, 'Ten-year-old Arthur, in a bid to save his grandfather''s house from being demolished, goes looking for some much-fabled hidden treasure in the land of the Minimoys, tiny people living in harmony with nature.', 94, '/gH27K0S7BiZCsNMxzOQTacG9IZp.jpg', '/zwV8u4kq6ClZ3IDylLGF3DprKDv.jpg', 'xIzKgO3C6Z8'),
    (10009, 'When an impulsive boy named Kenai is magically transformed into a bear, he must literally walk in another''s footsteps until he learns some valuable life lessons. His courageous and often zany journey introduces him to a forest full of wildlife, including the lovable bear cub Koda, hilarious moose Rutt and Tuke, woolly mammoths and rambunctious rams.', 85, '/otptPbEY0vBostmo95xwiiumMJm.jpg', '/sZhY0BAsN1bMAPLIqMRqG1fqb3A.jpg', '_w897MMkjPA'),
    (10020, 'Follow the adventures of Belle, a bright young woman who finds herself in the castle of a prince who''s been turned into a mysterious beast. With the help of the castle''s enchanted staff, Belle soon learns the most important lesson of all -- that true beauty comes from within.', 84, '/hUJ0UvQ5tgE2Z9WpfuduVSdiCiU.jpg', '/fW4ZCoEZRBqLAJGFQ2g5AdAfPQR.jpg', 'UUVpyeS_fVw'),
    (10022, 'Navy SEAL Shane Wolfe is handed a new assignment: Protect the five Plummer kids from enemies of their recently deceased father -- a government scientist whose top-secret experiment remains hidden in the kids'' house.', 95, '/ayVLPibrtazh7U5FliWRLDMmG3d.jpg', '/p0HdiQZVYylWy5JG8iuwzT1Ssdl.jpg', 'pknw1wh-2-U'),
    (10027, 'Raised as a slave, Danny is used to fighting for his survival. In fact, his "master," Bart, thinks of him as a pet and goes as far as leashing him with a collar so they can make money in fight clubs, where Danny is the main contender. When Bart''s crew is in a car accident, Danny escapes and meets a blind, kindhearted piano tuner who takes him in and uses music to free the fighter''s long-buried heart.', 103, '/gghvmS3UxtOw1UHIgYjpeZNxHil.jpg', '/leukkAoRu9rsa3s8oaLm8C10EWw.jpg', 'AoBkHA7-I84'),
    (10054, 'Carmen and Juni think their parents are boring. Little do they know that in their day, Gregorio and Ingrid Cortez were the top secret agents from their respective countries. They gave up that life to raise their children. Now, the disappearances of several of their old colleagues forces the Cortez'' return from retirement. What they didn''t count on was Carmen and Juni joining the "family business."', 88, '/j3rUkHIAAoKr6jU30q3Db4fcIF9.jpg', '/aFHAnOI1sjHktgEX5lykeSiUZ1C.jpg', 'GE5aHKJp6HI'),
    (10065, 'George Lutz, his wife Kathy, and their three children have just moved into a beautiful, and improbably cheap, Dutch colonial mansion nestled in the sleepy coastal town of Amityville, Long Island. However, their dream home is concealing a horrific past and soon each member of the Lutz family is plagued with increasingly strange and violent visions and impulses.', 90, '/4D246dpe7yy2GvHI2IbpeqkUXry.jpg', '/fxgZg5oV3PKzk1xQPF673KzzLFh.jpg', 'j_Lm2PXb3tk'),
    (10066, 'A group of unwitting teens are stranded near a strange wax museum and soon must fight to survive and keep from becoming the next exhibit.', 113, '/aCLSgw1DaqkRvosYc3YUttBTtpT.jpg', '/2J7re6BvXXxLFXCYZpTUmRKkTHn.jpg', 'ezUtqfB24Cg'),
    (10068, 'An erotic story about a woman, the assistant of an art gallery, who gets involved in an impersonal affair with a man. She barely knows about his life, only about the sex games they play, so the relationship begins to get complicated.', 117, '/aE1iunrgO8UHfoXKJcjCy4Ih17n.jpg', '/cf7jOkeY8tqSnVRzAbdlUKQynhe.jpg', 'bRIsOxLzLLM'),
    (10096, 'After total humiliation at her thirteenth birthday party, Jenna Rink wants to just hide until she''s thirty. Thanks to some magic wishing dust, Jenna''s prayer has been answered. With a knockout body, a fabulous wardrobe, an athlete boyfriend, a dream job, and superstar friends, this can''t be a better life. But soon Jenna realizes that adult life isn’t as easy as she hoped for.', 98, '/iNZdSIfhSCMtRILDNyhLn8UKeSG.jpg', '/ld7UTOGzZSxIMbuYsb6eQ6QdN4h.jpg', '_pmFp2W65Fs'),
    (10098, 'A tramp cares for a boy after he''s abandoned as a newborn by his mother. Later the mother has a change of heart and aches to be reunited with her son.', 68, '/drgMcyTsySQBnUPGaBThCHGdlWT.jpg', '/yJvv7kDmeWT18jUSW2ZugZmYg0i.jpg', 'O5WXokyub-4'),
    (10110, 'Jamie Graham, a privileged English boy, is living in Shanghai when the Japanese invade and force all foreigners into prison camps. Jamie is captured with an American sailor, who looks out for him while they are in the camp together. Even though he is separated from his parents and in a hostile environment, Jamie maintains his dignity and youthful spirit, providing a beacon of hope for the others held captive with him.', 153, '/gEaCzjwHoPgyQFcwHql7o5YLHAU.jpg', '/xt7boIC763DdceVQIGJdnmKlDVu.jpg', 'NsU11wxFMbY'),
    (10112, 'When Madame Adelaide Bonfamille leaves her fortune to Duchess and her children—Bonfamille’s beloved family of cats—the butler plots to steal the money and kidnaps the legatees, leaving them out on a country road. All seems lost until the wily Thomas O’Malley Cat and his jazz-playing alley cats come to the aristocats’ rescue.', 78, '/aOWs5XMJEABN6SKCTJBCoeD1kCA.jpg', '/rnMwOM8gMqo6Gf6XXMpaJEayUwk.jpg', 'h6M_OJ41NfA'),
    (10135, 'The Double Deuce is the meanest, loudest and rowdiest bar south of the Mason-Dixon Line, and Dalton has been hired to clean it up. He might not look like much, but the Ph.D.-educated bouncer proves he''s more than capable – busting the heads of troublemakers and turning the roadhouse into a jumping hot spot. But Dalton''s romance with the gorgeous Dr. Clay puts him on the bad side of cutthroat local big shot Brad Wesley.', 114, '/n7Ra0BRYQVn47kiqOMyS8vdY0QS.jpg', '/cUrFALlZP6Zh5SYRPSUnOYXfMhr.jpg', 'xbN9m-1vIZc'),
    (10137, 'When the Littles adopt Stuart, the mouse, George is initially unwelcoming to his new brother, and the family cat, Snowbell, is even less enthusiastic. Stuart resolves to face these difficulties with as much pluck and courage as he can muster.', 84, '/362lcwTJlNyAhitTlp2UraECISR.jpg', '/dECKGAenue36W50HYhd3Jh1OJs.jpg', 'Wlo-sYrADlw'),
    (10138, 'With the world now aware of his dual life as the armored superhero Iron Man, billionaire inventor Tony Stark faces pressure from the government, the press and the public to share his technology with the military. Unwilling to let go of his invention, Stark, with Pepper Potts and James ''Rhodey'' Rhodes at his side, must forge new alliances – and confront powerful enemies.', 124, '/6WBeq4fCfn7AN0o21W9qNcRF2l9.jpg', '/7lmBufEG7P7Y1HClYK3gCxYrkgS.jpg', '5fUQkLdJ2kE'),
    (10140, 'This time around Edmund and Lucy Pevensie, along with their pesky cousin Eustace Scrubb find themselves swallowed into a painting and on to a fantastic Narnian ship headed for the very edges of the world.', 113, '/pP27zlm9yeKrCeDZLFLP2HKELot.jpg', '/oc3be3waruLd0PB9h4bomN7Le3v.jpg', 'LuGUVkO0cRM'),
    (10144, 'This colorful adventure tells the story of an impetuous mermaid princess named Ariel who falls in love with the very human Prince Eric and puts everything on the line for the chance to be with him. Memorable songs and characters -- including the villainous sea witch Ursula.', 83, '/plcZXvI310FkbwIptvd6rqk63LP.jpg', '/qGZXYHvWR1TYOU9raCaEABrj9m7.jpg', 'ZGZX5-PAwR8'),
    (10147, 'You''d better watch out - Willie T. Soke is coming to town, and he doesn''t care if you''ve been naughty or nice. Willie''s favorite holiday tradition is to fill his sacks with loot lifted from shopping malls across the country. But this year his plot gets derailed by a wisecracking store detective, a sexy bartender, and a kid who''s convinced Willie is the real Santa Claus.', 92, '/rfClLIyeHqpMofmrPY8DaLe4z9x.jpg', '/tbmNzJIc7R1MuEweCOThpTzglyx.jpg', 'cvXyEiIoH2c'),
    (10184, 'Remember that really cute girl/guy who said they''d call – and didn''t? Maybe they lost your number. Maybe they''re in the hospital. Maybe they''re awed by your looks, brains or success. Or maybe... They''re just not that into you.', 129, '/jip2ap24Y6JxEgzVRyNqyYssnyR.jpg', '/jZkkch6yrP1tVVfEU2uqwej9rBM.jpg', '2c3rxHgfRTo'),
    (10185, 'A photographer''s obsessive pursuit of dark subject matter leads him into the path of a serial killer who stalks late night commuters, ultimately butchering them in the most gruesome ways.', 103, '/x5YbfyUA8huK0shr008xwzNVJ5Y.jpg', '/tcV7eCdGFN3RzB2ByWRrH5Xf7cU.jpg', 'wtUiRfMy_uI'),
    (10189, 'A stoner and his dealer are forced to go on the run from the police after the pothead witnesses a cop commit a murder.', 112, '/6E50WjeOYjDZg9HXgPjYdGtY2jG.jpg', '/aO6Z7ErkEoahGFKYdEs4k4ilWFe.jpg', '2T2o2WPNMXU'),
    (10191, 'As the son of a Viking leader on the cusp of manhood, shy Hiccup Horrendous Haddock III faces a rite of passage: he must kill a dragon to prove his warrior mettle. But after downing a feared dragon, he realizes that he no longer wants to destroy it, and instead befriends the beast – which he names Toothless – much to the chagrin of his warrior father.', 98, '/ygGmAO60t8GyqUo9xYeYxSZAR3b.jpg', '/59vDC1BuEQvti24OMr0ZvtAK6R1.jpg', 'KZtbJ_I9IFM'),
    (10192, 'A midlife-crisis burdened Shrek, longing for the days of when he felt like a real ogre, makes a pact with magic deal-maker Rumpelstiltskin. But when he''s duped and sent to a twisted version of Far Far Away—where Rumpelstiltskin is king, ogres are hunted, and he and Fiona have never met—he sets out to restore his world and reclaim his true love.', 93, '/6HrfPZtKcGmX2tUWW3cnciZTaSD.jpg', '/uzzTystB8lL0mRDII5Sfs5HxgkI.jpg', 'WV8bbMxPBdc'),
    (10193, 'Woody, Buzz, and the rest of Andy''s toys haven''t been played with in years. With Andy about to go to college, the gang find themselves accidentally left at a nefarious day care center. The toys must band together to escape and return home to Andy.', 103, '/AbbXspMOwdvwWZgVN0nabZq03Ec.jpg', '/wE5JGzujfvDPMIfFjJyrhXFjZLc.jpg', '6c3K7LhA9Yc'),
    (10195, 'Against his father Odin''s will, The Mighty Thor - a powerful but arrogant warrior god - recklessly reignites an ancient war. Thor is cast down to Earth and forced to live among humans as punishment. Once here, Thor learns what it takes to be a true hero when the most dangerous villain of his world sends the darkest forces of Asgard to invade Earth.', 115, '/prSfAi1xGrhLQNxVSUFh61xQ4Qy.jpg', '/cDJ61O1STtbWNBwefuqVrRe3d7l.jpg', 'uHBnrJowBZE'),
    (10196, 'A century has passed since the Fire Nation declared war on the other three nations of air, water, and earth in its attempt for global domination. Aang, the long-lost Avatar, is found by Water Tribe siblings Katara and Sokka and must learn to master water, earth, and fire bending to defeat the Fire Nation and restore balance to the world.', 103, '/zgwRTYWEEPivTwjB9S03HtmMcbM.jpg', '/gU5cR9LKtDD8YvzE7T7GvmzCEAA.jpg', 'WdoiHMCVqMQ'),
    (10198, 'A waitress, desperate to fulfill her dreams as a restaurant owner, is set on a journey to turn a frog prince back into a human being, but she has to face the same problem after she kisses him.', 98, '/yprv5PbnEksoVj2v6XEnDBg9joR.jpg', '/y5tad0a4yRbxYgOHGllEIEeCCKt.jpg', 'uQBy6jqbmlU'),
    (10200, 'A representative of an alien race that went through drastic evolution to survive its own climate change, Klaatu comes to Earth to assess whether humanity can prevent the environmental damage they have inflicted on their own planet. When barred from speaking to the United Nations, he decides humankind shall be exterminated so the planet can survive.', 104, '/vBgFSYmG5tb7GsZ3tHR0WNaWaxA.jpg', '/nIxFtd6gcmGGvFxyb1z3mt46CrN.jpg', '7eCVD3WTEtU'),
    (10201, 'Carl Allen, a guy whose life is going nowhere, signs up for a self-help program based on one simple covenant: say yes to everything…and anything.', 104, '/8Vk2nQF1kY34x53YnWd5zDaTht.jpg', '/l9kUuYVqiZV1r6d4nKUKcQvtLR3.jpg', 'fifBy4N3-_k'),
    (10202, 'Skeeter Bronson is a down-on-his-luck guy who''s always telling bedtime stories to his niece and nephew. But his life is turned upside down when the fantastical stories he makes up for entertainment inexplicably turn into reality. Can a bewildered Skeeter manage his own unruly fantasies now that the outrageous characters and situations from his mind have morphed into actual people and events?', 99, '/rSOnWm8ahvgThYp8TKGRUTcvsyw.jpg', '/gu9SE1fuuc5cA8w8om21lc4at3h.jpg', 'e-6N1NZrQAQ'),
    (10204, 'A bet pits a British inventor, a Chinese thief and a French artist on a worldwide adventure that they can circle the globe in 80 days.', 120, '/bBiMw6Jtg8tSTcEq8jFV7qk9TRW.jpg', '/lpZPrfmWrcSkYQx8JHT9APj2uPB.jpg', 'tFe7H-7YWD0'),
    (10225, 'Tommy Jarvis, tormented by the fear that maybe Jason isn''t really dead, unwittingly resurrects the mass murderer for another bloody rampage.', 86, '/6vdUpHvkspQonXBdWcLWW5ciEPJ.jpg', '/93tvkTtV6tQQiYhxhij9tuODNOq.jpg', '4ETsQHtUqcs'),
    (10229, 'When the popular, restless Landon Carter is forced to participate in the school drama production, he falls in love with Jamie Sullivan, the daughter of the town''s minister. Jamie has a "to-do" list for her life, as well as a very big secret she must keep from Landon.', 102, '/8lUYMvWdHA0Q0k5F76RQCeCBUkA.jpg', '/uRdJx2p950EobLYuf7Oz39Wk7jd.jpg', 'Kq02sBe5xko'),
    (10234, 'Two psychotic young men take a mother, father, and son hostage in their vacation cabin and force them to play sadistic "games" with one another for their own amusement.', 109, '/48uCNgdyYIoN4ayWjTpLaqSDcWI.jpg', '/79SBe1bU30Dy6QPwJ2KQ3LTr1lr.jpg', 'bH2HS6uWIhQ'),
    (10246, 'In 1954 Florida, a group of high school boys head to a strip club in the Everglades in an attempt to lose their collective virginity. When the club''s owner and his sheriff brother swindle them out of their money and embarrass them, the boys plan revenge.', 94, '/AqCOt1cWfKqCepxK7LIdT812idH.jpg', '/97f4GFF2Vv6v40Ee5S00nuvAr4i.jpg', 'KpzxvPigAr8'),
    (10315, 'The Fantastic Mr. Fox, bored with his current life, plans a heist against the three local farmers. The farmers, tired of sharing their chickens with the sly fox, seek revenge against him and his family.', 87, '/bOVr292mwn3jxr1e0NmUPM1rcjo.jpg', '/xRxSLhhjPG2D8l0BXi0KdN4IvPt.jpg', 'VuIaCvIFWIA'),
    (10330, 'Mother and daughter bicker over everything -- what Anna wears, whom she likes and what she wants to do when she''s older. In turn, Anna detests Tess''s fiancé. When a magical fortune cookie switches their personalities, they each get a peek at how the other person feels, thinks and lives.', 97, '/y6kn3tUb4qrNZvV4TDIIjskZ9eV.jpg', '/cTGeY2fdf0eLubvEFZAGcr2PfLZ.jpg', 'r8caetzt02g'),
    (10340, 'Lady, a golden cocker spaniel, meets up with a mongrel dog who calls himself the Tramp. He is obviously from the wrong side of town, but happenings at Lady''s home make her decide to travel with him for a while.', 76, '/340NcWz9SQXWQyf4oicMxjbrLOb.jpg', '/yGgEg4yimYQJLZrZg3Qhogp2raQ.jpg', 'SAoLpLXvGN0'),
    (10358, 'Lifelong platonic friends Zack and Miri look to solve their respective cash-flow problems by making an adult film together. As the cameras roll, however, the duo begin to sense that they may have more feelings for each other than they previously thought.', 102, '/ipePhKf87FixwfAVJ8MMWK53caI.jpg', '/5kPMUjtfDemu8MvKoa37cYoo5iJ.jpg', 'u2Y3cCOkz8o'),
    (10386, 'In the small town of Rockwell, Maine in October 1957, a giant metal machine befriends a nine-year-old boy and ultimately finds its humanity by unselfishly saving people from their own fears and prejudices.', 86, '/k1Cv5CHJvqGWK1xJDUJz8DojFEy.jpg', '/gZ78dyRH9hXeH94ASjuvD9Vw4b5.jpg', '2izFEWmzPdk'),
    (10439, 'After 300 years of slumber, three sister witches are accidentally resurrected in Salem on Halloween night, and it is up to three kids and their newfound feline friend to put an end to the witches'' reign of terror once and for all.', 96, '/by4D4Q9NlUjFSEUA1yrxq6ksXmk.jpg', '/ncr6KR7bBF8cps6yZKiTAwClpn1.jpg', 'OFm_2RyxXjQ'),
    (10483, 'Terminal Island, New York: 2020. Overcrowding in the US penal system has reached a breaking point. Prisons have been turned over to a monolithic Weyland Corporation, which sees jails full of thugs as an opportunity for televised sport. Adrenalized inmates, a global audience hungry for violence and a spectacular, enclosed arena come together to form the ''Death Race'', the biggest, most brutal event.', 105, '/8ASwIBJSyUXUdlPLVjExnOghBar.jpg', '/5mbFEJStH59cNFcF7VkRgsSxMqK.jpg', 'C8bxcJZrus0'),
    (10494, 'Rising pop star Mima Kirigoe quits singing to pursue a career as an actress. After she takes up a role on a popular detective show, her handlers and collaborators begin turning up murdered. Harboring feelings of guilt and haunted by visions of her former self, Mima''s reality and fantasy meld into a frenzied paranoia.', 82, '/6WTiOCfDPP8XV4jqfloiVWf7KHq.jpg', '/mHG7dpLb0ZScSY3LpP443IHRmjy.jpg', 'RrWausp8zDQ'),
    (10501, 'Stowing away after a failed con, a pair of swindlers end up on El Dorado, the fabled "city of gold", where they quickly get in over their heads when they are mistaken as gods by the inhabitants.', 90, '/tQuqhUBACMcGqCvliHxpJreBfXC.jpg', '/ciM5RFsBoWEj0tbwJy42Hr76iRd.jpg', 'JcOfJwN0bdY'),
    (10515, 'A young boy and a girl with a magic crystal must race against pirates and foreign agents in a search for a legendary floating castle.', 125, '/41XxSsJc5OrulP0m7TrrUeO2hoz.jpg', '/3cyjYtLWCBE1uvWINHFsFnE8LUK.jpg', '6s_wR3uuWec'),
    (10521, 'Two best friends become rivals when their respective weddings are accidentally booked for the same day.', 89, '/eyXT8tmUoyHrg7YX1UVjmecHCWP.jpg', '/bDYeMDIKeetY6J3ZM6POwnf1xc7.jpg', 'KBDE4uznmIw'),
    (10527, 'Alex, Marty, and other zoo animals find a way to escape from Madagascar when the penguins reassemble a wrecked airplane. The precariously repaired craft stays airborne just long enough to make it to the African continent. There the New Yorkers encounter members of their own species for the first time. Africa proves to be a wild place, but Alex and company wonder if it is better than their Central Park home.', 89, '/agRbLOHgN46TQO4YdKR462iR7To.jpg', '/3yXLkSTrVhG66MIAr3X6C4gjccw.jpg', 'hLVjIhPYq7s'),
    (10528, 'Eccentric consulting detective Sherlock Holmes and Doctor John Watson battle to bring down a new nemesis and unravel a deadly plot that could destroy England.', 129, '/momkKuWburNTqKBF6ez7rvhYVhE.jpg', '/85g84VtSf9tu1A9JqqruXEHspb7.jpg', 'zBQfbc1t_I8'),
    (10530, 'Pocahontas, daughter of a Native American tribe chief, falls in love with an English soldier as colonists invade 17th century Virginia.', 81, '/kZ1ft0QZ4e3zDUPMBftEkwI9ftd.jpg', '/fDZ2DCKW2D7J0ABNr9EICdD2H1s.jpg', 'mf0JmiI7NXY'),
    (10545, 'Isolated in the bell tower of Notre Dame, Quasimodo longs to experience the world beyond the cathedral walls, despite the wishes of his stern guardian, the Judge of Paris Claude Frollo. His first venture into the city leads him to Esmeralda, a fearless Romani woman whose defiance of Frollo''s tyranny draws her—and Quasimodo—into his dangerous obsession.', 91, '/dmMBtXuFzZzLYgeQXkOkg98w2Ak.jpg', '/k4HIk81b03lLeNo7I0dHxD3VPKD.jpg', 'HUGraD-rxjk'),
    (10555, 'Oscar is a small fish whose big aspirations often get him into trouble. Meanwhile, Lenny is a great white shark with a surprising secret that no sea creature would guess: He''s a vegetarian. When a lie turns Oscar into an improbable hero and Lenny becomes an outcast, the two form an unlikely friendship.', 90, '/r08DpyPyhXcJTfNZAICNGMzcQ8l.jpg', '/7ZmZxar3bYORcl0TPA4oceyxcaE.jpg', 'mp2SbaK8dDg'),
    (10567, 'An orphaned dinosaur raised by lemurs joins an arduous trek to a sancturary after a meteorite shower destroys his family home.', 82, '/rSje3FS7ycJSglowlngjsvDt7vO.jpg', '/laeEtakR2pLKu3CeRwB2lU5Y53X.jpg', 'yrhGIq5o5Yc'),
    (10585, 'After being shot in a toy store, a serial killer transfers his soul into a Good Guy doll. A mother then gifts it to her six-year-old son Andy, which unleashes terror upon the city.', 87, '/wvpgvcWNkF2HLuTEMIM7K83MvZ.jpg', '/edghRD7vw1XgWEpMLpGt1VSGB5w.jpg', 'sjiyV8mtXiU'),
    (10591, 'Exceptionally ambitious high schooler Matthew has aspirations for a career in politics when he falls in love with his gorgeous 19-year-old neighbor, Danielle. But Matthew''s bright future is jeopardized when he finds Danielle was once a porn star. As Danielle''s past catches up with her, Matthew''s love for her forces him to re-evaluate his goals.', 110, '/5mVyFHSY2rSsNgD4NfEwV82HigU.jpg', '/qvcOovScPoRalRxDy50rYSYFree.jpg', '0rD3Qkh-238'),
    (10601, 'In stifling Edwardian London, Wendy Darling mesmerizes her brothers every night with bedtime tales of swordplay, swashbuckling and the fearsome Captain Hook. But the children become the heroes of an even greater story, when Peter Pan flies into their nursery one night and leads them over moonlit rooftops through a galaxy of stars and to the lush jungles of Neverland.', 113, '/6QdU3TZZrIvXFzoHOwafZAynFjB.jpg', '/zyWbOvKCdA9V9P5xuUG2eiPYsUo.jpg', 'gVC0bENF-Ec'),
    (10603, 'Deep in the African jungle, a baby named George, the sole survivor of a plane crash, is raised by gorillas. George grows up to be a buff and lovable klutz who has a rainforest full of animal friends: Tookie, his big-beaked toucan messenger; Ape, a witty talking gorilla; and Shep, a peanut-loving pooch of an elephant. But when poachers mess with George''s pals, the King of Swing swings into action.', 92, '/lWp8hUqE4oLPxsYgilXoYoVThfU.jpg', '/gR9ztrutzPPqgK2V2djS0fg2twW.jpg', 'PP9VGoP8xnI'),
    (10625, 'Cady Heron is a hit with The Plastics, the A-list girl clique at her new school, until she makes the mistake of falling for Aaron Samuels, the ex-boyfriend of alpha Plastic Regina George.', 97, '/2ZkuQXvVhh45uSvkBej4S7Ix1NJ.jpg', '/nP3y0TkR6XniFs9J53qQkg4Bnnk.jpg', 'EMzEmGfTuM4'),
    (10637, 'After leading his football team to 15 winning seasons, coach Bill Yoast is demoted and replaced by Herman Boone – tough, opinionated and as different from the beloved Yoast as he could be. The two men learn to overcome their differences and turn a group of hostile young men into champions.', 113, '/825ohvC4wZ3gCuncCaqkWeQnK8h.jpg', '/7lwo8VLHD8Va49DKuszabpm41V9.jpg', 'nPhu9XsRl4M'),
    (10648, '"Dirty" Harry Callahan is a San Francisco Police Inspector on the trail of a group of rogue cops who have taken justice into their own hands. When shady characters are murdered one after another in grisly fashion, only Dirty Harry can stop them.', 124, '/1uX1uzn09seCftG3rTGLPyFXxV6.jpg', '/7QPcmXePg5U4hmUzugFPX44ntxK.jpg', '83iV6rVG-qw'),
    (10649, 'Dirty Harry Callahan returns again, this time saddled with a rookie female partner. Together, they must stop a terrorist group consisting of angry Vietnam veterans.', 96, '/l0W85fpnsfnpLSSF3D6bKKlH1dD.jpg', '/bAMxzr52aGwNOQrrxqYyIrvx9zk.jpg', 'ocz7A2B9H-c'),
    (10650, 'When a young rape victim takes justice into her own hands and becomes a serial killer, it''s up to Dirty Harry Callahan, on suspension from the SFPD, to bring her to justice.', 117, '/fSADY0EEM7ntpK5IwumcGS4UNNE.jpg', '/vjA6MbA8aI4A3GSN1wWSsi9OGNl.jpg', '8AnAgwxJk0Y'),
    (10661, 'An Israeli counterterrorism soldier with a secretly fabulous ambition to become a Manhattan hairstylist. Zohan''s desire runs so deep that he''ll do anything -- including faking his own death and going head-to-head with an Arab cab driver -- to make his dreams come true.', 113, '/gBhLQmpCPoKFMCGsulMbIFzrBID.jpg', '/tfUotS2rLaIu7ieJPDonyDn5EqQ.jpg', 'ucmnTmYpGhI'),
    (10665, 'After a 4 a.m. knock at the door and haunting voices, Kristen McKay and James Hoyt’s remote getaway becomes a psychological night of terror as three masked strangers invade. Now they must go far beyond what they thought themselves capable of if they hope to survive.', 86, '/gwsg4qFmLOvlhwXj4OZuxfFUdP0.jpg', '/y27M2hIwZRRvMAVEadFPP5hCPg1.jpg', 'jKGiF5m-FNY'),
    (10669, 'Intent on seeing the Cahulawassee River before it''s turned into one huge lake, outdoor fanatic Lewis Medlock takes his friends on a river-rafting trip they''ll never forget into the dangerous American back-country.', 109, '/2TrAzNJlHyNYYSkQf6asg3rs2Xr.jpg', '/aaqbyTRo1bZB34ZdjeWyqnL0qz0.jpg', 'iuOUF1-4P3c'),
    (10674, 'When Imperial China calls one man from every family to defend the empire from invading Huns, a young woman disguises herself as a soldier to take her ailing father’s place. Facing ruthless invaders, brutal training, and the risk of execution if discovered, she must decide who she truly is—and what she’s willing to fight for.', 88, '/jAbexAtB0aSfP5Ay4TpWHARyVnG.jpg', '/mUYV0ZdsDEliGaQahcQH1F3grsP.jpg', '2z2KsFZs-8I'),
    (10681, 'After hundreds of years doing what he was built for, WALL•E—a robot designed to clean up the earth—discovers a new purpose in life when he meets a sleek search robot named EVE. EVE comes to realize that WALL•E has inadvertently stumbled upon the key to the planet''s future, and races back to space to report to the humans. Meanwhile, WALL•E chases EVE across the galaxy and sets into motion one of the most imaginative adventures ever brought to the big screen.', 98, '/hbhFnRzzg6ZDmm8YAmxBnQpQIPh.jpg', '/nYs4ZwnJBK4AgljhvzwNz7fpr3E.jpg', 'geplBr2fcZc'),
    (10683, 'The lives of several individuals intertwine as they go about their lives in their own unique ways, engaging in acts which society as a whole might find disturbing in a desperate search for human connection.', 140, '/rYfUcEV88Z3gENrfYTE6i8yBkDr.jpg', '/3AE92av4pGYx9NKKss7x5zEgEOS.jpg', '1eOzYczx-Xk'),
    (10693, 'Leaving the safety of their nursery behind, Wendy, Michael and John follow Peter Pan to a magical world where childhood lasts forever. But while in Neverland, the kids must face Captain Hook and foil his attempts to get rid of Peter for good.', 77, '/fJJOs1iyrhKfZceANxoPxPwNGF1.jpg', '/vwcfvPzYO3Gz975yRXp6DYSSbzo.jpg', 'u9crctwuDLk'),
    (10708, 'Two men get laid off and have to become stay-at-home dads when they can''t find jobs, which inspires them to open their own day-care center.', 92, '/uiey5XUKuPicwpIJMf1OpaOd1jL.jpg', '/gQ9uxP1hBIJd0dw4jMTCkToQQly.jpg', 'hx0_F3I10ws'),
    (10719, 'When young Buddy falls into Santa''s gift sack on Christmas Eve, he''s transported back to the North Pole and raised as a toy-making elf by Santa''s helpers. But as he grows into adulthood, he can''t shake the nagging feeling that he doesn''t belong. Buddy vows to visit Manhattan and find his real dad, a workaholic.', 97, '/oOleziEempUPu96jkGs0Pj6tKxj.jpg', '/5nhp41gx49vXjwXuDXJwQrRFsng.jpg', '14o38xfHlXc'),
    (10756, 'Workaholic Jim Evers and his wife/business partner Sara get a call one night from  a mansion owner, Edward Gracey, who wants to sell his house. Once the Evers family arrive at the mansion, a torrential thunderstorm of mysterious origin strands them with the brooding, eccentric Gracey, his mysterious butler, and a variety of residents both seen and unseen.', 88, '/lGi5yio4pdDz5PkSeZCbnMQz5vK.jpg', '/uUgn9P3Ulmjt9bOfp5Yt83fauAS.jpg', 'IAJBBmMhC9U'),
    (10764, 'Betrayed by Vesper, the woman he loved, 007 fights the urge to make his latest mission personal. Pursuing his determination to uncover the truth, Bond and M interrogate Mr. White, who reveals that the organization that blackmailed Vesper is far more complex and dangerous than anyone had imagined.', 106, '/e3DXXLJHGqMx9yYpXsql1XNljmM.jpg', '/uGs5Z7dMguf7kxWubGFcp9EhKcy.jpg', 'BBqYaFEWBxI'),
    (10830, 'Matilda Wormwood is an brilliant and intelligent little girl. Unfortunately, her parents, Harry and Zinnia, fail to see that fact. As time passes, she finally starts school and has a kind teacher, loyal friends, and a terrifying, sadistic headmistress. As she becomes fed up with the constant cruelty, she discovers she has a special gift that she just might be able to use to outwit the unruly adults around her.', 98, '/wYoDpWInsBEVSmWStnRH06ddoyk.jpg', '/t3HVA7XdVnQneMjI5hYjEhXmHY3.jpg', 'c2DK0o-uEnU'),
    (10835, 'Mob assassin Jeffrey is no ordinary hired gun; the best in his business, he views his chosen profession as a calling rather than simply a job. So, when beautiful nightclub chanteuse Jennie is blinded in the crossfire of his most recent hit, Jeffrey chooses to retire after one last job to pay for his unintended victim''s sight-restoring operation. But when Jeffrey is double-crossed, he reluctantly joins forces with a rogue policeman to make things right.', 110, '/8hTxlSqMAHBXAh1eB69ir0BXhzE.jpg', '/jetidiki3UjVJEpFwcK2kUrvoR5.jpg', 'bdLwJ2-zxDA'),
    (10865, 'A young linguist named Milo Thatch joins an intrepid group of explorers to find the mysterious lost continent of Atlantis.', 95, '/oK8yR6xSQreWf1ouP1VpXKwoop5.jpg', '/4eTiLRTYwAVQyQAjuFuf3BXAony.jpg', 'DIA1OxnY3s4'),
    (10882, 'Cursed to die by the evil fairy Maleficent when she was a baby, Princess Aurora is sent into hiding under protection from three good fairies. As she grows up far away, Maleficent becomes increasingly determined to seal the princess''s fate.', 75, '/pO9YMLSmj3essVSWSGygjGxX6Kw.jpg', '/me67dwJnUBt3O9NqZaBdEQ6i4vM.jpg', 'pTd047cEBHg'),
    (10895, 'When the gentle woodcarver Geppetto builds a marionette to be his substitute son, a benevolent fairy brings the toy to life. The puppet, named Pinocchio, is not yet a human boy. He must earn the right to be real by proving that he is brave, truthful, and unselfish.', 88, '/bnZJrLRnoQHpzEJdka1KYfsAF3N.jpg', '/ikpwuaK0yzNhXO24OeB7cKulhZE.jpg', '_xHYzf_rdGU'),
    (10947, 'A popular high school athlete and an academically gifted girl get roles in the school musical and develop a friendship that threatens East High''s social order.', 98, '/1DGmWZjUJPeKGFRHGCA6VPFUBML.jpg', '/2p1nyBVSEBiCTrrZeVSV9nIsqHr.jpg', 'mpgel-TjMKk'),
    (10948, 'When a feisty little fox named Tod is adopted into a farm family, he quickly becomes friends with a fun and adorable hound puppy named Copper. Life is full of hilarious adventures until Copper is expected to take on his role as a hunting dog -- and the object of his search is his best friend!', 82, '/bbPEYD1z1DN13UJMr9sjhMh8DJx.jpg', '/lNmIAX1IuPIEPMHhLBEm4wmhYX0.jpg', 'LhV6BBvt8Vs'),
    (10996, 'Stuart, an adorable white mouse, still lives happily with his adoptive family, the Littles, on the east side of Manhattan''s Central Park. More crazy mouse adventures are in store as Stuart, his human brother, George, and their mischievous cat, Snowbell, set out to rescue a friend.', 78, '/1vdPKC35IOjEAJEr9Y2rjEeyCcW.jpg', '/iEvlXeDvLW5IjmWa5jwO0Tieu1g.jpg', 'k--OdtbKyqE'),
    (10999, 'John Matrix, the former leader of a special commando strike force that always got the toughest jobs done, is forced back into action when his young daughter is kidnapped. To find her, Matrix has to fight his way through an array of punks, killers, one of his former commandos, and a fully equipped private army. With the help of a feisty stewardess and an old friend, Matrix has only a few hours to overcome his greatest challenge: finding his daughter before she''s killed.', 90, '/ollPAAAgZ7euU8VisfqU3cuXhZ6.jpg', '/gvao0WZchzudp2oMF5sjgzwHY0q.jpg', 'm264f4tfG2s'),
    (11007, 'The Baker brood moves to Chicago after patriarch Tom gets a job coaching football at Northwestern University, forcing his writer wife, Kate, and the couple''s 12 children to make a major adjustment. The transition works well until work demands pull the parents away from home, leaving the kids bored -- and increasingly mischievous.', 98, '/afclGGoQslTYFTnyW1LRMtJMiBp.jpg', '/cgqJ2JAEFrFIxLpJ7hrsSMu1dDL.jpg', 'csiX-mSqkGc'),
    (11009, 'Tony spends his Saturdays at a disco where his stylish moves raise his popularity among the patrons. But his life outside the disco is not easy and things change when he gets attracted to Stephanie.', 118, '/ylA7E5Md21aqgzxbwa2dFxX8LKV.jpg', '/iihMna17sTxP3zwlWBsKZbvDiGZ.jpg', 'lX2FffaLdks'),
    (11011, 'Billionaire heir Richie Rich has it all, including Reggie Jackson as a batting coach and Claudia Schiffer as a personal trainer -- but no playmates. What''s more, scoundrel Laurence Van Dough is scheming to take over the family empire. Uh-oh! Enter faithful butler Cadbury to save the day.', 94, '/qgGh5d0IHAZRlHIdFS3XWVygumR.jpg', '/e3TJpdAJnuJkywVRvf4IevhSzM3.jpg', 'Yddr5thpDTE'),
    (11024, 'A masked villain wreaks mayhem on the city of Coolsville with a monster machine that creates real-life versions of Mystery Inc.''s former foes like The 10,000 Volt Ghost, The Cotton Candy Glob, The Skelemen and The Pterodactyl Ghost. Fred, Daphne, Shaggy, Velma and Scooby-Doo launch an investigation into the monster outbreak that leaves Shaggy and Scooby questioning their roles in Mystery Inc. Eager to prove their detective skills, the ever-ravenous duo comes up with a secret plan to solve the mystery all by themselves. Can the gang unravel their most challenging case?', 93, '/5BrXCJrs22bR5KR6mLHluYo6y4m.jpg', '/m8y7OjvCBLmJfG6CIb5gpXFSLec.jpg', 'mwsDWv26sVM'),
    (11033, 'After witnessing a mysterious woman brutally slay a homemaker, prostitute Liz Blake finds herself trapped in a dangerous situation. While the police thinks she is the murderer, the real killer is intent on silencing her only witness.', 105, '/oy1m5dd44foNrxV8U9l6Walx82V.jpg', '/8UZfEjAlFq1iUiAkHMkJViq4ZO0.jpg', 'aR8tpdj5WL8'),
    (11036, 'An epic love story centered around an older man who reads aloud to a woman with Alzheimer''s. From a faded notebook, the old man''s words bring to life the story about a couple who is separated by World War II, and is then passionately reunited, seven years later, after they have taken different paths.', 123, '/rNzQyW4f8B8cQeg7Dgj3n6eT5k9.jpg', '/zdXnJqBaGFVtLoPNuMeKfEYUViZ.jpg', 'FC6biTjEyZw'),
    (11130, 'Mia Thermopolis is now a college graduate and on her way to Genovia to take up her duties as princess. Accompanied by her friend Lilly, Mia continues her ''princess lessons'', like riding horses side-saddle and archery. But her already complicated life is turned upside down once again when she learns that she is to take the crown as queen earlier than expected, all while she meets a mysteriously charming young man.', 113, '/upJOyrxxSIxlSZC7KEqJfB1vlGl.jpg', '/pmOXaAK8hteMlCiMZyyDJENHCZI.jpg', 'noajhlyKW8s'),
    (11152, 'Americans Amy, Stacy, Jeff and Eric look for fun during a sunny holiday in Mexico, but they get much more than that after visiting an archaeological dig in the jungle.', 91, '/6HpicbiT7xmlMjQXOSCeNoLZGpf.jpg', '/xW7UfUVRLypDw2CvKFLmFB9Z7Xa.jpg', 'cyglpQU5sJ0'),
    (11216, 'A filmmaker recalls his childhood, when he fell in love with the movies at his village''s theater and formed a deep friendship with the theater''s projectionist.', 124, '/aRgPnx4aPS96f7CnhJH7IG5dN1A.jpg', '/zoVeIgKzGJzpdG6Gwnr7iOYfIMU.jpg', 'JMyVSD6OvO8'),
    (11224, 'Cinderella has faith her dreams of a better life will come true. With help from her loyal mice friends and a wave of her Fairy Godmother''s wand, Cinderella''s rags are magically turned into a glorious gown and off she goes to the Royal Ball. But when the clock strikes midnight, the spell is broken, leaving a single glass slipper... the only key to the ultimate fairy-tale ending!', 74, '/4nssBcQUBadCTBjrAkX46mVEKts.jpg', '/puJKgNcWaGgMk5VHanSSomUTpmw.jpg', 'rPTMApBFfcI'),
    (11247, 'Routinely exploited by her wicked stepmother, the downtrodden Samantha Montgomery is excited about the prospect of meeting her Internet beau at the school''s Halloween dance.', 95, '/ukwP7gDPWxj1R1dW5iN3mnxkL3D.jpg', '/cxj7Fi2r1fjE8iM2jynhx4YF1Jb.jpg', 'B_VFs9j95gc'),
    (11253, 'Hellboy, his pyrokinetic girlfriend, Liz, and aquatic empath, Abe Sapien, face their biggest battle when an underworld elven prince plans to reclaim Earth for his magical kindred. Tired of living in the shadow of humans, Prince Nuada tries to awaken an ancient force of killing machines, the all-powerful Golden Army, to clear the way for fantasy creatures to roam free. Only Hellboy can stop the dark prince and prevent humanity''s annihilation.', 120, '/zO0Wdrxnhx3KoJEvychSmnY3urC.jpg', '/gqQKxYVIaYv53Qoy72nQqQxdXYF.jpg', 'Yjivaeh5YOk'),
    (11281, 'After failing to kill stubborn survivor Laurie and taking a bullet or six from former psychiatrist Dr. Sam Loomis, Michael Myers has followed Laurie to the Haddonfield Memorial Hospital, where she''s been admitted for Myers'' attempt on her life. The institution proves to be particularly suited to serial killers, however, as Myers cuts, stabs and slashes his way through hospital staff to reach his favorite victim.', 92, '/3nX5HHGgOKaVMxXwMLT9DHO1Ne6.jpg', '/lDXQNRmQKzJGdEJSDxWrjIZb7gB.jpg', 'W34hF0rsj94'),
    (11283, 'Widower Cedric Brown hires Nanny McPhee to care for his seven rambunctious children, who have chased away all previous nannies. Taunted by Simon and his siblings, Nanny McPhee uses mystical powers to instill discipline. And when the children''s great-aunt and benefactor, Lady Adelaide Stitch, threatens to separate the kids, the family pulls together under the guidance of Nanny McPhee.', 97, '/8tommndfI0W62teXwSmXdmVZ7gz.jpg', '/ijmKdhQQ86L18ZUywjHjM7h7YgO.jpg', 'rA9R6oustLk'),
    (11319, 'Two agents of the mouse-run International Rescue Aid Society search for a little orphan girl kidnapped by sinister treasure hunters.', 78, '/9jpDjrRyvv9Nw0piXOpHHQTfxw9.jpg', '/dSlofjxxcTSLmnH6602WsSSELU5.jpg', 'bz4vILhWO18'),
    (11321, 'An IRS agent with a fateful secret embarks on an extraordinary journey of redemption by forever changing the lives of seven strangers.', 123, '/85zUipgVy2QbvAJ6djZXYaGckMv.jpg', '/mDu3nkdjzkJ9loy3QyppGcLjaI7.jpg', 'hvu2F6t26hs'),
    (11322, 'Depression-era bank robber John Dillinger''s charm and audacity endear him to much of America''s downtrodden public, but he''s also a thorn in the side of J. Edgar Hoover and the fledgling FBI. Desperate to capture the elusive outlaw, Hoover makes Dillinger his first Public Enemy Number One and assigns his top agent, Melvin Purvis, the task of bringing him in dead or alive.', 140, '/3KgtekisQBrHRsm2cD5UOB6Ce3k.jpg', '/rlKB2moKVOPasy4Dr19QluzbJgA.jpg', 'pv0DMzFwEW4'),
    (11324, 'World War II soldier-turned-U.S. Marshal Teddy Daniels investigates the disappearance of a patient from a hospital for the criminally insane, but his efforts are compromised by troubling visions and a mysterious doctor.', 138, '/nrmXQ0zcZUL8jFLrakWc90IR8z9.jpg', '/lavdyiJWciCJvyLG37ZOs6HJijg.jpg', 'qdPw9x9h5CY'),
    (11327, 'Billy Hayes is caught attempting to smuggle drugs out of a country. The courts decide to make an example of him, sentencing him to more than 30 years in prison. Hayes has two opportunities for release: the appeals made by his lawyer, his family, and the American government, or the "Midnight Express".', 121, '/mIzGfVCSWmmYjLIIbA2BX3rlV56.jpg', '/f4dcx5U9X3w27e8iithmsaohF5t.jpg', 'lhuutAnXBzQ'),
    (11361, 'After lying in a coma for a year, Michael Myers awakens and stalks his way back to his small hometown in Illinois, intent on killing his niece, Jamie, who has been confined to a mental institution since his last attempt to slay her.', 98, '/rYvP6yMXCIVHnkVtwGaAXFmpzkB.jpg', '/cZGpp2cD3dh15rrnA1jrAppZHyt.jpg', 'ilHM_qpy-zM'),
    (11368, 'The owner of a seedy small-town Texas bar discovers that one of his employees is having an affair with his wife. A chaotic chain of misunderstandings, lies and mischief ensues after he devises a plot to have them murdered.', 97, '/n8D1gVXUgmW4kkDzUzzoezAmUUa.jpg', '/rGPoNNk4fvgG2mvkNAxJJPlszOu.jpg', 'CO54LvO26zs'),
    (11395, 'On Christmas Eve, divorced dad Scott Calvin and his son discover Santa Claus has fallen off their roof. When Scott takes the reins of the magical sleigh, he finds he is now the new Santa, and must convince a world of disbelievers, including himself.', 97, '/hvV2rI60qOYELT7tHHLpxtafnBZ.jpg', '/p89QeYRc2u0rX0eKKU4TLJStwHO.jpg', 'aCc7bTJ8FCM'),
    (11397, 'On a bet, a gridiron hero at John Hughes High School sets out to turn a bespectacled plain Jane into a beautiful and popular prom queen in this outrageous send-up of the teen movies of the 1980s and ''90s.', 89, '/9ZaGxvj1mqdKVLpSloq4mzS7SK6.jpg', '/lyf1jjoMD1Pe7KD6KKEqL4Owgeb.jpg', 'f1sbQf58B50'),
    (11430, 'Timon the meerkat and Pumbaa the warthog are best pals and the unsung heroes of the African savanna. This prequel to the smash Disney animated adventure takes you back -- way back -- before Simba''s adventure began. You''ll find out all about Timon and Pumbaa and tag along as they search for the perfect home and attempt to raise a rambunctious lion cub.', 77, '/u2hN0WT7Dz46HfhQbr6uzSYfVW4.jpg', '/3eQnD9CIUerbXbgtFE1zJNvEVVo.jpg', 'p0DTnqn71WQ'),
    (11451, 'Maggie Peyton, the new owner of Number 53 - the free-wheelin'' Volkswagen bug with a mind of its own - puts the car through its paces on the road to becoming a NASCAR competitor.', 101, '/7lTfTZ8CDfXw09eAv3OOvsbCVgs.jpg', '/u6qrMY2PIzXwmydmKNHmVDFbjaV.jpg', 'K0aTcuB9IPw'),
    (11452, 'Van Wilder has been attending college for far too many years and is scared to graduate, but Van’s father eventually realizes what is going on. When he stops paying his son''s tuition fees, Van must come up with the money if he wants to stay in college, so he and his friends come up with a great fund-raising idea – throwing parties. However, when the college magazine finds out and reporter Gwen is sent to do a story on Van Wilder, things get a little complicated.', 92, '/4IvM4qnzlo62oLmS54FtyRt54ze.jpg', '/kvSQgjq2arVzfFVTvmiQc2Nl1XQ.jpg', 'qShNioFXXwM'),
    (11459, 'Set in a world where superheroes are commonly known and accepted, young Will Stronghold, the son of the Commander and Jetstream, tries to find a balance between being a normal teenager and an extraordinary being.', 100, '/nBB0XNMwvYvWpo67EcxQqKMoMKf.jpg', '/4gsnFDp3bsfFuDFot38F7sCVvBE.jpg', 'G7aMWVN1ThM'),
    (11474, 'Prominent gang leader Cyrus calls a meeting of New York''s gangs to set aside their turf wars and take over the city. At the meeting, a rival leader kills Cyrus, but a Coney Island gang called the Warriors is wrongly blamed for Cyrus'' death. Before you know it, the cops and every gangbanger in town is hot on the Warriors'' trail.', 94, '/d6YZpBq4BhQr1K985J3CuL1cA8J.jpg', '/7GDAldgmycOxNfEcycEX9IvVvIk.jpg', 'IAn_PrquNIY'),
    (11507, 'After losing an acting role and his girlfriend, Jake Scully finally catches a break: he gets offered a gig house-sitting in the Hollywood Hills. While peering through the beautiful home''s telescope one night, he spies a gorgeous woman dancing in her window. But when he witnesses the girl''s murder, it leads Scully through the netherworld of the adult entertainment industry on a search for answers—with porn actress Holly Body as his guide.', 114, '/lRFm5P2AdOGpELwm3HHhmUz6k5I.jpg', '/h5QkdbRmG2VodOCSB0QMhSGcCkI.jpg', '_B6KEJD605M'),
    (11524, 'Frank is an expert professional safecracker, specialized in high-profile diamond heists. He plans to use his ill-gotten income to retire from crime and build a nice life for himself complete with a home, wife and kids. To accelerate the process, he signs on with a top gangster for a big score.', 123, '/bpjRGwfYJ71bU0hNhLIz7g3t6Oy.jpg', '/3pYudqkEC8rkjqpBw8pqoLUtGHe.jpg', 'YDa_z0op7iU'),
    (11544, 'As Stitch, a runaway genetic experiment from a faraway planet, wreaks havoc on the Hawaiian Islands, he becomes the mischievous adopted alien "puppy" of an independent little girl named Lilo and learns about loyalty, friendship, and ʻohana, the Hawaiian tradition of family.', 85, '/cFuLvQJPoZpuruAtN3rVnMmLIH8.jpg', '/AcxbOWUbwtIEDisfuhNGHQNfnMK.jpg', 'wAtaSKQ4-T0'),
    (11551, 'When missile technology is used to enhance toy action figures, the toys soon begin to take their battle programming too seriously.', 110, '/2nuUjSzHsoYlRvTPmLo7m7gCQry.jpg', '/gdQk5g4TC95957Xs4xGbcOBnG56.jpg', 'YwIt5wagRsg'),
    (11569, 'Pinhead is set loose on the sinful streets of New York City to create chaos with a fresh cadre of Cenobitic kin.', 93, '/qnXEJp6KP6aIGWhNrg1fOKza4kp.jpg', '/xjeoa7KjnUMQzJXGunHmgMjhHmP.jpg', 'TDbbVx2YYEw'),
    (11619, 'London high-society mouse, Roddy is flushed down the toilet by Sid, a common sewer rat. Hang on for a madcap adventure deep in the sewer bowels of Ratropolis, where Roddy meets the resourceful Rita, the rodent-hating Toad and his faithful thugs, Spike and Whitey.', 85, '/ahVxu86XwxMp8RkartqY4B3mK9l.jpg', '/7xQk3HdCvkNmk3gblDGn9fVnbsT.jpg', 'zTj0LvKXIO0'),
    (11621, 'In Italy in the 1930s, sky pirates in biplanes terrorize wealthy cruise ships as they sail the Adriatic Sea. The only pilot brave enough to stop the scourge is the mysterious Porco Rosso, a former World War I flying ace who was somehow turned into a pig during the war. As he prepares to battle the pirate crew''s American ace, Porco Rosso enlists the help of spunky girl mechanic Fio Piccolo and his longtime friend Madame Gina.', 93, '/8mIvSvnVBApfORL9N6S38Q7wD6A.jpg', '/ec4m0EvVlEtVl5aySdw6ab9uG0b.jpg', '3LRyNwYg1f8'),
    (11631, 'A spirited young bride-to-be living with her single mother on a small Greek island secretly invites three of her mother''s ex-boyfriends in hope of finding her biological father to walk her down the aisle.', 108, '/xYLiCWmAMHJubx5jNZ7HuXKjAbV.jpg', '/90sDsHugeRU5dtTG3zEVIOXXl4L.jpg', '8RBNHdG35WY'),
    (11635, 'Three friends attempt to recapture their glory days by opening up a fraternity near their alma mater.', 92, '/nYtuwNHpEoIbTgS3aFPSEwZNN6l.jpg', '/2tZVYiosztNM1DAYUF59VPsNp9L.jpg', 'VqtymOtKr48'),
    (11665, 'When members of the nefarious crime syndicate KAOS attack the U.S. spy agency Control and the identities of secret agents are compromised, the Chief has to promote hapless but eager analyst Maxwell Smart to field agent. He is partnered with veteran and capable Agent 99, the only spy whose cover remains intact. Can they work together to thwart the evil world-domination plans of KAOS and its crafty operative?', 110, '/sZUjbtUS8qxXp4mj90evnqPJqX7.jpg', '/u0yaNgikY92zkI0t3fiEGZP3UWq.jpg', '-fYuByCXniA'),
    (11674, 'An evil, high-fashion designer plots to steal Dalmatian puppies in order to make an extravagant fur coat, but instead creates an extravagant mess.', 103, '/8o2ADoAyG796UwTjwBFjPyBz0yG.jpg', '/yqh3mb9jd3GTTs09ZlnW4mxS95z.jpg', 'mom8X7zk7PE'),
    (11688, 'When the self‑absorbed Emperor Kuzco is accidentally transformed into a llama, he must rely on a humble villager to survive the jungle and reclaim his throne.', 78, '/wwbgkXQBEKtnyIJapk6gUgWkVw8.jpg', '/mZj8EUr6F1x2PWZjKPxaeYd5WRw.jpg', 'Hjvy8vc39kw'),
    (11690, 'An American Army Major goes AWOL to Hong Kong for an outlawed martial arts contest called the Kumite.', 92, '/kndxR9TRK0kJ5hxzDprRSS80F2W.jpg', '/aSA7RuKmCQBnYKn70GYPi6ckgoY.jpg', 'bCZ1CIQ64YQ'),
    (11770, 'A young Shaolin follower reunites with his discouraged brothers to form a soccer team using their martial art skills to their advantage.', 113, '/z6ZQqwoxWy9muIxwUP4K2zWw7BU.jpg', '/lMRX4cLx4hxYth3iQ96c0E1RHGB.jpg', 'KEWUDWYDdYs'),
    (11774, 'Three wealthy children''s parents are killed in a fire. When they are sent to a distant relative, they find out that he is plotting to kill them and seize their fortune.', 108, '/r7S57FpBsCljWc9fBUo2Iy5XGew.jpg', '/i0M3a8Z2hfj5Oj4msArajhLjGvV.jpg', 'fccho1IyX8Y'),
    (11778, 'Three steelworkers enlist in the army and are sent to Vietnam, one leaving behind a rushed marriage, the others a shared love. What they encounter during the war changes their lives forever.', 183, '/bbGtogDZOg09bm42KIpCXUXICkh.jpg', '/a5zBQfXmLk3qqRYF7AioWpiAxk2.jpg', 'g7q1SjVdsNk'),
    (11782, 'A cop who loses his partner in a shoot-out with gun smugglers goes on a mission to catch them. In order to get closer to the leaders of the ring he joins forces with an undercover cop who''s working as a gangster hitman. They use all means of excessive force to find them.', 126, '/oMqr4CGGqVlfI8DdrSelK1e9aFM.jpg', '/bL3rgYFs0NTAoLBMpCBIJ7aX6hp.jpg', 'N_XBwks_MB8'),
    (11806, 'The Newton family live in their comfortable home, but there seems to something missing. This "hole" is filled by a small puppy, who walks into their home and their lives. Beethoven, as he is named, grows into a giant of a dog... a St Bernard. Doctor Varnick, the local vet has a secret and horrible sideline, which requires lots of dogs for experiments. Beethoven is on the bad doctor''s list.', 87, '/aSZYXOmQ9SW27gLdHU02PJQGBMH.jpg', '/dieTafH3G5IxNeyZbBdCOpugNzN.jpg', 'ki8wHMR-yOI'),
    (11836, 'There''s trouble brewing in Bikini Bottom. Someone has stolen King Neptune''s crown, and it looks like Mr. Krab, SpongeBob''s boss, is the culprit. Though he''s just been passed over for the promotion of his dreams, SpongeBob stands by his boss, and along with his best pal Patrick, sets out on a treacherous mission to Shell City to reclaim the crown and save Mr. Krab''s life.', 87, '/1rvzKV1d18EbDVaEd4VDzK3cgnY.jpg', '/6ZnHQKcqQ8nmfP6woZu2v5EtXoW.jpg', 'Tv8xk7BKaNM'),
    (11879, 'A farm boy reluctantly becomes a member of the undead when a girl he meets turns out to be part of a band of vampires who roam the highways in stolen cars.', 94, '/hVhFNn3IQxxARvnpLIKMx8ZfTtG.jpg', '/fLqhMfRyMySsqORn0xq7iFWRdcM.jpg', 'XBDhZrzqcPY'),
    (11886, 'With King Richard off to the Crusades, Prince John and his slithering minion, Sir Hiss, set about taxing Nottingham''s citizens with support from the corrupt sheriff - and staunch opposition by the wily Robin Hood and his band of merry men.', 83, '/x9AvkYek0bGdxQSZ8W3lAjGrREm.jpg', '/3WeFPoPVIGgMumjgLn0EPIfq53A.jpg', 'c5Qph47c2uE'),
    (11887, 'As seniors in high school, Troy and Gabriella struggle with the idea of being separated from one another as college approaches. Along with the rest of the Wildcats, they stage a spring musical to address their experiences, hopes and fears about their future.', 112, '/aq2o1wT0crBOTxof36O6KTyjpgE.jpg', '/spyZFUG0lR6FEbvMn3YBcxT8vdx.jpg', '1S8RTKL5cW8'),
    (11901, 'A gunfighting stranger comes to the small settlement of Lago. After gunning down three gunmen who tried to kill him, the townsfolk decide to hire the Stranger to hold off three outlaws who are on their way.', 106, '/AjkJCFkqanK1OZqiHxc6Kl2wPQO.jpg', '/gDrgpDJHi0ZwH69KfMIiuBMt0Ja.jpg', 'be2mIVxDrr8'),
    (11906, 'An American newcomer to a prestigious German ballet academy comes to realize that the school is a front for something sinister amid a series of grisly murders.', 99, '/f4EJQrq5bKCqJK6I5moST9kur2p.jpg', '/9uXGLBPIJkPqmVwiyh3FI0iAe6n.jpg', 'x_FfT98QJks'),
    (11917, 'Following Jigsaw''s grisly demise, Detective Mark Hoffman is commended as a hero, but Agent Strahm is suspicious, and delves into Hoffman''s past. Meanwhile, another group of people are put through a series of gruesome tests.', 95, '/rKl79KqLXg60KFyKsLe4wSSjQ08.jpg', '/jIjVPKDow5ai8dbs4PgWmtqg9Ol.jpg', 'J9TpHotLQk8'),
    (11932, 'For ten years, the tortured soul of serial killer Charles Lee Ray has been imprisoned inside a child''s doll. ''Chucky'' is reborn when his old flame, Tiffany, rescues his battered doll parts from a police impound. But Chucky wants his new playmate cut down to size, so he transforms his blushing bride into a stunning little terror. Chucky and Tiffany can''t wait to start their own homicidal honeymoon. When this demonic duo hits the road and hooks up with a pair of unsuspecting newlyweds, they leave a trail of murder and mayhem behind them. Chucky''s back!', 89, '/yaIPNOcC7ZRuwH3maNwP9qzIo5G.jpg', '/fLTd0VxpijUt6Hm1QM2ehLpWPeu.jpg', 'VNpqr8GfNRg'),
    (11970, 'Bestowed with superhuman strength, a young mortal named Hercules sets out to prove himself a hero in the eyes of his father, the great god Zeus. Along with his friends Pegasus, a flying horse, and Phil, a personal trainer, Hercules is tricked by the hilarious, hotheaded villain Hades, who''s plotting to take over Mount Olympus!', 93, '/dK9rNoC97tgX3xXg5zdxFisdfcp.jpg', '/oG9dcGSSu13fjFp1Uly15ZXjRKV.jpg', 'mXRDoJqg5Oo'),
    (12092, 'On a golden afternoon, wildly curious young Alice tumbles into the burrow and enters the merry, madcap world of Wonderland full of whimsical escapades.', 75, '/20cvfwfaFqNbe9Fc3VEHJuPRxmn.jpg', '/tyj0QztA0PkYo6XauifWjkx7UVi.jpg', 'JY2rHymtNvc'),
    (12096, 'When the coach of the France football team is killed by a poisoned dart in the stadium at the end of a game, and his huge, expensive ring with the Pink Panther diamond  disappears, the ambitious Chief Inspector Dreyfus assigns the worst police inspector – Jacques Clouseau – to the case.', 93, '/57ViRkdsddHLK32W8Nf3ZPLSAu4.jpg', '/3jiNJ4lyAmdSidvbFTFIL2GQGBu.jpg', 'er7sxi-ur1A'),
    (12113, 'The CIA’s hunt is on for the mastermind of a wave of terrorist attacks. Roger Ferris is the agency’s man on the ground, moving from place to place, scrambling to stay ahead of ever-shifting events. An eye in the sky – a satellite link – watches Ferris.  At the other end of that real-time link is the CIA’s Ed Hoffman, strategizing events from thousands of miles away. And as Ferris nears the target, he discovers trust can be just as dangerous as it is necessary for survival.', 128, '/sLjVDPPfNQfAma9XyOqHPClQb2V.jpg', '/jDPnm0VC2EHIvTwBnwMtQcMIM70.jpg', '1ejuhWeqaZA'),
    (12133, 'Brennan Huff and Dale Doback might be grown men. But that doesn''t stop them from living at home and turning into jealous, competitive stepbrothers when their single parents marry. Brennan''s constant competition with Dale strains his mom''s marriage to Dale''s dad, leaving everyone to wonder whether they''ll ever see eye to eye.', 98, '/nvggBbEraUTAVR6ffP3AaBUWSHs.jpg', '/247H2jS9Te9TTmKDcAMg3LN5gmI.jpg', 'CewglxElBK0'),
    (12143, 'While investigating a young nun''s rape, a corrupt New York City police detective, with a serious drug and gambling addiction, tries to change his ways and find forgiveness.', 96, '/mVJ2mXykqq3t2v1nuouf1P10g0d.jpg', '/m7NNNH0fAhkyIc4eEMUdyQy9NOB.jpg', 'Yhb2lT8Kktc'),
    (12153, 'Two FBI agent brothers, Marcus and Kevin Copeland, accidentally foil a drug bust. To avoid being fired they accept a mission escorting a pair of socialites to the Hamptons--but when the girls are disfigured in a car accident, they refuse to go. Left without options, Marcus and Kevin decide to pose as the sisters, transforming themselves from black men into rich white women.', 109, '/aHTUpo45qy9QYIOnVITGGqLoVcA.jpg', '/di47xqYMCYpjqwnqNlO17X5qXMX.jpg', 'aeVkbNka9HM'),
    (12155, 'Alice, now 19 years old, returns to the whimsical world she first entered as a child and embarks on a journey to discover her true destiny.', 108, '/o0kre9wRCZz3jjSjaru7QU0UtFz.jpg', '/ocOWbTzHcJVTw9Tz173KPeskDOP.jpg', '9POCgSRVvf0'),
    (12162, 'During the Iraq War, a Sergeant recently assigned to an army bomb squad is put at odds with his squad mates due to his maverick way of handling his work.', 131, '/io2dfBJhasvGbgkCX9cCGVOiA99.jpg', '/off0xgvtfHY82l3MC4mDpCk1APY.jpg', '4mgWq9wZs2o'),
    (12163, 'Aging wrestler Randy "The Ram" Robinson is long past his prime but still ready and rarin'' to go on the pro-wrestling circuit. After a particularly brutal beating, however, Randy hangs up his tights, pursues a serious relationship with a long-in-the-tooth stripper, and tries to reconnect with his estranged daughter. But he can''t resist the lure of the ring and readies himself for a comeback.', 109, '/7QH5p5BF582k6qHufCKjftfkqWH.jpg', '/wcJmFsz8RqIhozMwvU81hreTX4i.jpg', 'qjhGZhRJ3j0'),
    (12180, 'As the Clone Wars sweep through the galaxy, Anakin Skywalker and his new Padawan learner Ahsoka Tano plunge into a dangerous mission to rescue the kidnapped son of crime lord Jabba the Hutt.', 98, '/iJQfixW818LUdSXlCDL3JZm0S0g.jpg', '/eVA4ztLIuPEsokkgQ3NRt9rTRVh.jpg', 'hh3P3DoZZh4'),
    (12222, 'An imaginative elephant named Horton hears a faint cry for help coming from a tiny speck of dust floating through the air. Horton suspects there may be life on that speck and despite a surrounding community, who thinks he has lost his mind, he is determined to save the tiny particle.', 86, '/6k47Z3A5zI2rxubTMwiLyIqQLLr.jpg', '/vs2kMR95pXOsD69OIslazHOEE8U.jpg', 'HvuO0lK3U10'),
    (12230, 'When a litter of dalmatian puppies are abducted by the minions of Cruella De Vil, the parents must find them before she uses them for a diabolical fashion statement.', 79, '/kSlYq6FrBUviGSEh8v4L9nrSnBT.jpg', '/cZgUATpU4NDlsfGj7sRriKJEiLB.jpg', 'd2ALWgaLypE'),
    (12244, 'When 9 first comes to life, he finds himself in a post-apocalyptic world. All humans are gone, and it is only by chance that he discovers a small community of others like him taking refuge from fearsome machines that roam the earth intent on their extinction. Despite being the neophyte of the group, 9 convinces the others that hiding will do them no good.', 79, '/3uqXGOH4BQ2CLJWkDJZ0PzbUzOn.jpg', '/bxgbXWG7dBgNpaFw4BLwzNS7qLk.jpg', '_qApXdc1WPY'),
    (12262, 'Taking an ill-advised detour en-route to California, the Carter family soon run into trouble when their RV breaks down in the middle of the desert. Stranded, they find themselves at the mercy of monstrous cannibals lurking in the surrounding hills.', 90, '/1G2DBIEkoS0JdCiOFIeR3mD8ROE.jpg', '/e5ecjQw8AK0e924UIkMOUTxGhMj.jpg', 'zFVpBiVymTU'),
    (12279, 'Carmen''s caught in a virtual reality game designed by the Kids'' new nemesis, the Toymaker. It''s up to Juni to save his sister, and ultimately the world.', 84, '/buA8dN4zLNr0dYBeKfHfMnEfdLE.jpg', '/bmuTrxbPcr1nKCsV5YWWJi73PGR.jpg', 'mx0lo-xCljA'),
    (12405, 'A teenager reflects on his life after being accused of cheating on the Indian version of "Who Wants to be a Millionaire?".', 121, '/5leCCi7ZF0CawAfM5Qo2ECKPprc.jpg', '/1wZoVT9RJsZmNjg8CecXqSgFUd9.jpg', 'AIzbwV7on6Q'),
    (12429, 'When Sosuke, a young boy who lives on a clifftop overlooking the sea, rescues a stranded goldfish named Ponyo, he discovers more than he bargained for. Ponyo is a curious, energetic young creature who yearns to be human, but even as she causes chaos around the house, her father, a powerful sorcerer, schemes to return Ponyo to the sea.', 100, '/yp8vEZflGynlEylxEesbYasc06i.jpg', '/1QmEcK0w2Ub4Hm094fHbZT8vA7o.jpg', 'h6XP82TyFWw'),
    (12437, 'A prequel to the first two Underworld films, this fantasy explains the origins of the feud between the Vampires and the Lycans. Aided by his secret love, Sonja, courageous Lucian leads the Lycans in battle against brutal Vampire king Viktor. Determined to break the king''s enslavement of his people, Lucian faces off against the Death Dealer army in a bid for Lycan independence.', 92, '/yW9gF7rGn8EoV8B8rxOx1xjxVZf.jpg', '/agQrynTKEWWKAowcf7Dvb3I2F9A.jpg', 'pexrer4SweU'),
    (12444, 'Harry, Ron and Hermione walk away from their last year at Hogwarts to find and destroy the remaining Horcruxes, putting an end to Voldemort''s bid for immortality. But with Harry''s beloved Dumbledore dead and Voldemort''s unscrupulous Death Eaters on the loose, the world is more dangerous than ever.', 146, '/iGoXIpQb7Pot00EEdwpwPajheZ5.jpg', '/slW0M2G9txC0aUbftCTm1nYX1K8.jpg', 'Su1LOpjvdZ4'),
    (12445, 'Harry, Ron and Hermione continue their quest to vanquish the evil Voldemort once and for all. Just as things begin to look hopeless for the young wizards, Harry discovers a trio of magical objects that endow him with powers to rival Voldemort''s formidable skills.', 130, '/c54HpQmuwXjHq2C9wmoACjxoom3.jpg', '/cbcpDn6XJaIGoOil1bKuskU8ds4.jpg', 'kwM3kN8PNOc'),
    (12477, 'In the final months of World War II, 14-year-old Seita and his sister Setsuko are orphaned when their mother is killed during an air raid in Kobe, Japan. After a falling out with their aunt, they move into an abandoned bomb shelter. With no surviving relatives and their emergency rations depleted, Seita and Setsuko struggle to survive.', 89, '/k9tv1rXZbOhH7eiCk378x61kNQ1.jpg', '/aHaqZpOL7UyVu0nKqp3SMz0o2E1.jpg', 'QZbcx0WNrMU'),
    (13051, 'A DEA agent whose family was slain as part of a conspiracy, and an assassin out to avenge her sister''s death, join forces to solve a series of murders in New York City.', 100, '/dxy17rpjiWVmhaGvMlScZj96i8h.jpg', '/8tXo6o4cYzFxKYZPEKamWhkvN7x.jpg', 'GklHaGfncJI'),
    (13053, 'Bolt is the star of the biggest show in Hollywood. The only problem is, he thinks it''s real. After he''s accidentally shipped to New York City and separated from Penny, his beloved co-star and owner, Bolt must harness all his "super powers" to find a way home.', 98, '/v5aC4nrzXFGJDWY4JO1eengXzqk.jpg', '/zWqxBc6pdSIjklqWfZ70l5ce28P.jpg', 'T_yzxWNEOu8'),
    (13183, 'In a gritty and alternate 1985, the glory days of costumed vigilantes have been brought to a close by a government crackdown. But after one of the masked veterans is brutally murdered, an investigation into the killer is initiated. The reunited heroes set out to prevent their own destruction, but in doing so they uncover a sinister plot that puts all of humanity in grave danger.', 163, '/aVURelN3pM56lFM7Dgfs5TixcIf.jpg', '/dH7ia3vtkYCa3CBvDnvVjqm9uiQ.jpg', '89xoXmHgG00'),
    (13186, 'Retired military commander Colonel Dale Murphy hosts the simulated post-apocalyptic reality show where participants are challenged to survive a remote West Virginia wasteland. But the show turns into a nightmarish showdown when each realizes they are being hunted by an inbred family of cannibals determined to make them all dinner!', 97, '/iQ37ygxcpJNZp1XdHMantumylmw.jpg', '/o2SeAw8ARPB1D8oudCRJcxW3w60.jpg', 'VanCRj8eI9o'),
    (13207, 'A group of young adults visit a boarded up campsite named Crystal Lake where they soon encounter the mysterious Jason Voorhees and his deadly intentions.', 97, '/88wlJ4teYlck4hJ2bnlxBrAVh0m.jpg', '/j1PzqAMU4LzUnz60q9EEqmeX24n.jpg', 'J-gx4AHReGs'),
    (13223, 'Disgruntled Korean War veteran Walt Kowalski sets out to reform his neighbor, Thao Lor, a Hmong teenager who tried to steal Kowalski''s prized possession: a 1972 Gran Torino.', 116, '/zUybYvxWdAJy5hhYovsXtHSWI1l.jpg', '/sO2coXOiWWZL0sr6RsWTS3tu0J9.jpg', 'F8zue_BzNsw'),
    (13363, 'A departing professor gathers his closest colleagues for an intimate farewell, but the night takes an unexpected turn when he shares a stunning secret about his past. As the conversation unfolds, skepticism and curiosity collide, challenging everything they thought they knew about history, science, and belief.', 87, '/V086R82gNgWrotaXZFO4JhdgB1.jpg', '/gt4EnUGbbGbNOX0q47YII3WxB48.jpg', 'w01A_70hifM'),
    (13387, 'Frank Martin puts the driving gloves on to deliver Valentina, the kidnapped daughter of a Ukrainian government official, from Marseilles to Odessa on the Black Sea. En route, he has to contend with thugs who want to intercept Valentina''s safe delivery and not let his personal feelings get in the way of his dangerous objective.', 104, '/o4w9VF3GRZuXe9NHHvZ07pJespl.jpg', '/5yrQsEuuqc4s8t8nszLxAAGQpR2.jpg', 'Pbh3CDBNIQA'),
    (13448, 'Harvard symbologist Robert Langdon is recruited by the Vatican to investigate the apparent return of the Illuminati – a secret, underground organization – after four cardinals are kidnapped on the night of the papal conclave.', 139, '/tFZQAuulEOtFTp0gHbVdEXwGrYe.jpg', '/olz8Xw3yOLpBAHKgPoSRwmomdM.jpg', 'arb2-aZMDFg'),
    (13460, 'The lethal Reaper virus spreads throughout Britain—infecting millions and killing hundreds of thousands. Authorities brutally and successfully quarantine the country but, three decades later, the virus resurfaces in a major city. An elite group of specialists is urgently dispatched into the still-quarantined country to retrieve a cure by any means necessary. Shut off from the rest of the world, the unit must battle through a landscape that has become a waking nightmare.', 108, '/cKUmTyXgmhv8cMRCY9RYTKcAeTn.jpg', '/2GmnhciVW262POiTCx43TTSvys3.jpg', 'fJDVi0BMabU'),
    (13475, 'The fate of the galaxy rests in the hands of bitter rivals. One, James Kirk, is a delinquent, thrill-seeking Iowa farm boy. The other, Spock, a Vulcan, was raised in a logic-based society that rejects all emotion. As fiery instinct clashes with calm reason, their unlikely but powerful partnership is the only thing capable of leading their crew through unimaginable danger, boldly going where no one has gone before. The human adventure has begun again.', 127, '/lV5OpzAss1z06YNagOVap1I35mH.jpg', '/cqXEwYFcwyKPZCKl1jAPaG3cMsl.jpg', 'iGAHnZ555nI'),
    (13510, 'When a young couple goes to a remote wooded lake for a romantic getaway, their quiet weekend is shattered by an aggressive group of local kids. Rowdiness quickly turns to rage as the teens terrorize the couple in unimaginable ways, and a weekend outing becomes a bloody battle for survival.', 91, '/tOg6ElTe1mJwaCFN0172U4oso22.jpg', '/s9v1QZMVhwShQ7415jPhtfqzyjG.jpg', 'rJkO9HBXuhc'),
    (13597, 'Frustrated with babysitting on yet another weekend night, Sarah, a teenager with an active imagination, summons the Goblins to take her baby stepbrother away. When little Toby actually disappears, Sarah must follow him into a fantastical world to rescue him from the Goblin King. Guarding his castle is the labyrinth itself, a twisted maze of deception, populated with outrageous characters and unknown dangers.', 101, '/pejayhTVBEL4w8YKSfrhOjjWVlH.jpg', '/mGkleIuPO2flRyvP8yBcUykSQsp.jpg', '8bJy0GF2RZ0'),
    (13680, 'Bachelor football star Joe Kingman seems to have it all. He is wealthy and carefree, and his team is on the way to capturing a championship. Suddenly, he is tackled by some unexpected news: He has a young daughter, the result of a last fling with his ex-wife. Joe must learn to balance his personal and professional lives with the needs of his child.', 110, '/fcLFvIqCUrhY96mkSmr3okxaMEw.jpg', '/qCKO6xQMLgB1goL1v20tMOfMLBU.jpg', 'xo3XEQxbaEk'),
    (13700, 'When a greedy outlaw schemes to take possession of the "Patch Of Heaven" dairy farm, three determined cows, a karate-kicking stallion and a colorful corral of critters join forces to save their home. The stakes are sky-high as this unlikely animal alliance risk their hides and match wits with a mysterious band of bad guys.', 76, '/cgKnkbO3fNWwKc9qLyLYdeZQ9Vj.jpg', '/Jghbo8U2XkmGjCfKD9NiMM70ha.jpg', 'LMW_nGAsLfc'),
    (13804, 'When a crime brings them back to L.A., fugitive ex-con Dom Toretto reignites his feud with agent Brian O''Conner. But as they are forced to confront a shared enemy, Dom and Brian must give in to an uncertain new trust if they hope to outmaneuver him. And the two men will find the best way to get revenge: push the limits of what''s possible behind the wheel.', 107, '/lUtVoRukW7WNtUySwd8hWlByBds.jpg', '/25HepicRtrzZ3MVCqhfoxGDbHjw.jpg', 'ne5E7hOQqn0'),
    (13809, 'When a Russian mobster sets up a real estate scam that generates millions of pounds, various members of London''s criminal underworld pursue their share of the fortune. Various shady characters, including Mr One-Two, Stella the accountant, and Johnny Quid, a druggie rock-star, try to claim their slice.', 114, '/6mLXG2f7LBRpbZZgxsOFO5scgzd.jpg', '/11V6JMreBokxvTZTsxmSQsibaRb.jpg', 'mnigSqJ2i10'),
    (13811, 'A teacher opens a time capsule that has been dug up at his son''s elementary school; in it are some chilling predictions -- some that have already occurred and others that are about to -- that lead him to believe his family plays a role in the events that are about to unfold.', 121, '/OG0mxQt4YaNIWiz8EKJSHe9lPh.jpg', '/oZqounvawm4hDxpDGDHLmVBGJBr.jpg', 'A2oDiEVXuDo'),
    (13885, 'The infamous story of Benjamin Barker, a.k.a Sweeney Todd, who sets up a barber shop down in London which is the basis for a sinister partnership with his fellow tenant, Mrs. Lovett. Based on the hit Broadway musical.', 116, '/gAW4J1bkRjZKmFsJsIiOBASeoAp.jpg', '/obYVvi6eD4rjFeC7g4uoZQPIh7F.jpg', 'AAU7dRxGvco'),
    (13939, 'After his wife is murdered by street punks, a pacifistic New York City architect becomes a one-man vigilante squad, prowling the streets for would-be muggers after dark.', 93, '/rNksI6UiuTgLtBy69WvKT1PrG0R.jpg', '/9blNOmgTobqZGpt9A3JbG0mpMi3.jpg', 'FuDFXV56gQ0'),
    (14069, 'When 17-year-old Makoto Konno gains the ability to ''leap'' backwards through time, she immediately sets about improving her grades and preventing personal mishaps. However, she soon realises that changing the past isn''t as simple as it seems, and eventually, will have to rely on her new powers to shape the future of herself and her friends.', 98, '/fmK92C7HGu6sK0axItlQ0YsO9qR.jpg', '/6m2qbAqSMJTX4HUwRvVEQI6ioiO.jpg', 'boZINHGDxMw'),
    (14160, 'Carl Fredricksen spent his entire life dreaming of exploring the globe and experiencing life to its fullest. But at age 78, life seems to have passed him by, until a twist of fate (and a persistent 8-year old Wilderness Explorer named Russell) gives him a new lease on life.', 96, '/mFvoEwSfLqbcWwFsDjQebn9bzFe.jpg', '/hGGC9gKo7CFE3fW07RA587e5kol.jpg', 'Ajcdb4FAL7A'),
    (14161, 'Dr. Adrian Helmsley, part of a worldwide geophysical team investigating the effect on the earth of radiation from unprecedented solar storms, learns that the earth''s core is heating up. He warns U.S. President Thomas Wilson that the crust of the earth is becoming unstable and that without proper preparations for saving a fraction of the world''s population, the entire race is doomed. Meanwhile, writer Jackson Curtis stumbles on the same information. While the world''s leaders race to build "arks" to escape the impending cataclysm, Curtis struggles to find a way to save his family. Meanwhile, volcanic eruptions and earthquakes of unprecedented strength wreak havoc around the world.', 158, '/c2PkTPT5D9zB8SIm5wNlDAANEqM.jpg', '/4P71rDf6roxVskbvdcbNayVMpXd.jpg', 'ce0N3TEcFw0'),
    (14164, 'On his 18th birthday, Goku receives a mystical Dragonball as a gift from his grandfather. There are only six others like it in the whole world, and legend has it that whoever possesses all seven will be granted one perfect wish. When the arrival of a dark force triggers a tragedy, Goku and his companions are propelled into an epic quest to collect the seven Dragonballs and save the Earth from destruction.', 85, '/sunS9xhPnFNP5wlOWrvbpBteAB.jpg', '/5sXBW3XYwCA3FZxVoaIVI1hGOK6.jpg', 'T4_wHfz2qUA'),
    (14306, 'A newly married couple, in the process of starting a family, learn many of life''s important lessons from their trouble-loving retriever, Marley. Packed with plenty of laughs to lighten the load, the film explores the highs and lows of marriage, maturity and confronting one''s own mortality, as seen through the lens of family life with a dog.', 115, '/pnB6hjTKylb0Ve2nUWt16gzkErr.jpg', '/tVoWbAAfTDIhTeo78SbA2V6mv8E.jpg', 'KR5UBtAxseo'),
    (14411, 'The sailor of legend is framed by the goddess Eris for the theft of the Book of Peace, and must travel to her realm at the end of the world to retrieve it and save the life of his childhood friend Prince Proteus.', 86, '/yiW2L1fDiBT7AeWXrykhTNtPrr8.jpg', '/j8isWEPL3PmmVh8ap3jm75qVF4p.jpg', 'bRsdyOck9IY'),
    (14435, 'Ten years after a Valentine''s Day tragedy claimed the lives of five miners, Harry Warden returns for a vengeful massacre among teen sweethearts gearing up for another party.', 101, '/9biIVOMTdvv4aj4a5HClmrK5EHB.jpg', '/lhYlBOsmwoFlGQg9FmTsS7UMz1K.jpg', 'afxUFef1fNY'),
    (14560, 'When a shopping mall is taken over by a gang of organized crooks, it''s up to a mild-mannered security guard to save the day.', 91, '/A4zZv0Q1VKURFZFEl2vwjaE2q0g.jpg', '/nZwlezCansLTXU6w775zj9RAm4u.jpg', 'Ib4VZ1uvP6U'),
    (14574, 'When his family moves from their home in Berlin to a strange new house in Poland, young Bruno befriends Shmuel, a boy who lives on the other side of the fence where everyone seems to be wearing striped pajamas. Unaware of Shmuel''s fate as a Jewish prisoner or the role his own Nazi father plays in his imprisonment, Bruno embarks on a dangerous journey inside the camp''s walls.', 94, '/2C8QCXdMlojTxZjfBlINr4FWcb6.jpg', '/6aRuABAdhuuDypLGscM7HoEWHx4.jpg', 'uwysOfnX2Qg'),
    (14756, 'A semi-biographical account of Yip Man, the first martial arts master to teach the Chinese martial art of Wing Chun. The film focuses on events surrounding Ip that took place in the city of Foshan between the 1930s to 1940s during the Second Sino-Japanese War. Directed by Wilson Yip, the film stars Donnie Yen in the lead role, and features fight choreography by Sammo Hung.', 106, '/9bUIrDKnesNbBL1nAl1nt7gtocE.jpg', '/69QJSMkm5Hh0x9fLElZ8hjv5N4P.jpg', '3IUR6P5VwGo'),
    (14836, 'Wandering her rambling old house in her boring new town, 11-year-old Coraline discovers a hidden door to a strangely idealized version of her life. In order to stay in the fantasy, she must make a frighteningly real sacrifice.', 100, '/4jeFXQYytChdZYE9JYO7Un87IlW.jpg', '/hofnlIyF6bePkgQOpcuRWLvzf15.jpg', 'T6iQnnHNF50'),
    (14869, 'From the Egyptian desert to deep below the polar ice caps, the elite G.I. JOE team uses the latest in next-generation spy and military equipment to fight the corrupt arms dealer Destro and the growing threat of the mysterious Cobra organization to prevent them from plunging the world into chaos.', 118, '/mc9b25IAprHfsaOz0wTshOwGHcY.jpg', '/jE5wVBRCGQzjHjvFUcYwGS4x0ux.jpg', 'aFtzNHTB4C0'),
    (15092, 'Chelios faces a Chinese mobster who has stolen his nearly indestructible heart and replaced it with a battery-powered ticker that requires regular jolts of electricity to keep working.', 96, '/tzTC4EEvF0OPL63frEiogxL2T8M.jpg', '/oTbIfHSLNxi9ihV6SG4K6jZ2PvM.jpg', 't2koYVqwzT4'),
    (15121, 'In the years before World War II, a tomboyish postulant at an Austrian abbey is hired as a governess in the home of a widowed naval captain with seven children and brings a new love of life and music into the home.', 174, '/5qQTu2iGTiQ2UvyGp0beQAZ2rKx.jpg', '/ioQYjcRnU54ir5ltgyS7k53zw5x.jpg', 'Q7wZClqWm_o'),
    (15144, 'With the occasion all but overshadowed by her sister''s upcoming wedding, angst-ridden Samantha faces her 16th birthday with typical adolescent dread. Samantha pines for studly older boy Jake, but worries that her chastity will be a turnoff for the popular senior. Meanwhile, she must constantly rebuff the affections of nerdy Ted, who is unfortunately the only boy in school who seems to take an interest in her.', 93, '/A3WGCAgJF33kZdlxUdyXHYdbYax.jpg', '/6hgpBRaa1mWIrDGvkkf8BIusTZ4.jpg', 'FDQu9IiPbOM'),
    (15370, 'Young Haru rescues a cat from being run over, but soon learns it''s no ordinary feline; it happens to be the Prince of the Cats.', 75, '/pqyY7IEWkCWNZ7EuRStQaJITEta.jpg', '/uIF0sIkLTc7BHB0WZ6Cl0dDwd5z.jpg', 'yVnlvaxFQ6E'),
    (15373, 'Two salesmen trash a company truck on an energy drink-fueled bender. Upon their arrest, the court gives them a choice: do hard time or spend 150 service hours with a mentorship program. After one day with the kids, however, jail doesn''t look half bad.', 99, '/ki79dSjh6Rr51xrsz4dT04UGxSU.jpg', '/wEnMNW8rGX1RVhKY4Lj5sVDYSK8.jpg', 'wtFESEqa9fA'),
    (15472, 'Swedish thriller based on Stieg Larsson''s novel about a male journalist and a young female hacker. In the opening of the movie, Mikael Blomkvist, a middle-aged publisher for the magazine Millennium, loses a libel case brought by corrupt Swedish industrialist Hans-Erik Wennerström. Nevertheless, he is hired by Henrik Vanger in order to solve a cold case, the disappearance of Vanger''s niece', 152, '/r2pFUXKK20KD9RE3yybpQsNynRE.jpg', '/dPE25PbaeE6fCR2SQb4H4MeBmml.jpg', 'rIrjgFphVIc'),
    (15512, 'When Susan Murphy is unwittingly clobbered by a meteor full of outer space gunk on her wedding day, she mysteriously grows to 49-feet-11-inches. The military jumps into action and captures Susan, secreting her away to a covert government compound. She is renamed Ginormica and placed in confinement with a ragtag group of Monsters...', 94, '/hpHarddVj34j53T7NsoUGdKj4mP.jpg', '/fbxZeJEcyf76oEQIGmotlclwmiH.jpg', 'KrGiuIY-gDc'),
    (16320, 'A group of rebels travel the outskirts of space evading the sinister Alliance regime. Their lives of smuggling and cargo-running are interrupted by a psychic passenger who harbours a dangerous secret. Soon, the crew find themselves being pursued by an Alliance agent who will stop at nothing to find them.', 119, '/4sqUOaPFoP2W81mq1UYqZqf5WzA.jpg', '/3aGsZdB5ud6LmU9lppwTLh2fqH1.jpg', 'zybHB2V27G8'),
    (16859, 'A young witch, on her mandatory year of independent life, finds fitting into a new community difficult while she supports herself by running an air courier service.', 103, '/Aufa4YdZIv4AXpR9rznwVA5SEfd.jpg', '/ooGaNXI2OYszAajCFdIXLr73E1S.jpg', 'nu4OX6RKeLY'),
    (16866, 'When Earth astronaut Capt. Chuck Baker arrives on Planet 51 -- a world reminiscent of American suburbia circa 1950 -- he tries to avoid capture, recover his spaceship and make it home safely, all with the help of an empathetic little green being.', 91, '/x7Itcg3ZdExKwdKguy73WPEqosW.jpg', '/wk7R89u4l3AC3PRg7Abac2IJ5Ky.jpg', 'zaBAOVslv08'),
    (16869, 'In Nazi-occupied France during World War II, a group of Jewish-American soldiers known as "The Basterds" are chosen specifically to spread fear throughout the Third Reich by scalping and brutally killing Nazis. The Basterds, lead by Lt. Aldo Raine soon cross paths with a French-Jewish teenage girl who runs a movie theater in Paris which is targeted by the soldiers.', 153, '/aupnPtagH9JVBuMrGEanf4iqXEQ.jpg', '/bMJxwgLyD47CDQ6BFCT2AMMlID7.jpg', 'uSEDz-my7XQ'),
    (16871, 'After denying a woman the extension she needs to keep her home, loan officer Christine Brown sees her once-promising life take a startling turn for the worse. Christine is convinced she''s been cursed by a Gypsy, but her boyfriend is skeptical. Her only hope seems to lie in a psychic who claims he can help her lift the curse and keep her soul from being dragged straight to hell.', 99, '/fdyejM5Zd6dsa0YyWa02ZAKwQzK.jpg', '/3tvwsRSIDgwJuaGdh67XZ942UMy.jpg', 'PPOaxHqoYxo'),
    (16996, 'On the brink of a midlife crisis, 30-something Mike O''Donnell wishes he could have a "do-over." And that''s exactly what he gets when he wakes up one morning to find he''s 17 years old again. With his adult mind stuck inside the body of a teenager, Mike actually has the chance to reverse some decisions he wishes he''d never made. But maybe they weren''t so bad after all.', 102, '/yEcfFXEWpuXcfsR9nKESVCFneqV.jpg', '/8urrLPW6HFaIuRhJ1G3iQ7usEo7.jpg', '2wn6pAIRjjY'),
    (17431, 'With only three weeks left in his three-year contract, Sam Bell is eager to return to Earth. Stationed alone at a Moon-based facility with his computer assistant GERTY, an unexpected accident sets off a series of unsettling events that shake his isolation.', 97, '/35IU0Mq0zFsN1mYwDGts5mKc77n.jpg', '/mvUAo9ACgmLpS4Ofc2IwD4n7WCt.jpg', 'xV5udqNpP94'),
    (17578, 'Intrepid young reporter, Tintin, and his loyal dog, Snowy, are thrust into a world of high adventure when they discover a ship carrying an explosive secret. As Tintin is drawn into a centuries-old mystery, Ivan Ivanovitch Sakharine suspects him of stealing a priceless treasure. Tintin and Snowy, with the help of salty, cantankerous Captain Haddock and bumbling detectives, Thompson and Thomson, travel half the world, one step ahead of their enemies, as Tintin endeavors to find the Unicorn, a sunken ship that may hold a vast fortune, but also an ancient curse.', 107, '/fQZ3sLR1Fi63NMsNRbjm9q5qODJ.jpg', '/6mqgl2szMLRYj4lhlXOjju5Tpeo.jpg', 'LTnCE_SaU38'),
    (17609, 'A grieving couple retreats to their cabin ''Eden'' in the woods, hoping to repair their broken hearts and troubled marriage. But nature takes its course and things go from bad to worse.', 104, '/ge7zbYvpfsDP3luKi0iSpzOgncM.jpg', '/4ApgaV7wB3kfvxORnip0J7TNbvI.jpg', 'BO_wu_M2xjc'),
    (17654, 'Thirty years ago, aliens arrive on Earth. Not to conquer or give aid, but to find refuge from their dying planet. Separated from humans in a South African area called District 9, the aliens are managed by Multi-National United, which is unconcerned with the aliens'' welfare but will do anything to master their advanced technology. When a company field agent contracts a mysterious virus that begins to alter his DNA, there is only one place he can hide: District 9.', 112, '/tuGlQkqLxnodDSk6mp5c2wvxUEd.jpg', '/jhM3wgWUrrOkz9r4xwV5cV5RhI4.jpg', '_BjWEn5yvmw'),
    (17979, 'Miser Ebenezer Scrooge is awakened on Christmas Eve by spirits who reveal to him his own miserable existence, what opportunities he wasted in his youth, his current cruelties, and the dire fate that awaits him if he does not change his ways. Scrooge is faced with his own story of growing bitterness and meanness, and must decide what his own future will hold: death or redemption.', 96, '/xNwlAIdx1Ln28GRiQttUP9Gojy2.jpg', '/uocpNfrP0Vvnf2UxykXuIR1HNUd.jpg', 'HqK7ETwEE94'),
    (18239, 'Forks, Washington resident Bella Swan is reeling from the departure of her vampire love, Edward Cullen, and finds comfort in her friendship with Jacob Black, a werewolf. But before she knows it, she''s thrust into a centuries-old conflict, and her desire to be with Edward at any cost leads her to take greater and greater risks.', 131, '/k2qTooPlHffgNABNWxeJdGMglPK.jpg', '/dF2c20sRDgySZLaLS2OUerL07sz.jpg', 'q58iQSHhZGg'),
    (18240, 'When she learns she''s in danger of losing her visa status and being deported, overbearing book editor Margaret Tate forces her put-upon assistant, Andrew Paxton, to marry her.', 108, '/6stnAm1wSek8ZrislwK4xGTyCnt.jpg', '/ojgXOhVi9Yk8irDpRfDkIzdD1LK.jpg', 'jHraHCjK094'),
    (18360, 'Hapless museum night watchman Larry Daley must help his living, breathing exhibit friends out of a pickle now that they''ve been transferred to the archives at the Smithsonian Institution. Larry''s (mis)adventures this time include close encounters with Amelia Earhart, Abe Lincoln and Ivan the Terrible.', 105, '/l9yAQn6TyrA3gv5xZZkiMMoZsiw.jpg', '/zdhICEDUlBTQ43fQMa2KJt8fDFX.jpg', 'lPLY8O1y0qA'),
    (18405, 'When athletic teen Mari Collingwood opts to hang out with her friend Paige in town rather than spend an evening in with her parents vacationing at the family''s remote lake house, it marks the beginning of a night no one is going to forget.', 113, '/2Y35XCUS8U8vC8vs0HDEVkPu1BM.jpg', '/iiMR0RygNN3GTy8mjZOzXc5Q4jx.jpg', '2EZyJxabVck'),
    (18480, 'Flamboyantly gay Austrian television reporter Bruno stirs up trouble with unsuspecting guests and large crowds through brutally frank interviews and painfully hilarious public displays of homosexuality.', 83, '/wcUc7TYtsb72dHVb51sYaGIvQsr.jpg', '/vxeo16JiRxxpRYCteDPlmLIZwrb.jpg', 'pxyJ_ZQVhTI'),
    (18487, 'Armed men hijack a New York City subway train, holding the passengers hostage in return for a ransom, and turning an ordinary day''s work for dispatcher Walter Garber into a face-off with the mastermind behind the crime.', 106, '/baRXNiLDOpz3rH3VyjhayhgkWll.jpg', '/kBWPHSszi8jKLqW5tMaQV1bISB2.jpg', '6-8DF96kLtQ'),
    (18501, 'Mind-control technology has taken society by a storm, a multiplayer on-line game called "Slayers" allows players to control human prisoners in mass-scale. Simon controls Kable, the online champion of the game. Kable''s ultimate challenge becomes regaining his identity and independence by defeating the game''s mastermind.', 95, '/d5BTNmr87p7EvguTFW72vlL9l9H.jpg', '/zn4ayV8bFkGIvjH01DWmAjrNoQF.jpg', 'z88gktIxS-I'),
    (18533, 'A young man who was sentenced to 7 years in prison for robbing a post office ends up spending 30 years in solitary confinement. During this time, his own personality is supplanted by his alter ego, Charles Bronson.', 92, '/6diyyGIbBNiANsdIaCGtyv4IofR.jpg', '/uc8FwdCQi3eD7JIbyiZuzo5n6Jv.jpg', 'Ey5VRdEGhNI'),
    (18785, 'When three friends finally come to after a raucous night of bachelor-party revelry, they find a baby in the closet and a tiger in the bathroom. But they can''t seem to locate their best friend, Doug – who''s supposed to be tying the knot. Launching a frantic search for Doug, the trio perseveres through a nasty hangover to try to make it to the church on time.', 100, '/A0uS9rHR56FeBtpjVki16M5xxSW.jpg', '/iuRVt8tFiXDPGgzavhuSa3QHRxD.jpg', 'tlize92ffnY'),
    (18823, 'Born of a god but raised as a man, Perseus is helpless to save his family from Hades, vengeful god of the underworld. With nothing to lose, Perseus volunteers to lead a dangerous mission to defeat Hades before he can seize power from Zeus and unleash hell on earth. Battling unholy demons and fearsome beasts, Perseus and his warriors will only survive if Perseus accepts his power as a god, defies fate and creates his own destiny.', 106, '/6iHYLipwEyZUPNO8MM3l1yHDaFE.jpg', '/zRx1HyM1wF6wqEvxV12Ha2WrvlJ.jpg', 'TfyunOnMGqM'),
    (19404, 'Raj is a rich, carefree, happy-go-lucky second generation NRI. Simran is the daughter of Chaudhary Baldev Singh, who in spite of being an NRI is very strict about adherence to Indian values. Simran has left for India to be married to her childhood fiancé. Raj leaves for India with a mission at his hands, to claim his lady love under the noses of her whole family. Thus begins a saga.', 190, '/lfRkUr7DYdHldAqi3PwdQGBRBPM.jpg', '/7VDLEHli74eLsYLNcq9djn1Gw76.jpg', 'oIZ4U21DRlM'),
    (19901, 'In the year 2019, a plague has transformed almost every human into a vampire. Faced with a dwindling blood supply, the fractured dominant race plots their survival; meanwhile, a researcher works with a covert band of vampires on a way to save humankind.', 98, '/xFZH2l9UOyIclk2ZFWNHQ38B2RP.jpg', '/rNzLD5dTUoISDeo10qJDiUdwVNh.jpg', 'ADcmnVZQ9x8'),
    (19908, 'Columbus has made a habit of running from what scares him. Tallahassee doesn''t have fears. If he did, he''d kick their ever-living ass. In a world overrun by zombies, these two are perfectly evolved survivors. But now, they''re about to stare down the most terrifying prospect of all: each other.', 88, '/dUkAmAyPVqubSBNRjRqCgHggZcK.jpg', '/oihWVx3imvRKujnGmSDYhfG1gI5.jpg', '8m9EVP8X7N8'),
    (19912, 'A horrifying premonition saves a young man and his friends from death during a racetrack accident but terrible fates await them nonetheless.', 82, '/5vxXrr1MqGsT4NNeRITpfDnl4Rq.jpg', '/6j6YvWgmBSwqAEdGfwgWFZScDzY.jpg', 'x-MR-onocy0'),
    (19913, 'Tom, greeting-card writer and hopeless romantic, is caught completely off-guard when his girlfriend, Summer, suddenly dumps him. He reflects on their 500 days together to try to figure out where their love affair went sour, and in doing so, Tom rediscovers his true passions in life.', 95, '/qXAuQ9hF30sQRsXf40OfRVl0MJZ.jpg', '/1M2i4Mxd03elGOTmEkIvqrHfmyS.jpg', 'oBxR8cEt2xM'),
    (19994, 'Jennifer, a gorgeous, seductive cheerleader takes evil to a whole new level after she''s possessed by a sinister demon. Now it''s up to her best friend to stop Jennifer''s reign of terror before it''s too late.', 107, '/wrkjsGcFJxcQqR56kJUYAEKKg2T.jpg', '/rNvn89IcEJPqRKxIgwTAPXl9qjJ.jpg', 'C8azftM5puI'),
    (19995, 'In the 22nd century, a paraplegic Marine is dispatched to the moon Pandora on a unique mission, but becomes torn between following orders and protecting an alien civilization.', 162, '/gKY6q7SjCkAU6FqvqWybDYgUKIF.jpg', '/vL5LR6WdxWPjLPFRLe133jXWsh5.jpg', 'jm2sNLIPPvA'),
    (20048, 'In the glamorous world of New York City, Rebecca Bloomwood is a fun-loving girl who is really good at shopping – a little too good, perhaps. She dreams of working for her favorite fashion magazine, but can''t quite get her foot in the door – until ironically, she snags a job as an advice columnist for a financial magazine published by the same company.', 104, '/r17R9OIC0pKDqqsNore6atYLCVZ.jpg', '/vTMM4QXG6Jye7yffsOpz24oPNg1.jpg', 'd-jE5WJ7J28'),
    (20352, 'Determined to prove he''s the world''s greatest supervillain, Gru hatches an audacious plan to steal the Moon. To pull it off, he adopts three orphaned girls—Margo, Edith, and Agnes—intending to use them as pawns in his scheme. But the unexpected bond they form forces him to question the criminal life he''s always known.', 95, '/b1BT309QWjtFUlJPLmXmrcHOWEL.jpg', '/2XSeKDmIa2KxaiJy4J9e8FrIZhk.jpg', 'zzCZ1W_CUoI'),
    (20504, 'A post-apocalyptic tale, in which a lone man fights his way across America in order to protect a sacred book that holds the secrets to saving humankind.', 118, '/1H1y9ZiqNFaLgQiRDDZLA55PviW.jpg', '/aPrrrGtSjXbw8XnpzsVJgF0ioq3.jpg', 'vjUGsbGDNF8'),
    (20526, 'Sam Flynn, the tech-savvy and daring son of Kevin Flynn, investigates his father''s disappearance and is pulled into The Grid. With the help of a mysterious program named Quorra, Sam quests to stop evil dictator Clu from crossing into the real world.', 126, '/xcO8Uun0mfmE3N9CaiCy0tvjpiu.jpg', '/uUa6jgSr5BQpcBhhaz1PV1JhSa4.jpg', 'm9CTGwEZiPk'),
    (20662, 'When soldier Robin happens upon the dying Robert of Loxley, he promises to return the man''s sword to his family in Nottingham. There, he assumes Robert''s identity; romances his widow, Marion; and draws the ire of the town''s sheriff and King John''s henchman, Godfrey.', 140, '/9NS5QGOfck24yL3bZqWeW06PgPC.jpg', '/gxJnDz2W566PRdYKCaJrp1FpRRI.jpg', 'gnT3DRvQXXM'),
    (20766, 'A father and his son walk alone through burned America. Nothing moves in the ravaged landscape save the ash on the wind and water. It is cold enough to crack stones and, when the snow falls, it is gray. Their destination is the warmer south, although they don''t know what, if anything, awaits them there.', 111, '/qLaXnLzqleBWQtjvZ6JGVSaKoC3.jpg', '/6188iOmUAitGThYUjyx20fO4LJd.jpg', 'P8PyedKdTIY'),
    (20943, 'A romantically challenged morning show producer is reluctantly embroiled in a series of outrageous tests by her chauvinistic correspondent to prove his theories on relationships and help her find love. His clever ploys, however, lead to an unexpected result.', 96, '/2rq96Ihbqb1eU3TEBVtgFlqbeX7.jpg', '/75nC94NsD3PWGJ2JhQivnF6eBOM.jpg', 'DvsZtGxsvV0'),
    (21032, 'An outcast half-wolf risks his life to prevent a deadly epidemic from ravaging Nome, Alaska.', 78, '/dCVcdb5oxDizqFLz0F7TE60NoC9.jpg', '/hljMglukfpnfaNmUgMuORmL4OVW.jpg', 'GKH3bVyBDsg'),
    (21208, 'After losing their baby, a married couple adopt 9-year old Esther, who may not be as innocent as she seems.', 123, '/lCGpOgoTOGLtZnBiGY9HRg5Xnjd.jpg', '/hHlFspcHTLGFo8BwOSCsX9eHtbY.jpg', 'm5BSLNAKIZs'),
    (21407, 'Desperate to repay his debt to his ex-wife, an ex-con plots a heist at his new employer''s country home, unaware that a second criminal has also targeted the property, and rigged it with a series of deadly traps.', 90, '/qctYof0zQV34UARA22MKH3uUZZz.jpg', '/ywsta3d1MtV0MjQXs6uu0nnMjxi.jpg', 'EE1sL7QWL5c'),
    (22538, 'As bass guitarist for a garage-rock band, Scott Pilgrim has never had trouble getting a girlfriend; usually, the problem is getting rid of them. But when Ramona Flowers skates into his heart, he finds she has the most troublesome baggage of all: an army of ex-boyfriends who will stop at nothing to eliminate him from her list of suitors.', 113, '/g5IoYeudx9XBEfwNL0fHvSckLBz.jpg', '/6R9nT6m8wmzayV5XOQq3TRA6yZw.jpg', 'j66qP9Larlg'),
    (22794, 'Inventor Flint Lockwood creates a machine that makes clouds rain food, enabling the down-and-out citizens of Chewandswallow to feed themselves. But when the falling food reaches gargantuan proportions, Flint must scramble to avert disaster. Can he regain control of the machine and put an end to the wild weather before the town is destroyed?', 90, '/qhOhIKf7QEyQ5dMrRUqs5eTX1Oq.jpg', '/doNIj6jX27hhfcbD6GEb22ydLSF.jpg', 'BPH0ct2oXBg'),
    (22803, 'A frustrated man decides to take justice into his own hands after a plea bargain sets one of his family''s killers free. He targets not only the killer but also the district attorney and others involved in the deal.', 109, '/fcEXcip7v0O1ndV4VUdFqJSqbOg.jpg', '/nazre7z7MoUwAqimnrSlMlfLR5t.jpg', 'LX6kVRsdXW4'),
    (22804, 'Special Agent Strahm is dead, and Detective Hoffman has emerged as the unchallenged successor to Jigsaw''s legacy. However, when the FBI draws closer to Hoffman, he is forced to set a game into motion, and Jigsaw''s grand scheme is finally understood.', 90, '/aitPLjQ47emKTsYZ6Jdar1yw6X1.jpg', '/gqR59DjJGr6i8mxRD1VfOzCueTI.jpg', 'iadkoC3aIEs'),
    (22832, 'Ninja Assassin follows Raizo, one of the deadliest assassins in the world. Taken from the streets as a child, he was transformed into a trained killer by the Ozunu Clan, a secret society whose very existence is considered a myth. But haunted by the merciless execution of his friend by the Clan, Raizo breaks free from them and vanishes. Now he waits, preparing to exact his revenge.', 99, '/ipJ4mgqse6uoTRsDyU3TXmva1rt.jpg', '/44Yi72Ut3NchXewQzx814ViE2dy.jpg', 'H6tg0YwLJQQ'),
    (22881, 'The story of Michael Oher, a homeless and traumatized boy who became an All American football player and first round NFL draft pick with the help of a caring woman and her family.', 129, '/PhpAdRopu0sOWf0BY7vVtxrRD3.jpg', '/5P6hWD4zxAMntRuRnB4MmPLijNw.jpg', 'KA56LqFszYI'),
    (22894, 'When God loses faith in humankind, he sends his legion of angels to bring on the Apocalypse. Humanity''s only hope for survival lies in a group of strangers trapped in an out-of-the-way, desert diner with the Archangel Michael.', 100, '/ykocDqwg5PRUopnBVb1x1DWnEJF.jpg', '/7HzdWt7Rz3VeoHk5QEBEZaa0m1S.jpg', 'P6p01-in6-k'),
    (22947, 'Corporate downsizing expert Ryan Bingham spends his life in planes, airports, and hotels, but just as he’s about to reach a milestone of ten million frequent flyer miles, he meets a woman who causes him to rethink his transient life.', 110, '/useGH8nfwlaHK44IWEZdUYJOE2N.jpg', '/yTweHAwEokqAgZg1Io8e0zCJQvt.jpg', 'En0DYdjMVoY'),
    (22954, 'Newly elected President Nelson Mandela knows his nation remains racially and economically divided in the wake of apartheid. Believing he can bring his people together through the universal language of sport, Mandela rallies South Africa''s rugby union team as they make their historic run to the 1995 Rugby World Cup Championship match.', 134, '/runuhBAAX7PmdjGhqRKCyl4bh7z.jpg', '/vHwrJiFc74Lb8D0Trvdc0v04gRK.jpg', 'kKLDqC0rLIY'),
    (22970, 'Five friends set out for a weekend at a remote cabin in the woods, expecting nothing more than fun and relaxation. As night falls, they discover that something far more unsettling is at work and that nothing about their getaway is what it seems.', 95, '/zZZe5wn0udlhMtdlDjN4NB72R6e.jpg', '/wJffMiCnrszaNclKggGixYWB7D7.jpg', '7NiAWF7VIFY'),
    (22971, 'While Sergeant John Tyree is home on two weeks leave from Germany, he meets Savannah after he dives into the ocean to retrieve Savannah''s purse that had fallen off a pier. John eventually falls in love with Savannah, who promises to write to him until he returns from overseas.', 108, '/2lAPv2jQ5eh54l4EttA9wjDljED.jpg', '/bIzhIEW1zOmoGyx8qWQx4u3avWo.jpg', 'r0fq5dd0C60'),
    (23047, 'A 14th century Crusader returns with his comrade to a homeland devastated by the Black Plague. The Church commands the two knights to transport a witch to a remote abbey, where monks will perform a ritual in hopes of ending the pestilence.', 95, '/dNVqi8EsBtnnwfR6TgiWM51JOuS.jpg', '/9Lm94WVtV4HPxr7NWNlwkhLKSeH.jpg', 'yjCg3WCzKaU'),
    (23048, 'Four pals are stuck in a rut in adulthood: Adam has just been dumped, Lou is a hopeless party animal, Nick is a henpecked husband, and Jacob does nothing but play video games in his basement. But they get a chance to brighten their future by changing their past after a night of heavy drinking in a ski-resort hot tub results in their waking up in 1986.', 101, '/wjzbVXAes1acbh6k4OO5xVfy5.jpg', '/wwzuxanisjA7GhZOPYaWlfmlCKY.jpg', 'CZoViO13tq8'),
    (23168, 'A proficient group of thieves rob a bank and hold the manager hostage. Things begin to get complicated when one of the crew members falls in love with her.', 125, '/3NIzyXkfylsjflRKSz8Fts3lXzm.jpg', '/owAe5rRStnX7ibVAPmza3NCXjCy.jpg', 'uAjECYnrYks'),
    (23398, 'Pop sensations Alvin, Simon and Theodore end up in the care of Dave Seville''s twenty-something nephew Toby. The boys must put aside music super stardom to return to school, and are tasked with saving the school''s music program by winning the $25,000 prize in a battle of the bands. But the Chipmunks unexpectedly meet their match in three singing chipmunks known as The Chipettes - Brittany, Eleanor and Jeanette. Romantic and musical sparks are ignited when the Chipmunks and Chipettes square off.', 89, '/A2tgUeWadVJs1g6zOCZgKRs8uWC.jpg', '/3lf6YCItKcF3Wrrs7tp1PL0eyOT.jpg', 'HwVzCtRvcyY'),
    (23437, 'Teenagers Nancy, Quentin, Kris, Jesse and Dean are all neighbourhood friends who begin having the same dream of a horribly disfigured man who wears a tattered sweater and a glove made of knives. The man terrorises them in their dreams, and the only escape is to wake up. But when, one by one, they start dying violently, the friends realise that what happens in the dream world is real, and the only way to stay alive is to stay awake.', 95, '/nsmW28GcNabCUZfP5YtUEe8Li0f.jpg', '/Aur8dDhjDDJBuSDa9Y9GNrvlPI5.jpg', 'aNWZVIYGapI'),
    (23483, 'Dave Lizewski is an unnoticed high school student and comic book fan who one day decides to become a super-hero, even though he has no powers, training or meaningful reason to do so.', 118, '/iHMbrTHJwocsNvo5murCBw0CwTo.jpg', '/P4bGyJQF0shAcRku3I2perNUQR.jpg', 'RdBiTjy7AEI'),
    (23629, 'A young woman, institutionalized by her abusive stepfather, retreats into a vivid fantasy world where she envisions a plan to escape. Gathering a group of fellow inmates, she embarks on a quest to collect five mystical items, blurring the lines between reality and imagination.', 110, '/jtaUDnvIiHUd2ranDcjB5AbPx6o.jpg', '/cnWVCPDrX29kX7AwA9sfNlLx5vn.jpg', 'vJ0xYZ5mVMc'),
    (23631, 'After being set-up and betrayed by the man who hired him to assassinate a Texas Senator, an ex-Federale launches a brutal rampage of revenge against his former boss.', 105, '/dcPSm1rGEFdiEc7DaKz0t5kb66b.jpg', '/wbjoD8BN5W9VusuLJYdd7tWUxqh.jpg', 'GuDF9CEtFwE'),
    (23823, 'A group of people find themselves trapped in the backwoods of West Virginia, fighting for their lives against a group of vicious and horribly disfigured inbred cannibals.', 91, '/84s4LMWuGbm4xPWW5PSbHyQhh33.jpg', '/8568C7FeSsjmqLGuObSB0oB6kOU.jpg', 'yYAyDmOjZi0'),
    (23827, 'After a young, middle-class couple moves into what seems like a typical suburban house, they become increasingly disturbed by a presence that may or may not be demonic, but is certainly the most active in the middle of the night.', 86, '/tmclkEpjeo4Zu564gf3KrwIOuKw.jpg', '/wfCdJ0MD1hYJzlaHulolNw5pYtR.jpg', 'aXp6eO0ZrKM'),
    (24021, 'Bella once again finds herself surrounded by danger as Seattle is ravaged by a string of mysterious killings and a malicious vampire continues her quest for revenge. In the midst of it all, she is forced to choose between her love for Edward and her friendship with Jacob, knowing that her decision has the potential to ignite the ageless struggle between vampire and werewolf. With her graduation quickly approaching, Bella is confronted with the most important decision of her life.', 124, '/dK4Gi1UdMiHzHc7r7CZQG4IQ9Sr.jpg', '/yiWfT2Bl1Nul3Xie39Ahs3FqSjA.jpg', 'hZxJzhIPTTg'),
    (24150, 'Laurie Strode struggles to come to terms with her brother Michael''s deadly return to Haddonfield, Illinois. Meanwhile, Michael prepares for another reunion with his sister.', 105, '/vSHPM4LQDpWdQrD5KZWK6wNqSOD.jpg', '/mGHfOrb2MDOvgeFb4pQVeWH6adg.jpg', '66Xrr9KRSE0'),
    (24428, 'When an unexpected enemy emerges and threatens global safety and security, Nick Fury, director of the international peacekeeping agency known as S.H.I.E.L.D., finds himself in need of a team to pull the world back from the brink of disaster. Spanning the globe, a daring recruitment effort begins!', 143, '/RYMX2wcKCBAr24UyPD7xwmjaTn.jpg', '/9BBTo63ANSmhC4e6r62OJFuK2GL.jpg', 'hIR8Ar-Z4hw'),
    (25376, 'Hoping to put to rest years of unease concerning a past case, retired criminal investigator Benjamín begins writing a novel based on the unsolved mystery of a newlywed’s rape and murder. With the help of a former colleague, judge Irene, he attempts to make sense of the past.', 130, '/dkeAwfZzwL3WvToydE3CXiY80E0.jpg', '/zaANf06OtqDJr5saqp5ymEkDPsi.jpg', 'ZhEuUDO0YUQ'),
    (26389, 'James Reese has a good job as an ambassador''s aid in France, but his real passion is a side gig—working in a minor role in the CIA. He would love to be a full-fledged agent and can''t believe his luck when he lands an assignment with Charlie Wax. Trigger-happy Charlie soon has James crying for his desk job, but when he learns that the same guys they''re trying to catch are after him, James realises that Charlie may be his only hope of survival.', 92, '/poVoLKLxUqsTLSntA40Po2F78dZ.jpg', '/fra7Gk8xHPWaY4g8p6ue0o2yKOJ.jpg', '-jAbatBqqSc'),
    (26466, 'When Jess sets sail on a yacht with a group of friends, she cannot shake the feeling that there is something wrong.', 99, '/cRlMrbc4Iof7vN0ZqHwJnMBYBLi.jpg', '/9wNgQTtCuzVoKEX3SeCgGzHZ9vU.jpg', 'RFLvVYetuTE'),
    (27022, 'Balthazar Blake is a master sorcerer in modern-day Manhattan trying to defend the city from his arch-nemesis, Maxim Horvath. Balthazar can''t do it alone, so he recruits Dave Stutler, a seemingly average guy who demonstrates hidden potential, as his reluctant protégé. The sorcerer gives his unwilling accomplice a crash course in the art and science of magic, and together, these unlikely partners work to stop the forces of darkness.', 109, '/b5pIUsGll0418NyfNA5eYCI9aoK.jpg', '/mtrfLUfUoQunolDhmQy0GfbRclC.jpg', 'NDPPUJqFgks'),
    (27205, 'Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: "inception", the implantation of another person''s idea into a target''s subconscious.', 148, '/xlaY2zyzMfkhk0HSC5VUwzoZPU1.jpg', '/8ZTVqvKDQ8emSGUEMjsS4yHAwrp.jpg', 'JE9z-gy4De4'),
    (27576, 'As a CIA officer, Evelyn Salt swore an oath to duty, honor, and country. Her loyalty will be tested when a Russian defector accuses her of being a Russian sleeper spy. She goes on the run, using all her skills and years of experience as a covert operative to elude capture, protect her husband, and stay one step ahead of her colleagues at the CIA. Her efforts to prove her innocence only serve to cast doubt on her motives, as the hunt to uncover the truth behind her identity continues and the question remains: "Who is Salt?"', 100, '/ppXyhOe8UCEOrBRSYqE3SkHwrcR.jpg', '/xbQv34DdSkWJCLa3SGuLJPw1HYI.jpg', 'LbkQTB-OJsk'),
    (27578, 'Barney Ross leads a band of highly skilled mercenaries including knife enthusiast Lee Christmas, a martial arts expert Yin Yang, heavy weapons specialist Hale Caesar, demolitionist Toll Road, and a loose-cannon sniper Gunner Jensen. When the group is commissioned by the mysterious Mr. Church to assassinate the dictator of a small South American island, Barney and Lee visit the remote locale to scout out their opposition and discover the true nature of the conflict engulfing the city.', 103, '/j09ZkH6R4JWVylBcDai1laCmGw7.jpg', '/yBv9RxlWPXRCvjMFsrmB1pxwWo6.jpg', 'G_OQpXk8vAQ'),
    (27581, 'Unlike their heroic counterparts on the force, desk-bound NYPD detectives Gamble and Hoitz garner no headlines as they work day to day. When a seemingly minor case turns out to be a big deal, the two cops get the opportunity to finally prove to their comrades that they have the right stuff.', 107, '/wNEHNqo3MgHmj3BUiPSqqq5czcm.jpg', '/nHyri67CN6juBR6hmOefCn9oGf8.jpg', 'D6WOoUG1eNo'),
    (27582, 'Arthur Bishop is a ''mechanic'' - an elite assassin with a strict code requiring professional perfection and total detachment. One of an elite group of assassins, Bishop may be the best in the business - with a unique talent for cleanly eliminating targets. When Harry McKenna, his close friend and mentor, is murdered, Harry''s son comes to him with vengeance in his heart and a desire to learn Bishop''s trade, signaling the birth of a deadly partnership.', 93, '/k37axEHszFP9WOVvbozxF0r7X7g.jpg', '/dYb6kgvoGjUH59n2uB4eV9xqmKR.jpg', '39L8egLr518'),
    (28178, 'Professor Wilson discovers a lost Akita puppy on his way home. Despite objections from his wife, Hachi endears himself to the family and grows to be Parker''s loyal companion. As their bond grows deeper, a beautiful relationship unfolds.', 93, '/lsy3aEsEfYIHdLRk4dontZ4s85h.jpg', '/gOeSj4YzwxZb6FgcYPRK2hEzTdt.jpg', 'Y6U7mAnPtw4'),
    (28355, 'In her many years as a social worker, Emily Jenkins believes she has seen it all, until she meets 10-year-old Lilith and the girl''s cruel parents. Emily''s worst fears are confirmed when the parents try to harm the child, and so Emily assumes custody of Lilith while she looks for a foster family. However, Emily soon finds that dark forces surround the seemingly innocent girl, and the more she tries to protect Lilith, the more horrors she encounters.', 109, '/b16EjFeHd2AwoYXWUne7DA346pU.jpg', '/1i1Jfc9e15uRM3fGp7Detsjsapw.jpg', 'oTXOxLI0kVQ'),
    (30497, 'Five friends head out to rural Texas to visit the grave of a grandfather. On the way, they stumble across what appears to be a deserted house, only to discover something sinister within. Something armed with a chainsaw.', 83, '/mpgkRPH1GNkMCgdPk2OMyHzAks7.jpg', '/wvBx1Q1FcQE1BPLfBbgA3y9aaS1.jpg', 'iSxFeBdcqeE'),
    (31011, 'Nemo Nobody leads an ordinary existence with his wife and 3 children; one day, he wakes up as a mortal centenarian in the year 2092.', 141, '/qNkIONc4Rgmzo23ph7qWp9QfVnW.jpg', '/y9zcjxEilWr44c4vJbEaLTgE0Uw.jpg', '-GzJ1gA6Mg0'),
    (31867, 'In the future, medical technology has advanced to the point where people can buy artificial organs to extend their lives. But if they default on payments, an organization known as the Union sends agents to repossess the organs. Remy is one of the best agents in the business, but when he becomes the recipient of an artificial heart, he finds himself in the same dire straits as his many victims.', 111, '/1ZA5kEKuA6HgbyzZXXlyU4piNI.jpg', '/wQLcXBc0b4yNT542qxcZfb0KM40.jpg', 'pQ8BIqCbw3k'),
    (32657, 'Accident prone teenager, Percy discovers he''s actually a demi-God, the son of Poseidon, and he is needed when Zeus'' lightning is stolen. Percy must master his new found skills in order to prevent a war between the Gods that could devastate the entire world.', 118, '/brzpTyZ5bnM7s53C1KSk1TmrMO6.jpg', '/ugiV9SpJburMOPeIyjBJyAnO1So.jpg', 'R86InkfdboA'),
    (34544, 'A man who loves when a plan comes together, Col. Hannibal Smith leads a close-knit team of elite operatives and Iraq War veterans. Framed for a crime they didn''t commit, Smith and his men, Capt. H.M. ‘Howling Mad’ Murdock , Sgt. Bosco ‘B.A.’ Baracus, and Lt. Templeton ‘Faceman’ Peck, break out and go rogue, using their special talents to clear their names and find the perpetrator. Hot on their trail is Capt. Charissa Sosa, who was once involved with a member of Smith''s team and has sworn to capture them, no matter what it takes.', 117, '/bkAWEx5g5tvRPjtDQyvIZ7LRxQm.jpg', '/puAUfSiVrQO2DPKOobHFjqVcXPt.jpg', 'exyzEFrmLuM'),
    (34584, 'While hiding from bullies in his school''s attic, a young boy discovers the extraordinary land of Fantasia, through a magical book called The Neverending Story. The book tells the tale of Atreyu, a young warrior who, with the help of a luck dragon named Falkor, must save Fantasia from the destruction of The Nothing.', 101, '/ddYCa91iDXfJCxaqSYzwi2fjfnl.jpg', '/rKmOe5pb5a6P1HmQAzpRw20gORp.jpg', 'ToUgsvlsemo'),
    (34647, 'This psychedelic tour of life after death is seen entirely from the point of view of Oscar, a young American drug dealer and addict living in Tokyo with his prostitute sister, Linda. When Oscar is killed by police during a bust gone bad, his spirit journeys from the past -- where he sees his parents before their deaths -- to the present -- where he witnesses his own autopsy -- and then to the future, where he looks out for his sister from beyond the grave.', 161, '/krKnsfvSJM1PL40tLicRhVQ6kuG.jpg', '/2Mlw0JRNZHXLYxbeJ0LmiCCTiok.jpg', 'HkPMjoUqYXU'),
    (34851, 'A group of cold-blooded killers find themselves trapped on an alien planet to be hunted by extraterrestrial Predators.', 107, '/wdniP8NDaJIydi1hMxhpbJMUfr6.jpg', '/yVSgw4UyXWg0Edl7KMehdhhgIwL.jpg', 'N2jJOy8rzog'),
    (35791, 'In a world ravaged by a virus infection, turning its victims into the Undead, Alice continues on her journey to find survivors and lead them to safety. Her deadly battle with the Umbrella Corporation reaches new heights, but Alice gets some unexpected help from an old friend. A new lead that promises a safe haven from the Undead takes them to Los Angeles, but when they arrive the city is overrun by thousands of Undead - and Alice and her comrades are about to step into a deadly trap.', 97, '/qZHDnt8bnsD2cSJfIbjWbCkIq3G.jpg', '/8AvzydMm6vKICPOUuUG2KIW2on.jpg', 'SRRN6MvCdeg'),
    (36557, 'Le Chiffre, a banker to the world''s terrorists, is scheduled to participate in a high-stakes poker game in Montenegro, where he intends to use his winnings to establish his financial grip on the terrorist market. M sends Bond—on his maiden mission as a 00 Agent—to attend this game and prevent Le Chiffre from winning. With the help of Vesper Lynd and Felix Leiter, Bond enters the most important poker game in his already dangerous career.', 144, '/lMrxYKKhd4lqRzwUHAy5gcx9PSO.jpg', '/klJMCIblHLFwCuGjKz7tyOpekIC.jpg', 'p7D4U5YsZlM'),
    (36586, 'Blade forms an uneasy alliance with the vampire council in order to combat the Reapers, who are feeding on vampires.', 117, '/wAn6VYamKbnOtfyTZ6arVtkMzDv.jpg', '/86b0NGY1i0bt3ckhkcHxiCSMxk1.jpg', 'fcCQ7xk8zzM'),
    (36593, 'Frank Drebin is persuaded out of retirement to go undercover in a state prison. There he has to find out what top terrorist, Rocco, has planned for when he escapes. Adding to his problems, Frank''s wife, Jane, is desperate for a baby.', 83, '/p0AYsdgkudR9P5fNV5AjzbwQt8W.jpg', '/rZBc0S32bVNYOGJ5sKYsHhOwIT5.jpg', 'WQ3p19A1mbw'),
    (36647, 'The Daywalker known as "Blade" - a half-vampire, half-mortal man - becomes the protector of humanity against an underground army of vampires.', 121, '/oWT70TvbsmQaqyphCZpsnQR7R32.jpg', '/7NKfxJrQn053UJeLftlx4m4NTzo.jpg', 'O2Y3FFFIvRI'),
    (36648, 'For years, Blade has fought against the vampires in the cover of the night. But now, after falling into the crosshairs of the FBI, he is forced out into the daylight, where he is driven to join forces with a clan of human vampire hunters he never knew existed—The Nightstalkers. Together with Abigail and Hannibal, two deftly trained Nightstalkers, Blade follows a trail of blood to the ancient creature that is also hunting him—the original vampire, Dracula.', 113, '/6f7iXvPOnf83MaLB1JmPzUor1rr.jpg', '/63eAFgJtN6ZTyFFzlAOoZLhlYqc.jpg', 'qcHEDGs7eAY'),
    (36657, 'Two mutants, Rogue and Wolverine, come to a private academy for their kind whose resident superhero team, the X-Men, must oppose a terrorist organization with similar powers.', 104, '/bRDAc4GogyS9ci3ow7UnInOcriN.jpg', '/3QUVzbcNyfGe3ocWkYAT8emK8Co.jpg', 's4Wqw8tqgdM'),
    (36658, 'Professor Charles Xavier and his team of genetically gifted superheroes face a rising tide of anti-mutant sentiment led by Col. William Stryker. Storm, Wolverine and Jean Grey must join Magneto and Mystique to unhinge Stryker''s scheme to exterminate all mutants.', 133, '/bst4alFUXCxISwdRUKSMhhkrX1M.jpg', '/s8ftvFvafWWEhApISamHx32bx6h.jpg', 'yVzqz_zpP20'),
    (36668, 'When a cure is found to treat mutations, lines are drawn amongst the X-Men led by Professor Charles Xavier, and Magneto''s Brotherhood of Mutants.', 104, '/a2xicU8DpKtRizOHjQLC1JyCSRS.jpg', '/nLMXULCGLnzRxz11txPzPqbOHSz.jpg', 'X8ozc_dQprk'),
    (36669, 'James Bond is sent to investigate the connection between a North Korean terrorist and a diamond mogul, who is funding the development of an international space weapon.', 133, '/bZmGqOhMhaLn8AoFMvFDct4tbrL.jpg', '/orI5mvpksYIlhJqzdmeipys6sHQ.jpg', 'GTznf1x4khc'),
    (36955, 'A fearless, globe-trotting, terrorist-battling secret agent has his life turned upside down when he discovers his wife might be having an affair with a used car salesman while terrorists smuggle nuclear war heads into the United States.', 141, '/pqdvCBDThAOjlA0XBzbNm7GvwpU.jpg', '/jRZ3joUcg8YDCQYl4Tog5xhY6wk.jpg', 'Qw4hz62r-Kk'),
    (37056, 'An American girl on vacation in Italy finds an unanswered "letter to Juliet" -- one of thousands of missives left at the fictional lover''s Verona courtyard, which are typically answered by the "secretaries of Juliet" -- and she goes on a quest to find the lovers referenced in the letter.', 105, '/y9DdvY1IRNS2hWLq161hmP2gXn.jpg', '/2dCkaxVGvXnPfQC07cweMAT2n3F.jpg', '165tXUPESnk'),
    (37094, 'An ordinary man frustrated with the various flaws he sees in society begins to psychotically and violently lash out against them.', 113, '/7ujqyF96Zg3rfrsh9M0cEF0Yzqj.jpg', '/cS45swrlrTJijH1RblBLe8LlW2p.jpg', 'IBLKb8GSjW4'),
    (37135, 'Tarzan was a small orphan who was raised by an ape named Kala since he was a child. He believed that this was his family, but on an expedition Jane Porter is rescued by Tarzan. He then finds out that he''s human. Now Tarzan must make the decision as to which family he should belong to...', 88, '/bTvHlcqiOjGa3lFtbrTLTM3zasY.jpg', '/a0E1mbejev56Ii51hCnYUDj4tZS.jpg', 'JYOMf4SS2oA'),
    (37136, 'When the bumbling Lieutenant Frank Drebin investigates events following the shooting of his partner, he stumbles upon an attempt to assassinate Queen Elizabeth II.', 86, '/zT0mhZqZQJE1gSY5Eg9qcGP4NYo.jpg', '/7i3EPQ6ug0ip9OPqQXHEzaEs4An.jpg', 'PACTQutbow4'),
    (37165, 'In a picture-perfect seaside town, an insurance salesman begins to realize that his entire existence may be staged and observed by a vast unseen audience as part of a long-running real-time reality TV show.', 103, '/vuza0WqY239yBXOadKlGwJsZJFE.jpg', '/rmiG2uwcNoGFmBKMoa1pIcf514L.jpg', 'N1VlDVRiFrk'),
    (37247, 'A disillusioned college graduate finds himself torn between his older lover and her daughter.', 107, '/8XaDpF0COV1MLsDirJMnxmYc1Wp.jpg', '/lIY8ZTp6OJTAMfiorDGsPsJ5LT.jpg', 'KVNFaxJspMQ'),
    (37686, 'In late 1970s Ohio, a group of friends filming a homemade zombie movie witness a devastating train derailment. Soon after, their quiet town is gripped by unexplained disappearances, strange phenomena, and a growing sense of fear, as they uncover that something terrifying has been set loose.', 112, '/pUWIjaMMYJjeBm5bJyE3mIXdQ62.jpg', '/x6Dr9i6vhWICxs7hnX2BakcMtPd.jpg', 'US1E9i6BpUw'),
    (37707, 'Elsa and Clive, two rebellious young scientists, defy legal and ethical boundaries and forge ahead with a dangerous experiment: splicing together human and animal DNA to create a new organism. Named "Dren", the creature rapidly develops from a deformed female infant into a beautiful but dangerous winged human-chimera, who forges a bond with both of her creators — only to have that bond turn deadly.', 104, '/4oqaWnO3dKYAt3vZWAD4oLfOXOC.jpg', '/pjocJEjenTiJOi6o1vG8JArgt1h.jpg', 'NL3Glfcx4_I'),
    (37710, 'American tourist Frank meets mysterious British woman Elise on the train to Venice. Romance seems to bud, but there''s more to her than meets the eye.', 103, '/vVmek9VTnsfpQTIFWtL9h4HhOIP.jpg', '/j4xw4mD4GLEQRVRiu5CzU18FQXB.jpg', 'HgNiFN_gttA'),
    (37724, 'When Bond''s latest assignment goes gravely wrong, agents around the world are exposed and MI6 headquarters is attacked. While M faces challenges to her authority and position from Gareth Mallory, the new Chairman of the Intelligence and Security Committee, it''s up to Bond, aided only by field agent Eve, to locate the mastermind behind the attack.', 143, '/d0IVecFQvsGdSbnMAHqiYsNYaJT.jpg', '/wkA622CCN2X0uwpgqYEOnUYEDf5.jpg', 'YvV3g8hLlyU'),
    (37735, 'Olive, an average high school student, sees her below-the-radar existence turn around overnight once she decides to use the school''s gossip grapevine to advance her social standing. Now her classmates are turning against her and the school board is becoming concerned, including her favorite teacher and the distracted guidance counselor. With the support of her hilariously idiosyncratic parents and a little help from a long-time crush, Olive attempts to take on her notorious new identity and crush the rumor mill once and for all.', 93, '/v5f1qO6NJnxWgONgkYg21TW39DT.jpg', '/30rvmoEBqovm723agDJ3QddWXcY.jpg', 'KNbPnqyvItk'),
    (37799, 'In 2003, Harvard undergrad and computer programmer Mark Zuckerberg begins work on a new concept that eventually turns into the global social network known as Facebook. Six years later, Mark is one of the youngest billionaires ever, but his unprecedented success leads to both personal and legal complications when he ends up on the receiving end of two lawsuits, one involving his former friend.', 121, '/n0ybibhJtQ5icDqTp8eRytcIHJx.jpg', '/1PXwh3nJzgRkkYnqfWInJNypeL4.jpg', 'rBCNU0XT9GY'),
    (37834, 'A fugitive couple goes on a glamorous and sometimes deadly adventure where nothing and no one – even themselves – are what they seem. Amid shifting alliances and unexpected betrayals, they race across the globe, with their survival ultimately hinging on the battle of truth vs. trust.', 109, '/phhp52CZZJiGYmiOTp9ZBDkGHB3.jpg', '/k5mNW8qutywD3GhAuaq33qcQR2y.jpg', 'VDoNfrBlY3o'),
    (38050, 'A man glimpses the future Fate has planned for him – and chooses to fight for his own destiny. Battling the powerful Adjustment Bureau across, under and through the streets of New York, he risks his destined greatness to be with the only woman he''s ever loved.', 106, '/5ZzeR8iz1nEFLp94OBnbakLZawo.jpg', '/jE3deh9kkOKgl3MISqmpWpqLUjl.jpg', 'fSeWHl1PaKs'),
    (38055, 'After Megamind, a highly intelligent alien supervillain, defeats his long-time nemesis Metro Man, Megamind creates a new hero to fight, but must act to save the city when his "creation" becomes an even worse villain than he was.', 96, '/uZ9ytt3sPTx62XTfN56ILSuYWRe.jpg', '/irpJXGiVr539uuspcQcNdkhS2lq.jpg', 'bixkC-ZrH34'),
    (38117, 'A modern-day take on the "Beauty and the Beast" tale where a New York teen is transformed into a hideous monster in order to find true love.', 86, '/uSAXWZsSD0pE4HYVUiDgusnEyyl.jpg', '/hU4OdICqRXj3JFnSJsrR0SJejZy.jpg', '2jtZmQ_GM8Y'),
    (38142, 'Three moments in Takaki''s life: his relationship with Akari and their forced separation; his friendship with Kanae, who is secretly in love with him; the demands and disappointments of adulthood, an unhappy life in a cold city.', 63, '/dFipUR6W0y3PPkuVS8gjFd929m2.jpg', '/kTdmdPxl1gVPObxsffaOex6n3Vt.jpg', 'iPsu_sk-e7Q'),
    (38356, 'The Autobots continue to work for NEST, now no longer in secret. But after discovering a strange artifact during a mission in Chernobyl, it becomes apparent to Optimus Prime that the United States government has been less than forthright with them.', 154, '/28YlCLrFhONteYSs9hKjD1Km0Cj.jpg', '/h3js4rulxzKMOokM2oO5Kr0mBZU.jpg', 'XeUtb5L9iNE'),
    (38365, 'After their high school basketball coach passes away, five good friends and former teammates reunite for a Fourth of July holiday weekend.', 102, '/cQGM5k1NtU85n4TUlrOrwijSCcm.jpg', '/kARonxQpuSZdFraTKlCThWOBCtu.jpg', 'Nk1ERmswxsY'),
    (38575, '12-year-old Dre Parker could''ve been the most popular kid in Detroit, but his mother''s latest career move has landed him in China. Dre immediately falls for his classmate Mei Ying but the cultural differences make such a friendship impossible. Even worse, Dre''s feelings make him an enemy of the class bully, Cheng. With no friends in a strange land, Dre has nowhere to turn but maintenance man Mr. Han, who is a kung fu master. As Han teaches Dre that kung fu is not about punches and parries, but maturity and calm, Dre realizes that facing down the bullies will be the fight of his life.', 140, '/b1RBy3l297N0c7PHjlz35cClWju.jpg', '/tm4ld48rqEoV5tn0PDfvu3Q4Kna.jpg', 'XY8amUImEu0'),
    (38745, 'Travel writer Lemuel Gulliver takes an assignment in Bermuda, but ends up on the island of Liliput, where he towers over its tiny citizens.', 85, '/6NoEtuTwZ04luk5H2DpT5ivW7Mg.jpg', '/1EnX8qIJUYv6mG0Asub6Om8158z.jpg', 'aY6Gp36OIog'),
    (38757, 'Feisty teenager Rapunzel, who has long and magical hair, wants to go and see sky lanterns on her eighteenth birthday, but she''s bound to a tower by her overprotective mother. She strikes a deal with Flynn Rider, a charming wanted thief, and the duo set off on an action-packed escapade.', 100, '/ym7Kst6a4uodryxqbGOxmewF235.jpg', '/cWczNud8Y8i8ab0Z4bxos4myWYO.jpg', 'gsYKF8ecC8g'),
    (38810, 'Three teenagers are confined to an isolated country estate that could very well be on another planet. The trio spend their days listening to endless homemade tapes that teach them a whole new vocabulary. Any word that comes from beyond their family abode is instantly assigned a new meaning. Hence ''the sea'' refers to a large armchair and ''zombies'' are little yellow flowers. Having invented a brother whom they claim to have ostracized for his disobedience, the uber-controlling parents terrorize their offspring into submission.', 98, '/7nLuUGlH12cegPfR84QX4xIIH9k.jpg', '/hiSC94dJJbF4YxgUpMFrQYTKdaT.jpg', 'YJe4eZ9l5KY'),
    (39254, 'Charlie Kenton is a washed-up fighter who retired from the ring when robots took over the sport. After his robot is trashed, he reluctantly teams up with his estranged son to rebuild and train an unlikely contender.', 127, '/4GIeI5K5YdDUkR3mNQBoScpSFEf.jpg', '/pjlxrd646cBYznHoPBWTzz6FujX.jpg', 'obYuPJH2oTE'),
    (39513, 'For the past 60 years, a space-traveling smart-ass named Paul has been locked up in a top-secret military base, advising world leaders about his kind. But when he worries he’s outlived his usefulness and the dissection table is drawing uncomfortably close, Paul escapes on the first RV that passes by his compound in Area 51. Fortunately, it contains the two earthlings who are most likely to rescue and harbor an alien on the run.', 104, '/dKhexH8nS08lVlSmwSs00cHFxbY.jpg', '/kl3rMfydlxyLDsZidSUCEWm8K0M.jpg', '16Jfld1-kOI'),
    (39514, 'After surviving an assault from a squad of hit men, retired CIA black ops agent Frank Moses reassembles his old team for an all-out war. Frank reunites with old Joe, crazy Marvin and wily Victoria to uncover a massive conspiracy that threatens their lives. Only their expert training will allow them to survive a near-impossible mission -- breaking into CIA headquarters.', 111, '/8eeK3OB5PeSRQD7BpZcGZKkehG.jpg', '/5tqBeCUaNHptScH3rBixjE5z2NV.jpg', 'JlFkRY9xLmc'),
    (39538, 'As an epidemic of a lethal airborne virus - that kills within days - rapidly grows, the worldwide medical community races to find a cure and control the panic that spreads faster than the virus itself.', 106, '/2xYil8iO3uaNncmTTMxKbwV3MP.jpg', '/asDdBAvTneGs0k18Blt0oBQbsh8.jpg', '4sYSyuuLk5g'),
    (41154, 'Agents J and K are back...in time. J has seen some inexplicable things in his 15 years with the Men in Black, but nothing, not even aliens, perplexes him as much as his wry, reticent partner. But when K''s life and the fate of the planet are put at stake, Agent J will have to travel back in time to put things right. J discovers that there are secrets to the universe that K never told him - secrets that will reveal themselves as he teams up with the young Agent K to save his partner, the agency, and the future of humankind.', 106, '/90DdoEStzeObs96fsYf4GG544iN.jpg', '/5AhpUb8CAP0jZ4Wrn7AsRUYjZxB.jpg', 'aoyV49FfjOU'),
    (41216, 'When a young owl is abducted by an evil Owl army, he must escape with new-found friends and seek the legendary Guardians to stop the menace.', 97, '/qweKCtPdnIP2uGp1PgWZyCV7gzj.jpg', '/4Zh7sDqopYZrGaI3FItQ3KL3k0g.jpg', 'I_vJ0jS3i3o'),
    (41439, 'As a deadly battle rages over Jigsaw''s brutal legacy, a group of Jigsaw survivors gathers to seek the support of self-help guru and fellow survivor Bobby Dagen, a man whose own dark secrets unleash a new wave of terror.', 90, '/qHCZ6LjtmqWDfXXN28TlIC9OppK.jpg', '/qXTSZkk8mQHnZjuRjW9fc2Ax5vj.jpg', 'A1PxwwdEXao'),
    (41446, 'Fifteen years after the original Woodsboro murders, Sidney Prescott returns home to promote her new book about surviving trauma, only for a new Ghostface killer to emerge, targeting a new group of teens.', 111, '/3cf8p2qw9qnsaaFWc64AG6U05eT.jpg', '/c5EmNhLQsTTKAyUHULnKYQjlloz.jpg', 'vvV1WDueIC0'),
    (41513, 'When the evil wizard Gargamel chases the tiny blue Smurfs out of their village, they tumble from their magical world and into ours -- in fact, smack dab in the middle of Central Park. Just three apples high and stuck in the Big Apple, the Smurfs must find a way to get back to their village before Gargamel tracks them down.', 103, '/vRhnslP2gW0QDym7BsMeSuioUfK.jpg', '/iYLimHUF0C0R61v1ofg79SUIja9.jpg', 'vc0dljW2ZaU'),
    (41733, 'Peter Highman must scramble across the US in five days to be present for the birth of his first child. He gets off to a bad start when his wallet and luggage are stolen, and put on the ''no-fly'' list. Peter embarks on a terrifying journey when he accepts a ride from an actor.', 95, '/sBxWS09pOOyXZ0dcnqfqqCAQGan.jpg', '/naV4PO7ftzNThYKGX44F8vRY2z3.jpg', 'hEtu68oxBfc'),
    (43074, 'Following a ghost invasion of Manhattan, paranormal enthusiasts Erin Gilbert and Abby Yates, nuclear engineer Jillian Holtzmann, and subway worker Patty Tolan band together to stop the otherworldly threat.', 117, '/wJmWliwXIgZOCCVOcGRBhce7xPS.jpg', '/3KDHaahgXlUhmpXzoRZrLc7QSBM.jpg', 'D3i2CqernTE'),
    (43347, 'Maggie is an alluring free spirit who won''t let anyone – or anything – tie her down. But she meets her match in Jamie, whose relentless and nearly infallible charm serves him well with the ladies and the cutthroat world of pharmaceutical sales. Maggie and Jamie''s evolving relationship takes them both by surprise, as they find themselves under the influence of the ultimate drug: love.', 112, '/wZLM2uKJRYNchLmiCIjosX0rXy8.jpg', '/ca4DAKJ1stCFeU6wq16hxmTAba.jpg', 'h6w7Dh-QxzY'),
    (43593, 'Each year the population of sleepy Lake Victoria, Arizona explodes from 5,000 to 50,000 residents for the annual Spring Break celebration. But then, an earthquake opens an underwater chasm, releasing an enormous swarm of ancient Piranha that have been dormant for thousands of years, now with a taste for human flesh. This year, there''s something more to worry about than the usual hangovers and complaints from locals, a new type of terror is about to be cut loose on Lake Victoria.', 88, '/o45mRbIDykJld6WktTuVtWm7s6E.jpg', '/AF0PiDItegyUtlBGDMGlSQbtro.jpg', 'AImr8U_7CX4'),
    (43949, 'When Juli meets Bryce in the second grade, she knows it''s true love. After spending six years trying to convince Bryce the same, she''s ready to give up - until he starts to reconsider.', 89, '/6zDYFigohwncqFL00MKbFV01dWb.jpg', '/wdOGA0LC1NiWgAX1OaiKtNA247i.jpg', 'shN4dt583Y0'),
    (44048, 'When a massive, unmanned locomotive roars out of control, the threat is more ominous than just a derailment. The train is laden with toxic chemicals, and an accident would decimate human life and cause an environmental disaster. The only hope of bringing the train to a safe stop is in the hands of veteran engineer Frank Barnes, and young conductor Will Colson, who must risk their lives to save those in the runaway''s path. Inspired by true events.', 98, '/zKvHwL0GqLOear8rTnUPSTRYY0r.jpg', '/5JdyKWEzY6MQmJcIEdhbP4HozzZ.jpg', 'l__gGyq21U8'),
    (44115, 'The true story of mountain climber Aron Ralston''s remarkable adventure to save himself after a fallen boulder crashes on his arm and traps him in an isolated canyon in Utah.', 94, '/h0RMdn0rfl9l5hWXz3tUh6QVkhi.jpg', '/viBWzktrBmhzRw4ehmUIrrN4C0z.jpg', 'OlhLOWTnVoQ'),
    (44214, 'A committed dancer struggles to maintain her sanity after winning the lead role in a production of Tchaikovsky''s "Swan Lake."', 108, '/viWheBd44bouiLCHgNMvahLThqx.jpg', '/eDLp4uFdqP1gpy9oMrutwH6Q64I.jpg', '2Pxc_5f27Kg'),
    (44264, 'Following the murder of her father by a hired hand, a 14-year-old farm girl sets out to capture the killer. To aid her, she hires the toughest U.S. Marshal she can find—a man with ''true grit''—Reuben J. ''Rooster'' Cogburn.', 110, '/tCrB8pcjadZjsDk7rleGJaIv78k.jpg', '/5dwlH8Krm2bsuc2Pubw2cBb03g5.jpg', 'Q5fEgKj9QNs'),
    (44826, 'Orphaned and alone except for an uncle, Hugo Cabret lives in the walls of a train station in 1930s Paris. Hugo''s job is to oil and maintain the station''s clocks, but to him, his more important task is to protect a broken automaton and notebook left to him by his late father. Accompanied by the goddaughter of an embittered toy merchant, Hugo embarks on a quest to solve the mystery of the automaton and find a place he can call home.', 126, '/1dxRq3o3l3bVWNRvvSb7rRf68qp.jpg', '/Aj81Gu3u1a64qXFOLDuF5gdxyy0.jpg', 'nZGyAx7YyYM'),
    (44833, 'When mankind beams a radio signal into space, a reply comes from ‘Planet G’, in the form of several alien crafts that splash down in the waters off Hawaii. Lieutenant Alex Hopper is a weapons officer assigned to the USS John Paul Jones, part of an international naval coalition which becomes the world''s last hope for survival as they engage the hostile alien force of unimaginable strength. While taking on the invaders, Hopper must also try to live up to the potential that his brother, and his fiancée''s father—an Admiral—expect of him.', 131, '/9b0Im7SfedHiajTwzSL9zGyBI7M.jpg', '/85PMh0cKywekAJYDnRXfezYAmEc.jpg', 'wvXKvbIAq2k'),
    (44896, 'When Rango, a lost family pet, accidentally winds up in the gritty, gun-slinging Western town of Dirt, the theater-loving lizard suddenly finds himself the newly appointed sheriff. Welcomed as the last hope the town has been waiting for, Rango is forced to play his new role to the hilt and uncover the truth behind a looming water crisis—before his act catches up with him.', 107, '/A5MP1guV8pbruieG0tnpPIbaJtt.jpg', '/mOtKQlXdL5J4lwqcSFlkZmgmFeZ.jpg', '_gQys92pTqM'),
    (44912, 'For centuries, a small but powerful force of warriors called the Green Lantern Corps has sworn to keep intergalactic order. Each Green Lantern wears a ring that grants him superpowers. But when a new enemy called Parallax threatens to destroy the balance of power in the Universe, their fate and the fate of Earth lie in the hands of the first human ever recruited.', 114, '/fj21HwUprqjjwTdkKC1XZurRSpV.jpg', '/tS3ByIQR6V61DaWhEIFbLSuLK5Q.jpg', 'ojYMekJgqJU'),
    (44943, 'When once distant UFOs become a terrifying threat and an alien invasion force begins attacking Earths major costal and riverside cities, a U.S Marine staff sergeant and his team are sent into battle only to find they must take it upon themselves to defeat an unknown enemy and protect what remains of Los Angeles.', 116, '/jloyGeVYZSxM9zsLFvVOWuj2ey4.jpg', '/buspsNeIGOAznaYQsnGDmQLZakW.jpg', 'Yt7ofokzn04'),
    (45269, 'The King''s Speech tells the story of the man who became King George VI, the father of Queen Elizabeth II. After his brother abdicates, George (''Bertie'') reluctantly assumes the throne. Plagued by a dreaded stutter and considered unfit to be king, Bertie engages the help of an unorthodox speech therapist named Lionel Logue. Through a set of unexpected techniques, and as a result of an unlikely friendship, Bertie is able to find his voice and boldly lead the country into war.', 118, '/pVNKXVQFukBaCz6ML7GH3kiPlQP.jpg', '/m4MGxxEgAMqIX9x8MCg5pYeyYjU.jpg', 'HXMqX9s67kY'),
    (45317, 'Boxer "Irish" Micky Ward''s unlikely road to the world light welterweight title. His Rocky-like rise was shepherded by half-brother Dicky, a boxer-turned-trainer who rebounded in life after nearly being KO''d by drugs and crime.', 116, '/xfsFerGhO1h6rLk8vwLgMyQ8WVJ.jpg', '/2kqmEQZqime0G3ULgrKtAq3WVdH.jpg', 'LRIZ4mCi5Ps'),
    (45612, 'When decorated soldier Captain Colter Stevens wakes up in the body of an unknown man, he discovers he''s part of a mission to find the bomber of a Chicago commuter train.', 93, '/nTr0lvAzeQmUjgSgDEHTJpnrxTz.jpg', '/mDb4uku4zEElsITXDpbir4fR0HW.jpg', '0dafmG_c8kc'),
    (46195, 'Captured by smugglers when he was just a hatchling, a macaw named Blu never learned to fly and lives a happily domesticated life in Minnesota with his human friend, Linda. Blu is thought to be the last of his kind, but when word comes that Jewel, a lone female, lives in Rio de Janeiro, Blu and Linda go to meet her. Animal smugglers kidnap Blu and Jewel, but the pair soon escape and begin a perilous adventure back to freedom -- and Linda.', 96, '/4nJxhUknKV8Gqdhov8pU1YWDYfb.jpg', '/3vxlXdwBKztOJdgiZ2Qwasl9FY4.jpg', 'P1GRO31ve5Q'),
    (46529, 'A teenage fugitive with an incredible secret races to stay one step ahead of the mysterious forces seeking destroy him. With three dead and one on the run, the race to find the elusive Number Four begins. Outwardly normal teen John Smith never gets too comfortable in the same identity, and along with his guardian, Henri, he is constantly moving from town to town. With each passing day, John gains a stronger grasp on his extraordinary new powers, and his bond to the beings that share his fantastic fate grows stronger.', 109, '/tPxc7Bb5ZTSFMlCjYxzVWOVy8gD.jpg', '/lR8eHumEoL8FkszpDvbEUZRXVt5.jpg', 'XR2QSlHpKg4'),
    (46705, 'Dean and Cindy live a quiet life in a modest neighborhood. They appear to have the world at their feet at the outset of the relationship. However, his lack of ambition and her retreat into self-absorption cause potentially irreversible cracks in their marriage.', 112, '/dc8BdKnDY5Iy28KzUGtHIXuqqFK.jpg', '/fAqpfILTPsaKpAzoAvkXf5glgSo.jpg', 'aw0NChcdQfQ'),
    (46738, 'A mother''s last wishes send twins Jeanne and Simon on a journey to Middle East in search of their tangled roots. Adapted from Wajdi Mouawad''s acclaimed play, Incendies tells the powerful and moving tale of two young adults'' voyage to the core of deep-rooted hatred, never-ending wars and enduring love.', 131, '/yH6DAQVgbyj72S66gN4WWVoTjuf.jpg', '/f3ATwil5vmUeTsogBaMEKbBYBth.jpg', 'XJ69WnwvZhE'),
    (46838, 'Two hillbillies are suspected of being killers by a group of paranoid college kids camping near the duo''s West Virginian cabin. As the body count climbs, so does the fear and confusion as the college kids try to seek revenge against the pair.', 89, '/8shwLEDzajJGSfLgbpac8x8xn1U.jpg', '/2rDC2CEZktwMlGCWSasFRZQD2xD.jpg', 'NdNpFoWrBDQ'),
    (47327, 'Milton is a hardened felon who has broken out of Hell, intent on finding the vicious cult who brutally murdered his daughter and kidnapped her baby. He joins forces with a sexy, tough-as-nails waitress, who''s also seeking redemption of her own. Caught in a deadly race against time, Milton has three days to avoid capture, avenge his daughter''s death, and save her baby before she''s mercilessly sacrificed by the cult.', 104, '/nx2pChi41Xv4dsXsfSG3gnKcWaY.jpg', '/63QcB4IQpvoyROk9dLgcbHo9LYT.jpg', 'jouaan70m4c'),
    (47933, 'We always knew they were coming back. Using recovered alien technology, the nations of Earth have collaborated on an immense defense program to protect the planet. But nothing can prepare us for the aliens’ advanced and unprecedented force. Only the ingenuity of a few brave men and women can bring our world back from the brink of extinction.', 120, '/9S50foUIYGwiNPWOxi1WJF6IPwI.jpg', '/auT0H5fFUnPKjHNj0OkQMkxdbl2.jpg', 'FrS7PThzR8s'),
    (47964, 'Iconoclastic, take-no-prisoners cop John McClane, finds himself for the first time on foreign soil after traveling to Moscow to help his wayward son Jack - unaware that Jack is really a highly-trained CIA operative out to stop a nuclear weapons heist. With the Russian underworld in pursuit, and battling a countdown to war, the two McClanes discover that their opposing methods make them unstoppable heroes.', 98, '/qJ0csDXAVFMsNn0cRcjy6W6PxAK.jpg', '/wFUkS5cnMf3I8ysIPWzIXpTsuR7.jpg', 'mXTImBrEKUc'),
    (47971, 'Xander Cage is left for dead after an incident, though he secretly returns to action for a new, tough assignment with his handler Augustus Gibbons.', 107, '/hba8zREJpP1AYhaXgb2oJLQeO0K.jpg', '/cFcXilLbI7yjPIYB58AZiOyUnoh.jpg', '-ziu6JzJTZ0'),
    (48138, 'A man awakens from a coma, only to discover that someone has taken on his identity and that no one, (not even his wife), believes him. With the help of a young woman, he sets out to prove who he is.', 113, '/zCuenUdbo0GQzqtj64a2Y8gcbiK.jpg', '/f2d419xzKDbtVpToJorTxlKMvgQ.jpg', 'vSXUgkCjdBM'),
    (49013, 'Star race car Lightning McQueen and his pal Mater head overseas to compete in the World Grand Prix race. But the road to the championship becomes rocky as Mater gets caught up in an intriguing adventure of his own: international espionage.', 106, '/okIz1HyxeVOMzYwwHUjH2pHi74I.jpg', '/robYRZk9LxJTwD7GlZCginji5k.jpg', 'lg5hj2c5Nkk'),
    (49017, 'Vlad Tepes is a great hero, but when he learns the Sultan is preparing for battle and needs to form an army of 1,000 boys, he vows to find a way to protect his family. Vlad turns to dark forces in order to get the power to destroy his enemies and agrees to go from hero to monster as he''s turned into the mythological vampire, Dracula.', 92, '/m5h3NtZ2ZfryIHl1MvatmANvIqQ.jpg', '/oa0bHsnrD96miW3Yx10HWb211Sj.jpg', 'BRhjwiglXvQ'),
    (49018, 'A family discovers that dark spirits have invaded their home after their son inexplicably falls into an endless sleep. When they reach out to a professional for help, they learn things are a lot more personal than they thought.', 102, '/tmlDFIUpGRKiuWm9Ixc6CYDk4y0.jpg', '/aXOUc4dkzp9wmJG5lC2iAE6VUdt.jpg', '62rpZcMYa0A'),
    (49026, 'Following the death of District Attorney Harvey Dent, Batman assumes responsibility for Dent''s crimes to protect the late attorney''s reputation and is subsequently hunted by the Gotham City Police Department. Eight years later, Batman encounters the mysterious Selina Kyle and the villainous Bane, a new terrorist leader who overwhelms Gotham''s finest. The Dark Knight resurfaces to protect a city that has branded him an enemy.', 165, '/hr0L2aueqlP2BYUblTTjmtn0hw4.jpg', '/c3OHQncTAnKFhdOTX7D3LTW6son.jpg', 'GAjBzu8ggi0'),
    (49040, 'New CIA operative Aaron Cross experiences life-or-death stakes that have been triggered by the previous actions of Jason Bourne.', 135, '/1aExL5DTGHj25ZfIC3dDwS84RWi.jpg', '/akNBILfG0vh7WhuzjA1bXfrgpYI.jpg', '43WTCO8-C4w'),
    (49046, 'Paul Baumer and his friends Albert and Muller, egged on by romantic dreams of heroism, voluntarily enlist in the German army. Full of excitement and patriotic fervour, the boys enthusiastically march into a war they believe in. But once on the Western Front, they discover the soul-destroying horror of World War I.', 147, '/2IRjbi9cADuDMKmHdLK7LaqQDKA.jpg', '/xBwtP27cx8WfjHJVFkpuV6F1RES.jpg', 'hf8EYbVxtCY'),
    (49047, 'Dr Ryan Stone, an engineer on her first space mission, and Matt Kowalski, an astronaut on his final expedition, have to survive in space after they are hit by debris while spacewalking.', 91, '/kZ2nZw8D681aphje8NJi8EfbL1U.jpg', '/a2n6bKD7qhCPCAEALgsAhWOAQcc.jpg', 'OiTiKOy59o4'),
    (49049, 'In the future, America is a dystopian wasteland. The latest scourge is Ma-Ma, a prostitute-turned-drug pusher with a dangerous new drug and aims to take over the city. The only possibility of stopping her is an elite group of urban police called Judges, who combine the duties of judge, jury and executioner to deliver a brutal brand of swift justice. But even the top-ranking Judge, Dredd, discovers that taking down Ma-Ma isn’t as easy as it seems in this explosive adaptation of the hugely popular comic series.', 96, '/wLx65gtGVnUFCxceHWGszcruCZj.jpg', '/jUqDBi02CDjqrroC3Zl8hroBbSr.jpg', '3Sp-2FvUNv0'),
    (49051, 'Bilbo Baggins, a hobbit enjoying his quiet life, is swept into an epic quest by Gandalf the Grey and thirteen dwarves who seek to reclaim their mountain home from Smaug, the dragon.', 169, '/yHA9Fc37VmpUA5UncTxxo3rTGVA.jpg', '/xyXmtuvsoM5J3yNad0nvcetpBdY.jpg', 'CXqZK-nbZ74'),
    (49444, 'Po is finally living the dream as the Dragon Warrior—until a shadow from his past comes roaring back. When the ruthless peacock Lord Shen unleashes a devastating new weapon used to wipe out kung fu masters across the land, Po and the Furious Five race across China to put an end to his plans. But if Po is to have any hope of stopping him, he must first confront the truth of his origins—and find inner peace before his past tears him apart.', 91, '/mtqqD00vB4PGRt20gWtGqFhrkd0.jpg', '/iBUIS2duNa9aDfLgRr8thsUPRs0.jpg', 'FQ63rqSRrEI'),
    (49519, 'The prehistoric Croods family live in a particularly dangerous moment in time. Patriarch Grug, his mate Ugga, teenage daughter Eep, son Thunk, and feisty Gran gather food by day and huddle together in a cave at night. When a more evolved caveman named Guy arrives on the scene, Grug is distrustful, but it soon becomes apparent that Guy is correct about the impending destruction of their world.', 99, '/27zvjVOtOi5ped1HSlJKNsKXkFH.jpg', '/wFN8llYh215M8i2fqWAcPV8CSyL.jpg', '4fVCKy69zUY'),
    (49520, 'Lifelong friends Dave and Mitch are envious of the other''s life. Mitch thinks Dave has it all: a beautiful, loving family and a high-paying job at a prestigious law firm. But Dave thinks Mitch’s stress-free playboy life without obligation or consequence is the real dream come true. One fateful drunken night, they both admit that they wish they had the other’s life while peeing in a fountain when lightning strikes. The next morning, they wake up, hungover, in each other’s bodies! With time not on their side, Mitch and Dave comically struggle to avoid completely destroying each other’s lives before they can find a way to get their old ones back.', 112, '/iV6ARQZyGpjygtzFMdWH9U1Lj9x.jpg', '/mMxbSeNEkiddadwyuHrU21621U.jpg', 'p3W7SIrMMaQ'),
    (49521, 'A young boy learns that he has extraordinary powers and is not of this earth. As a young man, he journeys to discover where he came from and what he was sent here to do. But the hero in him must emerge if he is to save the world from annihilation and become the symbol of hope for all mankind.', 143, '/8GFtkImmK0K1VaUChR0n9O61CFU.jpg', '/69EFgWWPFWbRNHmQgYdSnyJ94Ge.jpg', 'vGrBV1C4hgo'),
    (49524, 'A recently slain cop joins a team of undead police officers working for the Rest in Peace Department and tries to find the man who murdered him.', 96, '/rS0kByPD4YF8pQ85KjzMdGiu7Xf.jpg', '/6KJcFFE1iBPC0Xj0iPCcmMvS5WK.jpg', 'nt59JjtWFSU'),
    (49529, 'John Carter is a war-weary, former military captain who''s inexplicably transported to the mysterious and exotic planet of Barsoom (Mars) and reluctantly becomes embroiled in an epic conflict. It''s a world on the brink of collapse, and Carter rediscovers his humanity when he realizes the survival of Barsoom and its people rests in his hands.', 132, '/lCxz1Yus07QCQQCb6I0Dr3Lmqpx.jpg', '/689yJyzzy6yGj359HrsT9KWyeWA.jpg', 'WR6HUkzxjR0'),
    (49530, 'In the not-too-distant future, the aging gene has been switched off. To avoid overpopulation, time has become the currency and the way people pay for luxuries and necessities. The rich can live forever, while the rest struggle to negotiate for their immortality. A poor young man who suddenly comes into a fortune of time finds himself on the run from a corrupt police force known as the "time keepers".', 109, '/3Mwj2sIONQckOZP3YwsUXF7U5I4.jpg', '/pxL08w7Eq0vKrQ3mJzYp0VHGaKG.jpg', 'xhYUaR5QiUs'),
    (49538, 'Before Charles Xavier and Erik Lensherr took the names Professor X and Magneto, they were two young men discovering their powers for the first time. Before they were arch-enemies, they were closest of friends, working together with other mutants (some familiar, some new), to stop the greatest threat the world has ever known.', 132, '/hNEokmUke0dazoBhttFN0o3L7Xv.jpg', '/yhp5Pt4GugkCs5mz63qWz5khHXe.jpg', '2BAYQD_j6Xc'),
    (49849, 'A stranger stumbles into the desert town of Absolution with no memory of his past and a futuristic shackle around his wrist. With the help of mysterious beauty Ella and the iron-fisted Colonel Dolarhyde, he finds himself leading an unlikely posse of cowboys, outlaws, and Apache warriors against a common enemy from beyond this world in an epic showdown for survival.', 119, '/9uZsGCP4rvOHVGCpMpYq5gNCuNI.jpg', '/sGXCYMzr1sCnGNVuRpB2TOWPWDA.jpg', 'M64b_44zpyk'),
    (50014, 'Aibileen Clark is a middle-aged African-American maid who has spent her life raising white children and has recently lost her only son; Minny Jackson is an African-American maid who has often offended her employers despite her family''s struggles with money and her desperate need for jobs; and Eugenia "Skeeter" Phelan is a young white woman who has recently moved back home after graduating college to find out her childhood maid has mysteriously disappeared. These three stories intertwine to explain how life in Jackson, Mississippi revolves around "the help"; yet they are always kept at a certain distance because of racial lines.', 146, '/3kmfoWWEc9Vtyuaf9v5VipRgdjx.jpg', '/yDwL5qAHeSyaozgXXcYnAOp4AUF.jpg', '3eajzW3XW7Q'),
    (50348, 'Mick Haller is a charismatic defense attorney who does business out of his Lincoln Continental sedan. Mick spends most of his time defending petty crooks and other bottom-feeders, so it comes as quite a surprise when he lands the case of a lifetime: defending a Beverly Hills playboy who is accused of attempted murder. However, what Mick initially thinks is an open-and-shut case with a big monetary reward develops into something more sinister.', 119, '/gOn8Ve9Yi8fxjRkmLr5BZoOc7KV.jpg', '/j9QaQVuyQIEwckUbjHpAgA7E4jJ.jpg', 'IFwE3UgCMIk'),
    (50456, 'Raised by her father, an ex-CIA agent, in the wilds of Finland, Hanna''s upbringing has been geared to making her the perfect assassin. Sent into the world by her father on a mission, Hanna journeys across Europe, eluding agents dispatched after her by a ruthless intelligence operative. As she nears her ultimate target, Hanna faces startling revelations about her existence.', 111, '/6QDeHwBXDHbCbuzStgUpuUAqnap.jpg', '/qq39KWLKBBJmOtj54grO58XyoXG.jpg', '7ImxHJtLEDs'),
    (50546, 'While romancing Palmer, a much younger schoolteacher, plastic surgeon Danny Maccabee enlists his loyal assistant Katherine to pretend to be his soon to be ex-wife, in order to cover up a careless lie. When more lies backfire, Katherine''s kids become involved, and everyone heads off for a weekend in Hawaii that will change all their lives.', 117, '/5nr4n667HD80Wr7dYmqhIYi6CHN.jpg', '/xoYEe7RvAHWC59Jbo1tdktB4v2a.jpg', 'fpj7i2CPt8M'),
    (50620, 'After the birth of Renesmee, the Cullens gather other vampire clans in order to protect the child from a false allegation that puts the family in front of the Volturi.', 115, '/7IGdPaKujv0BjI0Zd0m0a4CzEjJ.jpg', '/qkl57wzSFrpi2sRpoc2mZJbMuLP.jpg', 'bUXjqQ4GKRg'),
    (50646, 'Cal Weaver is living the American dream. He has a good job, a beautiful house, great children and a beautiful wife, named Emily. Cal''s seemingly perfect life unravels, however, when he learns that Emily has been unfaithful and wants a divorce. Over 40 and suddenly single, Cal is adrift in the fickle world of dating. Enter, Jacob Palmer, a self-styled player who takes Cal under his wing and teaches him how to be a hit with the ladies.', 118, '/p4RafgAPk558muOjnBMHhMArjS2.jpg', '/vyrCniZsrXZAW08eECKIp1BMLPh.jpg', 'W7U03cW7k-Y'),
    (51497, 'Former cop Brian O''Conner partners with ex-con Dom Toretto on the opposite side of the law. Since Brian and Mia Toretto broke Dom out of custody, they''ve blown across many borders to elude authorities. Now backed into a corner in Rio de Janeiro, they must pull one last job in order to gain their freedom.', 131, '/gEfQjjQwY7fh5bI4GlG0RrBu7Pz.jpg', '/tQN9JEQ4N4aqej7O6AkQtt0dLpt.jpg', 'P1UVXvKnCLM'),
    (51540, 'For Nick, Kurt and Dale, the only thing that would make the daily grind more tolerable would be to grind their intolerable bosses into dust. Quitting is not an option, so, with the benefit of a few-too-many drinks and some dubious advice from a hustling ex-con, the three friends devise a convoluted and seemingly foolproof plan to rid themselves of their respective employers... permanently.', 98, '/uQkUwgyFHAm0jGQERPG6Z9o9Zbj.jpg', '/9fkYHcOtaz4cKmlDWw7tqUr5TUt.jpg', 'VpUeQV8sdOc'),
    (51739, '14-year-old Arrietty and the rest of the Clock family live in peaceful anonymity as they make their own home from items "borrowed" from the house''s human inhabitants. However, life changes for the Clocks when a human boy discovers Arrietty.', 95, '/3lSRaSjDp2nkXMQkzzjpRi3035O.jpg', '/7Z7WVzJsSReG8B0CaPk0bvWD7tK.jpg', 'S75QfDA3rDA'),
    (51828, 'After spending the night together on the eve of their college graduation, Dexter and Emma are shown each year on the same date to see where they are in their lives. They are sometimes together, and sometimes not.', 107, '/n9jMwSg4IavdD8wqdYnyW5w3Mvp.jpg', '/1PJtX1UUieACKg3eKxuNBb3QEo7.jpg', 'DVOei5MjGQY'),
    (51876, 'The life of an unsuccessful writer is transformed by a top-secret ''smart drug'' that allows him to use 100% of his brain and become a perfect version of himself. His enhanced abilities soon attract shadowy forces that threaten his new life.', 106, '/r8anWUCVK7MZEolcfPrM9eFkRO4.jpg', '/9V6Yq2ZVUmyAPcPyDcCBPnkluKF.jpg', '4TLppsfzQH8'),
    (52449, 'A lazy, incompetent middle school teacher who hates her job and her students is forced to return to her job to make enough money for a boob job after her rich fiancé dumps her.', 92, '/zpIY4qUSX91J9XpPgr0hFrk1eKr.jpg', '/tSir1KH6WgQNAEDzf50tcrPiPzC.jpg', 'GahC5cVsU6A'),
    (52520, 'Having escaped years of imprisonment, vampire warrioress Selene finds herself in a changed world where humans have discovered the existence of both Vampire and Lycan clans and are conducting an all-out war to eradicate both immortal species. Now Selene must battle the humans and a frightening new breed of super Lycans to ensure the death dealers'' survival.', 88, '/jN0uuc8U6M3sTg9zEaliJV60Stf.jpg', '/wJJJS5ey53DqJ3cTuu7GFJsRsWu.jpg', 'WiJMiHazLPQ'),
    (54138, 'When the crew of the Enterprise is called back home, they find an unstoppable force of terror from within their own organization has detonated the fleet and everything it stands for, leaving our world in a state of crisis.  With a personal score to settle, Captain Kirk leads a manhunt to a war-zone world to capture a one man weapon of mass destruction. As our heroes are propelled into an epic chess game of life and death, love will be challenged, friendships will be torn apart, and sacrifices must be made for the only family Kirk has left: his crew.', 132, '/Aim3kVNh1MPIxPEFeJrl9e9Uf1a.jpg', '/npDrIM6ZbuD7nUxI7ZzNBxs4IRF.jpg', 'RJ1qOs7jkIQ'),
    (55301, 'Playing around while aboard a cruise ship, the Chipmunks and Chipettes accidentally go overboard and end up marooned in a tropical paradise. They discover their new turf is not as deserted as it seems.', 87, '/npOXWVoZyl8UrF2wtByHtfmsWSX.jpg', '/j8M9FjI1seC6OmUluDGkOZIwZt.jpg', '-dOc_fqmcZo'),
    (55721, 'Annie''s life is a mess. But when she finds out her lifetime best friend is engaged, she simply must serve as Lillian''s maid of honor. Though lovelorn and broke, Annie bluffs her way through the expensive and bizarre rituals. With one chance to get it perfect, she’ll show Lillian and her bridesmaids just how far you’ll go for someone you love.', 125, '/gJtA7hYsBMQ7EM3sPBMUdBfU7a0.jpg', '/1pkpV7a02phSfAPeGVmpHaQd99J.jpg', 'kg6HHhrxBIk'),
    (56292, 'Ethan Hunt and his team are racing against time to track down a dangerous terrorist named Hendricks, who has gained access to Russian nuclear launch codes and is planning a strike on the United States. An attempt to stop him ends in an explosion causing severe destruction to the Kremlin and the IMF to be implicated in the bombing, forcing the President to disavow them. No longer being aided by the government, Ethan and his team chase Hendricks around the globe, although they might still be too late to stop a disaster.', 133, '/eRZTGx7GsiKqPch96k27LK005ZL.jpg', '/hqyjzDRCs1N5gEsh2gklzPdsEFD.jpg', '7wkih9Yvxq0'),
    (57158, 'The Dwarves, Bilbo and Gandalf have successfully escaped the Misty Mountains, and Bilbo has gained the One Ring. They all continue their journey to get their gold back from the Dragon, Smaug.', 161, '/xQYiXsheRCDBA39DOrmaw1aSpbk.jpg', '/5ZYxL6k4ZHrEmrFvmY4HZVzerxG.jpg', 'gAo95e7_XKA'),
    (57165, 'Perseus tries to live a quieter life as a village fisherman while – dangerously weakened by humanity''s lack of devotion – the gods are losing control of the long-imprisoned Titans and their ferocious leader, Kronos.', 99, '/b9n2R3xZWQ8MVZgndQoV34stS0h.jpg', '/g6Bppew6A1PxpHfraNroo0mRBcm.jpg', '8jEWLCZA7R8'),
    (57201, 'The Texas Rangers chase down a gang of outlaws led by Butch Cavendish, but the gang ambushes the Rangers, seemingly killing them all. One survivor is found, however, by an American Indian named Tonto, who nurses him back to health. The Ranger, donning a mask and riding a white stallion named Silver, teams up with Tonto to bring the unscrupulous gang and others of that ilk to justice.', 149, '/yDuJGq8biNMW7zM3w95UaDJv0KG.jpg', '/vHd8RTXTGFwexUC2Mj1HOgSy9J3.jpg', 'LoVhgaj6PiE'),
    (57212, 'On the brink of the First World War, Albert''s beloved horse Joey is sold to the Cavalry by his father. Against the backdrop of the Great War, Joey begins an odyssey full of danger, joy, and sorrow, and he transforms everyone he meets along the way. Meanwhile, Albert, unable to forget his equine friend, searches the battlefields of France to find Joey and bring him home.', 146, '/3aRHhvvngFPJFy5uAjo7GVr3PhL.jpg', '/tcx15vswrQJCGET5lGxESQ4J5LG.jpg', 'tafBTls8RuA'),
    (57800, 'Manny, Diego, and Sid embark upon another adventure after their continent is set adrift. Using an iceberg as a ship, they encounter sea creatures and battle pirates as they explore a new world.', 88, '/dfp1BZF7FxbBUyzHvMOI9t8NWDD.jpg', '/scLQDnf1m2AqEEQSjAEdMRD6K9I.jpg', 'uDvtgm2REGI'),
    (58151, 'A teenager suspects his new neighbour is a vampire. Unable to convince anyone, he tries to enlist the help of a self-proclaimed vampire hunter and magician.', 106, '/ySQ3v4Fzpy3fePs86eoLiDzwLYM.jpg', '/hTfAhmwSqr79bQAAf5n68q2lw0v.jpg', 'txgGhyjPZGg'),
    (58224, 'Tom Popper is a successful businessman who’s clueless when it comes to the really important things in life...until he inherits six “adorable” penguins, each with its own unique personality. Soon Tom’s rambunctious roommates turn his swank New York apartment into a snowy winter wonderland — and the rest of his world upside-down.', 94, '/jGwZ1QI5DaL7mHQ2ZsMV1p8xvPS.jpg', '/gtkROcxhItcEvGoRr0a12PWBLpf.jpg', '7Js0ADU4owQ'),
    (58233, 'The most prominent heads of state in the world begin gathering for a conference that could have a major impact on global politics. When MI-7 receives word that the Chinese premier has become the target of some high-powered killers, it falls on Johnny English to save the day. Armed with the latest high-tech weaponry and gadgets that would make even James Bond jealous, the once-disgraced agent uncovers evidence of a massive conspiracy involving some of the world''s most powerful organisations, and vows to redeem his tarnished reputation by stopping the killers before they can strike.', 101, '/zDbrU0eSnRGh5gHc1iqTACTNNyT.jpg', '/croOmkPszzl9p8ASq4NTYunFJ5E.jpg', 'wCsSzZU-sQ4'),
    (58574, 'There is a new criminal mastermind at large (Professor Moriarty) and not only is he Holmes’ intellectual equal, but his capacity for evil and lack of conscience may give him an advantage over the detective.', 129, '/y1MYZkwhZK6L0Jy4YMuPktzDOfn.jpg', '/lWNASscWXn32Asr9vkB1wq6cKvD.jpg', 'amE1MxxRUFI'),
    (58595, 'After the Evil Queen marries the King, she performs a violent coup in which the King is murdered and his daughter, Snow White, is taken captive. Almost a decade later, a grown Snow White is still in the clutches of the Queen. In order to obtain immortality, The Evil Queen needs the heart of Snow White. After Snow escapes the castle, the Queen sends the Huntsman to find her in the Dark Forest.', 127, '/8HUa5kRubYbnAD5UVpnhTGGgMTW.jpg', '/KBe9fHU5rVg4daoKnFwl1Cbc28.jpg', 'hDzRFcxlkMw'),
    (59436, 'While on a trip to Paris with his fiancée''s family, a nostalgic screenwriter finds himself mysteriously going back to the 1920s every day at midnight.', 94, '/4wBG5kbfagTQclETblPRRGihk0I.jpg', '/b5bcKhvN6VP82U5ztNdPfOLiolD.jpg', 'FAfR8omt-CY'),
    (59440, 'The youngest son of an alcoholic former boxer returns home, where he''s trained by his father for competition in a mixed martial arts tournament – a path that puts the fighter on a collision course with his estranged, older brother.', 140, '/zeGvf99lr63RcvFXa6Woyq3iPs1.jpg', '/zb7b40ieuRGiIc9ebIEapneaCsl.jpg', 'I5kzcwcQA1Q'),
    (59859, 'After Kick-Ass'' insane bravery inspires a new wave of self-made masked crusaders, he joins a patrol led by the Colonel Stars and Stripes. When these amateur superheroes are hunted down by Red Mist — reborn as The Mother Fucker — only the blade-wielding Hit-Girl can prevent their annihilation.', 103, '/1go2A3gdQjaMuHWquybgoJlQRcX.jpg', '/dHBYguQvCDa00GMoidNYa7IOD8y.jpg', '1zcMLxIuuww'),
    (59860, 'Three young women vacationing in Paris find themselves whisked away to Monte Carlo after one of the girls is mistaken for a British heiress.', 109, '/dcbqyycrWA56HXq5lm41HYuED8Y.jpg', '/aD7XtR408aKDiBo4wJcO0sksvBw.jpg', 'X0n3Q_VDQk8'),
    (59961, 'A dangerous CIA renegade resurfaces after a decade on the run. When the safe house he''s remanded to is attacked by mercenaries, a rookie operative escapes with him. Now, the unlikely allies must stay alive long enough to uncover who wants them dead.', 115, '/7SYBPjv5ywF6cI4BSFFtlDyChT2.jpg', '/kXRskNzFiTxi5xwsM6hDmOTGae7.jpg', 'oWzTOoOpFa8'),
    (59962, 'Two top CIA operatives wage an epic battle against one another after they discover they are dating the same woman.', 98, '/7d1hwECRc1NZlGfAeYE42ki7Fem.jpg', '/mRRpXyjsuj314rqHbQEHlvhoO49.jpg', 'oleuD8479uM'),
    (59965, 'For many years, Nathan Harper has had the uneasy feeling that life with his family isn''t quite what it seems. As he draws closer to uncovering the truth, he is hunted by assassins, forcing him to flee with his neighbor, Karen, the only person he can trust.', 106, '/d0TIDrwnMFVjg2EO4LsXQn1mbbc.jpg', '/6wWIirFFZPQx7Lamh1iKMgbVezr.jpg', 'CEVkp5Je7m0'),
    (59967, 'In the year 2044, time travel has not yet been invented but in 30 years it will have been. When the mob wants to get rid of someone, they will send their target into the past where a looper, a hired gun, like Joe is waiting to mop up. Joe is getting rich and life is good until the day the mob decides to close the loop, sending back Joe''s future self for assassination.', 118, '/sNjL6SqErDBE8OUZlrDLkexfsCj.jpg', '/4GPCnwvTbsDleH5QIOyDLMsK8a2.jpg', '2iQuhsmtfHw'),
    (60308, 'The story of Oakland Athletics general manager Billy Beane''s successful attempt to put together a baseball team on a budget, by employing computer-generated analysis to draft his players.', 134, '/4yIQq1e6iOcaZ5rLDG3lZBP3j7a.jpg', '/kYlBNDkB5qFdpTDpnlQdH0CdK3T.jpg', 'RAG74hfW4pM'),
    (61791, 'A highly intelligent chimpanzee named Caesar has been living a peaceful suburban life ever since he was born. But when he gets taken to a cruel primate facility, Caesar decides to revolt against those who have harmed him.', 105, '/oqA45qMyyo1TtrnVEBKxqmTPhbN.jpg', '/6cCF0KMUO2QmrVsQFujkQduREXX.jpg', 'P1yKN0llkrY'),
    (62177, 'In the mystical Scottish Highlands, Merida is the princess of a kingdom ruled by King Fergus and Queen Elinor. An unruly daughter and an accomplished archer, Merida one day defies a sacred custom of the land and inadvertently brings turmoil to the kingdom. In an attempt to set things right, Merida seeks out an eccentric old Wise Woman and is granted an ill-fated wish.', 93, '/1XAuDtMWpL0sYSFK0R6EZate2Ux.jpg', '/qx9ts2hBYJrkIQxhryitxnLlm2u.jpg', 'OKdLpBLp3nM'),
    (62211, 'A look at the relationship between Mike and Sulley during their days at Monsters University — when they weren''t necessarily the best of friends.', 104, '/y7thwJ7z5Bplv6vwl6RI0yteaDD.jpg', '/mIpCxBWNz6SHCQBe2K2PFr5MB7f.jpg', 'xBzPioph8CI'),
    (62213, 'Vampire Barnabas Collins is inadvertently freed from his tomb and emerges into the very changed world of 1972. He returns to Collinwood Manor to find that his once-grand estate and family have fallen into ruin.', 113, '/fd9Ck4cxVlmtXsbeGtQW7WFuUFI.jpg', '/cJYerfZVf2rNwfGMK3MQ8lTbMnY.jpg', '4cVcpz8H3Pk'),
    (62214, 'When a car hits young Victor''s pet dog Sparky, Victor decides to bring him back to life the only way he knows how. But when the bolt-necked "monster" wreaks havoc and terror in the hearts of Victor''s neighbors, he has to convince them that Sparky''s still the good, loyal friend he was.', 87, '/yGjVbLVdZRBlZTTQVBsj2KUjL1s.jpg', '/yfTZ2MSRWc06cBrFOsAF4Lebi4.jpg', '2e1_XxakM-I'),
    (62215, 'Two sisters find their already strained relationship challenged as a mysterious new planet threatens to collide with Earth.', 136, '/fMneszMiQuTKY8JUXrGGB5vwqJf.jpg', '/qzrS5ShZZPsPdhM5ZbcQKG7fwFo.jpg', '6IZGwvxhXvw'),
    (62764, 'After she spends all her money, an evil enchantress queen schemes to marry a handsome, wealthy prince. There''s just one problem - he''s in love with a beautiful princess, Snow White. Now, joined by seven rebellious dwarves, Snow White launches an epic battle of good vs. evil...', 106, '/gzTSQUUuFrm5ndkIbOVibT797os.jpg', '/iFSO0glqR8wydqaRl9KxQI63xEd.jpg', '31JOXM_Nk20'),
    (62835, 'After witnessing her parents’ murder as a child in Bogota, Cataleya Restrepo grows up to be a stone-cold assassin. She works for her uncle as a hitman by day, but her personal time is spent engaging in vigilante murders that she hopes will lead her to her ultimate target: the mobster responsible for her parents'' death.', 108, '/rEdGDgRB3gducezNSIyx2lbKQy4.jpg', '/aoof4GKwyUBN07tRN2HJXm6mSco.jpg', 'HCxPLlFWdFo'),
    (64635, 'Factory worker Doug Quaid takes a virtual mind-trip vacation with the Rekall company, opting for implanted memories of being a spy. When the procedure goes wrong, Quaid becomes a wanted man by the police and joins forces with a rebel fighter to stop the evil Chancellor Cohaagen.', 118, '/hVUxVVzZ0WvvPIpKwsMPMDOQyqi.jpg', '/uBHeAB2Ug9ELBzkMyls8CUjzn4i.jpg', 'wbE6Wkzuydc'),
    (64682, 'Nick Carraway arrives in New York in 1922, an era of loose morals, glittering jazz and bootleg kings. Chasing his own American Dream, Nick encounters the mysterious millionaire Gatsby and his bewitching cousin Daisy. Soon, Nick is drawn into the captivating world of the super-rich, their illusions, loves and deceits. Bearing witness to this new world, Nick pens a tale of impossible love, incorruptible dreams and unforgettable tragedy -- mirroring our own times and struggles.​', 143, '/tyxfCBQv6Ap74jcu3xd7aBiaa29.jpg', '/cf4YmtSnNhdG7s9ERmXyaDEznEw.jpg', 'l6yANES3TMM'),
    (64685, 'A year after his father''s death, Oskar, a troubled young boy, discovers a mysterious key he believes was left for him by his father and embarks on a scavenger hunt to find the matching lock.', 129, '/6pszViNvKr1r31pP7gJNYDHEx5P.jpg', '/hTc55dlCPMP4oqrUU66GjKjSblp.jpg', 'vxnI-4c8HzU'),
    (64686, 'Kai—an outcast—joins Oishi, the leader of 47 outcast samurai.  Together they seek vengeance upon the treacherous overlord who killed their master and banished their kind.  To restore honour to their homeland, the warriors embark upon a quest that challenges them with a series of trials that would destroy ordinary warriors.', 119, '/xDHnmcroujCRG0ysYQaiswjbyHd.jpg', '/nyt0jlofZyjhRqiQkEp0cdoKaS3.jpg', 'DEoDulGTElE'),
    (64688, 'When cops Schmidt and Jenko join the secret Jump Street unit, they use their youthful appearances to go undercover as high school students. They trade in their guns and badges for backpacks, and set out to shut down a dangerous drug ring. But, as time goes on, Schmidt and Jenko discover that high school is nothing like it was just a few years earlier -- and, what''s more, they must again confront the teenage terror and anxiety they thought they had left behind.', 109, '/8v3Sqv9UcIUC4ebmpKWROqPBINZ.jpg', '/rXrpYOveFl76ivMmyb2612T7Q8w.jpg', 'BjRs18rV1FI'),
    (64690, 'Driver is a skilled Hollywood stuntman who moonlights as a getaway driver for criminals. Though he projects an icy exterior, lately he''s been warming up to a pretty neighbor named Irene and her young son, Benicio. When Irene''s husband gets out of jail, he enlists Driver''s help in a million-dollar heist. The job goes horribly wrong, and Driver must risk his life to protect Irene and Benicio from the vengeful masterminds behind the robbery.', 100, '/602vevIURmpDfzbnv5Ubi6wIkQm.jpg', '/hoyAALgfmjMEK7O1wZ4r8wT91RP.jpg', 'inTc4Q_gEWQ'),
    (65086, 'The story follows a young lawyer, Arthur Kipps, who is ordered to travel to a remote village and sort out a recently deceased client’s papers. As he works alone in the client’s isolated house, Kipps begins to uncover tragic secrets, his unease growing when he glimpses a mysterious woman dressed only in black. Receiving only silence from the locals, Kipps is forced to uncover the true identity of the Woman in Black on his own, leading to a desperate race against time when he discovers her true identity.', 95, '/peKkO5lYyyZ7flxeFuXoZPXArXo.jpg', '/jJ3yFKs6xeVGxtmm7GXZYQ3XAvz.jpg', 'Z2UZwaEUeE0'),
    (65754, 'Disgraced journalist Mikael Blomkvist investigates the disappearance of a weary patriarch''s niece from 40 years ago. He is aided by the pierced, tattooed, punk computer hacker named Lisbeth Salander. As they work together in the investigation, Blomkvist and Salander uncover immense corruption beyond anything they have ever imagined.', 158, '/8bokS83zGdhaXgN9tjidUKmAftW.jpg', '/dNFbrnF0mIBm0rClbfEFWTtsgMP.jpg', 'svucpVzRBD4'),
    (68718, 'With the help of a German bounty hunter, a freed slave sets out to rescue his wife from a brutal Mississippi plantation owner.', 165, '/7oWY8VDWW7thTzWh3OKYRkWUlD5.jpg', '/2oZklIzUbvZXXzIFzv7Hi68d6xf.jpg', '_iH0UBYDI4g'),
    (68721, 'Plagued with worry and insomnia since saving New York from destruction, Tony Stark, now, is more dependent on the suits that give him his Iron Man persona—so much so that every aspect of his life is affected, including his relationship with Pepper. After a malevolent enemy known as the Mandarin reduces his personal world to rubble, Tony must rely solely on instinct and ingenuity to avenge his losses and protect the people he loves, as he begins an odyssey of rebuilding and retribution.', 130, '/qhPtAc1TKbMPqNvcdXSOn9Bn7hZ.jpg', '/iVped1djsF0tvGkvnHbzsE3ZPTF.jpg', 'YLorLVa95Xo'),
    (68722, 'Freddie, a volatile, heavy-drinking veteran who suffers from post-traumatic stress disorder, finds some semblance of a family when he stumbles onto the ship of Lancaster Dodd, the charismatic leader of a new "religion" he forms after World War II.', 137, '/jjVGdNt4fYb3T2hjISGZ2qnCuaV.jpg', '/6vvt0ghvrrzEB8Z1BLvmHOWUdxw.jpg', 'RApl06pYIuU'),
    (68724, 'In the year 2159, two classes of people exist: the very wealthy who live on a pristine man-made space station called Elysium, and the rest, who live on an overpopulated, ruined Earth. Secretary Rhodes, a hard line government official, will stop at nothing to enforce anti-immigration laws and preserve the luxurious lifestyle of the citizens of Elysium. That doesn’t stop the people of Earth from trying to get in, by any means they can. When unlucky Max is backed into a corner, he agrees to take on a daunting mission that, if successful, will not only save his life, but could bring equality to these polarized worlds.', 109, '/aRjuJuPXHtVs6YegfeeQWXGRs1E.jpg', '/oo9GyiNKvR4CU1etuYl081UJ1LE.jpg', 'oIBtePb-dGY'),
    (68726, 'Using massive piloted robots to combat the alien threat, Earth''s survivors take the fight to the invading alien force lurking in the depths of the Pacific Ocean. Nearly defenseless in the face of the relentless enemy, the forces of mankind have no choice but to turn to two unlikely heroes who now stand as Earth''s final hope against the mounting apocalypse.', 131, '/mmznhaQDwlHWpUwKuNxtQiubbmM.jpg', '/9X7Im1YuBhyHYVD8r7CAONPJR5k.jpg', 'hQAQxQop6Io'),
    (68728, 'Oscar Diggs, a small-time circus illusionist and con-artist, is whisked from Kansas to the Land of Oz where the inhabitants assume he''s the great wizard of prophecy, there to save Oz from the clutches of evil.', 130, '/nr0deOZ4h7HkCzfc09fIgK7cxTG.jpg', '/f5bwgNLwNop0GfYg90FO3jmTzZG.jpg', 'DylgNj4YQVc'),
    (68730, 'In the 17th century, two Portuguese Jesuit priests travel to Japan in an attempt to locate their mentor, who is rumored to have committed apostasy, and to propagate Catholicism.', 161, '/x5T0cQDYws0xRBVG4Q3wpcrcmax.jpg', '/2tE0A6WjLowwQOUY8se1Xlf3O6U.jpg', 'IqrgxZLd_gE'),
    (68734, 'As the Iranian revolution reaches a boiling point, a CIA ''exfiltration'' specialist concocts a risky plan to free six Americans who have found shelter at the home of the Canadian ambassador.', 120, '/m5gPWFZFIp4UJFABgWyLkbXv8GX.jpg', '/iVk4mVKwNE66JbBcoDwcYFvuUXM.jpg', '3RrtxIci4T0'),
    (68735, 'The peaceful realm of Azeroth stands on the brink of war as its civilization faces a fearsome race of invaders: orc warriors fleeing their dying home to colonize another. As a portal opens to connect the two worlds, one army faces destruction and the other faces extinction. From opposing sides, two heroes are set on a collision course that will decide the fate of their family, their people, and their home.', 123, '/eGi5aoxaZveqNLtE7BZJCuWwR3G.jpg', '/aTGvZ3F8QnAD8cPpJRaaqRRxFK6.jpg', '65AjY_nRdqE'),
    (70074, 'After watching their respective partners die, a cop and a hitman form an alliance in order to bring down their common enemy.', 92, '/arJfxShfuZPhqfBZZU6DkPZfnjn.jpg', '/bXO410CYaMaoIGecgS7bcAlr5T9.jpg', 'maXSTzmY86g'),
    (70160, 'In a dystopian society where the Capitol forces each district to send two young tributes to fight to the death in a televised spectacle, a girl volunteers to take her sister’s place, setting the stage for a struggle of survival and defiance.', 142, '/apa5G43Hha7kH7wJG0gkkHT7FA9.jpg', '/eVYChqJavS1DCXFeJE2lzVUMLKp.jpg', 'wLGOaKY5STw'),
    (70981, 'A team of explorers discover a clue to the origins of mankind on Earth, leading them on a journey to the darkest corners of the universe. There, they must fight a terrifying battle to save the future of the human race.', 124, '/qsYQflQhOuhDpQ0W2aOcwqgDAeI.jpg', '/qDG5SlGkWNsjSJWiGTBMFI8DpzA.jpg', 'cJMIzdf1eo8'),
    (71552, 'The characters we met a little more than a decade ago return to East Great Falls for their high school reunion. In one long-overdue weekend, they will discover what has changed, who hasn’t, and that time and distance can’t break the bonds of friendship.', 113, '/de5QBIdVR4dnkBZ4a0zjkS4lTg.jpg', '/lroojUACXVHdnjVYQXgts5IhqGr.jpg', '1akixU65dDY'),
    (71672, 'A group of friends take refuge in a deserted sanatorium after they are left stranded in a snowstorm. Later, the place becomes a death trap when man-eating cannibals surround them.', 93, '/l1vD4GY7tlT420KJ3xWTzyQ2Aa9.jpg', '/8xyJcJnYbupkPPMvwTEJaUwjxDI.jpg', 'fulKeIZM2-s'),
    (71676, 'When the devil resurfaces with aims to take over the world in human form, Johnny Blaze reluctantly comes out of hiding to transform into the flame-spewing supernatural hero Ghost Rider -- and rescue a 10-year-old boy from an unsavory end.', 96, '/xEoBT6lYfQNpSpTm8gJMTrQytiw.jpg', '/ebNcAJfWsSbbv7VhboAvpUdOduJ.jpg', 'ibZPd9MX0zg'),
    (71679, 'The Umbrella Corporation’s deadly T-virus continues to ravage the Earth, transforming the global population into legions of the flesh eating Undead. The human race’s last and only hope, Alice, awakens in the heart of Umbrella’s most clandestine operations facility and unveils more of her mysterious past as she delves further into the complex. Without a safe haven, Alice continues to hunt those responsible for the outbreak; a chase that takes her from Tokyo to New York, Washington, D.C. and Moscow, culminating in a mind-blowing revelation that will force her to rethink everything that she once thought to be true. Aided by new found allies and familiar friends, Alice must fight to survive long enough to escape a hostile world on the brink of oblivion. The countdown has begun.', 95, '/cHFLp5jg2Q3pCDIqUQrsM8nr1Wi.jpg', '/mLgFebdy051NX1vfFrpuUPRQHgg.jpg', 'hoyMT-7wEqs'),
    (72105, 'John Bennett, a man whose childhood wish of bringing his teddy bear to life came true, now must decide between keeping the relationship with the bear or his girlfriend, Lori.', 107, '/1QVZXQQHCEIj8lyUhdBYd2qOYtq.jpg', '/hkAVgWvAMmM8tj9CDEvGqMdNQBE.jpg', 'xXDAs23aSQc'),
    (72190, 'Life for former United Nations investigator Gerry Lane and his family seems content. Suddenly, the world is plagued by a mysterious infection turning whole human populations into rampaging mindless zombies. After barely escaping the chaos, Lane is persuaded to go on a mission to investigate this disease. What follows is a perilous trek around the world where Lane must brave horrific dangers and long odds to find answers before human civilization falls.', 116, '/aCnVdvExw6UWSeQfr0tUH3jr4qG.jpg', '/kg2FOT2Oe5PSCgs3L4vLel6B7ck.jpg', 'TvRCQM2HrXs'),
    (72545, 'Sean Anderson partners with his mom''s boyfriend on a mission to find his grandfather, who is thought to be missing on a mythical island.', 94, '/uFm2vnp9LhHx5MNo1Ego6O3vUhl.jpg', '/fZvAroq9Vb5hhyKT6TxsjxJW7nm.jpg', 'IVX7OidrkXQ'),
    (72559, 'Framed for crimes against the country, the G.I. Joe team is terminated by Presidential order. This forces the G.I. Joes into not only fighting their mortal enemy Cobra; they are forced to contend with threats from within the government that jeopardize their very existence.', 110, '/3rWIZMzTKcCtV0eHJ70Z4Ru659f.jpg', '/pEhXq18GVe1dg2ltplcxtGWfSje.jpg', '2vAo4rJPqQ4'),
    (72570, 'Happy young married couple Paige and Leo are, well, happy. Then a car accident puts Paige into a life-threatening coma. Upon awakening she has lost the previous five years of memories, including those of her beloved Leo, her wedding, a confusing relationship with her parents, or the ending of her relationship with her ex-fiance. Despite these complications, Leo endeavors to win her heart again and rebuild their marriage.', 104, '/y5GUXzTvt7kSQbdQrSvbYNoa8HB.jpg', '/a8IFeO1BMn4QEfLsf41Ml7LodyC.jpg', 'PcL24s-S6ns'),
    (72710, 'A parasitic alien soul is injected into the body of Melanie Stryder. Instead of carrying out her race''s mission of taking over the Earth, "Wanda" (as she comes to be called) forms a bond with her host and sets out to aid other free humans.', 126, '/1mfIZw6WgkCX310eoe0Ys14c3Fi.jpg', '/1bDa2d9VqqBQlk42Gduu37Rz1ob.jpg', 'SRKjf8b4f2E'),
    (72976, 'The revealing story of the 16th US President''s tumultuous final months in office. In a nation divided by war and the strong winds of change, Lincoln pursues a course of action designed to end the war, unite the country and abolish slavery. With the moral courage and fierce determination to succeed, his choices during this critical moment will change the fate of generations to come.', 150, '/7mUYEkv9W3ek61eetZCfMQYVoi.jpg', '/hwOFrwHladQ8FktYn3aJNAt8KA1.jpg', 'nvP-ZrzA2lk'),
    (73567, 'A cop who moonlights as a hit man agrees to kill the hated mother of a desperate drug dealer in exchange for a tumble with the young man''s virginal sister.', 102, '/vr470u3L5govXLpoqtUe8S9GyxE.jpg', '/mpiwGcxp30sHxTOJ1jw3Dd1QgPZ.jpg', 'fF8dz-JPjNk'),
    (73723, 'A 12-year-old boy searches for the one thing that will enable him to win the affection of the girl of his dreams. To find it he must discover the story of the Lorax, the grumpy yet charming creature who fights to protect his world.', 86, '/tePFnZFw5JvjwjQjaKkqDPNMLPU.jpg', '/71FjlP0qZPc1iymcHf8u5vXfH50.jpg', 'XbGnmKPSq9k'),
    (74465, 'Benjamin has lost his wife and, in a bid to start his life over, purchases a large house that has a zoo – welcome news for his daughter, but his son is not happy about it. The zoo is in need of renovation and Benjamin sets about the work with the head keeper and the rest of the staff, but, the zoo soon runs into financial trouble.', 124, '/dcOvIqdsojUdAtWt1nPT9xS76Su.jpg', '/3epmRoQFyUpLATk1JKgnKKQp0kM.jpg', 'Fopeq7wx4sw'),
    (74643, 'Hollywood, 1927: As silent movie star George Valentin wonders if the arrival of talking pictures will cause him to fade into oblivion, he sparks with Peppy Miller, a young dancer set for a big break.', 100, '/xYMYV8lMIeQMymuNPBvq3hOnqXw.jpg', '/bYimqNnizPUCnL5HOdoCW02IGmH.jpg', 'qjCQmpNkBI4'),
    (74725, 'Nearly a year after a botched job, a hitman takes a new assignment with the promise of a big payoff for three killings. What starts off as an easy task soon unravels, sending the killer into the heart of darkness.', 95, '/qwT2I3ons0oD58jIppKmd4qLtvB.jpg', '/mVhPbSatTB40Gu874mu0WzejrmZ.jpg', 'aqkqF--v1tg'),
    (75612, 'Jack Harper is one of the last few drone repairmen stationed on Earth. Part of a massive operation to extract vital resources after decades of war with a terrifying threat known as the Scavs, Jack’s mission is nearly complete. His existence is brought crashing down when he rescues a beautiful  stranger from a downed spacecraft. Her arrival triggers a chain of events that  forces him to question everything he knows and puts the fate of humanity in his hands.', 124, '/eO3r38fwnhb58M1YgcjQBd3VNcp.jpg', '/2kVt8oj1cSz4GAP0Hi8SESOiH0T.jpg', 'tx6_JMDFfWI'),
    (75656, 'An FBI agent and an Interpol detective track a team of illusionists who pull off bank heists during their performances and reward their audiences with the money.', 116, '/tWsNYbrqy1p1w6K9zRk0mSchztT.jpg', '/574x1IR4TwHPOmMEol5tGe2aEfh.jpg', 'DaavRAV8a0A'),
    (75780, 'One morning in an ordinary town, five people are shot dead in a seemingly random attack. All evidence points to a single suspect: an ex-military sniper who is quickly brought into custody. The interrogation yields one written note: ''Get Jack Reacher!''. Reacher, an enigmatic ex-Army investigator, believes the authorities have the right man but agrees to help the sniper''s defense attorney. However, the more Reacher delves into the case, the less clear-cut it appears. So begins an extraordinary chase for the truth, pitting Jack Reacher against an unexpected enemy, with a skill for violence and a secret to keep.', 130, '/uQBbjrLVsUibWxNDGA4Czzo8lwz.jpg', '/iwvP8XVpYVmJ3xfF9xdBi5uAOWl.jpg', 'kAbxn_F8lps'),
    (76025, 'Brandon, a thirty-something man living in New York, eludes intimacy with women but feeds his deepest desires with a compulsive addiction to sex. When his younger sister temporarily moves into his apartment, stirring up bitter memories of their shared painful past, Brandon''s life, like his fragile mind, gets out of control.', 102, '/cAWLz9kFv4xc6IsEXTj2DrcqD55.jpg', '/rKVqCSqy6jfjpeUCs4Ka6DSITzR.jpg', 'Op9iQiB_ANI'),
    (76163, 'Mr. Church reunites the Expendables for what should be an easy paycheck, but when one of their men is murdered on the job, their quest for revenge puts them deep in enemy territory and up against an unexpected threat.', 103, '/74rTIGyGoIu5KSxDVMdr8H3MtMo.jpg', '/ihKsZZYMbyHXC1L7s90WDLITdC5.jpg', 'ip_CYHdyUBs'),
    (76170, 'Wolverine faces his ultimate nemesis - and tests of his physical, emotional, and mortal limits - in a life-changing voyage to modern-day Japan.', 126, '/t2wVAcoRlKvEIVSbiYDb8d0QqqS.jpg', '/bEAQfLTykGg232kJogBlxRYaRqU.jpg', 'DwG56k6VGOE'),
    (76203, 'In the pre-Civil War United States, Solomon Northup, a free black man from upstate New York, is abducted and sold into slavery. Facing cruelty as well as unexpected kindnesses Solomon struggles not only to stay alive, but to retain his dignity. In the twelfth year of his unforgettable odyssey, Solomon’s chance meeting with a Canadian abolitionist will forever alter his life.', 134, '/xdANQijuNrJaw1HA61rDccME4Tm.jpg', '/4Bb1kMIfrT2tYRZ9M6Jhqy6gkeF.jpg', 'z02Ie8wKKRg'),
    (76285, 'In their quest to confront the ultimate evil, Percy and his friends battle swarms of mythical creatures to find the mythical Golden Fleece and to stop an ancient evil from rising.', 106, '/tAu90qEpLqwqiZLsMqpaMVr55oN.jpg', '/fvrGb6zfQaQ8RD9pC8o9vv1b7W2.jpg', 'xg3znoE9m7I'),
    (76338, 'Thor fights to restore order across the cosmos… but an ancient race led by the vengeful Malekith returns to plunge the universe back into darkness. Faced with an enemy that even Odin and Asgard cannot withstand, Thor must embark on his most perilous and personal journey yet, one that will reunite him with Jane Foster and force him to sacrifice everything to save us all.', 112, '/wp6OxE4poJ4G7c0U2ZIXasTSMR7.jpg', '/5o88bbqcV5STn56jqOeovaaWbAE.jpg', 'npvJ9FTgZbM'),
    (76341, 'An apocalyptic story set in the furthest reaches of our planet, in a stark desert landscape where humanity is broken, and most everyone is crazed fighting for the necessities of life. Within this world exist two rebels on the run who just might be able to restore order.', 121, '/ulcAi4dKpAjHwYGS08vNyx9H6I9.jpg', '/uT895WNwm0aIJRtGizcQhrejWUo.jpg', 'MonFNCgK4WE'),
    (76492, 'Welcome to Hotel Transylvania, Dracula''s lavish five-stake resort, where monsters and their families can live it up and no humans are allowed. One special weekend, Dracula has invited all his best friends to celebrate his beloved daughter Mavis''s 118th birthday. For Dracula catering to all of these legendary monsters is no problem but the party really starts when one ordinary guy stumbles into the hotel and changes everything!', 91, '/eJGvzGrsfe2sqTUPv5IwLWXjVuR.jpg', '/5rARlA8beRAVXPYzSaF2NoS8Ry5.jpg', 'q4RK3jY7AVk'),
    (76493, 'The heroic story of a dictator who risks his life to ensure that democracy would never come to the country he so lovingly oppressed.', 83, '/n0W7kajF4GFMRk2c0wWwMQqTaDM.jpg', '/jWq20KNbg5txb28tLxJl0yLYuxp.jpg', 'cYplvwBvGA4'),
    (76600, 'Set more than a decade after the events of the first film, learn the story of the Sully family (Jake, Neytiri, and their kids), the trouble that follows them, the lengths they go to keep each other safe, the battles they fight to stay alive, and the tragedies they endure.', 192, '/t6HIqrRAclMCA60NsSmeqe9RmNV.jpg', '/kJsPVzdyBrYHLomuNv5SJDXUQ2f.jpg', 'o5F8MOz_IDw'),
    (76617, 'A young woman learns that she has inherited a Texas estate from her deceased grandmother. After embarking on a road trip with friends to uncover her roots, she finds she is the sole owner of a lavish, isolated Victorian mansion. But her newfound wealth comes at a price as she stumbles upon a horror that awaits her in the mansion’s dank cellars.', 92, '/dwIQ7WDCSiIcNdbferTcU7uI0KV.jpg', '/vTQ6fbyampB4lPwqIWRrsdBBxO0.jpg', 'Z0xYPG-gX0U'),
    (76640, 'Ray Owens is sheriff of the quiet US border town of Sommerton Junction after leaving the LAPD following a bungled operation. Following his escape from the FBI, a notorious drug baron, his gang, and a hostage are heading toward Sommerton Junction where the police are preparing to make a last stand to intercept them before they cross the border. Owens is reluctant to become involved but ultimately joins in with the law enforcement efforts.', 107, '/3tP4r47v8v6mEj5X5RuG9y8Frbh.jpg', '/7gJSakiM2e9hzmnY8G1lRvtA4OD.jpg', 'BS-FyAh9cv8'),
    (76726, 'Three high school students make an incredible discovery, leading to their developing uncanny powers beyond their understanding. As they learn to control their abilities and use them to their advantage, their lives start to spin out of control, and their darker sides begin to take over.', 84, '/kdyrdFIt29FUmLIKvedAc2j4rpo.jpg', '/rgNzvSagnlc32TuMEBa529QFIig.jpg', 'AQ9XG-j4kvU'),
    (76757, 'In a universe where human genetic material is the most precious commodity, an impoverished young Earth woman becomes the key to strategic maneuvers and internal strife within a powerful dynasty…', 127, '/xzQ25m9vrdyvpLX74T3B3KB40Ou.jpg', '/w4hk4QG05nDuSgimpa7XAM6OyPX.jpg', 'gQHKolIqBGs'),
    (77016, 'Two young officers are marked for death after confiscating a small cache of money and firearms from the members of a notorious cartel during a routine traffic stop.', 109, '/pDeVKQICkcdwwjHxGj0MeS14YJ6.jpg', '/wK2D1OAodmCWtaPxybcBFCLRskF.jpg', 'TYGXe5ggBx0'),
    (77174, 'In the town of Blithe Hollow, Norman Babcock can speak to the dead, but no one other than his eccentric new friend believes his ability is real. One day, Norman''s eccentric uncle tells him of a ritual he must perform to protect the town from a curse cast by a witch centuries ago.', 93, '/9DZPtuYTKYxt6vzHvZ5FLThG4fl.jpg', '/fRhpdmaA1wTAboeiKW2ZHvDezIm.jpg', 'mI4L-H0TeNI'),
    (77338, 'A true story of two men who should never have met – a quadriplegic aristocrat who was injured in a paragliding accident and a young man from the projects.', 113, '/1QU7HKgsQbGpzsJbJK4pAVQV9F5.jpg', '/q6OGlZ1KMEb14AC8KbPCxyNOal6.jpg', 'dvdJ--DV0Uo'),
    (77877, 'A Marine travels to Louisiana after serving three tours in Iraq and searches for the unknown woman he believes was his good luck charm during the war.', 101, '/vF1ZuIkF9Z71VzVvG265xJUawb0.jpg', '/zGZpy2u5yRczyRMOlNTEm8vJMCi.jpg', 't2LI5OOifsQ'),
    (77931, 'The evil wizard Gargamel creates a couple of mischievous Smurf-like creatures called the Naughties that he hopes will let him harness the all-powerful, magical Smurf-essence. But when he discovers that only a real Smurf can give him what he wants, and only a secret spell that Smurfette knows can turn the Naughties into real Smurfs, Gargamel kidnaps Smurfette and brings her to Paris, where he has been winning the adoration of millions as the world¹s greatest sorcerer. It''s up to Papa, Clumsy, Grouchy, and Vanity to return to our world, reunite with their human friends Patrick and Grace Winslow, and rescue her! Will Smurfette, who has always felt different from the other Smurfs, find a new connection with the Naughties Vexy and Hackus or will the Smurfs convince her that their love for her is True Blue?', 105, '/tmjvgbEH4BKYFfHmWXjXrHgi8wT.jpg', '/aIyvMthA7UGV6ix6AUUM88ZXfeU.jpg', 'W-yEIIMtwCA'),
    (77950, 'The tale of an ordinary garden snail who dreams of winning the Indy 500.', 96, '/inTKQni4YW8syrfgnXHwzmNeSo4.jpg', '/3qfiZd8ETMk9MQsmhbOB5QAAx0l.jpg', 'VlRtm8Gh9PQ'),
    (77987, 'Julian, who runs a Thai boxing club as a front organization for his family''s drug smuggling operation, is forced by his mother Crystal to find and kill the individual responsible for his brother''s recent death.', 89, '/kWjjFSng1JttmDRwDROoGcIArEh.jpg', '/pRrQMx00P8LaXGwJXYJ2tRGoVOs.jpg', 'XiSq-7QQDQg'),
    (80274, 'Based on the classic novel by Orson Scott Card, Ender''s Game is the story of the Earth''s most gifted children training to defend their homeplanet in the space wars of the future.', 114, '/pVcRI5YKnkkgaAD876jBeKb189d.jpg', '/zWvOs6lepfOI0dPa1ANVcdbkBuY.jpg', 'vP0cUBi4hwE'),
    (80278, 'In December 2004, close-knit family Maria, Henry and their three sons begin their winter vacation in Thailand. But the day after Christmas, the idyllic holiday turns into an incomprehensible nightmare when a terrifying roar rises from the depths of the sea, followed by a wall of black water that devours everything in its path. Though Maria and her family face their darkest hour, unexpected displays of kindness and courage ameliorate their terror.', 113, '/k0DLCiDbnYywOHiISALbl2EH2NE.jpg', '/3NfM0sRwVLnsQkCd5YBPGvM9a5v.jpg', 'PaY8EeUYh10'),
    (80321, 'Animal pals Alex, Marty, Melman, and Gloria are still trying to make it back to New York''s Central Park Zoo. They are forced to take a detour to Europe to find the penguins and chimps who broke the bank at a Monte Carlo casino. When French animal-control officer Capitaine Chantel DuBois picks up their scent, Alex and company are forced to hide out in a traveling circus.', 93, '/ekraj4ksvIKeuvQVEevEJkuybZd.jpg', '/uDR9UjSuykTL8g3N3bh3siZ4n3C.jpg', 'PlkWVkpP59U'),
    (81005, 'The story of an ancient war that is reignited when a young farmhand unwittingly opens a gateway between our world and a fearsome race of giants. Unleashed on the Earth for the first time in centuries, the giants strive to reclaim the land they once lost, forcing the young man, Jack into the battle of his life to stop them. Fighting for a kingdom, its people, and the love of a brave princess, he comes face to face with the unstoppable warriors he thought only existed in legend–and gets the chance to become a legend himself.', 114, '/9jSI7saUX9Qz0JLh19jX2ulEwL7.jpg', '/djSAd6HUm66eVNC3PiZbYwOpD5A.jpg', 'xpkcEIsgGmU'),
    (81188, 'Generation after generation, immortal Guardians have protected the world''s children from darkness and despair. But when the malicious boogeyman Pitch Black schemes to overthrow the Guardians by obliterating children’s innocent beliefs in them, the Guardians must join forces for the first time to protect the hopes and imagination of children all over the earth.', 97, '/yfzmfWGjcmyugH6FZ13WcsUGiNj.jpg', '/46IGtYNjpIvQYRIQlb2X493Wh8x.jpg', 'aPLiBxhoug0'),
    (82507, 'True-crime writer Ellison Oswalt is in a slump; he hasn''t had a best seller in more than 10 years and is becoming increasingly desperate for a hit. So, when he discovers the existence of a snuff film showing the deaths of a family, he vows to solve the mystery. He moves his own family into the victims'' home and gets to work. However, when old film footage and other clues hint at the presence of a supernatural force, Ellison learns that living in the house may be fatal.', 110, '/nzx10sca3arCeYBAomHan4Q6wa1.jpg', '/jovIEk4cAxWmA2dBcPrfhn3jzYN.jpg', 'apghx7q9oeY'),
    (82525, 'Pot growers Ben and Chon face off against the Mexican drug cartel that kidnapped their shared girlfriend.', 131, '/a5h5FvryxiALwfv3FzgUKxJHHPG.jpg', '/39FIOhhLT8mxvFRD6MaFzXCVgHr.jpg', 'jDZSt_MhU4Q'),
    (82654, 'After a zombie becomes involved with the girlfriend of one of his victims, their romance sets in motion a sequence of events that might transform the entire lifeless world.', 98, '/i8vCO3uszvlfBJVEyuIZVUDlt60.jpg', '/faEe5nH1VP2xMmE8f9lgqjhsmYI.jpg', 'x3ErWNBX9Rc'),
    (82675, 'In Istanbul, retired CIA operative Bryan Mills and his wife are taken hostage by the father of a kidnapper Mills killed while rescuing his daughter.', 91, '/yzAlcuJhpnxRPjaj7AHBRbNPQCJ.jpg', '/5M92Rtz6r01HLrN0TMrU8jCbyVm.jpg', 'otHUjWVgIig'),
    (82682, 'Los Angeles, 1949. Ruthless, Brooklyn-born mob king Mickey Cohen runs the show in this town, reaping the ill-gotten gains from the drugs, the guns, the prostitutes and — if he has his way — every wire bet placed west of Chicago. And he does it all with the protection of not only his own paid goons, but also the police and the politicians who are under his control. It’s enough to intimidate even the bravest, street-hardened cop… except, perhaps, for the small, secret crew of LAPD outsiders led by Sgt. John O’Mara and Jerry Wooters who come together to try to tear Cohen’s world apart.', 113, '/wAuQNTBFBu2yXZsX6yLhUPiwTlW.jpg', '/9LalKDfdttu9z8Ag1UKTTO66FzA.jpg', 'LlbN5cQKZik'),
    (82690, 'Wreck-It Ralph is the 9-foot-tall, 643-pound villain of an arcade video game named Fix-It Felix Jr., in which the game''s titular hero fixes buildings that Ralph destroys. Wanting to prove he can be a good guy and not just a villain, Ralph escapes his game and lands in Hero''s Duty, a first-person shooter where he helps the game''s hero battle against alien invaders. He later enters Sugar Rush, a kart racing game set on tracks made of candies, cookies and other sweets. There, Ralph meets Vanellope von Schweetz who has learned that her game is faced with a dire threat that could affect the entire arcade, and one that Ralph may have inadvertently started.', 101, '/zWoIgZ7mgmPkaZjG0102BSKFIqQ.jpg', '/3IFRjBDwtk0DlIsDfJ2zEzLjUBi.jpg', '87E6N7ToCxs'),
    (82693, 'After losing his job and wife, and spending time in an institution, a former teacher winds up living with his parents. He wants to rebuild his life and reconcile with his wife, but his father would be happy if he shared his obsession with the Philadelphia Eagles. Things get complicated when he meets Tiffany Maxwell who offers to help him reconnect with his wife if he will do something very important for her in exchange.', 122, '/fhHB1uvfFKKFbj6bTKE8xdtsjKi.jpg', '/12GpsUm9nVVKFlcjDTflKLClFVA.jpg', 'EI_3ywJLQio'),
    (82695, 'An adaptation of the successful stage musical based on Victor Hugo''s classic novel set in 19th-century France. Jean Valjean, a man imprisoned for stealing bread, must flee a relentless policeman named Javert. The pursuit consumes both men''s lives, and soon Valjean finds himself in the midst of the student revolutions in France.', 158, '/6CuzBs2Lb8At7qQr64mLXg2RYRb.jpg', '/bsG8LkZx1ijrcf3fP6AvBlGTxkX.jpg', '28sHoKcpugw'),
    (82700, 'One thousand years after cataclysmic events forced humanity''s escape from Earth, Nova Prime has become mankind''s new home. Legendary General Cypher Raige returns from an extended tour of duty to his estranged family, ready to be a father to his 13-year-old son, Kitai. When an asteroid storm damages Cypher and Kitai''s craft, they crash-land on a now unfamiliar and dangerous Earth. As his father lies dying in the cockpit, Kitai must trek across the hostile terrain to recover their rescue beacon. His whole life, Kitai has wanted nothing more than to be a soldier like his father. Today, he gets his chance.', 100, '/iXMvYIlzzJBs352CfeiQcBvovZt.jpg', '/e3posvSzYf9PjrQg27W64Kyc8qq.jpg', '-r9IXze_tPM'),
    (82702, 'Five years after uniting the dragons and Vikings of Berk, Hiccup and Toothless soar beyond their homeland, charting the vast unknown. During one of their adventures, the pair discover a secret cave that houses hundreds of wild dragons—and a mysterious dragon rider with a startling connection to Hiccup. And as the ruthless conqueror Drago Bludvist rises to seize control of both dragons and people alike, Hiccup must step into his role as a true leader and, alongside his friends and Toothless, protect Berk from a devastating war.', 102, '/d13Uj86LdbDLrfDoHR5aDOFYyJC.jpg', '/8AAuJtCzaibYkbE0QVHc8EBsELB.jpg', '1Y0erVF9cLI'),
    (82703, 'A young boy and his dog, who happens to have a genius-level IQ, spring into action when their time-machine is stolen and moments in history begin to be changed.', 92, '/hPcImYndWESKHzT2GHVCDsUxzYg.jpg', '/bJKoNFCLC0C3viZtsvP4lSDDXNO.jpg', 'aMl2tTVwsZA'),
    (82992, 'Hobbs has Dominic and Brian reassemble their crew to take down a team of mercenaries; Dominic unexpectedly gets sidetracked with facing his presumed deceased girlfriend, Letty.', 130, '/thSmnRdrzPBBospIOJjLZBReqzo.jpg', '/u1IfymTvKtftECKJR1vVF0mkvKV.jpg', '-1ysq_lKovg'),
    (83533, 'In the wake of the devastating war against the RDA and the loss of their eldest son, Jake Sully and Neytiri face a new threat on Pandora: the Ash People, a violent and power-hungry Na''vi tribe led by the ruthless Varang. Jake''s family must fight for their survival and the future of Pandora in a conflict that pushes them to their emotional and physical limits.', 198, '/bRBeSHfGHwkEpImlhxPmOcUsaeg.jpg', '/u8DU5fkLoM5tTRukzPC31oGPxaQ.jpg', 'Ma1x7ikpid8'),
    (83542, 'A set of six nested stories spanning time between the 19th century and a distant post-apocalyptic future. Cloud Atlas explores how the actions and consequences of individual lives impact one another throughout the past, the present and the future. Action, mystery and romance weave through the story as one soul is shaped from a killer into a hero and a single act of kindness ripples across centuries to inspire a revolution in the distant future.  Based on the award winning novel by David Mitchell. Directed by Tom Tykwer and the Wachowskis.', 172, '/8naVv2Xu3rWI5JKHz0vCujx6GaJ.jpg', '/sFDntG0Z0Wjrsz26TVptfs5OSLT.jpg', 'ByehYal_cCs'),
    (83666, 'Set on an island off the coast of New England in the summer of 1965, Moonrise Kingdom tells the story of two twelve-year-olds who fall in love, make a secret pact, and run away together into the wilderness. As various authorities try to hunt them down, a violent storm is brewing off-shore – and the peaceful island community is turned upside down in more ways than anyone can handle.', 94, '/y4SXcbNl6CEF2t36icuzuBioj7K.jpg', '/nv0WuVVLR3D5FYiJCJUQue7qjd3.jpg', 'RBCRe73dZb0'),
    (83899, 'When the Davison family comes under attack during their wedding anniversary getaway, the gang of mysterious killers soon learns that one of their victims harbors a secret talent for fighting back.', 96, '/l163jakfKvchUTVTtBi0KA7ZhIc.jpg', '/okjEw4GrEqn4seWkvUHIUXogQZD.jpg', '3ZKQU0YYkNw'),
    (84892, 'Pittsburgh, Pennsylvania, 1991. High school freshman Charlie is a wallflower, always watching life from the sidelines, until two senior students, Sam and her stepbrother Patrick, become his mentors, helping him discover the joys of friendship, music and love.', 103, '/aKCvdFFF5n80P2VdS7d8YBwbCjh.jpg', '/59ur074TVZ13QuQvRcubrEB3Izf.jpg', 'x0nTfbg24Qs'),
    (85350, 'The film tells a story of a divorced couple trying to raise their young son. The story follows the boy for twelve years, from first grade at age 6 through 12th grade at age 17-18, and examines his relationship with his parents as he grows.', 165, '/2BvtvDUyxiMJ4dmKfiQf4qdOHQN.jpg', '/qRwkMMZhQRKM4uDaXpd2XbZZmkE.jpg', 'oNC3NYWh1vI'),
    (85446, 'Emily arrives in Miami with aspirations to become a professional dancer. She sparks with Sean, the leader of a dance crew whose neighborhood is threatened by Emily''s father''s development plans.', 99, '/jMpwxmk3r7Aq36GcqMbCuP9DJYQ.jpg', '/9qM08KBrvuzENc0G9RzlzyVjkSm.jpg', 'aEAt9eTi72w'),
    (86825, 'Following her father Richard''s death in an unexplained road accident, reclusive teenager India Stoker withdraws further into the quiet rural life she shares with her emotionally disturbed mother Evie. But her curiosity is stirred when her mysterious uncle Charlie, who she has never met, suddenly arrives unannounced. Told that the darkly charismatic Charlie will now be staying at the house, India''s initial well-founded distrust of her uncle''s motivations begins to waver as she finds herself becoming ever more deeply entranced by his sinister charms.', 99, '/o0giW5oasaef5m9sgBuq0C7IkIa.jpg', '/yFop8dQmR7hvQaA7yzRb4gDSDoL.jpg', 'sOyxxhuvAmo'),
    (86834, 'A man who suffers visions of an apocalyptic deluge takes measures to protect his family from the coming flood.', 138, '/vVLkHabnF5lVpCpqyhZBI5iCYMA.jpg', '/5z75Q6nqgwgYfpMB9fVHQcw9gMz.jpg', 'fdu10cX3pWA'),
    (86838, 'A struggling screenwriter inadvertently becomes entangled in the Los Angeles criminal underworld after his oddball friends kidnap a gangster''s beloved Shih Tzu.', 110, '/4ukEYAxlSivFcDG6vLxJB6PjTjg.jpg', '/6KrodMTWn9hNZBhrwOYd8snqtVp.jpg', 'fUFUd5m7UH8'),
    (87101, 'The year is 2029. John Connor, leader of the resistance continues the war against the machines. At the Los Angeles offensive, John''s fears of the unknown future begin to emerge when TECOM spies reveal a new plot by SkyNet that will attack him from both fronts; past and future, and will ultimately change warfare forever.', 126, '/oZRVDpNtmHk8M1VYy1aeOWUXgbC.jpg', '/wvlIoof1FnKPLv9jAYanuP31V0C.jpg', 'Dx3ShEjUId0'),
    (87421, 'Betrayed by his own kind and left for dead on a desolate planet, Riddick fights for survival against alien predators and becomes more powerful and dangerous than ever before. Soon bounty hunters from throughout the galaxy descend on Riddick only to find themselves pawns in his greater scheme for revenge. With his enemies right where he wants them, Riddick unleashes a vicious attack of vengeance before returning to his home planet of Furya to save it from destruction.', 119, '/pUul9pGWOKT7X0smkTvsIEIQxcP.jpg', '/naGU49u4BXynQ1o5L755pfs8dom.jpg', 'au2xw42-8IA'),
    (87827, 'The story of an Indian boy named Pi, a zookeeper''s son who finds himself in the company of a hyena, zebra, orangutan, and a Bengal tiger after a shipwreck sets them adrift in the Pacific Ocean.', 127, '/iLgRu4hhSr6V1uManX6ukDriiSc.jpg', '/21YsCNMub5455NQCn3jh9SmRFyG.jpg', 'j9Hjrs6WQ8M'),
    (88751, 'On a quest to find out what happened to his missing brother, a scientist, his nephew and their mountain guide discover a fantastic and dangerous lost world in the center of the earth.', 93, '/kL55wY0s2H9JdwfjoWIp9plvYnl.jpg', '/Adlc8JMVEXOelFO6hYpIYcGBx2T.jpg', 'Dk0v8pe7tzw'),
    (91314, 'As humanity picks up the pieces after the battle of Chicago, a shadowy group reveals itself in an attempt to control the direction of history…while an ancient, powerful new menace sets Earth in its crosshairs. With help from Cade Yeager, Optimus Prime and the Autobots rise to meet their most fearsome challenge yet.', 165, '/jyzrfx2WaeY60kYZpPYepSjGz4S.jpg', '/wxr4Z6E83h14CogsZOzDm1vuDX3.jpg', 'S30VkLn5a2o'),
    (91586, 'The haunted Lambert family seeks to uncover the mysterious childhood secret that has left them dangerously connected to the spirit world.', 106, '/w5JjiB3O1CLDXbTJe1QpU5RHmlU.jpg', '/i9oyhCYxIYH2082J0Rc3a3jQjRB.jpg', 'aEByNYajexQ'),
    (93456, 'Gru is recruited by the Anti-Villain League to help deal with a powerful new super criminal.', 98, '/5Fh4NdoEnCjCK9wLjdJ9DJNFl2b.jpg', '/uD267eSiACfWLxp47t3gYymOQRj.jpg', 'EK3j98PHaGM'),
    (94329, 'Deep in the heart of Jakarta''s slums lies an impenetrable safe house for the world''s most dangerous killers and gangsters. Until now, the run-down apartment block has been considered untouchable to even the bravest of police. Cloaked under the cover of pre-dawn darkness and silence, an elite swat team is tasked with raiding the safe house in order to take down the notorious drug lord that runs it.  But when a chance encounter with a spotter blows their cover and news of their assault reaches the drug lord, the building''s lights are cut and all the exits blocked. Stranded on the sixth floor with no way out, the unit must fight their way through the city''s worst to survive their mission. Starring Indonesian martial arts sensation Iko Uwais.', 101, '/Abnm1Ws3JH0ReCfEhLMPwPcMcGO.jpg', '/3wf5wV222vqTmz10y1vbrPgrGDf.jpg', 'GDYwcjhvD-Y'),
    (96721, 'In the 1970s, a rivalry propels race car drivers Niki Lauda and James Hunt to fame and glory — until a horrible accident threatens to end it all.', 123, '/yqR7mzBKCv1ih6F2cXa0I8vFh3v.jpg', '/caKZWDGmv5iW2U99skHs75MmOmU.jpg', 'QKAr42gxjhM'),
    (97020, 'In RoboCop, the year is 2028 and multinational conglomerate OmniCorp is at the center of robot technology.  Overseas, their drones have been used by the military for years, but have been forbidden for law enforcement in America.  Now OmniCorp wants to bring their controversial technology to the home front, and they see a golden opportunity to do it.  When Alex Murphy – a loving husband, father and good cop doing his best to stem the tide of crime and corruption in Detroit – is critically injured, OmniCorp sees their chance to build a part-man, part-robot police officer.  OmniCorp envisions a RoboCop in every city and even more billions for their shareholders, but they never counted on one thing: there is still a man inside the machine.', 118, '/gM5ql3BKYmHG3WtZ0buKXN7xY8O.jpg', '/xACuC5FwpCdayrcCsJPxYzrl8BO.jpg', '_w_BPRUdmsQ'),
    (97367, 'A motorcycle stunt rider considers committing a crime in order to provide for his wife and child, an act that puts him on a collision course with a cop-turned-politician.', 140, '/vY5j2xQzMGWmxBuhQo0HfA4Lxqb.jpg', '/qCsaZ2GoaCn5vmOUD9kCsyabr9o.jpg', 'KepnbJT5nBw'),
    (97370, 'A seductive stranger prowls the streets of Glasgow in search of prey: unsuspecting men who fall under her spell.', 108, '/55wmcXJIDYITr7JDijJTdvwSaAv.jpg', '/eS5OdKN3kRZXQbWRSSCJ4Gh0z26.jpg', 'J7bAZCOk0Sc'),
    (97630, 'A chronicle of the decade-long hunt for al-Qaeda terrorist leader Osama bin Laden after the September 2001 attacks, and his death at the hands of the Navy S.E.A.L. Team 6 in May, 2011.', 157, '/wNSdSSxowM3WIqmPJNg3RagYbwP.jpg', '/evPzxMacNWsjkUKQO4NXKe5Rl6a.jpg', 'k7R2uVZYebE'),
    (98566, 'When a kingpin threatens New York City, a group of mutated turtle warriors must emerge from the shadows to protect their home.', 101, '/azL2ThbJMIkts3ZMt3j1YgBUeDB.jpg', '/eezsbzYPbYKjjh6E1XHDBNlLynh.jpg', 'dwXFsrp6WBs'),
    (99861, 'When Tony Stark tries to jumpstart a dormant peacekeeping program, things go awry and Earth’s Mightiest Heroes are put to the ultimate test as the fate of the planet hangs in the balance. As the villainous Ultron emerges, it is up to The Avengers to stop him from enacting his terrible plans, and soon uneasy alliances and unexpected action pave the way for an epic and unique global adventure.', 141, '/4ssDuvEDkSArWEdyBl2X5EHvYKU.jpg', '/kIBK5SKwgqIIuRKhhWrJn3XkbPq.jpg', 'JAUoeqvedMo'),
    (100402, 'After the cataclysmic events in New York with The Avengers, Steve Rogers, aka Captain America is living quietly in Washington, D.C. and trying to adjust to the modern world. But when a S.H.I.E.L.D. colleague comes under attack, Steve becomes embroiled in a web of intrigue that threatens to put the world at risk. Joining forces with the Black Widow, Captain America struggles to expose the ever-widening conspiracy while fighting off professional assassins sent to silence him at every turn. When the full scope of the villainous plot is revealed, Captain America and the Black Widow enlist the help of a new ally, the Falcon. However, they soon find themselves up against an unexpected and formidable enemy—the Winter Soldier.', 136, '/tVFRpFw3xTedgPGqxW0AOI8Qhh0.jpg', '/aZBZtLCM90QHDCuZFR6oc4NXCWu.jpg', '7SlILk2WMTI'),
    (101299, 'After surviving the Hunger Games, Katniss and Peeta struggle with the consequences of their victory as unrest spreads across Panem. Forced back into the spotlight, they become symbols of hope and resistance while the Capitol prepares a new and deadly challenge that will change the future of the nation forever.', 146, '/vrQHDXjVmbYzadOXQ0UaObunoy2.jpg', '/eHaazLxM5LRMh0ySkVy7SK6wUWt.jpg', 'zoKj7TdJk98'),
    (102382, 'For Peter Parker, life is busy. Between taking out the bad guys as Spider-Man and spending time with the person he loves, Gwen Stacy, high school graduation cannot come quickly enough. Peter has not forgotten about the promise he made to Gwen’s father to protect her by staying away, but that is a promise he cannot keep. Things will change for Peter when a new villain, Electro, emerges, an old friend, Harry Osborn, returns, and Peter uncovers new clues about his past.', 141, '/bU7nTmvmy0h3VUP01v1T2imgH6N.jpg', '/k0hlAzTryCYX1O1LyC6P8tAa8s0.jpg', 'DlM2CWNTQ84'),
    (102651, 'A beautiful, pure-hearted young woman, Maleficent has an idyllic life growing up in a peaceable forest kingdom, until one day when an invading army threatens the harmony of the land. She rises to be the land''s fiercest protector, but she ultimately suffers a ruthless betrayal – an act that begins to turn her heart into stone. Bent on revenge, Maleficent faces an epic battle with the invading King''s successor and, as a result, places a curse upon his newborn infant Aurora. As the child grows, Maleficent realizes that Aurora holds the key to peace in the kingdom – and to Maleficent''s true happiness as well.', 97, '/ik8PugpL41s137RAWEGTAWu0dPo.jpg', '/xjotE7aFdZ0D8aGriYjFOtDayct.jpg', '28U4LxdkNWI'),
    (102899, 'Armed with the astonishing ability to shrink in scale but increase in strength, master thief Scott Lang must embrace his inner-hero and help his mentor, Doctor Hank Pym, protect the secret behind his spectacular Ant-Man suit from a new generation of towering threats. Against seemingly insurmountable obstacles, Pym and Lang must plan and pull off a heist that will save the world.', 117, '/rQRnQfUl3kfp78nCWq8Ks04vnq1.jpg', '/1K3JmSNUN8OpjYsCjc0Hy0SYxAb.jpg', 'cx3joJnXydc'),
    (103620, 'As he helps a young artist with her upcoming exhibition, the owner of a mannequin shop''s deadly, suppressed desires come to the surface.', 89, '/nbDkRvhmbYnHDXkoq0sF0PLeo8j.jpg', '/6x9MC5ELoeJl7Wzl32ZlfsaDViK.jpg', 'R5IS6XSXQ_s'),
    (103663, 'A teacher lives a lonely life, all the while struggling over his son’s custody. His life slowly gets better as he finds love and receives good news from his son, but his new luck is about to be brutally shattered by an innocent little lie.', 116, '/jkixsXzRh28q3PCqFoWcf7unghT.jpg', '/jmVWlCZ8hRtmrQGbKXXFHsrSohp.jpg', 'BSVDnUgJVYY'),
    (105864, 'An epic journey into the world of dinosaurs where an Apatosaurus named Arlo makes an unlikely human friend.', 93, '/8RSkxOO80btfKjyiC5ZiTaCHIT8.jpg', '/cF3H9pyUF6dsvqlYUcH0TyBAMTG.jpg', 'daFnEiLEx70'),
    (106646, 'A New York stockbroker refuses to cooperate in a large securities fraud case involving corruption on Wall Street, corporate banking world and mob infiltration. Based on Jordan Belfort''s autobiography.', 180, '/kW9LmvYHAaS9iA0tHmZVq8hQYoq.jpg', '/7Nwnmyzrtd0FkcRyPqmdzTPppQa.jpg', 'Slj4-Sv-YNA'),
    (107846, 'Ray Breslin is the world''s foremost authority on structural security. After analyzing every high security prison and learning a vast array of survival skills so he can design escape-proof prisons, his skills are put to the test. He''s framed and incarcerated in a master prison he designed himself. He needs to escape and find the person who put him behind bars.', 115, '/qOZPLflxDqKogu9v9hYw3lolxGs.jpg', '/ix9WYBqQ2xSZCgyeQ1vVdrbaFa4.jpg', 'BrV-SXI6Nmo'),
    (109418, 'Lenny has relocated his family back to the small town where he and his friends grew up. This time around, the grown ups are the ones learning lessons from their kids on a day notoriously full of surprises—the last day of school.', 101, '/hT6ijOtjtYrnyDhN7VA2QWyGFAm.jpg', '/7JhsJxNmdW0y4IyNrHy10cECrAz.jpg', 'EClDbUb-bgc'),
    (109424, 'The true story of Captain Richard Phillips and the 2009 hijacking by Somali pirates of the US-flagged MV Maersk Alabama, the first American cargo ship to be hijacked in two hundred years.', 134, '/8Td0kkocW6sD3uRpzwfMfkqMWhx.jpg', '/fLrGQzvfhTwn9m7AqlJh65FMFfG.jpg', 'TzU3UJuV80w'),
    (109443, 'With the 70s behind him, San Diego''s top rated newsman, Ron Burgundy, returns to take New York''s first 24-hour news channel by storm.', 119, '/BAdmxMdCqzjs6hx3KuEtnoWP8d.jpg', '/hYY7wC3vuwSmoRdcMalVMjPC0a0.jpg', '6VdGI5-z_hg'),
    (109445, 'Young princess Anna of Arendelle dreams about finding true love at her sister Elsa’s coronation. Fate takes her on a dangerous journey in an attempt to end the eternal winter that has fallen over the kingdom. She''s accompanied by ice delivery man Kristoff, his reindeer Sven, and snowman Olaf. On an adventure where she will find out what friendship, courage, family, and true love really means.', 102, '/itAKcobTYGpYT8Phwjd8c9hleTo.jpg', '/rj58WQ9ImI0mYDptXdM7euX1Wjt.jpg', 'TbQm5doF_Uc'),
    (109451, 'After the disastrous food storm in the first film, Flint and his friends are forced to leave the town. Flint accepts the invitation from his idol Chester V to join The Live Corp Company, which has been tasked to clean the island, and where the best inventors in the world create technologies for the betterment of mankind. When Flint discovers that his machine still operates and now creates mutant food beasts like living pickles, hungry tacodiles, shrimpanzees and apple pie-thons, he and his friends must return to save the world.', 95, '/ss5NcK2NWFg2YcKKYXLrk8q1myS.jpg', '/vWriOBVlgW0XWdgbOiijhyLW7B8.jpg', '3QCJTbHU60U'),
    (110415, 'In a future where a failed global-warming experiment kills off most life on the planet, a class system evolves aboard the Snowpiercer; a train that travels around the globe via a perpetual-motion engine.', 127, '/kw6YQudA0TMcNmGUGy5XIw7zbnV.jpg', '/55vkNtb83bSwbdWrQTVZTGLBcLx.jpg', '3Np3v7xnNJk'),
    (110420, 'After her werewolf lover unexpectedly dies in an accident, a woman must find a way to raise the son and daughter that she had with him. However, their inheritance of their father''s traits prove to be a challenge for her.', 117, '/vHMvBkr42Gh3OORcnmfCFfqJ1E.jpg', '/oMqgJMCaNIqeJtilc71D4nRqdmt.jpg', 'SmhtOXCmTSY'),
    (112454, 'A loving father finds a clown suit for his son''s birthday party, only to realize the suit is part of an evil curse that turns its wearer into a killer.', 99, '/gp5QyaU49utfWVVL698BzlN2vMh.jpg', '/8tAI0aEjGSU6AE6lUaqDniYPVbK.jpg', 'PNtZu-3di38'),
    (114150, 'College student Beca knows she does not want to be part of a clique, but that''s exactly where she finds herself after arriving at her new school. Thrust in among mean gals, nice gals and just plain weird gals, Beca finds that the only thing they have in common is how well they sing together. She takes the women of the group out of their comfort zone of traditional arrangements and into a world of amazing harmonic combinations in a fight to the top of college music competitions.', 112, '/gsFoJk9g8W3zgaipRrrURk7LbiF.jpg', '/2sE6hrwfn9IV7eDlMvpIb9q1EWy.jpg', 'HXnjePW3ysU'),
    (116149, 'A young Peruvian bear travels to London in search of a home. Finding himself lost and alone at Paddington Station, he meets the kindly Brown family, who offer him a temporary haven.', 95, '/wpchRGhRhvhtU083PfX2yixXtiw.jpg', '/kfofK4GzJsJZhCShqZY438c8Y4Y.jpg', '5HiJSERyg2w'),
    (116711, 'A teenager finds herself transported to a deep forest setting where a battle between the forces of good and the forces of evil is taking place. She bands together with a rag-tag group of characters in order to save their world—and ours.', 102, '/81cSsWzjTfR3cJSqnTiHwy1eyPK.jpg', '/zFyuN8vF2XNSzxIdACES0IyNrhK.jpg', '_KqNCnd8AN4'),
    (116741, 'Two recently laid-off men in their 40s try to make it as interns at a successful Internet company where their managers are in their 20s.', 119, '/hIh3ZgsZ31nbUAGn5SKIZGKiKCX.jpg', '/kms4PhWfP1Q2jidPLOf26qm0paJ.jpg', 'G3W6IESxRKs'),
    (116745, 'A timid magazine photo manager who lives life vicariously through daydreams embarks on a true-life adventure when a negative goes missing.', 114, '/iAo1hlzsPV9XpYcLQp6Ud065tGO.jpg', '/8hSjOHRY4OUEpqxszYbMdem8z9C.jpg', 'Bp_cxxqOaPM'),
    (117251, 'Capitol Policeman John Cale has just been denied his dream job with the Secret Service protecting President James Sawyer. Not wanting to let down his little girl with the news, he takes her on a tour of the White House, when the complex is overtaken by a heavily armed paramilitary group. Now, with the nation''s government falling into chaos and time running out, it''s up to Cale to save the president, his daughter, and the country.', 131, '/6TeIVKPw7nXXWy2zKmDmlnSwzb7.jpg', '/eVidMQ5eXDhRizo9ig1X4iWCDqe.jpg', 'aVzMUz3coio'),
    (117263, 'When the White House (Secret Service Code: "Olympus") is captured by a terrorist mastermind and the President is kidnapped, disgraced former Presidential guard Mike Banning finds himself trapped within the building. As the national security team scrambles to respond, they are forced to rely on Banning''s inside knowledge to help retake the White House, save the President and avert an even bigger disaster.', 120, '/u3GTFGwesNBNd0t1hiLaEk1iqZU.jpg', '/mjYU7EwVeOtM39ArdWHZk78VhYm.jpg', '74F_pts7Uhg'),
    (118340, 'Light years from Earth, 26 years after being abducted, Peter Quill finds himself the prime target of a manhunt after discovering an orb wanted by Ronan the Accuser.', 121, '/r7vmZjiyZw9rpJMQJdXpjgiCOk9.jpg', '/uLtVbjvS1O7gXL8lUOwsFOH4man.jpg', '3CqymRQ1uUU'),
    (119283, 'A thief with a unique code of professional ethics is double-crossed by his crew and left for dead. Assuming a new disguise and forming an unlikely alliance with a woman on the inside, he looks to hijack the score of the crew''s latest heist.', 118, '/ocTaizFzASVPClHsx6VRBi5yP9Z.jpg', '/7ZUluM7tUW0nRD3WXkmAF5kDfB9.jpg', '2rIlk-Jk3lw'),
    (119450, 'A group of scientists in San Francisco struggle to stay alive in the aftermath of a plague that is wiping out humanity, while Caesar tries to maintain dominance over his community of intelligent apes.', 130, '/mSmAc9G25fhOHH45SLEeagR0qi7.jpg', '/3SozaNPOYUadcmTPgndDibMyDNC.jpg', 'DpSaTrW4leg'),
    (120467, 'The Grand Budapest Hotel tells of a legendary concierge at a famous European hotel between the wars and his friendship with a young employee who becomes his trusted protégé. The story involves the theft and recovery of a priceless Renaissance painting, the battle for an enormous family fortune and the slow and then sudden upheavals that transformed Europe during the first half of the 20th century.', 100, '/eWdyYQreja6JGCzqHWXpWHDrrPo.jpg', '/jK65srQczOKTpW62wPxwwKztGgE.jpg', 'G1jG8HUY4zI'),
    (121856, 'Through a technology that unlocks the genetic memories of his ancestor in 15th century Spain, Callum Lynch discovers he is a descendant of an ancient line of Assassins and amasses lethal skills to take on the oppressive Templar Order.', 116, '/kDXewoEcvbn0pUvJ8W3vfkuWgHw.jpg', '/e29oMyfzzlWbhRlCBrzmZhlsw2m.jpg', 'vzWVVla8WWA'),
    (122906, 'The night after another unsatisfactory New Year''s party, Tim''s father reveals to him that the men in their family have the ability to travel through time. They can''t change history, but they can change what happens and has happened in their own lives. Thus begins the start of a lesson in learning to appreciate life itself as it is, as it comes, and most importantly, the people living alongside us.', 123, '/ls6zswrOZVhCXQBh96DlbnLBajM.jpg', '/einbto9qLXFx9QXxEHylaxDbKPx.jpg', '7OIFdWk83no'),
    (122917, 'Following Smaug''s attack on Laketown, Bilbo and the dwarves try to defend Erebor''s mountain of treasure from others who claim it: the men of the ruined Laketown and the elves of Mirkwood. Meanwhile an army of Orcs led by Azog the Defiler is marching on Erebor, fueled by the rise of the dark lord Sauron. Dwarves, elves and men must unite, and the hope for Middle-Earth falls into Bilbo''s hands.', 144, '/xT98tLqatZPQApyRmlPL12LtiWp.jpg', '/3UbaCMmqOd7mca4Y5DOzY2ZVTyX.jpg', 'Y6Fv5StfAxA'),
    (123553, 'In New York City, Clary Fray, a seemingly ordinary teenager, learns that she is descended from a line of Shadowhunters — half-angel warriors who protect humanity from evil forces. After her mother disappears, Clary joins forces with a group of Shadowhunters and enters Downworld, an alternate realm filled with demons, vampires, and a host of other creatures. Clary and her companions must find and protect an ancient cup that holds the key to her mother''s future.', 130, '/fspW2P3ggzBjdIw5HpJOw8HKtQK.jpg', '/jgpzrdDoWrthKFDmMNXebVR2a2M.jpg', 'RbA0ufF5A8E'),
    (124905, 'Ford Brody, a Navy bomb expert, has just reunited with his family in San Francisco when he is forced to go to Japan to help his estranged father, Joe. Soon, both men are swept up in an escalating crisis when an ancient alpha predator arises from the sea to combat malevolent adversaries that threaten the survival of humanity. The creatures leave colossal destruction in their wake, as they make their way toward their final battleground: San Francisco.', 123, '/tphkjmQq8WebuVwNXelmjLUXuPJ.jpg', '/6CLNOzMXO9bvapDD8gsdwkJU4wN.jpg', 'oHKGx1pzczg'),
    (125509, 'A small West Virginia town is hosting the legendary Mountain Man Festival on Halloween, where throngs of costumed party goers gather for a wild night of music and mischief. But an inbred family of hillbilly cannibals kill the fun when they trick and treat themselves to a group of visiting college students.', 91, '/8fABep8FSRpeo8Ea4j3rfnoVgkg.jpg', '/6PTWsiDugvnI44QwmP2f2Yq2fhN.jpg', '5yi0aIRi3eg'),
    (126889, 'The crew of the colony ship Covenant, bound for a remote planet on the far side of the galaxy, discovers what they think is an uncharted paradise but is actually a dark, dangerous world.', 122, '/zecMELPbU5YMQpC81Z8ImaaXuf9.jpg', '/iXXPaQPfQowpQ5UvhsHLj9BgFhe.jpg', 'svnAD0TApb8'),
    (127380, 'Dory is reunited with her friends Nemo and Marlin in the search for answers about her past. What can she remember? Who are her parents? And where did she learn to speak Whale?', 97, '/3UVe8NL1E2ZdUZ9EDlKGJY5UzE.jpg', '/wijltj1toRcicHlCn8Cpsp4yPXe.jpg', 'NQu-153MnGQ'),
    (127585, 'The ultimate X-Men ensemble fights a war for the survival of the species across two time periods as they join forces with their younger selves in an epic battle that must change the past – to save our future.', 132, '/tYfijzolzgoMOtegh1Y7j2Enorg.jpg', '/3czpqXzFy5UcNuD1AubecRLWkwD.jpg', 'gsjtg7m1MMM'),
    (131631, 'After surviving the Quarter Quell, Katniss finds herself in the hidden stronghold of District 13, where the rebellion against the Capitol is gaining momentum. Struggling with the weight of becoming the symbol of resistance, she must navigate fragile alliances while trying to protect those she loves. As propaganda battles rage and Panem moves closer to full-scale war, Katniss is forced to confront the true cost of revolution.', 123, '/4FAA18ZIja70d1Tu5hr5cj2q1sB.jpg', '/lV1P1Q5gLDXVG1ZYCxZHStkcQC3.jpg', 'IXshQ5mv1K8'),
    (131634, 'As the war between the Capitol and the districts reaches its peak, Katniss Everdeen embarks on a perilous mission to liberate Panem and confront President Snow. Joined by a team of trusted allies, she navigates deadly traps, shifting loyalties, and the heavy cost of rebellion, determined to bring freedom to her people and end the Hunger Games once and for all.', 137, '/lImKHDfExAulp16grYm8zD5eONE.jpg', '/qVgLMRVNB5bHU0inmRa0ueShacN.jpg', 'SoKIqLEGhI0'),
    (132232, 'Guillermo del Toro presents Mama, a supernatural thriller that tells the haunting tale of two little girls who disappeared into the woods the day that their parents were killed. When they are rescued years later and begin a new life, they find that someone or something still wants to come tuck them in at night.', 100, '/eo8BhR8Q5STmWE9sMLsEPagxmy6.jpg', '/cu3uaBqPORcfpKQWaIjA1GJbvEg.jpg', '1lNyP7w3CuQ'),
    (133805, 'An awkward, telekinetic teenage girl is the object of relentless bullying at school and an oppressively religious mother at home.', 101, '/kloXz9qwO23z9Kbt3z3MgnjF4xO.jpg', '/ffi2k8g5NOXbfwYhpg0HyZfx5Vz.jpg', 'szzw_SQlfpU'),
    (135397, 'Twenty-two years after the events of Jurassic Park, Isla Nublar now features a fully functioning dinosaur theme park, Jurassic World, as originally envisioned by John Hammond.', 124, '/bkXjL03yWPmiuFqxWEp4zSYVZBY.jpg', '/dF6FjTZzRTENfB4R17HDN20jLT2.jpg', 'aJJrkyHas78'),
    (136400, 'A DEA agent and an undercover Naval Intelligence officer who have been tasked with investigating one another find they have been set up by the mob -- the very organization the two men believe they have been stealing money from.', 109, '/ptURGAFktibhk7DEAbMazlmNqWa.jpg', '/swyPgOP2lffHfMjeZKNnNFR9P88.jpg', 'AK6EbfdnTHg'),
    (136797, 'The film revolves around a local street-racer who partners with a rich and arrogant business associate, only to find himself framed by his colleague and sent to prison. After he gets out, he joins a New York-to-Los Angeles race to get revenge. But when the ex-partner learns of the scheme, he puts a massive bounty on the racer''s head, forcing him to run a cross-country gauntlet of illegal racers in all manner of supercharged vehicles.', 132, '/4ktdbrhCnAoDGLW36afjB717Sa.jpg', '/syVAWAnY6fTBDDFntHsM8vFjKex.jpg', 'e73J71RZRn8'),
    (136799, 'After the monstrous Bergens invade Troll Village, Princess Poppy, the happiest Troll ever born, and overly-cautious, curmudgeonly outcast Branch set off on a journey to rescue her friends. Their mission is full of adventure and mishaps, as this mismatched duo try to tolerate each other long enough to get the job done.', 92, '/9VlK2j0THZWzhQPq0W3Oc0IIdBB.jpg', '/gXyYOWAkk4FdQU3adK8WFj8nN9J.jpg', 'xyjm5VQ11TQ'),
    (137106, 'An ordinary Lego mini-figure, mistakenly thought to be the extraordinary MasterBuilder, is recruited to join a quest to stop an evil Lego tyrant from conquering the universe.', 100, '/lbctonEnewCYZ4FYoTZhs8cidAl.jpg', '/6gI1dAkOaUQ6659OdRPsTLlsem5.jpg', 'fZ_JOBCLF-I'),
    (137113, 'Major Bill Cage is an officer who has never seen a day of combat when he is unceremoniously demoted and dropped into combat. Cage is killed within minutes, managing to take an alpha alien down with him. He awakens back at the beginning of the same day and is forced to fight and die again... and again - as physical contact with the alien has thrown him into a time loop.', 114, '/nBM9MMa2WCwvMG4IJ3eiGUdbPe6.jpg', '/4V1yIoAKPMRQwGBaSses8Bp2nsi.jpg', 'eb8wTIcGLgQ'),
    (138103, 'Barney, Christmas and the rest of the team comes face-to-face with Conrad Stonebanks, who years ago co-founded The Expendables with Barney. Stonebanks subsequently became a ruthless arms trader and someone who Barney was forced to kill… or so he thought. Stonebanks, who eluded death once before, now is making it his mission to end The Expendables -- but Barney has other plans. Barney decides that he has to fight old blood with new blood, and brings in a new era of Expendables team members, recruiting individuals who are younger, faster and more tech-savvy. The latest mission becomes a clash of classic old-school style versus high-tech expertise in the Expendables’ most personal battle yet.', 126, '/utS5euWHlEdKBNnEFwjpZ2oGuhF.jpg', '/xSfBWkAarrPwwfiGBAMt8wqxUUH.jpg', 'KATn_m-AX9I'),
    (140300, 'While Po and his father are visiting a secret panda village, an evil spirit threatens all of China, forcing Po to form a ragtag army to fight back.', 95, '/oajNi4Su39WAByHI6EONu8G8HYn.jpg', '/s3FiHTdpQVpqIqdBxLLiy40wGut.jpg', 'yqN7nHM1YTA'),
    (140607, 'Thirty years after defeating the Galactic Empire, Han Solo and his allies face a new threat from the evil Kylo Ren and his army of Stormtroopers.', 136, '/wqnLdwVXoBjKibFRR5U3y0aDUhs.jpg', '/8BTsTfln4jlQrLXUBquXJ0ASQy9.jpg', 'sGbxmsDFVnE'),
    (140823, 'Author P.L. Travers looks back on her childhood while reluctantly meeting with Walt Disney, who seeks to adapt her Mary Poppins books for the big screen.', 126, '/4RkcUe5PKnYvrCwMjk8giUAoID7.jpg', '/7jyGyVB72hHPLjPQu4hqDGCaraK.jpg', 'nijccxWvyXU'),
    (141052, 'Fuelled by his restored faith in humanity and inspired by Superman''s selfless act, Bruce Wayne and Diana Prince assemble a team of metahumans consisting of Barry Allen, Arthur Curry and Victor Stone to face the catastrophic threat of Steppenwolf and the Parademons who are on the hunt for three Mother Boxes on Earth.', 120, '/eifGNCSDuxJeS1loAXil5bIGgvC.jpg', '/2nyaeISu2xIxIgZYNpX4UayY8PN.jpg', 'PXrgvNXfN7M'),
    (146216, 'Retired C.I.A. agent Frank Moses reunites his unlikely team of elite operatives for a global quest to track down a missing portable nuclear device.', 116, '/kMTG8jcjqFlq4A2GF3rpgbz73pF.jpg', '/gd2vQT8uMf1FAsiC0OdewL7XUFR.jpg', '56vPzBENK9Y'),
    (146233, 'After his six-year-old daughter is abducted, a desperate father takes justice into his own hands when he loses faith in the detective leading the investigation, setting both men on a collision course as the search descends into obsession and moral compromise.', 153, '/uhviyknTT5cEQXbn6vWIqfM4vGm.jpg', '/3RFmTz5h2UuFWEV4oH00XICBR9y.jpg', 'yszyHq-S9W8'),
    (147441, 'The defiant leader Moses rises up against the Egyptian Pharaoh Ramses, setting 400,000 slaves on a monumental journey of escape from Egypt and its terrifying cycle of deadly plagues.', 150, '/uaDj37JtvLan9tihxZ18e6qL33b.jpg', '/hJ1jUw8irCiWwQk7BElxF92BrlK.jpg', '6k8qeqZycgE'),
    (149870, 'A lifelong love of flight inspires Japanese aviation engineer Jiro Horikoshi, whose storied career includes the creation of the A-6M World War II fighter plane.', 126, '/jfwSexzlIzaOgxP9A8bTA6t8YYb.jpg', '/938lqhAQaO3hmLg44VbUR7OqlMs.jpg', 'q3kdZpeVbLM'),
    (150540, 'When 11-year-old Riley moves to a new city, her Emotions team up to help her through the transition. Joy, Fear, Anger, Disgust and Sadness work together, but when Joy and Sadness get lost, they must journey through unfamiliar places to get back home.', 95, '/2H1TmgdfNtsKlU9jKdeNyYL5y8T.jpg', '/jJKZaTBNenlFclQyjrnvzkRmvWE.jpg', '1HFv47QHWJU'),
    (150689, 'When her father unexpectedly passes away, young Ella finds herself at the mercy of her cruel stepmother and her daughters. Never one to give up hope, Ella''s fortunes begin to change after meeting a dashing stranger in the woods.', 105, '/j91LJmcWo16CArFOoapsz84bwxb.jpg', '/q7vmCCmyiHnuKGMzHZlr0fD44b9.jpg', 'n44EWI92Tc8'),
    (152601, 'In the not so distant future, Theodore, a lonely writer, purchases a newly developed operating system designed to meet the user''s every need. To Theodore''s surprise, a romantic relationship develops between him and his operating system. This unconventional love story blends science fiction and romance in a sweet tale that explores the nature of love and the ways that technology isolates and connects us all.', 126, '/eCOtqtfvn7mxGl6nfmq4b1exJRc.jpg', '/1YnZchmaGc8dchgRPDpR1KGrixA.jpg', 'ne6p6MfLBxc'),
    (152760, 'Based on the true story of the greatest treasure hunt in history, The Monuments Men is an action drama focusing on seven over-the-hill, out-of-shape museum directors, artists, architects, curators, and art historians who went to the front lines of WWII to rescue the world’s artistic masterpieces from Nazi thieves and return them to their rightful owners.  With the art hidden behind enemy lines, how could these guys hope to succeed?', 118, '/wiWAg4mKV2S4vImPxsPRIdj2R2B.jpg', '/vsLrBh3MALRGRB1pMErDQQz3l3c.jpg', 'oBfMOmR4S9M'),
    (153518, 'An island populated entirely by happy, flightless birds or almost entirely. In this paradise, Red, a bird with a temper problem, speedy Chuck, and the volatile Bomb have always been outsiders. But when the island is visited by mysterious green piggies, it’s up to these unlikely outcasts to figure out what the pigs are up to.', 97, '/iOH0fEFtV9z9rZp9zmBFGGeWicv.jpg', '/o4mhrLxv6I70kvYA42qANGUF7ya.jpg', 'Hksyh33N5dg'),
    (156022, 'McCall believes he has put his mysterious past behind him and dedicated himself to beginning a new, quiet life. But when he meets Teri, a young girl under the control of ultra-violent Russian gangsters, he can’t stand idly by – he has to help her. Armed with hidden skills that allow him to serve vengeance against anyone who would brutalize the helpless, McCall comes out of his self-imposed retirement and finds his desire for justice reawakened. If someone has a problem, if the odds are stacked against them, if they have nowhere else to turn, McCall will help. He is The Equalizer.', 132, '/9u4yW7yPA0BQ2pv9XwiNzItwvp8.jpg', '/9vAoubhoZE8aSkUZoSfxs3UWZhO.jpg', 'BP_FwE0Z7no'),
    (157336, 'The adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.', 169, '/yQvGrMoipbRoddT0ZR8tPoR7NfX.jpg', '/8sNiAPPYU14PUepFNeSNGUTiHW.jpg', 'LY19rHKAaAg'),
    (157350, 'In a world divided into factions based on personality types, Tris learns that she''s been classified as Divergent and won''t fit in. When she discovers a plot to destroy Divergents, Tris and the mysterious Four must find out what makes Divergents dangerous before it''s too late.', 140, '/aNh4Q3iuPKDMPi2SL7GgOpiLukX.jpg', '/bgkFOoXEQMRjKkCvgoj7smdGbuh.jpg', 'WI1Jqx47Uw8'),
    (157353, 'Two leading computer scientists work toward their goal of Technological Singularity,  as a radical anti-technology organization fights to prevent them from creating a world where computers can transcend the abilities of the human brain.', 119, '/i3JqPtiJWnidaif3UA2K2Eng0hp.jpg', '/ypuD6ZsupyVV1ElNSIPz2BooIlX.jpg', 'QheoYw1BKJ4'),
    (157433, 'Dr. Louis Creed and his wife, Rachel, move from Boston to Ludlow, in rural Maine, with their two young children. Hidden in the woods near the new family home, Ellie, their eldest daughter, discovers a mysterious cemetery where the pets of community members are buried.', 101, '/7SPhr7Qj39vbnfF9O2qHRYaKHAL.jpg', '/8iZjnNSIH4teZERl0VjUeHHVrec.jpg', 'XakmsXltPkA'),
    (158011, 'Jordan Turner is an experienced 911 operator but when she makes an error in judgment and a call ends badly, Jordan is rattled and unsure if she can continue. But when teenager Casey Welson is abducted in the back of a man''s car and calls 911, Jordan is the one called upon to use all of her experience, insights and quick thinking to help Casey escape, and not just to save her, but to make sure the man is brought to justice.', 96, '/mG334OlDVJpD8gMfTCM2Mpp0gQH.jpg', '/9jih8et3fkd0Zdo4NHf3cnPj05Z.jpg', 'LHrZxG9W3RI'),
    (158852, 'Bound by a shared destiny, a bright, optimistic teen bursting with scientific curiosity and a former boy-genius inventor jaded by disillusionment embark on a danger-filled mission to unearth the secrets of an enigmatic place somewhere in time and space that exists in their collective memory as "Tomorrowland."', 130, '/kziYpr5Nfw60P0My8aj1sgCEqed.jpg', '/udYOmbW1JEZjVd726PWHlmptxPi.jpg', '4kAHjjNL7ms'),
    (159824, 'When the old-old-old-fashioned vampire Vlad arrives at the hotel for an impromptu family get-together, Hotel Transylvania is in for a collision of supernatural old-school and modern day cool.', 89, '/3nFnrivNgipSKZ8LZJJbRSlAcTR.jpg', '/mfnkxXWuh2Br097Qteq8ieqKfev.jpg', '65YG3cGGj5A'),
    (160588, 'After experiencing a traumatic misfortune, Jasmine French, a wealthy woman from New York, moves to San Francisco to live with her foster sister Ginger and the firm purpose of getting a new life, but she will be haunted by anxiety and memories of the past.', 99, '/kh0q3HD0WQhfbdPx0zG0a0nb9gH.jpg', '/jDJCWtxwHRhFhhlm2vIV8ktOtJM.jpg', '3UBv1S4Ajfs'),
    (166424, 'Four young outsiders teleport to a dangerous universe, which alters their physical form in shocking ways. Their lives irrevocably upended, the team must learn to harness their daunting new abilities and work together to save Earth from a former friend turned enemy.', 100, '/cDroz5qSlP8xZ6tOpeYoPkBvKyL.jpg', '/or5kDR8Ve3TtuPSdEf1X5NdQHyz.jpg', 'AAgnQdiZFsQ'),
    (166426, 'Thrust into an all-new adventure, a down-on-his-luck Capt. Jack Sparrow feels the winds of ill-fortune blowing even more strongly when deadly ghost sailors led by his old nemesis, the evil Capt. Salazar, escape from the Devil''s Triangle. Jack''s only hope of survival lies in seeking out the legendary Trident of Poseidon, but to find it, he must forge an uneasy alliance with a brilliant and beautiful astronomer and a headstrong young man in the British navy.', 129, '/6lAPOAFYFWIO3SQRemEY2wInQMC.jpg', '/7C921eWK06n12c1miRXnYoEu5Yv.jpg', 'jnVk2C2YrSA'),
    (166428, 'As Hiccup fulfills his dream of creating a peaceful dragon utopia, Toothless’ discovery of an untamed, elusive mate draws the Night Fury away. When danger mounts at home and Hiccup’s reign as village chief is tested, both dragon and rider must make impossible decisions to save their kind.', 104, '/xvx4Yhf0DVH8G4LzNISpMfFBDy2.jpg', '/h3KN24PrOheHVYs9ypuOIdFBEpX.jpg', '5DEdq57E5ls'),
    (168259, 'Deckard Shaw seeks revenge against Dominic Toretto and his family for his comatose brother.', 138, '/wurKlC3VKUgcfsn0K51MJYEleS2.jpg', '/ehzI1mVcnHqB58NqPyQwpMqcVoz.jpg', 'B3Ms2yFvus0'),
    (168672, 'A conman and his seductive partner are forced to work for a wild FBI agent, who pushes them into a world of Jersey power-brokers and the Mafia.', 138, '/z6O1KDhfWDTm5ZBr6Ovr0eg8LqO.jpg', '/3r2G1vSDf4S3Pl5lJ9BDm9FTxe6.jpg', 'h5Cb4SFt7gE'),
    (169917, 'Private investigator Matthew Scudder is hired by a drug kingpin to find out who kidnapped and murdered his wife.', 114, '/euPgyPsiNFp6gOBB7nUFxvN5ZaY.jpg', '/k23FPWl97XKpJ1oTaDyADzxWxs6.jpg', 'aTKBowDjMQg'),
    (172385, 'It''s a jungle out there for Blu, Jewel and their three kids after they''re hurtled from Rio de Janeiro to the wilds of the Amazon. As Blu tries to fit in, he goes beak-to-beak with the vengeful Nigel, and meets the most fearsome adversary of all: his father-in-law.', 101, '/gVNTBrjxh2YRmQFjlaqrNbHVvrd.jpg', '/eg2jxQ1FFi6ENDfyMIMC5odpcU0.jpg', 'J9L06tdcG8A'),
    (173897, 'Picking up immediately after the events in Resident Evil: Retribution, Alice is the only survivor of what was meant to be humanity''s final stand against the undead. Now, she must return to where the nightmare began - The Hive in Raccoon City, where the Umbrella Corporation is gathering its forces for a final strike against the only remaining survivors of the apocalypse.', 107, '/gytKL6fimeiTIjd9kl5bfjY2k4C.jpg', '/sQRfWdDxH53Vk7ZJ1UqzcaBHocO.jpg', '79Sd4GtOXuI'),
    (177572, 'A special bond develops between plus-sized inflatable robot Baymax, and prodigy Hiro Hamada, who team up with a group of friends to form a band of high-tech heroes.', 102, '/2mxS4wUimwlLmI1xp6QW6NSU361.jpg', '/4s2d3xdyqotiVNHTlTlJjrr3q0H.jpg', '8IdMPpKMdcc'),
    (177677, 'Ethan and team take on their most impossible mission yet—eradicating ''The Syndicate'', an International and highly-skilled rogue organization committed to destroying the IMF.', 131, '/mXwC63mlpijqllhoeGnKBGgPtBa.jpg', '/vYIUN5rrCncHFY8WvcuXQlM4hk5.jpg', 'F-qBD17wwrQ'),
    (180863, 'After 20 years abroad, Mark Renton returns to Scotland and reunites with his old friends Sick Boy, Spud and Begbie.', 117, '/xlbpCwa9OXXIiNgXcwuompHFIk9.jpg', '/rTpNrsyhpOZPqW2qsyNHLxyarvL.jpg', 'hIWJ-mhg7vE'),
    (181533, 'When the magic powers of The Tablet of Ahkmenrah begin to die out, Larry Daley spans the globe, uniting favorite and new characters while embarking on an epic quest to save the magic before it is gone forever.', 98, '/xwgy305K6qDs3D20xUO4OZu1HPY.jpg', '/1ClgfKeczI0d0KKuBs5qSIqUReT.jpg', 'THxsWvtbMjM'),
    (181808, 'Rey develops her newly discovered abilities with the guidance of Luke Skywalker, who is unsettled by the strength of her powers. Meanwhile, the Resistance prepares to do battle with the First Order.', 152, '/kOVEVeg59E0wsnXmF9nrh6OmWII.jpg', '/5Iw7zQTHVRBOYpA0V6z0yypOPZh.jpg', 'Q0CbN8sfihY'),
    (181812, 'The surviving Resistance faces the First Order once again as the journey of Rey, Finn and Poe Dameron continues. With the power and knowledge of generations behind them, the final battle begins.', 142, '/db32LaOibwEliAmSL2jjDF6oDdj.jpg', '/auJKGst3vXpJozHZh4nMFs0xWIU.jpg', '8Qn_spdM5Zg'),
    (181886, 'A mild-mannered college professor discovers a look-alike actor and delves into the other man''s private affairs.', 91, '/vf40tyDRKZsBmaLsYeopzfFLzLx.jpg', '/deYWtXTc56YdXyIuuMuA8dvBY16.jpg', 'aVvgt3jIUsc'),
    (184315, 'When a new enemy threatens the innocent, Hercules must lead his fearless team of warriors in a battle against overwhelming odds.', 98, '/sKNIwY6UENCJ36FvYvnBW3Vdzt7.jpg', '/nl18gyzai02Tu99VkURu7kCFrR8.jpg', 'HydiAICZq6I'),
    (184346, 'When a frightening wave of violence sweeps through New York City, troubled cop Sarchie fails to find a rational explanation for the bizarre crimes. However, his eyes are opened to a frightening alternate reality when renegade Jesuit priest Mendoza convinces him that demonic possession may be to blame for the gruesome murders. Together, they wage a valiant supernatural struggle to rid the city of an otherworldly evil.', 118, '/Uz32ERsyCmGwV8Eg2wmT2ooWpo.jpg', '/JFQJDXEHnZmfJC1sWNbIrz0WS7.jpg', '2RR42oZX3-U'),
    (188927, 'The USS Enterprise crew explores the furthest reaches of uncharted space, where they encounter a mysterious new enemy who puts them and everything the Federation stands for to the test.', 122, '/wI5VghYNYLktDRPUa5rrVcVA1h7.jpg', '/nkr43pY7ZzUt9b0kDFwJLVuDP8G.jpg', 'NwpvjQKdpvI'),
    (193610, 'After discovering her boyfriend is married, Carly soon meets the wife he''s been cheating on. And when yet another affair is discovered, all three women team up to plot mutual revenge on the three-timing SOB.', 109, '/yHnbb6z8REuFIyBLT2Nj3MX54dY.jpg', '/40yTRVLhBuRvDbBChbz3dzbZHO3.jpg', 'BlHMHLuJWbo'),
    (193756, 'Four Navy SEALs on a covert mission to neutralize a high-level Taliban operative must make an impossible moral decision in the mountains of Afghanistan that leads them into an enemy ambush. As they confront unthinkable odds, the SEALs must find reserves of strength and resilience to fight to the finish.', 121, '/zaBIrloyhGK7iNTZMb3f9SARsl8.jpg', '/a66QNfdMrJ2IrneVMnzt0NnVmjG.jpg', '0cPJ1ifjBDs'),
    (194662, 'A fading actor best known for his portrayal of a popular superhero attempts to mount a comeback by appearing in a Broadway play. As opening night approaches, his attempts to become more altruistic, rebuild his career, and reconnect with friends and family prove more difficult than expected.', 120, '/rHUg2AuIuLSIYMYFgavVwqt1jtc.jpg', '/s0OrExdg7i3RLR7oqzHRk4q2kL4.jpg', 'egYzOALlYyU'),
    (198184, 'Every child comes into the world full of promise, and none more so than Chappie: he is gifted, special, a prodigy. Like any child, Chappie will come under the influence of his surroundings—some good, some bad—and he will rely on his heart and soul to find his way in the world and become his own man. But there''s one thing that makes Chappie different from any one else: he is a robot.', 120, '/uuDUpzlMFomdSfNWlpEPS9nVZWV.jpg', '/qX5T5GVAcq2UKaaiAx5SZp1AtlY.jpg', 'lyy7y0QOK-0'),
    (198277, 'Gretta, a budding songwriter, finds herself alone after her boyfriend Dave ditches her. Her life gains purpose when Dan, a record label executive, notices her talent.', 104, '/qx4HXHXt528hS4rwePZbZo20xqZ.jpg', '/xrSRmL6pXnRfu9vKwayILkNgLP.jpg', 'uTRCxOE7Xzc'),
    (198663, 'A teenager with no memory of his past finds himself among a group of boys living in a walled enclosure surrounded by a massive, ever-changing maze. As he struggles to adapt to their rules and society, he begins to uncover clues that may lead to escape and the truth behind their confinement.', 113, '/ode14q7WtDugFDp78fo9lCsmay9.jpg', '/eTlcNXGv32zkVI7ZDHhfeaKHXKQ.jpg', '3b946aGm0zs'),
    (200727, 'Since the moment they met at age 5, Rosie and Alex have been best friends, facing the highs and lows of growing up side by side. A fleeting shared moment, one missed opportunity, and the decisions that follow send their lives in completely different directions. As each navigates the complexities of life, love, and everything in between, they always find their way back to each other - but is it just friendship, or something more?', 102, '/2HOd431LX9ggqSpBIJ7qyYhATyo.jpg', '/rpsHpJj7FgnNBXhaO2KFthPwqH6.jpg', 'dOMTh9Jd81w'),
    (201088, 'Nicholas Hathaway, a furloughed convict, and his American and Chinese partners hunt a high-level cybercrime network from Chicago to Los Angeles to Hong Kong to Jakarta. As Hathaway closes in, the stakes become personal as he discovers that the attack on a Chinese nuclear power plant was just the beginning.', 133, '/6KGxFPcGcyYnN4ct96nmYoabLZ6.jpg', '/1u7TuvR5mSUz2xRQhz01i75IwdT.jpg', '-CA95Bzpy7s'),
    (203801, 'At the height of the Cold War, a mysterious criminal organization plans to use nuclear weapons and technology to upset the fragile balance of power between the United States and Soviet Union. CIA agent Napoleon Solo and KGB agent Illya Kuryakin are forced to put aside their hostilities and work together to stop the evildoers in their tracks. The duo''s only lead is the daughter of a missing German scientist, whom they must find soon to prevent a global catastrophe.', 116, '/y5yZaForGSJbPD66Cvq9AT5WMAD.jpg', '/lZ2MSmrhb3zanyvg0KTNNTzmK9B.jpg', 'w_Ky4KPzKwY'),
    (203833, 'While subjected to the horrors of WWII Germany, young Liesel finds solace by stealing books and sharing them with others. Under the stairs in her home, a Jewish refugee is being sheltered by her adoptive parents.', 131, '/wj4U5sMLcJMa3WR9CpRR9e2sdgZ.jpg', '/arFPEDEW4PzPaMBXgTPzJlumfGw.jpg', '38K6u_z5Gug'),
    (205584, 'A common thief joins a mythical god on a quest through Egypt.', 127, '/hzH7fwaTyQNITLo40Hu3R7cVMqv.jpg', '/pl2zr5efo9Dz1fi2gpsslGwEQm.jpg', 'tuVg_6UaQsU'),
    (205587, 'A successful lawyer returns to his hometown for his mother''s funeral only to discover that his estranged father, the town''s judge, is suspected of murder.', 141, '/3K93GWotLXe4FqpErri0xkpLaD5.jpg', '/9W02KZYKLoINpqpJ2yv8ATxR1AK.jpg', 'ZBvK6ni97W8'),
    (205596, 'Based on the real life story of legendary cryptanalyst Alan Turing, the film portrays the nail-biting race against time by Turing and his brilliant team of code-breakers at Britain''s top-secret Government Code and Cypher School at Bletchley Park, during the darkest days of World War II.', 113, '/zSqJ1qFq8NXFfi7JeIYMlzyR0dx.jpg', '/8FCHJ21JBQOgATY2WI8vwYAiXg8.jpg', 'j2jRs4EAvWM'),
    (205775, 'In the winter of 1820, the New England whaling ship Essex is assaulted by something no one could believe—a whale of mammoth size and will, and an almost human sense of vengeance.', 122, '/weVvNPfk6FM9vBg3BXtRtNAmiYM.jpg', '/4LRLz2V63TSwuQhBVNXsbnHxgoY.jpg', 'K-H35Mpj4uk'),
    (206487, 'Predestination chronicles the life of a Temporal Agent sent on an intricate series of time-travel journeys designed to prevent future killers from committing their crimes. Now, on his final assignment, the Agent must stop the one criminal that has eluded him throughout time and prevent a devastating attack in which thousands of lives will be lost.', 98, '/38Xr1JnV1ZcLQ55zmdSp6n475cZ.jpg', '/cvq9cRMDJIGzNpHaPVGFftqPcLj.jpg', 'xxG-YfedrfU'),
    (206647, 'A cryptic message from Bond’s past sends him on a trail to uncover a sinister organization. While M battles political forces to keep the secret service alive, Bond peels back the layers of deceit to reveal the terrible truth behind SPECTRE.', 148, '/zj8ongFhtWNsVlfjOGo8pSr7PQg.jpg', '/cCKU3EuiSKt6xsOI6gg5kiFgZYm.jpg', 'z4UDNzXD3qA'),
    (207703, 'The story of a super-secret spy organization that recruits an unrefined but promising street kid into the agency''s ultra-competitive training program just as a global threat emerges from a twisted tech genius.', 129, '/r6q9wZK5a2K51KFj4LWVID6Ja1r.jpg', '/qzUIOTk0E3F1zjvYjcBRTKUTgf9.jpg', 'Th_KrhqmHk8'),
    (207932, 'After waking up in a hospital with amnesia, professor Robert Langdon and a doctor must race against time to foil a deadly global plot.', 122, '/5T6iVetK5AB1kgwAEKbDM2hTZJU.jpg', '/y3w1fdR3QfYy22ryvhRl6YyHohs.jpg', 'RH2BD49sEZI'),
    (209112, 'Fearing the actions of a god-like Super Hero left unchecked, Gotham City’s own formidable, forceful vigilante takes on Metropolis’s most revered, modern-day savior, while the world wrestles with what sort of hero it really needs. And with Batman and Superman at war with one another, a new threat quickly arises, putting mankind in greater danger than it’s ever known before.', 152, '/5UsK3grJvtQrtzEgqNlDljJW96w.jpg', '/5fX1oSGuYdKgwWmUTAN5MNSQGzr.jpg', 's9EkdAHqtvU'),
    (210577, 'With his wife''s disappearance having become the focus of an intense media circus, a man sees the spotlight turned on him when it''s suspected that he may not be innocent.', 149, '/ts996lKsxvjkO2yiYG0ht4qAicO.jpg', '/iWak7wT0j6ycCc8lKr4NBz9c7n5.jpg', '2-_-1nJf8Vg'),
    (211672, 'Minions Stuart, Kevin and Bob are recruited by Scarlet Overkill, a super-villain who, alongside her inventor husband Herb, hatches a plot to take over the world.', 91, '/dr02BdCNAUPVU07aOodwPYv6HCf.jpg', '/wKrxeY6lbu7KFBsWVcMH6M8avwr.jpg', 'Wfql_DoHRKc'),
    (212778, 'When Chef Carl Casper suddenly quits his job at a prominent Los Angeles restaurant after refusing to compromise his creative integrity for its controlling owner, he is left to figure out what''s next. Finding himself in Miami, he teams up with his ex-wife, his friend and his son to launch a food truck. Taking to the road, Chef Carl goes back to his roots to reignite his passion for the kitchen -- and zest for life and love.', 114, '/hyp8EXDmO4dSC8V6Q5jU7gD1kcg.jpg', '/igVNCpS132rOqrnDsrVYW5HCIsM.jpg', 'GO4gFillQOc'),
    (214756, 'Newlywed couple Ted and Tami-Lynn want to have a baby, but in order to qualify to be a parent, Ted will have to prove he''s a person in a court of law.', 115, '/38C91I7Xft0gyY7BITm8i4yvuRb.jpg', '/xtHonIIIQXverDQM08TMQXjn9Fe.jpg', 'mSG3R_2Uisw'),
    (216015, 'When college senior Anastasia Steele steps in for her sick roommate to interview prominent businessman Christian Grey for their campus paper, little does she realize the path her life will take. Christian, as enigmatic as he is rich and powerful, finds himself strangely drawn to Ana, and she to him. Though sexually inexperienced, Ana plunges headlong into an affair -- and learns that Christian''s true sexual proclivities push the boundaries of pain and pleasure.', 125, '/63kGofUkt1Mx0SIL4XI4Z5AoSgt.jpg', '/7IGKrY1f1KfwMipx9wZC4NRgIdF.jpg', '6FDTMRK7-24'),
    (220289, 'Four couples gather for dinner the night a mysterious and powerful comet passes overhead.', 89, '/ezUtb9m5DeLwL2gxi4gktzNCvQv.jpg', '/cvGE73s935bXEAVt2W0zADPPegG.jpg', 'YixSld-6PqM'),
    (222935, 'Despite the tumor-shrinking medical miracle that has bought her a few years, Hazel has never been anything but terminal, her final chapter inscribed upon diagnosis. But when a patient named Augustus Waters suddenly appears at Cancer Kid Support Group, Hazel''s story is about to be completely rewritten.', 126, '/kcVuktIlrn9SAN1uBmPDnocTQmF.jpg', '/oQaVV7p916HO5MDI820zzs1pin9.jpg', '3Ixw15DE-xY'),
    (222936, 'A celebrated military contractor returns to the site of his greatest career triumphs and re-connects with a long-ago love while unexpectedly falling for the hard-charging Air Force watchdog assigned to him.', 105, '/58Y4CjcRX8AtMNtI0AXu9H7iebP.jpg', '/9c8TeWriKWYHFt2V664HqNPGOKX.jpg', 'hZGP4AR46Eg'),
    (223702, 'Hot dog Frank leads a group of supermarket products on a quest to discover the truth about their existence and what really happens when they''re chosen to leave the grocery store.', 89, '/vNgdPJQ5CI60oEiiHLKRNrsDhMy.jpg', '/hsb8nNBt3emvWqBs7Xv5IKlz6Im.jpg', 'GAJrBPUVDJM'),
    (224141, 'In a woods filled with magic and fairy tale characters, a baker and his wife set out to end the curse put on them by their neighbor, a spiteful witch.', 125, '/pf0TdnITu380Zp8DMQx0jcwDsAS.jpg', '/qF938YRj7RoYkjwOsXFDNYf907J.jpg', 'dRgr7itwgak'),
    (225574, 'Bill Marks is a Federal Air Marshall for whom every day is the same until this one. On this plane ride, he starts receiving text messages from someone claiming to be on the flight and threatening to kill passengers. In a race against the clock, he must identify and stop the killer to save everyone on board.', 107, '/Nkgaj3X0W2jHQ1TzHEgWFpN3kJ.jpg', '/pvvPS1V8aR1puiQeRIIXP0SgT1y.jpg', 'XSF6GPNXr9Y'),
    (227156, 'In a seemingly perfect community, without war, pain, suffering, differences or choice, a young boy is chosen to learn from an elderly man about the true pain and pleasure of the "real" world.', 97, '/dul62Av4pgi5x8LP7ELHzNyka9Z.jpg', '/1wX0Xgs316QapQXjmqrAY9UixgN.jpg', 'fMUli947oIE'),
    (227306, 'A chronicle of the life of Louis Zamperini, an Olympic runner who was taken prisoner by Japanese forces during World War II.', 137, '/vAlHUjHwLWMV5mg4epGR9WSIfiy.jpg', '/wxdtjlapI0d1vsXhNN0LhLMsaGw.jpg', 'rGlsxVfCSyQ'),
    (228150, 'April, 1945. As the Allies make their final push in the European Theater, a battle-hardened army sergeant commands a Sherman tank with a five-man crew on a deadly mission behind enemy lines.', 135, '/pfte7wdMobMF4CVHuOxyu6oqeeA.jpg', '/95ckrV6wQgbffurAVmETQ5YKASL.jpg', '09w9MTtZDEM'),
    (228161, 'When Earth is taken over by the overly-confident Boov, an alien race in search of a new place to call home, all humans are promptly relocated, while all Boov get busy reorganizing the planet. But when one resourceful girl, Tip, manages to avoid capture, she finds herself the accidental accomplice of a banished Boov named Oh. The two fugitives realize there’s a lot more at stake than intergalactic relations as they embark on the road trip of a lifetime.', 94, '/usFenYnk6mr8C62dB1MoAfSWMGR.jpg', '/gnkBzJVH2zicIopP2fHf4kRElne.jpg', 'Du4jTG7-93k'),
    (228326, 'The journey of Manolo, a young man who is torn between fulfilling the expectations of his family and following his heart. Before choosing which path to follow, he embarks on an incredible adventure that spans fantastical worlds where he must face his greatest fears.', 95, '/aotTZos5KswgCryEzx2rlOjFsm1.jpg', '/b0XkgWgCBurkCZdNXp7kEZdgxEi.jpg', '_i69CJc1BgE'),
    (228967, 'Dave Skylark and his producer Aaron Rapaport run the celebrity tabloid show "Skylark Tonight". When they land an interview with a surprise fan, North Korean dictator Kim Jong-un, they are recruited by the CIA to turn their trip to Pyongyang into an assassination mission.', 112, '/tIDC4xT65l7a8qbgg8GvwD5g8c5.jpg', '/3YKGMZQ0pwQXSBSASeKlfPlkso7.jpg', 'BJu0KYd5-_M'),
    (229297, 'Set in the 1920s French Riviera, a master magician is commissioned to try and expose a psychic as a fraud.', 98, '/4vKNUcdTK6mH3IBIdJ7OYabzqkg.jpg', '/gdUqfMhx1pqOj4BoI3lYAl8zaln.jpg', 'nzcPdGxuewU'),
    (232672, 'Recently divorced mom Lauren and widowed dad Jim let their friends push them into a blind date, which goes disastrously wrong. Unsurprisingly, neither wants to see the other ever again. However, fate intervenes when both Jim and Lauren, unbeknownst to each other, purchase one-half of the same vacation package at a South African resort for families, during spring break. They and their children are forced to share the same romantic suite and participate in a slew of family activities together.', 117, '/o2YrH9jS7CAfWjETHFeL0tth79E.jpg', '/g5haoqEqt5VwVwQKEkoXY9zqSxb.jpg', 'V6cKLTmDB-k'),
    (238713, 'A desk-bound CIA analyst volunteers to go undercover to infiltrate the world of a deadly arms dealer, and prevent diabolical global disaster.', 120, '/vPBmfMHxQvRRNGYD5S5ko2KnX56.jpg', '/eHEGPHKHTVhWdXzBQcrTATz9M0I.jpg', 'ltijEmlyqlg'),
    (240832, 'A woman, accidentally caught in a dark deal, turns the tables on her captors and transforms into a merciless warrior evolved beyond human logic.', 89, '/kRbpUTRNm6QbLQFPFWUcNC4czEm.jpg', '/ozVwXlfxqNsariipatGwa5px3Pm.jpg', 'l7zAV_MDC68'),
    (241259, 'Alice Kingsleigh returns to Underland and faces a new adventure in saving the Mad Hatter.', 113, '/kbGamUkYfgKIYIrU8kW5oc0NatZ.jpg', '/A6d09KtZKdVGSg0gzsldjDwwvhD.jpg', 'QtrOm-DBhIM'),
    (241554, 'Brooklyn mobster and prolific hit man Jimmy Conlon has seen better days. Longtime best friend of a mob boss, Jimmy is haunted by the sins of his past—as well as a dogged police detective who’s been one step behind Jimmy for 30 years. But when Jimmy’s estranged son becomes a target, Jimmy must make a choice between the crime family he chose and the real family he abandoned long ago. Now, with nowhere safe to turn, Jimmy has just one night to figure out exactly where his loyalties lie and to see if he can finally make things right.', 114, '/owTdkLW0uoVTUPtM5h4gw88prdC.jpg', '/dqTvzfXhUWPoBuIbQInOBmYvEL4.jpg', 'plrh783KCqg'),
    (242224, 'A grieving single mother and her child fall into a deep well of paranoia when an eerie children''s book manifests in their home.', 94, '/qt3fqapeo94TfvMyld8P7gkpXLz.jpg', '/t18ocAG0cpgC1AP288SseqmXqB5.jpg', '88DDAyYkvis'),
    (242512, 'A group of friends must confront their most terrifying fears when they awaken the dark powers of an ancient spirit board.', 89, '/gwjHlGjK2xXKpjd65BWyAMwzTWC.jpg', '/fsuA3wUYixjLeE97CyyPGdPoQF3.jpg', 'xBLmBdn2QF8'),
    (242582, 'When Lou Bloom, desperate for work, muscles into the world of L.A. crime journalism, he blurs the line between observer and participant to become the star of his own story. Aiding him in his effort is Nina, a TV-news veteran.', 118, '/j9HrX8f7GbZQm1BrBiR40uFQZSb.jpg', '/aCnpRvVBqltC8ZuVP67C4fdUCb4.jpg', '7uaYhPpV7G4'),
    (244786, 'Under the direction of a ruthless instructor, a talented young drummer begins to pursue perfection at any cost, even his humanity.', 107, '/7fn624j5lj3xTme2SgiLCeuedmO.jpg', '/fRGxZuo7jJUWQsVg9PREb98Aclp.jpg', 'Q7kZy3T6vRM'),
    (245891, 'Ex-hitman John Wick comes out of retirement to track down the gangsters that took everything from him.', 101, '/wXqWR7dHncNRbxoEGybEy7QTe9h.jpg', '/ff2ti5DkA9UYLzyqhQfI2kZqEuh.jpg', '6r0s41Ju5XA'),
    (246655, 'After the re-emergence of the world''s first mutant, world-destroyer Apocalypse, the X-Men must unite to defeat his extinction level plan.', 144, '/ikA8UhYdTGpqbatFa93nIf6noSr.jpg', '/sTQNRqLbfCXolrb5CizAW1dj528.jpg', 'Jer8XjMrUB4'),
    (246741, 'Vampire housemates try to cope with the complexities of modern life and show a newly turned hipster some of the perks of being undead.', 86, '/a2rD3i3DBMeYbA34rBv6z3B9S3a.jpg', '/utjThRtcnsj0GrDwNudjGdfmHfq.jpg', 'WBly4AfHc3c'),
    (249070, 'An assassin teams up with a woman to help her find her father and uncover the mysteries of her ancestry.', 96, '/cx9AOBOv9Qf5ufZYQMbfTV7w7VY.jpg', '/yRtZmZa2bmDYaOKygG7IaroSXwg.jpg', 'giNpP8VBIN8'),
    (249164, 'Mia Hall, a talented young cellist, thought the most difficult decision she would ever have to make would be whether to pursue her musical dreams at prestigious Juilliard or follow her heart to be with the love of her life, Adam, a rock singer/guitarist. However, a car wreck changes everything in an instant, and now Mia''s life hangs in the balance. Suspended between life and death, Mia faces a choice that will decide her future.', 106, '/7Twh8h3Wh7GC9npTAEUThgkxkWL.jpg', '/gz3rCM34UicmOxRY1T2SgiQZJoS.jpg', 'wH6PNeTy6Nc'),
    (250546, 'A couple begins to experience terrifying supernatural occurrences involving a vintage doll shortly after their home is invaded by satanic cultists.', 99, '/uXygZAPNsnCkzpZAa0UpRjgK5Mg.jpg', '/pWZ0srAfPx4XyJMlFkKBlmYfx3C.jpg', 'xabuZwG3XyM'),
    (253412, 'Inspired by the incredible events surrounding a treacherous attempt to reach the summit of the world''s highest mountain, "Everest" documents the awe-inspiring journey of two different expeditions challenged beyond their limits by one of the fiercest snowstorms ever encountered by mankind. Their mettle tested by the harshest of elements found on the planet, the climbers will face nearly impossible obstacles as a lifelong obsession becomes a breathtaking struggle for survival.', 121, '/2jKOu2bjpLP6NXJcm7Ep14bDGtA.jpg', '/P7d3lyBaYbAXVor6iB2avLvc4K.jpg', '5CKZwKpV06U'),
    (254128, 'In the aftermath of a massive earthquake in California, a rescue-chopper pilot makes a dangerous journey across the state in order to rescue his estranged daughter.', 114, '/2Gfjn962aaFSD6eST6QU3oLDZTo.jpg', '/zcySy6dnSmyqiichtDgO7AEeZoq.jpg', 'F1ZewAPl7L0'),
    (254320, 'In a dystopian near future, single people, according to the laws of The City, are taken to The Hotel, where they are obliged to find a romantic partner in forty-five days or are transformed into animals and sent off into The Woods.', 119, '/7Y9ILV1unpW9mLpGcqyGQU72LUy.jpg', '/s48CvFbWoWHhSPgz2wW9Rffw04q.jpg', 'LTNZmOJxuAc'),
    (254470, 'The Bellas are back, and they are better than ever. After being humiliated in front of none other than the President of the United States of America, the Bellas are taken out of the Aca-Circuit. In order to clear their name, and regain their status, the Bellas take on a seemingly impossible task: winning an international competition no American team has ever won. In order to accomplish this monumental task, they need to strengthen the bonds of friendship and sisterhood and blow away the competition with their amazing aca-magic! With all new friends and old rivals tagging along for the trip, the Bellas can hopefully accomplish their dreams.', 115, '/fQaEGzFmvTYu3G641WV0Tg9auAt.jpg', '/bWOfRV1Ubk9SWEDZDDjsmIUCcbZ.jpg', 'OgPm-yaLoyo'),
    (257211, '70-year-old widower Ben Whittaker has discovered that retirement isn''t all it''s cracked up to be. Seizing an opportunity to get back in the game, he becomes a senior intern at an online fashion site, founded and run by Jules Ostin.', 121, '/rdWkIocdGPEPn9no4wKwQ9LmlY.jpg', '/i8Q2Ei2dPliMLgPWYhRTxIDzh7r.jpg', 'f6dKhzYgksc'),
    (257344, 'Video game experts are recruited by the military to fight 1980s-era video game characters who''ve attacked New York.', 106, '/d26S5EfVXLNxRXqyFy1yyl3qRq3.jpg', '/6UFnKzVzFqKDjs4iCVLJdneK3ch.jpg', 'v5kTR1MGBuw'),
    (257445, 'After moving to a small town, Zach Cooper finds a silver lining when he meets next door neighbor Hannah, the daughter of bestselling Goosebumps series author R.L. Stine. When Zach unintentionally unleashes real monsters from their manuscripts and they begin to terrorize the town, it’s suddenly up to Stine, Zach and Hannah to get all of them back in the books where they belong.', 103, '/aeZT9pqEgrmXOGdESFkAuVjX6kw.jpg', '/6mPe4rBHzDMal2oL6hVgOBkaHz9.jpg', 'dr8hmqAgbtg'),
    (258216, 'A man named Seligman finds a fainted wounded woman in an alley and he brings her home. She tells him that her name is Joe and that she is nymphomaniac. Joe tells her life and sexual experiences with hundreds of men since she was a young teenager while Seligman tells about his hobbies, such as fly fishing, reading about Fibonacci numbers or listening to organ music.', 118, '/piikL8vRh3s1ysHGTIqaZpdjfNU.jpg', '/8tDhIbueuM4PK9b1q0Rshzgovee.jpg', 'w7-UH6d_Oyo'),
    (258230, '12-year-old Conor encounters an ancient tree monster who proceeds to help him cope with his mother''s terminal illness and being bullied in school.', 108, '/vNzWJwVqjszWwXrA7ZfsrJmhgV9.jpg', '/9iz9NrxldLvJof2133xvQH5vvhh.jpg', '8q-7trUd8Vw'),
    (258489, 'Tarzan, having acclimated to life in London, is called back to his former home in the jungle to investigate the activities at a mining encampment.', 109, '/eJrfz178xBGlxjDGxnBXTzWWa4w.jpg', '/btCaMm9aVW1PG485Ef8RMBBALzI.jpg', 'dLmKio67pVQ'),
    (259072, 'A sudden and mysterious inheritance brings Danny and his friends to Hobb Springs, a forgotten resort deep in the West Virginia hills. Hobb Springs is being looked after under the watchful care of Jackson and Sally, a socially awkward couple who introduce Danny to the long lost family he''s never known. A clan by the name of Hillicker. But soon Danny learns his relatives have a different way of living, that for generations, the Hillickers have observed ancient traditions rooted in cannibalism and other taboo rituals.', 91, '/cV1biK7jlHVXlQ7ErYe5MUSBGcx.jpg', '/iS3cMqqWQBehsm0b9Zb5ND4m2pf.jpg', 'R2jV-JSU8Yo'),
    (259316, 'In 1926, Newt Scamander arrives at the Magical Congress of the United States of America with a magically expanded briefcase, which houses a number of dangerous creatures and their habitats. When the creatures escape from the briefcase, it sends the American wizarding authorities after Newt, and threatens to strain even further the state of magical and non-magical relations.', 133, '/h6NYfVUyM6CDURtZSnBpz647Ldd.jpg', '/8Qsr8pvDL3s1jNZQ4HK1d1Xlvnh.jpg', 'Vso5o11LuGU'),
    (260346, 'Ex-government operative Bryan Mills finds his life is shattered when he''s falsely accused of a murder that hits close to home. As he''s pursued by a savvy police inspector, Mills employs his particular set of skills to track the real killer and exact his unique brand of justice.', 109, '/vzvMXMypMq7ieDofKThsxjHj9hn.jpg', '/vFm4pF0BgaWPj0i2zEiZO6TqEQ0.jpg', 'JuU0M2xBasc'),
    (260513, 'Elastigirl springs into action to save the day, while Mr. Incredible faces his greatest challenge yet – taking care of the problems of his three children.', 118, '/9lFKBtaVIhP7E2Pk0IY1CwTKTMZ.jpg', '/mabuNsGJgRuCTuGqjFkWe1xdu19.jpg', 'i5qOzqD9Rms'),
    (260514, 'Blindsided by a new generation of blazing-fast racers, the legendary Lightning McQueen finds himself pushed to the brink—and suddenly, the champion who once ruled the track is fighting just to stay in the race. With his career hanging in the balance, McQueen must turn to an ambitious young race technician with a plan of her own, draw strength from the legacy of the late Fabulous Hudson Hornet, and risk everything on one last shot at glory.', 102, '/zg5RDxvIIAKsucjuU2EZJIHEIvz.jpg', '/wvBO5vBrFQtQpJPWx83JYuysr4f.jpg', 'ZuaseSovWDY'),
    (262500, 'Beatrice Prior must confront her inner demons and continue her fight against a powerful alliance which threatens to tear her society apart.', 119, '/dP5Fb6YRfzmCQtRbHOr2kO7tJW9.jpg', '/8YNNyQiPZlF9qv5EGOUK20mnXVk.jpg', 'jfaqVegF2mo'),
    (262504, 'Beatrice Prior and Tobias Eaton venture into the world outside of the fence and are taken into protective custody by a mysterious agency known as the Bureau of Genetic Welfare.', 120, '/faq9JlF8znUGQ5p3En1W61Fi5p0.jpg', '/qSP072apfe2EEcd5Qg9vGYy2OLw.jpg', 'ESJBomF-9Y8'),
    (263115, 'In the near future, a weary Logan cares for an ailing Professor X in a hideout on the Mexican border. But Logan''s attempts to hide from the world and his legacy are upended when a young mutant arrives, pursued by dark forces.', 137, '/fnbjcRDYn6YviCcePDnGdyAkYsB.jpg', '/4DZxWNSAyksN6N3JkvpJ53Yq6zU.jpg', 'XaE_9pfybL4'),
    (263472, 'When a devoted husband and father is left home alone for the weekend, two stranded young women unexpectedly knock on his door for help. What starts out as a kind gesture results in a dangerous seduction and a deadly game of cat and mouse.', 99, '/cUC4rUb1Cs2KMaZ6RD4uYUEEwls.jpg', '/9DclZBBDxMrbcqNS81Pjz8opZTW.jpg', '1vGZWY5MFY0'),
    (264660, 'Caleb, a coder at the world''s largest internet company, wins a competition to spend a week at a private mountain retreat belonging to Nathan, the reclusive CEO of the company. But when Caleb arrives at the remote location he finds that he will have to participate in a strange and fascinating experiment in which he must interact with the world''s first true artificial intelligence, housed in the body of a beautiful robot girl.', 108, '/dmJW8IAKHKxFNiUnoDR7JfsK7Rp.jpg', '/uqOuJ50EtTj7kkDIXP8LCg7G45D.jpg', 'sDkEF7Db7Gw'),
    (265195, 'Injustice and the demands of the world can cause stress for many people. Some of them, however, explode. This includes a waitress serving a grouchy loan shark, an altercation between two motorists, an ill-fated wedding reception, and a wealthy businessman who tries to buy his family out of trouble.', 122, '/vmeCDuWJ6B2cqi9f3QFyIwRKqFV.jpg', '/dHnki2Dh6lbOtfksrh8H5lg08f5.jpg', 'Utq0aDEp084'),
    (266647, 'Living a bleak existence at a London orphanage, 12-year-old Peter finds himself whisked away to the fantastical world of Neverland. Adventure awaits as he meets new friend James Hook and the warrior Tiger Lily. They must band together to save Neverland from the ruthless pirate Blackbeard. Along the way, the rebellious and mischievous boy discovers his true destiny, becoming the hero forever known as Peter Pan.', 111, '/w8i0mZR7MEL7c3bXSsuYg7VJsew.jpg', '/fACoy2VWw9lz1UbqrgtbIcSYi5e.jpg', 'Y1wRv8vTpxo'),
    (266856, 'Once a healthy, active young man, Hawking received an earth-shattering diagnosis at 21 years of age. With Jane fighting tirelessly by his side, Stephen embarks on his most ambitious scientific work, studying the very thing he now has precious little of – time.', 123, '/7kwcLFNt887saoQAL7EY0XnW7VI.jpg', '/dh2QT3TPtAQf057yeLpNMuaJlmp.jpg', '_EnhOKk7BxM'),
    (267860, 'In London for the Prime Minister''s funeral, Mike Banning discovers a plot to assassinate all the attending world leaders.', 99, '/iEbLkYzyiUdOKNK4WNBFyGH7r2Y.jpg', '/ndi0PlHzSbV2pV2wUZFtS58Wk54.jpg', 'oQhX4JxGHtw'),
    (267935, 'An orphan little girl befriends a benevolent giant who takes her to Giant Country, where they attempt to stop the man-eating giants that are invading the human world.', 117, '/w17Mc2x2olB5CtewznUFxgpvne0.jpg', '/tOTtJelsPKX0bvSdvDVL2ou3cGS.jpg', 'Y6ZbRD1T7uI'),
    (268896, 'It has been ten years since The Battle of the Breach and the oceans are still, but restless. Vindicated by the victory at the Breach, the Jaeger program has evolved into the most powerful global defense force in human history. The PPDC now calls upon the best and brightest to rise up and become the next generation of heroes when the Kaiju threat returns.', 111, '/nFWhttU8PM50t25NPdy7PE7rv3G.jpg', '/oMaj75G2WFw66xI1TREg1hrToSg.jpg', '8BAhwgjMvnM'),
    (269149, 'Determined to prove herself, Officer Judy Hopps, the first bunny on Zootopia''s police force, jumps at the chance to crack her first case - even if it means partnering with scam-artist fox Nick Wilde to solve the mystery.', 109, '/hlK0e0wAQ3VLuJcsfIYPvb4JVud.jpg', '/9tOkjBEiiGcaClgJFtwocStZvIT.jpg', 'jWM0ct-OLsM'),
    (270303, 'A young woman is followed by an unknown supernatural force after a sexual encounter.', 101, '/iwnQ1JH1wdWrGYkgWySptJ5284A.jpg', '/ikaRI4yMxKOje5SmOlAhOBUnicL.jpg', 'zoNa1WH3GR8'),
    (270487, 'When a Hollywood star mysteriously disappears in the middle of filming, the studio sends their fixer to get him back.', 106, '/qvecZ7WyemhGW8fuJ8190p472jQ.jpg', '/zIUigIht3f9osNGyleF6B3jBbl7.jpg', 'vMUUKtF_BF0'),
    (270946, 'Skipper, Kowalski, Rico and Private join forces with undercover organization The North Wind to stop the villainous Dr. Octavius Brine from destroying the world as we know it.', 92, '/dXbpNrPDZDMEbujFoOxmMNQVMHa.jpg', '/msnknPOg9dx86b0YozXOFP8PgBI.jpg', 'BjfID263ViI'),
    (271110, 'Following the events of Age of Ultron, the collective governments of the world pass an act designed to regulate all superhuman activity. This polarizes opinion amongst the Avengers, causing two factions to side with Iron Man or Captain America, which causes an epic battle between former allies.', 147, '/rAGiXaUfPzY7CDEyNKUofk3Kw2e.jpg', '/7FWlcZq3r6525LWOcvO9kNWurN1.jpg', 'dKrVegVI0Us'),
    (272693, 'Bianca''s universe turns upside down when she learns that her high school refers to her as a ‘DUFF'' (Designated Ugly Fat Friend). Hoping to erase that label, she enlists the help of a charming jock and her favorite teacher. Together they''ll face the school''s mean girl and remind everyone that we are all someone''s DUFF… and that''s totally fine.', 100, '/A6ScveWmIPL9vSYyULD8ObqyHDQ.jpg', '/trL84LbzW4s0uhOtHkTWLFJhpYO.jpg', 'YGBNMNaJ6M4'),
    (273248, 'Bounty hunters seek shelter from a raging blizzard and get caught up in a plot of betrayal and deception.', 188, '/jIywvdPjia2t3eKYbjVTcwBQlG8.jpg', '/7g1zO5t0bd27Iqn5ZUDJmksOGPJ.jpg', 'GRG7fAPksbg'),
    (273481, 'An idealistic FBI agent is enlisted by a government task force to aid in the escalating war against drugs at the border area between the U.S. and Mexico.', 122, '/lz8vNyXeidqqOdJW9ZjnDAMb5Vr.jpg', '/fKPgObonYgPgCdu88yjV7Hpn7Dp.jpg', 'Yfhu5JIxnZc'),
    (274167, 'The story of a mild-mannered radio executive who strives to become the best stepdad ever to his wife''s two children, but complications ensue when their freewheeling, freeloading real father arrives, forcing stepdad to compete for the affection of the kids.', 96, '/fB9lALk9zKsMYWvf0bJSkJN219Z.jpg', '/4kui3QA55M2ZOmBgoRlrYj5MSlK.jpg', 'arhMMJx7tCU'),
    (274479, 'A story based on the life of a struggling Long Island single mom who became one of the country''s most successful entrepreneurs.', 124, '/nZAs0HbW82TI1i4Xid83M941Pki.jpg', '/gwlx0r6NyWUuaI6MNajpYHPogZ1.jpg', 'GVzSZFz7jF8'),
    (274854, 'The modern world holds many secrets, but by far the most astounding is that witches still live among us; vicious supernatural creatures intent on unleashing the Black Death upon the world and putting an end to the human race once and for all. Armies of witch hunters have battled this unnatural enemy for centuries, including Kaulder, a valiant warrior who many years ago slayed the all-powerful Witch Queen, decimating her followers in the process. In the moments right before her death, the Queen cursed Kaulder with immortality, forever separating him from his beloved wife and daughter. Today, Kaulder is the last living hunter who has spent his immortal life tracking down rogue witches, all the while yearning for his long-lost family.', 106, '/dS9YdnJkxtKE2PKCSsxTaO7Jpf5.jpg', '/mXmvN6drkdU1PWFF92AGklEVIa3.jpg', 'QJDRdGxGw8U'),
    (274855, 'After an unprecedented series of natural disasters threatened the planet, the world''s leaders came together to create an intricate network of satellites to control the global climate and keep everyone safe. But now, something has gone wrong: the system built to protect Earth is attacking it, and it becomes a race against the clock to uncover the real threat before a worldwide geostorm wipes out everything and everyone along with it.', 109, '/nrsx0jEaBgXq4PWo7SooSnYJTv.jpg', '/u6QKT8EqpPHoPUng7aE90mWXigX.jpg', 'w1QSI0CFEWU'),
    (274857, 'When the child Arthur’s father is murdered, Vortigern, Arthur’s uncle, seizes the crown. Robbed of his birthright and with no idea who he truly is, Arthur comes up the hard way in the back alleys of the city. But once he pulls the sword Excalibur from the stone, his life is turned upside down and he is forced to acknowledge his true legacy... whether he likes it or not.', 126, '/9kKXH6eJpzoFGhCbTN3FVwSQK3n.jpg', '/sVkjgKq8cwKm95LCyfrLldLbQIG.jpg', 'SX9y5JPuRHY'),
    (274870, 'A spacecraft traveling to a distant colony planet and transporting thousands of people has a malfunction in its sleep chambers. As a result, two passengers are awakened 90 years early.', 116, '/jK9S6HANSf2no64v1x1HxfcpmcA.jpg', '/gHz4ZQytRs8YGrqFMwB3Vrr8pig.jpg', 'sipflRaq2vg'),
    (277217, 'A present-day idyllic kingdom where the benevolent teenage son of King Adam and Queen Belle offers a chance of redemption for the troublemaking offspring of Disney''s classic villains: Cruella De Vil (Carlos), Maleficent (Mal), the Evil Queen (Evie) and Jafar (Jay).', 112, '/65DkgHPSLVjgr6IYkpY9Aqqqid5.jpg', '/20ncMtoy9Cxy6OQxgXZemHoFymz.jpg', 't4UUQqefajc'),
    (277834, 'In Ancient Polynesia, when a terrible curse incurred by Maui reaches an impetuous Chieftain''s daughter''s island, she answers the Ocean''s call to seek out the demigod to set things right.', 107, '/m5MDZOIFEFlxGiLuAzWzFSsWcye.jpg', '/qLVNZFHYUR6Li64He67SWl6BHQe.jpg', 'LKFuXETZUsI'),
    (278154, 'Set after the events of Continental Drift, Scrat''s epic pursuit of his elusive acorn catapults him outside of Earth, where he accidentally sets off a series of cosmic events that transform and threaten the planet. To save themselves from peril, Manny, Sid, Diego, and the rest of the herd leave their home and embark on a quest full of thrills and spills, highs and lows, laughter and adventure while traveling to exotic new lands and locations.', 95, '/tFzUkdhPOForVrEfvxydXfPLrZR.jpg', '/rBEH34dgPMy1WuqZ0AFXR2ThmNo.jpg', 'Ohq6NmKMja8'),
    (278924, 'Arthur Bishop thought he had put his murderous past behind him when his most formidable foe kidnaps the love of his life. Now he is forced to travel the globe to complete three impossible assassinations, and do what he does best, make them look like accidents.', 99, '/bG3Q6EFcngpPn7uPuQTzTuq9DgV.jpg', '/3f5rBEc6ioRBO2CATDt4sKjEJnY.jpg', 'QF903RaKLvs'),
    (278927, 'After a threat from the tiger Shere Khan, Mowgli, a man-cub fostered by wolves, is forced to flee the jungle, and he embarks on a journey of self-discovery with the help of the panther, Bagheera, and the free-spirited bear, Baloo.', 106, '/2Epx7F9X7DrFptn4seqn4mzBVks.jpg', '/8oYykF1Qhrb8fC2qZqD71EzRywg.jpg', 'YW97nCUE3ZA'),
    (280092, 'A prequel set before the haunting of the Lambert family that reveals how gifted psychic Elise Rainier reluctantly agrees to use her ability to contact the dead in order to help a teenage girl who has been targeted by a dangerous supernatural entity.', 97, '/iDdGfdNvY1EX0uDdA4Ru77fwMfc.jpg', '/1fpwEe2GvNjAq2MN2xxdifNZLBT.jpg', 'eiDph99MdZ4'),
    (280217, 'It''s been five years since everything was awesome and the citizens are facing a huge new threat: LEGO DUPLO® invaders from outer space, wrecking everything faster than they can rebuild.', 107, '/QTESAsBVZwjtGJNDP7utiGV37z.jpg', '/2U2h8PpsaWn90jdtyG0tu9ZxttZ.jpg', 'cksYkEzUa7k'),
    (281338, 'Caesar and his apes are forced into a deadly conflict with an army of humans led by a ruthless Colonel. After the apes suffer unimaginable losses, Caesar wrestles with his darker instincts and begins his own mythic quest to avenge his kind. As the journey finally brings them face to face, Caesar and the Colonel are pitted against each other in an epic battle that will determine the fate of both their species and the future of the planet.', 140, '/3vYhLLxrTtZLysXtIWktmd57Snv.jpg', '/ulMscezy9YX0bhknvJbZoUgQxO5.jpg', '1TxqmlIv1Iw'),
    (281957, 'In the 1820s, a frontiersman, Hugh Glass, sets out on a path of vengeance against those who left him for dead after a bear mauling.', 157, '/ji3ecJphATlVgWNY0B0RVXZizdf.jpg', '/hEQYZq2CDB2LSJVxxlazdBOKeyW.jpg', 'EhffABvfAW0'),
    (282035, 'Though safely entombed in a crypt deep beneath the unforgiving desert, an ancient queen whose destiny was unjustly taken from her is awakened in our current day, bringing with her malevolence grown over millennia, and terrors that defy human comprehension.', 110, '/zxkY8byBnCsXodEYpK8tmwEGXBI.jpg', '/i4ZougHEyBAboDpi6jsaTUDTjUl.jpg', 's4C1gnqdrew'),
    (283366, 'A teenager finds himself transported to an island where he must help protect a group of orphans with special powers from creatures intent on destroying them.', 127, '/CIlbMFOfYDj0MP23hsIYhFGrL6.jpg', '/ld7V9BjMk2xtiBNcR8savyyk5ca.jpg', 'EMNeogzc_bs'),
    (283995, 'The Guardians must fight to keep their newfound family together as they unravel the mysteries of Peter Quill''s true parentage.', 137, '/y4MBh0EjBlMuOzv9axM4qJlmhzz.jpg', '/aJn9XeesqsrSLKcHfHP4u5985hn.jpg', 'wUn05hdkhjM'),
    (284052, 'After his career is destroyed, a brilliant but arrogant surgeon gets a new lease on life when a sorcerer takes him under her wing and trains him to defend the world against evil.', 115, '/uGBVj3bEbCoZbDjjl9wTxcygko1.jpg', '/kkoiH8ZWxJ9WSAjOadGtuHUQxbm.jpg', 'HSzx-zryEgM'),
    (284053, 'Thor is imprisoned on the other side of the universe and finds himself in a race against time to get back to Asgard to stop Ragnarok, the destruction of his home-world and the end of Asgardian civilization, at the hands of a powerful new threat, the ruthless Hela.', 131, '/rzRwTcFvttcN1ZpX2xv4j3tSdJu.jpg', '/vLmHH8jAy8Jq8uBsLucd3592WGh.jpg', 'ue80QwXMRHg'),
    (284054, 'King T''Challa returns home to the reclusive, technologically advanced African nation of Wakanda to serve as his country''s new leader. However, T''Challa soon finds that he is challenged for the throne by factions within his own country as well as without. Using powers reserved to Wakandan kings, T''Challa assumes the Black Panther mantle to join with ex-girlfriend Nakia, the queen-mother, his princess-kid sister, members of the Dora Milaje (the Wakandan ''special forces'') and an American secret agent, to prevent Wakanda from being dragged into a world war.', 135, '/uxzzxijgPIY7slzFvMotPv8wjKA.jpg', '/b6ZJZHUdMEFECvGiDpJjlfUWela.jpg', 'xjDjIWPwcPU'),
    (285783, 'The story of French high-wire artist Philippe Petit''s attempt to cross the Twin Towers of the World Trade Center in 1974.', 123, '/tiESRqurrZwAC0hpERogOsBhjeg.jpg', '/vAYMNOcGgFa7HtjvOdxQYPGntgz.jpg', '4W6byFcD5uE'),
    (286217, 'During a manned mission to Mars, Astronaut Mark Watney is presumed dead after a fierce storm and left behind by his crew. But Watney has survived and finds himself stranded and alone on the hostile planet. With only meager supplies, he must draw upon his ingenuity, wit and spirit to subsist and find a way to signal to Earth that he is alive.', 141, '/5BHuvQ6p9kfc091Z8RiFNhCwL4b.jpg', '/lzMS0CI3FLQYC5EgJoWeIaEt0lm.jpg', 'ej3ioOneTy8'),
    (286565, 'Quentin Jacobsen has spent a lifetime loving the magnificently adventurous Margo Roth Spiegelman from afar. So when she cracks open a window and climbs back into his life dressed like a ninja and summoning him for an ingenious campaign of revenge, he follows. After their all-nighter ends and a new day breaks, Quentin arrives at school to discover that Margo, always an enigma, has now become a mystery. But Quentin soon learns that there are clues, and they''re for him. Urged down a disconnected path, the closer Quentin gets, the less he sees of the girl he thought he knew.', 109, '/lVW67w7eWwmBhbBCc4f983pO8m6.jpg', '/mwoIzHsliirmS0IlSrf2DvVouid.jpg', 'F1dDr4b36Mo'),
    (287947, 'A boy is given the ability to become an adult superhero in times of need with a single magic word.', 132, '/xnopI5Xtky18MPhK40cZAGAOVeV.jpg', '/o7JVhqMmrex1TPbmuxl8YXVlcfl.jpg', 'uilJZZ_iVwY'),
    (290098, '1930s Korea, in the period of Japanese occupation, a new girl, Sook-hee, is hired as a handmaiden to a Japanese heiress, Hideko, who lives a secluded life on a large countryside estate with her domineering Uncle Kouzuki. But the maid has a secret. She is a pickpocket recruited by a swindler posing as a Japanese Count to help him seduce the Lady to steal her fortune.', 145, '/dLlH4aNHdnmf62umnInL8xPlPzw.jpg', '/2b3RNXF7ca9bgX8FrjRBYfLnNQC.jpg', 'wYsdzNIcJNc'),
    (290595, 'As two evil sisters prepare to conquer the land, two renegades—Eric the Huntsman, who aided Snow White in defeating Ravenna in Snowwhite and the Huntsman, and his forbidden lover, Sara—set out to stop them.', 114, '/ekHPrneEoa1EoDclWdillOKznqM.jpg', '/4kCDWJhceLHwPbRWd9uTR8bJpLz.jpg', 'V9cPxenX1-0'),
    (290859, 'Decades after Sarah Connor prevented Judgment Day, a lethal new Terminator is sent to eliminate the future leader of the resistance. In a fight to save mankind, battle-hardened Sarah Connor teams up with an unexpected ally and an enhanced super soldier to stop the deadliest Terminator yet.', 128, '/vqzNJRH4YyquRiWxCCOH0aXggHI.jpg', '/a6cDxdwaQIFjSkXf7uskg78ZyTq.jpg', 'UqxnFHoKwzE'),
    (291805, 'One year after outwitting the FBI and winning the public’s adulation with their mind-bending spectacles, the Four Horsemen resurface only to find themselves face to face with a new enemy who enlists them to pull off their most dangerous heist yet.', 129, '/A81kDB6a1K86YLlcOtZB27jriJh.jpg', '/oFQilRMEq6yQbtMPxIYWpXeQ5ZN.jpg', 'JzZh8kJJwe4'),
    (292431, 'Murphy is an American living in Paris who enters a highly sexually and emotionally charged relationship with the unstable Electra. Unaware of the seismic effect it will have on their relationship, they invite their pretty neighbor into their bed.', 134, '/yz6lmOmsmYuj6AOLG4LIwK5eJZF.jpg', '/hoszursvZR1C054sTXVQBcBDory.jpg', 'mR4JLD84RBo'),
    (293167, 'Explore the mysterious and dangerous home of the king of the apes as a team of explorers ventures deep inside the treacherous, primordial island.', 118, '/r2517Vz9EhDhj88qwbDVj8DCRZN.jpg', '/nVodCGKYLpqNC8YwQAbivKlWCgZ.jpg', 'dBLdPIp-BuY'),
    (293660, 'The origin story of former Special Forces operative turned mercenary Wade Wilson, who, after being subjected to a rogue experiment that leaves him with accelerated healing powers, adopts the alter ego Deadpool. Armed with his new abilities and a dark, twisted sense of humor, Deadpool hunts down the man who nearly destroyed his life.', 108, '/3E53WEZJqP6aM84D8CckXx4pIHw.jpg', '/rFj9IKlL75B2pXhZA60jkNWvxeW.jpg', '9vN6DHB6bJc'),
    (293863, 'After 29-year-old Adaline recovers from a nearly lethal accident, she inexplicably stops growing older. As the years stretch on and on, Adaline keeps her secret to herself  until she meets a man who changes her life.', 112, '/3XFuCS6wBfpSnUQboLd1JtkJqe0.jpg', '/wTvDGO0xGMmnScqjuiDeWU7PkcB.jpg', '7UzSekc0LoQ'),
    (294254, 'Thomas and his fellow Gladers face their greatest challenge yet: searching for clues about the mysterious and powerful organization known as WCKD. Their journey takes them to the Scorch, a desolate landscape filled with unimaginable obstacles. Teaming up with resistance fighters, the Gladers take on WCKD’s vastly superior forces and uncover its shocking plans for them all.', 131, '/mYw7ZyejqSCPFlrT2jHZOESZDU3.jpg', '/4mcOCiR06dqQ5eoEJcG3zvonjOa.jpg', 'SDofO3P2HpE'),
    (294272, 'For years, old wood carver Mr. Meacham has delighted local children with his tales of the fierce dragon that resides deep in the woods of the Pacific Northwest. To his daughter, Grace, who works as a forest ranger, these stories are little more than tall tales... until she meets Pete, a mysterious 10-year-old with no family and no home who claims to live in the woods with a giant, green dragon named Elliott. And from Pete''s descriptions, Elliott seems remarkably similar to the dragon from Mr. Meacham''s stories. With the help of Natalie, an 11-year-old girl whose father Jack owns the local lumber mill, Grace sets out to determine where Pete came from, where he belongs, and the truth about this dragon.', 103, '/A9x4Ogk8KUXTfU649NS6lS9TCmu.jpg', '/ct9S0m2U2RTCFAVnq3y0nF0Tgb2.jpg', 'Xhv5Kc8dmv8'),
    (294963, 'During a shootout in a saloon, Sheriff Hunt injures a suspicious stranger. The doctor''s assistant, wife of the local foreman, tends to him in prison. That night, the town is attacked and they both disappear—only the arrow of a cannibal tribe is found. Hunt and a few of his men go in search of the prisoner and the foreman''s wife.', 133, '/4MmTHpn2Y8emqvBgvOjufImUmKZ.jpg', '/orXMq2jZy8wFmePv7zXS2Kor7Ug.jpg', '4KNWbfRDEv8'),
    (295693, 'A story about how a new baby''s arrival impacts a family, told from the point of view of a delightfully unreliable narrator, a wildly imaginative 7 year old named Tim.', 97, '/9MsQJKe4cUAGxc7R2NGaFQLqOPc.jpg', '/8280R0bDR1FusPyThAOmAcSC4nu.jpg', 'Ud8j5GaqH3c'),
    (296096, 'Lou Clark, a directionless 26-year-old from the English countryside, takes a job at the local castle as a caregiver and companion to a wealthy young banker, Will Traynor. Wheelchair-bound from an accident two years prior, the once adventurous Will has all but given up — that is until Lou determines to show him that life is worth living.', 110, '/oo2Q3T8juOYFh2G1YJ3oSMAfUyq.jpg', '/3WK7p9EdZmmvB1IbB2Vw9Rf4lXH.jpg', 'T0MmkG_nG1U'),
    (296098, 'During the Cold War, the Soviet Union captures U.S. pilot Francis Gary Powers after shooting down his U-2 spy plane. Sentenced to 10 years in prison, Powers'' only hope is New York lawyer James Donovan, recruited by a CIA operative to negotiate his release. Donovan boards a plane to Berlin, hoping to win the young man''s freedom through a prisoner exchange. If all goes well, the Russians would get Rudolf Abel, the convicted spy who Donovan defended in court.', 141, '/fmOOjHAQzxr0c1sfcY4qkiSRBH6.jpg', '/12M3SvYO4WMdlXCajWklz1zUAly.jpg', 'owhBnicLZt4'),
    (296524, 'A story set on the offshore drilling rig Deepwater Horizon, which exploded during April 2010 and created the worst oil spill in U.S. history.', 107, '/jgBIYCZACe3iaS9TL2XzVGkO5p5.jpg', '/fRT76SSQzAuZljogpsWyKphUxYX.jpg', 'S-UPJyEHmM0'),
    (297761, 'From DC Comics comes the Suicide Squad, an antihero team of incarcerated supervillains who act as deniable assets for the United States government, undertaking high-risk black ops missions in exchange for commuted prison sentences.', 122, '/sk3FZgh3sRrmr8vyhaitNobMcfh.jpg', '/wAk0yKrhAmvsoMvlKs4QImhvK5X.jpg', 'm0Xb9BhfVjY'),
    (297762, 'An Amazon princess comes to the world of Man in the grips of the First World War to confront the forces of evil and bring an end to human conflict.', 141, '/v4ncgZjG2Zu8ZW5al1vIZTsSjqX.jpg', '/AaABt75ZzfMGrscUR2seabz4PEX.jpg', 'VSB4wGIdDwo'),
    (297802, 'Half-human, half-Atlantean Arthur Curry is taken on the journey of his lifetime to discover if he is worth of being a king.', 143, '/ufl63EFcc5XpByEV2Ecdw6WJZAI.jpg', '/9QusGjxcYvfPD1THg6oW3RLeNn7.jpg', '2wcj6SrX4zw'),
    (298250, 'Law enforcement finds itself chasing the ghost of a man dead for over a decade, embroiled in a diabolical new game that''s only just begun.', 91, '/7RwHxhdUNS996JPFNB9a7CJtlwR.jpg', '/ucLGZ3zBRFDhdlRNhvXdkjXkNyd.jpg', 'vPP6aIw1vgY'),
    (298312, 'A brother and sister are sent to their grandparents'' remote Pennsylvania farm for a week, where they discover that the elderly couple is involved in something deeply disturbing.', 94, '/hDrToKMpKYTdwdpOhshL8ko6WVp.jpg', '/p3dOzDESVsKpV36enYI9P2gZxxO.jpg', 'oUmYRfjfL7k'),
    (298618, 'When his attempt to save his family inadvertently alters the future, Barry Allen becomes trapped in a reality in which General Zod has returned and there are no Super Heroes to turn to. In order to save the world that he is in and return to the future that he knows, Barry''s only hope is to race for his life. But will making the ultimate sacrifice be enough to reset the universe?', 144, '/rktDFPbfHfUbArZ6OOOKsXcv0Bm.jpg', '/yF1eOkaYvwiORauRCPWznV9xVvi.jpg', 'jprhe-cWKGs'),
    (299534, 'After the devastating events of Avengers: Infinity War, the universe is in ruins due to the efforts of the Mad Titan, Thanos. With the help of remaining allies, the Avengers must assemble once more in order to undo Thanos'' actions and restore order to the universe once and for all, no matter what consequences may be in store.', 181, '/jtDv3lCnST0fZRvdYFwR5CVwK2x.jpg', '/7RyHsO4yDXtBv1zUU3mTpHeQ0d5.jpg', 'L2NAh3CIdig'),
    (299536, 'As the Avengers and their allies have continued to protect the world from threats too large for any one hero to handle, a new danger has emerged from the cosmic shadows: Thanos. A despot of intergalactic infamy, his goal is to collect all six Infinity Stones, artifacts of unimaginable power, and use them to inflict his twisted will on all of reality. Everything the Avengers have fought for has led up to this moment - the fate of Earth and existence itself has never been more uncertain.', 149, '/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg', '/mDfJG3LC3Dqb67AZ52x3Z0jU0uB.jpg', 'QwievZ1Tx-8'),
    (299537, 'The story follows Carol Danvers as she becomes one of the universe’s most powerful heroes when Earth is caught in the middle of a galactic war between two alien races. Set in the 1990s, Captain Marvel is an all-new adventure from a previously unseen period in the history of the Marvel Cinematic Universe.', 124, '/AtsgWhDnHTq68L0lLsUrCnM7TjG.jpg', '/qAzYK4YPSWDc7aa4R43LcwRIAyb.jpg', 'GX33bIOA5aA'),
    (299687, '16-year-old Cassie Sullivan tries to survive in a world devastated by the waves of an alien invasion that has already decimated the population and knocked mankind back to the Stone Age.', 112, '/4Dd79cz5qxKNoKWg1xsfrpOchEr.jpg', '/rtjZeFESiaRFOj0cwHiNV382flB.jpg', 'kmxLybfGNC4'),
    (300668, 'A biologist signs up for a dangerous, secret expedition into a mysterious zone where the laws of nature don''t apply.', 115, '/4YRplSk6BhH6PRuE9gfyw9byUJ6.jpg', '/9trZvBr44UGedUOiGo3jgSUw13e.jpg', '89OP78l9oF0'),
    (301337, 'A kindly occupational therapist undergoes a new procedure to be shrunken to four inches tall so that he and his wife can help save the planet and afford a nice lifestyle at the same time.', 135, '/5bNzInSSAXfr0MFlHfb4IoQePVx.jpg', '/rtr0l61RxLPkmZHbZj0WFlGx5G5.jpg', '_POpCkJToEQ'),
    (301528, 'Woody has always been confident about his place in the world, devoted to taking care of his kid—whether that''s Andy or Bonnie. But after Bonnie creates a reluctant new toy called "Forky", a road trip adventure alongside old and new friends challenges everything Woody believes about loyalty, purpose, and what it truly means to be a toy.', 100, '/w9kR8qbmQ01HwnvK4alvnQ2ca0L.jpg', '/q62bpQ67qaXY0u6b2wFEnQYIbPd.jpg', 'Pl9JS8-gnWQ'),
    (302401, 'CIA employee Edward Snowden leaks thousands of classified documents to the press.', 135, '/yfK7zxNL63VWfluFuoUaJj5PdNw.jpg', '/mYZYVrQ2ghU3m79q7byeLzNXo1M.jpg', 'QlSAiI3xMh4'),
    (302699, 'Calvin Joyner, a mild-mannered accountant whose high school glory days are long behind him, reconnects with an awkward pal from high school through Facebook. After meeting up, Calvin’s mundane life takes an unexpectedly thrilling turn when he''s thrust into the world of international espionage.', 107, '/hXQVMbRNpf7c93e8clMY4W5DRm6.jpg', '/12gfRwL8RuZUQ4kiGzq9kRYBK5J.jpg', 'J_8OsnCTRx8'),
    (305470, 'Five ordinary teens must become something extraordinary when they learn that their small town of Angel Grove — and the world — is on the verge of being obliterated by an alien threat. Chosen by destiny, our heroes quickly discover they are the only ones who can save the planet. But to do so, they will have to overcome their real-life issues and before it’s too late, band together as the Power Rangers.', 124, '/bKYKyyIv5YnisxjZtDreWtYA386.jpg', '/z6UzOfIURK7n5MthpcYpFnqMNc0.jpg', 'oFkulzWMotY'),
    (306947, 'Will and his new girlfriend Kira are invited to a dinner with old friends at the house of Will’s ex Eden and her new partner David. Although the evening appears to be relaxed, Will soon gets a creeping suspicion that their charming host David is up to something.', 100, '/esubm23z8N5JUA1wQ5yLSjLicDx.jpg', '/UT0FaX3djSmvphvDopomPNWXIQ.jpg', 'wcFaLtnx43w'),
    (308266, 'Based on the true story of two young men, David Packouz and Efraim Diveroli, who won a $300 million contract from the Pentagon to arm America''s allies in Afghanistan.', 114, '/mDcPRjZC1bb6LavFU3gwsWdVfCM.jpg', '/oNoprEND25zXR6Fns8cIZUkuoMc.jpg', 'KWs5qnZnhfo'),
    (308531, 'After supervillain Shredder escapes custody, he joins forces with mad scientist Baxter Stockman and two dimwitted henchmen, Bebop and Rocksteady, to unleash a diabolical plan to take over the world. As the Turtles prepare to take on Shredder and his new crew, they find themselves facing an even greater evil with similar intentions: the notorious Krang.', 112, '/euVaCiCWz3AALcQXHT6aUqdGUo6.jpg', '/41objfan7PDTBG5MFXQl4ownQzJ.jpg', 'ubursnjg8NA'),
    (310131, 'In 1630, a farmer relocates his family to a remote plot of land on the edge of a forest where strange, unsettling things happen. With suspicion and paranoia mounting, each family member''s faith, loyalty and love are tested in shocking ways.', 92, '/zap5hpFCWSvdWSuPGAQyjUv2wAC.jpg', '/zi2oYYNSSv7t44iSt5YrxHX9PYs.jpg', '97OQ7MQC5Ck'),
    (310307, 'The true story of how Ray Kroc, a salesman from Illinois, met Mac and Dick McDonald, who were running a burger operation in 1950s Southern California. Kroc was impressed by the brothers’ speedy system of making the food and saw franchise potential. He maneuvered himself into a position to be able to pull the company from the brothers and create a billion-dollar empire.', 115, '/8gLIksu5ggdfBL1UbeTeonHquxl.jpg', '/5WparwIlAtSZW0tcWbK2NHEZJC6.jpg', 'oprJX5BomEc'),
    (311324, 'European mercenaries searching for black powder become embroiled in the defense of the Great Wall of China against a horde of monstrous creatures.', 103, '/p70dq1YxabemdZDm5K6Q8G10wSn.jpg', '/th26RNksfM9nn7DPH06OqiV6BA2.jpg', 'Bnsesxk5LF4'),
    (312221, 'The former World Heavyweight Champion Rocky Balboa serves as a trainer and mentor to Adonis Johnson, the son of his late friend and former rival Apollo Creed.', 133, '/1BfTsk5VWuw8FCocAhCyqnRbEzq.jpg', '/kODNw6GJNdgldUMEhKPlCw8wQCr.jpg', 'JQ9OhBYjTds'),
    (313297, 'Kubo mesmerizes the people in his village with his magical gift for spinning wild tales with origami. When he accidentally summons an evil spirit seeking vengeance, Kubo is forced to go on a quest to solve the mystery of his fallen samurai father and his mystical weaponry, as well as discover his own magical powers.', 102, '/la6QA9tk4Foq8OBH2Dyh5dTcw6H.jpg', '/bhspYsRMHgMqzUlxiVpIY8OrqMt.jpg', 'Pz49Ml_rB34'),
    (313369, 'Mia, an aspiring actress, serves lattes to movie stars in between auditions and Sebastian, a jazz musician, scrapes by playing cocktail party gigs in dingy bars, but as success mounts they are faced with decisions that begin to fray the fragile fabric of their love affair, and the dreams they worked so hard to maintain in each other threaten to rip them apart.', 129, '/uDO8zWDhfWwoFdKS4fzkUJt0Rf0.jpg', '/nlPCdZlHtRNcF6C9hzUH4ebmV1w.jpg', 'Zfy4rGzZDes'),
    (313922, 'Members of a punk rock band and a tough young woman are forced to fight for survival after witnessing an act of violence at a skinhead bar.', 95, '/evZicaR7nXe4LiD9G6QYTorcJGO.jpg', '/qRjahAq8JVoJBT2x18x2A01kxZT.jpg', 'T_Tklsuiako'),
    (314365, 'The true story of how the Boston Globe uncovered the massive scandal of child molestation and cover-up within the local Catholic Archdiocese, shaking the entire Catholic Church to its core.', 129, '/8DPGG400FgaFWaqcv11n8mRd2NG.jpg', '/8FbbcmwmpGd7brfiC7f7lWFNGdi.jpg', 'WgnrwwiIDlI'),
    (315162, 'Puss in Boots discovers that his passion for adventure has taken its toll: He has burned through eight of his nine lives, leaving him with only one life left. Puss sets out on an epic journey to find the mythical Last Wish and restore his nine lives.', 103, '/kuf6dutpsT0vSVehic3EZIqkOBt.jpg', '/jr8tSoJGj33XLgFBy6lmZhpGQNu.jpg', 'tHb7WlgyaUc'),
    (315635, 'Following the events of Captain America: Civil War, Peter Parker, with the help of his mentor Tony Stark, tries to balance his life as an ordinary high school student in Queens, New York City, with fighting crime as his superhero alter ego Spider-Man as a new threat, the Vulture, emerges.', 133, '/c24sv2weTHPsmDa7jEMN0m2P3RT.jpg', '/fn4n6uOYcB6Uh89nbNPoU2w80RV.jpg', 'xEvV3OsE2WM'),
    (315837, 'In the near future, Major is the first of her kind: a human saved from a terrible crash, then cyber-enhanced to be a perfect soldier devoted to stopping the world''s most dangerous criminals.', 107, '/zCtL3UBgCoZzd7XTVGhvl6XY75E.jpg', '/dDVqfmCzSy3TKSmiS2pJ9QB5E3P.jpg', '5XnptKCeaJE'),
    (316029, 'The story of American showman P.T. Barnum, founder of the circus that became the famous traveling Ringling Bros. and Barnum & Bailey Circus.', 105, '/b9CeobiihCx1uG1tpw8hXmpi7nm.jpg', '/lrNKm3HNvGdZoAfiBKu7b04FLHN.jpg', 'KTNtpYQPlhE'),
    (317442, 'Two years after the events of the Fourth Great Ninja War, the moon that Hagoromo Otsutsuki created long ago to seal away the Gedo Statue begins to descend towards the world, threatening to become a meteor that would destroy everything on impact. Amidst this crisis, a direct descendant of Kaguya Otsutsuki named Toneri Otsutsuki attempts to kidnap Hinata Hyuga but ends up abducting her younger sister Hanabi. Naruto and his allies now mount a rescue mission before finding themselves embroiled in a final battle to decide the fate of everything.', 114, '/bAQ8O5Uw6FedtlCbJTutenzPVKd.jpg', '/l8ubUlfzlB5R2j9cJ3CN7tj0gmd.jpg', 'SDIvvapG0sE'),
    (318846, 'In 2008, Wall Street outsider Michael Burry discovers that the U.S. housing market is on the verge of collapse due to widespread defaults on subprime mortgages, causing him to bet against the housing market by throwing more than $1 billion of his investors'' money into credit default swaps. His actions attract the attention of banker Jared Vennett, hedge-fund specialist Mark Baum, and other greedy opportunists. Together, these men make a fortune by taking full advantage of the impending economic collapse in America.', 131, '/scVEaJEwP8zUix8vgmMoJJ9Nq0w.jpg', '/iof28QKa6bKFYCXSexuITxdKBvi.jpg', '1kQc3mmtH-o'),
    (319888, 'The feel-good story of Michael ''Eddie'' Edwards, an unlikely but courageous British ski-jumper who never stopped believing in himself—even as an entire nation was counting him out. With the help of a rebellious and charismatic coach, Eddie takes on the establishment and wins the hearts of sports fans around the world by making an improbable and historic showing at the 1988 Calgary Winter Olympics.', 106, '/r562gvTRVHnDSvG7MrKHEECSn1V.jpg', '/jbcEWHYpnlZ1aiMCLcRyiIhwUwY.jpg', 'hyzQjVUmIxk'),
    (320288, 'The X-Men face their most formidable and powerful foe when one of their own, Jean Grey, starts to spiral out of control. During a rescue mission in outer space, Jean is nearly killed when she''s hit by a mysterious cosmic force. Once she returns home, this force not only makes her infinitely more powerful, but far more unstable. The X-Men must now band together to save her soul and battle aliens that want to use Grey''s new abilities to rule the galaxy.', 114, '/cCTJPelKGLhALq3r51A9uMonxKj.jpg', '/j9ZV0UOagjQ4seR8Hd5N6JfwdTP.jpg', 'azvR__GRQic'),
    (321258, 'A young American woman takes a job as a nanny in a remote English village, soon discovering that the family''s eight-year-old son is a life-sized doll that comes with a list of strict rules.', 98, '/kW2vgzhyWXQu5UxNzebPokipBqH.jpg', '/mRUW8rmpCS2kH22eihPbbMIbFxU.jpg', 'jfhHg3eeqS0'),
    (321612, 'A live-action adaptation of Disney''s version of the classic tale of a cursed prince and a beautiful young woman who helps him break the spell.', 129, '/hKegSKIDep2ewJWPUQD7u0KqFIp.jpg', '/uU1Mt4JWhDvl4vKb3AfxNsorkoM.jpg', 'hYO2Ga4WDk4'),
    (321697, 'Set backstage at three iconic product launches and ending in 1998 with the unveiling of the iMac, Steve Jobs takes us behind the scenes of the digital revolution to paint an intimate portrait of the brilliant man at its epicenter.', 122, '/ljiRO29Y9khEERRqMluptUYunJ9.jpg', '/xj49X22pmh61fWBsveCkHtVtOBS.jpg', '9XEh7arNSms'),
    (324552, 'John Wick is forced out of retirement by a former associate looking to seize control of a shadowy international assassins’ guild. Bound by a blood oath to aid him, Wick travels to Rome and does battle against some of the world’s most dangerous killers.', 122, '/hXWBc0ioZP3cN4zCu6SN3YHXZVO.jpg', '/Aa9Lx6gotP0szl9tlt5SPCN08oF.jpg', 'LZrX9mffH8Y'),
    (324668, 'The most dangerous former operative of the CIA is drawn out of hiding to uncover hidden truths about his past.', 123, '/xA7N41glw17MBQtcWSm2eBlBRuG.jpg', '/7mHeyU0a538bgguOeF57I8ZroSk.jpg', 'F4gJsKZvqE4'),
    (324670, 'A special-ops team is dispatched to fight supernatural beings that have taken over a European city.', 109, '/5yprxs7ZyBr58RsTQJrKCVmqk8X.jpg', '/cBrzOqgAJv1YG4Jww9dt1B54Sv8.jpg', 'rmC3ZhIHHi4'),
    (324786, 'WWII American Army Medic Desmond T. Doss, who served during the Battle of Okinawa, refuses to kill people and becomes the first Conscientious Objector in American history to receive the Congressional Medal of Honor.', 139, '/fnOMP6mjmOmZwmlC1n0K7ivrzt1.jpg', '/vDKRMZGFTKP9nQolzeSB1rB1w6p.jpg', 's2-1hz1juBI'),
    (324849, 'A cooler-than-ever Batman must face the usual villains as the Joker plots a takeover of Gotham City. But when Bruce Wayne accidentally adopts a teenage orphan who wishes to become his sidekick, he’s forced to give up his lone-vigilante ways and learn to work with others.', 104, '/e1TliRWOdXQ73pRunbpFiGst6Kd.jpg', '/rWYtghaUJSDvQm4jmXiCPXBHUdQ.jpg', 'rGQUKzSDhrg'),
    (324852, 'Gru and his wife Lucy must stop former ''80s child star Balthazar Bratt from achieving world domination.', 90, '/e72KCMHNkbZ6USRJmABeqwmaJ5n.jpg', '/ftRkFtAGuHngHnLiOxktq0aCVMF.jpg', 'oagwBHoh6Rs'),
    (324857, 'Struggling to find his place in the world while juggling school and family, Brooklyn teenager Miles Morales is unexpectedly bitten by a radioactive spider and develops unfathomable powers just like the one and only Spider-Man. While wrestling with the implications of his new abilities, Miles discovers a super collider created by the madman Wilson "Kingpin" Fisk, causing others from across the Spider-Verse to be inadvertently transported to his dimension.', 117, '/iiZZdoQBEYBv6id8su7ImL0oCbD.jpg', '/1ntePsIqeklfmrQJqZPncCydsqY.jpg', 'tg52up16eq0'),
    (325348, 'Henry, a newly resurrected cyborg who must save his wife/creator from the clutches of a psychotic tyrant with telekinetic powers, AKAN, and his army of mercenaries. Fighting alongside Henry is Jimmy, who is Henry''s only hope to make it through the day. Hardcore Henry takes place over the course of one day, in Moscow, Russia.', 97, '/ik1uZyiMSxF9HqrgRKUNfMCfr3z.jpg', '/2t6OUcM8SQVurkgkTz2gukNsAim.jpg', '4JVgQzBG5Ho'),
    (328111, 'The quiet life of a terrier named Max is upended when his owner takes in Duke, a stray whom Max instantly dislikes.', 86, '/g3Hms6AE174doeGR1gz5zX5sVsv.jpg', '/c1Ywtvlqls6tPBZ3BqbPtBwHyng.jpg', 'eWI_Jsw9qUs'),
    (328387, 'Industrious high school senior Vee Delmonico has had it with living life on the sidelines. When pressured by friends to join the popular online game Nerve, Vee decides to sign up for just one dare in what seems like harmless fun. But as she finds herself caught up in the thrill of the adrenaline-fueled competition partnered with a mysterious stranger, the game begins to take a sinister turn with increasingly dangerous acts, leading her into a high stakes finale that will determine her entire future.', 96, '/qmSpHC0CSNyNll9WhlwWYuwoQ28.jpg', '/fg04CQyJzuDJ82jm2meY37n9XyE.jpg', '2PR9MOPTI7g'),
    (329865, 'Taking place after alien crafts land around the world, an expert linguist is recruited by the military to determine whether they come in peace or are a threat.', 116, '/pEzNVQfdzYDzVK0XqxERIw2x2se.jpg', '/8MUZz7oPXQftFTslZpRP3CVMOoq.jpg', '7W1m5ER3I1Y'),
    (329996, 'A young elephant, whose oversized ears enable him to fly, helps save a struggling circus, but when the circus plans a new venture, Dumbo and his friends discover dark secrets beneath its shiny veneer.', 112, '/A7XkpLfNH0El2yyDLc4b0KLAKvE.jpg', '/5tFt6iuGnKapHl5tw0X0cKcnuVo.jpg', '7NiYVoqBt-8'),
    (330457, 'Elsa, Anna, Kristoff and Olaf head far into the forest to learn the truth about an ancient mystery of their kingdom.', 103, '/mINJaa34MtknCYl5AjtNJzWj8cD.jpg', '/AoSZyb37ljMAxw0RdeQEBHKtgcc.jpg', 'vSKlICmmi98'),
    (330459, 'A rogue band of resistance fighters unite for a mission to steal the Death Star plans and bring a new hope to the galaxy.', 133, '/1zoZ0e2q34FUnT7xuEnGazBFrbL.jpg', '/6t8ES1d12OzWyCGxBeDYLHoaDrT.jpg', 'sC9abcLLQpI'),
    (331482, 'Four sisters come of age in America in the aftermath of the Civil War.', 135, '/yn5ihODtZ7ofn8pDYfxCmxh8AXI.jpg', '/A8EzeMnCrQfnNZVpULItCbYlK7C.jpg', 'AST2-4db4ic'),
    (332210, 'Storks deliver babies…or at least they used to. Now they deliver packages for a global internet retail giant. Junior, the company’s top delivery stork, is about to be promoted when he accidentally activates the Baby Making Machine, producing an adorable and wholly unauthorized baby girl...', 87, '/pwGolX8JmGJhhcUjO5SJt38Uk0m.jpg', '/3dhuShnYmB0UOQrn8v8gT9DBf0T.jpg', 'O3W90X_O3JE'),
    (332562, 'Seasoned musician Jackson Maine discovers — and falls in love with — struggling artist Ally. She has just about given up on her dream to make it big as a singer — until Jack coaxes her into the spotlight. But even as Ally''s career takes off, the personal side of their relationship is breaking down, as Jack fights an ongoing battle with his own internal demons.', 136, '/wrFpXMNBRj2PBiN4Z5kix51XaIZ.jpg', '/dDYpjrwh1wNVQk0rEpc9P81wQt4.jpg', 'UywJmJ6ohvc'),
    (332567, 'While surfing on a secluded beach, Nancy finds herself in the feeding grounds of a great white shark. Though stranded only 200 yards from shore, survival proves to be the ultimate test of wills, requiring all of her ingenuity, resourcefulness, and fortitude.', 87, '/bnBV7hZmLuA0Si5Aop481sPF2RY.jpg', '/5W160Z6MGl6xB7QomSwfdsRKVJx.jpg', 'EgdxIlSuB70'),
    (333339, 'When the creator of a popular video game system dies, a virtual contest is created to compete for his fortune.', 140, '/pU1ULUq8D3iRxl1fdX2lZIzdHuI.jpg', '/5a7lMDn3nAj2ByO0X1fg6BhUphR.jpg', '1hrwbc5qCZ4'),
    (333371, 'After a catastrophic car crash, a young woman wakes up in a survivalist''s underground bunker, where he claims to have saved her from an apocalyptic attack that has left the outside world uninhabitable.', 104, '/q8A39vcBDruhvoDTJd6L8a4lnTi.jpg', '/dMERTVrObB7TkRVIFmcndR2sZFH.jpg', 'yQy-ANhnUpE'),
    (333484, 'Looking to mine for gold, greedy industrialist Bartholomew Bogue seizes control of the Old West town of Rose Creek. With their lives in jeopardy, Emma Cullen and other desperate residents turn to bounty hunter Sam Chisolm for help. Chisolm recruits an eclectic group of gunslingers to take on Bogue and his ruthless henchmen. With a deadly showdown on the horizon, the seven mercenaries soon find themselves fighting for more than just money once the bullets start to fly.', 132, '/ezcS78TIjgr85pVdaPDd2rSPVNs.jpg', '/4qxZJRYe4ezA5J1sidnV7vuaYaz.jpg', 'q-RBA0xoaWU'),
    (334533, 'Deep in the forests of the Pacific Northwest, a father devoted to raising his six kids with a rigorous physical and intellectual education is forced to leave his paradise and enter the world, beginning a journey that challenges his idea of what it means to be a parent.', 119, '/2sFME73GaD8UsUxPUKe60cPdLif.jpg', '/d84M69u6Q202dm6EvhVxbiqrK9f.jpg', 'w5jeBvjcJe4'),
    (334541, 'After his older brother passes away, Lee Chandler is forced to return home to care for his 16-year-old nephew. There he is compelled to deal with a tragic past that separated him from his family and the community where he was born and raised.', 138, '/o9VXYOuaJxCEKOxbA86xqtwmqYn.jpg', '/fjk4eE8Ypke4YLv5A3ArDH4GzYH.jpg', 'NxQmuJnrjxg'),
    (334543, 'A five-year-old Indian boy gets lost on the streets of Calcutta, thousands of kilometers from home. He survives many challenges before being adopted by a couple in Australia; 25 years later, he sets out to find his lost family.', 118, '/kCELJH1tCmaRLqvwIgKDb09aEaw.jpg', '/ycABRSIK1Ff10Tc2A6WJHagp1Co.jpg', 'GKkk-hDigTk'),
    (335787, 'A young street-smart, Nathan Drake and his wisecracking partner Victor “Sully” Sullivan embark on a dangerous pursuit of “the greatest treasure never found” while also tracking clues that may lead to Nathan’s long-lost brother.', 116, '/rJHC1RUORuUhtfNb4Npclx0xnOf.jpg', '/fwrqW8Lp5VQuppFrODd4iJ8LySE.jpg', 'l-LD16Yzi2c'),
    (335797, 'A koala named Buster recruits his best friend to help him drum up business for his theater by hosting a singing competition.', 108, '/rwopfpHqPCYBSgBuZwkaXXqHp14.jpg', '/z9ft5HYHzWcasR6SGcgeluxTznB.jpg', 'GIgXWuLQPFY'),
    (335977, 'Finding himself in a new era, and approaching retirement, Indy wrestles with fitting into a world that seems to have outgrown him. But as the tentacles of an all-too-familiar evil return in the form of an old rival, Indy must don his hat and pick up his whip once more to make sure an ancient and powerful artifact doesn''t fall into the wrong hands.', 155, '/Af4bXE63pVsb2FtbW8uYIyPBadD.jpg', '/57JocxmicOoAMhkUSmdKBlpZWMT.jpg', 'eQfMbSe7F2g'),
    (335983, 'Investigative journalist Eddie Brock attempts a comeback following a scandal, but accidentally becomes the host of Venom, a violent, super powerful alien symbiote. Soon, he must rely on his newfound powers to protect the world from a shadowy organization looking for a symbiote of their own.', 112, '/2uNW4WbgBXL25BAbXGLnLqX71Sw.jpg', '/VuukZLgaCrho2Ar8Scl9HtV3yD.jpg', 'xLCn88bfW1o'),
    (335984, 'Thirty years after the events of the first film, a new blade runner, LAPD Officer K, unearths a long-buried secret that has the potential to plunge what''s left of society into chaos. K''s discovery leads him on a quest to find Rick Deckard, a former LAPD blade runner who has been missing for 30 years.', 164, '/gajva2L0rPYkEWjzgFlBXCAVBE5.jpg', '/gNdLJU9TxrpGx4dkZidjys3fyy0.jpg', 'geFtxCSz8xI'),
    (335988, 'Humans and Transformers are at war. Optimus Prime is gone. The key to saving our future lies buried in the secrets of the past, in the hidden history of Transformers on Earth. Saving our world falls upon the shoulders of an unlikely alliance: Cade Yeager; Bumblebee; an English Lord; and an Oxford Professor.', 154, '/s5HQf2Gb3lIO2cRcFwNL9sn1o1o.jpg', '/1n00NlOGRFZVs8coBxyZLm5l4EC.jpg', 'e_uBTsgRJlk'),
    (336843, 'Thomas leads his group of escaped Gladers on their final and most dangerous mission yet. To save their friends, they must break into the legendary Last City, a WCKD-controlled labyrinth that may turn out to be the deadliest maze of all. Anyone who makes it out alive will get answers to the questions the Gladers have been asking since they first arrived in the maze.', 143, '/s8K0US4tUEoOrQ1LDh0eppuwGDx.jpg', '/zGCfnZ3bCowMY9So9ZGpsyuOYl3.jpg', 'Ww1GiTIJF_Y'),
    (337167, 'Believing they have left behind shadowy figures from their past, newlyweds Christian and Ana fully embrace an inextricable connection and shared life of luxury. But just as she steps into her role as Mrs. Grey and he relaxes into an unfamiliar stability, new threats could jeopardize their happy ending before it even begins.', 110, '/jjPJ4s3DWZZvI4vw8Xfi4Vqa1Q8.jpg', '/9ywA15OAiwjSTvg3cBs9B7kOCBF.jpg', 'nJCc5HRPxYA'),
    (337170, 'The true story of pilot Barry Seal, who transported contraband for the CIA and the Medellin cartel in the 1980s.', 115, '/23ILgoPSO5ShKcTZOuiTVfqFAUB.jpg', '/5TKGbYKEwGrJlHFfTQzaz1FC5AJ.jpg', 'AEBIJRAkujM'),
    (337339, 'When a mysterious woman seduces Dom into the world of crime and a betrayal of those closest to him, the crew face trials that will test them as never before.', 136, '/dImWM7GJqryWJO9LHa3XQ8DD5NH.jpg', '/3IJ8kG8i84PncXkSovu0PaZQfjM.jpg', 'iVdIiOKBPkg'),
    (337401, 'When the Emperor of China issues a decree that one man per family must serve in the Imperial Chinese Army to defend the country from Huns, Hua Mulan, the eldest daughter of an honored warrior, steps in to take the place of her ailing father. She is spirited, determined and quick on her feet. Disguised as a man by the name of Hua Jun, she is tested every step of the way and must harness her innermost strength and embrace her true potential.', 115, '/aKx1ARwG55zZ0GpRvU2WrGrCG9o.jpg', '/zMrk2G3XsnfYKiIp1NEfdtvDyBH.jpg', 'R-eFm--k21c'),
    (337404, 'In 1970s London amidst the punk rock revolution, a young grifter named Estella is determined to make a name for herself with her designs. She befriends a pair of young thieves who appreciate her appetite for mischief, and together they are able to build a life for themselves on the London streets. One day, Estella’s flair for fashion catches the eye of the Baroness von Hellman, a fashion legend who is devastatingly chic and terrifyingly haute. But their relationship sets in motion a course of events and revelations that will cause Estella to embrace her wicked side and become the raucous, fashionable and revenge-bent Cruella.', 134, '/hjS9mH8KvRiGHgjk6VUZH7OT0Ng.jpg', '/6MKr3KgOLmzOP6MSuZERO41Lpkt.jpg', 'jpZrVxvG3mk'),
    (338762, 'After he and his wife are murdered, marine Ray Garrison is resurrected by a team of scientists. Enhanced with nanotechnology, he becomes a superhuman, biotech killing machine—''Bloodshot''. As Ray first trains with fellow super-soldiers, he cannot recall anything from his former life. But when his memories flood back and he remembers the man that killed both him and his wife, he breaks out of the facility to get revenge, only to discover that there''s more to the conspiracy than he thought.', 110, '/8WUVHemHFH2ZIP6NWkwlHWsyrEL.jpg', '/zlqMASc3vEtdym2OvXgE7fC6onT.jpg', '0R-qIOGyEcw'),
    (338766, 'A divorced dad and his ex-con brother resort to a desperate scheme in order to save their family''s farm in West Texas.', 102, '/ljRRxqy2aXIkIBXLmOVifcOR021.jpg', '/rmPx82V79OetmdWDkyw1gyED6OE.jpg', 'igD-fXiHRRY'),
    (338952, 'Gellert Grindelwald has escaped imprisonment and has begun gathering followers to his cause—elevating wizards above all non-magical beings. The only one capable of putting a stop to him is the wizard he once called his closest friend, Albus Dumbledore. However, Dumbledore will need to seek help from the wizard who had thwarted Grindelwald once before, his former student Newt Scamander, who agrees to help, unaware of the dangers that lie ahead. Lines are drawn as love and loyalty are tested, even among the truest friends and family, in an increasingly divided wizarding world.', 134, '/fMMrl8fD9gRCFJvsx0SuFwkEOop.jpg', '/i3rRY0EKYhSpyOLRAQ7iB05zhAp.jpg', '8bYBOVWLNIs'),
    (338953, 'Professor Albus Dumbledore knows the powerful, dark wizard Gellert Grindelwald is moving to seize control of the wizarding world. Unable to stop him alone, he entrusts magizoologist Newt Scamander to lead an intrepid team of wizards and witches. They soon encounter an array of old and new beasts as they clash with Grindelwald''s growing legion of followers.', 142, '/3c5GNLB4yRSLBby0trHoA1DSQxQ.jpg', '/zGLHX92Gk96O1DJvLil7ObJTbaL.jpg', 'Fo6TfHkLW6Y'),
    (338967, 'Columbus, Tallahassee, Wichita, and Little Rock move to the American heartland as they face off against evolved zombies, fellow survivors, and the growing pains of the snarky makeshift family.', 99, '/dtRbVsUb5O12WWO54SRpiMtHKC0.jpg', '/e7tMI0zVKJB2TS74TaBifIZIkCp.jpg', 'ZlW9yhUKlkQ'),
    (338970, 'Lara Croft, the fiercely independent daughter of a missing adventurer, must push herself beyond her limits when she finds herself on the island where her father disappeared.', 118, '/s4Qn5LF6OwK4rIifmthIDtbqDSs.jpg', '/ohijjhvNqAPKTURQr6VIF7xuAjY.jpg', '3KkhD0MnaJU'),
    (339403, 'After being coerced into working for a crime boss, a young getaway driver finds himself taking part in a heist doomed to fail.', 113, '/tYzFuYXmT8LOYASlFCkaPiAFAl0.jpg', '/yir5430WblZSZuIMd9C6pIZerfA.jpg', 'jGGptGEAo2U'),
    (339527, 'A psychic doctor, John Clancy, works with an FBI special agent in search of a serial killer.', 101, '/pbcXpZgem8kgr90RwIUNAbC2ite.jpg', '/6rjS9JKTQVKknMWu6x6041s97Jx.jpg', 'kEu7BS8IsuA'),
    (339964, 'In the 28th century, Valerian and Laureline are special operatives charged with keeping order throughout the human territories. On assignment from the Minister of Defense, the two undertake a mission to Alpha, an ever-expanding metropolis where species from across the universe have converged over centuries to share knowledge, intelligence, and cultures. At the center of Alpha is a mysterious dark force which threatens the peaceful existence of the City of a Thousand Planets, and Valerian and Laureline must race to identify the menace and safeguard not just Alpha, but the future of the universe.', 137, '/vlc95gl3PtrjxSEuM8RhTtSm2xU.jpg', '/5rYnygKCkmqWuMv1O5yAnzGF8gV.jpg', '_shrCoqWh9k'),
    (339988, 'A young tech worker takes a job at a powerful Internet corporation, quickly rises up the company''s ranks, and soon finds herself in a perilous situation concerning privacy, surveillance and freedom. She comes to learn that her decisions and actions will determine the future of humanity.', 110, '/bQVqd5rWrx5GbXhJNuvKy4Viz6j.jpg', '/2NGBchckkORvJ94ojJWQDqgVvEX.jpg', 'QUlr8Am4zQ0'),
    (340102, 'Five young mutants, just discovering their abilities while held in a secret facility against their will, fight to escape their past sins and save themselves.', 94, '/xiDGcXJTvu1lazFRYip6g1eLt9c.jpg', '/1MoeNacOltBWojkStjhT3svBTOK.jpg', 'W_vJhUAOFpI'),
    (340666, 'Susan Morrow receives a book manuscript from her ex-husband – a man she left 20 years earlier – asking for her opinion of his writing. As she reads, she is drawn into the fictional life of Tony Hastings, a mathematics professor whose family vacation turns violent.', 116, '/mdLDgQBD0va09npSQX5Zgo2evXM.jpg', '/5d6m8CIBQcHeiwr6R5ou4wxO9Vn.jpg', 'SI45fDplBpw'),
    (341013, 'An undercover MI6 agent is sent to Berlin during the Cold War to investigate the murder of a fellow agent and recover a missing list of double agents.', 115, '/kV9R5h0Yct1kR8Hf8sJ1nX0Vz4x.jpg', '/g3hni0i9iAQ13jDGOFWavJFlojc.jpg', 'Rd5FJIUS6Jk'),
    (341174, 'When a wounded Christian Grey tries to entice a cautious Ana Steele back into his life, she demands a new arrangement before she will give him another chance. As the two begin to build trust and find stability, shadowy figures from Christian’s past start to circle the couple, determined to destroy their hopes for a future together.', 118, '/w3qa274gvca9t8pkUoG8nfQgTU3.jpg', '/16aJtXO6lObbBUr11IvkjB1QD1f.jpg', 'vnLqJLeTMVU'),
    (343611, 'Years after resigning command of an elite military police unit, the nomadic, righter-of-wrongs Reacher is drawn back into the life he left behind when his friend and successor, Major Susan Turner is framed for espionage. Reacher will stop at nothing to prove her innocence and to expose the real perpetrators behind the killings of his former soldiers.', 118, '/cOg3UT2NYWHZxp41vpxAnVCOC4M.jpg', '/ww1eIoywghjoMzRLRIcbJLuKnJH.jpg', 'DTBcGQWmQ1c'),
    (343668, 'When an attack on the Kingsman headquarters takes place and a new villain rises, Eggsy and Merlin are forced to work together with the American agency known as the Statesman to save the world.', 141, '/34xBL6BXNYFqtHO9zhcgoakS4aP.jpg', '/eVHVwP71el20fofkCHo78ebQv7Q.jpg', '0fvqnGmr9S8'),
    (345911, 'Rebecca must unlock the terror behind her little brother''s experiences that once tested her sanity, bringing her face to face with a supernatural spirit attached to their mother.', 81, '/AjZXonSbqC3LdSr8xCUzMiQksrM.jpg', '/bQt5iJCIIxTWe8fzAgoMafDaz31.jpg', 'H_nTMprod00'),
    (345920, 'Retreating from life after a tragedy, a man questions the universe by writing to Love, Time and Death. Receiving unexpected answers, he begins to see how these things interlock and how even loss can reveal moments of meaning and beauty.', 97, '/4vfqosgik5pLb32RpskYifp8PWJ.jpg', '/iovi35nPfjbYTw2gRo7uImWblRU.jpg', 'w1tfLWxcEzw'),
    (345940, 'A deep sea submersible pilot revisits his past fears in the Mariana Trench, and accidentally unleashes the seventy foot ancestor of the Great White Shark believed to be extinct.', 113, '/eyWICPcxOuTcDDDbTMOZawoOn8d.jpg', '/ibKeXahq4JD63z6uWQphqoJLvNw.jpg', 'b_4uXy2Y1SQ'),
    (346648, 'Paddington, now happily settled with the Browns, picks up a series of odd jobs to buy the perfect present for his Aunt Lucy, but it is stolen.', 104, '/1OJ9vkD5xPt3skC6KguyXAgagRZ.jpg', '/iJgNOTSBNrC90U2xyYq9ln0b35o.jpg', '07Um1PY_P4o'),
    (346698, 'Barbie and Ken are having the time of their lives in the colorful and seemingly perfect world of Barbie Land. However, when they get a chance to go to the real world, they soon discover the joys and perils of living among humans.', 114, '/iuFNMS8U5cb6xfzi51Dbkovj7vM.jpg', '/1esAE8sLJRWWFsLLeh5r3g2WanI.jpg', 'Y1IgAEejvqM'),
    (346910, 'When a young boy accidentally triggers the universe''s most lethal hunters'' return to Earth, only a ragtag crew of ex-soldiers and a disgruntled scientist can prevent the end of the human race.', 107, '/a3eWGF6YPF7No5Rbtjc8QpDvz7l.jpg', '/b96OdaJce7Zu70NYe8vmlfOQUUN.jpg', '50_Ala5BKBo'),
    (347031, 'Alone on a tiny deserted island, Hank has given up all hope of ever making it home again. But one day everything changes when a dead body washes ashore, and he soon realizes it may be his last opportunity to escape certain death. Armed with his new “friend” and an unusual bag of tricks, the duo go on an epic adventure to bring Hank back to the woman of his dreams.', 97, '/xE2QfqvAGI8n8ckIiy9FzS9XF94.jpg', '/xo6Sedrdj4DVnh4ZEzDM4D0QQYU.jpg', '4v92gXetGqA'),
    (348350, 'Through a series of daring escapades deep within a dark and dangerous criminal underworld, Han Solo meets his mighty future copilot Chewbacca and encounters the notorious gambler Lando Calrissian.', 135, '/4oD6VEccFkorEBTEDXtpLAaz0Rl.jpg', '/7LZ0K4FsALrt7OeNIGOVLNuKQRU.jpg', 'jPEYpryMp2s'),
    (351286, 'Three years after Jurassic World was destroyed, Isla Nublar now sits abandoned. When the island''s dormant volcano begins roaring to life, Owen and Claire mount a campaign to rescue the remaining dinosaurs from this extinction-level event.', 129, '/x2Us3jR6ToMJjbcPbLimYoxf6xr.jpg', '/gBmrsugfWpiXRh13Vo3j0WW55qD.jpg', '1FJD7jZqZEk'),
    (351460, 'Light Turner finds a supernatural notebook and uses it to mete out death, attracting the attention of a detective, a demon and a girl in his class.', 101, '/8xRQ0KG9ZZzjEiFa5fgEaTKhc0d.jpg', '/nDAbr3NSkkOMIkFrQ3ycVxzgaMc.jpg', 'gvxNaSIB_WI'),
    (353081, 'When an IMF mission ends badly, the world is faced with dire consequences. As Ethan Hunt takes it upon himself to fulfill his original briefing, the CIA begin to question his loyalty and his motives. The IMF team find themselves in a race against time, hunted by assassins while trying to prevent a global catastrophe.', 147, '/AkJQpZp9WoNdj7pLYSj1L0RcMMN.jpg', '/5jnoAA74Qwb5w6B9FMvnc20n6Ie.jpg', 'MEOOas3JZt0'),
    (353486, 'Four teenagers in detention discover an old video game console with a game they’ve never heard of. When they decide to play, they are immediately sucked into the jungle world of Jumanji in the bodies of their avatars. They’ll have to complete the adventure of their lives filled with fun, thrills and danger or be stuck in the game forever!', 119, '/pSgXKPU5h6U89ipF7HBYajvYt7j.jpg', '/zZKmEmRDc7ZjFucPm2UGNgDRlDc.jpg', '10VphsyJhbU'),
    (353491, 'A boy haunted by visions of a parallel world aids its disillusioned guardian in preventing the destruction of the nexus of universes known as the Dark Tower.', 95, '/i9GUSgddIqrroubiLsvvMRYyRy0.jpg', '/pVVobDO8cezhVPvwD6EBUN0g3mt.jpg', 'wZC5FoJ-cPU'),
    (354912, 'Despite his family’s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel''s family history.', 105, '/6Ryitt95xrO8KXuqRGm1fUuNwqF.jpg', '/g7CHF8gTLGooTbP4GznIGwaqAGL.jpg', 'Rvr68u6k5sI'),
    (357096, 'Jennifer Hills is still tormented by the brutal sexual assault she endured years ago. She’s changed identities and cities, reluctantly joining a support group where she begins to piece together a new life. But when her new friend’s murderer goes free and the tales of serial rapists haunt her, Jennifer will hunt down the men responsible and do what the system won’t – make them pay for their crimes in the most horrific ways imaginable. Only this time, no jury may be able to save her.', 91, '/qosIFCddpZjoMdsrkcQWB4UGm3o.jpg', '/ts2CQBbdPYRoq7yTovmDoRw7sTX.jpg', 'rKfwJtXXMkM'),
    (359410, 'Ex-UFC fighter Dalton takes a job as a bouncer at a Florida Keys roadhouse, only to discover that this paradise is not all it seems.', 121, '/fDEdtS4P0gJsxHDIt8dG8TR5dx1.jpg', '/clFFCapyGpE7KD4Jsu5pUbFBZF4.jpg', 'Y0ZsLudtfjI'),
    (359724, 'American car designer Carroll Shelby and the British-born driver Ken Miles work together to battle corporate interference, the laws of physics, and their own personal demons to build a revolutionary race car for Ford Motor Company and take on the dominating race cars of Enzo Ferrari at the 24 Hours of Le Mans in France in 1966.', 153, '/dR1Ju50iudrOh3YgfwkAU1g2HZe.jpg', '/2vq5GTJOahE03mNYZGxIynlHcWr.jpg', 'I3h9Z89U9ZA'),
    (359940, 'After seven months have passed without a culprit in her daughter''s murder case, Mildred Hayes makes a bold move, painting three signs leading into her town with a controversial message directed at Bill Willoughby, the town''s revered chief of police. When his second-in-command Officer Jason Dixon, an immature mother''s boy with a penchant for violence, gets involved, the battle between Mildred and Ebbing''s law enforcement is only exacerbated.', 115, '/bRYLt8fV82tdVoDppSFTZIcJiLN.jpg', '/oQHF0Y4gCw6VdPmapjsbZoxY2ht.jpg', 'nefD7UOhLCo'),
    (360920, 'The Grinch hatches a scheme to ruin Christmas when the residents of Whoville plan their annual holiday celebration. But a certain little who might change things.', 85, '/Al7DMUp8bqUN4JwXVNxfJYyv5cH.jpg', '/5lWIYxYEqWi8j3ZloxXntw3ImBo.jpg', '_UOh0UX3alI'),
    (361292, 'A darkness swirls at the center of a world-renowned dance company, one that will engulf the artistic director, an ambitious young dancer, and a grieving psychotherapist. Some will succumb to the nightmare. Others will finally wake up.', 152, '/bRpKFPb8CWKRQxVo9NzOuPPlO3Q.jpg', '/k4renoGJzagylgBYWbpjQLYGAfB.jpg', 'gh728YmlSFE'),
    (361743, 'After more than thirty years of service as one of the Navy’s top aviators, and dodging the advancement in rank that would ground him, Pete “Maverick” Mitchell finds himself training a detachment of TOP GUN graduates for a specialized mission the likes of which no living pilot has ever seen.', 131, '/n0YuM4f5lvGAP6MAW2kBIzugXnc.jpg', '/AaV1YIdWKnjAIAOe8UUKBFm327v.jpg', 'Klc__shdj88'),
    (363088, 'Just when his time under house arrest is about to end, Scott Lang once again puts his freedom at risk to help Hope van Dyne and Dr. Hank Pym dive into the quantum realm and try to accomplish, against time and any chance of success, a very dangerous rescue mission.', 119, '/cFQEO687n1K6umXbInzocxcnAQz.jpg', '/iYdgEUE2W2aJkgqfSjf1x3gFfuV.jpg', 'UUkn-enk2RU'),
    (363676, 'On 15 January 2009, the world witnessed the ''Miracle on the Hudson'' when Captain ''Sully'' Sullenberger glided his disabled plane onto the Hudson River, saving the lives of all 155 souls aboard. However, even as Sully was being heralded by the public and the media for his unprecedented feat of aviation skill, an investigation was unfolding that threatened to destroy his reputation and career.', 96, '/4vs83YcJ8TsabADDtaeCJ6ZTjYY.jpg', '/8TqBYPUscAWzSVtOZv8dAp6UKXI.jpg', '6Tbkbx4Hz8Q'),
    (364689, 'Ferdinand, a little bull, prefers sitting quietly under a cork tree just smelling the flowers versus jumping around, snorting, and butting heads with other bulls. As Ferdinand grows big and strong, his temperament remains mellow. But one day five men come to choose the "biggest, fastest, roughest bull" for the bullfights in Madrid— and Ferdinand is mistakenly chosen.', 108, '/rMm94JsRfcOPiPVsTRcBiiVBOhz.jpg', '/sTOhZruocNubL0HxjvdouwCEL9I.jpg', '0Iiq-9fhwa0'),
    (369885, 'In 1942, an intelligence officer in North Africa encounters a female French Resistance fighter on a deadly mission behind enemy lines. When they reunite in London, their relationship is tested by the pressures of war.', 124, '/sV4lXM32quwminL3TP36nlNPp7Q.jpg', '/cdR0qwyaMfuZRfTYEixUmRnmdop.jpg', '-hQGiozwHiI'),
    (369972, 'A look at the life of the astronaut, Neil Armstrong, and the legendary space mission that led him to become the first man to walk on the Moon on July 20, 1969.', 141, '/i91mfvFcPPlaegcbOyjGgiWfZzh.jpg', '/jrudoaXcoLyHRPdolyOGemXgPEs.jpg', 'TVowQ4LgwLk'),
    (370172, 'Bond has left active service and is enjoying a tranquil life in Jamaica. His peace is short-lived when his old friend Felix Leiter from the CIA turns up asking for help. The mission to rescue a kidnapped scientist turns out to be far more treacherous than expected, leading Bond onto the trail of a mysterious villain armed with dangerous new technology.', 163, '/iUgygt3fscRoKWCV1d0C7FbM9TP.jpg', '/x9td0NQha0t44K2qgcMipLOGjVi.jpg', 'N_gD9-Oa0fg'),
    (371638, 'An aspiring actor in Hollywood meets an enigmatic stranger by the name of Tommy Wiseau, the meeting leads the actor down a path nobody could have predicted; creating the worst movie ever made.', 104, '/2HuLGiyH0TPYxnCvYHAxc8K738o.jpg', '/1hdorswm5HPxb81xq84H9gqveUq.jpg', 'sPSJYXi7BWA'),
    (371645, 'Ricky is a defiant young city kid who finds himself on the run with his cantankerous foster uncle in the wild New Zealand bush. A national manhunt ensues, and the two are forced to put aside their differences and work together to survive.', 101, '/hkmz9rxgcweizXNElozGeKwmAJE.jpg', '/ixpUtvrZNwk6LBObXaNH8fh4FYf.jpg', 'w1LC-RrA7NI'),
    (372058, 'High schoolers Mitsuha and Taki are complete strangers living separate lives. But one night, they suddenly switch places. Mitsuha wakes up in Taki’s body, and he in hers. This bizarre occurrence continues to happen randomly, and the two must adjust their lives around each other.', 106, '/vfJFJPepRKapMd5G2ro7klIRysq.jpg', '/mMtUybQ6hL24FXo0F3Z4j2KG7kZ.jpg', 'TYku4P7MHdo'),
    (373571, 'Follows the heroic efforts of the crypto-zoological agency Monarch as its members face off against a battery of god-sized monsters, including the mighty Godzilla, who collides with Mothra, Rodan, and his ultimate nemesis, the three-headed King Ghidorah. When these ancient super-species, thought to be mere myths, rise again, they all vie for supremacy, leaving humanity''s very existence hanging in the balance.', 132, '/mzOHg7Q5q9yUmY0b9Esu8Qe6Nnm.jpg', '/mzRJpkWPjXdXak0WCc8ZxVH4hug.jpg', 'QFxN2oDKk0E'),
    (374720, 'The story of the miraculous evacuation of Allied soldiers from Belgium, Britain, Canada and France, who were cut off and surrounded by the German army from the beaches and harbour of Dunkirk between May 26th and June 4th 1940 during World War II.', 107, '/b4Oe15CGLL61Ped0RAS9JpqdmCt.jpg', '/pTwF9hLkqAtuOqXMdOyPwz4AgnI.jpg', 'T7O7BtBnsG4'),
    (375262, 'England, early 18th century. The close relationship between Queen Anne and Sarah Churchill is threatened by the arrival of Sarah''s cousin, Abigail Hill, resulting in a bitter rivalry between the two cousins to be the Queen''s favourite.', 120, '/cwBq0onfmeilU5xgqNNjJAMPfpw.jpg', '/iSskYDN193CJfTbSpFfscSwZ9Sx.jpg', 'SYb-wkehT1g'),
    (376659, 'When three overworked and under-appreciated moms are pushed beyond their limits, they ditch their conventional responsibilities for a jolt of long overdue freedom, fun, and comedic self-indulgence.', 100, '/u9q10ljhkLj0tNCjlVqe3DCjoU4.jpg', '/zci26eN6YKEg9gPLUp3wB5eqcEx.jpg', 'MVzDKTh49zs'),
    (376660, 'Two high school girls are best friends until one dates the other''s older brother, who is totally his sister''s nemesis.', 105, '/15FykQKiM0aYpC1MuybR43xl8eF.jpg', '/9g8UsxDTkzlVyjBJBRJT3zDceTC.jpg', 'oPO5J8Ap578'),
    (376866, 'An account of the days of First Lady, Jacqueline Kennedy, in the immediate aftermath of John F. Kennedy''s assassination in 1963.', 100, '/nF9N33PfhizMEzbfxHoxXBo2vx9.jpg', '/lF41LYBSLVpZ61rZci471pqi6UW.jpg', 'g9pW3B8Ycc4'),
    (376867, 'The tender, heartbreaking story of a young man’s struggle to find himself, told across three defining chapters in his life as he experiences the ecstasy, pain, and beauty of falling in love, while grappling with his own sexuality.', 112, '/qLnfEmPrDjJfPyyddLJPkXmshkp.jpg', '/jm1oD3eB08LImSwL1LrzF9AJQ5b.jpg', '9NJj12tJzqc'),
    (378064, 'Shouya Ishida starts bullying the new girl in class, Shouko Nishimiya, because she is deaf. But as the teasing continues, the rest of the class starts to turn on Shouya for his lack of compassion. When they leave elementary school, Shouko and Shouya do not speak to each other again... until an older, wiser Shouya, tormented by his past behaviour, decides he must see Shouko once more. He wants to atone for his sins, but is it already too late...?', 129, '/tuFaWiqX0TXoWu7DGNcmX3UW7sT.jpg', '/5lAMQMWpXMsirvtLLvW7cJgEPkU.jpg', 'TQK9By9qQiw'),
    (378236, 'Gene, a multi-expressional emoji, sets out on a journey to become a normal emoji.', 86, '/60bTx5z9zL1AqCjZ0gmWoRMJ6Bb.jpg', '/kTrgxhRSj2sun89bDbnGCPBiey6.jpg', 'Rd85FEdJfTw'),
    (379686, 'When LeBron and his young son Dom are trapped in a digital space by a rogue A.I., LeBron must get them home safe by leading Bugs, Lola Bunny and the whole gang of notoriously undisciplined Looney Tunes to victory over the A.I.''s digitized champions on the court. It''s Tunes versus Goons in the highest-stakes challenge of his life.', 115, '/5bFK5d3mVTAvBCXi5NPWH0tYjKl.jpg', '/8s4h9friP6Ci3adRGahHARVd76E.jpg', 'RCsEKvz2mxs'),
    (381284, 'The untold story of Katherine G. Johnson, Dorothy Vaughan and Mary Jackson – brilliant African-American women working at NASA and serving as the brains behind one of the greatest operations in history – the launch of astronaut John Glenn into orbit. The visionary trio crossed all gender and race lines to inspire generations to dream big.', 127, '/9lfz2W2uGjyow3am00rsPJ8iOyq.jpg', '/rfkIeCaIHhN3K5wjJJqKmfUjYp8.jpg', '5wfrDhgUMGI'),
    (381288, 'Though Kevin has evidenced 23 personalities to his trusted psychiatrist, Dr. Fletcher, there remains one still submerged who is set to materialize and dominate all the others. Compelled to abduct three teenage girls led by the willful, observant Casey, Kevin reaches a war for survival among all of those contained within him — as well as everyone around him — as the walls between his compartments shatter apart.', 117, '/ow2BSQGKJtZpH2zZY1rmX8eXKAi.jpg', '/9pkZesKMnblFfKxEhQx45YQ2kIe.jpg', '6bfooooTKyM'),
    (381289, 'A dog goes on quest to discover his purpose in life over the course of several lifetimes with multiple owners.', 100, '/3jcNvhtVQe5Neoffdic39fRactM.jpg', '/sLjeApi5odpyEoCzAnbr5DycL3z.jpg', '1jLOOCADTGs'),
    (381341, 'During a dinner, a group of friends decide to share whatever message or phone call they will receive during the evening, with unforeseen consequences.', 97, '/3wknM629Vryofb1HNo2YnLQnQyn.jpg', '/1YhiocGm8aOwILGX7mwlkdbr0ph.jpg', '-lOUnBsjGuY'),
    (383498, 'Wisecracking mercenary Deadpool battles the evil and powerful Cable and other bad guys to save a boy''s life.', 120, '/gyfPKfFYcVW54MoqhYlwwDDIfJR.jpg', '/3P52oz9HPQWxcwHOwxtyrVV1LKi.jpg', '20bpjtCbCz0'),
    (384018, 'Ever since US Diplomatic Security Service Agent Hobbs and lawless outcast Shaw first faced off, they just have traded smack talk and body blows. But when cyber-genetically enhanced anarchist Brixton''s ruthless actions threaten the future of humanity, they join forces to defeat him.', 137, '/qRyy2UmjC5ur9bDi3kpNNRCc5nc.jpg', '/hpgda6P9GutvdkDX5MUJ92QG9aj.jpg', 'b736ZM_KfEk'),
    (384521, 'Orbiting above a planet on the brink of war, scientists test a device to solve an energy crisis and end up face-to-face with a dark alternate reality.', 102, '/vJi2ExTcWdJR3150VPKqqtdGxsT.jpg', '/2cnUCcNmmj79hGmimvWlUo5P2K8.jpg', 'jrxBaaINseI'),
    (384677, 'Two overworked and underpaid assistants come up with a plan to get their bosses off their backs by setting them up with each other.', 105, '/7omfwqiiMld9EnUps3Uk9YZLy6g.jpg', '/kOCJvnRYKg6CkvoFYbzz0itrUzR.jpg', 'X-eRc9PF3TU'),
    (385128, 'Dominic Toretto and his crew battle the most skilled assassin and high-performance driver they''ve ever encountered: his forsaken brother.', 143, '/deEmLILTPejEb6OGsXRJ5MCvyDW.jpg', '/xXHZeb1yhJvnSHPzZDqee0zfMb6.jpg', 'TfJkFsCn8Zw'),
    (385687, 'Over many missions and against impossible odds, Dom Toretto and his family have outsmarted, out-nerved and outdriven every foe in their path. Now, they confront the most lethal opponent they''ve ever faced: A terrifying threat emerging from the shadows of the past who''s fueled by blood revenge, and who is determined to shatter this family and destroy everything—and everyone—that Dom loves, forever.', 142, '/fiVW06jE7z9YnO4trhaMEdclSiC.jpg', '/4XM8DUTQb3lhLemJC51Jx4a2EuA.jpg', 'eoOaKN4qCKw'),
    (387426, 'A young girl named Mija risks everything to prevent a powerful, multi-national company from kidnapping her best friend - a massive animal named Okja.', 120, '/pHlRr2MfjK77VIIAO7p0R4jhsJI.jpg', '/x8PmjDi2mkAKznApIz78C9v3tvt.jpg', '8MWwXfzTcow'),
    (392044, 'Genius Belgian detective Hercule Poirot investigates the murder of an American tycoon aboard the Orient Express train.', 114, '/7GtdJU6iAg6fjQu3E3zta3bIAQh.jpg', '/IQyEvPTYvrzsa7qstRj6VLQupr.jpg', 'z68frP9Q7XA'),
    (393345, 'Confined to an asylum for the criminally insane for the past four years, Nica is wrongly convinced that she, not Chucky, murdered her entire family... until a string of grisly deaths occur after her psychiatrist introduces a new group therapy tool -- a "Good Guy" doll.', 91, '/r5JUiMYfatwYeDkxkLWYUx5GIjY.jpg', '/af7uKmGnrOn4P1zyfFXPQZOCCEp.jpg', 'ksTv0_dGiX4'),
    (393457, 'In 1950s Pittsburgh, a frustrated African-American father struggles with the constraints of poverty, racism, and his own inner demons as he tries to raise a family.', 139, '/8NvnB8aeWQvBEz2ruN4g313j991.jpg', '/j2kgVOyp4dxlqohU5QJTrDHfbRD.jpg', 'spCxVd9ctFs'),
    (395834, 'An FBI agent teams with the town''s veteran game tracker to investigate a murder that occurred on a Native American reservation.', 107, '/pySivdR845Hom4u4T2WNkJxe6Ad.jpg', '/kQGxGXzYiCumY8kmXXpgbZyZQK8.jpg', 'E0qRHABxvfc'),
    (395990, 'A mild-mannered father is transformed into a killing machine after his family is torn apart by a violent act.', 107, '/g0eEEZAqMf98ULQnoiORuazjOpn.jpg', '/uQqQvmptJLPTcWDrZXn22p7j7s3.jpg', 'HzILu6yyA20'),
    (395992, 'The six-member crew of the International Space Station is tasked with studying a sample from Mars that may be the first proof of extra-terrestrial life, which proves more intelligent than ever expected.', 104, '/wztfli5NgYDgurVgShNflvnyA3Z.jpg', '/nNh7vHHISVAaziJEqAq0P9iL52w.jpg', 'cuA-xqBw4jE'),
    (396371, 'Molly Bloom, a young skier and former Olympic hopeful becomes a successful entrepreneur (and a target of an FBI investigation) when she establishes a high-stakes, international poker game.', 141, '/zrGQwKNmAz5awZI2V1k5M4eTTTN.jpg', '/rHcBZ6ZKCe4FalWHyvBGsyMsh0k.jpg', '9v-pw0ZQRLY'),
    (396422, 'Several years after the tragic death of their little girl, a doll maker and his wife welcome a nun and several girls from a shuttered orphanage into their home, soon becoming the target of the doll maker''s possessed creation—Annabelle.', 110, '/tb86j8jVCVsdZnzf8I6cIi65IeM.jpg', '/sxNGD6Wxp7qNUjKN5jLeZk4ORAy.jpg', 'EjZkJa6Z-SY'),
    (396535, 'When a zombie virus pushes Korea into a state of emergency, those trapped on an express train to Busan must fight for their own survival.', 118, '/vNVFt6dtcqnI7hqa6LFBUibuFiw.jpg', '/brnfCYyz8EMbBrHgmh8sCwBi5i1.jpg', '4qm59Rcq1Fw'),
    (397243, 'Father and son coroners receive a mysterious unidentified corpse with no apparent cause of death. As they attempt to examine the "Jane Doe," they discover increasingly bizarre clues that hold the key to her terrifying secrets.', 86, '/6K0wjP8kPCiPYy9PtXBGuypyt5I.jpg', '/2pOd80PQSJ9cUbli7PDeX59q3vQ.jpg', 'BNxsaFCzqxc'),
    (398175, 'After working as a drug courier and getting into a brutal shootout with police, a former boxer finds himself at the mercy of his enemies as they force him to instigate violent acts that turn the prison he resides in into a battleground.', 132, '/39daqfOgnLjz9alwcNkZAGEbUry.jpg', '/ct2r3CqnA0KtMfib4AvfBU1W9M2.jpg', '4XnCP5ggpbI'),
    (398181, 'A traumatized veteran, unafraid of violence, tracks down missing girls for a living. When a job spins out of control, Joe''s nightmares overtake him as a conspiracy is uncovered—leading to what may be his death trip or his awakening.', 89, '/nx4lUyQNEzJowcF55VAP0TQEaX0.jpg', '/g2yZ1kiGwLO5AUSmtsEJeFEWghJ.jpg', 'fQyDaGWQ43w'),
    (398818, 'In the summer of 1983, a 17-year-old Elio spends his days in his family''s villa in Italy. One day Oliver, a graduate student, arrives to assist Elio''s father, a professor of Greco-Roman culture. Soon, Elio and Oliver discover a summer that will alter their lives forever.', 132, '/gXiE0WveDnT0n5J4sW9TMxXF4oT.jpg', '/4Xh2a1WeTp6b8Ksvug0pAMbX3dT.jpg', 'Z9AYPxH5NTM'),
    (399035, 'A businessman, on his daily commute home, gets unwittingly caught up in a criminal conspiracy that threatens not only his life but the lives of those around him.', 104, '/rDeGK6FIUfVcXmuBdEORPAGPMNg.jpg', '/srnI5CdeydB9E8WNOqblj0jRfSn.jpg', 'g1RMoMrr3SM'),
    (399055, 'An other-worldly story, set against the backdrop of Cold War era America circa 1962, where a mute janitor working at a lab falls in love with an amphibious man being held captive there and devises a plan to help him escape.', 123, '/9zfwPffUXpBrEP26yp0q1ckXDcj.jpg', '/abirSHwWgKajV3hXhaIR5lcCIXe.jpg', 'oRKnlUanptY'),
    (399170, 'Trying to reverse a family curse, brothers Jimmy and Clyde Logan set out to execute an elaborate robbery during the legendary Coca-Cola 600 race at the Charlotte Motor Speedway.', 119, '/mQrhrBaaHvRfBQq0Px3HtVbH9iE.jpg', '/eszmHIWJHAKdnJcE3KcvVzOb6Jd.jpg', 'ti46sNeNkBU'),
    (399174, 'In the future, an outbreak of canine flu leads the mayor of a Japanese city to banish all dogs to an island used as a garbage dump. The outcasts must soon embark on an epic journey when a 12-year-old boy arrives on the island to find his beloved pet.', 101, '/4C7ZHv5LUPq7XzxC3nq8mBr77sP.jpg', '/goMGTcitprGu7YD6VZS4lUUwzRA.jpg', 'dt__kig8PVU'),
    (399360, 'In the prehistoric past, Keda, a young and inexperienced hunter, struggles to return home after being separated from his tribe when bison hunting goes awry. On his way back he will find an unexpected ally.', 97, '/afdZAIcAQscziqVtsEoh2PwsYTW.jpg', '/Gn7CHQKw5rgQrnVQhvGnlOaD8F.jpg', 'uIxnTi4GmCo'),
    (399404, 'In May 1940, the fate of World War II hangs on Winston Churchill, who must decide whether to negotiate with Adolf Hitler or fight on knowing that it could mean the end of the British Empire.', 125, '/xa6G3aKlysQeVg9wOb0dRcIGlWu.jpg', '/6prkTmEEsB3f9hhKBzUePLe27b2.jpg', 'JQAYFbcgf60'),
    (399566, 'In a time when monsters walk the Earth, humanity’s fight for its future sets Godzilla and Kong on a collision course that will see the two most powerful forces of nature on the planet collide in a spectacular battle for the ages.', 114, '/pgqgaUx1cJb5oZQQ5v0tNARCeBp.jpg', '/wWqTMWkEw6HouLd1zPZbZWxtAPr.jpg', 'odM92ap8_c0'),
    (399579, 'When Alita awakens with no memory of who she is in a future world she does not recognize, she is taken in by Ido, a compassionate doctor who realizes that somewhere in this abandoned cyborg shell is the heart and soul of a young woman with an extraordinary past.', 122, '/xRWht48C2V8XNfzvPehyClOvDni.jpg', '/jXDselREPq8TOVGM4dzBBUM7xVk.jpg', 'puKWa8hrvA8'),
    (400155, 'Dracula, Mavis, Johnny and the rest of the Drac Pack take a vacation on a luxury Monster Cruise Ship, where Dracula falls in love with the ship’s captain, Ericka, who’s secretly a descendant of Abraham Van Helsing, the notorious monster slayer.', 97, '/lzE5BwGQea1nek7TPXUuC5AZ6rq.jpg', '/gvUYIHWzq7r3KuzAaKvly2h0SjM.jpg', 'Ku52zNnft8k'),
    (400535, 'Agent Matt Graver teams up with operative Alejandro Gillick to prevent Mexican drug cartels from smuggling terrorists across the United States border.', 122, '/OdD7A0LgLXPjqzmfcEl9sTYVPo.jpg', '/tnwMCH4yLBY4qpe6Nr4n66u4U3f.jpg', 'sIMChzE_aCo'),
    (400617, 'In 1950s London, a renowned dressmaker''s meticulous lifestyle begins drastically changing as his relationship with his young muse intensifies.', 130, '/hgoWjp9Sh0MI97eAMZCnIoVfgvq.jpg', '/sJZd1H4cl2Nxhj0nutVCK5pMczL.jpg', 'xNsiQMeSvMk'),
    (400650, 'Mary Poppins returns to the Banks family and helps them evade grave dangers by taking them on magical, musical adventures.', 131, '/uTVGku4LibMGyKgQvjBtv3OYfAX.jpg', '/oGzToOBTRdXVOrHj8r0VgK3d2sU.jpg', '-3jsfXDZLIY'),
    (400928, 'Frank, a single man raising his child prodigy niece Mary, is drawn into a custody battle with his mother.', 101, '/7YB2YrMwIm1g8FyZtlvmVDfRnAT.jpg', '/aH63TQfTFgAT8tYZs0CjDsqfMo2.jpg', 'x7CAjpdRaXU'),
    (401981, 'Prima ballerina Dominika Egorova faces a bleak and uncertain future after she suffers an injury that ends her career. She soon turns to Sparrow School, a secret intelligence service that trains exceptional young people to use their minds and bodies as weapons. Dominika emerges as the most dangerous Sparrow after completing the sadistic training process. As she comes to terms with her new abilities, she meets a CIA agent who tries to convince her that he is the only person she can trust.', 140, '/cdefNr6aS00IwVbSlxdFJnfmzKh.jpg', '/sGzuQYSTwJvLBc2PnuSVLHhuFeh.jpg', 'PmUL6wMpMWw'),
    (402431, 'In the land of Oz, ostracized and misunderstood green-skinned Elphaba is forced to share a room with the popular aristocrat Glinda at Shiz University, and the two''s unlikely friendship is tested as they begin to fulfill their respective destinies as Glinda the Good and the Wicked Witch of the West.', 162, '/xDGbZ0JJ3mYaGKy4Nzd9Kph6M9L.jpg', '/w22GVYotTIVC1dUd58mRhwPqiS.jpg', 'pqi45Qhq3CI'),
    (402900, 'Debbie Ocean, a criminal mastermind, gathers a crew of female thieves to pull off the heist of the century at New York''s annual Met Gala.', 111, '/MvYpKlpFukTivnlBhizGbkAe3v.jpg', '/scQf03Fm3jeyv4FH04qvi4fp4wh.jpg', 'n5LoVcVsiSQ'),
    (404368, 'Video game bad guy Ralph and fellow misfit Vanellope von Schweetz must risk it all by traveling to the World Wide Web in search of a replacement part to save Vanellope''s video game, Sugar Rush. In way over their heads, Ralph and Vanellope rely on the citizens of the internet — the netizens — to help navigate their way, including an entrepreneur named Yesss, who is the head algorithm and the heart and soul of trend-making site BuzzzTube.', 112, '/iVCrhBcpDaHGvv7CLYbK6PuXZo1.jpg', '/qDQEQbgP3v7B9IYLAUcYexNrVYP.jpg', 'T73h5bmD8Dc'),
    (406759, 'A mysterious force knocks the moon from its orbit around Earth and sends it hurtling on a collision course with life as we know it.', 131, '/odVv1sqVs0KxBXiA8bhIBlPgalx.jpg', '/8QpzqK3nPGxpqpKqhe6QasTGBWQ.jpg', 'ivIwdQBlS10'),
    (406990, 'In a world where families are limited to one child due to overpopulation, a set of identical septuplets must avoid being put to a long sleep by the government and dangerous infighting while investigating the disappearance of one of their own.', 123, '/atOgZMJpMrTdpqvPiHVPfBhR61l.jpg', '/j7ij93mtHXAF8D3PjRSEaKPHpIE.jpg', 'idZPTuwcMJA'),
    (406997, 'The story of August Pullman – a boy with facial differences – who enters fifth grade, attending a mainstream elementary school for the first time.', 113, '/sONh3LYGFcVDTy8pm1tbSOB13Li.jpg', '/b7xQ5fuyVO4c24igizCfPgF6n7q.jpg', 'ASAGdtAJPnU'),
    (411088, 'Barcelona, Spain. Adrián Doria, a young and successful businessman accused of murder, meets one night with Virginia Goodman, an expert interrogation lawyer, in order to devise a defense strategy.', 107, '/fptnZJbLzKUHeNlYrAynbyoL5YJ.jpg', '/157QuwzU58D5RtXmkBl5iNaxigN.jpg', 'epCg2RbyF80'),
    (412117, 'Max the terrier must cope with some major life changes when his owner gets married and has a baby. When the family takes a trip to the countryside, nervous Max has numerous run-ins with canine-intolerant cows, hostile foxes and a scary turkey. Luckily for Max, he soon catches a break when he meets Rooster, a gruff farm dog who tries to cure the lovable pooch of his neuroses.', 86, '/s9xg4V5EDKiphgIksVJ9gewBM11.jpg', '/zDIievPXqjfjLogXFqnnopU0OkK.jpg', 'mYocfuqu2A8'),
    (414906, 'In his second year of fighting crime, Batman uncovers corruption in Gotham City that connects to his own family while facing a serial killer known as the Riddler.', 177, '/74xTEgt7R36Fpooo50r9T25onhq.jpg', '/rvtdN5XkWAfGX6xDuPL6yYS2seK.jpg', 'vc7_mH2PWHs'),
    (417678, 'A teenager who''s lived a sheltered life because she''s allergic to everything, falls for the boy who moves in next door.', 96, '/gukkmf3W5Cev7winxBa8FHvKLql.jpg', '/hTLydq9rAuO0Eus1WWqab1tpyGg.jpg', 'mAC-nh9PU5s'),
    (417859, 'Long before he even met Shrek, the notorious fighter, lover and outlaw Puss in Boots becomes a hero when he sets off on an adventure with the tough and street smart Kitty Softpaws and the mastermind Humpty Dumpty to save his town. This is the true story of The Cat, The Myth, The Legend... The Boots.', 90, '/7a5Jzjr9TmffGy76y1SZhn3sCiz.jpg', '/c5MCkebYhFuhmi32x760HfcvLIO.jpg', 'Znuq-daWfLE'),
    (419430, 'Chris and his girlfriend Rose go upstate to visit her parents for the weekend. At first, Chris reads the family''s overly accommodating behavior as nervous attempts to deal with their daughter''s interracial relationship, but as the weekend progresses, a series of increasingly disturbing discoveries lead him to a truth that he never could have imagined.', 104, '/tFXcEccSQMf3lfhfXKSU9iRBpa3.jpg', '/bBQHALHRAaaORlPNXv7fNcRXYdx.jpg', 'gsB70ZRY-hI'),
    (419478, 'Katie, a 17-year-old, has been sheltered since childhood and confined to her house during the day by a rare disease that makes even the smallest amount of sunlight deadly. Fate intervenes when she meets Charlie and they embark on a summer romance.', 92, '/vPG2zEKPXhovPW9S91SRnwr5JM1.jpg', '/9T8sj5io4SGCBTHsk5H8LGcfKVe.jpg', 'U8N1fKXunCg'),
    (419479, 'When Cole stays up past his bedtime, he discovers that his hot babysitter is part of a Satanic cult that will stop at nothing to keep him quiet.', 85, '/uAzKNxGnbK5SL7VF7UeQyZdQLHV.jpg', '/z9NxO5sgLPYOQDT3h3w6qx3FAGq.jpg', '27d5R9BVInU'),
    (419680, 'Father and stepfather Dusty and Brad join forces to make Christmastime perfect for the children. Their newfound partnership soon gets put to the test when Dusty''s old-school, macho dad and Brad''s gentle father arrive to turn the holiday upside down. After a sudden change in plans, the four men decide to take the kids to a luxury resort for a fun-filled getaway that turns into a hilarious and chaotic adventure.', 100, '/rF2IoKL0IFmumEXQFUuB8LajTYP.jpg', '/wGQZepzZbZpzZW7a4aTZyAu8huy.jpg', 'hTKMUn87SxA'),
    (419704, 'The near future, a time when both hope and hardships drive humanity to look to the stars and beyond. While a mysterious phenomenon menaces to destroy life on planet Earth, astronaut Roy McBride undertakes a mission across the immensity of space and its many perils to uncover the truth about a lost expedition that decades before boldly faced emptiness and silence in search of the unknown.', 123, '/xBHvZcjRiWyobQ9kxBhO6B2dtRI.jpg', '/duengnNbJdTdjR329SmAAJO4stC.jpg', 'BsCNKuB93BA'),
    (420634, 'A mute maniac named Art the Clown terrorizes two friends on Halloween and everyone else who gets in his way.', 84, '/fjXqhGmaeQpB73WerhrYU6HlyV5.jpg', '/naNXYdBzTEb1KwOdi1RbBkM9Zv1.jpg', 'fN5j1MtGO2Q'),
    (420809, 'Maleficent and her goddaughter Aurora begin to question the complex family ties that bind them as they are pulled in different directions by impending nuptials, unexpected allies, and dark new forces at play.', 119, '/vloNTScJ3w7jwNwtNGoG8DbTThv.jpg', '/skvI4rYFrKXS73BJxWGH54Omlvv.jpg', 'AZJUQ9Sp_0U'),
    (420814, 'Christopher Robin, the boy who had countless adventures in the Hundred Acre Wood, has grown up and lost his way. Now it’s up to his spirited and loveable stuffed animals, Winnie The Pooh, Tigger, Piglet, and the rest of the gang, to rekindle their friendship and remind him of endless days of childlike wonder and make-believe, when doing nothing was the very best something.', 104, '/i6Ytex4d3CdfIKJFxB5v5vh24vb.jpg', '/hnh4oqnGPlVFEMUuw41nYxKRYf0.jpg', 'kHnqoHj1ipk'),
    (420817, 'A kindhearted street urchin named Aladdin embarks on a magical adventure after finding a lamp that releases a wisecracking genie while a power-hungry Grand Vizier vies for the same lamp that has the power to make their deepest wishes come true.', 127, '/ykUEbfpkf8d0w49pHh0AD2KrT52.jpg', '/rVqY0Bo4Npf6EIONUROxjYAJfmD.jpg', 'h44kpghglWw'),
    (420818, 'Simba idolizes his father, King Mufasa, and takes to heart his own royal destiny. But not everyone in the kingdom celebrates the new cub''s arrival. Scar, Mufasa''s brother—and former heir to the throne—has plans of his own. The battle for Pride Rock is ravaged with betrayal, tragedy and drama, ultimately resulting in Simba''s exile. With help from a curious pair of newfound friends, Simba will have to figure out how to grow up and take back what is rightfully his.', 118, '/dzBtMocZuJbjLOXvrl4zGYigDzh.jpg', '/1TUg5pO1VZ4B0Q1amk3OlXvlpXV.jpg', '7TavVZMewpY'),
    (423204, 'After a treacherous attack, Secret Service agent Mike Banning is charged with attempting to assassinate President Trumbull. Chased by his own colleagues and the FBI, Banning begins a race against the clock to clear his name.', 122, '/fapXd3v9qTcNBTm39ZC4KUVQDNf.jpg', '/sGqqnvOqJg2HDHrjtCPIlCwF4Mu.jpg', 'l4AQchYSxwc'),
    (424139, 'Laurie Strode comes to her final confrontation with Michael Myers, the masked figure who has haunted her since she narrowly escaped his killing spree on Halloween night four decades ago.', 106, '/f7JAX5EGk4GgsEnus6OxyzwpFp7.jpg', '/8VjIXC2x8SHwAO52rfFpejKL4wc.jpg', 'x_-x4Dwz-rU'),
    (424694, 'Singer Freddie Mercury, guitarist Brian May, drummer Roger Taylor and bass guitarist John Deacon take the music world by storm when they form the rock ''n'' roll band Queen in 1970. Hit songs become instant classics. When Mercury''s increasingly wild lifestyle starts to spiral out of control, Queen soon faces its greatest challenge yet – finding a way to keep the band together amid the success and excess.', 135, '/lHu1wtNaczFPGFDTrjCSzeLPTKN.jpg', '/dcvbs8z0GEXslC1kCT77x19XDeR.jpg', '27zlBpzdOZg'),
    (424783, 'On the run in the year 1987, Bumblebee finds refuge in a junkyard in a small Californian beach town. Charlie, on the cusp of turning 18 and trying to find her place in the world, discovers Bumblebee, battle-scarred and broken.  When Charlie revives him, she quickly learns this is no ordinary yellow VW bug.', 114, '/fw02ONlDhrYjTSZV8XO6hhU3ds3.jpg', '/hMANgfPHR1tRObNp2oPiOi9mMlz.jpg', 'lcwmDAYt22k'),
    (425909, 'When single mom Callie and her two kids Trevor and Phoebe arrive in a small Oklahoma town, they begin to discover their connection to the original Ghostbusters and the secret legacy their grandfather left behind.', 124, '/sg4xJaufDiQl7caFEskBtQXfD4x.jpg', '/EnDlndEvw6Ptpp8HIwmRcSSNKQ.jpg', 'G_ua10EMbSg'),
    (426063, 'A gothic tale of obsession between a haunted young woman and the terrifying vampire infatuated with her, causing untold horror in its wake.', 133, '/d0B8xDdqBZlzlPEzES8lu5LlNQn.jpg', '/2gAStVyyv9C3BSEKhP0a1aM3Qy9.jpg', 'nulvWqYUM8k'),
    (426426, 'In 1970s Mexico City, two domestic workers help a mother of four while her husband is away for an extended period of time.', 135, '/dtIIyQyALk57ko5bjac7hi01YQ.jpg', '/zl9uqCl5iUSb50sTk2BPzw6bJnU.jpg', '6BS27ngZtxg'),
    (426543, 'When Clara’s mother leaves her a mysterious gift, she embarks on a journey to four secret realms—where she discovers her greatest strength could change the world.', 99, '/9vPDY8e7YxLwgVum7YZIUJbr4qc.jpg', '/l2ji4YiNSPBV69WjGBgU0gCvRqy.jpg', 'FacrK2lLbYU'),
    (427641, 'Primatologist Davis Okoye shares an unshakable bond with George, the extraordinarily intelligent, silverback gorilla who has been in his care since birth.  But a rogue genetic experiment gone awry mutates this gentle ape into a raging creature of enormous size.  To make matters worse, it’s soon discovered there are other similarly altered animals.  As these newly created alpha predators tear across North America, destroying everything in their path, Okoye teams with a discredited genetic engineer to secure an antidote, fighting his way through an ever-changing battlefield, not only to halt a global catastrophe but to save the fearsome creature that was once his friend.', 107, '/MGADip4thVSErP34FAAfzFBTZ5.jpg', '/vm8mhrjk5nQ562UQ0KbUzi0yOHr.jpg', '-nEB0oCwgxI'),
    (428078, 'Many thousands of years in the future, Earth’s cities roam the globe on huge wheels, devouring each other in a struggle for ever diminishing resources. On one of these massive traction cities, the old London, Tom Natsworthy has an unexpected encounter with a mysterious young woman from the wastelands who will change the course of his life forever.', 128, '/gLhYg9NIvIPKVRTtvzCWnp1qJWG.jpg', '/rm2oMykm5nX6SzXFr7TGHkO6r8Z.jpg', 's-Q-wgosfKg'),
    (429197, 'George W. Bush picks Dick Cheney, the CEO of Halliburton Co., to be his Republican running mate in the 2000 presidential election. No stranger to politics, Cheney''s impressive résumé includes stints as White House chief of staff, House Minority Whip and Defense Secretary. When Bush wins by a narrow margin, Cheney begins to use his newfound power to help reshape the country and the world.', 132, '/1gCab6rNv1r6V64cwsU4oEr649Y.jpg', '/aHcNu3tYihvkL45CrXTFY4YfrfF.jpg', 'g09a9laLh0k'),
    (429351, 'A team of special forces head into Afghanistan in the aftermath of the September 11th attacks in an attempt to dismantle the Taliban.', 130, '/37Qwani2g0jVPU7N4OkkTZ7aERz.jpg', '/x5EUEv1N9g4BCX9GQXKvv3nqMVo.jpg', 'Zxag9p-63RU'),
    (429617, 'Peter Parker and his friends go on a summer trip to Europe. However, they will hardly be able to rest - Peter will have to agree to help Nick Fury uncover the mystery of creatures that cause natural disasters and destruction throughout the continent.', 129, '/4q2NNj4S5dG2RLF9CpXsej7yXl.jpg', '/vamhMTvh9m9zFHDoR0v1nRtf6T4.jpg', 'LFoz8ZJWmPs'),
    (431580, 'A group of misfits encounter a young Yeti named Everest, and they set off to reunite the magical creature with his family on the mountain of his namesake.', 97, '/20djTLqppfBx5WYA67Y300S6aPD.jpg', '/jXk3ZMq7n4ugOqKYq0CtMn3gia8.jpg', 'Ap0NRJD-2ts'),
    (431693, 'Super spy Lance Sterling and scientist Walter Beckett are almost exact opposites. Lance is smooth, suave and debonair. Walter is… not. But what Walter lacks in social skills he makes up for in smarts and invention, creating the awesome gadgets Lance uses on his epic missions. But when events take an unexpected turn, Walter and Lance suddenly have to rely on each other in a whole new way.', 102, '/z52xI0MnoX1rqySFJYnmBqHbXRn.jpg', '/uG1v9Hk1XKICd6IJChRR20mBh8i.jpg', 'K4xs7sNPTe8'),
    (436270, 'Nearly 5,000 years after he was bestowed with the almighty powers of the Egyptian gods—and imprisoned just as quickly—Black Adam is freed from his earthly tomb, ready to unleash his unique form of justice on the modern world.', 125, '/rCtreCr4xiYEWDQTebybolIh6Xe.jpg', '/bQXAqRx2Fgc46uCVWgoPz5L5Dtr.jpg', 'mkomfZHG5q4'),
    (436969, 'Supervillains Harley Quinn, Bloodsport, Peacemaker and a collection of nutty cons at Belle Reve prison join the super-secret, super-shady Task Force X as they are dropped off at the remote, enemy-infused island of Corto Maltese.', 132, '/q61qEyssk2ku3okWICKArlAdhBn.jpg', '/jlGmlFOcfo8n5tURmhC7YVd4Iyy.jpg', 'eg5ciqQzmK0'),
    (438148, 'A fanboy of a supervillain supergroup known as the Vicious 6, Gru hatches a plan to become evil enough to join them, with the backup of his followers, the Minions.', 87, '/4dBDk1LPdvdhcZdjQBmdXwiVKUA.jpg', '/wZS4xSfPtk1NPQnx9zsT5R2WhCu.jpg', 'HhIl_XJ-OGA'),
    (438631, 'Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet''s exclusive supply of the most precious resource in existence - a commodity capable of unlocking humanity''s greatest potential - only those who can conquer their fear will survive.', 155, '/v1tRXZ4JtD2Iv6fjkPvT4GiwslV.jpg', '/xS0g3s4blsiPmtpjjb7chFjI1ip.jpg', 'w0HgHet0sxg'),
    (438695, 'Buster and his new cast now have their sights set on debuting a new show at the Crystal Tower Theater in glamorous Redshore City. But with no connections, he and his singers must sneak into the Crystal Entertainment offices, run by the ruthless wolf mogul Jimmy Crystal, where the gang pitches the ridiculous idea of casting the lion rock legend Clay Calloway in their show. Buster must embark on a quest to find the now-isolated Clay and persuade him to return to the stage.', 110, '/aWeKITRFbbwY8txG5uCj4rMCfSP.jpg', '/ztiFxuG0gC6wQ8y7JZFYbCQyN4Y.jpg', 'EPZu5MA2uqI'),
    (440021, 'Caught in a bizarre and terrifying time warp, college student Tree finds herself repeatedly reliving the day of her murder, ultimately realizing that she must identify the killer and the reason for her death before her chances of survival run out.', 97, '/cTaEIUYTt52ooq9quVbAQ7NpGwo.jpg', '/9XSEL3EMC2D8k4UcYBn8etgRxPg.jpg', 'v3lXYAzf5TQ'),
    (443791, 'After an earthquake destroys their underwater station, six researchers must navigate two miles along the dangerous, unknown depths of the ocean floor to make it to safety in a race against time.', 95, '/gzlbb3yeVISpQ3REd3Ga1scWGTU.jpg', '/tya34K7D4jtDrVbvExyvTx97Aen.jpg', 'jCFWEzIVILc'),
    (446021, 'Lake Tahoe, 1969. Seven strangers, each one with a secret to bury, meet at El Royale, a decadent motel with a dark past. In the course of a fateful night, everyone will have one last shot at redemption.', 141, '/qExufIc4Rw0e4xdVZlhMdmEDGES.jpg', '/gb3TVVZNNxVGNfS1NxGaiWZfwnW.jpg', 'y7wzBVARwaU'),
    (446354, 'A cover-up that spanned four U.S. Presidents pushed the country''s first female newspaper publisher and a hard-driving editor to join an unprecedented battle between journalist and government. Inspired by true events.', 116, '/h4XG3g6uMMPIBPjAoQhC2QIMdkl.jpg', '/8sb4aBST28vN3rBz704XJczS0Ld.jpg', 'nrXlY6gzTTM'),
    (446893, 'Queen Poppy and Branch make a surprising discovery — there are other Troll worlds beyond their own, and their distinct differences create big clashes between these various tribes. When a mysterious threat puts all of the Trolls across the land in danger, Poppy, Branch, and their band of friends must embark on an epic quest to create harmony among the feuding Trolls to unite them against certain doom.', 91, '/7W0G3YECgDAfnuiHG91r8WqgIOe.jpg', '/qsxhnirlp7y4Ae9bd11oYJSX59j.jpg', '08AExF6dETA'),
    (447200, 'Framed and on the run, a former FBI agent must save his family from a blazing fire in the world''s tallest building.', 102, '/52ml62vClzrlqvXZq2FEW6UF6c1.jpg', '/oMKFQmoVgB69fyXfSMu0lGlHJP2.jpg', '_xcJyqwZxyQ'),
    (447277, 'The youngest of King Triton’s daughters, and the most defiant, Ariel longs to find out more about the world beyond the sea, and while visiting the surface, falls for the dashing Prince Eric. With mermaids forbidden to interact with humans, Ariel makes a deal with the evil sea witch, Ursula, which gives her a chance to experience life on land, but ultimately places her life – and her father’s crown – in jeopardy.', 135, '/ym1dxyOk4jFcSl4Q2zmRrA5BEEN.jpg', '/pbMbDlOAkVuvnxovBA2ENin59xH.jpg', 'kpGo2_d3oYE'),
    (447332, 'A family is forced to live in silence while hiding from creatures that hunt by sound.', 91, '/nAU74GmpUk7t5iklEp3bufwDq4n.jpg', '/nHRUtBwFNnNN70vcQ7lAsjc2T6S.jpg', 'rqEnM25BsNQ'),
    (447365, 'Peter Quill, still reeling from the loss of Gamora, must rally his team around him to defend the universe along with protecting one of their own. A mission that, if not completed successfully, could quite possibly lead to the end of the Guardians as we know them.', 150, '/r2J02Z2OpNTctfOSN1Ydgii51I3.jpg', '/5YZbUmjbMa3ClvSW1Wj3D6XGolb.jpg', 'AAE5VZktooM'),
    (447404, 'In a world where people collect pocket-size monsters (Pokémon) to do battle, a boy comes across an intelligent monster who seeks to be a detective.', 105, '/uhWvnFgg3BNlcUz0Re1HfQqIcCD.jpg', '/yXybBEC45p84D0Ky7GmQQYrclVr.jpg', 'S_uE8kX0CkY'),
    (448119, 'After losing his wife seven years earlier, the eccentric Dr. John Dolittle, famed doctor and veterinarian of Queen Victoria’s England, hermits himself away behind the high walls of Dolittle Manor with only his menagerie of exotic animals for company. But when the young queen falls gravely ill, a reluctant Dolittle is forced to set sail on an epic adventure to a mythical island in search of a cure, regaining his wit and courage as he crosses old adversaries and discovers wondrous creatures.', 101, '/3Nt3v1uzUgfSuVARD1AnI9g9Zl9.jpg', '/xcUf6yIheo78btFqihlRLftdR3M.jpg', 'zjm6rDgKNMY'),
    (449176, 'Everyone deserves a great love story, but for 17-year-old Simon Spier, it''s a little more complicated. He hasn''t told his family or friends that he''s gay, and he doesn''t know the identity of the anonymous classmate that he''s fallen for online.', 110, '/snIsqVPmlu4LPjvToHpDotxa7Eh.jpg', '/nJSPkq5dtASykhiYIZhpCX9Zgeq.jpg', 'E0cbWdlQg_8'),
    (449443, 'A gritty crime saga which follows the lives of an elite unit of the LA County Sheriff''s Dept. and the state''s most successful bank robbery crew as the outlaws plan a seemingly impossible heist on the Federal Reserve Bank.', 140, '/AfybH6GbGFw1F9bcETe2yu25mIE.jpg', '/gQEfeFzEDhvz1YB3JXU2yUZspmH.jpg', 'CZkUlNwiEBY'),
    (449992, 'After sparing a girl''s life during a massacre, an elite Triad assassin is targeted by an onslaught of murderous gangsters.', 121, '/8lI1p5cPqgXN2qrKZrmI3mhKBfs.jpg', '/9uoZrTXUiByDECmWopkIJhZxSzw.jpg', 'HfSisHrUTLM'),
    (450465, 'In a series of escalating encounters, former security guard David Dunn uses his supernatural abilities to track Kevin Wendell Crumb, a disturbed man who has twenty-four personalities. Meanwhile, the shadowy presence of Elijah Price emerges as an orchestrator who holds secrets critical to both men.', 129, '/svIDTNUoajS8dLEo7EosxvyAsgJ.jpg', '/rzsMWXQ7GaN60wIpg3yf01iBmXy.jpg', 'Q7ztHi9ejp4'),
    (451048, 'Dr. Lily Houghton enlists the aid of wisecracking skipper Frank Wolff to take her down the Amazon in his dilapidated boat. Together, they search for an ancient tree that holds the power to heal – a discovery that will change the future of medicine.', 127, '/yKy9ELL8CON5sqDg4yIvBb5LTZL.jpg', '/7WJjFviFBffEJvkAms4uWwbcVUk.jpg', 'hJZ82pwwJqA'),
    (453395, 'Doctor Strange, with the help of mystical allies both old and new, traverses the mind-bending and dangerous alternate realities of the Multiverse to confront a mysterious new adversary.', 126, '/ddJcSKbcp4rKZTmuyWaMhuwcfMz.jpg', '/AdyJH8kDm8xT8IKTlgpEC15ny4u.jpg', 'Rf8LAYJSOL8'),
    (453405, 'Henry Brogan is an elite 51-year-old assassin who''s ready to call it quits after completing his 72nd job. His plans get turned upside down when he becomes the target of a mysterious operative who can seemingly predict his every move. To his horror, Brogan soon learns that the man who''s trying to kill him is a younger, faster, cloned version of himself.', 117, '/49hNtMyJ9Fbapgi2nATtuBYvtBz.jpg', '/hmv300bqfZmxvdXCtCsruDH0ycT.jpg', '6orc_lHvJKY'),
    (454626, 'Powered with incredible speed, Sonic The Hedgehog embraces his new home on Earth. That is, until Sonic sparks the attention of super-uncool evil genius Dr. Robotnik. Now it’s super-villain vs. super-sonic in an all-out race across the globe to stop Robotnik from using Sonic’s unique power for world domination.', 99, '/aQvJ5WPzZgYVDrxLX4R6cLJCEaQ.jpg', '/stmYfCUGd8Iy6kAMBr6AmWqx8Bq.jpg', 'szby7ZHLnkA'),
    (454983, 'When teenager Elle''s first kiss leads to a forbidden romance with the hottest boy in high school, she risks her relationship with her best friend.', 105, '/vcQNnnXgKLacoYF4LNWgkNiDXPd.jpg', '/aqrDUkuzksLhOD8pbyBXLO0dz5t.jpg', '7bfS6seiLhk'),
    (455207, 'An American-born Chinese economics professor accompanies her boyfriend to Singapore for his best friend''s wedding, only to get thrust into the lives of Asia''s rich and famous.', 121, '/1XxL4LJ5WHdrcYcihEZUCgNCpAW.jpg', '/zeHB7aP46Xs3u4aFLuAq2GFeUGb.jpg', 'ZQ-YX-5bAs0'),
    (456740, 'Hellboy comes to England, where he must defeat Nimue, Merlin''s consort and the Blood Queen. But their battle will bring about the end of the world, a fate he desperately tries to turn away.', 121, '/bk8LyaMqUtaQ9hUShuvFznQYQKR.jpg', '/djiDKVB07xTy7tDFbWb9k7KLI3E.jpg', 'ZsBO4b3tyZg'),
    (457799, 'A chronicle of the crimes of Ted Bundy, from the perspective of his longtime girlfriend, Elizabeth Kloepfer, who refused to believe the truth about him for years.', 111, '/a7dVwEBU3vupg3hZQMeyL6ksz0F.jpg', '/uRoA67sM5vvCI4cplxhl67BTPly.jpg', 'mdMtnvMJcDA'),
    (458156, 'Super-assassin John Wick returns with a $14 million price tag on his head and an army of bounty-hunting killers on his trail. After killing a member of the shadowy international assassin’s guild, the High Table, John Wick is excommunicado, but the world’s most ruthless hit men and women await his every turn.', 131, '/ziEuG1essDuWuC5lpWUaw1uXY2O.jpg', '/vVpEOvdxVBP2aV166j5Xlvb5Cdc.jpg', 'pU8-7BX9uxs'),
    (458423, 'Five years after meeting her three fathers, Sophie Sheridan prepares to open her mother’s hotel. In 1979, young Donna Sheridan meets the men who each could be Sophie’s biological father.', 114, '/aWicerX4Y7n7tUwRAVHsVcBBpj2.jpg', '/gtv2H1u9eGffjxVqNfJBZuFCKxR.jpg', 'nd4cLL_MP7M'),
    (458576, 'US Ranger Captain Artemis and her team are part of a UN joint security mission north of Hemat, in Afghanistan.  While searching for a missing team (Bravo), they are transported to a strange world where powerful monsters rule with deadly ferocity.  Faced with relentless danger, the team encounters a mysterious hunter who may be their only hope to find a way home.', 103, '/1UCOF11QCw8kcqvce8LKOO6pimh.jpg', '/8tNX8s3j1O0eqilOQkuroRLyOZA.jpg', 'BeON-bSbrL4'),
    (458723, 'Husband and wife Gabe and Adelaide Wilson take their kids to their beach house expecting to unplug and unwind with friends. But as night descends, their serenity turns to tension and chaos when some shocking visitors arrive uninvited.', 116, '/ux2dU1jQ2ACIMShzB3yP93Udpzc.jpg', '/sC0b8iPUHfZdD8kseLiHw3N8gkp.jpg', 'hNCmb-4oXJA'),
    (459151, 'The Templeton brothers — Tim and his Boss Baby little bro Ted — have become adults and drifted away from each other. But a new boss baby with a cutting-edge approach and a can-do attitude is about to bring them together again … and inspire a new family business.', 107, '/aQ7huOn3F0iJCJrFezS8p9WEsri.jpg', '/yBov7O4eXDcBLDpZrOHZzFr8rIl.jpg', '-rF2j6K5FoM'),
    (460019, 'A harmless game of "Truth or Dare" among friends turns deadly when someone—or something—begins to punish those who tell a lie—or refuse the dare.', 101, '/ei2waWQAG8NP244WShIFgGu9IOu.jpg', '/eQ5xu2pQ5Kergubto5PbbUzey28.jpg', 'BjRNY3u3bUw'),
    (460465, 'Washed-up MMA fighter Cole Young, unaware of his heritage, and hunted by Emperor Shang Tsung''s best warrior, Sub-Zero, seeks out and trains with Earth''s greatest champions as he prepares to stand against the enemies of Outworld in a high stakes battle for the universe.', 110, '/nkayOAUBUu4mMvyNf9iHSUiPjF1.jpg', '/6ELCZlTA5lGUops70hKdB83WJxH.jpg', 'jBa_aHwCbC4'),
    (460885, 'The Shadow Mountains, 1983. Red and Mandy lead a loving and peaceful existence; but when their pine-scented haven is savagely destroyed, Red is catapulted into a phantasmagoric journey filled with bloody vengeance and laced with fire.', 122, '/m0yf7J7HsKeK6E81SMRcX8vx6mH.jpg', '/tNa19CK0CQZl5rxZ35QRdKAT2s0.jpg', 'rI054ow6KJk'),
    (461130, 'In Lincoln City, some inhabitants have extraordinary abilities. Most live below the poverty line, under the close surveillance of a heavily militarized police force. Connor, a construction worker with powers, involves with a criminal gang to help his ailing mother. (Based on the short film “Code 8,” 2016.)', 99, '/izGX7npHEopDQvngYcxMJEfcFbj.jpg', '/gqbgCJUZyy4NEdk5m0qxaNOvAqq.jpg', 'PrX1JJ5dduA'),
    (463272, 'Disaster strikes when a criminal mastermind reveals the identities of all active undercover agents in Britain. The secret service can now rely on only one man - Johnny English. Currently teaching at a minor prep school, Johnny springs back into action to find the mysterious hacker. For this mission to succeed, he’ll need all of his skills - what few he has - as the man with yesterday’s analogue methods faces off against tomorrow’s digital technology.', 88, '/tCBxnZwLiY1BOKw3tH6AxHZdqPh.jpg', '/qw6nuv56NW1JqzMoONlM84Iciwz.jpg', '__c_SVavGF4'),
    (463821, 'When ten-year-old Lewis is suddenly orphaned, he is sent to live with his Uncle Jonathan in a creaky (and creepy) old mansion with a mysterious ticking noise that emanates from the walls. Upon discovering that his uncle is a warlock, Lewis begins learning magic, but when he rebelliously resurrects an evil warlock he must find the secret of the house and save the world from destruction.', 105, '/qM66Hv4ByAxnilr0jaqCA9uOD4Y.jpg', '/tQvvRReWhrXnj28s4AIp2PblByg.jpg', 'uIlx5-aGq_A'),
    (464052, 'A botched store robbery places Wonder Woman in a global battle against a powerful and mysterious ancient force that puts her powers in jeopardy.', 151, '/8UlWHLMpgZm9bx6QYh0NFoq67TZ.jpg', '/egg7KFi18TSQc1s24RMmR9i2zO6.jpg', 'EMgbWouN4wE'),
    (466272, 'Los Angeles, 1969. TV star Rick Dalton, a struggling actor specializing in westerns, and stuntman Cliff Booth, his best friend, try to survive in a constantly changing movie industry. Dalton is the neighbor of the young and promising actress and model Sharon Tate, who has just married the prestigious Polish director Roman Polanski…', 162, '/8j58iEBw9pOXFD2L0nt0ZXeHviB.jpg', '/kKTPv9LKKs5L3oO1y5FNObxAPWI.jpg', 'vKgITiP1UMg'),
    (466282, 'Lara Jean''s love life goes from imaginary to out of control when her secret letters to every boy she''s ever fallen for are mysteriously mailed out.', 100, '/hKHZhUbIyUAjcSrqJThFGYIR6kI.jpg', '/xXhta1NIKn09IXy0mfp68cabdWS.jpg', '555oiY9RWM4'),
    (473033, 'A charismatic New York City jeweler always on the lookout for the next big score makes a series of high-stakes bets that could lead to the windfall of a lifetime. Howard must perform a precarious high-wire act, balancing business, family, and encroaching adversaries on all sides in his relentless pursuit of the ultimate win.', 136, '/6XN1vxHc7kUSqNWtaQKN45J5x2v.jpg', '/eGljNfNCrPhFYG2RXXmmE0OKu5.jpg', 'sXga1Oy0iRk'),
    (475557, 'During the 1980s, a failed stand-up comedian is driven insane and turns to a life of crime and chaos in Gotham City while becoming an infamous psychopathic crime figure.', 122, '/udDclJoHjfjb8Ekgsd4FDteOkCU.jpg', '/rlay2M5QYvi6igbGcFjq8jxeusY.jpg', '-RFFRxcoKfA'),
    (476669, 'As a collection of history''s worst tyrants and criminal masterminds gather to plot a war to wipe out millions, one man must race against time to stop them.', 131, '/iMjSfMUuCkCE7z5fzGtjeDusPD3.jpg', '/oQPbZ5e6J9fuAyv4Gl0mMZMIyPI.jpg', '_0vKejp3rvA'),
    (479455, 'The Men in Black have always protected the Earth from the scum of the universe. In this new adventure, they tackle their biggest, most global threat to date: a mole in the Men in Black organization.', 115, '/dPrUPFcgLfNbmDL8V69vcrTyEfb.jpg', '/2FYzxgLNuNVwncilzUeCGbOQzP7.jpg', 'F3lJwV7ZIIk'),
    (480530, 'Between personal obligations and training for his next big fight against an opponent with ties to his family''s past, Adonis Creed is up against the challenge of his life.', 130, '/v3QyboWRoA4O9RbcsqH8tJMe8EB.jpg', '/9il7qNbeYnPMYlutsVYDsj4hRyb.jpg', 'cPNVNqn4T9I'),
    (481084, 'The Addams family''s lives begin to unravel when they face-off against a treacherous, greedy crafty reality-TV host while also preparing for their extended family to arrive for a major celebration.', 87, '/q1epO0eO8DWu8Vo8tPfvVlzW48T.jpg', '/grY5sfuT9YeXWlp4JYCmRZVqjk0.jpg', 'xFCrR3Uw6Mk'),
    (481848, 'Buck is a big-hearted dog whose blissful domestic life is turned upside down when he is suddenly uprooted from his California home and transplanted to the exotic wilds of the Yukon during the Gold Rush of the 1890s. As the newest rookie on a mail delivery dog sled team—and later its leader—Buck experiences the adventure of a lifetime, ultimately finding his true place in the world and becoming his own master.', 100, '/33VdppGbeNxICrFUtW2WpGHvfYc.jpg', '/1GZCV0dwIoAn6jpWPfVAbeMTVC2.jpg', '5P8R2zAhEwg'),
    (483906, 'When a retiring assassin realizes that he is the target of a hit, he winds up back in the game going head to head with a gang of younger, ruthless killers.', 118, '/qOBEpKVLl8Q9CZScbOcRRVISezV.jpg', '/lSCKo6QGJ88Gn3espNnvL87CinA.jpg', 'oMHwRal-AR8'),
    (484247, 'Stephanie, a dedicated mother and popular vlogger, befriends Emily, a mysterious upper-class woman whose son Nicky attends the same school as Miles, Stephanie''s son. When Emily asks her to pick Nicky up from school and then disappears, Stephanie undertakes an investigation that will dive deep into Emily''s cloudy past.', 117, '/aIYsjQM0piKc0ibPBCTWv3sqshj.jpg', '/ugDSJKMEexMt1d38uyzRnVFsDIh.jpg', 'rAqMlh0b2HU'),
    (484641, 'Beneath Anna Poliatova''s striking beauty lies a secret that will unleash her indelible strength and skill to become one of the world''s most feared government assassins.', 119, '/2U0oAVAE0lDRhNmJPPYhDW9kQ8t.jpg', '/xavGKawUyXPWAa6JTUkFzaRXMPF.jpg', 'oZSMV-NDH4w'),
    (487558, 'Colorado Springs, late 1970s. Ron Stallworth, an African American police officer, and Flip Zimmerman, his Jewish colleague, run an undercover operation to infiltrate the Ku Klux Klan.', 136, '/8jxqAvSDoneSKRczaK8v9X5gqBp.jpg', '/ot3eZ9XfOF42a3zFWluMPWkfCHB.jpg', '7tgMuagdEhc'),
    (489999, 'After David Kim''s 16-year-old daughter goes missing, a local investigation is opened and a detective is assigned to the case. But 37 hours later and without a single lead, David decides to search the one place no one has looked yet, where all secrets are kept today: his daughter''s laptop.', 102, '/yuAPCsCGJGSxA7YOW4elF5JNrzK.jpg', '/jOqOduY1tLhXgVZo7ypCtDVr0mM.jpg', '1f-nx8OAMVk'),
    (490132, 'Tony Lip, a bouncer in 1962, is hired to drive pianist Don Shirley on a tour through the Deep South in the days when African Americans, forced to find alternate accommodations and services due to segregation laws below the Mason-Dixon Line, relied on a guide called The Negro Motorist Green Book.', 130, '/7BsvSuDQuoqhWmU2fL7W2GOcZHU.jpg', '/5En0fmDagt3Pk8d7P3uTwfeQceg.jpg', 'QkZxoko_HC0'),
    (491418, 'When Pete and Ellie decide to start a family, they stumble into the world of foster care adoption. They hope to take in one small child but when they meet three siblings, including a rebellious 15 year old girl, they find themselves speeding from zero to three kids overnight.', 118, '/xYV1mODz99w7AjKDSQ7h2mzZhVe.jpg', '/hgESQ2sK21j22Yode4w99jfwj44.jpg', 'IUfZq3DUd3Y'),
    (492188, 'A stage director and an actress struggle through a grueling, coast-to-coast divorce that pushes them to their personal extremes.', 137, '/2JRyCKaRKyJAVpsIHeLvPw5nHmw.jpg', '/wDwQXLDUuiEaaiuWIDBpbqnwYGX.jpg', 'BHi-a1n8t7M'),
    (493529, 'A charming thief and a band of unlikely adventurers undertake an epic heist to retrieve a lost relic, but things go dangerously awry when they run afoul of the wrong people.', 134, '/v7UF7ypAqjsFZFdjksjQ7IUpXdn.jpg', '/AdBXP8e6K3FYdDrMx3Wr6WZqCYF.jpg', '9LLOLEBlVIA'),
    (495764, 'Harley Quinn joins forces with a singer, an assassin and a police detective to help a young girl who had a hit placed on her after she stole a rare diamond from a crime lord.', 109, '/h4VB6m0RwcicVEZvzftYZyKXs6K.jpg', '/3zBjU7mXlzxJKAStRzlNDZRGT0m.jpg', 'q2u2raiIlm0'),
    (496243, 'All unemployed, Ki-taek''s family takes peculiar interest in the wealthy and glamorous Parks for their livelihood until they get entangled in an unexpected incident.', 133, '/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg', '/TU9NIjwzjoKPwQHoHshkFcQUCG.jpg', 'bM9QabAojCg'),
    (497582, 'While searching for her missing mother, intrepid teen Enola Holmes uses her sleuthing skills to outsmart big brother Sherlock and help a runaway lord.', 124, '/riYInlsq2kf1AWoGm80JQW5dLKp.jpg', '/kMe4TKMDNXTKptQPAdOF0oZHq3V.jpg', '1d0Zf9sXlHk'),
    (497698, 'Natasha Romanoff, also known as Black Widow, confronts the darker parts of her ledger when a dangerous conspiracy with ties to her past arises. Pursued by a force that will stop at nothing to bring her down, Natasha must deal with her history as a spy and the broken relationships left in her wake long before she became an Avenger.', 134, '/qAZ0pzat24kLdO3o8ejmbLxyOac.jpg', '/keIxh0wPr2Ymj0Btjh4gW7JJ89e.jpg', 'Fp9pNPdNwjI'),
    (500664, 'A brutal mugging leaves Grey Trace paralyzed in the hospital and his beloved wife dead. A billionaire inventor soon offers Trace a cure — an artificial intelligence implant called STEM that will enhance his body. Now able to walk, Grey finds that he also has superhuman strength and agility — skills he uses to seek revenge against the thugs who destroyed his life.', 100, '/woLGROUdPWdBnLVFKYdGD3kFkPY.jpg', '/oiPUcD1IIZrYGTSIpvTmd3dRmPo.jpg', 'gEnRNIvEKu8'),
    (501170, 'Still scarred by the trauma he endured as a child at the Overlook Hotel, Dan Torrance faces the ghosts of the past when he meets Abra, a courageous teen who desperately needs his help -- and who possesses a powerful extrasensory ability called the "shine".', 152, '/p69QzIBbN06aTYqRRiCOY1emNBh.jpg', '/ap6Zc5NDOfbZaMhkRDyghbGeLf0.jpg', '6u8ggerDcwg'),
    (501929, 'A quirky, dysfunctional family''s road trip is upended when they find themselves in the middle of the robot apocalypse and suddenly become humanity''s unlikeliest last hope.', 110, '/mI2Di7HmskQQ34kz0iau6J1vr70.jpg', '/vsZLf5uog08pAnfsMuDWrsLWUUF.jpg', '_ak5dFt8Ar0'),
    (502356, 'While working underground to fix a water main, Brooklyn plumbers—and brothers—Mario and Luigi are transported down a mysterious pipe and wander into a magical new world. But when the brothers are separated, Mario embarks on an epic quest to find Luigi.', 93, '/qNBAXBIQlnOThrVvA6mA2B5ggV6.jpg', '/9n2tJBplPbgR2ca05hS5CKXwP2c.jpg', 'RjNcTBXTk4I'),
    (502416, 'Sue Ann is a loner who keeps to herself in her quiet Ohio town. One day, she is asked by Maggie, a new teenager in town, to buy some booze for her and her friends, and Sue Ann sees the chance to make some unsuspecting, if younger, friends of her own.', 99, '/6n7ASmQ1wY2cxTubFFGlcvPpyk7.jpg', '/35kYvfK9TUOQ912QVsNoTCnYqlH.jpg', 'eIvbEC8N3cA'),
    (503314, 'Earth is peaceful following the Tournament of Power. Realizing that the universes still hold many more strong people yet to see, Goku spends all his days training to reach even greater heights. Then one day, Goku and Vegeta are faced by a Saiyan called ''Broly'' who they''ve never seen before. The Saiyans were supposed to have been almost completely wiped out in the destruction of Planet Vegeta, so what''s this one doing on Earth? This encounter between the three Saiyans who have followed completely different destinies turns into a stupendous battle, with even Frieza (back from Hell) getting caught up in the mix.', 101, '/uMEgkyiPznZP5AiMSWAk2jsj5gC.jpg', '/6OTRuxpwUUGbmCX3MKP25dOmo59.jpg', '1GtIJsvIFAQ'),
    (503736, 'Following a zombie outbreak in Las Vegas, a group of mercenaries take the ultimate gamble: venturing into the quarantine zone to pull off the greatest heist ever attempted.', 148, '/gCIsRxzcxvmuLYeAvWgoOuSxszF.jpg', '/c0izdYdnTe4uMRifHgvTA85wPz0.jpg', 'tI1JGPhYBS8'),
    (503919, 'Two lighthouse keepers try to maintain their sanity while living on a remote and mysterious New England island in the 1890s.', 109, '/dwXmOYJVM1VIkkSXHY5zYSaLJLC.jpg', '/sYLzRuEcwSz0L1Z92wQNrETHU9O.jpg', '42_UHhpq530'),
    (504172, 'Earl Stone, a man in his eighties, is broke, alone, and facing foreclosure of his business when he is offered a job that simply requires him to drive. Easy enough, but, unbeknownst to Earl, he''s just signed on as a drug courier for a Mexican cartel. He does so well that his cargo increases exponentially, and Earl hit the radar of hard-charging DEA agent Colin Bates.', 116, '/vkOfx5meJvFb4qmAJU7j6v8IIpZ.jpg', '/h51DdjaDD2aPu1fLHsmpJaaJinS.jpg', '0WhaleJ3Zik'),
    (504608, 'The story of Elton John''s life, from his years as a prodigy at the Royal Academy of Music through his influential and enduring musical partnership with Bernie Taupin.', 121, '/f4FF18ia7yTvHf2izNrHqBmgH8U.jpg', '/isnJGDrfR9dIrHMsPTvHtJaGEpc.jpg', 'S3vO8E2e6G0'),
    (505026, 'Belgian sleuth Hercule Poirot''s Egyptian vacation aboard a glamorous river steamer turns into a terrifying search for a murderer when a picture-perfect couple''s idyllic honeymoon is tragically cut short.', 127, '/kVr5zIAFSPRQ57Y1zE7KzmhzdMQ.jpg', '/lRbDyjI7HEaXxflFQbYpqHRGFBJ.jpg', 'dZRqB0JLizw'),
    (505642, 'Queen Ramonda, Shuri, M’Baku, Okoye and the Dora Milaje fight to protect their nation from intervening world powers in the wake of King T’Challa’s death.  As the Wakandans strive to embrace their next chapter, the heroes must band together with the help of War Dog Nakia and Everett Ross and forge a new path for the kingdom of Wakanda.', 162, '/sv1xJUazXeYqALzczSZ3O6nkH75.jpg', '/83H0C66AcvkwpG2738VCTHMY9uv.jpg', '_Z3QKkl1WyM'),
    (507076, 'When a dance troupe is lured to an empty school, a bowl of drug-laced sangria causes their jubilant rehearsal to descend into a dark and explosive nightmare as they try to survive the night—and find who''s responsible—before it''s too late.', 97, '/47IXH2iEWwX0F7vIyGXaKQ0psBG.jpg', '/v0sblc9A8eaE8EqDQ5Y6fELj4oB.jpg', 'Hi69nL_VrTE'),
    (507086, 'Four years after Isla Nublar was destroyed, dinosaurs now live—and hunt—alongside humans all over the world. This fragile balance will reshape the future and determine, once and for all, whether human beings are to remain the apex predators on a planet they now share with history''s most fearsome creatures.', 147, '/jbAvCACjLf1ZG0unB2tdmx5HAf1.jpg', '/9hk5iiycq7ukRAAXQiJT9HZX3SX.jpg', 'DtQycgMD4HQ'),
    (507089, 'Recently fired and desperate for work, a troubled young man named Mike agrees to take a position as a night security guard at an abandoned theme restaurant: Freddy Fazbear''s Pizzeria. But he soon discovers that nothing at Freddy''s is what it seems.', 110, '/7BpNtNfxuocYEVREzVMO75hso1l.jpg', '/7NRGAtu8E4343NSKwhkgmVRDINw.jpg', 'X4d_v-HyR4o'),
    (508439, 'In a suburban fantasy world, two teenage elf brothers embark on an extraordinary quest to discover if there is still a little magic left out there.', 102, '/f4aul3FyD3jv3v4bul1IrkWZvzq.jpg', '/bcT8CaBIj086WVD7K529h78eujb.jpg', 'HxKXiQvyG_o'),
    (508442, 'Joe Gardner is a middle school teacher with a love for jazz music. After a successful audition at the Half Note Club, he suddenly gets into an accident that separates his soul from his body and is transported to the You Seminar, a center in which souls develop and gain passions before being transported to a newborn child. Joe must enlist help from the other souls-in-training, like 22, a soul who has spent eons in the You Seminar, in order to get back to Earth.', 101, '/hm58Jw4Lw8OIeECIq5qyPYhAeRJ.jpg', '/rQaHA74pevnGsxcKGaoZVGWe9TC.jpg', 'Gs--6c7Hn_A'),
    (508883, 'While the Second World War rages, the teenage Mahito, haunted by his mother''s tragic death, is relocated from Tokyo to the serene rural home of his new stepmother Natsuko, a woman who bears a striking resemblance to the boy''s mother.  As he tries to adjust, this strange new world grows even stranger following the appearance of a persistent gray heron, who perplexes and bedevils Mahito, dubbing him the "long-awaited one."', 124, '/4GKye5dR4uJyYbcyTveSue1gATD.jpg', '/75nSb1fbWooipwcSU5bUttiOriI.jpg', 'A002-b7IH2M'),
    (508943, 'Luca and his best friend Alberto experience an unforgettable summer on the Italian Riviera. But all the fun is threatened by a deeply-held secret: they are sea monsters from another world just below the water’s surface.', 95, '/9x4i9uKGXt8IiiIF5Ey0DIoY738.jpg', '/620hnMVLu6RSZW6a5rwO8gqpt0t.jpg', 'mYfJxlgR2jw'),
    (508947, 'Thirteen-year-old Mei is experiencing the awkwardness of being a teenager with a twist – when she gets too excited, she transforms into a giant red panda.', 100, '/qsdjk9oAKSQMWs0Vt5Pyfh6O4GZ.jpg', '/fOy2Jurz9k6RnJnMUMRDAgBwru2.jpg', 'XdKzUbAiswE'),
    (508965, 'A selfish postman and a reclusive toymaker form an unlikely friendship, delivering joy to a cold, dark town that desperately needs it.', 97, '/q125RHUDgR4gjwh1QkfYuJLYkL.jpg', '/cYQvXNPZLow73lhspVQ7CYlT3Mi.jpg', 'taE3PwurhYM'),
    (509967, 'After faking his death, a tech billionaire recruits a team of international operatives for a bold and bloody mission to take down a brutal dictator.', 128, '/lnWkyG3LLgbbrIEeyl5mK5VRFe4.jpg', '/eFw5YSorHidsajLTayo1noueIxI.jpg', 'XcIuFTrLS6g'),
    (512195, 'An Interpol-issued Red Notice is a global alert to hunt and capture the world''s most wanted. But when a daring heist brings together the FBI''s top profiler and two rival criminals, there''s no telling what will happen.', 118, '/lAXONuqg41NwUMuzMiFvicDET9Y.jpg', '/p34WRcgkN2QIHcds5FtFiSpV3PC.jpg', 'Pj0wz7zu3Ms'),
    (512196, 'Collegian Tree Gelbman wakes up in horror to learn that she''s stuck in a parallel universe. Her boyfriend Carter is now with someone else, and her friends and fellow students seem to be completely different versions of themselves. When Tree discovers that Carter''s roommate has been altering time, she finds herself once again the target of a masked killer. When the psychopath starts to go after her inner circle, Tree soon realizes that she must die over and over again to save everyone.', 100, '/4tdnePOkOOzwuGPEOAHp8UA4vqx.jpg', '/bU1n7bkDviEqwfKFTbjQ8BFrqEN.jpg', 'MT9MBytHuOI'),
    (512200, 'As the gang return to Jumanji to rescue one of their own, they discover that nothing is as they expect. The players will have to brave parts unknown and unexplored in order to escape the world’s most dangerous game.', 123, '/2RyMYPKmlUcT4BkVmPIOUV4X2iC.jpg', '/qgch2rFskIxDMgwrD5lWTaB4nBl.jpg', 'F6QaLsw8EWY'),
    (514999, 'On a long-awaited trip to Europe, a New York City cop and his hairdresser wife scramble to solve a baffling murder aboard a billionaire''s yacht.', 98, '/bSMSO9xupd4R4vwTPqigHn2quLN.jpg', '/wL8KA3zIJQPbbU5hJlyIdmmLZit.jpg', '5YEVQDr2f3Q'),
    (515001, 'Jojo, a lonely German boy during World War II has his world shaken when he learns that his single mother is hiding a Jewish girl in their home. Influenced by a buffoonish imaginary version of Adolf Hitler, he begins to question his beliefs and confront the conflict between propaganda and his own humanity.', 108, '/1mqL7VG4Ix8wmxwypmCA1HTHBky.jpg', '/lTyikzfGgRX5ZqIfVeT26APYfRL.jpg', 'tL4McUzXfFI'),
    (515195, 'A struggling musician realizes he''s the only person on Earth who can remember The Beatles after waking up in an alternate reality where the group was forgotten.', 116, '/9fYka5CQt9nrb6LOtKicysUf9NA.jpg', '/t5Kp02Jzixl0KfpwthHp9ZUex9t.jpg', 'qD6FDkUXSZQ'),
    (519182, 'Gru and Lucy and their girls—Margo, Edith and Agnes—welcome a new member to the Gru family, Gru Jr., who is intent on tormenting his dad. Gru also faces a new nemesis in Maxime Le Mal and his femme fatale girlfriend Valentina, forcing the family to go on the run.', 94, '/wWba3TaojhK7NdycRhoQpsG0FaH.jpg', '/twsxsfao6ZOVvT8LfudH603MMi6.jpg', 'LtNYaH61dXY'),
    (520763, 'Following the events at home, the Abbott family now face the terrors of the outside world. Forced to venture into the unknown, they realize that the creatures that hunt by sound are not the only threats that lurk beyond the sand path.', 97, '/4q2hz2m8hubgvijz8Ez0T2Os2Yv.jpg', '/uuBYYlbfiYD7ny5VNj46NG14ykR.jpg', 'BpdDN9d9Jio'),
    (521029, 'Determined to keep Annabelle from wreaking more havoc, demonologists Ed and Lorraine Warren bring the possessed doll to the locked artifacts room in their home, placing her “safely” behind sacred glass and enlisting a priest’s holy blessing. But an unholy night of horror awaits as Annabelle awakens the evil spirits in the room, who all set their sights on a new target—the Warrens'' ten-year-old daughter, Judy, and her friends.', 106, '/qFjtLOeVl4jpzPUhp4cl4ieANHY.jpg', '/tKgOSGe3f8qG5EqG0I82NHJmCRS.jpg', 'bCxm7cTpBAs'),
    (522402, 'On a post-apocalyptic Earth, a robot, built to protect the life of his dying creator''s beloved dog, learns about life, love, friendship, and what it means to be human.', 116, '/eEJtzD1F05xDipFEDY98CTH5yZn.jpg', '/uoc358GH6Yl7TufbUKHkETPu64B.jpg', '-0bYWnP3jH4'),
    (522627, 'American expat Mickey Pearson has built a highly profitable marijuana empire in London. When word gets out that he’s looking to cash out of the business forever it triggers plots, schemes, bribery and blackmail in an attempt to steal his domain out from under him.', 113, '/jtrhTYB7xSrJxR1vusu99nvnZ1g.jpg', '/tintsaQ0WLzZsTMkTiqtMB3rfc8.jpg', 'KlXsguV9g0E'),
    (522681, 'Six strangers find themselves in circumstances beyond their control, and must use their wits to survive.', 99, '/8Ls1tZ6qjGzfGHjBB7ihOnf7f0b.jpg', '/mWLljCmpqlcYQh7uh51BBMwCZwN.jpg', '6dSKUoV0SNI'),
    (522938, 'After fighting his demons for decades, John Rambo now lives in peace on his family ranch in Arizona, but his rest is interrupted when Gabriela, the granddaughter of his housekeeper María, disappears after crossing the border into Mexico to meet her biological father. Rambo, who has become a true father figure for Gabriela over the years, undertakes a desperate and dangerous journey to find her.', 89, '/kTQ3J8oTTKofAVLYnds2cHUz9KO.jpg', '/spYx9XQFODuqEVoPpvaJI1ksAVt.jpg', 'YPuhNtG47M0'),
    (523139, 'After hearing a child screaming for help from the green depths of a vast field of tall grass, Becky, a pregnant woman, and Cal, her brother, park their car near a mysterious abandoned church and enter the field, discovering that they are not alone and, for some reason, they are unable to escape a completely inextricable vegetable labyrinth.', 101, '/1RxhzwFkAUqMt215Brb06u8P8pn.jpg', '/qk8pKinGFWEDZ02NVKuUsBuWuGx.jpg', '7afc9gTbVFI'),
    (524047, 'John Garrity, his estranged wife and their young son embark on a perilous journey to find sanctuary as a planet-killing comet hurtles toward Earth. Amid terrifying accounts of cities getting levelled, the Garritys experience the best and worst in humanity. As the countdown to the global apocalypse approaches zero, their incredible trek culminates in a desperate and last-minute flight to a possible safe haven.', 120, '/bNo2mcvSwIvnx8K6y1euAc1TLVq.jpg', '/2Fk3AB8E9dYIBc2ywJkxk8BTyhc.jpg', 'd4s9XNChIRk'),
    (524434, 'The Eternals are a team of ancient aliens who have been living on Earth in secret for thousands of years. When an unexpected tragedy forces them out of the shadows, they are forced to reunite against mankind’s most ancient enemy, the Deviants.', 156, '/lFByFSLV5WDJEv3KabbdAF959F2.jpg', '/c6H7Z4u73ir3cIoCteuhJh7UCAR.jpg', 'x_me3xsvDgk'),
    (526896, 'Dangerously ill with a rare blood disorder, and determined to save others suffering his same fate, Dr. Michael Morbius attempts a desperate gamble. What at first appears to be a radical success soon reveals itself to be a remedy potentially worse than the disease.', 105, '/Av8Z2jZhEm1FLkFzMThzz9hndJF.jpg', '/jzWT0zd8U77fqWg5WgUfYaMzSFz.jpg', 'wG2TjtueeSU'),
    (527435, 'Siblings Kate and Teddy try to prove Santa Claus is real, but when they accidentally cause his sleigh to crash, they have to save Christmas.', 104, '/5Il2EMSF2KecrUKZPuen6BZmaCP.jpg', '/zQVsXIPXU040BnFtBmzoOfYGcDu.jpg', 'YaeDa_Uempk'),
    (527641, 'Seventeen-year-old Stella spends most of her time in the hospital as a cystic fibrosis patient. Her life is full of routines, boundaries and self-control — all of which get put to the test when she meets Will, an impossibly charming teen who has the same illness. There''s an instant flirtation, though restrictions dictate that they must maintain a safe distance between them. As their connection intensifies, so does the temptation to throw the rules out the window and embrace that attraction.', 116, '/kreTuJBkUjVWePRfhHZuYfhNE1T.jpg', '/cYdHaKx6Ihj1BIvbxpCxIGXfZ02.jpg', '24YrEAGF32M'),
    (527774, 'Long ago, in the fantasy world of Kumandra, humans and dragons lived together in harmony. But when an evil force threatened the land, the dragons sacrificed themselves to save humanity. Now, 500 years later, that same evil has returned and it’s up to a lone warrior, Raya, to track down the legendary last dragon to restore the fractured land and its divided people.', 107, '/5nVhgCzxKbK47OLIKxCR1syulOn.jpg', '/zmX7ObPaRfiCmY6LMalUb1bJDKj.jpg', '3UFWsEY8Hdc'),
    (529203, 'Searching for a safer habitat, the prehistoric Crood family discovers an idyllic, walled-in paradise that meets all of its needs. Unfortunately, they must also learn to live with the Bettermans -- a family that''s a couple of steps above the Croods on the evolutionary ladder. As tensions between the new neighbors start to rise, a new threat soon propels both clans on an epic adventure that forces them to embrace their differences, draw strength from one another, and survive together.', 95, '/tbVZ3Sq88dZaCANlUcewQuHQOaE.jpg', '/ytTQoYkdpsgtfDWrNFCei8Mfbxu.jpg', 'hy4vAqF9Ko0'),
    (530385, 'Several friends travel to Sweden to study as anthropologists a summer festival that is held every ninety years in the remote hometown of one of them. What begins as a dream vacation in a place where the sun never sets, gradually turns into a dark nightmare as the mysterious inhabitants invite them to participate in their disturbing festive activities.', 147, '/7LEI8ulZzO5gy9Ww2NVCrKmHeDZ.jpg', '/pYgj8e2Y6RufnSyOA6OnzmxFXxZ.jpg', '1Vnghdsjmd0'),
    (530915, 'At the height of the First World War, two young British soldiers must cross enemy territory and deliver a message that will stop a deadly attack on hundreds of soldiers.', 119, '/iZf0KyrE25z1sage4SYFLCCrMi9.jpg', '/2lBOQK06tltt8SQaswgb8d657Mv.jpg', 'gZjQROMAh_s'),
    (533535, 'A listless Wade Wilson toils away in civilian life with his days as the morally flexible mercenary, Deadpool, behind him. But when his homeworld faces an existential threat, Wade must reluctantly suit-up again with an even more reluctant Wolverine.', 128, '/8cdWjvZQUExUUTzyp4t6EDMubfO.jpg', '/by8z9Fe8y7p4jo2YlW2SZDnptyT.jpg', 'Idh8n5XuYIA'),
    (535581, 'In the sleepy town of Centerville, the lives of a number of interconnected characters are disrupted by the undead.', 104, '/ndvOjo7Nfk8ULnFLMXthPzhI62L.jpg', '/cXyfAViYly0Lk2CVpEKgYbt9wKQ.jpg', 'CeWfxvHmNTI'),
    (536554, 'A brilliant toy company roboticist uses artificial intelligence to develop M3GAN, a life-like doll programmed to emotionally bond with her newly orphaned niece. But when the doll''s programming works too well, she becomes overprotective of her new friend with terrifying results.', 102, '/d9nBoowhjiiYc4FBNtQkPY7c11H.jpg', '/qd4EKTuudkws9lW76Dn9C0tnuVA.jpg', 'OoDHM_A1axc'),
    (537915, 'Tessa Young is a dedicated student, dutiful daughter and loyal girlfriend to her high school sweetheart. Entering her first semester of college, Tessa''s guarded world opens up when she meets Hardin Scott, a mysterious and brooding rebel who makes her question all she thought she knew about herself -- and what she wants out of life.', 106, '/u3B2YKUjWABcxXZ6Nm9h10hLUbh.jpg', '/997ToEZvF2Obp9zNZbY5ELVnmrW.jpg', '2ZAdcWHuCmY'),
    (539885, 'A black ops assassin is forced to fight for her own survival after a job goes dangerously wrong.', 96, '/qzA87Wf4jo1h8JMk9GilyIYvwsA.jpg', '/54yOImQgj8i85u9hxxnaIQBRUuo.jpg', 'ozUuAcGOhPs'),
    (539972, 'Kraven Kravinoff''s complex relationship with his ruthless gangster father, Nikolai, starts him down a path of vengeance with brutal consequences, motivating him to become not only the greatest hunter in the world, but also one of its most feared.', 127, '/1GvBhRxY6MELDfxFrete6BNhBB5.jpg', '/bGGjyPqtNc8hhGkPo8W8D8t90bW.jpg', 'hR1-ihzff3I'),
    (541671, 'Taking place during the events of John Wick: Chapter 3 – Parabellum, Eve Macarro begins her training in the assassin traditions of the Ruska Roma.', 125, '/2VUmvqsHb6cEtdfscEA6fqqVzLg.jpg', '/1yktYsxkmUtUFTUnCAUaqG6FEiz.jpg', 'b9Rr9ygb-ac'),
    (545609, 'A hardened gun-for-hire''s latest mission becomes a soul-searching race to survive when he''s sent into Bangladesh to rescue a drug lord''s kidnapped son.', 116, '/nygOUcBKPHFTbxsYRFZVePqgPK6.jpg', '/2QSZ4CPd8AoljAL76qM30dFft07.jpg', 'L6P3nI6VnlY'),
    (545611, 'An aging Chinese immigrant is swept up in an insane adventure, where she alone can save what''s important to her by connecting with the lives she could have led in other universes.', 140, '/u68AjlvlutfEIcpmbYpKcdi09ut.jpg', '/fIwiFha3WPu5nHkBeMQ4GzEk0Hv.jpg', 'wxN1T1uxQ2g'),
    (546121, 'Chloe, a teenager who is confined to a wheelchair, is homeschooled by her mother, Diane. Chloe soon becomes suspicious of her mother and begins to suspect that she may be harboring a dark secret.', 90, '/ilHG4EayOVoYeKqslspY3pR4wzC.jpg', '/rLchzndbDRy41J9X363pMePbV5x.jpg', 'z_v0icKzgw0'),
    (546554, 'When renowned crime novelist Harlan Thrombey is found dead at his estate just after his 85th birthday, the inquisitive and debonair Detective Benoit Blanc is mysteriously enlisted to investigate. From Harlan''s dysfunctional family to his devoted staff, Blanc sifts through a web of red herrings and self-serving lies to uncover the truth behind Harlan''s untimely death.', 131, '/pThyQovXQrw2m0s9x82twj48Jq4.jpg', '/4HWAQu28e2yaWrtupFPGFkdNU7V.jpg', 'qOg3AoRc4nI'),
    (547016, 'Four undying warriors who''ve secretly protected humanity for centuries become targeted for their mysterious powers just as they discover a new immortal.', 125, '/cjr4NWURcVN3gW5FlHeabgBHLrY.jpg', '/m0ObOaJBerZ3Unc74l471ar8Iiy.jpg', 'aK-X2d0lJ_s'),
    (549053, 'Kate is a young woman who has a habit of making bad decisions, and her last date with disaster occurs after she accepts work as Santa''s elf for a department store. However, after she meets Tom there, her life takes a new turn.', 103, '/kDEjffiKgjuGo2DRzsqfjvW0CQh.jpg', '/qIjyBgsMDbpeEO3CJx7vxVn4KO8.jpg', 'z9CEIcmWmtA'),
    (550988, 'A bank teller discovers he is actually a background player in an open-world video game, and decides to become the hero of his own story. Now, in a world where there are no limits, he is determined to be the guy who saves his world his way before it''s too late.', 115, '/dxraF0qPr1OEgJk17ltQTO84kQF.jpg', '/rOJb0yQOCny0bPjg8bCLw8DyAD7.jpg', 'cttnRmcr_ME'),
    (552524, 'The wildly funny and touching story of a lonely Hawaiian girl and the fugitive alien who helps to mend her broken family.', 108, '/ckQzKpQJO4ZQDCN5evdpKcfm7Ys.jpg', '/7Zx3wDG5bBtcfk8lcnCWDOLM4Y4.jpg', 'VWqJifMMgZE'),
    (556984, 'What was supposed to be a peaceful protest turned into a violent clash with the police. What followed was one of the most notorious trials in history.', 130, '/ahf5cVdooMAlDRiJOZQNuLqa1Is.jpg', '/v8Nf6Y1qL1Q3PWTBezXNPPaXqza.jpg', 'FVb6EdKDBfU'),
    (558449, 'Years after witnessing the death of the revered hero Maximus at the hands of his uncle, Lucius is forced to enter the Colosseum after his home is conquered by the tyrannical Emperors who now lead Rome with an iron fist. With rage in his heart and the future of the Empire at stake, Lucius must look to his past to find strength and honor to return the glory of Rome to its people.', 148, '/2cxhvwyEwRlysAmRH4iodkvo0z5.jpg', '/tOqIwliWMovSIZ9DyvHcHI7p2im.jpg', 'TQwSz88ITAE'),
    (559969, 'In the wake of his dramatic escape from captivity, Jesse Pinkman must come to terms with his past in order to forge some kind of future.', 123, '/ePXuKdXZuJx8hHMNr2yM4jY2L7Z.jpg', '/uLXK1LQM28XovWHPao3ViTeggXA.jpg', 'rklOejPnD3Y'),
    (566525, 'Shang-Chi must confront the past he thought he left behind when he is drawn into the web of the mysterious Ten Rings organization.', 132, '/9f2Q0U3IOsLgrI2HkvldwSABZy5.jpg', '/r7K6Xt0RX4Mw0cAbZVw5cyb1Tux.jpg', '8YjFbMbfXaQ'),
    (567609, 'A young bride''s wedding night turns into her worst nightmare when her ridiculously rich in-laws force her to play a gruesome game of hide-and-seek.', 96, '/oJD9KQFoObZmxAS1je56SIFVNJt.jpg', '/oJ1MIABA0WF0a7MDVQnnMvBdex8.jpg', 'LBwfO9Hj6oQ'),
    (568124, 'The tale of an extraordinary family, the Madrigals, who live hidden in the mountains of Colombia, in a magical house, in a vibrant town, in a wondrous, charmed place called an Encanto. The magic of the Encanto has blessed every child in the family—every child except one, Mirabel. But when she discovers that the magic surrounding the Encanto is in danger, Mirabel decides that she, the only ordinary Madrigal, might just be her exceptional family''s last hope.', 102, '/4j0PNHkMr5ax3IA8tjtxcmPU3QT.jpg', '/3G1Q5xF40HkUBJXxt2DQgQzKTp5.jpg', 'CaimKeDcudo'),
    (568160, 'The summer of his high school freshman year, Hodaka runs away from his remote island home to Tokyo, and quickly finds himself pushed to his financial and personal limits. The weather is unusually gloomy and rainy every day, as if taking its cue from his life. After many days of solitude, he finally finds work as a freelance writer for a mysterious occult magazine. Then, one day, Hodaka meets Hina on a busy street corner. This bright and strong-willed girl possesses a strange and wonderful ability: the power to stop the rain and clear the sky.', 112, '/qgrk7r1fV4IjuoeiGS5HOhXNdLJ.jpg', '/jFK8BOPL6ZeWyjMVWX8ajsTTinp.jpg', 'gVFDCLSSQVM'),
    (569094, 'After reuniting with Gwen Stacy, Brooklyn’s full-time, friendly neighborhood Spider-Man is catapulted across the Multiverse, where he encounters the Spider Society, a team of Spider-People charged with protecting the Multiverse''s very existence. But when the heroes clash on how to handle a new threat, Miles finds himself pitted against the other Spiders and must set out on his own to save those he loves most.', 140, '/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg', '/kVd3a9YeLGkoeR50jGEXM6EqseS.jpg', 'yFrxzaBLDQM'),
    (572802, 'Black Manta seeks revenge on Aquaman for his father''s death. Wielding the Black Trident''s power, he becomes a formidable foe. To defend Atlantis, Arthur (Aquaman) forges an alliance with his imprisoned brother. They must protect the kingdom.', 124, '/7lTnXOy0iNtBAdRP3TZvaKJ77F6.jpg', '/bckxSN9ueOgm0gJpVJmPQrecWul.jpg', '4cSkHPW-MPE'),
    (573435, 'After their late former Captain is framed, Lowrey and Burnett try to clear his name, only to end up on the run themselves.', 116, '/oGythE98MYleE6mZlGs5oBGkux1.jpg', '/3q01ACG0MWm0DekhvkPFCXyPZSu.jpg', 'uWLNl_KQCAU'),
    (574475, 'Plagued by a violent recurring nightmare, college student Stefanie heads home to track down the one person who might be able to break the cycle and save her family from the grisly demise that inevitably awaits them all.', 110, '/6WxhEvFsauuACfv8HyoVX6mZKFj.jpg', '/uIpJPDNFoeX0TVml9smPrs9KUVx.jpg', 'xitSoRbHJ50'),
    (575264, 'Ethan Hunt and his IMF team embark on their most dangerous mission yet: To track down a terrifying new weapon that threatens all of humanity before it falls into the wrong hands. With control of the future and the world''s fate at stake and dark forces from Ethan''s past closing in, a deadly race around the globe begins. Confronted by a mysterious, all-powerful enemy, Ethan must consider that nothing can matter more than his mission—not even the lives of those he cares about most.', 164, '/NNxYkU70HPurnNCSiCjYAmacwm.jpg', '/628Dep6AxEtDxjZoGP78TsOxYbK.jpg', 'HurjfO_TDlQ'),
    (577922, 'Armed with only one word - Tenet - and fighting for the survival of the entire world, the Protagonist journeys through a twilight world of international espionage on a mission that will unfold in something beyond real time.', 150, '/rrKH3VhHssGTCfPuaEQkxvEoElv.jpg', '/mQOUyqDybTqxl73hO5LujCZsM1o.jpg', 'KJP5RunZUKk'),
    (580175, 'Four stagnant high school teachers decide to test out a theory that maintaining a constant level of intoxication will improve their overall lives.', 117, '/aDcIt4NHURLKnAEu7gow51Yd00Q.jpg', '/a2pPepVPtKY7E4XEkT7W3ZxUOY5.jpg', 'xlwAgvn1e5E'),
