    (583083, 'With college decisions looming, Elle juggles her long-distance romance with Noah, changing relationship with bestie Lee and feelings for a new classmate.', 132, '/mb7wQv0adK3kjOUr9n93mANHhPJ.jpg', '/bXdCpL1A1mW2sEBiTmYYFnb10XN.jpg', 'fjVonI2oVeM'),
    (585083, 'When Van Helsing''s mysterious invention, the "Monsterfication Ray," goes haywire, Drac and his monster pals are all transformed into humans, and Johnny becomes a monster. In their new mismatched bodies, Drac and Johnny must team up and race across the globe to find a cure before it''s too late, and before they drive each other crazy.', 92, '/teCy1egGQa0y8ULJvlrDHQKnxBL.jpg', '/7QabKu8tizoqy8qCZJXljdSpP4A.jpg', '6suJohjIvfo'),
    (585511, 'Suddenly finding herself in the never-before-seen Land of Luck, the unluckiest person in the world must unite with the magical creatures there to turn her luck around.', 105, '/1HOYvwGFioUFL58UVvDRG6beEDm.jpg', '/sKvQUSyqsFq8e1ts6oo3Xp3dPH2.jpg', 'xSG5UX0EQVg'),
    (587807, 'Tom the cat and Jerry the mouse get kicked out of their home and relocate to a fancy New York hotel, where a scrappy employee named Kayla will lose her job if she can’t evict Jerry before a high-class wedding at the hotel. Her solution? Hiring Tom to get rid of the pesky mouse.', 101, '/8XZI9QZ7Pm3fVkigWJPbrXCMzjq.jpg', '/69USXLJEXcgMzlhZi7bmaCORxHn.jpg', 'kP9TfCWaQT4'),
    (588228, 'The world is stunned when a group of time travelers arrive from the year 2051 to deliver an urgent message: Thirty years in the future, mankind is losing a global war against a deadly alien species. The only hope for survival is for soldiers and civilians from the present to be transported to the future and join the fight. Among those recruited is high school teacher and family man Dan Forester. Determined to save the world for his young daughter, Dan teams up with a brilliant scientist and his estranged father in a desperate quest to rewrite the fate of the planet.', 138, '/34nDCQZwaEvsy4CFO5hkGRFDCVU.jpg', '/yizL4cEKsVvl17Wc1mGEIrQtM2F.jpg', 'RQjEbkV-9ZM'),
    (590223, 'Seven years since the Monsterpocalypse began, Joel Dawson has been living underground in order to survive. But after reconnecting over radio with his high school girlfriend Aimee, Joel decides to venture out to reunite with her, despite all the dangerous monsters that stand in his way.', 109, '/718NnyxyQuBQcGWt9sdelA1Zc3h.jpg', '/lA5fOBqTOQBQ1s9lEYYPmNXoYLi.jpg', 'DdIHtymX_Fc'),
    (591274, 'In 1978, two rival groups at Camp Nightwing must band together to solve a terrifying mystery when horrors from their towns'' history come alive.', 111, '/5dNTxhoGDTHHGqUTdxcr4H1dqlU.jpg', '/oMnJhVFr0xVfxy4HPBt1LDKoFgV.jpg', 'eR2KSY1fipo'),
    (593643, 'A young couple travels to a remote island to eat at an exclusive restaurant where the chef has prepared a lavish menu, with some shocking surprises.', 107, '/fPtUgMcLIboqlTlPrq0bQpKK8eq.jpg', '/4vSBj7BYsyuKCx96EJzGyp20WfY.jpg', 'C_uTkUGcHv4'),
    (594767, 'Billy Batson and his foster siblings, who transform into superheroes by saying "Shazam!", are forced to get back into action and fight the Daughters of Atlas, who they must stop from using a weapon that could destroy the world.', 130, '/3GrRgt6CiLIUXUtoktcv1g2iwT5.jpg', '/kQV9sV0IbastbU5FYxuYwxfMawz.jpg', 'AIc671o9yCI'),
    (597208, 'An ambitious carnival man with a talent for manipulating people with a few well-chosen words hooks up with a female psychologist who is even more dangerous than he is.', 151, '/vfn1feL0V9HNSXuLLpaxAW8O6LO.jpg', '/g0YNGpmlXsgHfhGnJz3c5uyzZ1B.jpg', 'Q81Yf46Oj3s'),
    (600354, 'A man refuses all assistance from his daughter as he ages and, as he tries to make sense of his changing circumstances, he begins to doubt his loved ones, his own mind and even the fabric of his reality.', 97, '/pr3bEQ517uMb5loLvjFQi8uLAsp.jpg', '/h3weAFgg06GqchI2xDfufBgSFTj.jpg', 'g0ox9ExOA1M'),
    (603692, 'With the price on his head ever increasing, John Wick uncovers a path to defeating The High Table. But before he can earn his freedom, Wick must face off against a new enemy with powerful alliances across the globe and forces that turn old friends into foes.', 170, '/vZloFAK7NmvMGKE7VkF5UHaz0I.jpg', '/7I6VUdPj6tQECNHdviJkUHD2u89.jpg', 'yjRHZEUamCc'),
