    (609681, 'When her duties send her to an anomalous wormhole linked to a Kree revolutionary, Carol''s powers become entangled with that of Jersey City super-fan Kamala Khan, aka Ms. Marvel, and Carol''s estranged niece, now S.A.B.E.R. astronaut Captain Monica Rambeau. Together, this unlikely trio must team up and learn to work in concert to save the universe.', 105, '/9GBhzXMFjgcZ3FdR9w3bUMMTps5.jpg', '/feSiISwgEpVzR1v3zv2n2AU4ANJ.jpg', 'uwmDH12MAA4'),
