    (615457, 'Hutch Mansell, a suburban dad, overlooked husband, nothing neighbor — a "nobody." When two thieves break into his home one night, Hutch''s unknown long-simmering rage is ignited and propels him on a brutal path that will uncover dark secrets he fought to leave behind.', 91, '/oBgWY00bEFeZ9N25wWVyuQddbAo.jpg', '/61MrK5U4w4MVL1vfwoG12zYPJ8B.jpg', 'wZti8QKBWPo'),
