    (615777, 'A tale of outsized ambition and outrageous excess, tracing the rise and fall of multiple characters in an era of unbridled decadence and depravity during Hollywood''s transition from silent films to sound films in the late 1920s.', 189, '/wjOHjWCUE0YzDiEzKv8AfqHj3ir.jpg', '/5fxTB08O7CW1hAcN2MWOKodp1h1.jpg', 'OumYv1aE1VI'),
    (616037, 'After his retirement is interrupted by Gorr the God Butcher, a galactic killer who seeks the extinction of the gods, Thor Odinson enlists the help of King Valkyrie, Korg, and ex-girlfriend Jane Foster, who now wields Mjolnir as the Mighty Thor. Together they embark upon a harrowing cosmic adventure to uncover the mystery of the God Butcher’s vengeance and stop him before it’s too late.', 119, '/pIkRyD18kl4FhoCNQuWxWu5cBLM.jpg', '/jsoz1HlxczSuTx0mDl2h0lxy36l.jpg', 'Go8nTmfrQd8'),
    (617126, 'Against the vibrant backdrop of a 1960s-inspired, retro-futuristic world, Marvel''s First Family is forced to balance their roles as heroes with the strength of their family bond, while defending Earth from a ravenous space god called Galactus and his enigmatic Herald, Silver Surfer.', 115, '/nf5qaSEvyYSNeFH0YhSs5EsBLX9.jpg', '/s94NjfKkcSczZ1FembwmQZwsuwY.jpg', 'LJa5wv93YGM'),
    (619264, 'A slab of food descends down a vertical facility. The residents above eat heartily, leaving those below starving and desperate. A rebellion is imminent.', 95, '/iXvQnzy6JCAx1PiQEKXuTY04ZHl.jpg', '/3tkDMNfM2YuIAJlvGO6rfIzAnfG.jpg', 'RlfooqeZcdY'),
    (624860, 'Plagued by strange memories, Neo''s life takes an unexpected turn when he finds himself back inside the Matrix.', 148, '/8c4a8kE7PizaGQQnditMmI1xbRp.jpg', '/eNI7PtK6DEYgZmHWP9gQNuff8pv.jpg', 'nNpvWBuTfrc'),
