    (631843, 'A group of families on a tropical holiday discover that the secluded beach where they are staying is somehow causing them to age rapidly – reducing their entire lives into a single day.', 108, '/vclShucpUmPhdAOmKgf3B3Z4POD.jpg', '/32yqxyLlWcO81UCx51Jfq9aeJdA.jpg', 'A4U2pMRV9_k'),
    (634649, 'Peter Parker is unmasked and no longer able to separate his normal life from the high-stakes of being a super-hero. When he asks for help from Doctor Strange the stakes become even more dangerous, forcing him to discover what it truly means to be Spider-Man.', 148, '/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg', '/iQFcwSGbZXMkeyKrxbPnwnRo5fl.jpg', '1mTjfMFyPi8'),
    (635302, 'Tanjiro Kamado, joined with Inosuke Hashibira, a boy raised by boars who wears a boar''s head, and Zenitsu Agatsuma, a scared boy who reveals his true power when he sleeps, boards the Infinity Train on a new mission with the Fire Hashira, Kyojuro Rengoku, to defeat a demon who has been tormenting the people and killing the demon slayers who oppose it!', 117, '/h8Rb9gBr48ODIwYUttZNYeMWeUU.jpg', '/qjGrUmKW78MCFG8PTLDBp67S27p.jpg', 'v30H0qj_b9E'),
    (637649, 'A cold and mysterious new security guard for a Los Angeles cash truck company surprises his co-workers when he unleashes precision skills during a heist. The crew is left wondering who he is and where he came from. Soon, the marksman''s ultimate motive becomes clear as he takes dramatic and irrevocable steps to settle a score.', 119, '/M7SUK85sKjaStg4TKhlAVyGlz3.jpg', '/70AV2Xx5FQYj20labp0EGdbjI6E.jpg', 'wo1kO8m2Nik'),
    (639933, 'Prince Amleth is on the verge of becoming a man when his father is brutally murdered by his uncle, who kidnaps the boy''s mother. Two decades later, Amleth is now a Viking who''s on a mission to save his mother, kill his uncle and avenge his father.', 137, '/aSSJMnHknzKjlZ6zybwD7eyJ4Po.jpg', '/fMiEp00v8gGWEceL4QeLu6H6z69.jpg', '6WrpvCmv0hk'),
