    (646380, 'Two astronomers go on a media tour to warn humankind of a planet-killing comet hurtling toward Earth. The response from a distracted world: Meh.', 138, '/th4E1yqsE8DGpAseLiUrI60Hf8V.jpg', '/nvxrQQspxmSblCYDtvDAbVFX8Jt.jpg', 'RbIxYm3mKzI'),
    (646385, 'Twenty-five years after a streak of brutal murders shocked the quiet town of Woodsboro, a new killer has donned the Ghostface mask and begins targeting a group of teenagers to resurrect secrets from the town’s deadly past.', 114, '/nD4M4Bx457ryLuKYpxFwQ2IBJ5w.jpg', '/ifUfE79O1raUwbaQRIB7XnFz5ZC.jpg', 'nRwLyKIBNU8'),
    (646389, 'After a heroic job of successfully landing his storm-damaged aircraft in a war zone, a fearless pilot finds himself between the agendas of multiple militias planning to take the plane and its passengers hostage.', 107, '/oJRsTQR47pyjSJCZYpOfbycpNBR.jpg', '/6JU2ysRVOHqav0Hs6BUv4mvvDxZ.jpg', '7-6_Ulo7mdk'),
    (649609, 'Having grown sick and tired of his centuries as Dracula''s lackey, Renfield finds a new lease on life — and maybe even redemption — when he falls for feisty, perennially angry traffic cop Rebecca Quincy.', 93, '/p6yUjhvNGQpFZilKwOKbxQ1eHlo.jpg', '/nHbsOoAESokKFaIPQGGHR0jJiAP.jpg', 'OkMep-7CXCI'),
    (653346, 'Several generations following Caesar''s reign, apes – now the dominant species – live harmoniously while humans have been reduced to living in the shadows. As a new tyrannical ape leader builds his empire, one young ape undertakes a harrowing journey that will cause him to question all he''s known about the past and to make choices that will define a future for apes and humans alike.', 145, '/gKkl37BQuKTanygYQG1pyYgLVgf.jpg', '/fqv8v6AycXKsivp1T5yKtLbGXce.jpg', 'Tg1FesR8X90'),
    (661374, 'World-famous detective Benoit Blanc heads to Greece to peel back the layers of a mystery surrounding a tech billionaire and his eclectic crew of friends.', 140, '/vDGr1YdrlfbU9wxTOdpf3zChmv9.jpg', '/y3uOfZAYwLkbvhunswBCskNMrfI.jpg', 'gj5ibYSz8C0'),
    (663712, 'Resurrected by a sinister entity, Art the Clown returns to Miles County to terrorize a teenage girl and her younger brother on Halloween night.', 138, '/qEAlwXbYk6IHA4ztoS2XFFaa7Xo.jpg', '/4QJtcL4D3abqdX6Snrk8ciRkroa.jpg', 'x5DhuDSArTI'),
    (666243, 'Escaping from poverty to become a witcher, Vesemir slays monsters for coin and glory, but when a new menace rises, he must face the demons of his past.', 83, '/3sLz2yv6vBDWqBbd8rdnNeoJ2kJ.jpg', '/orGlr1vHTgbDkGJPwuBjd8ncVjQ.jpg', 'J365hQpaWRw'),
    (667216, 'While staying at an isolated island resort, James and Em are enjoying a perfect vacation of pristine beaches, exceptional staff, and soaking up the sun. But guided by the seductive and mysterious Gabi, they venture outside the resort grounds and find themselves in a culture filled with violence, hedonism, and untold horror. A tragic accident leaves them facing a zero tolerance policy for crime: either you''ll be executed, or, if you’re rich enough to afford it, you can watch yourself die instead.', 118, '/cQKyNm0Nz6KWiDBQF9w4aZAmOfC.jpg', '/1xhcEecvRJXQ2OAVO7l9btlrN6D.jpg', 'W5mfHz-5dx8'),
    (667538, 'When a new threat capable of destroying the entire planet emerges, Optimus Prime and the Autobots must team up with a powerful faction known as the Maximals. With the fate of humanity hanging in the balance, humans Noah and Elena will do whatever it takes to help the Transformers as they engage in the ultimate battle to save Earth.', 127, '/gPbM0MK8CP8A174rmUwGsADNYKD.jpg', '/2vFuG6bWGyQUzYS9d69E5l85nIz.jpg', 'ZtuFgnxQMrA'),
    (670292, 'Amid a future war between the human race and the forces of artificial intelligence, a hardened ex-special forces agent grieving the disappearance of his wife, is recruited to hunt down and kill the Creator, the elusive architect of advanced AI who has developed a mysterious weapon with the power to end the war—and mankind itself.', 134, '/3dSivDtOuyxLDxPH4v2tcNG1fP7.jpg', '/kjQBrc00fB2RjHZB3PGR4w9ibpz.jpg', 'MAZuGdi32bk'),
    (675353, 'After settling in Green Hills, Sonic is eager to prove he has what it takes to be a true hero. His test comes when Dr. Robotnik returns, this time with a new partner, Knuckles, in search for an emerald that has the power to destroy civilizations. Sonic teams up with his own sidekick, Tails, and together they embark on a globe-trotting journey to find the emerald before it falls into the wrong hands.', 123, '/6DrHO1jr3qVrViUO6s6kFiAGM7.jpg', '/xuLA0pii2IMJW2puT7EvJtgpg0H.jpg', '47r8FXYZWNU'),
    (687163, 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', 157, '/iOb2fjXLbpJgyQXe46n1WtGCnaa.jpg', '/2I1OFQJ0L9T0dpU6FobKFWV2PxX.jpg', 'Q2UjkMU_ZWQ'),
    (693134, 'Follow the mythic journey of Paul Atreides as he unites with Chani and the Fremen while on a path of revenge against the conspirators who destroyed his family. Facing a choice between the love of his life and the fate of the known universe, Paul endeavors to prevent a terrible future only he can foresee.', 167, '/6izwz7rsy95ARzTR3poZ8H6c5pp.jpg', '/eZ239CUp1d6OryZEBPnO2n87gMG.jpg', 'U2Qp5pL3ovA'),
    (695721, '64 years before he becomes the tyrannical president of Panem, Coriolanus Snow sees a chance for a change in fortunes when he mentors Lucy Gray Baird, the female tribute from District 12.', 157, '/mBaXZ95R2OxueZhvQbcEWy2DqyO.jpg', '/bk1TitfD4YIGrM6AvljonMCtfnl.jpg', 'NxW_X4kzeus'),
    (696506, 'Unlikely hero Mickey Barnes finds himself in the extraordinary circumstance of working for an employer who demands the ultimate commitment to the job… to die, for a living.', 137, '/edKpE9B5qN3e559OuMCLZdW1iBZ.jpg', '/9PRKAdrDvAdCfg3EcApLTfzGsEt.jpg', 'tA1s65o_kYM'),
    (696806, 'After accidentally crash-landing in 2022, time-traveling fighter pilot Adam Reed teams up with his 12-year-old self on a mission to save the future.', 106, '/wFjboE0aFZNbVOF05fzrka9Fqyx.jpg', '/ewUqXnwiRLhgmGhuksOdLgh49Ch.jpg', 'IE8HIsIrq4o'),
    (697843, 'Back from the brink of death, highly skilled commando Tyler Rake takes on another dangerous mission: saving the imprisoned family of a ruthless gangster.', 122, '/7gKI9hpEMcZUQpNgKrkDzJpbnNS.jpg', '/wRxLAw4l17LqiFcPLkobriPTZAw.jpg', 'Y274jZs5s7s'),
    (701387, 'Two conspiracy obsessed young men kidnap the high-powered CEO of a major company, convinced that she is an alien intent on destroying planet Earth.', 119, '/rSdOua3wKMEaFWDcKAYWRjXQWOt.jpg', '/tN3pTxkQoP96wtaEahYuRVdUWb2.jpg', '7VBigr-JHB0'),
    (713704, 'A reunion between two estranged sisters gets cut short by the rise of flesh-possessing demons, thrusting them into a primal battle for survival as they face the most nightmarish version of family imaginable.', 96, '/5ik4ATKmNtmJU6AYD0bLm56BCVM.jpg', '/7bWxAsNPv9CXHOhZbJVlj2KxgfP.jpg', 'sI2JcVku4Gk'),
