    (718930, 'Unlucky assassin Ladybug is determined to do his job peacefully after one too many gigs gone off the rails. Fate, however, may have other plans, as Ladybug''s latest mission puts him on a collision course with lethal adversaries from around the globe—all with connected, yet conflicting, objectives—on the world''s fastest train.', 126, '/j8szC8OgrejDQjjMKSVXyaAjw3V.jpg', '/y2Ca1neKke2mGPMaHzlCNDVZqsK.jpg', 'EGeJczJvWns'),
    (725201, 'When a shadowy CIA agent uncovers damning agency secrets, he''s hunted across the globe by a sociopathic rogue operative who''s put a bounty on his head.', 128, '/8cXbitsS6dWQ5gfMTZdorpAAzEH.jpg', '/2u1YBNBlSwvBReyvI7i5z5ykQXP.jpg', 'OryyR6ad2rQ'),
    (740985, '14 years after making a film about his journey across the USA, Borat risks life and limb when he returns to the United States with his young daughter, and reveals more about the culture, the COVID-19 pandemic, and the political elections.', 96, '/3L1Ml5RWjFVfVq3rQENvgFymT0U.jpg', '/hbrXbVoE0NuA1ORoSGGYNASagrl.jpg', '0Rsa4U8mqkw'),
    (746036, 'Fresh off an almost career-ending accident, stuntman Colt Seavers has to track down a missing movie star, solve a conspiracy and try to win back the love of his life while still doing his day job.', 127, '/e7olqFmzcIX5c23kX4zSmLPJi8c.jpg', '/2rjI2uXmjitMAaXVO21r9ao7v2j.jpg', 'EySdVK0NK1Y'),
    (752623, 'Reclusive author Loretta Sage writes about exotic places in her popular adventure novels that feature a handsome cover model named Alan. While on tour promoting her new book with Alan, Loretta gets kidnapped by an eccentric billionaire who hopes she can lead him to the ancient city''s lost treasure that featured in her latest story. Alan, determined to prove he can be a hero in real life and not just on the pages of her books, sets off to rescue her.', 112, '/rnheO8cFvCYcmZsDrBoabJbKLFE.jpg', '/1Ds7xy7ILo8u2WWxdnkJth1jQVT.jpg', '5f9VcZqxFO4'),
    (753342, 'An epic that details the checkered rise and fall of French Emperor Napoleon Bonaparte and his relentless journey to power through the prism of his addictive, volatile relationship with his wife, Josephine.', 158, '/ytFOXyghxLzAM4KZyazDdEkM66q.jpg', '/33pMXav77ICRnceEBLhL8lXTywv.jpg', 'KPr42qEdhnU'),
