    (758323, 'Father Gabriele Amorth, Chief Exorcist of the Vatican, investigates a young boy''s terrifying possession and ends up uncovering a centuries-old conspiracy the Vatican has desperately tried to keep hidden.', 103, '/jFC4LS5qTAT3PinzdEzINfu1CV9.jpg', '/3oqmk6mNWPatBKcjOOJLp5WW9zN.jpg', 'YJXqvnT_rsk'),
