    (800815, 'West Point, New York, 1830. When a cadet at the burgeoning military academy is found hanged with his heart cut out, the top brass summons former New York City constable Augustus Landor to investigate. While attempting to solve this grisly mystery, the reluctant detective engages the help of one of the cadets: a strange but brilliant young fellow by the name of Edgar Allan Poe.', 128, '/9xkGlFRqrN8btTLU0KQvOfn2PHr.jpg', '/exEXLc85nYPtztn1u3KJ8wU0uJX.jpg', 'ddbL9jvg77w'),
