    (936075, 'The story of Michael Jackson, one of the most influential artists the world has ever known, and his life beyond the music. His journey from the discovery of his extraordinary talent as the lead of the Jackson Five, to the visionary artist whose creative ambition fueled a relentless pursuit to become the biggest entertainer in the world, highlighting both his life off-stage and some of the most iconic performances from his early solo career.', 128, '/dueFqKLvjftnELZaGYwY7xinfaI.jpg', '/ufSwlnECLoUbBjPrFqEQcWBzHwc.jpg', 'k-YAcjaLuSI'),
