    (939243, 'Sonic, Knuckles, and Tails reunite against a powerful new adversary, Shadow, a mysterious villain with powers unlike anything they have faced before. With their abilities outmatched in every way, Team Sonic must seek out an unlikely alliance in hopes of stopping Shadow and protecting the planet.', 110, '/d8Ryb8AunYAuycVKDp5HpdWPKgC.jpg', '/zOpe0eHsq0A2NvNyBbtT6sj53qV.jpg', 'LH1J1EbqCaI'),
    (940551, 'After a migrating duck family alights on their pond with thrilling tales of far-flung places, the Mallard family embarks on a family road trip, from New England, to New York City, to tropical Jamaica.', 83, '/ldfCF9RhR40mppkzmftxapaHeTo.jpg', '/d1ECsrOqB17DamTMPtiUTd6HdXd.jpg', 'hWbfohXIdEU'),
    (940721, 'In postwar Japan, Godzilla brings new devastation to an already scorched landscape. With no military intervention or government help in sight, the survivors must join together in the face of despair and fight back against an unrelenting horror.', 125, '/2E2WTX0TJEflAged6kzErwqX1kt.jpg', '/oHBhHoNe59VH6bUMazDtJmWOFSS.jpg', 'MSp68m8OJus'),
    (945961, 'While scavenging the deep ends of a derelict space station, a group of young space colonizers come face to face with the most terrifying life form in the universe.', 119, '/2uSWRTtCG336nuBiG8jOTEUKSy8.jpg', '/iYqSQaWDttQIQzsxg9xHyg0bttG.jpg', 'x0XDEhP4MQs'),
