    (950387, 'Four misfits find themselves struggling with ordinary problems when they are suddenly pulled through a mysterious portal into the Overworld: a bizarre, cubic wonderland that thrives on imagination. To get back home, they''ll have to master this world while embarking on a magical quest with an unexpected, expert crafter, Steve.', 101, '/yFHHfHcUgGAxziP1C3lLt0q2T4s.jpg', '/2Nti3gYAX513wvhp8IiLL6ZDyOm.jpg', 'aSh_L6bvaCQ'),
    (950396, 'Two highly trained operatives grow close from a distance after being sent to guard opposite sides of a mysterious gorge. When an evil below emerges, they must work together to survive what lies within.', 128, '/7iMBZzVZtG0oBug4TfqDb9ZxAOa.jpg', '/9nhjGaFLKtddDPtPaX5EmKqsWdH.jpg', 'rUSdnuOLebE'),
    (951491, 'Between the events of ''Saw'' and ''Saw II'', a sick and desperate John Kramer travels to Mexico for a risky and experimental medical procedure in hopes of a miracle cure for his cancer, only to discover the entire operation is a scam to defraud the most vulnerable. Armed with a newfound purpose, the infamous serial killer returns to his work, turning the tables on the con artists in his signature visceral way through devious, deranged, and ingenious traps.', 118, '/u7Lp1Hi8aBS73jv4KRMIv5aK4ax.jpg', '/uUJp5I4IbzuhdUiEx4R9OAoFpbz.jpg', 't3PzUo4P21c'),
    (967847, 'The Spengler family returns to where it all started - the iconic New York City firehouse - to team up with the original Ghostbusters, who''ve developed a top-secret research lab to take busting ghosts to the next level. But when the discovery of an ancient artifact unleashes an evil force, Ghostbusters new and old must join forces to protect their home and save the world from a second Ice Age.', 115, '/e1J2oNzSBdou01sUvriVuoYp0pJ.jpg', '/5cCfqeUH2f5Gnu7Lh9xepY9TB6x.jpg', 'X7Di42uUaF0'),
    (969681, 'Fighting crime full-time as Spider-Man in a world that doesn''t remember him—and the pressure of seeing his old friends move on without him—sparks a change in Peter Parker he may not have the power to control. But that transformation might also be the only thing that can stop a shocking new threat to the city and those he loves - a powerful villain no one can even see.', 145, '/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg', '/r08LxMJCbf1SiJIWeyH9aJmdqwC.jpg', 'P3uI5sLosKU'),
    (974576, 'After the unexpected death of the Pope, Cardinal Lawrence is tasked with managing the covert and ancient ritual of electing a new one. Sequestered in the Vatican with the Catholic Church’s most powerful leaders until the process is complete, Lawrence finds himself at the center of a conspiracy that could lead to its downfall.', 120, '/m5x8D0bZ3eKqIVWZ5y7TnZ2oTVg.jpg', '/91SnazWmEWnnH988aaz0l6NaWY9.jpg', 't915aZmyEBg'),
    (976573, 'In a city where fire, water, land and air residents live together, a fiery young woman and a go-with-the-flow guy will discover something elemental: how much they have in common.', 102, '/4Y1WNkd88JXmGfhtWR7dmDAo1T2.jpg', '/4fLZUr1e65hKPPVw0R3PmKFKxj1.jpg', 'hXzcyx9V0xw'),
    (976893, 'Hirayama is content with his life as a toilet cleaner in Tokyo. Outside of his structured routine, he cherishes music on cassette tapes, books, and taking photos of trees. Through unexpected encounters, he reflects on finding beauty in the world.', 124, '/tvUHVSTJV9ITON3oyHaWp7oaAc8.jpg', '/7WBIaphEm09Z8WFBo85kWGxYYkk.jpg', 'Iv8YO5BXCAQ'),
    (980078, 'After Christopher Robin abandons them for college, Pooh and Piglet embark on a bloody rampage as they search for a new source of food.', 84, '/y3iPrVHicDBcx2N6eamv0jbHH6H.jpg', '/jEybIB7yl3zgEdTHukaiR8b9yJp.jpg', 'dcpcwARBMJ4'),
    (985939, 'For best friends Becky and Hunter, life is all about conquering fears and pushing limits. But after they climb 2,000 feet to the top of a remote, abandoned radio tower, they find themselves stranded with no way down. Now Becky and Hunter''s expert climbing skills will be put to the ultimate test as they desperately fight to survive the elements, a lack of supplies, and vertigo-inducing heights.', 107, '/spCAxD99U1A6jsiePFoqdEcY0dG.jpg', '/hlxduUs8y9icWGMzYCDLcYHEQ2u.jpg', 'FNk7Cu4sJOs'),
