    (1007757, 'A small woodland creature and a majestic bird, two natural sworn enemies of the Valley, magically trade places and set off on an adventure of a lifetime to switch back. Their journey soon uncovers a greater threat—one that could endanger not only their species, but the entire valley they call home.', 102, '/tHhxWxge06goXU6ZQH1hj7vK8Hd.jpg', '/zMwhWailP1WY7sb6AoE6b8ugoy.jpg', 'glgmAwRDP8s'),
    (1008042, 'When a group of friends discover how to conjure spirits using an embalmed hand, they become hooked on the new thrill, until one of them goes too far and unleashes terrifying supernatural forces.', 95, '/kdPMUMJzyYAc4roD52qavX0nLIC.jpg', '/46Os8U0DEPmI0OnvKDxucl6SLVZ.jpg', 'PGo4wfCejsk'),
    (1010581, 'Noah must leave her city, boyfriend, and friends to move into William Leister''s mansion, the flashy and wealthy husband of her mother Rafaela. As a proud and independent 17 year old, Noah resists living in a mansion surrounded by luxury. However, it is there where she meets Nick, her new stepbrother, and the clash of their strong personalities becomes evident from the very beginning.', 116, '/w46Vw536HwNnEzOa7J24YH9DPRS.jpg', '/oz4U9eA6ilYf1tyiVuGmkftdLac.jpg', 'xY-qRGC6Yu0'),
    (1011985, 'Po is gearing up to become the spiritual leader of his Valley of Peace, but also needs someone to take his place as Dragon Warrior. As such, he will train a new kung fu practitioner for the spot and will encounter a villain called the Chameleon who conjures villains from the past.', 94, '/kDp1vUBnMpe8ak4rjgl3cLELqjU.jpg', '/3ffPx9jqg0yj9y1KWeagT7D20CB.jpg', 'd2OONzqh2jk'),
    (1022789, 'Teenager Riley''s mind headquarters is undergoing a sudden demolition to make room for something entirely unexpected: new Emotions! Joy, Sadness, Anger, Fear and Disgust, who’ve long been running a successful operation by all accounts, aren’t sure how to feel when Anxiety shows up. And it looks like she’s not alone.', 97, '/vpnVM9B6NMmQpWeZvzLvDESb2QY.jpg', '/p5ozvmdgsmbWe0H8Xk7Rc8SCwAB.jpg', 'u69y5Ie519M'),
    (1034541, 'Five years after surviving Art the Clown''s Halloween massacre, Sienna and Jonathan are still struggling to rebuild their shattered lives. As the holiday season approaches, they try to embrace the Christmas spirit and leave the horrors of the past behind. But just when they think they''re safe, Art returns, determined to turn their holiday cheer into a new nightmare. The festive season quickly unravels as Art unleashes his twisted brand of terror, proving that no holiday is safe.', 125, '/ju10W5gl3PPK3b7TjEmVOZap51I.jpg', '/bHfGHipZ32Oec94FDJO4mWs3aZ5.jpg', '0EDDtgWnSeY'),
