    (1054867, 'Washed-up revolutionary Bob exists in a state of stoned paranoia, surviving off-grid with his spirited, self-reliant daughter, Willa. When his evil nemesis resurfaces after 16 years and she goes missing, the former radical scrambles to find her, father and daughter both battling the consequences of his past.', 162, '/lbBWwxBht4JFP5PsuJ5onpMqugW.jpg', '/hiazLNa1UXuX35OTnMQRKOx3eTk.jpg', 'u6GVb4p7oD4'),
    (1061474, 'Superman, a journalist in Metropolis, embarks on a journey to reconcile his Kryptonian heritage with his human upbringing as Clark Kent.', 130, '/ombsmhYUqR4qqOLOxAyr5V8hbyv.jpg', '/eGX66zonvc4bXg3rM08RUxdYSDx.jpg', 'MikgqM0LXr4'),
    (1062722, 'Dr. Victor Frankenstein, a brilliant but egotistical scientist, brings a creature to life in a monstrous experiment that ultimately leads to the undoing of both the creator and his tragic creation.', 150, '/g4JtvGlQO7DByTI6frUobqvSL3R.jpg', '/hpXBJxLD2SEf8l2CspmSeiHrBKX.jpg', '9WZllcEgWrM'),
    (1064213, 'A young sex worker from Brooklyn gets her chance at a Cinderella story when she meets and impulsively marries the son of an oligarch. Once the news reaches Russia, her fairytale is threatened as his parents set out to get the marriage annulled.', 139, '/cgXk2tNYhJZLXdBDO5DidAVzQ82.jpg', '/88nIQnyDyYfEpR7s9hwbfhJuxK9.jpg', '8m6UrWMl18M'),
    (1071215, 'After a Black Friday riot ends in tragedy, a mysterious Thanksgiving-inspired killer terrorizes Plymouth, Massachusetts - the birthplace of the holiday. Picking off residents one by one, what begins as random revenge killings are soon revealed to be part of a larger, sinister holiday plan.', 106, '/f5f3TEVst1nHHyqgn7Z3tlwnBIH.jpg', '/ktHEdqmMWC1wdfPRMRCTZe2OISL.jpg', 'rc8vLvZ0fTE'),
    (1072790, 'After an amazing first date, Bea and Ben’s fiery attraction turns ice cold — until they find themselves unexpectedly reunited at a destination wedding in Australia. So they do what any two mature adults would do: pretend to be a couple.', 103, '/5qHoazZiaLe7oFBok7XlUhg96f2.jpg', '/j9eOeLlTGoHoM8BNUJVNyWmIvCi.jpg', 'biOxRfgF8Rs'),
    (1078605, 'When all but one child from the same class mysteriously vanish on the same night at exactly the same time, a community is left questioning who or what is behind their disappearance.', 128, '/cpf7vsRZ0MYRQcnLWteD5jK9ymT.jpg', '/8VyTWJrNEyV2MTWvniDVp0MpOAe.jpg', 'QKHySfXqN0I'),
    (1083381, 'A strange doorway appears in the basement of a furniture showroom.', 111, '/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg', '/QNE9Ihuas4duMHJYGQgAcuRtXz.jpg', '0HjdiohVOik'),
    (1084199, 'During a weekend getaway at a secluded lakeside estate, a group of friends finds themselves entangled in a web of secrets, deception, and advanced technology. As tensions rise and loyalties are tested, they uncover unsettling truths about themselves and the world around them.', 97, '/oCoTgC3UyWGfyQ9thE10ulWR7bn.jpg', '/sc1abgWNXc29wSBaerrjGBih06l.jpg', 'Qr_kX0D3DNA'),
    (1084242, 'After cracking the biggest case in Zootopia''s history, rookie cops Judy Hopps and Nick Wilde find themselves on the twisting trail of a great mystery when Gary De''Snake arrives and turns the animal metropolis upside down. To crack the case, Judy and Nick must go undercover to unexpected new parts of town, where their growing partnership is tested like never before.', 108, '/oJ7g2CifqpStmoYQyaLQgEU32qO.jpg', '/lgotja3xMoJZbynwHfcQcJAEMWH.jpg', 'sEgPQ7HKoBA'),
    (1084244, 'When Bonnie receives a Lilypad tablet as a gift and becomes obsessed, Buzz, Woody, Jessie and the rest of the gang''s jobs become exponentially harder when they have to go head to head with the all-new threat to playtime.', 102, '/sfQtVlIHljToOwYjhe21KPGzZWK.jpg', '/qjTqY5coNiz6sVtPng40IzltsoN.jpg', 'QftAW9TTmuQ'),
    (1087192, 'On the rugged isle of Berk, where Vikings and dragons have been bitter enemies for generations, Hiccup stands apart, defying centuries of tradition when he befriends Toothless, a feared Night Fury dragon. Their unlikely bond reveals the true nature of dragons, challenging the very foundations of Viking society.', 125, '/53dsJ3oEnBhTBVMigWJ9tkA5bzJ.jpg', '/8J6UlIFcU7eZfq9iCLbgc8Auklg.jpg', 'OWEq2Pf8qpk'),
    (1100782, 'About to embark on a new world tour, global pop sensation Skye Riley begins experiencing increasingly terrifying and inexplicable events. Overwhelmed by the escalating horrors and the pressures of fame, Skye is forced to face her dark past to regain control of her life before it spirals out of control.', 127, '/ht8Uv9QPv9y7K0RvUyJIaXOZTfd.jpg', '/iR79ciqhtaZ9BE7YFA1HpCHQgX4.jpg', 'FU_bAopCcSE'),
    (1100988, 'Twenty-eight years after the Rage virus outbreak, a heavily-defended island survives connected to the mainland by a single causeway. When one of the group leaves the island into the dark heart of the mainland, he discovers secrets, wonders, and horrors that have mutated not only the infected but other survivors as well.', 115, '/n5FygjEppOvac6yEaowi26nTyw3.jpg', '/6WqqEjiycNvDLjbEClM1zCwIbDD.jpg', 'IYGG55qwQZQ'),
    (1111873, 'A group of criminals kidnap a teenage ballet dancer, the daughter of a notorious gang leader, in order to obtain a ransom of $50 million, but they discover that she is not just an ordinary girl.', 109, '/5gKKSoD3iezjoL7YqZONjmyAiRA.jpg', '/2TPoqmatGDfBOiRxqNoL11ncCJe.jpg', 'xtAL2x58hns'),
    (1114513, 'When an American family is invited to spend the weekend at the idyllic country estate of a charming British family they befriended on vacation, what begins as a dream holiday soon warps into a snarled psychological nightmare.', 110, '/dA4N6uWOnEMgbxXwFX7qX7adzs8.jpg', '/1fL2S8LKxCVE9KoPRBXeagmBtex.jpg', 'iSIuxrjTMk0'),
    (1125510, 'After a mysterious leader imposes his law in a brutal system of vertical cells, a new arrival battles against a dubious food distribution method.', 101, '/tvIpBg12IIA5Dr9Sjn38ygS1vQp.jpg', '/3m0j3hCS8kMAaP9El6Vy5Lqnyft.jpg', 'UKFMYWNatQM'),
    (1138194, 'Two young missionaries are forced to prove their faith when they knock on the wrong door and are greeted by a diabolical Mr. Reed, becoming ensnared in his deadly game of cat-and-mouse.', 111, '/fr96XzlzsONrQrGfdLMiwtQjott.jpg', '/ag66gJCiZ06q1GSJuQlhGLi3Udx.jpg', 'jpWUOxRozZg'),
    (1184918, 'After a shipwreck, an intelligent robot called Roz is stranded on an uninhabited island. To survive the harsh environment, Roz bonds with the island''s animals and cares for an orphaned baby goose.', 102, '/wTnV3PCVW5O92JMrFvvrRcV39RU.jpg', '/1pmXyN3sKeYoUhu5VBZiDU4BX21.jpg', 'VUCNBAmse04'),
    (1198994, 'Two colleagues become stranded on a deserted island, the only survivors of a plane crash. On the island, they must overcome past grievances and work together to survive, but ultimately, it''s a battle of wills and wits to make it out alive.', 113, '/zbJWVHOtj3ljBzWgL1P8pxP03Up.jpg', '/bpp58yHuQmpt6xwggI63mVRw7po.jpg', 'cOmnmFz_Uzs'),
    (1212763, 'After her husband''s abrupt death, Alice seeks solace with his remaining family — descendants of a leading researcher on demonic possession. As her in-laws transform one by one into creatures that feed on fear, she comes to discover that the vows she took in life survive even in death.', 110, '/uRxrNXQWkHoENm3nwVOZDYSCx2F.jpg', '/o0jkkpcN81QqSl8DMLScBCXyUH9.jpg', 'RddZObTlmA8'),
    (1226578, 'FBI Agent Lee Harker is a gifted new recruit assigned to the unsolved case of an elusive serial killer. As the case takes complex turns, unearthing evidence of the occult, Harker discovers a personal connection to the merciless killer and must race against time to stop him before he claims the lives of another innocent family.', 101, '/1EwNyiiNFd863H4e8nWEzutnZD7.jpg', '/6ToGkmqn0KG0UGGGUAC1Ww0e5CM.jpg', 'FXOtkvx25gI'),
    (1226863, 'Having thwarted Bowser''s previous plot to marry Princess Peach, Mario and Luigi now face a fresh threat in Bowser Jr., who is determined to liberate his father from captivity and restore the family legacy. Alongside companions new and old, the brothers travel across the stars to stop the young heir''s crusade.', 98, '/eJGWx219ZcEMVQJhAgMiqo8tYY.jpg', '/kxQiIJ4gVcD3K6o14MJ72p5yRcE.jpg', 'En5QZmL5R1s'),
    (1233413, 'Trying to leave their troubled lives behind, twin brothers return to their hometown to start again, only to discover that an even greater evil is waiting to welcome them back.', 138, '/fWPgbnt2LSqkQ6cdQc0SZN9CpLm.jpg', '/j7KqDRzjbvIjDv7cdHz9G3ZYEQy.jpg', 'l2h2lC0vlX4'),
    (1234821, 'Five years after the events of Jurassic World Dominion, covert operations expert Zora Bennett is contracted to lead a skilled team on a top-secret mission to secure genetic material from the world''s three most massive dinosaurs. When Zora''s operation intersects with a civilian family whose boating expedition was capsized, they all find themselves stranded on an island where they come face-to-face with a sinister, shocking discovery that''s been hidden from the world for decades.', 134, '/1RICxzeoNCAO5NpcRMIgg1XT6fm.jpg', '/zNriRTr0kWwyaXPzdg1EIxf0BWk.jpg', '2ZhB-YO5Tnk'),
    (1241982, 'After receiving an unexpected call from her wayfinding ancestors, Moana journeys alongside Maui and a new crew to the far seas of Oceania and into dangerous, long-lost waters for an adventure unlike anything she''s ever faced.', 100, '/aLVkiINlIeCkcZIzb7XHzPYgO6L.jpg', '/vYqt6kb4lcF8wwqsMMaULkP9OEn.jpg', 'JdSl4RMNtGE'),
    (1242898, 'Cast out from his clan, a young Predator finds an unlikely ally in a damaged android and embarks on a treacherous journey in search of the ultimate adversary.', 107, '/pHpq9yNUIo6aDoCXEBzjSolywgz.jpg', '/82lM4GJ9uuNvNDOEpxFy77uv4Ak.jpg', 'LkBqjfg8TGM'),
    (1265609, 'On one last grueling mission during Army Ranger training, a combat engineer must lead his unit in a fight against a giant otherworldly killing machine.', 110, '/rFhKkXhk7ClU03jQ5rHIApJDwev.jpg', '/6yeVcxFR0j08vlv2OlL6zbewm4D.jpg', 'AFuE1LRxm80'),
    (1275779, 'A cybersecurity expert becomes a whistleblower after uncovering secrets about aliens, putting him on the run from a corporation. Meanwhile, a meteorologist experiencing strange phenomena joins forces with him to prove there''s life beyond our understanding.', 146, '/AnJ8IQJI23hNpYXVNaythu061Ru.jpg', '/1e0KDRYKRPHiVNj8yQKYuU2jVyQ.jpg', 'icDuEHSxE-w'),
    (1304313, 'The young daughter of a journalist disappears into the desert without a trace—eight years later, the broken family is shocked when she is returned to them, as what should be a joyful reunion turns into a living nightmare.', 133, '/1q308iixueCU4pFtSYugNOevtNx.jpg', '/xugEpZk9YQ0DIz1aFvH5HGkqpZK.jpg', '6wbMsDmJLCs'),
    (1311031, 'The Demon Slayer Corps are drawn into the Infinity Castle, where Tanjiro, Nezuko, and the Hashira face terrifying Upper Rank demons in a desperate fight as the final battle against Muzan Kibutsuji begins.', 156, '/fWVSwgjpT2D78VUh6X8UBd2rorW.jpg', '/1RgPyOhN4DRs225BGTlHJqCudII.jpg', 'EpAlHmuA2YM'),
    (1327819, 'Scientists have discovered how to ''hop'' human consciousness into lifelike robotic animals, allowing people to communicate with animals as animals. Animal lover Mabel seizes an opportunity to use the technology, uncovering mysteries within the animal world beyond anything she could have imagined.', 104, '/xjtWQ2CL1mpmMNwuU5HeS4Iuwuu.jpg', '/u53UYu5XG2hNgWGvs3xGhAVzypl.jpg', 'PypDSyIRRSs'),
    (1339713, 'After breaking the mysterious "One Wish Willow" to win his crush''s heart, a hopeless romantic finds himself getting exactly what he asked for but soon discovers that some desires come at a dark, sinister price.', 109, '/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg', '/5lTZyuBTNOfawsfPT8Q0cIg6qAF.jpg', 'gMC8kkwbIQQ'),
    (1368166, 'Trying to escape her past, Millie Calloway accepts a job as a live-in housemaid for the wealthy Nina and Andrew Winchester. But what begins as a dream job quickly unravels into something far more dangerous—a sexy, seductive game of secrets, scandal, and power.', 131, '/cWsBscZzwu5brg9YjNkGewRUvJX.jpg', '/zTnAnYIn0Iv3cn0ZHlzLhou3ybm.jpg', 'BqWH0KDqm3U'),
    (1368337, 'Odysseus, the legendary King of Ithaca, embarks on a long and perilous journey home following the Trojan War. Throughout his voyage, he is forced to confront the whims of gods, mythological monsters, and trials that stretch both his cunning and his humanity to the breaking point.', 173, '/5rhTDKUhPYvpdQIijFIs5VoWsON.jpg', '/c7btGYblBnfAaw713WvFM0Kimc7.jpg', 'AyIZ9tiiN8I'),
    (1423191, 'Medical courier Bryan unwittingly finds himself fighting for survival as one fateful, horrifying night collapses around him in chaos.', 94, '/gAgWJhUSQWCgtKR8170nMkYlBda.jpg', '/3icyRAqgakNcQn6aDVz9libFmBA.jpg', 'mNd1gb19A-c')
) AS t (tmdb_id, synopsis, runtime, poster, backdrop, trailer)
WHERE m.tmdb_id = t.tmdb_id;

